-- pay_workbench_delta_refresh_family_key(uuid,uuid,jsonb,bigint,text,text,text)
CREATE OR REPLACE FUNCTION public.pay_workbench_delta_refresh_family_key(p_session_id uuid, p_candidate_id uuid, p_payload_json jsonb DEFAULT '{}'::jsonb, p_fallback_session_version bigint DEFAULT NULL::bigint, p_fallback_projection_mode text DEFAULT NULL::text, p_fallback_projection_class text DEFAULT NULL::text, p_fallback_refresh_scope_kind text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_session_id_text text := NULLIF(BTRIM(COALESCE(
    CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    v_payload_json->>'session_id',
    v_payload_json->>'workbench_session_id',
    v_payload_json->>'source_session_id',
    v_payload_json->>'target_session_id',
    ''
  )), '');
  v_candidate_id_text text := NULLIF(BTRIM(COALESCE(
    CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    v_payload_json->>'candidate_id',
    v_payload_json#>>'{candidate,id}',
    ''
  )), '');
  v_session_version_text text := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'session_version',
    v_payload_json->>'workbench_session_version',
    v_payload_json->>'version',
    CASE WHEN p_fallback_session_version IS NULL THEN NULL ELSE p_fallback_session_version::text END,
    '0'
  )), '');
  v_session_version bigint := 0;
  v_projection_mode text := UPPER(BTRIM(COALESCE(
    NULLIF(v_payload_json->>'projection_mode', ''),
    NULLIF(v_payload_json->>'resolved_mode', ''),
    NULLIF(v_payload_json->>'mode', ''),
    NULLIF(p_fallback_projection_mode, ''),
    'DELTA'
  )));
  v_projection_class text := UPPER(BTRIM(COALESCE(
    NULLIF(v_payload_json->>'projection_class', ''),
    NULLIF(v_payload_json->>'classifier_projection_class', ''),
    NULLIF(v_payload_json#>>'{classifier_result,projection_class}', ''),
    NULLIF(p_fallback_projection_class, ''),
    'UNKNOWN'
  )));
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_timesheet_family_hash text := NULL::text;
  v_refresh_scope_kind text := NULL::text;
BEGIN
  IF v_session_version_text ~ '^-?[0-9]{1,18}$' THEN
    v_session_version := v_session_version_text::bigint;
  ELSE
    v_session_version := COALESCE(p_fallback_session_version, 0);
  END IF;

  SELECT COALESCE(jsonb_agg(sorted_ids.timesheet_id_text ORDER BY sorted_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(raw_ids.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}'
        WHEN NULLIF(BTRIM(COALESCE(v_payload_json->>'targeted_timesheet_id', v_payload_json->>'timesheet_id', '')), '') IS NOT NULL THEN jsonb_build_array(COALESCE(v_payload_json->>'targeted_timesheet_id', v_payload_json->>'timesheet_id'))
        ELSE '[]'::jsonb
      END
    ) AS raw_ids(value)
    WHERE NULLIF(BTRIM(raw_ids.value), '') ~* v_uuid_re
  ) AS sorted_ids;

  SELECT COALESCE(jsonb_agg(sorted_ids.timesheet_id_text ORDER BY sorted_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(raw_ids.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'array' THEN v_payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'linked_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}'
        ELSE '[]'::jsonb
      END
    ) AS raw_ids(value)
    WHERE NULLIF(BTRIM(raw_ids.value), '') ~* v_uuid_re
  ) AS sorted_ids;

  v_refresh_scope_kind := UPPER(BTRIM(COALESCE(
    NULLIF(v_payload_json->>'refresh_scope_kind', ''),
    NULLIF(v_payload_json->>'scope_kind', ''),
    NULLIF(v_payload_json#>>'{source_build,refresh_scope_kind}', ''),
    NULLIF(v_payload_json#>>'{preview_decisions_json,refresh_scope_kind}', ''),
    NULLIF(p_fallback_refresh_scope_kind, ''),
    CASE
      WHEN jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
        OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
      THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END
  )));

  v_timesheet_family_hash := md5(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)::text || ':' || COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)::text);

  RETURN 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || COALESCE(v_session_id_text, 'none')
    || ':version:' || COALESCE(v_session_version, 0)::text
    || ':projection_mode:' || COALESCE(NULLIF(v_projection_mode, ''), 'DELTA')
    || ':projection_class:' || COALESCE(NULLIF(v_projection_class, ''), 'UNKNOWN')
    || ':refresh_scope:' || COALESCE(NULLIF(v_refresh_scope_kind, ''), 'CANDIDATE_FULL_LIVE')
    || ':candidate:' || COALESCE(v_candidate_id_text, 'none')
    || ':timesheets:' || v_timesheet_family_hash;
END;
$function$;

-- pay_workbench_delta_shadow_compare_v1(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_delta_shadow_compare_v1(p_session_id uuid, p_candidate_id uuid, p_projection_run_id uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_options_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_options_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_options_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_reference_json jsonb := '{}'::jsonb;
  v_delta_source_rows_json jsonb := '[]'::jsonb;
  v_delta_line_work_rows_json jsonb := '[]'::jsonb;
  v_delta_preview_rows_json jsonb := '[]'::jsonb;
  v_reference_source_rows_json jsonb := '[]'::jsonb;
  v_reference_line_work_rows_json jsonb := '[]'::jsonb;
  v_reference_preview_rows_json jsonb := '[]'::jsonb;
  v_delta_source_hash text := NULL::text;
  v_delta_line_work_hash text := NULL::text;
  v_delta_preview_hash text := NULL::text;
  v_reference_source_hash text := NULL::text;
  v_reference_line_work_hash text := NULL::text;
  v_reference_preview_hash text := NULL::text;
  v_delta_row_key_hash text := NULL::text;
  v_reference_row_key_hash text := NULL::text;
  v_delta_line_key_hash text := NULL::text;
  v_reference_line_key_hash text := NULL::text;
  v_delta_economic_key_hash text := NULL::text;
  v_reference_economic_key_hash text := NULL::text;
  v_delta_draftability_hash text := NULL::text;
  v_reference_draftability_hash text := NULL::text;
  v_delta_readiness_hash text := NULL::text;
  v_reference_readiness_hash text := NULL::text;
  v_delta_selection_state_hash text := NULL::text;
  v_reference_selection_state_hash text := NULL::text;
  v_delta_policy_x_hash text := NULL::text;
  v_reference_policy_x_hash text := NULL::text;
  v_source_parity_match boolean := false;
  v_line_work_parity_match boolean := false;
  v_preview_parity_match boolean := false;
  v_row_key_parity_match boolean := false;
  v_line_key_parity_match boolean := false;
  v_economic_key_parity_match boolean := false;
  v_draftability_parity_match boolean := false;
  v_readiness_parity_match boolean := false;
  v_selection_state_parity_match boolean := false;
  v_policy_x_authority_parity_match boolean := false;
  v_fallback_required boolean := false;
  v_fallback_reason text := NULL::text;
  v_source_mismatches integer := 0;
  v_line_work_mismatches integer := 0;
  v_preview_mismatches integer := 0;
  v_delta_source_count integer := 0;
  v_delta_line_work_count integer := 0;
  v_delta_preview_count integer := 0;
  v_has_reference boolean := false;
  v_compare_status text := 'MATCH';
  v_sample_mismatches jsonb := '[]'::jsonb;
  v_shadow_compare_required boolean := false;
  v_shadow_compare_enforced boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_PROGRESS');

  v_shadow_compare_required := lower(BTRIM(COALESCE(v_options_json->>'shadow_compare_required', v_options_json->>'shadow_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_shadow_compare_enforced := lower(BTRIM(COALESCE(v_options_json->>'shadow_compare_enforced', v_options_json->>'shadow_enforced', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF p_session_id IS NULL OR p_candidate_id IS NULL OR p_projection_run_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'compare_status', 'MISMATCH',
      'fallback_required', true,
      'fallback_reason', 'SHADOW_COMPARE_INPUT_REQUIRED',
      'source_mismatches', 1,
      'line_work_mismatches', 0,
      'preview_mismatches', 0,
      'sample_mismatches', jsonb_build_array('SHADOW_COMPARE_INPUT_REQUIRED')
    );
  END IF;

  IF jsonb_typeof(v_options_json->'legacy_compare_json') = 'object' THEN
    v_reference_json := v_options_json->'legacy_compare_json';
  ELSIF to_regclass('public.banking_pay_workbench_candidate_delta_projection_runs') IS NOT NULL THEN
    SELECT COALESCE(projection_run.legacy_compare_json, '{}'::jsonb)
    INTO v_reference_json
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.id = p_projection_run_id
      AND projection_run.session_id = p_session_id
      AND projection_run.candidate_id = p_candidate_id
    LIMIT 1;

    SELECT COALESCE(projection_run.shadow_compare_required, false) OR v_shadow_compare_required,
           COALESCE(projection_run.shadow_compare_enforced, false) OR v_shadow_compare_enforced
    INTO v_shadow_compare_required,
         v_shadow_compare_enforced
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.id = p_projection_run_id
      AND projection_run.session_id = p_session_id
      AND projection_run.candidate_id = p_candidate_id
    LIMIT 1;
  END IF;

  IF jsonb_typeof(COALESCE(v_reference_json, '{}'::jsonb)) <> 'object' THEN
    v_reference_json := '{}'::jsonb;
  END IF;

  WITH source_rows AS (
    SELECT jsonb_strip_nulls(jsonb_build_object(
             'candidate_id', source_row.candidate_id::text,
             'timesheet_id', CASE WHEN source_row.timesheet_id IS NULL THEN NULL ELSE source_row.timesheet_id::text END,
             'section', source_row.section,
             'line_key', source_row.line_key,
             'source_ordinal', source_row.source_ordinal,
             'source_row_json', COALESCE(source_row.source_row_json, '{}'::jsonb) - 'projection_run_id' - 'created_at_utc' - 'updated_at_utc',
             'economic_key_json', COALESCE(source_row.economic_key_json, '{}'::jsonb),
             'contract_json', COALESCE(source_row.contract_json, '{}'::jsonb) - 'projection_run_id',
             'pay_channel_scope', source_row.pay_channel_scope,
             'refresh_scope_kind', source_row.refresh_scope_kind
           )) AS row_json
    FROM public.banking_pay_workbench_candidate_source_lines AS source_row
    WHERE source_row.session_id = p_session_id
      AND source_row.candidate_id = p_candidate_id
      AND source_row.source_build_run_id = p_projection_run_id
      AND source_row.status = 'CURRENT'
    ORDER BY source_row.source_ordinal, source_row.line_key, source_row.id
  )
  SELECT COALESCE(jsonb_agg(source_rows.row_json ORDER BY source_rows.row_json->>'line_key'), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_delta_source_rows_json,
       v_delta_source_count
  FROM source_rows;

  WITH line_rows AS (
    SELECT jsonb_strip_nulls(jsonb_build_object(
             'candidate_id', line_row.candidate_id::text,
             'timesheet_id', CASE WHEN line_row.timesheet_id IS NULL THEN NULL ELSE line_row.timesheet_id::text END,
             'line_key', line_row.line_key,
             'line_ordinal', line_row.line_ordinal,
             'status', CASE WHEN UPPER(BTRIM(COALESCE(line_row.status, ''))) IN ('MATERIALISED', 'MATERIALIZED') THEN 'MATERIALISED' ELSE UPPER(BTRIM(COALESCE(line_row.status, ''))) END,
             'work_payload_json', COALESCE(line_row.work_payload_json, '{}'::jsonb) - 'projection_run_id',
             'result_row_json', COALESCE(line_row.result_row_json, '{}'::jsonb) - 'projection_run_id'
           )) AS row_json
    FROM public.banking_pay_workbench_candidate_line_work AS line_row
    WHERE line_row.session_id = p_session_id
      AND line_row.candidate_id = p_candidate_id
      AND (
        line_row.work_payload_json->>'projection_run_id' = p_projection_run_id::text
        OR line_row.result_row_json->>'projection_run_id' = p_projection_run_id::text
      )
    ORDER BY line_row.line_ordinal, line_row.line_key, line_row.id
  )
  SELECT COALESCE(jsonb_agg(line_rows.row_json ORDER BY line_rows.row_json->>'line_key'), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_delta_line_work_rows_json,
       v_delta_line_work_count
  FROM line_rows;

  WITH preview_rows AS (
    SELECT jsonb_strip_nulls(jsonb_build_object(
             'candidate_id', preview_row.candidate_id::text,
             'timesheet_id', CASE WHEN preview_row.timesheet_id IS NULL THEN NULL ELSE preview_row.timesheet_id::text END,
             'section', preview_row.section,
             'row_key', preview_row.row_key,
             'key_type', preview_row.key_type,
             'key_value', preview_row.key_value,
             'row_json', COALESCE(preview_row.row_json, '{}'::jsonb) - 'projection_run_id' - 'materialised_at_utc' - 'created_at_utc' - 'updated_at_utc',
             'draftable', COALESCE(preview_row.row_json->>'draftable', ''),
             'is_ready_for_draft', COALESCE(preview_row.row_json->>'is_ready_for_draft', ''),
             'selection_allowed', COALESCE(preview_row.row_json->>'selection_allowed', ''),
             'readiness_state', COALESCE(preview_row.row_json->>'readiness_state', ''),
             'line_key', COALESCE(preview_row.row_json->>'line_key', ''),
             'policy_x_authority_scope', COALESCE(preview_row.row_json->>'policy_x_authority_scope', ''),
             'selected', preview_row.selected,
             'selection_state', preview_row.selection_state,
             'status', preview_row.status,
             'session_version', preview_row.session_version
           )) AS row_json
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND preview_row.candidate_id = p_candidate_id
      AND preview_row.row_json->>'projection_run_id' = p_projection_run_id::text
    ORDER BY preview_row.section, preview_row.row_ordinal, preview_row.row_key, preview_row.id
  )
  SELECT COALESCE(jsonb_agg(preview_rows.row_json ORDER BY preview_rows.row_json->>'section', preview_rows.row_json->>'row_key'), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_delta_preview_rows_json,
       v_delta_preview_count
  FROM preview_rows;

  v_delta_source_hash := md5(COALESCE(v_delta_source_rows_json, '[]'::jsonb)::text);
  v_delta_line_work_hash := md5(COALESCE(v_delta_line_work_rows_json, '[]'::jsonb)::text);
  v_delta_preview_hash := md5(COALESCE(v_delta_preview_rows_json, '[]'::jsonb)::text);

  v_reference_source_rows_json := CASE WHEN jsonb_typeof(v_reference_json->'source_rows') = 'array' THEN v_reference_json->'source_rows' ELSE '[]'::jsonb END;
  v_reference_line_work_rows_json := CASE WHEN jsonb_typeof(v_reference_json->'line_work_rows') = 'array' THEN v_reference_json->'line_work_rows' ELSE '[]'::jsonb END;
  v_reference_preview_rows_json := CASE WHEN jsonb_typeof(v_reference_json->'preview_rows') = 'array' THEN v_reference_json->'preview_rows' ELSE '[]'::jsonb END;

  v_reference_source_hash := COALESCE(NULLIF(BTRIM(COALESCE(v_reference_json->>'source_hash', '')), ''), md5(COALESCE(v_reference_source_rows_json, '[]'::jsonb)::text));
  v_reference_line_work_hash := COALESCE(NULLIF(BTRIM(COALESCE(v_reference_json->>'line_work_hash', '')), ''), md5(COALESCE(v_reference_line_work_rows_json, '[]'::jsonb)::text));
  v_reference_preview_hash := COALESCE(NULLIF(BTRIM(COALESCE(v_reference_json->>'preview_hash', '')), ''), md5(COALESCE(v_reference_preview_rows_json, '[]'::jsonb)::text));

  SELECT md5(COALESCE(jsonb_agg(delta_keys.value ORDER BY delta_keys.value), '[]'::jsonb)::text)
  INTO v_delta_row_key_hash
  FROM (
    SELECT COALESCE(delta_row.value->>'row_key', '') AS value
    FROM jsonb_array_elements(COALESCE(v_delta_preview_rows_json, '[]'::jsonb)) AS delta_row(value)
  ) AS delta_keys;

  SELECT md5(COALESCE(jsonb_agg(reference_keys.value ORDER BY reference_keys.value), '[]'::jsonb)::text)
  INTO v_reference_row_key_hash
  FROM (
    SELECT COALESCE(reference_row.value->>'row_key', '') AS value
    FROM jsonb_array_elements(COALESCE(v_reference_preview_rows_json, '[]'::jsonb)) AS reference_row(value)
  ) AS reference_keys;

  SELECT md5(COALESCE(jsonb_agg(delta_keys.value ORDER BY delta_keys.value), '[]'::jsonb)::text)
  INTO v_delta_line_key_hash
  FROM (
    SELECT COALESCE(delta_row.value->>'line_key', delta_row.value->>'row_key', '') AS value
    FROM jsonb_array_elements(COALESCE(v_delta_preview_rows_json, '[]'::jsonb)) AS delta_row(value)
  ) AS delta_keys;

  SELECT md5(COALESCE(jsonb_agg(reference_keys.value ORDER BY reference_keys.value), '[]'::jsonb)::text)
  INTO v_reference_line_key_hash
  FROM (
    SELECT COALESCE(reference_row.value->>'line_key', reference_row.value->>'row_key', '') AS value
    FROM jsonb_array_elements(COALESCE(v_reference_preview_rows_json, '[]'::jsonb)) AS reference_row(value)
  ) AS reference_keys;

  SELECT md5(COALESCE(jsonb_agg(delta_keys.value ORDER BY delta_keys.value), '[]'::jsonb)::text)
  INTO v_delta_economic_key_hash
  FROM (
    SELECT jsonb_build_object(
             'timesheet_id', delta_row.value->>'timesheet_id',
             'key_type', delta_row.value->>'key_type',
             'key_value', delta_row.value->>'key_value'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_delta_preview_rows_json, '[]'::jsonb)) AS delta_row(value)
  ) AS delta_keys;

  SELECT md5(COALESCE(jsonb_agg(reference_keys.value ORDER BY reference_keys.value), '[]'::jsonb)::text)
  INTO v_reference_economic_key_hash
  FROM (
    SELECT jsonb_build_object(
             'timesheet_id', reference_row.value->>'timesheet_id',
             'key_type', reference_row.value->>'key_type',
             'key_value', reference_row.value->>'key_value'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_reference_preview_rows_json, '[]'::jsonb)) AS reference_row(value)
  ) AS reference_keys;

  SELECT md5(COALESCE(jsonb_agg(delta_keys.value ORDER BY delta_keys.value), '[]'::jsonb)::text)
  INTO v_delta_draftability_hash
  FROM (
    SELECT jsonb_build_object(
             'row_key', delta_row.value->>'row_key',
             'draftable', delta_row.value->>'draftable',
             'is_ready_for_draft', delta_row.value->>'is_ready_for_draft'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_delta_preview_rows_json, '[]'::jsonb)) AS delta_row(value)
  ) AS delta_keys;

  SELECT md5(COALESCE(jsonb_agg(reference_keys.value ORDER BY reference_keys.value), '[]'::jsonb)::text)
  INTO v_reference_draftability_hash
  FROM (
    SELECT jsonb_build_object(
             'row_key', reference_row.value->>'row_key',
             'draftable', reference_row.value->>'draftable',
             'is_ready_for_draft', reference_row.value->>'is_ready_for_draft'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_reference_preview_rows_json, '[]'::jsonb)) AS reference_row(value)
  ) AS reference_keys;

  SELECT md5(COALESCE(jsonb_agg(delta_keys.value ORDER BY delta_keys.value), '[]'::jsonb)::text)
  INTO v_delta_readiness_hash
  FROM (
    SELECT jsonb_build_object(
             'row_key', delta_row.value->>'row_key',
             'readiness_state', delta_row.value->>'readiness_state'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_delta_preview_rows_json, '[]'::jsonb)) AS delta_row(value)
  ) AS delta_keys;

  SELECT md5(COALESCE(jsonb_agg(reference_keys.value ORDER BY reference_keys.value), '[]'::jsonb)::text)
  INTO v_reference_readiness_hash
  FROM (
    SELECT jsonb_build_object(
             'row_key', reference_row.value->>'row_key',
             'readiness_state', reference_row.value->>'readiness_state'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_reference_preview_rows_json, '[]'::jsonb)) AS reference_row(value)
  ) AS reference_keys;

  SELECT md5(COALESCE(jsonb_agg(delta_keys.value ORDER BY delta_keys.value), '[]'::jsonb)::text)
  INTO v_delta_selection_state_hash
  FROM (
    SELECT jsonb_build_object(
             'row_key', delta_row.value->>'row_key',
             'selected', delta_row.value->>'selected',
             'selection_state', delta_row.value->>'selection_state',
             'status', delta_row.value->>'status'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_delta_preview_rows_json, '[]'::jsonb)) AS delta_row(value)
  ) AS delta_keys;

  SELECT md5(COALESCE(jsonb_agg(reference_keys.value ORDER BY reference_keys.value), '[]'::jsonb)::text)
  INTO v_reference_selection_state_hash
  FROM (
    SELECT jsonb_build_object(
             'row_key', reference_row.value->>'row_key',
             'selected', reference_row.value->>'selected',
             'selection_state', reference_row.value->>'selection_state',
             'status', reference_row.value->>'status'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_reference_preview_rows_json, '[]'::jsonb)) AS reference_row(value)
  ) AS reference_keys;

  SELECT md5(COALESCE(jsonb_agg(delta_keys.value ORDER BY delta_keys.value), '[]'::jsonb)::text)
  INTO v_delta_policy_x_hash
  FROM (
    SELECT jsonb_build_object(
             'row_key', delta_row.value->>'row_key',
             'policy_x_authority_scope', delta_row.value->>'policy_x_authority_scope'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_delta_preview_rows_json, '[]'::jsonb)) AS delta_row(value)
  ) AS delta_keys;

  SELECT md5(COALESCE(jsonb_agg(reference_keys.value ORDER BY reference_keys.value), '[]'::jsonb)::text)
  INTO v_reference_policy_x_hash
  FROM (
    SELECT jsonb_build_object(
             'row_key', reference_row.value->>'row_key',
             'policy_x_authority_scope', reference_row.value->>'policy_x_authority_scope'
           ) AS value
    FROM jsonb_array_elements(COALESCE(v_reference_preview_rows_json, '[]'::jsonb)) AS reference_row(value)
  ) AS reference_keys;

  v_has_reference := jsonb_typeof(v_reference_json->'source_rows') = 'array'
                     OR jsonb_typeof(v_reference_json->'line_work_rows') = 'array'
                     OR jsonb_typeof(v_reference_json->'preview_rows') = 'array'
                     OR NULLIF(BTRIM(COALESCE(v_reference_json->>'source_hash', v_reference_json->>'line_work_hash', v_reference_json->>'preview_hash', '')), '') IS NOT NULL;

  IF v_has_reference IS NOT TRUE THEN
    v_compare_status := 'REFERENCE_UNAVAILABLE';
    v_source_mismatches := 0;
    v_line_work_mismatches := 0;
    v_preview_mismatches := 0;
    v_sample_mismatches := jsonb_build_array(jsonb_build_object(
      'kind', 'REFERENCE_UNAVAILABLE',
      'message', 'No legacy reference rows or hashes were supplied for shadow comparison.'
    ));
  ELSE
    v_source_mismatches := CASE WHEN v_delta_source_hash = v_reference_source_hash THEN 0 ELSE 1 END;
    v_line_work_mismatches := CASE WHEN v_delta_line_work_hash = v_reference_line_work_hash THEN 0 ELSE 1 END;
    v_preview_mismatches := CASE WHEN v_delta_preview_hash = v_reference_preview_hash THEN 0 ELSE 1 END;

    v_source_parity_match := v_delta_source_hash = v_reference_source_hash;
    v_line_work_parity_match := v_delta_line_work_hash = v_reference_line_work_hash;
    v_preview_parity_match := v_delta_preview_hash = v_reference_preview_hash;
    v_row_key_parity_match := v_delta_row_key_hash = v_reference_row_key_hash;
    v_line_key_parity_match := v_delta_line_key_hash = v_reference_line_key_hash;
    v_economic_key_parity_match := v_delta_economic_key_hash = v_reference_economic_key_hash;
    v_draftability_parity_match := v_delta_draftability_hash = v_reference_draftability_hash;
    v_readiness_parity_match := v_delta_readiness_hash = v_reference_readiness_hash;
    v_selection_state_parity_match := v_delta_selection_state_hash = v_reference_selection_state_hash;
    v_policy_x_authority_parity_match := v_delta_policy_x_hash = v_reference_policy_x_hash;

    IF COALESCE(v_source_mismatches, 0) + COALESCE(v_line_work_mismatches, 0) + COALESCE(v_preview_mismatches, 0) = 0
       AND COALESCE(v_row_key_parity_match, false) IS TRUE
       AND COALESCE(v_line_key_parity_match, false) IS TRUE
       AND COALESCE(v_economic_key_parity_match, false) IS TRUE
       AND COALESCE(v_draftability_parity_match, false) IS TRUE
       AND COALESCE(v_readiness_parity_match, false) IS TRUE
       AND COALESCE(v_selection_state_parity_match, false) IS TRUE
       AND COALESCE(v_policy_x_authority_parity_match, false) IS TRUE THEN
      v_compare_status := 'MATCH';
    ELSE
      v_compare_status := 'MISMATCH';
      v_sample_mismatches := jsonb_build_array(
        jsonb_build_object(
          'kind', 'HASH_COMPARE',
          'delta_source_hash', v_delta_source_hash,
          'reference_source_hash', v_reference_source_hash,
          'delta_line_work_hash', v_delta_line_work_hash,
          'reference_line_work_hash', v_reference_line_work_hash,
          'delta_preview_hash', v_delta_preview_hash,
          'reference_preview_hash', v_reference_preview_hash
        )
        || jsonb_build_object(
          'row_key_parity_match', COALESCE(v_row_key_parity_match, false),
          'line_key_parity_match', COALESCE(v_line_key_parity_match, false),
          'economic_key_parity_match', COALESCE(v_economic_key_parity_match, false),
          'draftability_parity_match', COALESCE(v_draftability_parity_match, false),
          'readiness_parity_match', COALESCE(v_readiness_parity_match, false),
          'selection_state_parity_match', COALESCE(v_selection_state_parity_match, false),
          'policy_x_authority_parity_match', COALESCE(v_policy_x_authority_parity_match, false)
        )
      );
    END IF;
  END IF;

  v_fallback_required := (v_compare_status = 'MISMATCH')
                         OR (v_compare_status = 'REFERENCE_UNAVAILABLE' AND COALESCE(v_shadow_compare_enforced, false) IS TRUE);
  v_fallback_reason := CASE
    WHEN v_compare_status = 'MATCH' THEN NULL::text
    WHEN v_compare_status = 'REFERENCE_UNAVAILABLE' AND COALESCE(v_shadow_compare_enforced, false) IS TRUE THEN 'SHADOW_REFERENCE_UNAVAILABLE'
    WHEN v_compare_status = 'REFERENCE_UNAVAILABLE' THEN NULL::text
    ELSE 'SHADOW_COMPARE_MISMATCH'
  END;

  IF to_regclass('public.banking_pay_workbench_candidate_delta_projection_runs') IS NOT NULL THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET shadow_compare_required = COALESCE(v_shadow_compare_required, false),
        shadow_compare_enforced = COALESCE(v_shadow_compare_enforced, false),
        shadow_compare_status = v_compare_status,
        legacy_compare_status = v_compare_status,
        legacy_compare_json = COALESCE(projection_run_update.legacy_compare_json, '{}'::jsonb)
          || jsonb_build_object(
            'compare_status', v_compare_status,
            'source_mismatches', COALESCE(v_source_mismatches, 0),
            'line_work_mismatches', COALESCE(v_line_work_mismatches, 0),
            'preview_mismatches', COALESCE(v_preview_mismatches, 0),
            'delta_source_hash', v_delta_source_hash,
            'delta_line_work_hash', v_delta_line_work_hash,
            'delta_preview_hash', v_delta_preview_hash,
            'compared_at_utc', v_now::text,
            'shadow_compare_required', COALESCE(v_shadow_compare_required, false),
            'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false),
            'reference_available', COALESCE(v_has_reference, false),
            'source_parity_match', COALESCE(v_source_parity_match, false),
            'line_work_parity_match', COALESCE(v_line_work_parity_match, false),
            'preview_parity_match', COALESCE(v_preview_parity_match, false),
            'row_key_parity_match', COALESCE(v_row_key_parity_match, false),
            'line_key_parity_match', COALESCE(v_line_key_parity_match, false),
            'economic_key_parity_match', COALESCE(v_economic_key_parity_match, false),
            'draftability_parity_match', COALESCE(v_draftability_parity_match, false),
            'readiness_parity_match', COALESCE(v_readiness_parity_match, false),
            'selection_state_parity_match', COALESCE(v_selection_state_parity_match, false),
            'policy_x_authority_parity_match', COALESCE(v_policy_x_authority_parity_match, false)
          ),
        fallback_required = COALESCE(v_fallback_required, false),
        fallback_reason = v_fallback_reason,
        updated_at_utc = v_now
    WHERE projection_run_update.id = p_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'compare_status', v_compare_status,
    'shadow_compare_required', COALESCE(v_shadow_compare_required, false),
    'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false),
    'reference_available', COALESCE(v_has_reference, false),
    'source_parity_match', COALESCE(v_source_parity_match, false),
    'line_work_parity_match', COALESCE(v_line_work_parity_match, false),
    'preview_parity_match', COALESCE(v_preview_parity_match, false),
    'row_key_parity_match', COALESCE(v_row_key_parity_match, false),
    'line_key_parity_match', COALESCE(v_line_key_parity_match, false),
    'economic_key_parity_match', COALESCE(v_economic_key_parity_match, false),
    'draftability_parity_match', COALESCE(v_draftability_parity_match, false),
    'readiness_parity_match', COALESCE(v_readiness_parity_match, false),
    'selection_state_parity_match', COALESCE(v_selection_state_parity_match, false),
    'policy_x_authority_parity_match', COALESCE(v_policy_x_authority_parity_match, false),
    'source_mismatches', COALESCE(v_source_mismatches, 0),
    'line_work_mismatches', COALESCE(v_line_work_mismatches, 0),
    'preview_mismatches', COALESCE(v_preview_mismatches, 0),
    'fallback_required', COALESCE(v_fallback_required, false),
    'fallback_reason', v_fallback_reason,
    'targeted_legacy_fallback_required', COALESCE(v_fallback_required, false),
    'sample_mismatches', COALESCE(v_sample_mismatches, '[]'::jsonb),
    'delta_counts', jsonb_build_object(
      'source_rows', COALESCE(v_delta_source_count, 0),
      'line_work_rows', COALESCE(v_delta_line_work_count, 0),
      'preview_rows', COALESCE(v_delta_preview_count, 0)
    )
  );
END;
$function$;

-- pay_workbench_delta_update_candidate_state_v1(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_delta_update_candidate_state_v1(p_session_id uuid, p_candidate_id uuid, p_projection_run_id uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_session_version bigint := NULL::bigint;
  v_source_change_seq bigint := 0;
  v_ready_rows integer := 0;
  v_blocked_rows integer := 0;
  v_selected_rows integer := 0;
  v_total_preview_rows integer := 0;
  v_section_counts_json jsonb := '{}'::jsonb;
  v_preview_rows_json jsonb := '[]'::jsonb;
  v_candidate_fragment_json jsonb := '{}'::jsonb;
  v_summary_json jsonb := '{}'::jsonb;
  v_payees_json jsonb := '[]'::jsonb;
  v_case_resolution_states_json jsonb := '[]'::jsonb;
  v_canonical_preview_lines_json jsonb := '[]'::jsonb;
  v_paye_candidate_json jsonb := NULL::jsonb;
  v_non_paye_payee_json jsonb := NULL::jsonb;
  v_context text := UPPER(BTRIM(COALESCE(v_payload_json->>'context', v_payload_json->>'update_context', 'DELTA_REFRESH')));
  v_candidate_state_version bigint := 0;
  v_candidate_state_rows_written integer := 0;
  v_existing_source_change_seq bigint := 0;
  v_live_source_change_seq bigint := 0;
  v_incomplete_source_row_count integer := 0;
  v_duplicate_current_source_count integer := 0;
  v_incomplete_line_work_count integer := 0;
  v_dirty_preview_row_count integer := 0;
  v_newer_active_job_count integer := 0;
  v_duplicate_finance_component_count integer := 0;
  v_finance_family_mismatch_count integer := 0;
  v_accepted_run_source_count integer := 0;
  v_accepted_run_source_change_seq_count integer := 0;
  v_accepted_run_source_change_seq bigint := NULL::bigint;
  v_readiness_guard_reason text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF v_context NOT IN ('DELTA_REFRESH', 'POST_DRAFT_PATCH', 'READINESS_PATCH', 'RESERVATION_PATCH', 'CLONE_REBASE') THEN
    v_context := 'DELTA_REFRESH';
  END IF;

  IF p_session_id IS NULL OR p_candidate_id IS NULL OR p_projection_run_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'fallback_required', true,
      'fallback_reason', 'DELTA_CANDIDATE_STATE_INPUT_REQUIRED'
    );
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
    AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
    AND session_row.discarded_at_utc IS NULL;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'fallback_required', true,
      'fallback_reason', 'SESSION_NOT_OPEN_FOR_DELTA_CANDIDATE_STATE'
    );
  END IF;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'fallback_required', true,
      'fallback_reason', 'CANDIDATE_SCOPE_NOT_FOUND_FOR_DELTA_CANDIDATE_STATE'
    );
  END IF;

  IF COALESCE(v_payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN
    v_session_version := (v_payload_json->>'session_version')::bigint;
  ELSE
    v_session_version := COALESCE(v_session_row.version, 1);
  END IF;

  IF COALESCE(v_payload_json->>'source_change_seq', v_payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$' THEN
    v_source_change_seq := COALESCE(v_payload_json->>'source_change_seq', v_payload_json->>'source_change_sequence')::bigint;
  ELSE
    v_source_change_seq := 0;
  END IF;

  /*
   * The accepted source-build run is database authority for its sequence.
   * This also covers clone/rebase calls, which historically did not repeat
   * the sequence in the caller payload.
   */
  SELECT
    COUNT(*)::integer,
    COUNT(DISTINCT accepted_source.source_change_seq)::integer,
    MAX(accepted_source.source_change_seq)
  INTO
    v_accepted_run_source_count,
    v_accepted_run_source_change_seq_count,
    v_accepted_run_source_change_seq
  FROM public.banking_pay_workbench_candidate_source_lines AS accepted_source
  WHERE accepted_source.session_id = p_session_id
    AND accepted_source.candidate_id = p_candidate_id
    AND accepted_source.session_version = v_session_version
    AND accepted_source.source_build_run_id = p_projection_run_id
    AND UPPER(BTRIM(COALESCE(accepted_source.status, ''))) = 'CURRENT';

  IF COALESCE(v_accepted_run_source_count, 0) > 0
     AND COALESCE(v_accepted_run_source_change_seq_count, 0) = 1 THEN
    v_source_change_seq := COALESCE(
      v_accepted_run_source_change_seq,
      v_source_change_seq
    );
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_source_change_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  v_live_source_change_seq := COALESCE(v_live_source_change_seq, 0);

  IF v_context = 'POST_DRAFT_PATCH' THEN
    v_source_change_seq := GREATEST(
      COALESCE(v_source_change_seq, 0),
      COALESCE(v_live_source_change_seq, 0)
    );
  END IF;

  IF COALESCE(v_source_change_seq, 0) > 0
     AND COALESCE(v_live_source_change_seq, 0) > COALESCE(v_source_change_seq, 0) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', false,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'affected_candidate_ids', jsonb_build_array(p_candidate_id::text),
      'candidate_state_version', 0,
      'candidate_state_updated', false,
      'stale_candidate_state_update_skipped', true,
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'existing_source_change_seq', COALESCE(v_live_source_change_seq, 0),
      'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
      'stale_guard', 'APP_CHANGE_COUNTER_NEWER_THAN_DELTA',
      'context', v_context,
      'projection_run_id', p_projection_run_id::text,
      'status', 'STALE_SKIPPED',
      'ready_rows', 0,
      'blocked_rows', 0,
      'selected_rows', 0,
      'total_preview_rows', 0,
      'section_counts_json', '{}'::jsonb
    );
  END IF;

  /*
   * Pre-draft READY is an adoption proof, not a label applied merely because
   * one worker phase returned successfully. Frozen post-draft patching remains
   * outside this live-truth guard.
   */
  IF v_context <> 'POST_DRAFT_PATCH' THEN
    SELECT COUNT(*)::integer
    INTO v_incomplete_source_row_count
    FROM public.banking_pay_workbench_candidate_source_lines AS source_guard
    WHERE source_guard.session_id = p_session_id
      AND source_guard.candidate_id = p_candidate_id
      AND source_guard.session_version = v_session_version
      AND COALESCE(source_guard.source_change_seq, 0) =
          COALESCE(v_source_change_seq, 0)
      AND UPPER(BTRIM(COALESCE(source_guard.status, ''))) IN (
        'DIRTY', 'PENDING', 'PROCESSING', 'RUNNING', 'QUEUED'
      );

    SELECT COUNT(*)::integer
    INTO v_duplicate_current_source_count
    FROM (
      SELECT source_guard.line_key, source_guard.timesheet_id
      FROM public.banking_pay_workbench_candidate_source_lines AS source_guard
      WHERE source_guard.session_id = p_session_id
        AND source_guard.candidate_id = p_candidate_id
        AND source_guard.session_version = v_session_version
        AND UPPER(BTRIM(COALESCE(source_guard.status, ''))) = 'CURRENT'
      GROUP BY source_guard.line_key, source_guard.timesheet_id
      HAVING COUNT(*) > 1
    ) AS duplicate_source;

    SELECT COUNT(*)::integer
    INTO v_incomplete_line_work_count
    FROM public.banking_pay_workbench_candidate_line_work AS line_guard
    WHERE line_guard.session_id = p_session_id
      AND line_guard.candidate_id = p_candidate_id
      AND (
        UPPER(BTRIM(COALESCE(line_guard.status, ''))) IN (
          'DIRTY', 'PENDING', 'PROCESSING', 'RUNNING', 'QUEUED', 'READY'
        )
        OR (
          UPPER(BTRIM(COALESCE(line_guard.status, ''))) IN (
            'MATERIALISED', 'MATERIALIZED'
          )
          AND NULLIF(BTRIM(COALESCE(line_guard.work_payload_json->>'source_build_run_id', '')), '')
                ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND (
            NULLIF(BTRIM(COALESCE(line_guard.result_row_json->>'source_build_run_id', '')), '')
              IS DISTINCT FROM
            NULLIF(BTRIM(COALESCE(line_guard.work_payload_json->>'source_build_run_id', '')), '')
            OR NULLIF(BTRIM(COALESCE(line_guard.result_row_json->>'source_change_seq', '')), '')
              IS DISTINCT FROM
            NULLIF(BTRIM(COALESCE(line_guard.work_payload_json->>'source_change_seq', '')), '')
          )
        )
      );

    SELECT COUNT(*)::integer
    INTO v_dirty_preview_row_count
    FROM public.banking_pay_workbench_preview_rows AS preview_guard
    WHERE preview_guard.session_id = p_session_id
      AND preview_guard.candidate_id = p_candidate_id
      AND preview_guard.session_version = v_session_version
      AND UPPER(BTRIM(COALESCE(preview_guard.status, ''))) IN (
        'DIRTY', 'PENDING', 'PROCESSING', 'RUNNING', 'QUEUED'
      );

    SELECT COUNT(*)::integer
    INTO v_newer_active_job_count
    FROM public.banking_pay_workbench_jobs AS job_guard
    WHERE job_guard.session_id = p_session_id
      AND job_guard.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(job_guard.status, ''))) IN (
        'QUEUED', 'PENDING', 'CLAIMED', 'RUNNING', 'PROCESSING'
      )
      AND COALESCE(
            CASE
              WHEN COALESCE(
                     job_guard.payload_json->>'source_change_seq',
                     job_guard.payload_json->>'source_change_sequence',
                     ''
                   ) ~ '^[0-9]{1,18}$'
                THEN COALESCE(
                       job_guard.payload_json->>'source_change_seq',
                       job_guard.payload_json->>'source_change_sequence'
                     )::bigint
              ELSE 0
            END,
            0
          ) > COALESCE(v_source_change_seq, 0);

    /* Finance cases are stored as one current component row per economic
       component.  The UI derives the single expandable case parent from that
       complete component family; there is deliberately no synthetic parent
       preview row.  Prove the accepted source and preview family key sets are
       identical instead of requiring a row shape that the projection does not
       create. */
    SELECT COUNT(*)::integer
    INTO v_duplicate_finance_component_count
    FROM (
      SELECT preview_component.row_key
      FROM public.banking_pay_workbench_preview_rows AS preview_component
      WHERE preview_component.session_id = p_session_id
        AND preview_component.candidate_id = p_candidate_id
        AND preview_component.session_version = v_session_version
        AND UPPER(BTRIM(COALESCE(preview_component.status, ''))) = 'READY'
        AND preview_component.row_key ~* '^finance:[0-9a-f-]{36}:'
      GROUP BY preview_component.row_key
      HAVING COUNT(*) <> 1
    ) AS duplicate_component;

    SELECT COUNT(*)::integer
    INTO v_finance_family_mismatch_count
    FROM (
      SELECT source_finance.line_key AS family_key
      FROM public.banking_pay_workbench_candidate_source_lines AS source_finance
      WHERE source_finance.session_id = p_session_id
        AND source_finance.candidate_id = p_candidate_id
        AND source_finance.session_version = v_session_version
        AND COALESCE(source_finance.source_change_seq, 0) =
            COALESCE(v_source_change_seq, 0)
        AND UPPER(BTRIM(COALESCE(source_finance.status, ''))) = 'CURRENT'
        AND source_finance.line_key ~* '^finance:[0-9a-f-]{36}:'
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_preview_rows AS preview_finance
          WHERE preview_finance.session_id = source_finance.session_id
            AND preview_finance.candidate_id = source_finance.candidate_id
            AND preview_finance.session_version = source_finance.session_version
            AND UPPER(BTRIM(COALESCE(preview_finance.status, ''))) = 'READY'
            AND preview_finance.row_key = source_finance.line_key
        )
      UNION ALL
      SELECT preview_finance.row_key AS family_key
      FROM public.banking_pay_workbench_preview_rows AS preview_finance
      WHERE preview_finance.session_id = p_session_id
        AND preview_finance.candidate_id = p_candidate_id
        AND preview_finance.session_version = v_session_version
        AND UPPER(BTRIM(COALESCE(preview_finance.status, ''))) = 'READY'
        AND preview_finance.row_key ~* '^finance:[0-9a-f-]{36}:'
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_source_lines AS source_finance
          WHERE source_finance.session_id = preview_finance.session_id
            AND source_finance.candidate_id = preview_finance.candidate_id
            AND source_finance.session_version = preview_finance.session_version
            AND COALESCE(source_finance.source_change_seq, 0) =
                COALESCE(v_source_change_seq, 0)
            AND UPPER(BTRIM(COALESCE(source_finance.status, ''))) = 'CURRENT'
            AND source_finance.line_key = preview_finance.row_key
        )
    ) AS mismatched_finance_family;

    v_readiness_guard_reason := CASE
      WHEN COALESCE(v_accepted_run_source_count, 0) > 0
           AND COALESCE(v_accepted_run_source_change_seq_count, 0) <> 1
        THEN 'ACCEPTED_SOURCE_RUN_SEQUENCE_AMBIGUOUS'
      WHEN COALESCE(v_source_change_seq, 0) IS DISTINCT FROM COALESCE(v_live_source_change_seq, 0)
        THEN 'SOURCE_CHANGE_SEQUENCE_NOT_CURRENT'
      WHEN COALESCE(v_incomplete_source_row_count, 0) > 0
        THEN 'SOURCE_FAMILY_INCOMPLETE'
      WHEN COALESCE(v_duplicate_current_source_count, 0) > 0
        THEN 'SOURCE_FAMILY_DUPLICATED'
      WHEN COALESCE(v_incomplete_line_work_count, 0) > 0
        THEN 'LINE_WORK_NOT_TERMINAL'
      WHEN COALESCE(v_dirty_preview_row_count, 0) > 0
        THEN 'PREVIEW_ROWS_NOT_CURRENT'
      WHEN COALESCE(v_newer_active_job_count, 0) > 0
        THEN 'NEWER_CANDIDATE_JOB_PENDING'
      WHEN COALESCE(v_duplicate_finance_component_count, 0) > 0
        THEN 'FINANCE_CASE_COMPONENT_DUPLICATED'
      WHEN COALESCE(v_finance_family_mismatch_count, 0) > 0
        THEN 'FINANCE_CASE_FAMILY_MISMATCH'
      ELSE NULL::text
    END;

    IF v_readiness_guard_reason IS NOT NULL THEN
      UPDATE public.banking_pay_workbench_session_candidate_state AS pending_state
      SET status = 'PENDING',
          pending_job_id = COALESCE(pending_state.pending_job_id, v_scope_row.pending_job_id),
          last_error_json = jsonb_build_object(
            'code', 'PAY_WORKBENCH_CANDIDATE_ADOPTION_INCOMPLETE',
            'reason', v_readiness_guard_reason,
            'source_change_seq', COALESCE(v_source_change_seq, 0),
            'live_source_change_seq', COALESCE(v_live_source_change_seq, 0)
          ),
          updated_at_utc = v_now
      WHERE pending_state.session_id = p_session_id
        AND pending_state.candidate_id = p_candidate_id;

      RETURN jsonb_build_object(
        'ok', true,
        'fallback_required', true,
        'fallback_reason', v_readiness_guard_reason,
        'candidate_state_updated', false,
        'candidate_state_status', 'PENDING',
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'live_source_change_seq', COALESCE(v_live_source_change_seq, 0),
        'incomplete_source_row_count', COALESCE(v_incomplete_source_row_count, 0),
        'duplicate_current_source_count', COALESCE(v_duplicate_current_source_count, 0),
        'incomplete_line_work_count', COALESCE(v_incomplete_line_work_count, 0),
        'dirty_preview_row_count', COALESCE(v_dirty_preview_row_count, 0),
        'newer_active_job_count', COALESCE(v_newer_active_job_count, 0),
        'duplicate_finance_component_count',
          COALESCE(v_duplicate_finance_component_count, 0),
        'finance_family_mismatch_count',
          COALESCE(v_finance_family_mismatch_count, 0),
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
    END IF;
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_delta_candidate_ready_rows;
  CREATE TEMP TABLE _bpay_delta_candidate_ready_rows ON COMMIT DROP AS
  SELECT
    preview_row.id,
    preview_row.section,
    preview_row.row_key,
    preview_row.row_ordinal,
    preview_row.row_json,
    preview_row.timesheet_id,
    preview_row.key_type,
    preview_row.key_value,
    preview_row.selected,
    preview_row.selection_state,
    preview_row.status,
    preview_row.session_version
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.candidate_id = p_candidate_id
    AND preview_row.session_version = v_session_version
    AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
    AND NOT (
      COALESCE(
        lower(BTRIM(COALESCE(preview_row.row_json->>'post_draft_unavailable', '')))
          IN ('true', 't', '1', 'yes', 'y', 'on'),
        false
      )
      OR (
        COALESCE(
          lower(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', '')))
            IN ('true', 't', '1', 'yes', 'y', 'on'),
          false
        )
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_operation_type', '')))
          IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
        AND lower(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_active', 'true')))
          NOT IN ('false', 'f', '0', 'no', 'n', 'off')
      )
    );

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE candidate_rows.section = 'canonical_preview_lines')::integer,
         COUNT(*) FILTER (WHERE candidate_rows.section <> 'canonical_preview_lines')::integer,
         COUNT(*) FILTER (WHERE candidate_rows.selected IS TRUE AND candidate_rows.selection_state = 'SELECTED')::integer
  INTO v_total_preview_rows,
       v_ready_rows,
       v_blocked_rows,
       v_selected_rows
  FROM pg_temp._bpay_delta_candidate_ready_rows AS candidate_rows;

  SELECT COALESCE(jsonb_object_agg(section_rows.section, section_rows.row_count ORDER BY section_rows.section), '{}'::jsonb)
  INTO v_section_counts_json
  FROM (
    SELECT candidate_rows.section,
           COUNT(*)::integer AS row_count
    FROM pg_temp._bpay_delta_candidate_ready_rows AS candidate_rows
    GROUP BY candidate_rows.section
  ) AS section_rows;

  SELECT COALESCE(jsonb_agg(
           candidate_rows.row_json
           || jsonb_build_object(
             'preview_row_id', candidate_rows.id::text,
             'row_id', candidate_rows.id::text,
             'section', candidate_rows.section,
             'row_key', candidate_rows.row_key,
             'row_ordinal', candidate_rows.row_ordinal,
             'selected', COALESCE(candidate_rows.selected, false),
             'selection_state', candidate_rows.selection_state,
             'timesheet_id', CASE WHEN candidate_rows.timesheet_id IS NULL THEN NULL ELSE candidate_rows.timesheet_id::text END,
             'key_type', candidate_rows.key_type,
             'key_value', candidate_rows.key_value
           )
           ORDER BY candidate_rows.section, candidate_rows.row_ordinal, candidate_rows.id
         ), '[]'::jsonb)
  INTO v_preview_rows_json
  FROM (
    SELECT page_rows.*
    FROM pg_temp._bpay_delta_candidate_ready_rows AS page_rows
    ORDER BY page_rows.section, page_rows.row_ordinal, page_rows.id
    LIMIT 100
  ) AS candidate_rows;

  SELECT COALESCE(jsonb_agg(candidate_rows.row_json ORDER BY candidate_rows.row_ordinal, candidate_rows.id), '[]'::jsonb)
  INTO v_canonical_preview_lines_json
  FROM (
    SELECT page_rows.*
    FROM pg_temp._bpay_delta_candidate_ready_rows AS page_rows
    WHERE page_rows.section = 'canonical_preview_lines'
    ORDER BY page_rows.row_ordinal, page_rows.id
    LIMIT 100
  ) AS candidate_rows;

  SELECT COALESCE(jsonb_agg(candidate_rows.row_json ORDER BY candidate_rows.row_ordinal, candidate_rows.id), '[]'::jsonb)
  INTO v_case_resolution_states_json
  FROM pg_temp._bpay_delta_candidate_ready_rows AS candidate_rows
  WHERE candidate_rows.section = 'cases_resolutions';

  SELECT COALESCE(jsonb_agg(DISTINCT jsonb_strip_nulls(jsonb_build_object(
           'payee_entity_kind', candidate_rows.row_json#>>'{payee_context,payee_entity_kind}',
           'payee_entity_id', candidate_rows.row_json#>>'{payee_context,payee_entity_id}',
           'payee_bank_hash', candidate_rows.row_json#>>'{payee_context,payee_bank_hash}',
           'pay_channel', candidate_rows.row_json->>'pay_channel',
           'name_check_status', candidate_rows.row_json#>>'{payee_context,name_check_status}',
           'payee_map_present', candidate_rows.row_json#>>'{payee_context,payee_map_present}'
         ))), '[]'::jsonb)
  INTO v_payees_json
  FROM pg_temp._bpay_delta_candidate_ready_rows AS candidate_rows
  WHERE candidate_rows.row_json ? 'payee_context';

  SELECT jsonb_strip_nulls(jsonb_build_object(
           'candidate_id', p_candidate_id::text,
           'session_id', p_session_id::text,
           'session_version', v_session_version,
           'scope_status', COALESCE(v_scope_row.status, 'PENDING'),
           'row_backed', true,
           'delta_projection_run_id', p_projection_run_id::text,
           'delta_updated_at_utc', v_now::text,
           'update_context', v_context
         ))
  INTO v_candidate_fragment_json;

  v_summary_json := jsonb_strip_nulls(
    jsonb_build_object(
      'candidate_id', p_candidate_id::text,
      'session_id', p_session_id::text,
      'session_version', v_session_version,
      'status', CASE WHEN COALESCE(v_total_preview_rows, 0) = 0 THEN 'READY_EMPTY' ELSE 'READY' END,
      'scope_status', COALESCE(v_scope_row.status, 'PENDING'),
      'ready_rows', COALESCE(v_ready_rows, 0),
      'blocked_rows', COALESCE(v_blocked_rows, 0),
      'selected_rows', COALESCE(v_selected_rows, 0),
      'total_preview_rows', COALESCE(v_total_preview_rows, 0),
      'section_counts_json', COALESCE(v_section_counts_json, '{}'::jsonb),
      'projection_run_id', p_projection_run_id::text,
      'updated_at_utc', v_now::text,
      'update_context', v_context
    )
  );

  SELECT candidate_rows.row_json
  INTO v_paye_candidate_json
  FROM pg_temp._bpay_delta_candidate_ready_rows AS candidate_rows
  WHERE UPPER(BTRIM(COALESCE(candidate_rows.row_json->>'pay_channel', ''))) = 'PAYE'
  ORDER BY candidate_rows.row_ordinal, candidate_rows.id
  LIMIT 1;

  SELECT candidate_rows.row_json
  INTO v_non_paye_payee_json
  FROM pg_temp._bpay_delta_candidate_ready_rows AS candidate_rows
  WHERE UPPER(BTRIM(COALESCE(candidate_rows.row_json->>'pay_channel', ''))) <> 'PAYE'
  ORDER BY candidate_rows.row_ordinal, candidate_rows.id
  LIMIT 1;

  INSERT INTO public.banking_pay_workbench_session_candidate_state AS candidate_state (
    session_id,
    candidate_id,
    status,
    effective_candidate_fragment_json,
    effective_summary_fragment_json,
    effective_paye_candidate_json,
    effective_non_paye_payee_json,
    effective_payees_json,
    effective_case_resolution_states_json,
    effective_canonical_preview_lines_json,
    source_change_seq,
    session_version,
    pending_job_id,
    created_at_utc,
    updated_at_utc,
    last_recomputed_at_utc,
    last_error_json
  )
  VALUES (
    p_session_id,
    p_candidate_id,
    'READY',
    v_candidate_fragment_json,
    v_summary_json || jsonb_build_object('preview_rows_json', COALESCE(v_preview_rows_json, '[]'::jsonb)),
    v_paye_candidate_json,
    v_non_paye_payee_json,
    COALESCE(v_payees_json, '[]'::jsonb),
    COALESCE(v_case_resolution_states_json, '[]'::jsonb),
    COALESCE(v_canonical_preview_lines_json, '[]'::jsonb),
    COALESCE(v_source_change_seq, 0),
    COALESCE(v_session_version, 1),
    NULL::uuid,
    v_now,
    v_now,
    v_now,
    NULL::jsonb
  )
  ON CONFLICT (session_id, candidate_id)
  DO UPDATE
  SET status = 'READY',
      effective_candidate_fragment_json = EXCLUDED.effective_candidate_fragment_json,
      effective_summary_fragment_json = EXCLUDED.effective_summary_fragment_json,
      effective_paye_candidate_json = EXCLUDED.effective_paye_candidate_json,
      effective_non_paye_payee_json = EXCLUDED.effective_non_paye_payee_json,
      effective_payees_json = EXCLUDED.effective_payees_json,
      effective_case_resolution_states_json = EXCLUDED.effective_case_resolution_states_json,
      effective_canonical_preview_lines_json = EXCLUDED.effective_canonical_preview_lines_json,
      source_change_seq = EXCLUDED.source_change_seq,
      session_version = EXCLUDED.session_version,
      pending_job_id = NULL::uuid,
      updated_at_utc = v_now,
      last_recomputed_at_utc = v_now,
      last_error_json = NULL::jsonb
  WHERE COALESCE(candidate_state.source_change_seq, 0) <= COALESCE(EXCLUDED.source_change_seq, 0);

  GET DIAGNOSTICS v_candidate_state_rows_written = ROW_COUNT;

  IF COALESCE(v_candidate_state_rows_written, 0) = 0 THEN
    SELECT COALESCE(candidate_state.source_change_seq, 0),
           COALESCE(EXTRACT(EPOCH FROM candidate_state.updated_at_utc)::bigint, 0)
    INTO v_existing_source_change_seq,
         v_candidate_state_version
    FROM public.banking_pay_workbench_session_candidate_state AS candidate_state
    WHERE candidate_state.session_id = p_session_id
      AND candidate_state.candidate_id = p_candidate_id
    LIMIT 1;

    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', false,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'affected_candidate_ids', jsonb_build_array(p_candidate_id::text),
      'candidate_state_version', COALESCE(v_candidate_state_version, 0),
      'candidate_state_updated', false,
      'stale_candidate_state_update_skipped', true,
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'existing_source_change_seq', COALESCE(v_existing_source_change_seq, 0),
      'context', v_context,
      'projection_run_id', p_projection_run_id::text,
      'status', 'STALE_SKIPPED',
      'ready_rows', COALESCE(v_ready_rows, 0),
      'blocked_rows', COALESCE(v_blocked_rows, 0),
      'selected_rows', COALESCE(v_selected_rows, 0),
      'total_preview_rows', COALESCE(v_total_preview_rows, 0),
      'section_counts_json', COALESCE(v_section_counts_json, '{}'::jsonb)
    );
  END IF;

  SELECT COALESCE(EXTRACT(EPOCH FROM candidate_state.updated_at_utc)::bigint, 0)
  INTO v_candidate_state_version
  FROM public.banking_pay_workbench_session_candidate_state AS candidate_state
  WHERE candidate_state.session_id = p_session_id
    AND candidate_state.candidate_id = p_candidate_id
  LIMIT 1;

  IF to_regclass('public.banking_pay_workbench_candidate_delta_projection_runs') IS NOT NULL THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET candidate_state_updated = true,
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'candidate_state_context', v_context,
            'candidate_state_updated_at_utc', v_now::text,
            'candidate_state_total_preview_rows', COALESCE(v_total_preview_rows, 0),
            'candidate_state_selected_rows', COALESCE(v_selected_rows, 0)
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = p_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'fallback_required', false,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'affected_candidate_ids', jsonb_build_array(p_candidate_id::text),
    'candidate_state_version', v_candidate_state_version,
    'candidate_state_updated', true,
    'context', v_context,
    'projection_run_id', p_projection_run_id::text,
    'status', CASE WHEN COALESCE(v_total_preview_rows, 0) = 0 THEN 'READY_EMPTY' ELSE 'READY' END,
    'ready_rows', COALESCE(v_ready_rows, 0),
    'blocked_rows', COALESCE(v_blocked_rows, 0),
    'selected_rows', COALESCE(v_selected_rows, 0),
    'total_preview_rows', COALESCE(v_total_preview_rows, 0),
    'section_counts_json', COALESCE(v_section_counts_json, '{}'::jsonb)
  );
END;
$function$;

-- pay_workbench_delta_write_compatible_rows_v1(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_delta_write_compatible_rows_v1(p_session_id uuid, p_candidate_id uuid, p_projection_run_id uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_started_at timestamptz := clock_timestamp();
  v_elapsed_ms integer := 0;
  v_budget_ms integer := 3000;
  v_budget_cutoff_ms integer := 2400;
  v_settings_json jsonb := '{}'::jsonb;
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_projection_row_count integer := 0;
  v_preview_rows_superseded integer := 0;
  v_source_rows_superseded integer := 0;
  v_line_rows_superseded integer := 0;
  v_source_rows_written integer := 0;
  v_line_rows_written integer := 0;
  v_preview_rows_written integer := 0;
  v_selected_preserved_count integer := 0;
  v_selected_cleared_count integer := 0;
  v_affected_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_cleanup_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_current_source_change_seq bigint := 0;
  v_current_session_version bigint := NULL::bigint;
  v_affected_key_count integer := 0;
  v_write_phase text := 'SUPERSEDE_PREVIEW';
  v_write_cursor_json jsonb := '{}'::jsonb;
  v_write_phase_order integer := 1;
  v_selection_guard_violation_count integer := 0;
  v_invalid_direct_preview_contract_count integer := 0;
  v_shadow_compare_required boolean := false;
  v_shadow_compare_enforced boolean := false;
  v_shadow_compare_status text := NULL::text;
  v_shadow_compare_passed boolean := false;
  v_run_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_run_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_selection_intent_mode text := '';
  v_explicit_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_reconciled_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_reconciled_selected_row_count integer := 0;
  v_sealed_targeted_delta boolean := false;
  v_sealed_event_class text := '';
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  SELECT COALESCE(to_jsonb(settings_row), '{}'::jsonb)
  INTO v_settings_json
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1
  LIMIT 1;

  IF COALESCE(v_settings_json->>'banking_pay_workbench_delta_budget_ms', '') ~ '^[0-9]{1,9}$' THEN
    v_budget_ms := LEAST(GREATEST((v_settings_json->>'banking_pay_workbench_delta_budget_ms')::integer, 500), 30000);
  ELSE
    v_budget_ms := 3000;
  END IF;
  v_budget_cutoff_ms := GREATEST(250, FLOOR(v_budget_ms * 0.80)::integer);

  SELECT COALESCE(projection_run.write_phase, 'SUPERSEDE_PREVIEW'),
         COALESCE(projection_run.write_cursor_json, '{}'::jsonb),
         COALESCE(projection_run.shadow_compare_required, false),
         COALESCE(projection_run.shadow_compare_enforced, false),
         NULLIF(UPPER(BTRIM(COALESCE(projection_run.shadow_compare_status, ''))), ''),
         COALESCE(projection_run.targeted_timesheet_ids, '[]'::jsonb),
         COALESCE(projection_run.linked_timesheet_ids, '[]'::jsonb),
         (
           projection_run.admission_seal_version = 1
           AND projection_run.admission_seal_digest IS NOT NULL
           AND projection_run.admission_sealed_at_utc IS NOT NULL
           AND UPPER(BTRIM(COALESCE(projection_run.projection_class, ''))) = 'TIMESHEET_LIFECYCLE'
         ),
         UPPER(BTRIM(COALESCE(projection_run.admission_seal_json->>'event_class','')))
  INTO v_write_phase,
       v_write_cursor_json,
       v_shadow_compare_required,
       v_shadow_compare_enforced,
       v_shadow_compare_status,
       v_run_targeted_timesheet_ids_json,
       v_run_linked_timesheet_ids_json,
       v_sealed_targeted_delta,
       v_sealed_event_class
  FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
  WHERE projection_run.id = p_projection_run_id
    AND projection_run.session_id = p_session_id
    AND projection_run.candidate_id = p_candidate_id
  LIMIT 1;

  IF COALESCE(v_sealed_targeted_delta,false) IS TRUE THEN
    UPDATE public.banking_pay_workbench_session_scope AS staged_scope
    SET certified_preview_publication_required=true,
        certified_preview_publication_parity_ok=false,
        certified_preview_publication_session_version=NULL,
        certified_preview_publication_source_change_seq=NULL,
        certified_preview_publication_source_build_run_id=NULL,
        certified_preview_publication_source_publication_id=NULL,
        certified_preview_publication_attestation_json='{}'::jsonb,
        certified_preview_publication_attested_at_utc=NULL,
        status='DELTA_REFRESH_PENDING',
        dirty=true,
        updated_at_utc=v_now
    WHERE staged_scope.session_id=p_session_id
      AND staged_scope.candidate_id=p_candidate_id;
  END IF;

  IF lower(BTRIM(COALESCE(v_payload_json->>'reset_write_phase', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    v_write_phase := 'SUPERSEDE_PREVIEW';
    v_write_cursor_json := '{}'::jsonb;
  END IF;

  v_write_phase := upper(BTRIM(COALESCE(v_write_phase, 'SUPERSEDE_PREVIEW')));
  v_write_phase := CASE v_write_phase
    WHEN 'SUPERSEDE_PREVIEW_ROWS' THEN 'SUPERSEDE_PREVIEW'
    WHEN 'SUPERSEDE_SOURCE_ROWS' THEN 'SUPERSEDE_SOURCE'
    WHEN 'SUPERSEDE_LINE_WORK_ROWS' THEN 'SUPERSEDE_LINE_WORK'
    WHEN 'UPSERT_SOURCE_ROWS' THEN 'UPSERT_SOURCE'
    WHEN 'UPSERT_LINE_WORK_ROWS' THEN 'UPSERT_LINE_WORK'
    WHEN 'UPSERT_PREVIEW_ROWS' THEN 'UPSERT_PREVIEW'
    WHEN 'SUPERSEDE_PREVIEW' THEN 'SUPERSEDE_PREVIEW'
    WHEN 'SUPERSEDE_SOURCE' THEN 'SUPERSEDE_SOURCE'
    WHEN 'SUPERSEDE_LINE_WORK' THEN 'SUPERSEDE_LINE_WORK'
    WHEN 'UPSERT_SOURCE' THEN 'UPSERT_SOURCE'
    WHEN 'UPSERT_LINE_WORK' THEN 'UPSERT_LINE_WORK'
    WHEN 'UPSERT_PREVIEW' THEN 'UPSERT_PREVIEW'
    ELSE v_write_phase
  END;
  v_shadow_compare_status := UPPER(BTRIM(COALESCE(v_shadow_compare_status, '')));
  v_shadow_compare_passed := v_shadow_compare_status IN ('MATCH', 'PASSED');
  v_write_phase_order := CASE v_write_phase
    WHEN 'SUPERSEDE_PREVIEW' THEN 1
    WHEN 'SUPERSEDE_SOURCE' THEN 2
    WHEN 'SUPERSEDE_LINE_WORK' THEN 3
    WHEN 'UPSERT_SOURCE' THEN 4
    WHEN 'UPSERT_LINE_WORK' THEN 5
    WHEN 'UPSERT_PREVIEW' THEN 6
    WHEN 'WRITE_COUNTS' THEN 7
    WHEN 'WRITE_COMPLETE' THEN 8
    ELSE 1
  END;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
  SET write_phase = COALESCE(v_write_phase, 'SUPERSEDE_PREVIEW'),
      write_cursor_json = COALESCE(v_write_cursor_json, '{}'::jsonb),
      updated_at_utc = v_now
  WHERE projection_run_update.id = p_projection_run_id
    AND projection_run_update.session_id = p_session_id
    AND projection_run_update.candidate_id = p_candidate_id;

  IF p_session_id IS NULL OR p_candidate_id IS NULL OR p_projection_run_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'fallback_required', true,
      'fallback_reason', 'DELTA_WRITE_INPUT_REQUIRED',
      'source_rows_written', 0,
      'line_rows_written', 0,
      'preview_rows_written', 0,
      'rows_superseded', 0
    );
  END IF;

  SELECT UPPER(BTRIM(COALESCE(
           session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
           ''
         ))),
         CASE
           WHEN jsonb_typeof(COALESCE(session_row.server_selected_preview_row_ids, '[]'::jsonb)) = 'array'
             THEN COALESCE(session_row.server_selected_preview_row_ids, '[]'::jsonb)
           ELSE '[]'::jsonb
         END
  INTO v_selection_intent_mode,
       v_explicit_selected_preview_row_ids
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  LIMIT 1;

  IF v_selection_intent_mode NOT IN ('IMPLICIT_ALL', 'EXPLICIT_INCLUDE') THEN
    SELECT CASE
             WHEN COALESCE(session_row.server_selected_preview_row_ids_provided, false) THEN 'EXPLICIT_INCLUDE'
             ELSE ''
           END
    INTO v_selection_intent_mode
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = p_session_id
    LIMIT 1;
  END IF;
  v_explicit_selected_preview_row_ids := COALESCE(v_explicit_selected_preview_row_ids, '[]'::jsonb);

  IF to_regclass('pg_temp._bpay_delta_projection_rows') IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'fallback_required', true,
      'fallback_reason', 'DELTA_PROJECTION_TEMP_ROWS_MISSING',
      'source_rows_written', 0,
      'line_rows_written', 0,
      'preview_rows_written', 0,
      'rows_superseded', 0
    );
  END IF;

  SELECT COALESCE(array_agg(DISTINCT parsed_timesheet_id ORDER BY parsed_timesheet_id), ARRAY[]::uuid[])
  INTO v_targeted_cleanup_timesheet_ids
  FROM (
    SELECT CASE WHEN value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN value_text::uuid ELSE NULL::uuid END AS parsed_timesheet_id
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(COALESCE(v_payload_json->'targeted_timesheet_ids', '[]'::jsonb)) = 'array' THEN COALESCE(v_payload_json->'targeted_timesheet_ids', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS parsed(value_text)
    UNION ALL
    SELECT CASE WHEN value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN value_text::uuid ELSE NULL::uuid END
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(COALESCE(v_payload_json->'linked_timesheet_ids', '[]'::jsonb)) = 'array' THEN COALESCE(v_payload_json->'linked_timesheet_ids', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS parsed(value_text)
    UNION ALL
    SELECT CASE WHEN value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN value_text::uuid ELSE NULL::uuid END
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(COALESCE(v_run_targeted_timesheet_ids_json, '[]'::jsonb)) = 'array' THEN COALESCE(v_run_targeted_timesheet_ids_json, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS parsed(value_text)
    UNION ALL
    SELECT CASE WHEN value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN value_text::uuid ELSE NULL::uuid END
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(COALESCE(v_run_linked_timesheet_ids_json, '[]'::jsonb)) = 'array' THEN COALESCE(v_run_linked_timesheet_ids_json, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS parsed(value_text)
  ) AS parsed_ids
  WHERE parsed_timesheet_id IS NOT NULL;

  SELECT COUNT(*)::integer
  INTO v_projection_row_count
  FROM pg_temp._bpay_delta_projection_rows AS projection_rows
  WHERE projection_rows.projection_run_id = p_projection_run_id
    AND projection_rows.session_id = p_session_id
    AND projection_rows.candidate_id = p_candidate_id;

  IF COALESCE(v_projection_row_count, 0) = 0 THEN
    IF COALESCE(v_sealed_targeted_delta,false) IS TRUE
       AND v_sealed_event_class <> 'UNAUTHORISE' THEN
      RETURN jsonb_build_object(
        'ok',false,'fallback_required',true,
        'fallback_reason','TARGETED_DELTA_ZERO_AUTHORISE_UNSUPPORTED',
        'source_rows_written',0,'line_rows_written',0,'preview_rows_written',0,'rows_superseded',0
      );
    END IF;
    IF COALESCE(v_sealed_targeted_delta, false) IS NOT TRUE
       AND COALESCE(array_length(v_targeted_cleanup_timesheet_ids, 1), 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line_cleanup
      SET status = 'SUPERSEDED',
          source_row_json = jsonb_strip_nulls(
            COALESCE(source_line_cleanup.source_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_projection_run_id', p_projection_run_id::text,
              'superseded_reason', 'DELTA_ZERO_ROWS_TARGETED_TIMESHEET_NON_PAYABLE',
              'superseded_at_utc', v_now::text,
              'policy_x_boundary', 'PRE_DRAFT_WORKBENCH_ONLY_NO_ECONOMIC_CHANGE'
            )
          ),
          updated_at_utc = v_now
      WHERE source_line_cleanup.session_id = p_session_id
        AND source_line_cleanup.candidate_id = p_candidate_id
        AND source_line_cleanup.timesheet_id = ANY(v_targeted_cleanup_timesheet_ids)
        AND UPPER(BTRIM(COALESCE(source_line_cleanup.status, ''))) IN ('CURRENT', 'DIRTY');
      GET DIAGNOSTICS v_source_rows_superseded = ROW_COUNT;

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_cleanup
      SET status = 'SKIPPED',
          result_row_json = jsonb_strip_nulls(
            COALESCE(line_work_cleanup.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'skipped_by_projection_run_id', p_projection_run_id::text,
              'skipped_reason', 'DELTA_ZERO_ROWS_TARGETED_TIMESHEET_NON_PAYABLE',
              'skipped_at_utc', v_now::text,
              'policy_x_boundary', 'PRE_DRAFT_WORKBENCH_ONLY_NO_ECONOMIC_CHANGE'
            )
          ),
          updated_at_utc = v_now
      WHERE line_work_cleanup.session_id = p_session_id
        AND line_work_cleanup.candidate_id = p_candidate_id
        AND line_work_cleanup.timesheet_id = ANY(v_targeted_cleanup_timesheet_ids)
        AND UPPER(BTRIM(COALESCE(line_work_cleanup.status, ''))) IN ('PENDING', 'PROCESSING', 'RUNNING', 'QUEUED', 'DIRTY', 'READY', 'MATERIALISED');
      GET DIAGNOSTICS v_line_rows_superseded = ROW_COUNT;

      UPDATE public.banking_pay_workbench_preview_rows AS preview_cleanup
      SET status = 'SUPERSEDED',
          selected = false,
          selection_state = 'SUPERSEDED',
          row_json = jsonb_strip_nulls(
            COALESCE(preview_cleanup.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'superseded_by_projection_run_id', p_projection_run_id::text,
              'superseded_reason', 'DELTA_ZERO_ROWS_TARGETED_TIMESHEET_NON_PAYABLE',
              'superseded_at_utc', v_now::text,
              'policy_x_boundary', 'PRE_DRAFT_WORKBENCH_ONLY_NO_ECONOMIC_CHANGE'
            )
          ),
          updated_at_utc = v_now
      WHERE preview_cleanup.session_id = p_session_id
        AND preview_cleanup.candidate_id = p_candidate_id
        AND preview_cleanup.timesheet_id = ANY(v_targeted_cleanup_timesheet_ids)
        AND (
          UPPER(BTRIM(COALESCE(preview_cleanup.status, ''))) IN ('READY', 'DIRTY', 'DELTA_PENDING')
          OR UPPER(BTRIM(COALESCE(preview_cleanup.selection_state, ''))) IN ('SELECTED', 'DIRTY')
          OR preview_cleanup.selected IS TRUE
        );
      GET DIAGNOSTICS v_preview_rows_superseded = ROW_COUNT;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', false,
      'source_rows_written', 0,
      'line_rows_written', 0,
      'preview_rows_written', 0,
      'rows_superseded', COALESCE(v_source_rows_superseded, 0) + COALESCE(v_line_rows_superseded, 0) + COALESCE(v_preview_rows_superseded, 0),
      'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
      'line_rows_superseded', COALESCE(v_line_rows_superseded, 0),
      'preview_rows_superseded', COALESCE(v_preview_rows_superseded, 0),
      'zero_projection_cleanup_applied', COALESCE(array_length(v_targeted_cleanup_timesheet_ids, 1), 0) > 0,
      'zero_projection_cleanup_timesheet_count', COALESCE(array_length(v_targeted_cleanup_timesheet_ids, 1), 0),
      'selected_preserved_count', 0,
      'selected_cleared_count', COALESCE(v_preview_rows_superseded, 0)
    );
  END IF;

  SELECT COUNT(*)::integer
  INTO v_invalid_direct_preview_contract_count
  FROM pg_temp._bpay_delta_projection_rows AS projection_rows
  WHERE projection_rows.projection_run_id = p_projection_run_id
    AND projection_rows.session_id = p_session_id
    AND projection_rows.candidate_id = p_candidate_id
    AND (
      jsonb_typeof(projection_rows.result_row_json->'preview_contract') IS DISTINCT FROM 'object'
      OR NOT ((projection_rows.result_row_json->'preview_contract') ? 'ok')
      OR NOT ((projection_rows.result_row_json->'preview_contract') ? 'materialisable')
      OR NOT ((projection_rows.result_row_json->'preview_contract') ? 'selection_allowed')
      OR NOT ((projection_rows.result_row_json->'preview_contract') ? 'draftable')
      OR NOT ((projection_rows.result_row_json->'preview_contract') ? 'is_ready_for_draft')
      OR NOT ((projection_rows.result_row_json->'preview_contract') ? 'is_excluded_from_allocation')
      OR (projection_rows.result_row_json->'preview_contract') ? 'preview_contract'
      OR jsonb_typeof(projection_rows.contract_json->'preview_contract') IS DISTINCT FROM 'object'
      OR projection_rows.contract_json->'preview_contract'
           IS DISTINCT FROM projection_rows.result_row_json->'preview_contract'
      OR (
        LOWER(BTRIM(COALESCE(
          projection_rows.result_row_json#>>'{preview_contract,ok}',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
      ) IS DISTINCT FROM COALESCE(projection_rows.contract_ok, false)
      OR (
        LOWER(BTRIM(COALESCE(
          projection_rows.result_row_json#>>'{preview_contract,materialisable}',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
      ) IS DISTINCT FROM COALESCE(projection_rows.materialisable, false)
    );

  IF COALESCE(v_invalid_direct_preview_contract_count, 0) > 0 THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET write_phase = 'WRITE_FALLBACK_REQUIRED',
        write_cursor_json = jsonb_build_object(
          'phase', 'WRITE_FALLBACK_REQUIRED',
          'fallback_reason', 'DELTA_DIRECT_PREVIEW_CONTRACT_INVALID'
        ),
        fallback_required = true,
        fallback_reason = 'DELTA_DIRECT_PREVIEW_CONTRACT_INVALID',
        diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'invalid_direct_preview_contract_count', COALESCE(v_invalid_direct_preview_contract_count, 0),
            'direct_preview_contract_required', true,
            'nested_preview_contract_rejected', true,
            'delta_write_contract_validation_at_utc', v_now::text
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = p_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id;

    RETURN jsonb_build_object(
      'ok', false,
      'fallback_required', true,
      'fallback_reason', 'DELTA_DIRECT_PREVIEW_CONTRACT_INVALID',
      'invalid_direct_preview_contract_count', COALESCE(v_invalid_direct_preview_contract_count, 0),
      'source_rows_written', 0,
      'line_rows_written', 0,
      'preview_rows_written', 0,
      'rows_superseded', 0
    );
  END IF;

  SELECT COALESCE(array_agg(DISTINCT projection_rows.timesheet_id ORDER BY projection_rows.timesheet_id), ARRAY[]::uuid[])
  INTO v_affected_timesheet_ids
  FROM pg_temp._bpay_delta_projection_rows AS projection_rows
  WHERE projection_rows.projection_run_id = p_projection_run_id
    AND projection_rows.session_id = p_session_id
    AND projection_rows.candidate_id = p_candidate_id
    AND projection_rows.timesheet_id IS NOT NULL;

  SELECT COALESCE(MAX(projection_rows.source_change_seq), 0)::bigint,
         COALESCE(MAX(projection_rows.session_version), NULL)::bigint
  INTO v_current_source_change_seq,
       v_current_session_version
  FROM pg_temp._bpay_delta_projection_rows AS projection_rows
  WHERE projection_rows.projection_run_id = p_projection_run_id
    AND projection_rows.session_id = p_session_id
    AND projection_rows.candidate_id = p_candidate_id;

  SELECT COALESCE(array_agg(DISTINCT affected_scope.timesheet_id ORDER BY affected_scope.timesheet_id), ARRAY[]::uuid[])
  INTO v_affected_timesheet_ids
  FROM (
    SELECT unnest(COALESCE(v_affected_timesheet_ids, ARRAY[]::uuid[])) AS timesheet_id
    UNION ALL
    SELECT unnest(COALESCE(v_targeted_cleanup_timesheet_ids, ARRAY[]::uuid[])) AS timesheet_id
  ) AS affected_scope
  WHERE affected_scope.timesheet_id IS NOT NULL;

  SELECT COUNT(*)::integer
  INTO v_affected_key_count
  FROM (
    SELECT DISTINCT projection_rows.timesheet_id, projection_rows.key_type, projection_rows.key_value
    FROM pg_temp._bpay_delta_projection_rows AS projection_rows
    WHERE projection_rows.projection_run_id = p_projection_run_id
      AND projection_rows.session_id = p_session_id
      AND projection_rows.candidate_id = p_candidate_id
      AND projection_rows.timesheet_id IS NOT NULL
      AND projection_rows.key_type IS NOT NULL
      AND projection_rows.key_value IS NOT NULL
  ) AS affected_keys;

  DROP TABLE IF EXISTS pg_temp._bpay_delta_existing_preview_rows;
  CREATE TEMP TABLE _bpay_delta_existing_preview_rows ON COMMIT DROP AS
  SELECT preview_row.*
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.candidate_id = p_candidate_id
    AND (v_current_session_version IS NULL OR preview_row.session_version IS NOT DISTINCT FROM v_current_session_version)
    AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
    AND (
      preview_row.timesheet_id = ANY(COALESCE(v_affected_timesheet_ids, ARRAY[]::uuid[]))
      OR EXISTS (
        SELECT 1
        FROM pg_temp._bpay_delta_projection_rows AS projection_rows
        WHERE projection_rows.projection_run_id = p_projection_run_id
          AND projection_rows.session_id = p_session_id
          AND projection_rows.candidate_id = p_candidate_id
          AND projection_rows.timesheet_id IS NOT DISTINCT FROM preview_row.timesheet_id
          AND projection_rows.key_type IS NOT DISTINCT FROM preview_row.key_type
          AND projection_rows.key_value IS NOT DISTINCT FROM preview_row.key_value
      )
    );

  IF v_write_phase_order <= 1 THEN
  IF COALESCE(v_sealed_targeted_delta, false) IS NOT TRUE THEN
  UPDATE public.banking_pay_workbench_preview_rows AS preview_update
  SET status = 'SUPERSEDED',
      selected = false,
      selection_state = 'SUPERSEDED',
      row_json = jsonb_strip_nulls(
        COALESCE(preview_update.row_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_by_projection_run_id', p_projection_run_id::text,
          'superseded_by_source_change_seq', NULLIF(v_current_source_change_seq, 0),
          'superseded_by_session_version', v_current_session_version,
          'superseded_reason', 'DELTA_REPROJECTED_AFFECTED_SCOPE',
          'superseded_at_utc', v_now::text,
          'policy_x_boundary', 'PRE_DRAFT_WORKBENCH_ONLY_NO_ECONOMIC_CHANGE'
        )
      ),
      updated_at_utc = v_now
  WHERE preview_update.session_id = p_session_id
    AND preview_update.candidate_id = p_candidate_id
    AND (v_current_session_version IS NULL OR preview_update.session_version IS NOT DISTINCT FROM v_current_session_version)
    AND UPPER(BTRIM(COALESCE(preview_update.status, ''))) IN ('READY', 'DIRTY', 'DELTA_PENDING')
    AND (
      preview_update.timesheet_id = ANY(COALESCE(v_affected_timesheet_ids, ARRAY[]::uuid[]))
      OR EXISTS (
        SELECT 1
        FROM pg_temp._bpay_delta_projection_rows AS projection_rows
        WHERE projection_rows.projection_run_id = p_projection_run_id
          AND projection_rows.session_id = p_session_id
          AND projection_rows.candidate_id = p_candidate_id
          AND projection_rows.timesheet_id IS NOT DISTINCT FROM preview_update.timesheet_id
          AND projection_rows.key_type IS NOT DISTINCT FROM preview_update.key_type
          AND projection_rows.key_value IS NOT DISTINCT FROM preview_update.key_value
      )
    )
    AND COALESCE(preview_update.row_json->>'projection_run_id', '') IS DISTINCT FROM p_projection_run_id::text
    AND NOT EXISTS (
      SELECT 1
      FROM pg_temp._bpay_delta_projection_rows AS projection_rows
      WHERE projection_rows.projection_run_id = p_projection_run_id
        AND projection_rows.session_id = preview_update.session_id
        AND projection_rows.candidate_id = preview_update.candidate_id
        AND projection_rows.section = preview_update.section
        AND projection_rows.row_key = preview_update.row_key
    );

  GET DIAGNOSTICS v_preview_rows_superseded = ROW_COUNT;
  END IF;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
  SET write_phase = 'SUPERSEDE_SOURCE',
      write_cursor_json = jsonb_build_object('phase', 'SUPERSEDE_SOURCE', 'preview_rows_superseded', COALESCE(v_preview_rows_superseded, 0)),
      updated_at_utc = v_now
  WHERE projection_run_update.id = p_projection_run_id
    AND projection_run_update.session_id = p_session_id
    AND projection_run_update.candidate_id = p_candidate_id;

  v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
  IF v_elapsed_ms >= v_budget_cutoff_ms THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'write_budget_checkpoint_elapsed_ms', v_elapsed_ms,
            'write_budget_checkpoint_at_utc', v_now::text,
            'write_budget_checkpoint_phase', COALESCE(v_write_phase, 'UNKNOWN')
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = p_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id;
  END IF;

  END IF;

  IF v_write_phase_order <= 2 THEN
  IF COALESCE(v_sealed_targeted_delta, false) IS NOT TRUE THEN
  UPDATE public.banking_pay_workbench_candidate_source_lines AS source_update
  SET status = 'SUPERSEDED',
      source_row_json = jsonb_strip_nulls(
        COALESCE(source_update.source_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_by_projection_run_id', p_projection_run_id::text,
          'superseded_by_source_change_seq', NULLIF(v_current_source_change_seq, 0),
          'superseded_by_session_version', v_current_session_version,
          'superseded_reason', 'DELTA_REPROJECTED_AFFECTED_SCOPE',
          'superseded_at_utc', v_now::text,
          'policy_x_boundary', 'PRE_DRAFT_WORKBENCH_ONLY_NO_ECONOMIC_CHANGE'
        )
      ),
      updated_at_utc = v_now
  WHERE source_update.session_id = p_session_id
    AND source_update.candidate_id = p_candidate_id
    AND (v_current_session_version IS NULL OR source_update.session_version IS NOT DISTINCT FROM v_current_session_version)
    AND UPPER(BTRIM(COALESCE(source_update.status, ''))) IN ('CURRENT', 'DIRTY')
    AND source_update.timesheet_id = ANY(COALESCE(v_affected_timesheet_ids, ARRAY[]::uuid[]))
    AND COALESCE(source_update.source_change_seq, 0) <= COALESCE(NULLIF(v_current_source_change_seq, 0), COALESCE(source_update.source_change_seq, 0))
    AND source_update.source_build_run_id IS DISTINCT FROM p_projection_run_id;

  GET DIAGNOSTICS v_source_rows_superseded = ROW_COUNT;
  END IF;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
  SET write_phase = 'SUPERSEDE_LINE_WORK',
      write_cursor_json = jsonb_build_object('phase', 'SUPERSEDE_LINE_WORK'),
      updated_at_utc = v_now
  WHERE projection_run_update.id = p_projection_run_id
    AND projection_run_update.session_id = p_session_id
    AND projection_run_update.candidate_id = p_candidate_id;

  v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
  IF v_elapsed_ms >= v_budget_cutoff_ms THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'write_budget_checkpoint_elapsed_ms', v_elapsed_ms,
            'write_budget_checkpoint_at_utc', v_now::text,
            'write_budget_checkpoint_phase', COALESCE(v_write_phase, 'UNKNOWN')
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = p_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id;
  END IF;

  END IF;

  IF v_write_phase_order <= 3 THEN
  IF COALESCE(v_sealed_targeted_delta, false) IS NOT TRUE THEN
  UPDATE public.banking_pay_workbench_candidate_line_work AS line_update
  SET status = 'SKIPPED',
      result_row_json = jsonb_strip_nulls(
        COALESCE(line_update.result_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_by_projection_run_id', p_projection_run_id::text,
          'superseded_reason', 'DELTA_REPROJECTED_AFFECTED_SCOPE',
          'superseded_at_utc', v_now::text
        )
      ),
      updated_at_utc = v_now
  WHERE line_update.session_id = p_session_id
    AND line_update.candidate_id = p_candidate_id
    AND line_update.timesheet_id = ANY(COALESCE(v_affected_timesheet_ids, ARRAY[]::uuid[]))
    AND NOT EXISTS (
      SELECT 1
      FROM pg_temp._bpay_delta_projection_rows AS projection_rows
      WHERE projection_rows.projection_run_id = p_projection_run_id
        AND projection_rows.session_id = line_update.session_id
        AND projection_rows.candidate_id = line_update.candidate_id
        AND projection_rows.timesheet_id IS NOT DISTINCT FROM line_update.timesheet_id
        AND projection_rows.line_key = line_update.line_key
    )
    AND COALESCE(line_update.work_payload_json->>'projection_run_id', line_update.result_row_json->>'projection_run_id', '') IS DISTINCT FROM p_projection_run_id::text
    AND UPPER(BTRIM(COALESCE(line_update.status, ''))) NOT IN ('SKIPPED');

  GET DIAGNOSTICS v_line_rows_superseded = ROW_COUNT;
  END IF;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
  SET write_phase = 'UPSERT_SOURCE',
      write_cursor_json = jsonb_build_object('phase', 'UPSERT_SOURCE'),
      updated_at_utc = v_now
  WHERE projection_run_update.id = p_projection_run_id
    AND projection_run_update.session_id = p_session_id
    AND projection_run_update.candidate_id = p_candidate_id;

  v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
  IF v_elapsed_ms >= v_budget_cutoff_ms THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'write_budget_checkpoint_elapsed_ms', v_elapsed_ms,
            'write_budget_checkpoint_at_utc', v_now::text,
            'write_budget_checkpoint_phase', COALESCE(v_write_phase, 'UNKNOWN')
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = p_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id;
  END IF;

  END IF;

  IF v_write_phase_order <= 4 THEN
  WITH upserted_source_rows AS (
    INSERT INTO public.banking_pay_workbench_candidate_source_lines (
      session_id,
      candidate_id,
      session_version,
      source_change_seq,
      source_build_run_id,
      source_publication_id,
      source_ordinal,
      line_key,
      parent_line_key,
      split_suffix,
      timesheet_id,
      section,
      source_row_json,
      economic_key_json,
      contract_json,
      pay_channel_scope,
      refresh_scope_kind,
      status,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      projection_rows.session_id,
      projection_rows.candidate_id,
      projection_rows.session_version,
      COALESCE(projection_rows.source_change_seq, 0),
      p_projection_run_id,
      CASE WHEN COALESCE((SELECT setting.banking_pay_source_publication_identity_write_v1_enabled
                           FROM public.settings_defaults AS setting WHERE setting.id=1),false)
        THEN private.pay_workbench_source_publication_identity_v1(
          projection_rows.session_id,projection_rows.candidate_id,
          projection_rows.session_version,COALESCE(projection_rows.source_change_seq,0),
          p_projection_run_id
        ) ELSE NULL::uuid END,
      projection_rows.source_ordinal,
      projection_rows.line_key,
      projection_rows.parent_line_key,
      projection_rows.split_suffix,
      projection_rows.timesheet_id,
      projection_rows.section,
      jsonb_strip_nulls(
        COALESCE(projection_rows.source_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'source_function', 'pay_workbench_project_changed_timesheets_v1',
          'source_kind', 'VALID_PREVIEW_LINE',
          'projection_path', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'projection_run_id', p_projection_run_id::text,
          'source_ordinal', projection_rows.source_ordinal,
          'line_ordinal', projection_rows.source_ordinal,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      ),
      projection_rows.economic_key_json,
      projection_rows.contract_json,
      COALESCE(NULLIF(BTRIM(projection_rows.pay_channel_scope), ''), 'ALL'),
      COALESCE(NULLIF(BTRIM(projection_rows.refresh_scope_kind), ''), 'TARGETED_TIMESHEETS'),
      CASE WHEN COALESCE(v_sealed_targeted_delta, false) IS TRUE THEN 'DIRTY' ELSE 'CURRENT' END,
      v_now,
      v_now
    FROM pg_temp._bpay_delta_projection_rows AS projection_rows
    WHERE projection_rows.projection_run_id = p_projection_run_id
      AND projection_rows.session_id = p_session_id
      AND projection_rows.candidate_id = p_candidate_id
      AND LOWER(BTRIM(COALESCE(
        projection_rows.preview_row_json->>'live_pay_eligibility_proven',
        projection_rows.preview_row_json#>>'{live_pay_eligibility,proven}',
        projection_rows.source_row_json->>'live_pay_eligibility_proven',
        projection_rows.source_row_json#>>'{live_pay_eligibility,proven}',
        projection_rows.contract_json->>'live_pay_eligibility_proven',
        projection_rows.contract_json#>>'{live_pay_eligibility,proven}',
        'false'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    ON CONFLICT (
      session_id,
      candidate_id,
      session_version,
      source_change_seq,
      source_build_run_id,
      (COALESCE(timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)),
      line_key
    ) WHERE status = 'CURRENT'
    DO UPDATE
    SET source_ordinal = EXCLUDED.source_ordinal,
        parent_line_key = EXCLUDED.parent_line_key,
        split_suffix = EXCLUDED.split_suffix,
        section = EXCLUDED.section,
        source_row_json = EXCLUDED.source_row_json,
        economic_key_json = EXCLUDED.economic_key_json,
        contract_json = EXCLUDED.contract_json,
        pay_channel_scope = EXCLUDED.pay_channel_scope,
        refresh_scope_kind = EXCLUDED.refresh_scope_kind,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_candidate_source_lines.id
  )
  SELECT COUNT(*)::integer
  INTO v_source_rows_written
  FROM upserted_source_rows;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
  SET write_phase = 'UPSERT_LINE_WORK',
      write_cursor_json = jsonb_build_object('phase', 'UPSERT_LINE_WORK'),
      written_source_count = COALESCE(projection_run_update.written_source_count, 0) + COALESCE(v_source_rows_written, 0),
      updated_at_utc = v_now
  WHERE projection_run_update.id = p_projection_run_id
    AND projection_run_update.session_id = p_session_id
    AND projection_run_update.candidate_id = p_candidate_id;

  v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
  IF v_elapsed_ms >= v_budget_cutoff_ms THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'write_budget_checkpoint_elapsed_ms', v_elapsed_ms,
            'write_budget_checkpoint_at_utc', v_now::text,
            'write_budget_checkpoint_phase', COALESCE(v_write_phase, 'UNKNOWN')
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = p_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id;
  END IF;

  END IF;

  IF v_write_phase_order <= 5 THEN
  WITH upserted_line_rows AS (
    INSERT INTO public.banking_pay_workbench_candidate_line_work (
      session_id,
      candidate_id,
      timesheet_id,
      line_key,
      line_ordinal,
      status,
      work_payload_json,
      result_row_json,
      error_json,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      projection_rows.session_id,
      projection_rows.candidate_id,
      projection_rows.timesheet_id,
      projection_rows.line_key,
      projection_rows.row_ordinal,
      CASE
        WHEN COALESCE(v_sealed_targeted_delta, false) IS TRUE THEN 'PENDING'
        WHEN projection_rows.contract_ok IS TRUE
         AND projection_rows.materialisable IS TRUE
         AND LOWER(BTRIM(COALESCE(
           projection_rows.preview_row_json->>'live_pay_eligibility_proven',
           projection_rows.preview_row_json#>>'{live_pay_eligibility,proven}',
           projection_rows.source_row_json->>'live_pay_eligibility_proven',
           projection_rows.source_row_json#>>'{live_pay_eligibility,proven}',
           projection_rows.contract_json->>'live_pay_eligibility_proven',
           projection_rows.contract_json#>>'{live_pay_eligibility,proven}',
           'false'
         ))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'MATERIALISED'
        WHEN projection_rows.contract_ok IS TRUE THEN 'SKIPPED'
        ELSE 'ERROR'
      END,
      jsonb_strip_nulls(
        COALESCE(projection_rows.work_payload_json, '{}'::jsonb)
        || jsonb_build_object(
          'projection_path', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'projection_run_id', p_projection_run_id::text,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'targeted_delta_stage', CASE
            WHEN COALESCE(v_sealed_targeted_delta, false) IS TRUE THEN jsonb_build_object(
              'projection_run_id', p_projection_run_id::text,
              'final_status', CASE
                WHEN projection_rows.contract_ok IS TRUE
                 AND projection_rows.materialisable IS TRUE
                 AND LOWER(BTRIM(COALESCE(
                   projection_rows.preview_row_json->>'live_pay_eligibility_proven',
                   projection_rows.preview_row_json#>>'{live_pay_eligibility,proven}',
                   projection_rows.source_row_json->>'live_pay_eligibility_proven',
                   projection_rows.source_row_json#>>'{live_pay_eligibility,proven}',
                   projection_rows.contract_json->>'live_pay_eligibility_proven',
                   projection_rows.contract_json#>>'{live_pay_eligibility,proven}',
                   'false'
                 ))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'MATERIALISED'
                WHEN projection_rows.contract_ok IS TRUE THEN 'SKIPPED'
                ELSE 'ERROR'
              END
            )
            ELSE NULL::jsonb
          END
        )
      ),
      jsonb_strip_nulls(
        (COALESCE(projection_rows.result_row_json, '{}'::jsonb) - 'preview_contract')
        || jsonb_build_object(
          'projection_path', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'projection_run_id', p_projection_run_id::text,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'live_pay_eligibility_proven', LOWER(BTRIM(COALESCE(
            projection_rows.preview_row_json->>'live_pay_eligibility_proven',
            projection_rows.preview_row_json#>>'{live_pay_eligibility,proven}',
            projection_rows.source_row_json->>'live_pay_eligibility_proven',
            projection_rows.source_row_json#>>'{live_pay_eligibility,proven}',
            projection_rows.contract_json->>'live_pay_eligibility_proven',
            projection_rows.contract_json#>>'{live_pay_eligibility,proven}',
            'false'
          ))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'economic_key', projection_rows.economic_key_json,
          'preview_contract', projection_rows.result_row_json->'preview_contract'
        )
      ),
      CASE
        WHEN projection_rows.contract_ok IS TRUE THEN NULL::jsonb
        ELSE jsonb_build_object(
          'code', 'DELTA_CONTRACT_NOT_OK',
          'projection_run_id', p_projection_run_id::text
        )
      END,
      v_now,
      v_now
    FROM pg_temp._bpay_delta_projection_rows AS projection_rows
    WHERE projection_rows.projection_run_id = p_projection_run_id
      AND projection_rows.session_id = p_session_id
      AND projection_rows.candidate_id = p_candidate_id
    ON CONFLICT (session_id, candidate_id, (COALESCE(timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)), line_key)
    DO UPDATE
    SET line_ordinal = EXCLUDED.line_ordinal,
        status = EXCLUDED.status,
        work_payload_json = EXCLUDED.work_payload_json,
        result_row_json = EXCLUDED.result_row_json,
        error_json = EXCLUDED.error_json,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_candidate_line_work.id
  )
  SELECT COUNT(*)::integer
  INTO v_line_rows_written
  FROM upserted_line_rows;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
  SET write_phase = 'UPSERT_PREVIEW',
      write_cursor_json = jsonb_build_object('phase', 'UPSERT_PREVIEW'),
      written_line_work_count = COALESCE(projection_run_update.written_line_work_count, 0) + COALESCE(v_line_rows_written, 0),
      updated_at_utc = v_now
  WHERE projection_run_update.id = p_projection_run_id
    AND projection_run_update.session_id = p_session_id
    AND projection_run_update.candidate_id = p_candidate_id;

  v_elapsed_ms := FLOOR(EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::integer;
  IF v_elapsed_ms >= v_budget_cutoff_ms THEN
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET diagnostics_json = COALESCE(projection_run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'write_budget_checkpoint_elapsed_ms', v_elapsed_ms,
            'write_budget_checkpoint_at_utc', v_now::text,
            'write_budget_checkpoint_phase', COALESCE(v_write_phase, 'UNKNOWN')
          ),
        updated_at_utc = v_now
    WHERE projection_run_update.id = p_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id;
  END IF;

  END IF;

  IF v_write_phase_order <= 6 THEN
  DROP TABLE IF EXISTS pg_temp._bpay_delta_preview_upsert_rows;
  CREATE TEMP TABLE _bpay_delta_preview_upsert_rows ON COMMIT DROP AS
  SELECT
    projection_rows.*,
    existing_preview.id AS existing_preview_row_id,
    COALESCE(existing_preview.selected, false) AS existing_preview_selected,
    UPPER(BTRIM(COALESCE(existing_preview.selection_state, ''))) AS existing_preview_selection_state,
    CASE
      WHEN existing_preview.id IS NULL THEN false
      WHEN existing_preview.selected IS TRUE
       AND existing_preview.selection_state = 'SELECTED'
       AND existing_preview.row_key = projection_rows.row_key
       AND existing_preview.timesheet_id IS NOT DISTINCT FROM projection_rows.timesheet_id
       AND existing_preview.key_type IS NOT DISTINCT FROM projection_rows.key_type
       AND existing_preview.key_value IS NOT DISTINCT FROM projection_rows.key_value
       AND ROUND(COALESCE(CASE WHEN COALESCE(existing_preview.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (existing_preview.row_json->>'amount_ex_vat')::numeric ELSE NULL::numeric END, 0), 2) = ROUND(COALESCE(projection_rows.amount_ex_vat, 0), 2)
       AND ROUND(COALESCE(CASE WHEN COALESCE(existing_preview.row_json->>'amount_inc_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (existing_preview.row_json->>'amount_inc_vat')::numeric ELSE NULL::numeric END, 0), 2) = ROUND(COALESCE(projection_rows.amount_inc_vat, 0), 2)
       AND LOWER(BTRIM(COALESCE(existing_preview.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') = projection_rows.draftable
       AND LOWER(BTRIM(COALESCE(existing_preview.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') = projection_rows.is_ready_for_draft
       AND LOWER(BTRIM(COALESCE(existing_preview.row_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') = projection_rows.selection_allowed
       AND NULLIF(BTRIM(COALESCE(existing_preview.row_json->>'readiness_state', '')), '') IS NOT DISTINCT FROM NULLIF(BTRIM(COALESCE(projection_rows.readiness_state, '')), '')
       AND COALESCE(existing_preview.row_json->'outstanding_state_json', '{}'::jsonb) = COALESCE(projection_rows.outstanding_state_json, '{}'::jsonb)
      THEN true
      ELSE false
    END AS preserve_selected
  FROM pg_temp._bpay_delta_projection_rows AS projection_rows
  LEFT JOIN pg_temp._bpay_delta_existing_preview_rows AS existing_preview
    ON existing_preview.session_id = projection_rows.session_id
   AND existing_preview.candidate_id = projection_rows.candidate_id
   AND existing_preview.section = projection_rows.section
   AND existing_preview.row_key = projection_rows.row_key
  WHERE projection_rows.projection_run_id = p_projection_run_id
    AND projection_rows.session_id = p_session_id
    AND projection_rows.candidate_id = p_candidate_id;

  ALTER TABLE pg_temp._bpay_delta_preview_upsert_rows
    ADD COLUMN can_publish_ready boolean NOT NULL DEFAULT false,
    ADD COLUMN can_serve_selected boolean NOT NULL DEFAULT false,
    ADD COLUMN effective_selected boolean NOT NULL DEFAULT false,
    ADD COLUMN effective_selection_state text NOT NULL DEFAULT 'NOT_SELECTABLE';

  UPDATE pg_temp._bpay_delta_preview_upsert_rows AS preview_upsert_update
  SET can_publish_ready = (
        preview_upsert_update.contract_ok IS TRUE
        AND preview_upsert_update.materialisable IS TRUE
        AND preview_upsert_update.timesheet_id IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(preview_upsert_update.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(preview_upsert_update.key_value, '')), '') IS NOT NULL
        AND COALESCE(preview_upsert_update.contract_json->>'policy_x_authority_scope', preview_upsert_update.preview_row_json->>'policy_x_authority_scope', '') = 'PRE_DRAFT_LIVE_TRUTH'
        AND LOWER(BTRIM(COALESCE(
          preview_upsert_update.preview_row_json->>'live_pay_eligibility_proven',
          preview_upsert_update.preview_row_json#>>'{live_pay_eligibility,proven}',
          preview_upsert_update.source_row_json->>'live_pay_eligibility_proven',
          preview_upsert_update.source_row_json#>>'{live_pay_eligibility,proven}',
          preview_upsert_update.contract_json->>'live_pay_eligibility_proven',
          preview_upsert_update.contract_json#>>'{live_pay_eligibility,proven}',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_upsert_update.preview_row_json->>'projection_certified', preview_upsert_update.contract_json->>'projection_certified', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          LOWER(BTRIM(COALESCE(preview_upsert_update.preview_row_json->>'row_key_line_key_parity_proven', preview_upsert_update.contract_json->>'row_key_line_key_parity_proven', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR COALESCE(v_shadow_compare_passed, false) IS TRUE
        )
      ),
      can_serve_selected = (
        preview_upsert_update.contract_ok IS TRUE
        AND preview_upsert_update.materialisable IS TRUE
        AND preview_upsert_update.timesheet_id IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(preview_upsert_update.key_type, '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(preview_upsert_update.key_value, '')), '') IS NOT NULL
        AND COALESCE(preview_upsert_update.contract_json->>'policy_x_authority_scope', preview_upsert_update.preview_row_json->>'policy_x_authority_scope', '') = 'PRE_DRAFT_LIVE_TRUTH'
        AND LOWER(BTRIM(COALESCE(
          preview_upsert_update.preview_row_json->>'live_pay_eligibility_proven',
          preview_upsert_update.preview_row_json#>>'{live_pay_eligibility,proven}',
          preview_upsert_update.source_row_json->>'live_pay_eligibility_proven',
          preview_upsert_update.source_row_json#>>'{live_pay_eligibility,proven}',
          preview_upsert_update.contract_json->>'live_pay_eligibility_proven',
          preview_upsert_update.contract_json#>>'{live_pay_eligibility,proven}',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_upsert_update.preview_row_json->>'projection_certified', preview_upsert_update.contract_json->>'projection_certified', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          LOWER(BTRIM(COALESCE(preview_upsert_update.preview_row_json->>'row_key_line_key_parity_proven', preview_upsert_update.contract_json->>'row_key_line_key_parity_proven', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR COALESCE(v_shadow_compare_passed, false) IS TRUE
        )
        AND LOWER(BTRIM(COALESCE(preview_upsert_update.preview_row_json->>'target_selected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND COALESCE(NULLIF(BTRIM(preview_upsert_update.preview_row_json->>'target_selection_state'), ''), 'NOT_SELECTABLE') = 'SELECTED'
        AND preview_upsert_update.draftable IS TRUE
        AND preview_upsert_update.is_ready_for_draft IS TRUE
        AND preview_upsert_update.selection_allowed IS TRUE
        AND LOWER(BTRIM(COALESCE(preview_upsert_update.outstanding_state_json->>'reservation_overrun_detected', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      )
  WHERE preview_upsert_update.projection_run_id = p_projection_run_id
    AND preview_upsert_update.session_id = p_session_id
    AND preview_upsert_update.candidate_id = p_candidate_id;

  UPDATE pg_temp._bpay_delta_preview_upsert_rows AS preview_upsert_update
  SET effective_selected = CASE
        WHEN preview_upsert_update.can_serve_selected IS NOT TRUE THEN false
        WHEN preview_upsert_update.existing_preview_row_id IS NOT NULL
         AND preview_upsert_update.existing_preview_selection_state IN ('SELECTED', 'UNSELECTED')
          THEN COALESCE(preview_upsert_update.existing_preview_selected, false)
        WHEN COALESCE(v_selection_intent_mode, '') = 'EXPLICIT_INCLUDE' THEN EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(COALESCE(v_explicit_selected_preview_row_ids, '[]'::jsonb)) AS explicit_id(value)
          WHERE BTRIM(explicit_id.value) = preview_upsert_update.existing_preview_row_id::text
        )
        ELSE true
      END
  WHERE preview_upsert_update.projection_run_id = p_projection_run_id
    AND preview_upsert_update.session_id = p_session_id
    AND preview_upsert_update.candidate_id = p_candidate_id;

  UPDATE pg_temp._bpay_delta_preview_upsert_rows AS preview_upsert_update
  SET effective_selection_state = CASE
        WHEN preview_upsert_update.can_serve_selected IS NOT TRUE THEN 'NOT_SELECTABLE'
        WHEN preview_upsert_update.effective_selected IS TRUE THEN 'SELECTED'
        ELSE 'UNSELECTED'
      END
  WHERE preview_upsert_update.projection_run_id = p_projection_run_id
    AND preview_upsert_update.session_id = p_session_id
    AND preview_upsert_update.candidate_id = p_candidate_id;

  SELECT COUNT(*) FILTER (WHERE preview_upsert_rows.existing_preview_row_id IS NOT NULL AND preview_upsert_rows.effective_selected IS TRUE)::integer,
         COUNT(*) FILTER (WHERE preview_upsert_rows.existing_preview_row_id IS NOT NULL AND preview_upsert_rows.effective_selected IS NOT TRUE)::integer
  INTO v_selected_preserved_count,
       v_selected_cleared_count
  FROM pg_temp._bpay_delta_preview_upsert_rows AS preview_upsert_rows;

  SELECT COUNT(*)::integer
  INTO v_selection_guard_violation_count
  FROM pg_temp._bpay_delta_preview_upsert_rows AS preview_upsert_rows
  WHERE (
      preview_upsert_rows.can_serve_selected IS TRUE
      AND preview_upsert_rows.can_publish_ready IS NOT TRUE
    )
    OR (
      COALESCE(v_sealed_targeted_delta,false) IS TRUE
      AND preview_upsert_rows.can_publish_ready IS NOT TRUE
    );

  IF COALESCE(v_selection_guard_violation_count, 0) > 0 THEN
    UPDATE public.banking_pay_workbench_candidate_source_lines AS source_row_update
    SET status = 'SUPERSEDED',
        source_row_json = jsonb_strip_nulls(
          COALESCE(source_row_update.source_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'delta_write_selection_guard_failed', true,
            'delta_fallback_reason', 'DELTA_SELECTED_PREVIEW_ROW_SAFETY_GUARD_FAILED',
            'delta_fallback_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE source_row_update.session_id = p_session_id
      AND source_row_update.candidate_id = p_candidate_id
      AND source_row_update.source_build_run_id = p_projection_run_id
      AND source_row_update.status IN ('CURRENT', 'DIRTY');

    UPDATE public.banking_pay_workbench_candidate_line_work AS line_work_update
    SET status = 'SKIPPED',
        result_row_json = jsonb_strip_nulls(
          COALESCE(line_work_update.result_row_json, '{}'::jsonb)
          || jsonb_build_object(
            'delta_write_selection_guard_failed', true,
            'delta_fallback_reason', 'DELTA_SELECTED_PREVIEW_ROW_SAFETY_GUARD_FAILED',
            'delta_fallback_at_utc', v_now::text
          )
        ),
        updated_at_utc = v_now
    WHERE line_work_update.session_id = p_session_id
      AND line_work_update.candidate_id = p_candidate_id
      AND (
        COALESCE(line_work_update.work_payload_json->>'projection_run_id', '') = p_projection_run_id::text
        OR COALESCE(line_work_update.result_row_json->>'projection_run_id', '') = p_projection_run_id::text
      )
      AND UPPER(BTRIM(COALESCE(line_work_update.status, ''))) NOT IN ('ERROR', 'FAILED', 'SKIPPED');

    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
    SET write_phase = 'WRITE_FALLBACK_REQUIRED',
        fallback_required = true,
        fallback_reason = CASE
          WHEN COALESCE(v_sealed_targeted_delta,false) IS TRUE THEN 'TARGETED_DELTA_OUTPUT_NOT_READY'
          ELSE 'DELTA_SELECTED_PREVIEW_ROW_SAFETY_GUARD_FAILED'
        END,
        updated_at_utc = v_now
    WHERE projection_run_update.id = p_projection_run_id
      AND projection_run_update.session_id = p_session_id
      AND projection_run_update.candidate_id = p_candidate_id;

    RETURN jsonb_build_object(
      'ok', false,
      'fallback_required', true,
      'fallback_reason', CASE
        WHEN COALESCE(v_sealed_targeted_delta,false) IS TRUE THEN 'TARGETED_DELTA_OUTPUT_NOT_READY'
        ELSE 'DELTA_SELECTED_PREVIEW_ROW_SAFETY_GUARD_FAILED'
      END,
      'selection_guard_violation_count', COALESCE(v_selection_guard_violation_count, 0),
      'source_rows_written', 0,
      'line_rows_written', 0,
      'preview_rows_written', 0,
      'rows_superseded', 0
    );
  END IF;

  WITH upserted_preview_rows AS (
    INSERT INTO public.banking_pay_workbench_preview_rows (
      session_id,
      candidate_id,
      section,
      row_key,
      row_ordinal,
      row_json,
      timesheet_id,
      key_type,
      key_value,
      selected,
      selection_state,
      status,
      session_version,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      preview_upsert_rows.session_id,
      preview_upsert_rows.candidate_id,
      preview_upsert_rows.section,
      preview_upsert_rows.row_key,
      preview_upsert_rows.row_ordinal,
      jsonb_strip_nulls(
        (COALESCE(preview_upsert_rows.preview_row_json, '{}'::jsonb) - 'preview_contract')
        || jsonb_build_object(
          'projection_path', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'preview_contract', preview_upsert_rows.result_row_json->'preview_contract',
          'projection_run_id', p_projection_run_id::text,
          'projection_certified', preview_upsert_rows.can_publish_ready,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'selected', COALESCE(preview_upsert_rows.effective_selected, false),
          'selection_state', COALESCE(NULLIF(BTRIM(preview_upsert_rows.effective_selection_state), ''), 'NOT_SELECTABLE'),
          'outstanding_state_json', COALESCE(preview_upsert_rows.outstanding_state_json, '{}'::jsonb),
          'target_selected', LOWER(BTRIM(COALESCE(preview_upsert_rows.preview_row_json->>'target_selected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'target_selection_state', COALESCE(NULLIF(BTRIM(preview_upsert_rows.preview_row_json->>'target_selection_state'), ''), CASE WHEN preview_upsert_rows.can_serve_selected IS TRUE THEN 'SELECTED' ELSE 'NOT_SELECTABLE' END),
          'row_key_line_key_parity_proven', LOWER(BTRIM(COALESCE(preview_upsert_rows.preview_row_json->>'row_key_line_key_parity_proven', preview_upsert_rows.contract_json->>'row_key_line_key_parity_proven', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
          'shadow_compare_status', CASE WHEN COALESCE(v_shadow_compare_status, '') = '' THEN NULL ELSE v_shadow_compare_status END,
          'targeted_delta_stage', CASE
            WHEN COALESCE(v_sealed_targeted_delta, false) IS TRUE THEN jsonb_build_object(
              'projection_run_id', p_projection_run_id::text,
              'final_selected', COALESCE(preview_upsert_rows.effective_selected, false),
              'final_selection_state', COALESCE(NULLIF(BTRIM(preview_upsert_rows.effective_selection_state), ''), 'NOT_SELECTABLE'),
              'final_status', CASE WHEN preview_upsert_rows.can_publish_ready IS TRUE THEN 'READY' ELSE 'DELTA_PENDING' END
            )
            ELSE NULL::jsonb
          END
        )
      ),
      preview_upsert_rows.timesheet_id,
      preview_upsert_rows.key_type,
      preview_upsert_rows.key_value,
      CASE WHEN COALESCE(v_sealed_targeted_delta, false) IS TRUE THEN false ELSE COALESCE(preview_upsert_rows.effective_selected, false) END,
      CASE WHEN COALESCE(v_sealed_targeted_delta, false) IS TRUE THEN 'NOT_SELECTABLE' ELSE COALESCE(NULLIF(BTRIM(preview_upsert_rows.effective_selection_state), ''), 'NOT_SELECTABLE') END,
      CASE WHEN COALESCE(v_sealed_targeted_delta, false) IS TRUE THEN 'DELTA_PENDING' WHEN preview_upsert_rows.can_publish_ready IS TRUE THEN 'READY' ELSE 'DELTA_PENDING' END,
      preview_upsert_rows.session_version,
      v_now,
      v_now
    FROM pg_temp._bpay_delta_preview_upsert_rows AS preview_upsert_rows
    WHERE preview_upsert_rows.materialisable IS TRUE
      AND preview_upsert_rows.contract_ok IS TRUE
    ON CONFLICT (session_id, section, candidate_id, row_key)
    DO UPDATE
    SET row_ordinal = EXCLUDED.row_ordinal,
        row_json = EXCLUDED.row_json,
        timesheet_id = EXCLUDED.timesheet_id,
        key_type = EXCLUDED.key_type,
        key_value = EXCLUDED.key_value,
        selected = COALESCE(EXCLUDED.selected, false),
        selection_state = COALESCE(NULLIF(BTRIM(EXCLUDED.selection_state), ''), 'NOT_SELECTABLE'),
        status = EXCLUDED.status,
        session_version = EXCLUDED.session_version,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_preview_rows.id
  )
  SELECT COUNT(*)::integer
  INTO v_preview_rows_written
  FROM upserted_preview_rows;

  IF COALESCE(v_preview_rows_written, 0) > 0
     AND COALESCE(v_sealed_targeted_delta, false) IS NOT TRUE THEN
    PERFORM public.pay_workbench_session_recompute_progress_counters(
      p_session_id,
      true,
      'DELTA_WRITE_SELECTION_RECONCILE',
      false
    );

    SELECT COALESCE(jsonb_agg(to_jsonb(current_selected_preview_row.id::text) ORDER BY current_selected_preview_row.row_ordinal, current_selected_preview_row.id), '[]'::jsonb),
           COUNT(*)::integer
    INTO v_reconciled_selected_preview_row_ids,
         v_reconciled_selected_row_count
    FROM public.banking_pay_workbench_preview_rows AS current_selected_preview_row
    WHERE current_selected_preview_row.session_id = p_session_id
      AND current_selected_preview_row.session_version = COALESCE(v_current_session_version, 1)
      AND lower(COALESCE(NULLIF(BTRIM(current_selected_preview_row.section), ''), 'canonical_preview_lines')) = 'canonical_preview_lines'
      AND UPPER(BTRIM(COALESCE(current_selected_preview_row.status, ''))) = 'READY'
      AND COALESCE(current_selected_preview_row.selected, false) = true
      AND UPPER(BTRIM(COALESCE(current_selected_preview_row.selection_state, ''))) = 'SELECTED';

    UPDATE public.banking_pay_workbench_sessions AS selection_summary_session
    SET selected_row_count = COALESCE(v_reconciled_selected_row_count, 0),
        server_selected_preview_row_ids = CASE
          WHEN COALESCE(v_selection_intent_mode, '') = 'EXPLICIT_INCLUDE'
            OR COALESCE(selection_summary_session.server_selected_preview_row_ids_provided, false) IS TRUE
            THEN COALESCE(v_reconciled_selected_preview_row_ids, '[]'::jsonb)
          ELSE selection_summary_session.server_selected_preview_row_ids
        END,
        server_selected_preview_row_ids_provided = CASE
          WHEN COALESCE(v_selection_intent_mode, '') = 'EXPLICIT_INCLUDE' THEN true
          ELSE COALESCE(selection_summary_session.server_selected_preview_row_ids_provided, false)
        END,
        updated_at_utc = v_now
    WHERE selection_summary_session.id = p_session_id;
  END IF;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
  SET write_phase = 'WRITE_COUNTS',
      write_cursor_json = jsonb_build_object('phase', 'WRITE_COUNTS'),
      written_preview_count = COALESCE(projection_run_update.written_preview_count, 0) + COALESCE(v_preview_rows_written, 0),
      updated_at_utc = v_now
  WHERE projection_run_update.id = p_projection_run_id
    AND projection_run_update.session_id = p_session_id
    AND projection_run_update.candidate_id = p_candidate_id;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
  SET write_phase = 'WRITE_COMPLETE',
      write_cursor_json = jsonb_build_object('phase', 'WRITE_COMPLETE'),
      updated_at_utc = v_now
  WHERE projection_run_update.id = p_projection_run_id
    AND projection_run_update.session_id = p_session_id
    AND projection_run_update.candidate_id = p_candidate_id;

  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'fallback_required', false,
    'source_rows_written', COALESCE(v_source_rows_written, 0),
    'line_rows_written', COALESCE(v_line_rows_written, 0),
    'preview_rows_written', COALESCE(v_preview_rows_written, 0),
    'rows_superseded', COALESCE(v_preview_rows_superseded, 0) + COALESCE(v_source_rows_superseded, 0) + COALESCE(v_line_rows_superseded, 0),
    'preview_rows_superseded', COALESCE(v_preview_rows_superseded, 0),
    'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
    'line_rows_superseded', COALESCE(v_line_rows_superseded, 0),
    'selected_preserved_count', COALESCE(v_selected_preserved_count, 0),
    'selected_cleared_count', COALESCE(v_selected_cleared_count, 0),
    'affected_timesheet_count', COALESCE(array_length(v_affected_timesheet_ids, 1), 0),
    'affected_economic_key_count', COALESCE(v_affected_key_count, 0),
    'live_pay_eligibility_publication_guard', true,
    'write_phase', 'WRITE_COMPLETE',
    'write_cursor_json', jsonb_build_object('phase', 'WRITE_COMPLETE')
  );
END;
$function$;

-- pay_workbench_dirty_apply_jobs_chunk(integer,timestamp with time zone,uuid,uuid,text,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_dirty_apply_jobs_chunk(p_limit integer DEFAULT 5, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_session_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_worker_id text DEFAULT NULL::text, p_lease_seconds integer DEFAULT 180)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := COALESCE(p_now_utc, clock_timestamp());
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 5), 0), 50);
  v_processed integer := 0;
  v_succeeded integer := 0;
  v_failed integer := 0;
  v_requeued integer := 0;
  v_recovered_stale integer := 0;
  v_remaining integer := 0;
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_stage_result jsonb := '{}'::jsonb;
  v_processor_result jsonb := '{}'::jsonb;
  v_results jsonb := '[]'::jsonb;
  v_latest_source_change_seq bigint := 0;
  v_processed_source_change_seq bigint := 0;
  v_rerun_required boolean := false;
  v_lease_seconds integer := LEAST(GREATEST(COALESCE(p_lease_seconds, 180), 30), 3600);
  v_worker_id text := LEFT(COALESCE(NULLIF(BTRIM(p_worker_id), ''), 'dirty-priority-worker'), 200);
  v_processor_has_more boolean := false;
  v_next_cursor_json jsonb := '{}'::jsonb;
  v_page_limit integer := 100;
  v_error_message text;
  v_error_state text;
BEGIN
  UPDATE public.banking_pay_workbench_jobs AS stale_job
  SET status = 'QUEUED',
      run_at_utc = v_now,
      started_at_utc = NULL,
      updated_at_utc = v_now,
      payload_json = public._pay_workbench_dirty_payload_merge(
        COALESCE(stale_job.payload_json, '{}'::jsonb),
        jsonb_build_object(
          'rerun_required', true,
          'recovered_from_stale_running_at_utc', v_now::text,
          'recovered_by_worker_id', v_worker_id
        )
      )
  WHERE stale_job.status = 'RUNNING'
    AND stale_job.updated_at_utc <= v_now - make_interval(secs => v_lease_seconds)
    AND (
      stale_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY')
      OR (stale_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND COALESCE(stale_job.payload_json->>'queue_class', '') = 'DIRTY_TRIGGER_PRIORITY')
    );
  GET DIAGNOSTICS v_recovered_stale = ROW_COUNT;

  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', NULL::text, jsonb_build_object('function_name', 'pay_workbench_dirty_apply_jobs_chunk', 'stage', 'dirty_priority_lane_start', 'limit', v_limit, 'worker_id', v_worker_id, 'recovered_stale_count', v_recovered_stale));

  WHILE v_processed < v_limit LOOP
    v_job := NULL;

    WITH candidate_pool AS (
      SELECT
        claim_job.id,
        claim_job.job_type,
        claim_job.priority,
        claim_job.run_at_utc,
        claim_job.created_at_utc,
        claim_job.candidate_id,
        claim_job.payload_json,
        public._pay_workbench_candidate_serial_candidate_id(claim_job.candidate_id, claim_job.payload_json) AS candidate_serial_candidate_id,
        public._pay_workbench_candidate_serial_key(public._pay_workbench_candidate_serial_candidate_id(claim_job.candidate_id, claim_job.payload_json)) AS candidate_serial_key,
        (
          claim_job.job_type <> 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
          AND public._pay_workbench_candidate_serial_is_candidate_job(claim_job.job_type, claim_job.candidate_id, claim_job.payload_json)
        ) AS candidate_serial_required,
        (
          lower(BTRIM(COALESCE(claim_job.payload_json->>'continuation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR UPPER(BTRIM(COALESCE(claim_job.payload_json->>'run_mode', ''))) IN ('BOUNDED_CONTINUATION', 'CONTINUATION', 'STAGE_CONTINUATION')
          OR lower(BTRIM(COALESCE(claim_job.payload_json->>'fallback_from_delta', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR (
            lower(BTRIM(COALESCE(claim_job.payload_json->>'source_build_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            AND NULLIF(BTRIM(COALESCE(claim_job.payload_json->>'fallback_reason', '')), '') IS NOT NULL
          )
          OR (
            NULLIF(BTRIM(COALESCE(claim_job.payload_json->>'source_job_id', claim_job.payload_json->>'continuation_source_job_id', claim_job.payload_json->>'bounded_continuation_source_job_id', '')), '') IS NOT NULL
            AND UPPER(BTRIM(COALESCE(claim_job.payload_json->>'run_mode', ''))) NOT IN ('LATEST_STATE_HEAD', 'LATEST_RERUN_AFTER_RUNNING')
          )
        ) AS candidate_serial_is_chain_continuation
      FROM public.banking_pay_workbench_jobs AS claim_job
      WHERE claim_job.status = 'QUEUED'
        AND claim_job.run_at_utc <= v_now
        AND (
          claim_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY')
          OR (claim_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND COALESCE(claim_job.payload_json->>'queue_class', '') = 'DIRTY_TRIGGER_PRIORITY')
        )
        AND (p_candidate_id IS NULL OR claim_job.candidate_id = p_candidate_id OR claim_job.payload_json->>'candidate_id' = p_candidate_id::text OR claim_job.payload_json->'candidate_ids' ? p_candidate_id::text)
        AND (p_session_id IS NULL OR claim_job.session_id = p_session_id OR claim_job.payload_json->>'session_id' = p_session_id::text OR claim_job.payload_json->>'source_session_id' = p_session_id::text)
      ORDER BY claim_job.run_at_utc ASC, claim_job.priority ASC, claim_job.created_at_utc ASC, claim_job.id ASC
      FOR UPDATE SKIP LOCKED
      LIMIT GREATEST(v_limit * 5, 10)
    ), ranked_pool AS (
      SELECT
        candidate_pool.*,
        ROW_NUMBER() OVER (
          PARTITION BY COALESCE(candidate_pool.candidate_serial_key, candidate_pool.id::text)
          ORDER BY
            CASE WHEN candidate_pool.candidate_serial_required IS TRUE AND candidate_pool.candidate_serial_is_chain_continuation IS TRUE THEN 0 ELSE 1 END ASC,
            candidate_pool.run_at_utc ASC,
            candidate_pool.priority ASC,
            candidate_pool.created_at_utc ASC,
            candidate_pool.id ASC
        ) AS candidate_serial_rank
      FROM candidate_pool
    ), next_job AS (
      SELECT ranked_pool.id,
             ranked_pool.candidate_serial_required,
             ranked_pool.candidate_serial_key,
             ranked_pool.candidate_serial_candidate_id
      FROM ranked_pool
      CROSS JOIN LATERAL (
        SELECT public._pay_workbench_candidate_serial_active_state(
          ranked_pool.id,
          ranked_pool.candidate_serial_candidate_id,
          ranked_pool.job_type,
          ranked_pool.payload_json,
          v_now
        ) AS state_json
      ) AS candidate_serial_state
      WHERE (ranked_pool.candidate_serial_required IS NOT TRUE OR ranked_pool.candidate_serial_rank = 1)
        AND (ranked_pool.candidate_serial_required IS NOT TRUE OR pg_try_advisory_xact_lock(hashtextextended(ranked_pool.candidate_serial_key, 24062027)))
        AND (ranked_pool.candidate_serial_required IS NOT TRUE OR lower(BTRIM(COALESCE(candidate_serial_state.state_json->>'blocked', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on'))
      ORDER BY ranked_pool.run_at_utc ASC, ranked_pool.priority ASC, ranked_pool.created_at_utc ASC, ranked_pool.id ASC
      LIMIT 1
    ), claimed AS (
      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'RUNNING',
          attempt_count = COALESCE(update_job.attempt_count, 0) + 1,
          started_at_utc = COALESCE(update_job.started_at_utc, v_now),
          updated_at_utc = v_now,
          last_error_json = NULL::jsonb,
          payload_json = public._pay_workbench_dirty_payload_merge(
            COALESCE(update_job.payload_json, '{}'::jsonb),
            jsonb_strip_nulls(jsonb_build_object(
              'claimed_at_utc', v_now::text,
              'claimed_by_worker_id', v_worker_id,
              'candidate_serial_key', CASE WHEN next_job.candidate_serial_required IS TRUE THEN next_job.candidate_serial_key ELSE NULL END,
              'candidate_serial_candidate_id', CASE WHEN next_job.candidate_serial_candidate_id IS NULL THEN NULL ELSE next_job.candidate_serial_candidate_id::text END,
              'candidate_serial_active_chain_id', CASE WHEN next_job.candidate_serial_required IS TRUE THEN COALESCE(NULLIF(BTRIM(COALESCE(update_job.payload_json->>'candidate_serial_active_chain_id', '')), ''), NULLIF(BTRIM(COALESCE(update_job.payload_json->>'source_job_id', '')), ''), update_job.id::text) ELSE NULL END,
              'candidate_serial_started_at_utc', CASE WHEN next_job.candidate_serial_required IS TRUE THEN v_now::text ELSE NULL END,
              'candidate_serial_reason', CASE WHEN next_job.candidate_serial_required IS TRUE THEN 'CANDIDATE_SERIAL_CLAIM_GRANTED' ELSE NULL END
            ))
          )
      FROM next_job
      WHERE update_job.id = next_job.id
      RETURNING update_job.*
    )
    SELECT claimed.* INTO v_job FROM claimed;

    IF v_job.id IS NULL THEN
      EXIT;
    END IF;

    v_processed := v_processed + 1;
    PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', v_job.id::text, jsonb_build_object('function_name', 'pay_workbench_dirty_apply_jobs_chunk', 'stage', 'dirty_priority_claimed', 'job_id', v_job.id::text, 'job_type', v_job.job_type, 'dedupe_key', v_job.dedupe_key, 'priority', v_job.priority, 'queue_class', COALESCE(v_job.payload_json->>'queue_class', '')));

    IF NULLIF(BTRIM(COALESCE(v_job.payload_json->>'candidate_serial_key', '')), '') IS NOT NULL THEN
      PERFORM public._pay_workbench_candidate_serial_audit(
        'CANDIDATE_SERIAL_CLAIM_GRANTED',
        v_job.id,
        public._pay_workbench_candidate_serial_candidate_id(v_job.candidate_id, v_job.payload_json),
        jsonb_build_object(
          'job_type', v_job.job_type,
          'candidate_serial_key', v_job.payload_json->>'candidate_serial_key',
          'candidate_serial_active_chain_id', v_job.payload_json->>'candidate_serial_active_chain_id',
          'claimed_by_worker_id', v_worker_id,
          'claimed_at_utc', v_now::text
        ),
        'CANDIDATE_SERIAL_CLAIM_GRANTED',
        NULL::uuid
      );
    END IF;

    BEGIN
      IF v_job.job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN
        v_processor_result := public.pay_workbench_candidate_dirty_apply_job_process(v_job.id, 100);
      ELSIF v_job.job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' THEN
        v_processor_result := public.pay_workbench_finance_case_dirty_apply_job_process(v_job.id, 100);
      ELSIF v_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
        v_page_limit := COALESCE(
          CASE WHEN COALESCE(v_job.payload_json->>'page_limit', '') ~ '^\d+$' THEN (v_job.payload_json->>'page_limit')::integer END,
          100
        );
        v_processor_result := public.pay_workbench_contract_client_dirty_fanout_chunk(v_job.id, NULL::jsonb, v_page_limit);
      ELSE
        RAISE EXCEPTION 'Unsupported dirty priority job_type %', v_job.job_type
          USING ERRCODE = '22023';
      END IF;

      IF lower(COALESCE(v_processor_result->>'candidate_serial_delayed', 'false')) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
        SELECT COALESCE(job_after.payload_json, '{}'::jsonb)
        INTO v_stage_result
        FROM public.banking_pay_workbench_jobs AS job_after
        WHERE job_after.id = v_job.id;

        v_requeued := v_requeued + 1;
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'job_id', v_job.id::text,
          'job_type', v_job.job_type,
          'status', 'DELAYED',
          'stage_result', v_processor_result,
          'job_payload_after', v_stage_result
        ));
        CONTINUE;
      END IF;

      v_processor_has_more := lower(COALESCE(v_processor_result->>'has_more', 'false')) IN ('true', 't', '1', 'yes', 'y', 'on');
      v_next_cursor_json := CASE
        WHEN jsonb_typeof(v_processor_result->'next_cursor_json') = 'object' THEN v_processor_result->'next_cursor_json'
        WHEN jsonb_typeof(v_processor_result->'next_cursor') = 'object' THEN v_processor_result->'next_cursor'
        ELSE '{}'::jsonb
      END;

      UPDATE public.banking_pay_workbench_jobs AS cursor_job
      SET payload_json = public._pay_workbench_dirty_payload_merge(
            COALESCE(cursor_job.payload_json, '{}'::jsonb),
            jsonb_build_object(
              'cursor_json', CASE WHEN v_processor_has_more THEN COALESCE(v_next_cursor_json, '{}'::jsonb) ELSE '{}'::jsonb END,
              'next_cursor_json', COALESCE(v_next_cursor_json, '{}'::jsonb),
              'has_more', COALESCE(v_processor_has_more, false)
            )
          ),
          updated_at_utc = v_now
      WHERE cursor_job.id = v_job.id;

      SELECT COALESCE(job_after.payload_json, '{}'::jsonb)
      INTO v_stage_result
      FROM public.banking_pay_workbench_jobs AS job_after
      WHERE job_after.id = v_job.id;

      v_latest_source_change_seq := COALESCE(CASE WHEN COALESCE(v_stage_result->>'latest_source_change_seq', '') ~ '^\d+$' THEN (v_stage_result->>'latest_source_change_seq')::bigint END, 0);
      v_processed_source_change_seq := COALESCE(CASE WHEN COALESCE(v_stage_result->>'processed_source_change_seq', '') ~ '^\d+$' THEN (v_stage_result->>'processed_source_change_seq')::bigint END, v_latest_source_change_seq);
      v_rerun_required := lower(COALESCE(v_stage_result->>'rerun_required', 'false')) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR v_latest_source_change_seq > v_processed_source_change_seq;

      IF v_processor_has_more IS TRUE THEN
        v_rerun_required := true;
      END IF;

      IF v_rerun_required THEN
        UPDATE public.banking_pay_workbench_jobs AS requeue_job
        SET status = 'QUEUED',
            run_at_utc = v_now,
            started_at_utc = NULL,
            completed_at_utc = NULL,
            failed_at_utc = NULL,
            last_error_json = NULL::jsonb,
            updated_at_utc = v_now,
            payload_json = public._pay_workbench_dirty_payload_merge(
              COALESCE(requeue_job.payload_json, '{}'::jsonb),
              jsonb_build_object(
                'rerun_required', false,
                'requeued_due_to_later_change_at_utc', v_now::text,
                'processed_source_change_seq', v_processed_source_change_seq,
                'latest_source_change_seq', GREATEST(v_latest_source_change_seq, v_processed_source_change_seq)
              )
            )
        WHERE requeue_job.id = v_job.id;
        v_requeued := v_requeued + 1;
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', v_job.id::text, jsonb_build_object('function_name', 'pay_workbench_dirty_apply_jobs_chunk', 'stage', 'dirty_worker_requeued_due_to_later_change', 'job_id', v_job.id::text, 'job_type', v_job.job_type, 'latest_source_change_seq', v_latest_source_change_seq, 'processed_source_change_seq', v_processed_source_change_seq));
      ELSE
        PERFORM public.pay_workbench_complete_job(
          p_job_id => v_job.id,
          p_result_json => public._pay_workbench_dirty_payload_merge(
            v_stage_result,
            jsonb_build_object('completed_by_dirty_priority_lane', true, 'completed_at_utc', v_now::text)
          )
        );
        v_succeeded := v_succeeded + 1;
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', v_job.id::text, jsonb_build_object('function_name', 'pay_workbench_dirty_apply_jobs_chunk', 'stage', 'dirty_worker_completed', 'job_id', v_job.id::text, 'job_type', v_job.job_type));
      END IF;

      v_results := v_results || jsonb_build_array(jsonb_build_object('job_id', v_job.id::text, 'job_type', v_job.job_type, 'status', CASE WHEN v_rerun_required THEN 'REQUEUED' ELSE 'SUCCEEDED' END, 'stage_result', v_processor_result, 'job_payload_after', v_stage_result));
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS v_error_message = MESSAGE_TEXT, v_error_state = RETURNED_SQLSTATE;
      PERFORM public.pay_workbench_fail_job(
        p_job_id => v_job.id,
        p_error_json => jsonb_build_object(
          'code', COALESCE(v_error_state, 'DIRTY_PRIORITY_FAILED'),
          'message', COALESCE(v_error_message, 'Dirty priority job failed'),
          'job_type', v_job.job_type,
          'failed_at_utc', v_now::text,
          'worker_id', v_worker_id
        )
      );
      v_failed := v_failed + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('job_id', v_job.id::text, 'job_type', v_job.job_type, 'status', 'FAILED', 'error', jsonb_build_object('code', v_error_state, 'message', v_error_message)));
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', v_job.id::text, jsonb_build_object('function_name', 'pay_workbench_dirty_apply_jobs_chunk', 'stage', 'dirty_worker_failed', 'job_id', v_job.id::text, 'job_type', v_job.job_type, 'error_code', v_error_state, 'error_message', v_error_message));
    END;
  END LOOP;

  SELECT COUNT(*)::integer
  INTO v_remaining
  FROM public.banking_pay_workbench_jobs AS remaining_job
  WHERE remaining_job.status = 'QUEUED'
    AND remaining_job.run_at_utc <= v_now
    AND (
      remaining_job.job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY')
      OR (remaining_job.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND COALESCE(remaining_job.payload_json->>'queue_class', '') = 'DIRTY_TRIGGER_PRIORITY')
    );

  IF v_processed >= v_limit AND v_remaining > 0 THEN
    PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', NULL::text, jsonb_build_object('function_name', 'pay_workbench_dirty_apply_jobs_chunk', 'stage', 'dirty_priority_cap_reached', 'dirty_priority_jobs_processed', v_processed, 'dirty_priority_jobs_remaining', v_remaining));
  ELSIF v_remaining = 0 THEN
    PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', NULL::text, jsonb_build_object('function_name', 'pay_workbench_dirty_apply_jobs_chunk', 'stage', 'dirty_priority_empty', 'dirty_priority_jobs_processed', v_processed));
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'dirty_priority_jobs_processed', v_processed,
    'processed', v_processed,
    'succeeded', v_succeeded,
    'failed', v_failed,
    'requeued', v_requeued,
    'recovered_stale_count', v_recovered_stale,
    'dirty_priority_jobs_remaining', v_remaining,
    'cap_reached', (v_processed >= v_limit AND v_remaining > 0),
    'more_due', (v_remaining > 0),
    'worker_id', v_worker_id,
    'job_results', v_results,
    'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
  );
END;
$function$;

-- pay_workbench_dirty_event_enqueue(text,text,text,uuid,uuid[],uuid[],jsonb,text,integer,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.pay_workbench_dirty_event_enqueue(p_job_type text, p_scope_kind text, p_scope_id text, p_candidate_id uuid DEFAULT NULL::uuid, p_targeted_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_linked_timesheet_ids uuid[] DEFAULT ARRAY[]::uuid[], p_payload_json jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_priority integer DEFAULT '-1000'::integer, p_run_at_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job_type text := UPPER(BTRIM(COALESCE(p_job_type, '')));
  v_scope_kind text := UPPER(BTRIM(COALESCE(p_scope_kind, '')));
  v_scope_id text := NULLIF(BTRIM(COALESCE(p_scope_id, '')), '');
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_key_part text := 'ALL';
  v_dedupe_key text;
  v_reason text := NULLIF(BTRIM(COALESCE(p_reason, '')), '');
  v_payload_json jsonb := '{}'::jsonb;
  v_incoming_payload jsonb := '{}'::jsonb;
  v_latest_source_change_seq bigint := 0;
  v_job_id uuid;
  v_job_status text;
  v_job_payload jsonb;
  v_priority integer := COALESCE(p_priority, -1000);
  v_run_at_utc timestamptz := COALESCE(p_run_at_utc, v_now);
  v_scope_uuid uuid := NULL::uuid;
  v_scope_invalidation_result jsonb := '{}'::jsonb;
  v_scope_change_tx_token uuid := NULL::uuid;
BEGIN
  IF v_job_type NOT IN (
    'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'CONTRACT_CLIENT_DIRTY_FANOUT'
  ) THEN
    RAISE EXCEPTION 'Unsupported Banking Pay dirty event job_type: %', p_job_type
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_kind = '' OR v_scope_id IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event requires scope_kind and scope_id'
      USING ERRCODE = '22023';
  END IF;

  IF v_scope_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_scope_uuid := v_scope_id::uuid;
  END IF;

  IF v_job_type IN ('WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT')
     AND v_scope_uuid IS NULL THEN
    RAISE EXCEPTION 'Banking Pay dirty event scope_id must be a UUID for job_type %, scope_kind %, scope_id %', v_job_type, v_scope_kind, v_scope_id
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT target_id ORDER BY target_id), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM unnest(COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[])) AS target_id
  WHERE target_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT linked_id ORDER BY linked_id), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM unnest(COALESCE(p_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_id
  WHERE linked_id IS NOT NULL;

  -- The central invalidator owns durable candidate/timesheet economic state.
  -- Its guarded callback into this function preserves the installed queue
  -- envelope without recursion or a second queue authority.
  IF v_job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
     AND p_candidate_id IS NOT NULL
     AND COALESCE(current_setting('cloudtms.bpay_scope_invalidator_active',true),'')<>'true' THEN
    IF COALESCE(p_payload_json->>'scope_change_tx_token','')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_scope_change_tx_token:=(p_payload_json->>'scope_change_tx_token')::uuid;
    END IF;
    v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
      CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[p_candidate_id]
        ELSE array_fill(p_candidate_id,ARRAY[cardinality(v_targeted_timesheet_ids)]) END,
      CASE WHEN cardinality(v_targeted_timesheet_ids)=0 THEN ARRAY[NULL::uuid]
        ELSE v_targeted_timesheet_ids END,
      COALESCE(v_reason,'DIRTY_TRIGGER:'||v_scope_kind),
      v_scope_change_tx_token,
      COALESCE(p_payload_json,'{}'::jsonb)||jsonb_build_object('skip_candidate_job_enqueue',true)
    );
  END IF;

  IF COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN
    v_targeted_key_part := array_to_string(v_targeted_timesheet_ids, ',');
  END IF;

  IF p_candidate_id IS NOT NULL THEN
    PERFORM public._change_bump('pay_candidate:' || p_candidate_id::text);

    SELECT COALESCE(change_counter.seq, 0)
    INTO v_latest_source_change_seq
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;
  END IF;

  v_latest_source_change_seq := GREATEST(
    COALESCE(v_latest_source_change_seq, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'latest_source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_seq', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(p_payload_json->>'source_change_sequence', '') ~ '^\d+$' THEN (p_payload_json->>'source_change_sequence')::bigint END, 0)
  );

  IF v_reason IS NULL THEN
    v_reason := 'DIRTY_TRIGGER:' || v_scope_kind;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN
    IF p_candidate_id IS NULL THEN
      RAISE EXCEPTION 'Candidate dirty apply job requires p_candidate_id'
        USING ERRCODE = '22023';
    END IF;
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_CANDIDATE_DIRTY_APPLY:CANDIDATE:'
      || p_candidate_id::text
      || ':TIMESHEETS:' || v_targeted_key_part;
  ELSIF v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' THEN
    v_dedupe_key := 'DIRTY_TRIGGER:WORKBENCH_FINANCE_CASE_DIRTY_APPLY:' || v_scope_kind || ':' || v_scope_id;
  ELSE
    v_dedupe_key := 'DIRTY_TRIGGER:CONTRACT_CLIENT_DIRTY_FANOUT:' || v_scope_kind || ':' || v_scope_id;
  END IF;

  v_incoming_payload := jsonb_strip_nulls(
    COALESCE(p_payload_json, '{}'::jsonb)
    || jsonb_build_object(
      'job_type', v_job_type,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority_class', 'DIRTY_TRIGGER_PRIORITY',
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'finance_case_id', CASE WHEN v_job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'contract_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CONTRACT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'client_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'CLIENT' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'umbrella_id', CASE WHEN v_job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT' AND v_scope_kind = 'UMBRELLA' AND v_scope_uuid IS NOT NULL THEN v_scope_uuid::text ELSE NULL::text END,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(to_jsonb(v_linked_timesheet_ids), '[]'::jsonb),
      'reason', v_reason,
      'reason_latest', v_reason,
      'reason_count', 1,
      'trigger_source', COALESCE(p_payload_json->>'trigger_source', p_payload_json->>'trigger_table', v_scope_kind),
      'latest_source_change_seq', v_latest_source_change_seq,
      'source_change_seq', v_latest_source_change_seq,
      'source_change_sequence', v_latest_source_change_seq,
      'latest_event_at_utc', v_now::text,
      'event_at_utc', v_now::text,
      'rerun_required', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'policy_x_dirtying_only', true,
      'economic_truth_mutation_allowed', false
    )
  );

  v_payload_json := public._pay_workbench_dirty_payload_merge('{}'::jsonb, v_incoming_payload);

  INSERT INTO public.banking_pay_workbench_jobs AS queued_job (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    v_job_type,
    'QUEUED',
    v_priority,
    v_run_at_utc,
    0,
    8,
    v_dedupe_key,
    NULL,
    NULL,
    CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DIRTY_APPLY' THEN p_candidate_id ELSE NULL::uuid END,
    v_payload_json,
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(queued_job.priority, EXCLUDED.priority),
      run_at_utc = LEAST(queued_job.run_at_utc, EXCLUDED.run_at_utc),
      updated_at_utc = v_now,
      failed_at_utc = CASE WHEN queued_job.status = 'QUEUED' THEN NULL ELSE queued_job.failed_at_utc END,
      last_error_json = CASE WHEN queued_job.status = 'QUEUED' THEN NULL::jsonb ELSE queued_job.last_error_json END,
      payload_json = public._pay_workbench_dirty_payload_merge(
        COALESCE(queued_job.payload_json, '{}'::jsonb),
        COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        || CASE
             WHEN queued_job.status = 'RUNNING' THEN jsonb_build_object('rerun_required', true)
             ELSE '{}'::jsonb
           END
      )
  RETURNING queued_job.id, queued_job.status, queued_job.payload_json
  INTO v_job_id, v_job_status, v_job_payload;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    v_scope_id,
    jsonb_build_object(
      'function_name', 'pay_workbench_dirty_event_enqueue',
      'stage', CASE WHEN v_job_status = 'RUNNING' THEN 'dirty_enqueue_coalesced_existing_running' ELSE 'dirty_enqueue_inserted_or_coalesced_queued' END,
      'job_id', v_job_id::text,
      'job_type', v_job_type,
      'dedupe_key', v_dedupe_key,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'priority', v_priority,
      'scope_kind', v_scope_kind,
      'scope_id', v_scope_id,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'latest_source_change_seq', v_latest_source_change_seq,
      'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'status', v_job_status,
    'dedupe_key', v_dedupe_key,
    'queue_class', 'DIRTY_TRIGGER_PRIORITY',
    'priority', v_priority,
    'scope_kind', v_scope_kind,
    'scope_id', v_scope_id,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
    'latest_source_change_seq', v_latest_source_change_seq,
    'rerun_required', COALESCE((v_job_payload->>'rerun_required')::boolean, false)
  );
END;
$function$;

-- pay_workbench_enqueue_candidate_refresh_many(uuid,jsonb,text,uuid)
CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_candidate_refresh_many(p_session_id uuid, p_candidate_ids jsonb, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_candidate_ids_input jsonb := '[]'::jsonb;
  v_skip_candidate_ids_input jsonb := '[]'::jsonb;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_skip_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_requested_count integer := 0;
  v_scope_count integer := 0;
  v_queued_count integer := 0;
  v_reused_count integer := 0;
  v_legacy_queued_count integer := 0;
  v_delta_queued_count integer := 0;
  v_clone_skipped_ready_count integer := 0;
  v_clone_skipped_pending_count integer := 0;
  v_clone_skip_list_count integer := 0;
  v_enqueued_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_enqueued_candidate_count integer := 0;
  v_clone_rebase_queued boolean := false;
  v_candidate_scope_status text := NULL::text;
  v_candidate_state_status text := NULL::text;
  v_candidate_clone_certified boolean := false;
  v_candidate_clone_failed boolean := false;
  v_job_ids_jsonb jsonb := '[]'::jsonb;
  v_source_build_run_ids_jsonb jsonb := '[]'::jsonb;
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), 'SESSION_SOURCE_BUILD_REFRESH');
  v_candidate_id uuid;
  v_refresh_result jsonb := '{}'::jsonb;
  v_job_id_text text := NULL::text;
  v_previous_ready integer := 0;
  v_previous_failed integer := 0;
  v_previous_pending integer := 0;
  v_source_build_limit integer := 25;
  v_pay_channel_scope text := 'ALL';
  v_force_refresh boolean := false;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF p_candidate_ids IS NULL THEN
    RAISE EXCEPTION 'p_candidate_ids must be supplied';
  END IF;

  IF jsonb_typeof(p_candidate_ids) = 'array' THEN
    v_candidate_ids_input := p_candidate_ids;
  ELSIF jsonb_typeof(p_candidate_ids) = 'object' AND jsonb_typeof(p_candidate_ids->'candidate_ids') = 'array' THEN
    v_candidate_ids_input := p_candidate_ids->'candidate_ids';
    v_force_refresh := LOWER(BTRIM(COALESCE(
      p_candidate_ids->>'force_refresh',
      p_candidate_ids->>'forceRefresh',
      p_candidate_ids->>'user_requested_refresh',
      p_candidate_ids->>'userRequestedRefresh',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
    IF jsonb_typeof(p_candidate_ids->'skip_candidate_ids') = 'array' THEN
      v_skip_candidate_ids_input := v_skip_candidate_ids_input || p_candidate_ids->'skip_candidate_ids';
    END IF;
    IF jsonb_typeof(p_candidate_ids->'clone_rebase_skip_candidate_ids') = 'array' THEN
      v_skip_candidate_ids_input := v_skip_candidate_ids_input || p_candidate_ids->'clone_rebase_skip_candidate_ids';
    END IF;
    IF jsonb_typeof(p_candidate_ids->'cloned_ready_candidate_ids') = 'array' THEN
      v_skip_candidate_ids_input := v_skip_candidate_ids_input || p_candidate_ids->'cloned_ready_candidate_ids';
    END IF;
    IF jsonb_typeof(p_candidate_ids->'clone_ready_candidate_ids') = 'array' THEN
      v_skip_candidate_ids_input := v_skip_candidate_ids_input || p_candidate_ids->'clone_ready_candidate_ids';
    END IF;
  ELSE
    RAISE EXCEPTION 'p_candidate_ids must be a non-empty JSON array or an object containing candidate_ids';
  END IF;

  IF jsonb_array_length(v_candidate_ids_input) = 0 THEN
    RAISE EXCEPTION 'p_candidate_ids must be a non-empty JSON array';
  END IF;

  IF jsonb_array_length(v_candidate_ids_input) > 100 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_MANY_INPUT_TOO_LARGE',
      'message', 'At most 100 candidate ids may be enqueued in one RPC. Seed workbench scope chunks and call again with a capped page.',
      'session_id', p_session_id::text,
      'requested_count', jsonb_array_length(v_candidate_ids_input),
      'max_candidate_ids', 100,
      'recommended_next_api', 'pay_workbench_session_seed_scope_chunk'
    );
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not open', p_session_id;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id
    AND COALESCE(actor_user.is_active, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found or inactive', p_actor_user_id;
  END IF;

  SELECT COALESCE(array_agg(candidate_input.candidate_id ORDER BY candidate_input.candidate_id), ARRAY[]::uuid[]),
         count(*)::integer
  INTO v_candidate_ids, v_requested_count
  FROM (
    SELECT DISTINCT (candidate_element.value #>> '{}')::uuid AS candidate_id
    FROM jsonb_array_elements(v_candidate_ids_input) AS candidate_element(value)
    WHERE (candidate_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS candidate_input;

  IF COALESCE(v_requested_count, 0) <> jsonb_array_length(v_candidate_ids_input) THEN
    RAISE EXCEPTION 'p_candidate_ids contains invalid candidate id values';
  END IF;

  SELECT COALESCE(array_agg(skip_input.candidate_id ORDER BY skip_input.candidate_id), ARRAY[]::uuid[])
  INTO v_skip_candidate_ids
  FROM (
    SELECT DISTINCT (skip_element.value #>> '{}')::uuid AS candidate_id
    FROM jsonb_array_elements(v_skip_candidate_ids_input) AS skip_element(value)
    WHERE (skip_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS skip_input;

  SELECT count(*)::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY'))::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer
  INTO v_scope_count,
       v_previous_ready,
       v_previous_failed,
       v_previous_pending
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = ANY(v_candidate_ids);

  IF v_scope_count <> v_requested_count THEN
    RAISE EXCEPTION 'one or more candidate ids do not belong to session % scope', p_session_id;
  END IF;

  SELECT LEAST(GREATEST(COALESCE(
    CASE
      WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job', '') ~ '^[0-9]{1,9}$'
        THEN (to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job')::integer
      ELSE NULL::integer
    END,
    CASE
      WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job', '') ~ '^[0-9]{1,9}$'
        THEN (to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job')::integer
      ELSE NULL::integer
    END,
    25
  ), 1), 100)
  INTO v_source_build_limit
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1
  LIMIT 1;

  v_source_build_limit := COALESCE(v_source_build_limit, 25);

  v_pay_channel_scope := NULLIF(UPPER(BTRIM(COALESCE(
    v_session_row.filters_json->>'pay_channel_scope',
    v_session_row.filters_json#>>'{filters,pay_channel_scope}',
    'ALL'
  ))), '');

  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  v_clone_rebase_queued := UPPER(BTRIM(COALESCE(v_session_row.progress_state, ''))) = 'CLONE_REBASING'
    OR LOWER(BTRIM(COALESCE(v_session_row.progress_json->>'clone_rebase_queued', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR LOWER(BTRIM(COALESCE(v_session_row.progress_json->>'clone_rebase_more_due', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR (
      jsonb_typeof(p_candidate_ids) = 'object'
      AND LOWER(BTRIM(COALESCE(p_candidate_ids->>'clone_rebase_queued', p_candidate_ids->>'clone_rebase_pending', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    );

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP
    v_candidate_scope_status := NULL::text;
    v_candidate_state_status := NULL::text;
    v_candidate_clone_certified := false;
    v_candidate_clone_failed := false;

    SELECT UPPER(BTRIM(COALESCE(scope_row.status, ''))),
           UPPER(BTRIM(COALESCE(candidate_state.status, ''))),
           COALESCE(
             LOWER(BTRIM(COALESCE(candidate_state.effective_summary_fragment_json->>'clone_certified', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             false
           )
           OR COALESCE(
             LOWER(BTRIM(COALESCE(candidate_state.effective_candidate_fragment_json->>'clone_certified', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             false
           )
           OR COALESCE(
             LOWER(BTRIM(COALESCE(scope_row.error_json#>>'{clone_eligibility,clone_certified}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
             false
           ),
           (
             scope_row.error_json ? 'clone_eligibility'
             OR LOWER(BTRIM(COALESCE(scope_row.error_json->>'clone_eligibility_failed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR LOWER(BTRIM(COALESCE(scope_row.error_json#>>'{clone_eligibility,clone_eligible}', 'true'))) IN ('false', 'f', '0', 'no', 'n', 'off')
           )
    INTO v_candidate_scope_status,
         v_candidate_state_status,
         v_candidate_clone_certified,
         v_candidate_clone_failed
    FROM public.banking_pay_workbench_session_scope AS scope_row
    LEFT JOIN public.banking_pay_workbench_session_candidate_state AS candidate_state
      ON candidate_state.session_id = scope_row.session_id
     AND candidate_state.candidate_id = scope_row.candidate_id
    WHERE scope_row.session_id = p_session_id
      AND scope_row.candidate_id = v_candidate_id
    LIMIT 1;

    IF v_candidate_id = ANY(COALESCE(v_skip_candidate_ids, ARRAY[]::uuid[]))
       OR (
         COALESCE(v_force_refresh, false) IS NOT TRUE
         AND
         COALESCE(v_candidate_clone_certified, false) IS TRUE
         AND v_candidate_scope_status IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY')
         AND COALESCE(v_candidate_state_status, 'READY') IN ('READY', 'READY_EMPTY')
       ) THEN
      v_clone_skipped_ready_count := v_clone_skipped_ready_count + 1;
      IF v_candidate_id = ANY(COALESCE(v_skip_candidate_ids, ARRAY[]::uuid[])) THEN
        v_clone_skip_list_count := v_clone_skip_list_count + 1;
      END IF;
      CONTINUE;
    END IF;

    IF COALESCE(v_force_refresh, false) IS NOT TRUE
       AND COALESCE(v_clone_rebase_queued, false) IS TRUE
       AND COALESCE(v_candidate_clone_failed, false) IS NOT TRUE THEN
      v_clone_skipped_pending_count := v_clone_skipped_pending_count + 1;
      CONTINUE;
    END IF;

    v_refresh_result := public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => v_session_row.source_snapshot_run_id,
      p_candidate_id => v_candidate_id,
      p_reason => v_reason,
      p_actor_user_id => p_actor_user_id,
      p_payload_json => jsonb_build_object(
        'session_id', p_session_id::text,
        'source_session_id', p_session_id::text,
        'session_signature', v_session_row.session_signature,
        'session_version', COALESCE(v_session_row.version, 0),
        'force_broad_legacy', true,
        'force_legacy', true,
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'enqueue_origin', 'SESSION_SCOPE_SEED_OR_PAGE',
        'source_build_required', true,
        'line_work_required', true,
        'line_work_only', false,
        'delta_refresh_required', false,
        'source_build_action', 'BUILD_SOURCE',
        'targeted_timesheet_ids', '[]'::jsonb,
        'linked_timesheet_ids', '[]'::jsonb,
        'pay_channel_scope', v_pay_channel_scope,
        'source_build_limit', v_source_build_limit,
        'limit', v_source_build_limit,
        'refresh_reason', v_reason,
        'reason', v_reason
      )
    );

    v_job_id_text := NULLIF(BTRIM(COALESCE(v_refresh_result->>'job_id', '')), '');
    IF v_job_id_text IS NOT NULL THEN
      v_job_ids_jsonb := v_job_ids_jsonb || jsonb_build_array(v_job_id_text);
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_refresh_result->>'source_build_run_id', '')), '') IS NOT NULL THEN
      v_source_build_run_ids_jsonb := v_source_build_run_ids_jsonb || jsonb_build_array(v_refresh_result->>'source_build_run_id');
    END IF;

    IF UPPER(BTRIM(COALESCE(v_refresh_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
      v_delta_queued_count := v_delta_queued_count + 1;
    ELSE
      v_legacy_queued_count := v_legacy_queued_count + 1;
    END IF;

    IF LOWER(BTRIM(COALESCE(v_refresh_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_reused_count := v_reused_count + 1;
    ELSE
      v_queued_count := v_queued_count + 1;
    END IF;

    IF NOT (v_candidate_id = ANY(COALESCE(v_enqueued_candidate_ids, ARRAY[]::uuid[]))) THEN
      v_enqueued_candidate_ids := array_append(v_enqueued_candidate_ids, v_candidate_id);
    END IF;
  END LOOP;

  v_enqueued_candidate_count := COALESCE(array_length(v_enqueued_candidate_ids, 1), 0);

  SELECT count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY'))::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer,
         count(*) FILTER (WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) NOT IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'SOURCE_EMPTY', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR', 'SOURCE_BUILD_ERROR'))::integer
  INTO v_previous_ready,
       v_previous_failed,
       v_previous_pending
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = ANY(COALESCE(v_enqueued_candidate_ids, ARRAY[]::uuid[]));

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET scope_pending_count = GREATEST(0, COALESCE(session_update.scope_pending_count, 0) + COALESCE(v_enqueued_candidate_count, 0) - COALESCE(v_previous_pending, 0)),
      scope_ready_count = GREATEST(0, COALESCE(session_update.scope_ready_count, 0) - COALESCE(v_previous_ready, 0)),
      scope_failed_count = GREATEST(0, COALESCE(session_update.scope_failed_count, 0) - COALESCE(v_previous_failed, 0)),
      progress_state = CASE WHEN COALESCE(v_legacy_queued_count, 0) + COALESCE(v_delta_queued_count, 0) > 0 THEN 'REFRESHING_CANDIDATES' ELSE session_update.progress_state END,
      progress_json = COALESCE(session_update.progress_json, '{}'::jsonb) || jsonb_build_object(
        'phase', 'SOURCE_BUILDING',
        'status_text', 'Preparing payment source rows.',
        'last_source_build_enqueue_count', COALESCE(v_legacy_queued_count, 0),
        'last_delta_enqueue_count', COALESCE(v_delta_queued_count, 0),
        'last_clone_skipped_ready_count', COALESCE(v_clone_skipped_ready_count, 0),
        'last_clone_skipped_pending_count', COALESCE(v_clone_skipped_pending_count, 0),
        'last_clone_skip_list_count', COALESCE(v_clone_skip_list_count, 0),
        'last_clone_rebase_queued', COALESCE(v_clone_rebase_queued, false),
        'last_source_build_queued_count', COALESCE(v_queued_count, 0),
        'last_source_build_reused_count', COALESCE(v_reused_count, 0),
        'last_source_build_enqueue_at_utc', v_now::text,
        'last_source_build_limit', v_source_build_limit,
        'next_recommended_action', 'BUILD_SOURCE_CHUNK'
      ),
      progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'reason', v_reason,
    'queued_count', COALESCE(v_queued_count, 0),
    'reused_count', COALESCE(v_reused_count, 0),
    'candidate_count', COALESCE(v_requested_count, 0),
    'legacy_queued_count', COALESCE(v_legacy_queued_count, 0),
    'delta_queued_count', COALESCE(v_delta_queued_count, 0),
    'clone_skipped_ready_count', COALESCE(v_clone_skipped_ready_count, 0),
    'clone_skipped_pending_count', COALESCE(v_clone_skipped_pending_count, 0),
    'clone_skip_list_count', COALESCE(v_clone_skip_list_count, 0),
    'clone_rebase_queued', COALESCE(v_clone_rebase_queued, false),
    'enqueued_candidate_count', COALESCE(v_enqueued_candidate_count, 0),
    'job_ids', COALESCE(v_job_ids_jsonb, '[]'::jsonb),
    'source_build_run_ids', COALESCE(v_source_build_run_ids_jsonb, '[]'::jsonb),
    'session_recompute_job_ids', COALESCE(v_job_ids_jsonb, '[]'::jsonb),
    'requires_new_session', false,
    'source_session_discard_required', false,
    'source_build_required', COALESCE(v_legacy_queued_count, 0) > 0,
    'line_work_required', COALESCE(v_legacy_queued_count, 0) > 0,
    'clone_rebase_deferred', COALESCE(v_clone_skipped_pending_count, 0) > 0,
    'first_stage_job_type', CASE
      WHEN COALESCE(v_legacy_queued_count, 0) > 0 THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      WHEN COALESCE(v_delta_queued_count, 0) > 0 THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
      WHEN COALESCE(v_clone_skipped_pending_count, 0) > 0 THEN 'WORKBENCH_SESSION_CLONE_REBASE'
      ELSE NULL::text
    END,
    'source_build_limit', v_source_build_limit,
    'force_refresh', COALESCE(v_force_refresh, false)
  );
END;
$function$;

-- pay_workbench_enqueue_candidate_refresh(uuid,uuid,text,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_session_id uuid := NULL::uuid;
  v_session_id_text text := NULL::text;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_actor_user_id uuid := p_actor_user_id;
  v_live_change_seq bigint := 0;
  v_payload_source_change_seq bigint := NULL::bigint;
  v_source_change_seq bigint := 0;
  v_job_type text := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  v_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_pay_channel_scope text := 'ALL';
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_queue_identity_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_queue_identity_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_source_build_run_id_text text := NULL::text;
  v_source_build_run_id uuid := NULL::uuid;
  v_source_build_hash text := NULL::text;
  v_source_build_seed_text text := NULL::text;
  v_initial_cursor_json jsonb := '{}'::jsonb;
  v_cursor_token text := 'none';
  v_session_signature_token text := 'none';
  v_stage_limit integer := 100;
  v_dedupe_key text;
  v_job_id uuid;
  v_job_status text;
  v_job_was_inserted boolean := false;
  v_insert_row_count integer := 0;
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), 'WORKBENCH_CANDIDATE_SOURCE_BUILD');
  v_payload_out_json jsonb := '{}'::jsonb;
  v_classifier_result jsonb := '{}'::jsonb;
  v_force_legacy boolean := false;
  v_force_broad_legacy boolean := false;
  v_resolved_job_type text := NULL::text;
  v_projection_run_id uuid := NULL::uuid;
  v_projection_run_id_text text := NULL::text;
  v_projection_mode text := 'LEGACY';
  v_projection_class text := 'UNKNOWN';
  v_resolved_mode text := 'LEGACY';
  v_no_job_reason text := NULL::text;
  v_delta_jobs_superseded integer := 0;
  v_delta_ids_hash text := NULL::text;
  v_delta_coalescing_key text := NULL::text;
  v_delta_coalescing_hash text := NULL::text;
  v_delta_active_running_job_id uuid := NULL::uuid;
  v_existing_delta_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_existing_delta_source_change_seq bigint := 0;
  v_existing_delta_event_count integer := 0;
  v_merged_delta_event_count integer := 1;
  v_existing_delta_projection_run_id_text text := NULL::text;
  v_delta_merge_reused_existing boolean := false;
  v_payload_shadow_compare_required boolean := false;
  v_payload_shadow_compare_enforced boolean := false;
  v_rotation_scope_json jsonb := '{}'::jsonb;
  v_early_preflight_result jsonb := '{}'::jsonb;
  v_early_preflight_action text := 'PROCEED';
  v_early_preflight_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_early_preflight_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_shadow_compare_required boolean := false;
  v_shadow_compare_enforced boolean := false;
  v_bounded_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_scope_change_tx_token uuid := NULL::uuid;
  v_scope_invalidation_result jsonb := '{}'::jsonb;
  v_scope_state_precedes_job boolean := false;
  v_payload_scope_change_generation bigint := NULL::bigint;
  v_finalized_scope_tx_state text := NULL::text;
  v_finalized_scope_tx_generation bigint := NULL::bigint;
  v_live_scope_change_generation bigint := 0;
  v_registry_dirty_generation bigint := NULL::bigint;
  v_registry_source_change_seq_before bigint := 0;
  v_registry_source_change_seq_after bigint := 0;
  v_registry_sequence_synchronised boolean := false;
  v_scope_state_generation_match_count integer := 0;
  v_stale_preinvalidated_absorb_only boolean := false;
  v_requested_source_build_run_id uuid := NULL::uuid;
  v_authority_fingerprint_text text := NULL::text;
  v_authority_fingerprint text := NULL::text;
  v_owner_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_owner_root_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_owner_active_job_id uuid := NULL::uuid;
  v_owner_refresh_scope_kind text := NULL::text;
  v_owner_pay_channel_scope text := NULL::text;
  v_owner_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_owner_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_owner_covers_request boolean := false;
  v_owner_resolution text := 'NO_CURRENT_OWNER';
  v_owner_reasons_json jsonb := '[]'::jsonb;
  v_owner_trigger_sources_json jsonb := '[]'::jsonb;
  v_owner_provenance_json jsonb := '{}'::jsonb;
  v_owner_request_count bigint := 0;
  v_owner_scope_status text := NULL::text;
  v_reversion_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_reversion_state public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_reversion_attestation jsonb := '{}'::jsonb;
  v_reversion_source_count integer := 0;
  v_reversion_state_exact boolean := false;
  v_semantic_ready_publication_enabled boolean := false;
  v_source_publication_identity_enforced boolean := false;
  v_source_publication_baseline_required boolean := false;
  v_required_physical_publication_contract_version smallint := 0;
  v_authority_fingerprint_version smallint := 2;
  v_physical_currentness jsonb := '{}'::jsonb;
  v_candidate_currentness jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'snapshot_run_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  PERFORM 1
  FROM public.banking_pay_snapshot_runs AS snapshot_run
  WHERE snapshot_run.id = p_snapshot_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found', p_snapshot_run_id;
  END IF;

  PERFORM 1
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidates row % not found', p_candidate_id;
  END IF;

  SELECT COALESCE(
           settings_row.banking_pay_workbench_semantic_ready_publication_v3_enabled,
           false
         ),
         COALESCE(
           settings_row.banking_pay_source_publication_identity_enforce_v1_enabled,
           false
         )
  INTO v_semantic_ready_publication_enabled,
       v_source_publication_identity_enforced
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1;

  v_source_publication_baseline_required :=
    v_source_publication_identity_enforced
    OR lower(BTRIM(COALESCE(
      v_payload_json->>'source_publication_baseline_required',
      v_payload_json#>>'{source_publication,baseline_required}',
      'false'
    ))) IN ('true','t','1','yes','y','on');
  v_required_physical_publication_contract_version :=
    CASE WHEN v_source_publication_baseline_required THEN 1 ELSE 0 END;
  -- Fingerprint V3 distinguishes the semantic publication contract from the
  -- legacy structural owner even while physical-publication enforcement is
  -- still being rolled out.  The physical contract remains an independent
  -- 0/1 capability inside V3, so enabling semantic V3 does not silently make
  -- legacy Drafts fast-reversion eligible.
  v_authority_fingerprint_version := CASE
    WHEN v_semantic_ready_publication_enabled
      OR v_source_publication_baseline_required THEN 3
    ELSE 2
  END;

  -- One candidate may be requested through several independent refresh routes
  -- in the same lifecycle. Elect/reuse its economic owner under the common
  -- candidate serial authority before taking any session or scope row lock.
  -- This is re-entrant for callers which already own the transaction lock.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(p_candidate_id),
      24062027
    )
  );

  v_session_id_text := NULLIF(BTRIM(COALESCE(
    v_payload_json->>'session_id',
    v_payload_json->>'source_session_id',
    v_payload_json->>'workbench_session_id',
    v_payload_json#>>'{workbench,session_id}',
    ''
  )), '');

  IF v_session_id_text IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'job_id', NULL::text,
      'job_type', NULL::text,
      'canonical_job_type', NULL::text,
      'snapshot_run_id', p_snapshot_run_id::text,
      'session_id', NULL::text,
      'candidate_id', p_candidate_id::text,
      'source_change_seq', 0,
      'source_build_required', true,
      'line_work_required', true,
      'delta_refresh_required', false,
      'full_snapshot_job', false,
      'no_op', true,
      'deferred', true,
      'requires_workbench_session', true,
      'reason', v_reason,
      'message', 'Banking Pay candidate refresh now requires a row-backed workbench session.'
    );
  END IF;

  IF v_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SESSION_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SESSION_ID_INVALID',
              'session_id', v_session_id_text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  v_session_id := v_session_id_text::uuid;

  SELECT COALESCE(array_agg(DISTINCT parsed_target_ids.timesheet_id_value ORDER BY parsed_target_ids.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_early_preflight_targeted_timesheet_ids
  FROM (
    SELECT NULLIF(BTRIM(targeted_values.value), '')::uuid AS timesheet_id_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,targeted_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,targeted_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS targeted_values(value)
    WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_target_ids;

  SELECT COALESCE(array_agg(DISTINCT parsed_linked_ids.timesheet_id_value ORDER BY parsed_linked_ids.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_early_preflight_linked_timesheet_ids
  FROM (
    SELECT NULLIF(BTRIM(linked_values.value), '')::uuid AS timesheet_id_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'array' THEN v_payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'linked_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,linked_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,linked_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS linked_values(value)
    WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_linked_ids;

  -- The hotkey is only advisory after the canonical session and scope
  -- authorities have been locked.  It must never create/reuse work for a
  -- candidate which has not first entered the session through the scope owner.
  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id=v_session_id
  FOR UPDATE;
  IF NOT FOUND OR UPPER(BTRIM(COALESCE(v_session_row.status,'')))<>'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not open',v_session_id;
  END IF;
  IF v_session_row.source_snapshot_run_id IS DISTINCT FROM p_snapshot_run_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SNAPSHOT_MISMATCH' USING ERRCODE='P0001';
  END IF;
  PERFORM 1 FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id=v_session_id AND scope_row.candidate_id=p_candidate_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %',p_candidate_id,v_session_id;
  END IF;

  IF COALESCE(array_length(v_early_preflight_targeted_timesheet_ids, 1), 0) > 0 THEN
    SELECT public.pay_workbench_authorise_delta_hotkey_preflight(
      p_session_id => v_session_id,
      p_candidate_id => p_candidate_id,
      p_targeted_timesheet_ids => v_early_preflight_targeted_timesheet_ids,
      p_linked_timesheet_ids => v_early_preflight_linked_timesheet_ids,
      p_payload_json => v_payload_json || jsonb_build_object(
        'session_id', v_session_id::text,
        'source_session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'snapshot_run_id', p_snapshot_run_id::text,
        'source_snapshot_run_id', p_snapshot_run_id::text,
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'projection_mode', 'DELTA',
        'projection_class', CASE
          WHEN lower(BTRIM(COALESCE(v_payload_json->>'authorise_boundary_changed','false'))) IN ('true','t','1','yes','y','on')
            OR lower(BTRIM(COALESCE(v_payload_json->>'unauthorise_boundary_changed','false'))) IN ('true','t','1','yes','y','on')
            OR lower(BTRIM(COALESCE(v_payload_json->>'lifecycle_mutation_context',v_payload_json->>'mutation_context',''))) IN ('timesheet_authorise','authorise_timesheet','timesheet_unauthorise','unauthorise_timesheet')
          THEN 'TIMESHEET_LIFECYCLE' ELSE 'NORMAL_TIMESHEET' END,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ),
      p_reason => v_reason,
      p_actor_user_id => v_actor_user_id,
      p_source_change_seq => NULL::bigint
    ) INTO v_early_preflight_result;

    v_early_preflight_action := COALESCE(v_early_preflight_result->>'action', 'PROCEED');

    IF v_early_preflight_action IN ('REUSED_QUEUED_SAME_FAMILY_JOB', 'UPDATED_WAITING_AFTER_RUNNING_JOB') THEN
      RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok', true,
        'job_id', NULLIF(BTRIM(COALESCE(v_early_preflight_result->>'job_id', '')), ''),
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'snapshot_run_id', p_snapshot_run_id::text,
        'session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'source_change_seq', CASE WHEN COALESCE(v_early_preflight_result->>'latest_source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_early_preflight_result->>'latest_source_change_seq')::bigint ELSE NULL::bigint END,
        'dedupe_key', NULLIF(BTRIM(COALESCE(v_early_preflight_result->>'normalised_delta_family_key', '')), ''),
        'reason', v_reason,
        'refresh_scope_kind', 'TARGETED_TIMESHEETS',
        'targeted_timesheet_ids', COALESCE(v_early_preflight_result->'targeted_timesheet_ids', '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_early_preflight_result->'linked_timesheet_ids', '[]'::jsonb),
        'queue_identity_targeted_timesheet_ids', COALESCE(v_early_preflight_result->'queue_identity_targeted_timesheet_ids', v_early_preflight_result->'resolved_family_timesheet_ids', v_early_preflight_result->'targeted_timesheet_ids', '[]'::jsonb),
        'queue_identity_linked_timesheet_ids', COALESCE(v_early_preflight_result->'queue_identity_linked_timesheet_ids', '[]'::jsonb),
        'source_build_required', false,
        'line_work_required', false,
        'line_work_only', false,
        'delta_refresh_required', true,
        'scope_status', 'DELTA_REFRESH_PENDING',
        'projection_mode', 'DELTA',
        'projection_class', 'NORMAL_TIMESHEET',
        'full_snapshot_job', false,
        'reused', true,
        'early_preflight_action', v_early_preflight_action,
        'early_preflight_result', COALESCE(v_early_preflight_result, '{}'::jsonb),
        'early_preflight_returned_before_session_lock', true,
        'session_lock_skipped', true,
        'scope_lock_skipped', true,
        'classifier_work_skipped', true,
        'dirty_marking_skipped', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ));
    END IF;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = v_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', v_session_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not open', v_session_id;
  END IF;

  IF v_session_row.source_snapshot_run_id IS DISTINCT FROM p_snapshot_run_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SNAPSHOT_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SNAPSHOT_MISMATCH',
              'session_id', v_session_id::text,
              'payload_snapshot_run_id', p_snapshot_run_id::text,
              'session_snapshot_run_id', v_session_row.source_snapshot_run_id::text
            )::text;
  END IF;

  PERFORM 1
  FROM public.banking_pay_workbench_session_scope AS session_scope
  WHERE session_scope.session_id = v_session_id
    AND session_scope.candidate_id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, v_session_id;
  END IF;

  v_actor_user_id := COALESCE(v_actor_user_id, v_session_row.actor_user_id);

  SELECT COALESCE(change_counter.seq, 0),
         COALESCE(change_counter.scope_change_generation, 0)
  INTO v_live_change_seq,
       v_live_scope_change_generation
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text
  FOR UPDATE;

  IF COALESCE(v_payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json->>'source_change_seq')::bigint;
  ELSIF COALESCE(v_payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json->>'source_change_sequence')::bigint;
  ELSIF COALESCE(v_payload_json->>'latest_source_change_seq', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json->>'latest_source_change_seq')::bigint;
  ELSIF COALESCE(v_payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN
    v_payload_source_change_seq := (v_payload_json#>>'{source_build,source_change_seq}')::bigint;
  END IF;

  v_source_change_seq := GREATEST(COALESCE(v_payload_source_change_seq, 0), COALESCE(v_live_change_seq, 0));

  SELECT COALESCE(jsonb_agg(parsed_target_ids.timesheet_id_text ORDER BY parsed_target_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_values.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,targeted_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,targeted_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS targeted_values(value)
    WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_target_ids;

  SELECT COALESCE(jsonb_agg(parsed_linked_ids.timesheet_id_text ORDER BY parsed_linked_ids.timesheet_id_text), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'array' THEN v_payload_json->'linked_timesheet_ids'
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}'
        WHEN jsonb_typeof(v_payload_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'linked_timesheet_ids')
        WHEN jsonb_typeof(v_payload_json#>'{source_build,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{source_build,linked_timesheet_ids}')
        WHEN jsonb_typeof(v_payload_json#>'{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_payload_json#>>'{preview_decisions_json,linked_timesheet_ids}')
        ELSE '[]'::jsonb
      END
    ) AS linked_values(value)
    WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_linked_ids;

  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(
    v_payload_json->>'refresh_scope_kind',
    v_payload_json#>>'{source_build,refresh_scope_kind}',
    v_payload_json#>>'{preview_decisions_json,refresh_scope_kind}',
    ''
  ))), '');

  IF v_refresh_scope_kind IS NULL OR v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := CASE
      WHEN jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
        OR jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) > 0
      THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END;
  END IF;


  v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
  v_queue_identity_linked_timesheet_ids_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);

  IF v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
     AND to_regprocedure('public._pay_workbench_normalise_timesheet_rotation_scope_payload(uuid[],uuid[])') IS NOT NULL THEN
    SELECT public._pay_workbench_normalise_timesheet_rotation_scope_payload(
      COALESCE((
        SELECT array_agg(DISTINCT targeted_value.value::uuid ORDER BY targeted_value.value::uuid)
        FROM jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) AS targeted_value(value)
        WHERE targeted_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), ARRAY[]::uuid[]),
      COALESCE((
        SELECT array_agg(DISTINCT linked_value.value::uuid ORDER BY linked_value.value::uuid)
        FROM jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) AS linked_value(value)
        WHERE linked_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), ARRAY[]::uuid[])
    )
    INTO v_rotation_scope_json;

    v_payload_json := public._pay_workbench_merge_targeted_scope_payload(
      v_payload_json,
      jsonb_build_object(
        'targeted_timesheet_ids_requested', COALESCE(v_rotation_scope_json->'requested_targeted_timesheet_ids', v_targeted_timesheet_ids_json),
        'linked_timesheet_ids_requested', COALESCE(v_rotation_scope_json->'requested_linked_timesheet_ids', v_linked_timesheet_ids_json),
        'requested_timesheet_ids', COALESCE(v_rotation_scope_json->'requested_timesheet_ids', v_targeted_timesheet_ids_json),
        'family_timesheet_ids', COALESCE(v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json),
        'targeted_timesheet_ids', COALESCE(v_rotation_scope_json->'targeted_timesheet_ids', v_targeted_timesheet_ids_json),
        'linked_timesheet_ids', COALESCE(v_rotation_scope_json->'linked_timesheet_ids', v_linked_timesheet_ids_json, '[]'::jsonb),
        'queue_identity_targeted_timesheet_ids', COALESCE(v_rotation_scope_json->'queue_identity_targeted_timesheet_ids', v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json),
        'queue_identity_linked_timesheet_ids', COALESCE(v_rotation_scope_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb),
        'queue_identity_timesheet_ids', COALESCE(v_rotation_scope_json->'queue_identity_timesheet_ids', v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json),
        'rotation_family_scope_for_queue_identity', true,
        'queue_identity_preserves_targeted_linked_semantics', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );
    v_targeted_timesheet_ids_json := COALESCE(v_rotation_scope_json->'targeted_timesheet_ids', v_targeted_timesheet_ids_json);
    v_linked_timesheet_ids_json := COALESCE(v_rotation_scope_json->'linked_timesheet_ids', v_linked_timesheet_ids_json, '[]'::jsonb);
    v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_rotation_scope_json->'queue_identity_targeted_timesheet_ids', v_rotation_scope_json->'family_timesheet_ids', v_targeted_timesheet_ids_json, '[]'::jsonb);
    v_queue_identity_linked_timesheet_ids_json := COALESCE(v_rotation_scope_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb);
  END IF;

  v_pay_channel_scope := NULLIF(UPPER(BTRIM(COALESCE(
    v_payload_json->>'pay_channel_scope',
    v_payload_json#>>'{source_build,pay_channel_scope}',
    v_payload_json#>>'{preview_decisions_json,pay_channel_scope}',
    v_session_row.filters_json->>'pay_channel_scope',
    v_session_row.filters_json#>>'{filters,pay_channel_scope}',
    'ALL'
  ))), '');

  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  v_force_legacy := lower(BTRIM(COALESCE(v_payload_json->>'force_legacy', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_force_broad_legacy := lower(BTRIM(COALESCE(v_payload_json->>'force_broad_legacy', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF jsonb_typeof(v_payload_json->'classifier_result') = 'object' THEN
    v_classifier_result := v_payload_json->'classifier_result';
  ELSIF v_payload_json ? 'fast_path_allowed' OR v_payload_json ? 'resolved_job_type' THEN
    v_classifier_result := v_payload_json;
  ELSIF to_regprocedure('public.pay_workbench_delta_refresh_classify_v1(uuid,uuid,jsonb)') IS NOT NULL THEN
    v_classifier_result := public.pay_workbench_delta_refresh_classify_v1(
      v_session_id,
      p_candidate_id,
      v_payload_json
      || jsonb_build_object(
        'session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'pay_channel_scope', v_pay_channel_scope,
        'force_legacy', v_force_legacy,
        'force_broad_legacy', v_force_broad_legacy
      )
    );
  ELSE
    v_classifier_result := jsonb_build_object(
      'ok', true,
      'fast_path_allowed', false,
      'resolved_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'projection_mode', 'LEGACY',
      'projection_class', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(v_payload_json->>'projection_class', ''))), ''), 'UNKNOWN_TRIGGER'),
      'scope_status', 'SOURCE_BUILD_PENDING',
      'fallback_required', true,
      'fallback_reason', 'DELTA_CLASSIFIER_NOT_INSTALLED'
    );
  END IF;

  v_classifier_result := COALESCE(v_classifier_result, '{}'::jsonb)
    - 'old_row_json'
    - 'new_row_json'
    - 'old_row'
    - 'new_row'
    - 'source_row_json'
    - 'work_payload_json'
    - 'result_row_json'
    - 'preview_row_json'
    - 'row_payload_json'
    - 'line_payload_json'
    - 'projection_rows'
    - 'projected_rows';

  v_resolved_mode := UPPER(BTRIM(COALESCE(v_classifier_result->>'resolved_mode', v_classifier_result->>'routing_decision', v_classifier_result->>'projection_mode', 'LEGACY')));
  IF v_resolved_mode NOT IN ('DELTA', 'PATCH_ONLY', 'CLONE_REBASE', 'LEGACY', 'BLOCKED') THEN
    v_resolved_mode := 'LEGACY';
  END IF;

  v_resolved_job_type := UPPER(BTRIM(COALESCE(v_classifier_result->>'resolved_job_type', CASE WHEN v_resolved_mode = 'DELTA' THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH' WHEN v_resolved_mode = 'LEGACY' THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD' ELSE 'NOOP' END)));
  v_projection_mode := UPPER(BTRIM(COALESCE(v_classifier_result->>'projection_mode', v_payload_json->>'projection_mode', 'LEGACY')));
  v_projection_class := UPPER(BTRIM(COALESCE(v_classifier_result->>'projection_class', v_payload_json->>'projection_class', 'UNKNOWN')));

  IF jsonb_typeof(v_classifier_result->'targeted_timesheet_ids') = 'array' THEN
    v_targeted_timesheet_ids_json := v_classifier_result->'targeted_timesheet_ids';
  END IF;
  IF jsonb_typeof(v_classifier_result->'linked_timesheet_ids') = 'array' THEN
    v_linked_timesheet_ids_json := v_classifier_result->'linked_timesheet_ids';
  END IF;

  IF jsonb_typeof(v_payload_json->'queue_identity_targeted_timesheet_ids') = 'array' THEN
    v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_payload_json->'queue_identity_targeted_timesheet_ids', v_queue_identity_targeted_timesheet_ids_json, '[]'::jsonb);
  ELSIF jsonb_array_length(COALESCE(v_queue_identity_targeted_timesheet_ids_json, '[]'::jsonb)) = 0 THEN
    v_queue_identity_targeted_timesheet_ids_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);
  END IF;

  IF jsonb_typeof(v_payload_json->'queue_identity_linked_timesheet_ids') = 'array' THEN
    v_queue_identity_linked_timesheet_ids_json := COALESCE(v_payload_json->'queue_identity_linked_timesheet_ids', '[]'::jsonb);
  ELSIF jsonb_array_length(COALESCE(v_queue_identity_linked_timesheet_ids_json, '[]'::jsonb)) = 0 THEN
    v_queue_identity_linked_timesheet_ids_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);
  END IF;

  IF v_force_legacy IS TRUE OR v_force_broad_legacy IS TRUE THEN
    v_resolved_mode := 'LEGACY';
    v_resolved_job_type := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid),ARRAY[]::uuid[])
  INTO v_bounded_timesheet_ids
  FROM jsonb_array_elements_text(
    COALESCE(v_targeted_timesheet_ids_json,'[]'::jsonb)
    || COALESCE(v_linked_timesheet_ids_json,'[]'::jsonb)
  ) value
  WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  IF COALESCE(v_payload_json->>'scope_change_tx_token','')
     ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_scope_change_tx_token:=(v_payload_json->>'scope_change_tx_token')::uuid;
  END IF;
  v_scope_state_precedes_job := lower(BTRIM(COALESCE(
    v_payload_json->>'bounded_scope_state_precedes_job','false'
  ))) IN ('true','t','1','yes','y','on');
  IF COALESCE(v_payload_json->>'scope_change_generation','') ~ '^\d+$' THEN
    v_payload_scope_change_generation :=
      (v_payload_json->>'scope_change_generation')::bigint;
  END IF;

  -- Elect an already-current economic owner before scope invalidation.  A
  -- reason such as USER_REQUESTED_FULL_REFRESH or force_legacy is provenance,
  -- not proof that current certified output is stale.  This early fence is
  -- what prevents a same-sequence refresh from first destroying the evidence
  -- needed by COMPLETE_CURRENT_AUTHORITY.
  IF NOT v_scope_state_precedes_job THEN
    SELECT registry.dirty_generation,
           registry.current_source_change_seq
    INTO v_registry_dirty_generation,
         v_registry_source_change_seq_before
    FROM private.banking_pay_workbench_candidate_scope_registry AS registry
    WHERE registry.candidate_id=p_candidate_id
    FOR UPDATE;
  END IF;

  v_session_signature_token:=md5(COALESCE(v_session_row.session_signature,''));

  v_authority_fingerprint_text := concat_ws('|',
    CASE WHEN v_authority_fingerprint_version=3
      THEN 'WORKBENCH_SOURCE_OWNER_V3' ELSE 'WORKBENCH_SOURCE_OWNER_V2' END,
    v_session_id::text,
    COALESCE(v_session_row.version,0)::text,
    v_session_row.source_snapshot_run_id::text,
    v_session_signature_token,
    p_candidate_id::text,
    COALESCE(v_source_change_seq,0)::text,
    COALESCE(v_registry_dirty_generation,v_live_scope_change_generation,0)::text,
    UPPER(BTRIM(COALESCE(v_pay_channel_scope,'ALL'))),
    'FULL_CANDIDATE',
    CASE WHEN v_authority_fingerprint_version=3
      THEN 'READY_TO_PAY_SEMANTIC_V2' ELSE NULL END,
    CASE WHEN v_authority_fingerprint_version=3
      THEN v_required_physical_publication_contract_version::text ELSE NULL END
  );
  v_authority_fingerprint := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(v_authority_fingerprint_text,'UTF8'),'sha256'),
    'hex'
  );

  SELECT build_row.*
  INTO v_owner_build
  FROM private.banking_pay_workbench_economic_builds AS build_row
  JOIN public.banking_pay_workbench_session_scope AS current_scope
    ON current_scope.session_id=build_row.session_id
   AND current_scope.candidate_id=build_row.candidate_id
  JOIN public.banking_pay_workbench_session_candidate_state AS current_state
    ON current_state.session_id=build_row.session_id
   AND current_state.candidate_id=build_row.candidate_id
  WHERE build_row.candidate_id=p_candidate_id
    AND build_row.session_id=v_session_id
    AND build_row.session_version=COALESCE(v_session_row.version,0)
    AND build_row.source_snapshot_run_id=v_session_row.source_snapshot_run_id
    AND build_row.source_change_seq=COALESCE(v_source_change_seq,0)
    AND build_row.captured_candidate_generation=
          COALESCE(v_registry_dirty_generation,v_live_scope_change_generation,0)
    AND UPPER(BTRIM(COALESCE(build_row.status,'')))='COMPLETE'
    AND UPPER(BTRIM(COALESCE(build_row.private_stage,'')))='COMPLETE'
    AND current_scope.dirty IS FALSE
    AND current_scope.pending_job_id IS NULL
    AND current_scope.certified_preview_publication_required IS TRUE
    AND current_scope.certified_preview_publication_parity_ok IS TRUE
    AND current_scope.certified_preview_publication_session_version=build_row.session_version
    AND current_scope.certified_preview_publication_source_change_seq=build_row.source_change_seq
    AND current_scope.certified_preview_publication_source_build_run_id=build_row.source_build_run_id
    AND (
      NOT v_source_publication_baseline_required
      OR (
        current_scope.certified_preview_publication_source_publication_id IS NOT NULL
        AND current_scope.certified_preview_publication_attestation_json->>'source_publication_id'
              =current_scope.certified_preview_publication_source_publication_id::text
      )
    )
    AND (
      NOT v_semantic_ready_publication_enabled
      OR (
        current_scope.certified_preview_publication_attestation_json->>'attestation_version'
              ='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
        AND current_scope.certified_preview_publication_attestation_json->>'contract_version'='3'
        AND current_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
              ='READY_TO_PAY_SEMANTIC_V2'
        AND COALESCE(
          (current_scope.certified_preview_publication_attestation_json->>'semantic_ready')::boolean,
          false
        )
        AND COALESCE(
          (current_scope.certified_preview_publication_attestation_json->>'parity_complete')::boolean,
          false
        )
      )
    )
    AND UPPER(BTRIM(COALESCE(current_state.status,'')))='READY'
    AND current_state.pending_job_id IS NULL
    AND current_state.session_version=build_row.session_version
    AND current_state.source_change_seq=build_row.source_change_seq
  ORDER BY build_row.completed_at_utc DESC NULLS LAST,build_row.id DESC
  LIMIT 1
  FOR UPDATE OF build_row,current_scope,current_state;

  IF FOUND THEN
    SELECT source_job.*
    INTO v_owner_root_job
    FROM public.banking_pay_workbench_jobs AS source_job
    WHERE source_job.economic_build_id=v_owner_build.id
      AND UPPER(BTRIM(COALESCE(source_job.job_type,'')))='WORKBENCH_CANDIDATE_SOURCE_BUILD'
      AND COALESCE(
        source_job.payload_json->>'source_build_run_id',
        source_job.payload_json#>>'{source_build,source_build_run_id}',
        ''
      )=v_owner_build.source_build_run_id::text
    ORDER BY source_job.created_at_utc,source_job.id
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      v_owner_pay_channel_scope:=UPPER(BTRIM(COALESCE(
        v_owner_root_job.payload_json->>'pay_channel_scope',
        v_owner_root_job.payload_json#>>'{source_build,pay_channel_scope}',
        'ALL'
      )));
      IF v_owner_pay_channel_scope=UPPER(BTRIM(COALESCE(v_pay_channel_scope,'ALL'))) THEN
        EXECUTE 'SELECT private.pay_workbench_candidate_physical_currentness_page_v1($1,$2,$3,$4)'
          INTO v_physical_currentness
          USING v_session_id,ARRAY[p_candidate_id],'TERMINAL_CURRENT',
            jsonb_build_object('contract_version',1,'allow_active_owner',false);
        v_candidate_currentness:=COALESCE(v_physical_currentness->'candidate_results'->0,'{}'::jsonb);
        IF COALESCE((v_candidate_currentness->>'terminal_current')::boolean,false) IS NOT TRUE THEN
          v_owner_build:=NULL;
          v_owner_root_job:=NULL;
        ELSE
        UPDATE public.banking_pay_workbench_jobs AS owner_job
        SET payload_json=jsonb_strip_nulls(
              COALESCE(owner_job.payload_json,'{}'::jsonb)
              || jsonb_build_object('reason_latest',v_reason)
            ),
            updated_at_utc=v_now
        WHERE owner_job.id=v_owner_root_job.id;

        RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok',true,
        'job_id',v_owner_root_job.id::text,
        'job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'canonical_job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'session_id',v_session_id::text,
        'candidate_id',p_candidate_id::text,
        'session_version',COALESCE(v_session_row.version,0),
        'source_change_seq',COALESCE(v_source_change_seq,0),
        'registry_source_change_seq',COALESCE(v_registry_source_change_seq_before,v_source_change_seq,0),
        'source_build_run_id',v_owner_build.source_build_run_id::text,
        'source_publication_id',(
          SELECT current_scope.certified_preview_publication_source_publication_id::text
          FROM public.banking_pay_workbench_session_scope AS current_scope
          WHERE current_scope.session_id=v_session_id
            AND current_scope.candidate_id=p_candidate_id
        ),
        'authority_fingerprint',COALESCE(v_owner_build.authority_fingerprint,v_authority_fingerprint),
        'authority_fingerprint_version',COALESCE(v_owner_build.authority_fingerprint_version,v_authority_fingerprint_version),
        'required_physical_publication_contract_version',v_required_physical_publication_contract_version,
        'owner_resolution','COMPLETE_CURRENT_AUTHORITY',
        'owner_build_id',v_owner_build.id::text,
        'owner_root_job_id',v_owner_root_job.id::text,
        'owner_source_build_run_id',v_owner_build.source_build_run_id::text,
        'requested_coverage','FULL_CANDIDATE',
        'owner_coverage','FULL_CANDIDATE',
        'scope_status','MATERIALISED',
        'source_build_required',false,
        'delta_refresh_required',false,
        'coalesced',true,
        'reused',true,
        'new_owner_created',false,
        'no_op',true,
        'pre_invalidation_owner_election',true,
        'diagnostic_provenance_merged',true,
        'reason',v_reason,
        'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
        ));
        END IF;
      END IF;
    END IF;
  END IF;

  v_owner_build:=NULL;
  v_owner_root_job:=NULL;
  v_owner_active_job_id:=NULL::uuid;
  SELECT build_row.*
  INTO v_owner_build
  FROM private.banking_pay_workbench_economic_builds AS build_row
  WHERE build_row.candidate_id=p_candidate_id
    AND build_row.session_id=v_session_id
    AND build_row.session_version=COALESCE(v_session_row.version,0)
    AND build_row.source_snapshot_run_id=v_session_row.source_snapshot_run_id
    AND build_row.source_change_seq=COALESCE(v_source_change_seq,0)
    AND build_row.captured_candidate_generation=
          COALESCE(v_registry_dirty_generation,v_live_scope_change_generation,0)
    AND build_row.authority_fingerprint_version=v_authority_fingerprint_version
    AND build_row.authority_fingerprint=v_authority_fingerprint
    AND UPPER(BTRIM(COALESCE(build_row.status,''))) IN (
      'COLLECTING','READY_FOR_RECONCILIATION','RECONCILING','RECONCILED',
      'PUBLISHING','BLOCKED_UNVALIDATED_RECONCILIATION_SCALE'
    )
    AND EXISTS (
      SELECT 1 FROM public.banking_pay_workbench_jobs AS active_job
      WHERE active_job.economic_build_id=build_row.id
        AND active_job.status IN ('QUEUED','RUNNING')
    )
  ORDER BY build_row.created_at_utc DESC,build_row.id DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    SELECT source_job.*
    INTO v_owner_root_job
    FROM public.banking_pay_workbench_jobs AS source_job
    WHERE source_job.economic_build_id=v_owner_build.id
      AND UPPER(BTRIM(COALESCE(source_job.job_type,'')))='WORKBENCH_CANDIDATE_SOURCE_BUILD'
    ORDER BY source_job.created_at_utc,source_job.id
    LIMIT 1
    FOR UPDATE;
    SELECT active_job.id
    INTO v_owner_active_job_id
    FROM public.banking_pay_workbench_jobs AS active_job
    WHERE active_job.economic_build_id=v_owner_build.id
      AND active_job.status IN ('QUEUED','RUNNING')
    ORDER BY CASE WHEN active_job.status='RUNNING' THEN 0 ELSE 1 END,
             active_job.run_at_utc,active_job.created_at_utc,active_job.id
    LIMIT 1;

    IF v_owner_root_job.id IS NOT NULL AND v_owner_active_job_id IS NOT NULL THEN
      RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok',true,
        'job_id',v_owner_root_job.id::text,
        'job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'canonical_job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'session_id',v_session_id::text,
        'candidate_id',p_candidate_id::text,
        'session_version',COALESCE(v_session_row.version,0),
        'source_change_seq',COALESCE(v_source_change_seq,0),
        'source_build_run_id',v_owner_build.source_build_run_id::text,
        'authority_fingerprint',v_authority_fingerprint,
        'authority_fingerprint_version',v_authority_fingerprint_version,
        'required_physical_publication_contract_version',v_required_physical_publication_contract_version,
        'owner_resolution','ACTIVE_CURRENT_OWNER_COVERS_REQUEST',
        'owner_build_id',v_owner_build.id::text,
        'owner_root_job_id',v_owner_root_job.id::text,
        'owner_active_job_id',v_owner_active_job_id::text,
        'owner_source_build_run_id',v_owner_build.source_build_run_id::text,
        'requested_coverage','FULL_CANDIDATE',
        'owner_coverage','FULL_CANDIDATE',
        'scope_status','SOURCE_BUILD_PENDING',
        'source_build_required',true,
        'delta_refresh_required',false,
        'coalesced',true,
        'reused',true,
        'new_owner_created',false,
        'no_op',false,
        'pre_invalidation_owner_election',true,
        'reason',v_reason,
        'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
      ));
    END IF;
  END IF;

  v_owner_build:=NULL;
  v_owner_root_job:=NULL;
  v_owner_active_job_id:=NULL::uuid;

  IF v_scope_state_precedes_job THEN
    SELECT registry.dirty_generation,
           registry.current_source_change_seq
    INTO v_registry_dirty_generation,
         v_registry_source_change_seq_before
    FROM private.banking_pay_workbench_candidate_scope_registry AS registry
    WHERE registry.candidate_id=p_candidate_id
    FOR UPDATE;

    -- A delayed pre-invalidated job may be older than a newer authority which
    -- has already adopted the live sequence and generation.  Such a request
    -- may only be absorbed by an active/current owner below; it must never
    -- create work from its stale transaction proof.
    v_stale_preinvalidated_absorb_only :=
      v_payload_scope_change_generation IS NOT NULL
      AND v_payload_scope_change_generation < COALESCE(v_live_scope_change_generation,0)
      AND COALESCE(v_registry_dirty_generation,0)=COALESCE(v_live_scope_change_generation,0)
      AND COALESCE(v_registry_source_change_seq_before,0)=COALESCE(v_source_change_seq,0);

    IF v_stale_preinvalidated_absorb_only THEN
      v_registry_source_change_seq_after:=v_registry_source_change_seq_before;
      v_scope_invalidation_result:=jsonb_build_object(
        'ok',true,
        'stale_preinvalidated_absorb_only',true,
        'payload_scope_change_generation',v_payload_scope_change_generation,
        'current_scope_change_generation',v_live_scope_change_generation,
        'accepted_source_change_seq',v_source_change_seq,
        'reason',COALESCE(v_reason,'CANDIDATE_REFRESH_ENQUEUED')
      );
    ELSE
      SELECT scope_tx.state,
             scope_tx.allocated_generation
      INTO v_finalized_scope_tx_state,
           v_finalized_scope_tx_generation
      FROM public.banking_pay_scope_change_transactions AS scope_tx
      WHERE scope_tx.tx_token=v_scope_change_tx_token
      FOR UPDATE;

      SELECT count(*)::integer
      INTO v_scope_state_generation_match_count
      FROM unnest(v_bounded_timesheet_ids) AS requested(timesheet_id)
       JOIN private.banking_pay_workbench_timesheet_scope_state AS scope_state
        ON scope_state.timesheet_id=requested.timesheet_id
       AND scope_state.candidate_id=p_candidate_id
       AND scope_state.dirty_generation=v_payload_scope_change_generation;

      IF v_scope_change_tx_token IS NULL
         OR v_payload_scope_change_generation IS NULL
         OR v_payload_scope_change_generation < 1
         OR v_finalized_scope_tx_state IS DISTINCT FROM 'FINALIZED'
         OR v_finalized_scope_tx_generation IS DISTINCT FROM
            v_payload_scope_change_generation
         OR v_live_scope_change_generation IS DISTINCT FROM
            v_payload_scope_change_generation
         OR COALESCE(v_registry_dirty_generation,0) IS DISTINCT FROM
            v_payload_scope_change_generation
         OR v_scope_state_generation_match_count IS DISTINCT FROM
            cardinality(v_bounded_timesheet_ids) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_PRECEDING_SCOPE_INVALIDATION_UNPROVED'
          USING ERRCODE='22023', DETAIL=jsonb_build_object(
            'code','PAY_WORKBENCH_PRECEDING_SCOPE_INVALIDATION_UNPROVED',
            'candidate_id',p_candidate_id,
            'scope_change_tx_token',v_scope_change_tx_token,
            'payload_scope_change_generation',v_payload_scope_change_generation,
            'transaction_state',v_finalized_scope_tx_state,
            'transaction_generation',v_finalized_scope_tx_generation,
            'live_scope_change_generation',v_live_scope_change_generation,
            'registry_dirty_generation',v_registry_dirty_generation,
            'requested_timesheet_count',cardinality(v_bounded_timesheet_ids),
            'matched_scope_state_count',v_scope_state_generation_match_count
          )::text;
      END IF;

      UPDATE private.banking_pay_workbench_candidate_scope_registry AS registry
      SET current_source_change_seq=GREATEST(
            COALESCE(registry.current_source_change_seq,0),
            COALESCE(v_source_change_seq,0)
          ),
          updated_at_utc=CASE
            WHEN COALESCE(registry.current_source_change_seq,0)<COALESCE(v_source_change_seq,0)
              THEN clock_timestamp()
            ELSE registry.updated_at_utc
          END
      WHERE registry.candidate_id=p_candidate_id
        AND registry.dirty_generation=v_payload_scope_change_generation
      RETURNING registry.current_source_change_seq
      INTO v_registry_source_change_seq_after;

      IF NOT FOUND
         OR COALESCE(v_registry_source_change_seq_after,0)<COALESCE(v_source_change_seq,0) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_ACCEPTED_SOURCE_SEQUENCE_NOT_SYNCHRONISED'
          USING ERRCODE='40001', DETAIL=jsonb_build_object(
            'code','PAY_WORKBENCH_ACCEPTED_SOURCE_SEQUENCE_NOT_SYNCHRONISED',
            'candidate_id',p_candidate_id,
            'accepted_source_change_seq',v_source_change_seq,
            'registry_source_change_seq_before',v_registry_source_change_seq_before,
            'registry_source_change_seq_after',v_registry_source_change_seq_after,
            'scope_change_generation',v_payload_scope_change_generation
          )::text;
      END IF;
      v_registry_sequence_synchronised :=
        COALESCE(v_registry_source_change_seq_after,0)>
        COALESCE(v_registry_source_change_seq_before,0);

      v_scope_invalidation_result := jsonb_build_object(
        'ok',true,
        'already_finalized',true,
        'scope_change_tx_token',v_scope_change_tx_token,
        'scope_change_generation',v_finalized_scope_tx_generation,
        'candidate_count',1,
        'timesheet_count',cardinality(v_bounded_timesheet_ids),
        'accepted_source_change_seq',v_source_change_seq,
        'registry_source_change_seq_before',v_registry_source_change_seq_before,
        'registry_source_change_seq_after',v_registry_source_change_seq_after,
        'registry_sequence_synchronised',v_registry_sequence_synchronised,
        'reason',COALESCE(v_reason,'CANDIDATE_REFRESH_ENQUEUED')
      );
    END IF;
  ELSE
    v_scope_invalidation_result:=private.pay_workbench_scope_invalidate_v1(
      CASE WHEN cardinality(v_bounded_timesheet_ids)=0 THEN ARRAY[p_candidate_id]
        ELSE array_fill(p_candidate_id,ARRAY[cardinality(v_bounded_timesheet_ids)]) END,
      CASE WHEN cardinality(v_bounded_timesheet_ids)=0 THEN ARRAY[NULL::uuid]
        ELSE v_bounded_timesheet_ids END,
      COALESCE(v_reason,'CANDIDATE_REFRESH_ENQUEUED'),
      v_scope_change_tx_token,
      v_payload_json||jsonb_build_object(
        'skip_candidate_job_enqueue',true,
        'source_change_seq',v_source_change_seq,
        'source_change_sequence',v_source_change_seq,
        'latest_source_change_seq',v_source_change_seq
      )
    );

    SELECT registry.dirty_generation,
           registry.current_source_change_seq
    INTO v_registry_dirty_generation,
         v_registry_source_change_seq_after
    FROM private.banking_pay_workbench_candidate_scope_registry AS registry
    WHERE registry.candidate_id=p_candidate_id
    FOR UPDATE;

    IF NOT FOUND
       OR COALESCE(v_registry_source_change_seq_after,0)<COALESCE(v_source_change_seq,0) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ACCEPTED_SOURCE_SEQUENCE_NOT_SYNCHRONISED'
        USING ERRCODE='40001', DETAIL=jsonb_build_object(
          'code','PAY_WORKBENCH_ACCEPTED_SOURCE_SEQUENCE_NOT_SYNCHRONISED',
          'candidate_id',p_candidate_id,
          'accepted_source_change_seq',v_source_change_seq,
          'registry_source_change_seq_after',v_registry_source_change_seq_after,
          'registry_dirty_generation',v_registry_dirty_generation
        )::text;
    END IF;
    v_registry_sequence_synchronised := true;
  END IF;

  v_payload_shadow_compare_required := lower(BTRIM(COALESCE(
    v_payload_json->>'shadow_compare_required',
    v_payload_json->>'shadow_compare',
    v_payload_json->>'shadow_mode',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_payload_shadow_compare_enforced := lower(BTRIM(COALESCE(
    v_payload_json->>'shadow_compare_enforced',
    v_payload_json->>'enforce_shadow_compare',
    v_payload_json->>'shadow_enforced',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  v_shadow_compare_required := (
    lower(BTRIM(COALESCE(v_classifier_result#>>'{complexity_flags,delta_shadow_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_classifier_result#>>'{complexity_flags,payload_shadow_mode}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_classifier_result->>'shadow_compare_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_payload_shadow_compare_required
  );

  v_shadow_compare_enforced := COALESCE(v_shadow_compare_required, false) AND (
    COALESCE(v_payload_shadow_compare_enforced, false)
    OR lower(BTRIM(COALESCE(v_classifier_result->>'shadow_compare_enforced', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
  );

  IF v_resolved_mode IN ('PATCH_ONLY', 'CLONE_REBASE', 'BLOCKED') THEN
    v_no_job_reason := CASE
      WHEN v_resolved_mode = 'PATCH_ONLY' THEN COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'PATCH_ONLY_NO_SOURCE_BUILD_JOB')
      WHEN v_resolved_mode = 'CLONE_REBASE' THEN COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'CLONE_REBASE_NOT_A_CANDIDATE_SOURCE_BUILD_JOB')
      ELSE COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'CLASSIFIER_BLOCKED_REFRESH')
    END;

    UPDATE public.banking_pay_workbench_session_scope AS no_job_scope
    SET status = CASE
          WHEN v_resolved_mode = 'PATCH_ONLY' THEN COALESCE(NULLIF(v_classifier_result->>'scope_status', ''), 'PATCH_ONLY_PENDING')
          WHEN v_resolved_mode = 'CLONE_REBASE' THEN COALESCE(NULLIF(v_classifier_result->>'scope_status', ''), 'CLONE_REBASE_PENDING')
          ELSE COALESCE(NULLIF(v_classifier_result->>'scope_status', ''), no_job_scope.status)
        END,
        pending_job_id = NULL,
        dirty = false,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE no_job_scope.session_id = v_session_id
      AND no_job_scope.candidate_id = p_candidate_id
      AND v_resolved_mode IN ('PATCH_ONLY', 'CLONE_REBASE');

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'ok', true,
      'job_id', NULL::text,
      'job_type', NULL::text,
      'canonical_job_type', NULL::text,
      'snapshot_run_id', p_snapshot_run_id::text,
      'session_id', v_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'reason', v_reason,
      'resolved_mode', v_resolved_mode,
      'projection_mode', v_projection_mode,
      'projection_class', v_projection_class,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
      'pay_channel_scope', v_pay_channel_scope,
      'source_build_required', false,
      'line_work_required', false,
      'line_work_only', false,
      'delta_refresh_required', false,
      'patch_only', v_resolved_mode = 'PATCH_ONLY',
      'clone_rebase_required', v_resolved_mode = 'CLONE_REBASE',
      'blocked', v_resolved_mode = 'BLOCKED',
      'no_op', v_resolved_mode = 'BLOCKED',
      'deferred', v_resolved_mode = 'CLONE_REBASE',
      'fallback_required', lower(BTRIM(COALESCE(v_classifier_result->>'fallback_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'fallback_reason', v_no_job_reason,
      'classifier_result', v_classifier_result
    ));
  END IF;

  IF v_resolved_mode = 'DELTA'
     AND v_resolved_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
     AND lower(BTRIM(COALESCE(v_classifier_result->>'fast_path_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     AND v_force_legacy IS NOT TRUE
     AND v_force_broad_legacy IS NOT TRUE THEN
    v_job_type := 'WORKBENCH_CANDIDATE_DELTA_REFRESH';
  ELSE
    v_resolved_mode := 'LEGACY';
    v_job_type := 'WORKBENCH_CANDIDATE_SOURCE_BUILD';
  END IF;

  IF COALESCE(v_payload_json->>'source_build_limit', '') ~ '^[0-9]{1,9}$' THEN
    v_stage_limit := LEAST(GREATEST((v_payload_json->>'source_build_limit')::integer, 1), 100);
  ELSIF COALESCE(v_payload_json#>>'{stage_limits,source_build}', '') ~ '^[0-9]{1,9}$' THEN
    v_stage_limit := LEAST(GREATEST((v_payload_json#>>'{stage_limits,source_build}')::integer, 1), 100);
  ELSIF COALESCE(v_payload_json->>'limit', '') ~ '^[0-9]{1,9}$' THEN
    v_stage_limit := LEAST(GREATEST((v_payload_json->>'limit')::integer, 1), 100);
  ELSE
    SELECT LEAST(GREATEST(COALESCE(
      CASE
        WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job', '') ~ '^[0-9]{1,9}$'
          THEN (to_jsonb(settings_row)->>'banking_pay_workbench_source_build_units_per_job')::integer
        ELSE NULL::integer
      END,
      CASE
        WHEN COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job', '') ~ '^[0-9]{1,9}$'
          THEN (to_jsonb(settings_row)->>'banking_pay_workbench_stage_work_units_per_job')::integer
        ELSE NULL::integer
      END,
      25
    ), 1), 100)
    INTO v_stage_limit
    FROM public.settings_defaults AS settings_row
    WHERE settings_row.id = 1
    LIMIT 1;

    v_stage_limit := COALESCE(v_stage_limit, 25);
  END IF;

  v_initial_cursor_json := CASE
    WHEN jsonb_typeof(v_payload_json->'cursor_json') = 'object' THEN v_payload_json->'cursor_json'
    WHEN jsonb_typeof(v_payload_json->'cursor') = 'object' THEN v_payload_json->'cursor'
    WHEN jsonb_typeof(v_payload_json->'source_cursor') = 'object' THEN v_payload_json->'source_cursor'
    WHEN jsonb_typeof(v_payload_json#>'{source_build,cursor}') = 'object' THEN v_payload_json#>'{source_build,cursor}'
    ELSE '{}'::jsonb
  END;

  v_cursor_token := md5(COALESCE(v_initial_cursor_json, '{}'::jsonb)::text);
  v_session_signature_token := md5(COALESCE(v_session_row.session_signature, ''));

  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_projection_run_id_text := NULLIF(BTRIM(COALESCE(v_payload_json->>'projection_run_id', v_classifier_result->>'projection_run_id', '')), '');
    IF v_projection_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_projection_run_id := v_projection_run_id_text::uuid;
    ELSE
      v_projection_run_id := gen_random_uuid();
    END IF;

    v_delta_ids_hash := md5(
      COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb)::text
      || ':'
      || COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb)::text
    );

    v_delta_coalescing_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || COALESCE(v_session_id::text, 'none')
    || ':version:' || COALESCE(COALESCE(v_session_row.version, 0), 0)::text
    || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''), 'DELTA'))), ''), 'DELTA')
    || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(v_projection_class, ''), 'UNKNOWN'))), ''), 'UNKNOWN')
    || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''), 'TARGETED_TIMESHEETS'))), ''), 'TARGETED_TIMESHEETS')
    || ':candidate:' || COALESCE(p_candidate_id::text, 'none')
    || ':timesheets:' || COALESCE(v_delta_ids_hash, md5('[]:[]'));
    v_delta_coalescing_hash := md5(v_delta_coalescing_key);

    SELECT running_delta_job.id
    INTO v_delta_active_running_job_id
    FROM public.banking_pay_workbench_jobs AS running_delta_job
    WHERE running_delta_job.session_id = v_session_id
      AND running_delta_job.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
      AND UPPER(BTRIM(COALESCE(running_delta_job.status, ''))) = 'RUNNING'
      AND (
        COALESCE(running_delta_job.payload_json->>'normalised_delta_family_key', running_delta_job.payload_json->>'delta_family_key', running_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
        OR (
            SELECT
              'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
              || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.session_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                ''
              )), ''), 'none')
              || ':version:' || COALESCE(
                CASE
                  WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                    THEN delta_family_values.session_version_text::bigint
                  ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                END,
                0
              )::text
              || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_mode_text, ''),
                NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                'DELTA'
              ))), ''), 'DELTA')
              || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_class_text, ''),
                NULLIF(v_projection_class, ''),
                'UNKNOWN'
              ))), ''), 'UNKNOWN')
              || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                CASE
                  WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                    OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                    THEN 'TARGETED_TIMESHEETS'
                  ELSE 'CANDIDATE_FULL_LIVE'
                END
              ))), ''), 'CANDIDATE_FULL_LIVE')
              || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.candidate_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                ''
              )), ''), 'none')
              || ':timesheets:' || md5(
                COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                || ':'
                || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
              )
            FROM (
              SELECT
                NULLIF(BTRIM(COALESCE(
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                  CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                  '0'
                )), '') AS session_version_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))) AS projection_mode_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))) AS projection_class_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                ))) AS refresh_scope_kind_text
            ) AS delta_family_values
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                    WHEN NULLIF(BTRIM(COALESCE(
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                           ''
                         )), '') IS NOT NULL
                      THEN jsonb_build_array(COALESCE(
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                      ))
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_targeted_raw(value)
                WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_targeted_sorted
            ) AS delta_family_targeted
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_linked_raw(value)
                WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_linked_sorted
            ) AS delta_family_linked
          ) = v_delta_coalescing_key
      )
    ORDER BY running_delta_job.started_at_utc ASC NULLS LAST, running_delta_job.created_at_utc ASC, running_delta_job.id ASC
    LIMIT 1;

    v_dedupe_key := CASE
      WHEN v_delta_active_running_job_id IS NOT NULL THEN
        v_delta_coalescing_key || ':waiting_after_running:' || v_delta_active_running_job_id::text
      ELSE
        v_delta_coalescing_key
    END;

    v_payload_out_json := jsonb_strip_nulls(
      v_payload_json
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'resolved_mode', 'DELTA',
        'projection_run_id', v_projection_run_id::text,
        'projection_mode', COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'),
        'projection_class', v_projection_class,
        'phase', 'INIT_PREFLIGHT',
        'cursor_json', '{}'::jsonb,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'queue_identity_targeted_timesheet_ids', COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb),
        'queue_identity_linked_timesheet_ids', COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb),
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'source_change_sequence', COALESCE(v_source_change_seq, 0),
        'latest_source_change_seq', COALESCE(v_source_change_seq, 0),
        'delta_coalescing_key', v_delta_coalescing_key,
        'delta_family_key', v_delta_coalescing_key,
        'normalised_delta_family_key', v_delta_coalescing_key,
        'delta_coalescing_hash', v_delta_coalescing_hash,
        'coalesced_source_change_seqs', jsonb_build_array(COALESCE(v_source_change_seq, 0)),
        'coalesced_event_count', 1,
        'latest_event_at_utc', v_now::text,
        'source_build_required', false,
        'line_work_required', false,
        'delta_refresh_required', true,
        'legacy_fallback_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      )
      || jsonb_build_object(
        'reason', v_reason,
        'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
        'snapshot_run_id', p_snapshot_run_id::text,
        'source_snapshot_run_id', p_snapshot_run_id::text,
        'session_id', v_session_id::text,
        'source_session_id', v_session_id::text,
        'workbench_session_id', v_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'pay_channel_scope', v_pay_channel_scope,
        'refresh_scope_kind', COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'),
        'candidate_id', p_candidate_id::text,
        'dedupe_key', v_dedupe_key,
        'shadow_compare_required', COALESCE(v_shadow_compare_required, false),
        'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false),
        'classifier_result', v_classifier_result,
        'fallback_required', false,
        'fallback_reason', NULL::text,
        'force_legacy', false,
        'force_broad_legacy', false
      )
      || jsonb_build_object(
        'mutation_context', NULLIF(BTRIM(COALESCE(v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'lifecycle_context', '')), ''),
        'lifecycle_mutation_context', NULLIF(BTRIM(COALESCE(v_payload_json->>'lifecycle_mutation_context', v_payload_json->>'mutation_context', v_payload_json->>'lifecycle_context', '')), ''),
        'trigger_table', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', v_payload_json#>>'{trigger,table}', '')), ''),
        'trigger_operation', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_operation', v_payload_json->>'trigger_op', v_payload_json#>>'{trigger,operation}', '')), ''),
        'trigger_op', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', v_payload_json->>'trigger_operation', v_payload_json#>>'{trigger,operation}', '')), ''),
        'authorise_boundary_changed', lower(BTRIM(COALESCE(v_payload_json->>'authorise_boundary_changed', v_classifier_result#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'unauthorise_boundary_changed', lower(BTRIM(COALESCE(v_payload_json->>'unauthorise_boundary_changed', v_classifier_result#>>'{complexity_flags,unauthorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'explicit_banking_pay_action', lower(BTRIM(COALESCE(v_payload_json->>'explicit_banking_pay_action', v_classifier_result#>>'{complexity_flags,explicit_banking_pay_action}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'banking_pay_dirty_required', lower(BTRIM(COALESCE(v_payload_json->>'banking_pay_dirty_required', v_classifier_result->>'banking_pay_dirty_required', v_classifier_result#>>'{complexity_flags,banking_pay_dirty_required}', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
        'ordinary_timesheet_edit_save_no_dirty', lower(BTRIM(COALESCE(v_payload_json->>'ordinary_timesheet_edit_save_no_dirty', v_classifier_result#>>'{complexity_flags,ordinary_timesheet_edit_save_no_dirty}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
    );
  ELSE
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
      v_payload_json->>'source_build_run_id',
      v_payload_json#>>'{source_build,source_build_run_id}',
      v_payload_json#>>'{source_build,run_id}',
      v_initial_cursor_json->>'source_build_run_id',
      ''
    )), '');

    IF v_source_build_run_id_text IS NOT NULL THEN
      IF v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SOURCE_BUILD_RUN_ID_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_SOURCE_BUILD_RUN_ID_INVALID',
                  'source_build_run_id', v_source_build_run_id_text,
                  'session_id', v_session_id::text,
                  'candidate_id', p_candidate_id::text
                )::text;
      END IF;
      v_requested_source_build_run_id := v_source_build_run_id_text::uuid;
    END IF;

    v_authority_fingerprint_text := concat_ws('|',
      CASE WHEN v_authority_fingerprint_version=3
        THEN 'WORKBENCH_SOURCE_OWNER_V3' ELSE 'WORKBENCH_SOURCE_OWNER_V2' END,
      v_session_id::text,
      COALESCE(v_session_row.version, 0)::text,
      v_session_row.source_snapshot_run_id::text,
      v_session_signature_token,
      p_candidate_id::text,
      COALESCE(v_source_change_seq, 0)::text,
      COALESCE(v_registry_dirty_generation, 0)::text,
      UPPER(BTRIM(COALESCE(v_pay_channel_scope, 'ALL'))),
      'FULL_CANDIDATE',
      CASE WHEN v_authority_fingerprint_version=3
        THEN 'READY_TO_PAY_SEMANTIC_V2' ELSE NULL END,
      CASE WHEN v_authority_fingerprint_version=3
        THEN v_required_physical_publication_contract_version::text ELSE NULL END
    );
    v_authority_fingerprint := pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(v_authority_fingerprint_text, 'UTF8'), 'sha256'),
      'hex'
    );
    v_source_build_hash := substr(v_authority_fingerprint, 1, 32);
    v_source_build_run_id := (
      substr(v_source_build_hash, 1, 8) || '-' ||
      substr(v_source_build_hash, 9, 4) || '-' ||
      substr(v_source_build_hash, 13, 4) || '-' ||
      substr(v_source_build_hash, 17, 4) || '-' ||
      substr(v_source_build_hash, 21, 12)
    )::uuid;

    v_dedupe_key := CASE WHEN v_authority_fingerprint_version=3
        THEN 'WORKBENCH_SOURCE_OWNER_V3:' ELSE 'WORKBENCH_SOURCE_OWNER_V2:' END
      || v_authority_fingerprint
      || ':cursor:' || v_cursor_token;

    v_payload_out_json := jsonb_strip_nulls(
      v_payload_json
      || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'resolved_mode', 'LEGACY',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'reason', v_reason,
        'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
        'snapshot_run_id', p_snapshot_run_id::text,
        'source_snapshot_run_id', p_snapshot_run_id::text,
        'session_id', v_session_id::text,
        'source_session_id', v_session_id::text,
        'workbench_session_id', v_session_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'session_signature', v_session_row.session_signature,
        'session_signature_token', v_session_signature_token
      )
      || jsonb_build_object(
        'candidate_id', p_candidate_id::text,
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'source_change_sequence', COALESCE(v_source_change_seq, 0),
        'source_build_run_id', v_source_build_run_id::text,
        'refresh_scope_kind', v_refresh_scope_kind,
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
        'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)
      )
      || jsonb_build_object(
        'pay_channel_scope', v_pay_channel_scope,
        'source_build_required', true,
        'line_work_required', true,
        'line_work_only', false,
        'delta_refresh_required', false,
        'source_build_action', 'BUILD_SOURCE',
        'line_work_action', 'SOURCE_BUILD_THEN_SEED',
        'source_build_limit', v_stage_limit,
        'limit', v_stage_limit,
        'source_cursor', COALESCE(v_initial_cursor_json, '{}'::jsonb),
        'cursor_json', COALESCE(v_initial_cursor_json, '{}'::jsonb),
        'cursor_token', v_cursor_token
      )
      || jsonb_build_object(
        'trigger_table', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_table', v_payload_json#>>'{trigger,table}', '')), ''),
        'trigger_operation', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_operation', v_payload_json->>'trigger_op', v_payload_json#>>'{trigger,operation}', '')), ''),
        'trigger_op', NULLIF(BTRIM(COALESCE(v_payload_json->>'trigger_op', v_payload_json->>'trigger_operation', v_payload_json#>>'{trigger,operation}', '')), ''),
        'dedupe_key', v_dedupe_key,
        'authority_fingerprint_version', v_authority_fingerprint_version,
        'authority_fingerprint', v_authority_fingerprint,
        'source_publication_baseline_required',v_source_publication_baseline_required,
        'required_physical_publication_contract_version',v_required_physical_publication_contract_version,
        'requested_source_build_run_id', CASE WHEN v_requested_source_build_run_id IS NULL THEN NULL ELSE v_requested_source_build_run_id::text END,
        'created_by_helper', 'pay_workbench_enqueue_candidate_refresh',
        'created_at_utc', v_now::text,
        'classifier_result', v_classifier_result
      )
      || jsonb_build_object(
        'source_build', jsonb_strip_nulls(jsonb_build_object(
          'required', true,
          'run_id', v_source_build_run_id::text,
          'source_build_run_id', v_source_build_run_id::text,
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'session_version', COALESCE(v_session_row.version, 0),
          'refresh_scope_kind', v_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'pay_channel_scope', v_pay_channel_scope,
          'limit', v_stage_limit,
          'cursor', COALESCE(v_initial_cursor_json, '{}'::jsonb),
          'reason', v_reason
          ,'source_publication_baseline_required',v_source_publication_baseline_required
          ,'required_physical_publication_contract_version',v_required_physical_publication_contract_version
        ))
      )
    );
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
    -- An active economic build, rather than the lifecycle reason or the root
    -- job's current status, is the durable refresh owner.  A succeeded root
    -- with queued/running stage continuations therefore remains active.
    SELECT build_row.*
    INTO v_owner_build
    FROM private.banking_pay_workbench_economic_builds AS build_row
    WHERE build_row.candidate_id = p_candidate_id
      AND build_row.session_id = v_session_id
      AND build_row.session_version = COALESCE(v_session_row.version, 0)
      AND build_row.source_snapshot_run_id = v_session_row.source_snapshot_run_id
      AND build_row.source_change_seq = COALESCE(v_source_change_seq, 0)
      AND build_row.captured_candidate_generation = COALESCE(v_registry_dirty_generation, 0)
      AND (
        v_source_publication_baseline_required IS NOT TRUE
        OR (
          build_row.authority_fingerprint_version=3
          AND COALESCE((build_row.attestation_json->>'required_physical_publication_contract_version')::integer,0)>=1
        )
      )
      AND UPPER(BTRIM(COALESCE(build_row.status, ''))) IN (
        'COLLECTING',
        'READY_FOR_RECONCILIATION',
        'RECONCILING',
        'RECONCILED',
        'PUBLISHING',
        'BLOCKED_UNVALIDATED_RECONCILIATION_SCALE'
      )
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_jobs AS owner_active_job
        WHERE owner_active_job.economic_build_id = build_row.id
          AND UPPER(BTRIM(COALESCE(owner_active_job.status, ''))) IN ('QUEUED', 'RUNNING')
      )
    ORDER BY
      CASE
        WHEN build_row.id = (
          SELECT registry.current_build_id
          FROM private.banking_pay_workbench_candidate_scope_registry AS registry
          WHERE registry.candidate_id = p_candidate_id
        ) THEN 0
        ELSE 1
      END,
      build_row.created_at_utc DESC,
      build_row.id DESC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      SELECT source_job.*
      INTO v_owner_root_job
      FROM public.banking_pay_workbench_jobs AS source_job
      WHERE source_job.economic_build_id = v_owner_build.id
        AND UPPER(BTRIM(COALESCE(source_job.job_type, ''))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND COALESCE(
          source_job.payload_json->>'source_build_run_id',
          source_job.payload_json#>>'{source_build,source_build_run_id}',
          ''
        ) = v_owner_build.source_build_run_id::text
      ORDER BY source_job.created_at_utc, source_job.id
      LIMIT 1
      FOR UPDATE;

      IF FOUND THEN
        v_owner_refresh_scope_kind := UPPER(BTRIM(COALESCE(
          v_owner_root_job.payload_json->>'refresh_scope_kind',
          v_owner_root_job.payload_json#>>'{source_build,refresh_scope_kind}',
          ''
        )));
        v_owner_pay_channel_scope := UPPER(BTRIM(COALESCE(
          v_owner_root_job.payload_json->>'pay_channel_scope',
          v_owner_root_job.payload_json#>>'{source_build,pay_channel_scope}',
          'ALL'
        )));
        v_owner_targeted_timesheet_ids_json := CASE
          WHEN jsonb_typeof(v_owner_root_job.payload_json->'targeted_timesheet_ids') = 'array'
            THEN v_owner_root_job.payload_json->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_owner_root_job.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array'
            THEN v_owner_root_job.payload_json#>'{source_build,targeted_timesheet_ids}'
          ELSE '[]'::jsonb
        END;
        v_owner_linked_timesheet_ids_json := CASE
          WHEN jsonb_typeof(v_owner_root_job.payload_json->'linked_timesheet_ids') = 'array'
            THEN v_owner_root_job.payload_json->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_owner_root_job.payload_json#>'{source_build,linked_timesheet_ids}') = 'array'
            THEN v_owner_root_job.payload_json#>'{source_build,linked_timesheet_ids}'
          ELSE '[]'::jsonb
        END;
        -- Every WORKBENCH_CANDIDATE_SOURCE_BUILD owns complete candidate truth.
        -- Diagnostic refresh scope is retained as provenance, not identity.
        v_owner_covers_request :=
          v_owner_pay_channel_scope = UPPER(BTRIM(COALESCE(v_pay_channel_scope, 'ALL')));
        IF v_owner_covers_request THEN
          v_owner_resolution := 'ACTIVE_CURRENT_OWNER_COVERS_REQUEST';
        END IF;
      END IF;
    END IF;

    -- A cancellation reversion deliberately retains the immutable original
    -- economic-build lineage while publishing a new current source run at the
    -- cancellation sequence/generation.  It is therefore a complete current
    -- authority even though the historical build row itself has an older
    -- source sequence.  Recognise only the exact V3 terminal attestation; an
    -- ordinary V1/V2 or structurally incomplete scope cannot enter this path.
    IF v_owner_resolution='NO_CURRENT_OWNER'
       AND v_scope_state_precedes_job IS TRUE THEN
      SELECT current_scope.*
      INTO v_reversion_scope
      FROM public.banking_pay_workbench_session_scope AS current_scope
      WHERE current_scope.session_id=v_session_id
        AND current_scope.candidate_id=p_candidate_id
        AND current_scope.dirty IS FALSE
        AND current_scope.pending_job_id IS NULL
        AND current_scope.certified_preview_publication_required IS TRUE
        AND current_scope.certified_preview_publication_parity_ok IS TRUE
        AND current_scope.certified_preview_publication_session_version=COALESCE(v_session_row.version,0)
        AND current_scope.certified_preview_publication_source_change_seq=COALESCE(v_source_change_seq,0)
        AND current_scope.certified_preview_publication_attestation_json->>'attestation_version'
              ='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
        AND current_scope.certified_preview_publication_attestation_json->>'contract_version'='3'
        AND current_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
              ='READY_TO_PAY_SEMANTIC_V2'
        AND current_scope.certified_preview_publication_attestation_json->>'authority_kind'
              ='CERTIFIED_CANCELLATION_REVERSION'
        AND COALESCE((current_scope.certified_preview_publication_attestation_json->>'semantic_ready')::boolean,false)
        AND COALESCE((current_scope.certified_preview_publication_attestation_json->>'parity_complete')::boolean,false)
        AND (
          NOT v_source_publication_baseline_required
          OR (
            current_scope.certified_preview_publication_source_publication_id IS NOT NULL
            AND current_scope.certified_preview_publication_attestation_json->>'source_publication_id'
                  =current_scope.certified_preview_publication_source_publication_id::text
          )
        )
      FOR UPDATE;

      IF FOUND THEN
        v_reversion_attestation:=COALESCE(
          v_reversion_scope.certified_preview_publication_attestation_json,'{}'::jsonb
        );

        SELECT current_state.*
        INTO v_reversion_state
        FROM public.banking_pay_workbench_session_candidate_state AS current_state
        WHERE current_state.session_id=v_session_id
          AND current_state.candidate_id=p_candidate_id
          AND UPPER(BTRIM(COALESCE(current_state.status,'')))='READY'
          AND current_state.pending_job_id IS NULL
          AND current_state.session_version=COALESCE(v_session_row.version,0)
          AND current_state.source_change_seq=COALESCE(v_source_change_seq,0)
        FOR UPDATE;
        v_reversion_state_exact:=FOUND;

        SELECT COUNT(*)::integer
        INTO v_reversion_source_count
        FROM public.banking_pay_workbench_candidate_source_lines AS reversion_source
        WHERE reversion_source.session_id=v_session_id
          AND reversion_source.candidate_id=p_candidate_id
          AND reversion_source.session_version=COALESCE(v_session_row.version,0)
          AND reversion_source.source_change_seq=COALESCE(v_source_change_seq,0)
          AND reversion_source.source_publication_id
                =v_reversion_scope.certified_preview_publication_source_publication_id
          AND reversion_source.status='CURRENT';

        IF v_reversion_state_exact
           AND COALESCE(v_registry_source_change_seq_after,v_source_change_seq,0)
                =COALESCE(v_source_change_seq,0)
           AND COALESCE(v_registry_dirty_generation,0)=COALESCE(v_live_scope_change_generation,0)
           AND COALESCE(v_reversion_attestation->>'source_row_count','') ~ '^[0-9]{1,9}$'
           AND v_reversion_source_count=(v_reversion_attestation->>'source_row_count')::integer
           AND NOT EXISTS (
             SELECT 1
             FROM public.banking_pay_workbench_candidate_source_lines AS foreign_current_source
             WHERE foreign_current_source.session_id=v_session_id
               AND foreign_current_source.candidate_id=p_candidate_id
               AND foreign_current_source.status='CURRENT'
               AND (
                 foreign_current_source.session_version IS DISTINCT FROM COALESCE(v_session_row.version,0)
                 OR foreign_current_source.source_change_seq IS DISTINCT FROM COALESCE(v_source_change_seq,0)
                 OR foreign_current_source.source_publication_id IS DISTINCT FROM
                      v_reversion_scope.certified_preview_publication_source_publication_id
               )
            ) THEN
          EXECUTE 'SELECT private.pay_workbench_candidate_physical_currentness_page_v1($1,$2,$3,$4)'
            INTO v_physical_currentness
            USING v_session_id,ARRAY[p_candidate_id],'TERMINAL_CURRENT',
              jsonb_build_object('contract_version',1,'allow_active_owner',false);
          v_candidate_currentness:=COALESCE(v_physical_currentness->'candidate_results'->0,'{}'::jsonb);
          IF COALESCE((v_candidate_currentness->>'terminal_current')::boolean,false) THEN
          RETURN jsonb_strip_nulls(jsonb_build_object(
            'ok',true,
            'job_id',NULL,
            'job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'canonical_job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'session_id',v_session_id::text,
            'candidate_id',p_candidate_id::text,
            'session_version',COALESCE(v_session_row.version,0),
            'source_change_seq',COALESCE(v_source_change_seq,0),
            'registry_source_change_seq',COALESCE(v_registry_source_change_seq_after,v_source_change_seq,0),
            'source_build_run_id',v_reversion_scope.certified_preview_publication_source_build_run_id::text,
            'source_publication_id',v_reversion_scope.certified_preview_publication_source_publication_id::text,
            'authority_fingerprint',v_authority_fingerprint,
            'authority_fingerprint_version',v_authority_fingerprint_version,
            'required_physical_publication_contract_version',v_required_physical_publication_contract_version,
            'owner_resolution','COMPLETE_CURRENT_AUTHORITY',
            'owner_build_id',v_reversion_attestation->>'economic_build_id',
            'owner_root_job_id',NULL,
            'owner_source_build_run_id',v_reversion_scope.certified_preview_publication_source_build_run_id::text,
            'requested_coverage','FULL_CANDIDATE',
            'owner_coverage','FULL_CANDIDATE',
            'scope_status',v_reversion_scope.status,
            'source_build_required',false,
            'delta_refresh_required',false,
            'coalesced',true,
            'reused',true,
            'new_owner_created',false,
            'no_op',true,
            'stale_preinvalidated_absorb_only',v_stale_preinvalidated_absorb_only,
            'diagnostic_provenance_merged',false,
            'reason',v_reason,
            'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
          ));
          END IF;
        END IF;
      END IF;
    END IF;

    -- A delayed dirty event which revalidates to an already published current
    -- authority is a true no-op.  This branch is deliberately limited to the
    -- caller's proven, already-finalised scope generation.
    IF v_owner_resolution = 'NO_CURRENT_OWNER'
       AND v_scope_state_precedes_job IS TRUE THEN
      SELECT build_row.*
      INTO v_owner_build
      FROM private.banking_pay_workbench_economic_builds AS build_row
      JOIN public.banking_pay_workbench_session_scope AS current_scope
        ON current_scope.session_id = build_row.session_id
       AND current_scope.candidate_id = build_row.candidate_id
      JOIN public.banking_pay_workbench_session_candidate_state AS current_state
        ON current_state.session_id = build_row.session_id
       AND current_state.candidate_id = build_row.candidate_id
      WHERE build_row.candidate_id = p_candidate_id
        AND build_row.session_id = v_session_id
        AND build_row.session_version = COALESCE(v_session_row.version, 0)
        AND build_row.source_snapshot_run_id = v_session_row.source_snapshot_run_id
        AND build_row.source_change_seq = COALESCE(v_source_change_seq, 0)
        AND build_row.captured_candidate_generation = COALESCE(v_registry_dirty_generation, 0)
        AND UPPER(BTRIM(COALESCE(build_row.status, ''))) = 'COMPLETE'
        AND UPPER(BTRIM(COALESCE(build_row.private_stage, ''))) = 'COMPLETE'
        AND current_scope.dirty IS FALSE
        AND current_scope.pending_job_id IS NULL
        AND current_scope.certified_preview_publication_required IS TRUE
        AND current_scope.certified_preview_publication_parity_ok IS TRUE
        AND current_scope.certified_preview_publication_session_version = build_row.session_version
        AND current_scope.certified_preview_publication_source_change_seq = build_row.source_change_seq
        AND current_scope.certified_preview_publication_source_build_run_id = build_row.source_build_run_id
        AND (
          NOT v_source_publication_baseline_required
          OR (
            current_scope.certified_preview_publication_source_publication_id IS NOT NULL
            AND current_scope.certified_preview_publication_attestation_json->>'source_publication_id'
                  =current_scope.certified_preview_publication_source_publication_id::text
          )
        )
        AND (
          v_semantic_ready_publication_enabled IS NOT TRUE
          OR (
            current_scope.certified_preview_publication_attestation_json->>'attestation_version'
              = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
            AND current_scope.certified_preview_publication_attestation_json->>'contract_version' = '3'
            AND current_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
              = 'READY_TO_PAY_SEMANTIC_V2'
            AND COALESCE(
              (current_scope.certified_preview_publication_attestation_json->>'semantic_ready')::boolean,
              false
            )
          )
        )
        AND UPPER(BTRIM(COALESCE(current_state.status, ''))) = 'READY'
        AND current_state.pending_job_id IS NULL
        AND current_state.session_version = build_row.session_version
        AND current_state.source_change_seq = build_row.source_change_seq
      ORDER BY build_row.completed_at_utc DESC NULLS LAST, build_row.id DESC
      LIMIT 1
      FOR UPDATE OF build_row, current_scope, current_state;

      IF FOUND THEN
        SELECT source_job.*
        INTO v_owner_root_job
        FROM public.banking_pay_workbench_jobs AS source_job
        WHERE source_job.economic_build_id = v_owner_build.id
          AND UPPER(BTRIM(COALESCE(source_job.job_type, ''))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
          AND COALESCE(
            source_job.payload_json->>'source_build_run_id',
            source_job.payload_json#>>'{source_build,source_build_run_id}',
            ''
          ) = v_owner_build.source_build_run_id::text
        ORDER BY source_job.created_at_utc, source_job.id
        LIMIT 1
        FOR UPDATE;

        IF FOUND THEN
          v_owner_refresh_scope_kind := UPPER(BTRIM(COALESCE(
            v_owner_root_job.payload_json->>'refresh_scope_kind',
            v_owner_root_job.payload_json#>>'{source_build,refresh_scope_kind}',
            ''
          )));
          v_owner_pay_channel_scope := UPPER(BTRIM(COALESCE(
            v_owner_root_job.payload_json->>'pay_channel_scope',
            v_owner_root_job.payload_json#>>'{source_build,pay_channel_scope}',
            'ALL'
          )));
          v_owner_covers_request :=
            v_owner_pay_channel_scope = UPPER(BTRIM(COALESCE(v_pay_channel_scope, 'ALL')));
          IF v_owner_covers_request THEN
            EXECUTE 'SELECT private.pay_workbench_candidate_physical_currentness_page_v1($1,$2,$3,$4)'
              INTO v_physical_currentness
              USING v_session_id,ARRAY[p_candidate_id],'TERMINAL_CURRENT',
                jsonb_build_object('contract_version',1,'allow_active_owner',false);
            v_candidate_currentness:=COALESCE(v_physical_currentness->'candidate_results'->0,'{}'::jsonb);
            IF COALESCE((v_candidate_currentness->>'terminal_current')::boolean,false) THEN
              v_owner_resolution := 'COMPLETE_CURRENT_AUTHORITY';
            END IF;
          END IF;
        END IF;
      END IF;
    END IF;

    IF v_owner_resolution IN (
      'ACTIVE_CURRENT_OWNER_COVERS_REQUEST',
      'COMPLETE_CURRENT_AUTHORITY'
    ) THEN
      SELECT COALESCE(jsonb_agg(bounded_reason.reason ORDER BY bounded_reason.reason), '[]'::jsonb)
      INTO v_owner_reasons_json
      FROM (
        SELECT DISTINCT reason_value.reason
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_owner_root_job.payload_json->'reasons') = 'array'
              THEN v_owner_root_job.payload_json->'reasons'
            WHEN NULLIF(BTRIM(COALESCE(v_owner_root_job.payload_json->>'reason', '')), '') IS NOT NULL
              THEN jsonb_build_array(v_owner_root_job.payload_json->>'reason')
            ELSE '[]'::jsonb
          END || jsonb_build_array(v_reason)
        ) AS reason_value(reason)
        WHERE NULLIF(BTRIM(reason_value.reason), '') IS NOT NULL
        ORDER BY reason_value.reason
        LIMIT 16
      ) AS bounded_reason;

      SELECT COALESCE(jsonb_agg(bounded_source.source ORDER BY bounded_source.source), '[]'::jsonb)
      INTO v_owner_trigger_sources_json
      FROM (
        SELECT DISTINCT source_value.source
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_owner_root_job.payload_json->'trigger_sources') = 'array'
              THEN v_owner_root_job.payload_json->'trigger_sources'
            ELSE '[]'::jsonb
          END || jsonb_build_array(NULLIF(BTRIM(COALESCE(
            v_payload_json->>'trigger_source',
            v_payload_json->>'trigger_table',
            v_payload_json->>'enqueue_origin',
            ''
          )), ''))
        ) AS source_value(source)
        WHERE NULLIF(BTRIM(source_value.source), '') IS NOT NULL
        ORDER BY source_value.source
        LIMIT 16
      ) AS bounded_source;

      v_owner_request_count := GREATEST(
        CASE WHEN COALESCE(v_owner_root_job.payload_json->>'reason_count', '') ~ '^\d+$'
          THEN (v_owner_root_job.payload_json->>'reason_count')::bigint ELSE 1 END,
        CASE WHEN COALESCE(v_owner_root_job.payload_json#>>'{orchestration_provenance,coalesced_request_count}', '') ~ '^\d+$'
          THEN (v_owner_root_job.payload_json#>>'{orchestration_provenance,coalesced_request_count}')::bigint ELSE 1 END
      ) + 1;
      v_owner_provenance_json := jsonb_strip_nulls(
        CASE WHEN jsonb_typeof(v_owner_root_job.payload_json->'orchestration_provenance') = 'object'
          THEN v_owner_root_job.payload_json->'orchestration_provenance' ELSE '{}'::jsonb END
        || jsonb_build_object(
          'primary_reason', COALESCE(v_owner_root_job.payload_json#>>'{orchestration_provenance,primary_reason}', v_owner_root_job.payload_json->>'reason', v_reason),
          'reason_latest', v_reason,
          'reasons', v_owner_reasons_json,
          'trigger_sources', v_owner_trigger_sources_json,
          'coalesced_request_count', v_owner_request_count,
          'last_requested_at_utc', v_now::text,
          'authority_fingerprint_version', v_authority_fingerprint_version,
          'authority_fingerprint', v_authority_fingerprint
        )
      );

      UPDATE public.banking_pay_workbench_jobs AS owner_job
      SET payload_json = jsonb_strip_nulls(
            COALESCE(owner_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'reason_latest', v_reason,
              'reason_count', v_owner_request_count,
              'reasons', v_owner_reasons_json,
              'trigger_sources', v_owner_trigger_sources_json,
              'orchestration_provenance', v_owner_provenance_json
            )
          ),
          updated_at_utc = v_now
      WHERE owner_job.id = v_owner_root_job.id;

      SELECT active_job.id
      INTO v_owner_active_job_id
      FROM public.banking_pay_workbench_jobs AS active_job
      WHERE active_job.economic_build_id = v_owner_build.id
        AND UPPER(BTRIM(COALESCE(active_job.status, ''))) IN ('QUEUED', 'RUNNING')
      ORDER BY CASE WHEN UPPER(BTRIM(active_job.status)) = 'RUNNING' THEN 0 ELSE 1 END,
               active_job.run_at_utc,
               active_job.created_at_utc,
               active_job.id
      LIMIT 1;

      SELECT scope_row.status
      INTO v_owner_scope_status
      FROM public.banking_pay_workbench_session_scope AS scope_row
      WHERE scope_row.session_id = v_session_id
        AND scope_row.candidate_id = p_candidate_id;

      RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok', true,
        'job_id', v_owner_root_job.id::text,
        'job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'session_id', v_session_id::text,
        'candidate_id', p_candidate_id::text,
        'session_version', COALESCE(v_session_row.version, 0),
        'source_change_seq', COALESCE(v_source_change_seq, 0),
        'registry_source_change_seq', COALESCE(v_registry_source_change_seq_after, v_source_change_seq, 0),
        'source_build_run_id', v_owner_build.source_build_run_id::text,
        'requested_source_build_run_id', CASE WHEN v_requested_source_build_run_id IS NULL THEN NULL ELSE v_requested_source_build_run_id::text END,
        'authority_fingerprint', v_authority_fingerprint,
        'authority_fingerprint_version', v_authority_fingerprint_version,
        'required_physical_publication_contract_version',v_required_physical_publication_contract_version,
        'owner_resolution', v_owner_resolution,
        'owner_build_id', v_owner_build.id::text,
        'owner_root_job_id', v_owner_root_job.id::text,
        'owner_active_job_id', CASE WHEN v_owner_active_job_id IS NULL THEN NULL ELSE v_owner_active_job_id::text END,
        'owner_source_build_run_id', v_owner_build.source_build_run_id::text,
        'requested_coverage', 'FULL_CANDIDATE',
        'owner_coverage', 'FULL_CANDIDATE',
        'scope_status', COALESCE(v_owner_scope_status, CASE WHEN v_owner_resolution = 'COMPLETE_CURRENT_AUTHORITY' THEN 'MATERIALISED' ELSE 'SOURCE_BUILD_PENDING' END),
        'source_build_required', v_owner_resolution <> 'COMPLETE_CURRENT_AUTHORITY',
        'delta_refresh_required', false,
        'coalesced', true,
        'reused', true,
        'new_owner_created', false,
        'no_op', v_owner_resolution = 'COMPLETE_CURRENT_AUTHORITY',
        'stale_preinvalidated_absorb_only', v_stale_preinvalidated_absorb_only,
        'diagnostic_provenance_merged', true,
        'reason', v_reason,
        'reason_count', v_owner_request_count,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ));
    END IF;
  END IF;

  IF v_stale_preinvalidated_absorb_only THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_STALE_PREINVALIDATED_AUTHORITY_NOT_CURRENT'
      USING ERRCODE='40001', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_STALE_PREINVALIDATED_AUTHORITY_NOT_CURRENT',
        'candidate_id',p_candidate_id,
        'payload_scope_change_generation',v_payload_scope_change_generation,
        'live_scope_change_generation',v_live_scope_change_generation,
        'registry_dirty_generation',v_registry_dirty_generation,
        'source_change_seq',v_source_change_seq,
        'registry_source_change_seq',v_registry_source_change_seq_after,
        'owner_resolution',v_owner_resolution
      )::text;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    SELECT existing_delta_job.*
    INTO v_existing_delta_job
    FROM public.banking_pay_workbench_jobs AS existing_delta_job
    WHERE existing_delta_job.session_id = v_session_id
      AND existing_delta_job.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(existing_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
      AND UPPER(BTRIM(COALESCE(existing_delta_job.status, ''))) = 'QUEUED'
      AND (
        COALESCE(existing_delta_job.payload_json->>'normalised_delta_family_key', existing_delta_job.payload_json->>'delta_family_key', existing_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
        OR (
            SELECT
              'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
              || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                existing_delta_job.session_id::text,
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                ''
              )), ''), 'none')
              || ':version:' || COALESCE(
                CASE
                  WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                    THEN delta_family_values.session_version_text::bigint
                  ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                END,
                0
              )::text
              || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_mode_text, ''),
                NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                'DELTA'
              ))), ''), 'DELTA')
              || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_class_text, ''),
                NULLIF(v_projection_class, ''),
                'UNKNOWN'
              ))), ''), 'UNKNOWN')
              || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                CASE
                  WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                    OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                    THEN 'TARGETED_TIMESHEETS'
                  ELSE 'CANDIDATE_FULL_LIVE'
                END
              ))), ''), 'CANDIDATE_FULL_LIVE')
              || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                existing_delta_job.candidate_id::text,
                (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                ''
              )), ''), 'none')
              || ':timesheets:' || md5(
                COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                || ':'
                || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
              )
            FROM (
              SELECT
                NULLIF(BTRIM(COALESCE(
                  (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                  (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                  (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'version',
                  CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                  '0'
                )), '') AS session_version_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))) AS projection_mode_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                  NULLIF(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))) AS projection_class_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                  NULLIF((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                  NULLIF(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                  NULLIF(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                ))) AS refresh_scope_kind_text
            ) AS delta_family_values
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                      THEN (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                    WHEN NULLIF(BTRIM(COALESCE(
                           (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                           (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                           ''
                         )), '') IS NOT NULL
                      THEN jsonb_build_array(COALESCE(
                        (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                        (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                      ))
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_targeted_raw(value)
                WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_targeted_sorted
            ) AS delta_family_targeted
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                      THEN (COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(existing_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_linked_raw(value)
                WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_linked_sorted
            ) AS delta_family_linked
          ) = v_delta_coalescing_key
      )
      AND lower(BTRIM(COALESCE(existing_delta_job.payload_json->>'force_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
      AND lower(BTRIM(COALESCE(existing_delta_job.payload_json->>'force_broad_legacy', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    ORDER BY
      CASE
        WHEN COALESCE(existing_delta_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (existing_delta_job.payload_json->>'source_change_seq')::bigint
        ELSE 0::bigint
      END DESC,
      existing_delta_job.priority ASC,
      existing_delta_job.run_at_utc ASC,
      existing_delta_job.created_at_utc ASC,
      existing_delta_job.id ASC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      -- Reused queued latest-state heads must not inherit an old projection/cursor identity.
      v_existing_delta_projection_run_id_text := NULLIF(BTRIM(COALESCE(v_existing_delta_job.payload_json->>'projection_run_id', '')), '');
      v_projection_run_id := gen_random_uuid();

      v_existing_delta_source_change_seq := GREATEST(
        CASE WHEN COALESCE(v_existing_delta_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_existing_delta_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_existing_delta_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_existing_delta_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_existing_delta_job.payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_existing_delta_job.payload_json->>'source_change_sequence')::bigint ELSE 0::bigint END
      );
      v_existing_delta_event_count := CASE
        WHEN COALESCE(v_existing_delta_job.payload_json->>'coalesced_event_count', '') ~ '^[0-9]{1,9}$'
          THEN GREATEST((v_existing_delta_job.payload_json->>'coalesced_event_count')::integer, 1)
        ELSE 1
      END;
      v_merged_delta_event_count := v_existing_delta_event_count + 1;

      v_payload_out_json := public._pay_workbench_merge_targeted_scope_payload(
        COALESCE(v_existing_delta_job.payload_json, '{}'::jsonb),
        COALESCE(v_payload_out_json, '{}'::jsonb)
      ) || jsonb_build_object(
        'job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'canonical_job_type', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', v_projection_run_id::text,
        'projection_mode', COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'),
        'projection_class', v_projection_class,
        'phase', 'INIT_PREFLIGHT',
        'source_build_required', false,
        'line_work_required', false,
        'delta_refresh_required', true,
        'legacy_fallback_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      );

      v_source_change_seq := GREATEST(
        COALESCE(v_live_change_seq, 0),
        COALESCE(v_source_change_seq, 0),
        COALESCE(v_existing_delta_source_change_seq, 0),
        CASE WHEN COALESCE(v_payload_out_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_payload_out_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_payload_out_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_payload_out_json->>'source_change_seq')::bigint ELSE 0::bigint END,
        CASE WHEN COALESCE(v_payload_out_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$'
          THEN (v_payload_out_json->>'source_change_sequence')::bigint ELSE 0::bigint END
      );

      SELECT COALESCE(jsonb_agg(merged_target_ids.timesheet_id_text ORDER BY merged_target_ids.timesheet_id_text), '[]'::jsonb)
      INTO v_targeted_timesheet_ids_json
      FROM (
        SELECT DISTINCT NULLIF(BTRIM(targeted_values.value), '') AS timesheet_id_text
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_payload_out_json->'targeted_timesheet_ids') = 'array' THEN v_payload_out_json->'targeted_timesheet_ids'
            WHEN jsonb_typeof(v_payload_out_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_out_json->>'targeted_timesheet_ids')
            ELSE '[]'::jsonb
          END
        ) AS targeted_values(value)
        WHERE NULLIF(BTRIM(targeted_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS merged_target_ids;

      SELECT COALESCE(jsonb_agg(merged_linked_ids.timesheet_id_text ORDER BY merged_linked_ids.timesheet_id_text), '[]'::jsonb)
      INTO v_linked_timesheet_ids_json
      FROM (
        SELECT DISTINCT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_payload_out_json->'linked_timesheet_ids') = 'array' THEN v_payload_out_json->'linked_timesheet_ids'
            WHEN jsonb_typeof(v_payload_out_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_out_json->>'linked_timesheet_ids')
            ELSE '[]'::jsonb
          END
        ) AS linked_values(value)
        WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS merged_linked_ids;

      v_delta_ids_hash := md5(
        COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb)::text
        || ':'
        || COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb)::text
      );

      v_delta_coalescing_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
    || ':session:' || COALESCE(v_session_id::text, 'none')
    || ':version:' || COALESCE(COALESCE(v_session_row.version, 0), 0)::text
    || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''), 'DELTA'))), ''), 'DELTA')
    || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(v_projection_class, ''), 'UNKNOWN'))), ''), 'UNKNOWN')
    || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''), 'TARGETED_TIMESHEETS'))), ''), 'TARGETED_TIMESHEETS')
    || ':candidate:' || COALESCE(p_candidate_id::text, 'none')
    || ':timesheets:' || COALESCE(v_delta_ids_hash, md5('[]:[]'));
      v_delta_coalescing_hash := md5(v_delta_coalescing_key);

      v_payload_out_json := jsonb_strip_nulls(
        (COALESCE(v_payload_out_json, '{}'::jsonb) - ARRAY[
          'cursor',
          'cursor_json',
          'next_cursor',
          'next_cursor_json',
          'source_cursor',
          'write_cursor_json',
          'candidate_cursor',
          'cursor_token',
          'has_cursor',
          'continuation_reason',
          'source_job_id',
          'continuation_source_job_id',
          'bounded_continuation_source_job_id',
          'parent_job_id',
          'next_phase',
          'write_phase',
          'source_result_summary',
          'source_result_has_more',
          'source_result_next_cursor_present'
        ]::text[])
        || jsonb_build_object(
          'cursor_json', '{}'::jsonb,
          'continuation', false,
          'phase', 'INIT_PREFLIGHT',
          'run_mode', CASE WHEN v_delta_active_running_job_id IS NULL THEN 'LATEST_STATE_HEAD' ELSE 'LATEST_RERUN_AFTER_RUNNING' END,
          'normalised_delta_family_key', v_delta_coalescing_key,
          'delta_family_key', v_delta_coalescing_key,
          'delta_coalescing_key', v_delta_coalescing_key,
          'delta_coalescing_hash', v_delta_coalescing_hash
        )
      );

      SELECT running_delta_job.id
      INTO v_delta_active_running_job_id
      FROM public.banking_pay_workbench_jobs AS running_delta_job
      WHERE running_delta_job.session_id = v_session_id
        AND running_delta_job.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND UPPER(BTRIM(COALESCE(running_delta_job.status, ''))) = 'RUNNING'
        AND running_delta_job.id IS DISTINCT FROM v_existing_delta_job.id
        AND (
          COALESCE(running_delta_job.payload_json->>'normalised_delta_family_key', running_delta_job.payload_json->>'delta_family_key', running_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
          OR (
              SELECT
                'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
                || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  running_delta_job.session_id::text,
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                  ''
                )), ''), 'none')
                || ':version:' || COALESCE(
                  CASE
                    WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                      THEN delta_family_values.session_version_text::bigint
                    ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                  END,
                  0
                )::text
                || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_mode_text, ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))), ''), 'DELTA')
                || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.projection_class_text, ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))), ''), 'UNKNOWN')
                || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                  NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                  CASE
                    WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                      OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                      THEN 'TARGETED_TIMESHEETS'
                    ELSE 'CANDIDATE_FULL_LIVE'
                  END
                ))), ''), 'CANDIDATE_FULL_LIVE')
                || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                  running_delta_job.candidate_id::text,
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                  ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                  ''
                )), ''), 'none')
                || ':timesheets:' || md5(
                  COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                  || ':'
                  || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
                )
              FROM (
                SELECT
                  NULLIF(BTRIM(COALESCE(
                    (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                    (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                    (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                    CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                    '0'
                  )), '') AS session_version_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                    NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                    'DELTA'
                  ))) AS projection_mode_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                    NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                    NULLIF(v_projection_class, ''),
                    'UNKNOWN'
                  ))) AS projection_class_text,
                  UPPER(BTRIM(COALESCE(
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                    NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                    NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                    NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                    NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                  ))) AS refresh_scope_kind_text
              ) AS delta_family_values
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                        THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                      WHEN NULLIF(BTRIM(COALESCE(
                             (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                             (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                             ''
                           )), '') IS NOT NULL
                        THEN jsonb_build_array(COALESCE(
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                          (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                        ))
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_targeted_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_targeted_sorted
              ) AS delta_family_targeted
              CROSS JOIN (
                SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
                FROM (
                  SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                        THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                      WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                        THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                      WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                        THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                      ELSE '[]'::jsonb
                    END
                  ) AS delta_family_linked_raw(value)
                  WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                ) AS delta_family_linked_sorted
              ) AS delta_family_linked
            ) = v_delta_coalescing_key
        )
      ORDER BY running_delta_job.started_at_utc ASC NULLS LAST, running_delta_job.created_at_utc ASC, running_delta_job.id ASC
      LIMIT 1;

      v_dedupe_key := CASE
        WHEN v_delta_active_running_job_id IS NOT NULL THEN
          v_delta_coalescing_key || ':waiting_after_running:' || v_delta_active_running_job_id::text
        ELSE
          v_delta_coalescing_key
      END;

      v_payload_out_json := jsonb_strip_nulls(
        v_payload_out_json
        || jsonb_build_object(
          'dedupe_key', v_dedupe_key,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'queue_identity_targeted_timesheet_ids', COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb),
          'queue_identity_linked_timesheet_ids', COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb),
          'projection_run_id', v_projection_run_id::text,
          'source_change_seq', COALESCE(v_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_source_change_seq, 0),
          'latest_source_change_seq', COALESCE(v_source_change_seq, 0),
          'delta_coalescing_key', v_delta_coalescing_key,
          'delta_family_key', v_delta_coalescing_key,
          'normalised_delta_family_key', v_delta_coalescing_key,
          'delta_coalescing_hash', v_delta_coalescing_hash,
          'coalesced_event_count', GREATEST(COALESCE(v_merged_delta_event_count, 1), 1),
          'coalesced_source_change_seqs', jsonb_build_array(COALESCE(v_existing_delta_source_change_seq, 0), COALESCE(v_source_change_seq, 0)),
          'latest_event_at_utc', v_now::text,
          'scope_merge_applied', true,
          'scope_merge_at_utc', v_now::text,
          'cursor_json', '{}'::jsonb,
          'continuation', false,
          'phase', 'INIT_PREFLIGHT',
          'run_mode', CASE WHEN v_delta_active_running_job_id IS NULL THEN 'LATEST_STATE_HEAD' ELSE 'LATEST_RERUN_AFTER_RUNNING' END
        )
      );

      UPDATE public.banking_pay_workbench_jobs AS existing_delta_update
      SET dedupe_key = v_dedupe_key,
          priority = LEAST(existing_delta_update.priority, 43),
          run_at_utc = LEAST(existing_delta_update.run_at_utc, v_now),
          payload_json = v_payload_out_json,
          updated_at_utc = v_now
      WHERE existing_delta_update.id = v_existing_delta_job.id
      RETURNING existing_delta_update.id,
                existing_delta_update.status,
                false
      INTO v_job_id,
           v_job_status,
           v_job_was_inserted;

      v_delta_merge_reused_existing := true;
    END IF;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_payload_out_json := jsonb_strip_nulls(
      (COALESCE(v_payload_out_json, '{}'::jsonb) - ARRAY[
        'old_row_json',
        'new_row_json',
        'old_row',
        'new_row',
        'source_row_json',
        'work_payload_json',
        'result_row_json',
        'preview_row_json',
        'row_payload_json',
        'line_payload_json',
        'projection_rows',
        'projected_rows',
        'cursor',
        'cursor_json',
        'next_cursor',
        'next_cursor_json',
        'source_cursor',
        'write_cursor_json',
        'candidate_cursor',
        'cursor_token',
        'has_cursor',
        'continuation_reason',
        'source_job_id',
        'continuation_source_job_id',
        'bounded_continuation_source_job_id',
        'parent_job_id',
        'next_phase',
        'write_phase',
        'source_result_summary',
        'source_result_has_more',
        'source_result_next_cursor_present'
      ]::text[])
      || jsonb_build_object(
        'continuation', false,
        'cursor_json', '{}'::jsonb,
        'run_mode', CASE WHEN v_delta_active_running_job_id IS NULL THEN 'LATEST_STATE_HEAD' ELSE 'LATEST_RERUN_AFTER_RUNNING' END,
        'phase', 'INIT_PREFLIGHT'
      )
    );
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
    UPDATE public.banking_pay_workbench_jobs AS queued_delta_job
    SET status = 'SUCCEEDED',
        completed_at_utc = v_now,
        updated_at_utc = v_now,
        payload_json = jsonb_strip_nulls(
          COALESCE(queued_delta_job.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_legacy', true,
            'superseded_by_legacy_at_utc', v_now::text,
            'superseded_reason', COALESCE(NULLIF(v_classifier_result->>'fallback_reason', ''), 'LEGACY_REFRESH_WINS'),
            'legacy_source_change_seq', COALESCE(v_source_change_seq, 0)
          )
        )
    WHERE queued_delta_job.session_id = v_session_id
      AND queued_delta_job.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(queued_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
      AND UPPER(BTRIM(COALESCE(queued_delta_job.status, ''))) = 'QUEUED';
    GET DIAGNOSTICS v_delta_jobs_superseded = ROW_COUNT;
  END IF;

  IF v_job_id IS NULL THEN
    INSERT INTO public.banking_pay_workbench_jobs AS enqueue_job (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      economic_build_id,
      private_stage,
      private_cursor_kind,
      private_cursor_json,
      private_stage_version,
      created_at_utc,
      updated_at_utc,
      started_at_utc,
      completed_at_utc,
      failed_at_utc,
      last_error_json
    )
    VALUES (
      v_job_type,
      'QUEUED',
      CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 43 ELSE 44 END,
      v_now,
      0,
      8,
      v_dedupe_key,
      p_snapshot_run_id,
      v_session_id,
      p_candidate_id,
      v_payload_out_json,
      NULL::uuid,
      CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 'BUILD_INITIALISE' ELSE NULL::text END,
      CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 'BUILD_INITIALISE' ELSE NULL::text END,
      '{}'::jsonb,
      CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 1 ELSE NULL::integer END,
      v_now,
      v_now,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::timestamptz,
      NULL::jsonb
    )
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(enqueue_job.priority, EXCLUDED.priority),
        run_at_utc = LEAST(enqueue_job.run_at_utc, EXCLUDED.run_at_utc),
        payload_json = CASE
          WHEN EXCLUDED.job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
            jsonb_strip_nulls(
              (public._pay_workbench_merge_targeted_scope_payload(
                COALESCE(enqueue_job.payload_json, '{}'::jsonb),
                COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
              ) - ARRAY[
                'cursor',
                'cursor_json',
                'next_cursor',
                'next_cursor_json',
                'source_cursor',
                'write_cursor_json',
                'candidate_cursor',
                'cursor_token',
                'has_cursor',
                'continuation_reason',
                'source_job_id',
                'continuation_source_job_id',
                'bounded_continuation_source_job_id',
                'parent_job_id',
                'next_phase',
                'write_phase',
                'source_result_summary',
                'source_result_has_more',
                'source_result_next_cursor_present'
              ]::text[])
              || jsonb_build_object(
                'cursor_json', '{}'::jsonb,
                'continuation', false,
                'phase', 'INIT_PREFLIGHT',
                'run_mode', CASE
                  WHEN lower(BTRIM(COALESCE(EXCLUDED.payload_json->>'waiting_after_running_delta_job', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'LATEST_RERUN_AFTER_RUNNING'
                  ELSE 'LATEST_STATE_HEAD'
                END,
                'latest_source_change_seq', GREATEST(
                  CASE WHEN COALESCE(enqueue_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (enqueue_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(enqueue_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (enqueue_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END
                )
              )
            )
          ELSE public._pay_workbench_merge_targeted_scope_payload(
            COALESCE(enqueue_job.payload_json, '{}'::jsonb),
            COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
          )
        END,
        updated_at_utc = v_now
    WHERE NOT (
      UPPER(BTRIM(COALESCE(enqueue_job.status, ''))) = 'RUNNING'
      AND EXCLUDED.job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    )
    RETURNING enqueue_job.id,
              enqueue_job.status,
              (xmax = 0)
    INTO v_job_id, v_job_status, v_job_was_inserted;

    GET DIAGNOSTICS v_insert_row_count = ROW_COUNT;

    IF COALESCE(v_insert_row_count, 0) = 0
       AND v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
      SELECT running_delta_job.id
      INTO v_delta_active_running_job_id
      FROM public.banking_pay_workbench_jobs AS running_delta_job
      WHERE running_delta_job.session_id = v_session_id
        AND running_delta_job.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(running_delta_job.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
        AND UPPER(BTRIM(COALESCE(running_delta_job.status, ''))) = 'RUNNING'
        AND (
          COALESCE(running_delta_job.payload_json->>'normalised_delta_family_key', running_delta_job.payload_json->>'delta_family_key', running_delta_job.payload_json->>'delta_coalescing_key', '') = v_delta_coalescing_key
          OR (
            SELECT
              'WORKBENCH_CANDIDATE_DELTA_REFRESH_FAMILY'
              || ':session:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.session_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'source_session_id',
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'target_session_id',
                ''
              )), ''), 'none')
              || ':version:' || COALESCE(
                CASE
                  WHEN delta_family_values.session_version_text ~ '^-?[0-9]{1,18}$'
                    THEN delta_family_values.session_version_text::bigint
                  ELSE COALESCE(COALESCE(v_session_row.version, 0), 0)::bigint
                END,
                0
              )::text
              || ':projection_mode:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_mode_text, ''),
                NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                'DELTA'
              ))), ''), 'DELTA')
              || ':projection_class:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.projection_class_text, ''),
                NULLIF(v_projection_class, ''),
                'UNKNOWN'
              ))), ''), 'UNKNOWN')
              || ':refresh_scope:' || COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
                NULLIF(delta_family_values.refresh_scope_kind_text, ''),
                NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), ''),
                CASE
                  WHEN jsonb_array_length(COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)) > 0
                    OR jsonb_array_length(COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)) > 0
                    THEN 'TARGETED_TIMESHEETS'
                  ELSE 'CANDIDATE_FULL_LIVE'
                END
              ))), ''), 'CANDIDATE_FULL_LIVE')
              || ':candidate:' || COALESCE(NULLIF(BTRIM(COALESCE(
                running_delta_job.candidate_id::text,
                (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'candidate_id',
                ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{candidate,id}'),
                ''
              )), ''), 'none')
              || ':timesheets:' || md5(
                COALESCE(delta_family_targeted.targeted_timesheet_ids_json, '[]'::jsonb)::text
                || ':'
                || COALESCE(delta_family_linked.linked_timesheet_ids_json, '[]'::jsonb)::text
              )
            FROM (
              SELECT
                NULLIF(BTRIM(COALESCE(
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'workbench_session_version',
                  (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'version',
                  CASE WHEN COALESCE(v_session_row.version, 0) IS NULL THEN NULL ELSE (COALESCE(v_session_row.version, 0))::text END,
                  '0'
                )), '') AS session_version_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'resolved_mode', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'mode', ''),
                  NULLIF(COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA'), ''),
                  'DELTA'
                ))) AS projection_mode_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'projection_class', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'classifier_projection_class', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{classifier_result,projection_class}'), ''),
                  NULLIF(v_projection_class, ''),
                  'UNKNOWN'
                ))) AS projection_class_text,
                UPPER(BTRIM(COALESCE(
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'refresh_scope_kind', ''),
                  NULLIF((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'scope_kind', ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{source_build,refresh_scope_kind}'), ''),
                  NULLIF(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>>'{preview_decisions_json,refresh_scope_kind}'), ''),
                  NULLIF(COALESCE(NULLIF(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE'), 'TARGETED_TIMESHEETS'), '')
                ))) AS refresh_scope_kind_text
            ) AS delta_family_values
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_targeted_sorted.timesheet_id_text ORDER BY delta_family_targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_targeted_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'targeted_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,targeted_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,targeted_timesheet_ids}')
                    WHEN NULLIF(BTRIM(COALESCE(
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                           (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id',
                           ''
                         )), '') IS NOT NULL
                      THEN jsonb_build_array(COALESCE(
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'targeted_timesheet_id',
                        (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'timesheet_id'
                      ))
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_targeted_raw(value)
                WHERE NULLIF(BTRIM(delta_family_targeted_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_targeted_sorted
            ) AS delta_family_targeted
            CROSS JOIN (
              SELECT COALESCE(jsonb_agg(delta_family_linked_sorted.timesheet_id_text ORDER BY delta_family_linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
              FROM (
                SELECT DISTINCT NULLIF(BTRIM(delta_family_linked_raw.value), '') AS timesheet_id_text
                FROM jsonb_array_elements_text(
                  CASE
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'array'
                      THEN (COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids'
                    WHEN jsonb_typeof((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->'linked_timesheet_ids') = 'string'
                      THEN jsonb_build_array((COALESCE(running_delta_job.payload_json, '{}'::jsonb))->>'linked_timesheet_ids')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{source_build,linked_timesheet_ids}')
                    WHEN jsonb_typeof(((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')) = 'array'
                      THEN ((COALESCE(running_delta_job.payload_json, '{}'::jsonb))#>'{preview_decisions_json,linked_timesheet_ids}')
                    ELSE '[]'::jsonb
                  END
                ) AS delta_family_linked_raw(value)
                WHERE NULLIF(BTRIM(delta_family_linked_raw.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ) AS delta_family_linked_sorted
            ) AS delta_family_linked
          ) = v_delta_coalescing_key
          OR running_delta_job.dedupe_key = v_dedupe_key
        )
      ORDER BY running_delta_job.started_at_utc ASC NULLS LAST, running_delta_job.created_at_utc ASC, running_delta_job.id ASC
      LIMIT 1;

      IF v_delta_active_running_job_id IS NOT NULL THEN
        v_dedupe_key := v_delta_coalescing_key || ':waiting_after_running:' || v_delta_active_running_job_id::text;

        v_payload_out_json := jsonb_strip_nulls(
          COALESCE(v_payload_out_json, '{}'::jsonb)
          || jsonb_build_object(
            'dedupe_key', v_dedupe_key,
            'delta_active_running_job_id', v_delta_active_running_job_id::text,
            'waiting_after_running_delta_job', true,
            'waiting_after_running_enqueued_at_utc', v_now::text,
            'delta_running_conflict_fail_closed', true
          )
        );

        INSERT INTO public.banking_pay_workbench_jobs AS waiting_enqueue_job (
          job_type,
          status,
          priority,
          run_at_utc,
          attempt_count,
          max_attempts,
          dedupe_key,
          snapshot_run_id,
          session_id,
          candidate_id,
          payload_json,
          economic_build_id,
          private_stage,
          private_cursor_kind,
          private_cursor_json,
          private_stage_version,
          created_at_utc,
          updated_at_utc,
          started_at_utc,
          completed_at_utc,
          failed_at_utc,
          last_error_json
        )
        VALUES (
          v_job_type,
          'QUEUED',
          43,
          v_now,
          0,
          8,
          v_dedupe_key,
          p_snapshot_run_id,
          v_session_id,
          p_candidate_id,
          v_payload_out_json,
          NULL::uuid,
          CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 'BUILD_INITIALISE' ELSE NULL::text END,
          CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 'BUILD_INITIALISE' ELSE NULL::text END,
          '{}'::jsonb,
          CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 1 ELSE NULL::integer END,
          v_now,
          v_now,
          NULL::timestamptz,
          NULL::timestamptz,
          NULL::timestamptz,
          NULL::jsonb
        )
        ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
        DO UPDATE
        SET priority = LEAST(waiting_enqueue_job.priority, EXCLUDED.priority),
            run_at_utc = LEAST(waiting_enqueue_job.run_at_utc, EXCLUDED.run_at_utc),
            payload_json = jsonb_strip_nulls(
              (public._pay_workbench_merge_targeted_scope_payload(
                COALESCE(waiting_enqueue_job.payload_json, '{}'::jsonb),
                COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
              ) - ARRAY[
                'cursor',
                'cursor_json',
                'next_cursor',
                'next_cursor_json',
                'source_cursor',
                'write_cursor_json',
                'candidate_cursor',
                'cursor_token',
                'has_cursor',
                'continuation_reason',
                'source_job_id',
                'continuation_source_job_id',
                'bounded_continuation_source_job_id',
                'parent_job_id',
                'next_phase',
                'write_phase',
                'source_result_summary',
                'source_result_has_more',
                'source_result_next_cursor_present'
              ]::text[])
              || jsonb_build_object(
                'cursor_json', '{}'::jsonb,
                'continuation', false,
                'phase', 'INIT_PREFLIGHT',
                'run_mode', 'LATEST_RERUN_AFTER_RUNNING',
                'waiting_after_running_delta_job', true,
                'latest_source_change_seq', GREATEST(
                  CASE WHEN COALESCE(waiting_enqueue_job.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (waiting_enqueue_job.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(waiting_enqueue_job.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (waiting_enqueue_job.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'latest_source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'latest_source_change_seq')::bigint ELSE 0::bigint END,
                  CASE WHEN COALESCE(EXCLUDED.payload_json->>'source_change_seq', '') ~ '^-?[0-9]{1,18}$' THEN (EXCLUDED.payload_json->>'source_change_seq')::bigint ELSE 0::bigint END
                )
              )
            ),
            updated_at_utc = v_now
        WHERE UPPER(BTRIM(COALESCE(waiting_enqueue_job.status, ''))) <> 'RUNNING'
        RETURNING waiting_enqueue_job.id,
                  waiting_enqueue_job.status,
                  (xmax = 0)
        INTO v_job_id, v_job_status, v_job_was_inserted;

        GET DIAGNOSTICS v_insert_row_count = ROW_COUNT;
      END IF;
    END IF;

    IF v_job_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_ACTIVE_DELTA_HEAD_CONFLICT'
        USING ERRCODE = '55000',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_ENQUEUE_CANDIDATE_REFRESH_ACTIVE_DELTA_HEAD_CONFLICT',
                'session_id', v_session_id::text,
                'candidate_id', p_candidate_id::text,
                'job_type', v_job_type,
                'delta_coalescing_key', v_delta_coalescing_key,
                'dedupe_key', v_dedupe_key,
                'active_running_job_id', CASE WHEN v_delta_active_running_job_id IS NULL THEN NULL ELSE v_delta_active_running_job_id::text END,
                'message', 'A running delta refresh head was detected during enqueue conflict handling and a safe waiting-head could not be created.'
              )::text;
    END IF;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
    v_owner_resolution := CASE
      WHEN v_job_was_inserted THEN 'NEW_OWNER_CREATED'
      ELSE 'ACTIVE_ROOT_JOB_REUSED'
    END;
  END IF;

  UPDATE public.banking_pay_workbench_session_scope AS session_scope
  SET status = CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 'DELTA_REFRESH_PENDING' ELSE 'SOURCE_BUILD_PENDING' END,
      pending_job_id = v_job_id,
      dirty = true,
      error_json = NULL::jsonb,
      updated_at_utc = v_now
  WHERE session_scope.session_id = v_session_id
    AND session_scope.candidate_id = p_candidate_id;

  /*
    The certified publisher requires one session-candidate state row carrying
    the exact session version and source sequence owned by this refresh.  A
    freshly seeded or force-reseeded scope can legitimately have no state row
    yet.  Establish that pending owner here, alongside the canonical job/scope
    enqueue, rather than allowing the completed build to reach publication
    with no state authority to adopt.

    Existing fragments are deliberately retained on conflict for display
    continuity, but they are no longer READY authority while this job owns the
    candidate.  A state row from a newer source sequence or session version is
    never overwritten by an older enqueue.
  */
  INSERT INTO public.banking_pay_workbench_session_candidate_state AS candidate_state (
    session_id,
    candidate_id,
    status,
    source_change_seq,
    session_version,
    pending_job_id,
    created_at_utc,
    updated_at_utc,
    last_error_json
  )
  VALUES (
    v_session_id,
    p_candidate_id,
    'PENDING',
    COALESCE(v_source_change_seq, 0),
    COALESCE(v_session_row.version, 1),
    v_job_id,
    v_now,
    v_now,
    NULL::jsonb
  )
  ON CONFLICT (session_id, candidate_id)
  DO UPDATE
  SET status = 'PENDING',
      source_change_seq = EXCLUDED.source_change_seq,
      session_version = EXCLUDED.session_version,
      pending_job_id = EXCLUDED.pending_job_id,
      updated_at_utc = v_now,
      last_error_json = NULL::jsonb
  WHERE candidate_state.source_change_seq <= EXCLUDED.source_change_seq
    AND candidate_state.session_version <= EXCLUDED.session_version;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL::jsonb,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', v_job_type,
    'resolved_mode', v_resolved_mode,
      'status', v_job_status,
      'snapshot_run_id', p_snapshot_run_id::text,
      'session_id', v_session_id::text,
      'candidate_id', p_candidate_id::text,
      'dedupe_key', v_dedupe_key,
      'source_change_seq', COALESCE(v_source_change_seq, 0),
      'source_build_run_id', CASE WHEN v_source_build_run_id IS NULL THEN NULL ELSE v_source_build_run_id::text END,
      'projection_run_id', CASE WHEN v_projection_run_id IS NULL THEN NULL ELSE v_projection_run_id::text END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_count', jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)),
      'linked_timesheet_count', jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)),
      'queue_identity_targeted_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
      'queue_identity_linked_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
      'source_build_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'line_work_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'delta_refresh_required', v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'delta_scope_merge_reused_existing', COALESCE(v_delta_merge_reused_existing, false),
      'delta_coalescing_key', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_key ELSE NULL::text END,
      'delta_coalescing_hash', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_hash ELSE NULL::text END,
      'delta_active_running_job_id', CASE WHEN v_delta_active_running_job_id IS NULL THEN NULL ELSE v_delta_active_running_job_id::text END,
      'delta_jobs_superseded_by_legacy', COALESCE(v_delta_jobs_superseded, 0)
    ),
    'WORKBENCH_CANDIDATE_REFRESH_JOB_ENQUEUE',
    v_actor_user_id
  );

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'canonical_job_type', v_job_type,
    'resolved_mode', v_resolved_mode,
    'snapshot_run_id', p_snapshot_run_id::text,
    'session_id', v_session_id::text,
    'candidate_id', p_candidate_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'source_change_seq', COALESCE(v_source_change_seq, 0),
    'registry_source_change_seq', COALESCE(v_registry_source_change_seq_after, v_source_change_seq, 0),
    'registry_sequence_synchronised', COALESCE(v_registry_sequence_synchronised, false),
    'source_build_run_id', CASE WHEN v_source_build_run_id IS NULL THEN NULL ELSE v_source_build_run_id::text END,
    'projection_run_id', CASE WHEN v_projection_run_id IS NULL THEN NULL ELSE v_projection_run_id::text END,
    'dedupe_key', v_dedupe_key,
    'reason', v_reason,
    'refresh_scope_kind', v_refresh_scope_kind,
    'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
    'queue_identity_targeted_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_targeted_timesheet_ids_json, v_targeted_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
    'queue_identity_linked_timesheet_ids', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(v_queue_identity_linked_timesheet_ids_json, v_linked_timesheet_ids_json, '[]'::jsonb) ELSE NULL::jsonb END,
    'pay_channel_scope', v_pay_channel_scope,
    'source_build_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'line_work_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'line_work_only', false,
    'delta_refresh_required', v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
    'scope_status', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 'DELTA_REFRESH_PENDING' ELSE 'SOURCE_BUILD_PENDING' END,
    'projection_mode', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN COALESCE(NULLIF(v_projection_mode, 'LEGACY'), 'DELTA') ELSE NULL::text END,
    'projection_class', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_projection_class ELSE NULL::text END,
    'full_snapshot_job', false,
    'reused', NOT v_job_was_inserted,
    'coalesced', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' AND NOT v_job_was_inserted,
    'new_owner_created', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' AND v_job_was_inserted,
    'owner_resolution', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN v_owner_resolution ELSE NULL::text END,
    'authority_fingerprint_version', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN v_authority_fingerprint_version ELSE NULL::integer END,
    'required_physical_publication_contract_version', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN v_required_physical_publication_contract_version ELSE NULL::integer END,
    'authority_fingerprint', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN v_authority_fingerprint ELSE NULL::text END,
    'owner_root_job_id', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN v_job_id::text ELSE NULL::text END,
    'requested_coverage', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 'FULL_CANDIDATE' ELSE NULL::text END,
    'owner_coverage', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 'FULL_CANDIDATE' ELSE NULL::text END,
    'owner_source_build_run_id', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN v_source_build_run_id::text ELSE NULL::text END,
    'delta_scope_merge_reused_existing', COALESCE(v_delta_merge_reused_existing, false),
    'delta_coalescing_key', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_key ELSE NULL::text END,
    'delta_coalescing_hash', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_coalescing_hash ELSE NULL::text END,
    'delta_active_running_job_id', CASE WHEN v_delta_active_running_job_id IS NULL THEN NULL ELSE v_delta_active_running_job_id::text END,
    'delta_jobs_superseded_by_legacy', COALESCE(v_delta_jobs_superseded, 0),
    'classifier_result', v_classifier_result
  ));
END;
$function$;

-- pay_workbench_enqueue_expired_snooze_refreshes_v1(uuid,integer,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_expired_snooze_refreshes_v1(p_session_id uuid DEFAULT NULL::uuid, p_session_limit integer DEFAULT 25, p_candidate_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_date_context jsonb := public.pay_banking_official_date_context_v1(NULL::timestamptz);
  v_today_uk date;
  v_current_official_pay_date date;
  v_limit integer := LEAST(GREATEST(COALESCE(p_candidate_limit, 100), 1), 100);
  v_actor_user_id uuid;
  v_due record;
  v_transition jsonb := '{}'::jsonb;
  v_enqueue jsonb := '{}'::jsonb;
  v_examined integer := 0;
  v_changed integer := 0;
  v_unchanged integer := 0;
  v_marked integer := 0;
  v_marker_rows integer := 0;
  v_failed integer := 0;
  v_enqueued integer := 0;
  v_more_due boolean := false;
  v_results jsonb := '[]'::jsonb;
BEGIN
  v_today_uk := (v_date_context->>'business_date')::date;
  v_current_official_pay_date := (v_date_context->>'current_official_pay_date')::date;

  SELECT session_row.actor_user_id
  INTO v_actor_user_id
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
    AND session_row.discarded_at_utc IS NULL
    AND session_row.replacement_session_id IS NULL
    AND (p_session_id IS NULL OR session_row.id = p_session_id)
  ORDER BY session_row.updated_at_utc DESC, session_row.id
  LIMIT 1;

  IF v_actor_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'processed_session_count', 0,
      'due_examined_count', 0,
      'state_changed_count', 0,
      'unchanged_due_count', 0,
      'check_marker_updated_count', 0,
      'transition_failed_count', 0,
      'has_more_unchecked_due', false,
      'reason', 'NO_CURRENT_OPEN_SESSION'
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_unchecked_due_snoozes;
  CREATE TEMP TABLE _bpay_unchecked_due_snoozes ON COMMIT DROP AS
  WITH locked_due AS (
    SELECT snooze_row.id
    FROM public.pay_item_snoozes AS snooze_row
    WHERE snooze_row.cleared_at_utc IS NULL
      AND snooze_row.cancelled_at_utc IS NULL
      AND snooze_row.snooze_until_date IS NOT NULL
      AND snooze_row.snooze_until_date < v_today_uk
      AND snooze_row.natural_expiry_source_fingerprint IS NOT NULL
      AND snooze_row.natural_expiry_checked_fingerprint
            IS DISTINCT FROM snooze_row.natural_expiry_source_fingerprint
    ORDER BY snooze_row.snooze_until_date, snooze_row.candidate_id, snooze_row.id
    FOR UPDATE SKIP LOCKED
    LIMIT v_limit
  )
  SELECT snooze_row.id,
         snooze_row.candidate_id,
         snooze_row.timesheet_id,
         snooze_row.snooze_until_date,
         snooze_row.natural_expiry_source_fingerprint
  FROM public.pay_item_snoozes AS snooze_row
  JOIN locked_due ON locked_due.id = snooze_row.id
  ORDER BY snooze_row.snooze_until_date, snooze_row.candidate_id, snooze_row.id;

  FOR v_due IN
    SELECT due_snooze.*
    FROM pg_temp._bpay_unchecked_due_snoozes AS due_snooze
    ORDER BY due_snooze.snooze_until_date, due_snooze.candidate_id, due_snooze.id
  LOOP
    BEGIN
      v_examined := v_examined + 1;
      v_transition := public.pay_snooze_resolution_transition_v1(
        p_snooze_id => v_due.id,
        p_actor_user_id => v_actor_user_id,
        p_transition_reason => 'NATURAL_EXPIRY'
      );

      UPDATE public.pay_item_snoozes AS snooze_update
      SET natural_expiry_checked_fingerprint = v_due.natural_expiry_source_fingerprint,
          natural_expiry_checked_at_utc = v_now,
          natural_expiry_state_changed = LOWER(BTRIM(COALESCE(v_transition->>'state_changed', 'false')))
            IN ('true', 't', '1', 'yes', 'y', 'on'),
          natural_expiry_result_code = LEFT(COALESCE(
            NULLIF(BTRIM(v_transition->>'code'), ''),
            NULLIF(BTRIM(v_transition->>'reason'), ''),
            'NATURAL_EXPIRY_EVALUATED'
          ), 200)
      WHERE snooze_update.id = v_due.id
        AND snooze_update.natural_expiry_source_fingerprint = v_due.natural_expiry_source_fingerprint;
      GET DIAGNOSTICS v_marker_rows = ROW_COUNT;
      v_marked := v_marked + v_marker_rows;

      IF LOWER(BTRIM(COALESCE(v_transition->>'state_changed', 'false')))
           IN ('true', 't', '1', 'yes', 'y', 'on') THEN
        v_changed := v_changed + 1;
        v_enqueue := public.pay_workbench_dirty_event_enqueue(
          p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
          p_scope_kind => 'CANDIDATE',
          p_scope_id => v_due.candidate_id::text,
          p_candidate_id => v_due.candidate_id,
          p_targeted_timesheet_ids => CASE
            WHEN v_due.timesheet_id IS NULL THEN ARRAY[]::uuid[]
            ELSE ARRAY[v_due.timesheet_id]::uuid[]
          END,
          p_linked_timesheet_ids => ARRAY[]::uuid[],
          p_payload_json => jsonb_build_object(
            'refresh_scope_kind', CASE
              WHEN v_due.timesheet_id IS NULL THEN 'CANDIDATE_FULL_LIVE'
              ELSE 'TARGETED_TIMESHEETS'
            END,
            'snooze_id', v_due.id::text,
            'london_current_date', v_today_uk::text,
            'current_official_pay_date', v_current_official_pay_date::text,
            'reason', 'SNOOZE_EXPIRED_LONDON_DATE',
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          ),
          p_reason => 'SNOOZE_EXPIRED_LONDON_DATE',
          p_priority => -1000,
          p_run_at_utc => v_now
        );
        v_enqueued := v_enqueued + 1;
        v_results := v_results || jsonb_build_array(jsonb_build_object(
          'candidate_id', v_due.candidate_id::text,
          'snooze_id', v_due.id::text,
          'job_id', v_enqueue->>'job_id'
        ));
      ELSE
        v_unchanged := v_unchanged + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'snooze_id', v_due.id::text,
        'transition_failed', true,
        'sqlstate', SQLSTATE
      ));
    END;
  END LOOP;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_item_snoozes AS snooze_row
    WHERE snooze_row.cleared_at_utc IS NULL
      AND snooze_row.cancelled_at_utc IS NULL
      AND snooze_row.snooze_until_date IS NOT NULL
      AND snooze_row.snooze_until_date < v_today_uk
      AND snooze_row.natural_expiry_source_fingerprint IS NOT NULL
      AND snooze_row.natural_expiry_checked_fingerprint
            IS DISTINCT FROM snooze_row.natural_expiry_source_fingerprint
  ) INTO v_more_due;

  RETURN jsonb_build_object(
    'ok', v_failed = 0,
    'global_due_scan', true,
    'processed_session_count', 1,
    'due_examined_count', v_examined,
    'state_changed_count', v_changed,
    'unchanged_due_count', v_unchanged,
    'check_marker_updated_count', v_marked,
    'transition_failed_count', v_failed,
    'enqueued_count', v_enqueued,
    'has_more_unchecked_due', v_more_due,
    'work_limit', v_limit,
    'results', v_results
  );
END;
$function$;

-- pay_workbench_enqueue_payee_readiness_ensure(uuid,jsonb,uuid,uuid,text,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_payee_readiness_ensure(p_candidate_id uuid, p_payees_json jsonb, p_snapshot_run_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_source_change_seq bigint := 0;
  v_session_version bigint := NULL;
  v_resolved_snapshot_run_id uuid := p_snapshot_run_id;
  v_readiness_fingerprint text := md5(COALESCE(p_payees_json::text, '[]'));
  v_dedupe_key text;
  v_job_id uuid;
  v_job_status text;
  v_job_was_inserted boolean := false;
  v_completed_job_id uuid := NULL;
  v_completed_job_status text := NULL;
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  PERFORM 1
  FROM public.candidates AS c
  WHERE c.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidates row % not found', p_candidate_id;
  END IF;

  IF p_payees_json IS NULL THEN
    RAISE EXCEPTION 'payees_json is required';
  END IF;

  IF jsonb_typeof(p_payees_json) <> 'array' THEN
    RAISE EXCEPTION 'payees_json must be a JSON array';
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT ws.source_snapshot_run_id, ws.version
    INTO v_resolved_snapshot_run_id, v_session_version
    FROM public.banking_pay_workbench_sessions AS ws
    WHERE ws.id = p_session_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
    END IF;
  END IF;

  IF v_resolved_snapshot_run_id IS NOT NULL THEN
    SELECT COALESCE(snap.source_change_seq, 0)
    INTO v_source_change_seq
    FROM public.banking_pay_snapshot_candidate_state AS snap
    WHERE snap.snapshot_run_id = v_resolved_snapshot_run_id
      AND snap.candidate_id = p_candidate_id;
  END IF;

  IF v_source_change_seq = 0 THEN
    SELECT COALESCE(acc.seq, 0)
    INTO v_source_change_seq
    FROM public.app_change_counters AS acc
    WHERE acc.entity_key = 'pay_candidate:' || p_candidate_id::text;
  END IF;

  v_dedupe_key := 'PAYEE_READINESS_ENSURE:'
    || COALESCE(v_resolved_snapshot_run_id::text, 'no-run')
    || ':'
    || COALESCE(p_session_id::text, 'no-session')
    || ':'
    || p_candidate_id::text
    || ':s'
    || v_source_change_seq::text
    || ':'
    || v_readiness_fingerprint;

  SELECT j.id, j.status
  INTO v_completed_job_id, v_completed_job_status
  FROM public.banking_pay_workbench_jobs AS j
  WHERE j.job_type = 'PAYEE_READINESS_ENSURE'
    AND j.dedupe_key = v_dedupe_key
    AND j.completed_at_utc IS NOT NULL
    AND j.failed_at_utc IS NULL
  ORDER BY j.completed_at_utc DESC, j.id DESC
  LIMIT 1;

  IF v_completed_job_id IS NOT NULL THEN
    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_completed_job_id::text,
      'NO_OP',
      NULL,
      jsonb_build_object(
        'id', v_completed_job_id::text,
        'job_type', 'PAYEE_READINESS_ENSURE',
        'status', v_completed_job_status,
        'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
        'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
        'candidate_id', p_candidate_id::text,
        'session_version', v_session_version,
        'source_change_seq', v_source_change_seq,
        'dedupe_key', v_dedupe_key,
        'reason', p_reason,
        'readiness_fingerprint', v_readiness_fingerprint
      ),
      'WORKBENCH_JOB_ENQUEUE',
      p_actor_user_id
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_completed_job_id::text,
      'job_type', 'PAYEE_READINESS_ENSURE',
      'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
      'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_change_seq', v_source_change_seq,
      'dedupe_key', v_dedupe_key,
      'reason', p_reason,
      'readiness_fingerprint', v_readiness_fingerprint,
      'no_op', true,
      'reused', false
    );
  END IF;

  INSERT INTO public.banking_pay_workbench_jobs (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    'PAYEE_READINESS_ENSURE',
    'QUEUED',
    100,
    v_now,
    0,
    8,
    v_dedupe_key,
    v_resolved_snapshot_run_id,
    p_session_id,
    p_candidate_id,
    COALESCE(p_payload_json, '{}'::jsonb)
      || jsonb_build_object(
        'reason', p_reason,
        'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
        'candidate_id', p_candidate_id::text,
        'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
        'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
        'session_version', v_session_version,
        'source_change_seq', v_source_change_seq,
        'payees_json', p_payees_json,
        'job_type', 'PAYEE_READINESS_ENSURE',
        'readiness_fingerprint', v_readiness_fingerprint
      ),
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
      run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
      payload_json = COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || COALESCE(EXCLUDED.payload_json, '{}'::jsonb),
      updated_at_utc = v_now
  RETURNING public.banking_pay_workbench_jobs.id, public.banking_pay_workbench_jobs.status, (xmax = 0)
  INTO v_job_id, v_job_status, v_job_was_inserted;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', 'PAYEE_READINESS_ENSURE',
      'status', v_job_status,
      'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
      'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_change_seq', v_source_change_seq,
      'dedupe_key', v_dedupe_key,
      'reason', p_reason,
      'readiness_fingerprint', v_readiness_fingerprint
    ),
    'WORKBENCH_JOB_ENQUEUE',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', 'PAYEE_READINESS_ENSURE',
    'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
    'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    'candidate_id', p_candidate_id::text,
    'session_version', v_session_version,
    'source_change_seq', v_source_change_seq,
    'dedupe_key', v_dedupe_key,
    'reason', p_reason,
    'readiness_fingerprint', v_readiness_fingerprint,
    'no_op', false,
    'reused', (NOT v_job_was_inserted)
  );
END;
$function$;

-- pay_workbench_enqueue_session_candidate_refresh(uuid,uuid,text,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_session_candidate_refresh(p_session_id uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_actor_user_id uuid := p_actor_user_id;
  v_page_limit integer := 100;
  v_cursor_scope_ordinal bigint := -1;
  v_page_candidate_ids jsonb := '[]'::jsonb;
  v_page_next_cursor jsonb := NULL::jsonb;
  v_page_enqueue_result jsonb := '{}'::jsonb;
  v_payload_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_direct_result jsonb := '{}'::jsonb;
  v_force_refresh boolean := false;
  v_discover_current_scope boolean := false;
  v_scope_seed_cursor_json jsonb := NULL::jsonb;
  v_scope_seed_result jsonb := '{}'::jsonb;
  v_scope_seed_enqueue_result jsonb := '{}'::jsonb;
  v_scope_seed_first_page boolean := false;
  v_scope_discovery_job_id uuid := gen_random_uuid();
  v_scope_discovery_job_dedupe_key text := NULL::text;
  v_scope_discovery_job_inserted boolean := false;
  v_scope_discovery_limit integer := 5;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status <> 'OPEN' OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  v_actor_user_id := COALESCE(v_actor_user_id, v_session_row.actor_user_id);

  v_force_refresh := LOWER(BTRIM(COALESCE(
    v_payload_json->>'force_refresh',
    v_payload_json->>'forceRefresh',
    v_payload_json->>'user_requested_refresh',
    v_payload_json->>'userRequestedRefresh',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_discover_current_scope := p_candidate_id IS NULL
    AND UPPER(BTRIM(COALESCE(
      v_payload_json->>'refresh_scope_kind',
      v_payload_json->>'refreshScopeKind',
      ''
    ))) IN ('SESSION_SCOPE_DISCOVERY', 'SESSION_FULL_LIVE', 'BROAD_SESSION_REFRESH');

  v_targeted_timesheet_ids_json := CASE
    WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'array' THEN v_payload_json->'targeted_timesheet_ids'
    WHEN jsonb_typeof(v_payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN v_payload_json#>'{source_build,targeted_timesheet_ids}'
    WHEN jsonb_typeof(v_payload_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_payload_json->>'targeted_timesheet_ids')
    ELSE '[]'::jsonb
  END;

  IF p_candidate_id IS NOT NULL THEN
    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = p_session_id
      AND scope_row.candidate_id = p_candidate_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, p_session_id;
    END IF;

    IF jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 THEN
      v_direct_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => p_candidate_id,
        p_reason => COALESCE(p_reason, 'SESSION_CANDIDATE_TARGETED_REFRESH'),
        p_actor_user_id => v_actor_user_id,
        p_payload_json => v_payload_json || jsonb_build_object(
          'session_id', p_session_id::text,
          'source_session_id', p_session_id::text,
          'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'session_version', COALESCE(v_session_row.version, 0),
          'session_signature', v_session_row.session_signature,
          'refresh_scope_kind', 'TARGETED_TIMESHEETS',
          'targeted_timesheet_ids', v_targeted_timesheet_ids_json
        )
      );

      RETURN jsonb_build_object(
        'ok', true,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'job_type', v_direct_result->>'job_type',
        'delta_queued_count', CASE WHEN UPPER(BTRIM(COALESCE(v_direct_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 1 ELSE 0 END,
        'legacy_queued_count', CASE WHEN UPPER(BTRIM(COALESCE(v_direct_result->>'job_type', ''))) = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN 0 ELSE 1 END,
        'paged', false,
        'candidate_count', 1,
        'next_cursor', NULL::jsonb,
        'has_more', false,
        'enqueue_result', COALESCE(v_direct_result, '{}'::jsonb)
      );
    END IF;

    v_page_enqueue_result := public.pay_workbench_enqueue_candidate_refresh_many(
      p_session_id => p_session_id,
      p_candidate_ids => jsonb_build_object(
        'candidate_ids', jsonb_build_array(p_candidate_id::text),
        'force_refresh', COALESCE(v_force_refresh, false),
        'user_requested_refresh', COALESCE(v_force_refresh, false)
      ),
      p_reason => COALESCE(p_reason, 'SESSION_CANDIDATE_LINE_WORK'),
      p_actor_user_id => v_actor_user_id
    );

    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'job_type', v_page_enqueue_result->>'first_stage_job_type',
      'delta_queued_count', COALESCE((v_page_enqueue_result->>'delta_queued_count')::integer, 0),
      'legacy_queued_count', COALESCE((v_page_enqueue_result->>'legacy_queued_count')::integer, 0),
      'paged', false,
      'candidate_count', 1,
      'enqueued_candidate_count', COALESCE((v_page_enqueue_result->>'enqueued_candidate_count')::integer, 0),
      'force_refresh', COALESCE(v_force_refresh, false),
      'next_cursor', NULL::jsonb,
      'has_more', false,
      'enqueue_result', COALESCE(v_page_enqueue_result, '{}'::jsonb)
    );
  END IF;

  IF v_discover_current_scope THEN
    IF UPPER(BTRIM(COALESCE(
      v_payload_json->>'refresh_scope_kind',
      v_payload_json->>'refreshScopeKind',
      ''
    ))) = 'SESSION_SCOPE_DISCOVERY' THEN
      /*
        Opening an attached Banking Pay session must remain a cheap queueing
        action. The existing bounded scope-seed worker expands the durable
        pay_candidate change-counter shortlist and live-validates each
        candidate. It must not synchronously walk every discovery page inside
        the HTTP request.
      */
      v_scope_discovery_limit := CASE
        WHEN COALESCE(v_payload_json->>'limit', '') ~ '^[0-9]+$'
          THEN LEAST(GREATEST((v_payload_json->>'limit')::integer, 1), 5)
        ELSE 5
      END;
      v_scope_discovery_job_dedupe_key :=
        'WORKBENCH_STAGE_CONTINUATION'
        || ':WORKBENCH_SESSION_SCOPE_DISCOVERY'
        || ':session:' || p_session_id::text
        || ':version:' || COALESCE(v_session_row.version, 0)::text
        || ':snapshot:' || COALESCE(v_session_row.source_snapshot_run_id::text, 'none')
        || ':candidate:ALL';

      /*
        Do not update an already queued/running discovery job merely because
        the modal reopened. A worker may hold that row while claiming or
        completing it; waiting for the row lock would turn a harmless open
        into an HTTP timeout. A normal MVCC read can reuse the committed job
        without waiting and preserves its existing retry schedule.
      */
      SELECT active_discovery_job.id
      INTO v_scope_discovery_job_id
      FROM public.banking_pay_workbench_jobs AS active_discovery_job
      WHERE active_discovery_job.dedupe_key = v_scope_discovery_job_dedupe_key
        AND active_discovery_job.status IN ('QUEUED', 'RUNNING')
      ORDER BY active_discovery_job.created_at_utc, active_discovery_job.id
      LIMIT 1;

      IF v_scope_discovery_job_id IS NULL THEN
        v_scope_discovery_job_id := gen_random_uuid();
        INSERT INTO public.banking_pay_workbench_jobs AS discovery_job (
          id,
          job_type,
          status,
          priority,
          run_at_utc,
          attempt_count,
          max_attempts,
          dedupe_key,
          snapshot_run_id,
          session_id,
          candidate_id,
          payload_json,
          created_at_utc,
          updated_at_utc,
          started_at_utc,
          completed_at_utc,
          failed_at_utc,
          last_error_json
        )
        VALUES (
          v_scope_discovery_job_id,
          'WORKBENCH_SESSION_SCOPE_SEED',
          'QUEUED',
          40,
          now(),
          0,
          8,
          v_scope_discovery_job_dedupe_key,
          v_session_row.source_snapshot_run_id,
          p_session_id,
          NULL::uuid,
          jsonb_build_object(
            'session_id', p_session_id::text,
            'session_version', COALESCE(v_session_row.version, 0),
            'snapshot_run_id', CASE
              WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL::text
              ELSE v_session_row.source_snapshot_run_id::text
            END,
            'session_signature', v_session_row.session_signature,
            'candidate_id', NULL::text,
            'job_type', 'WORKBENCH_SESSION_SCOPE_SEED',
            'dedupe_key', v_scope_discovery_job_dedupe_key,
            'continuation', false,
            'root_job', false,
            'reason', COALESCE(p_reason, 'WORKBENCH_SESSION_OPEN_SCOPE_DISCOVERY'),
            'continuation_reason', 'WORKBENCH_SESSION_OPEN_SCOPE_DISCOVERY',
            'line_work_action', 'SCOPE_DISCOVERY',
            'next_recommended_action', 'SEED_SCOPE_DISCOVERY_CHUNK',
            'limit', v_scope_discovery_limit,
            'line_limit', v_scope_discovery_limit,
            'chunk_size', v_scope_discovery_limit,
            'run_mode', 'BOUNDED_SCOPE_DISCOVERY',
            'line_work_required', false,
            'line_work_only', false,
            'cursor_json', jsonb_build_object(
              'force_reseed', true,
              'force_refresh', false,
              'user_requested_refresh', false,
              'scope_discovery_only', true
            ),
            'cursor', jsonb_build_object(
              'force_reseed', true,
              'force_refresh', false,
              'user_requested_refresh', false,
              'scope_discovery_only', true
            ),
            'cursor_token', 'scope-discovery-start',
            'has_cursor', true,
            'created_by_helper', 'pay_workbench_enqueue_session_candidate_refresh',
            'created_at_utc', now()::text
          ),
          now(),
          now(),
          NULL::timestamptz,
          NULL::timestamptz,
          NULL::timestamptz,
          NULL::jsonb
        )
        ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
        DO NOTHING
        RETURNING discovery_job.id
        INTO v_scope_discovery_job_id;

        v_scope_discovery_job_inserted := v_scope_discovery_job_id IS NOT NULL;

        IF v_scope_discovery_job_id IS NULL THEN
          SELECT concurrent_discovery_job.id
          INTO v_scope_discovery_job_id
          FROM public.banking_pay_workbench_jobs AS concurrent_discovery_job
          WHERE concurrent_discovery_job.dedupe_key = v_scope_discovery_job_dedupe_key
            AND concurrent_discovery_job.status IN ('QUEUED', 'RUNNING')
          ORDER BY concurrent_discovery_job.created_at_utc, concurrent_discovery_job.id
          LIMIT 1;
        END IF;
      END IF;

      IF v_scope_discovery_job_id IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_DISCOVERY_JOB_NOT_RESOLVED'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_SCOPE_DISCOVERY_JOB_NOT_RESOLVED',
                  'session_id', p_session_id::text
                )::text;
      END IF;

      RETURN jsonb_build_object(
        'ok', true,
        'session_id', p_session_id::text,
        'candidate_id', NULL::text,
        'paged', true,
        'scope_rediscovered', false,
        'scope_discovery_queued', true,
        'scope_discovery_job_id', v_scope_discovery_job_id::text,
        'scope_discovery_job_inserted', COALESCE(v_scope_discovery_job_inserted, false),
        'candidate_count', 0,
        'enqueued_candidate_count', 0,
        'force_refresh', false,
        'next_cursor', NULL::jsonb,
        'has_more', false,
        'delta_queued_count', 0,
        'legacy_queued_count', 0
      );
    END IF;

    v_scope_seed_cursor_json := CASE
      WHEN jsonb_typeof(v_payload_json->'cursor') = 'object'
        THEN COALESCE(v_payload_json->'cursor', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;
    v_scope_seed_first_page := v_scope_seed_cursor_json = '{}'::jsonb;
    v_scope_seed_cursor_json := v_scope_seed_cursor_json
      || jsonb_build_object(
        'force_reseed', v_scope_seed_first_page,
        'force_refresh', COALESCE(v_force_refresh, false),
        'user_requested_refresh', COALESCE(v_force_refresh, false),
        'scope_discovery_only', UPPER(BTRIM(COALESCE(
          v_payload_json->>'refresh_scope_kind',
          v_payload_json->>'refreshScopeKind',
          ''
        ))) = 'SESSION_SCOPE_DISCOVERY'
      );

    v_scope_seed_result := public.pay_workbench_session_seed_scope_chunk(
      p_session_id => p_session_id,
      p_cursor_json => v_scope_seed_cursor_json,
      p_limit => CASE
        WHEN COALESCE(v_payload_json->>'limit', '') ~ '^[0-9]+$'
          THEN LEAST(GREATEST((v_payload_json->>'limit')::integer, 1), 100)
        ELSE 100
      END
    );
    v_scope_seed_enqueue_result := CASE
      WHEN jsonb_typeof(v_scope_seed_result->'enqueue_result') = 'object'
        THEN COALESCE(v_scope_seed_result->'enqueue_result', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;

    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'candidate_id', NULL::text,
      'paged', true,
      'scope_rediscovered', true,
      'scope_reseed_started', v_scope_seed_first_page,
      'candidate_count', COALESCE(jsonb_array_length(
        CASE
          WHEN jsonb_typeof(v_scope_seed_result->'candidate_ids') = 'array'
            THEN v_scope_seed_result->'candidate_ids'
          ELSE '[]'::jsonb
        END
      ), 0),
      'enqueued_candidate_count', COALESCE(
        NULLIF(BTRIM(COALESCE(v_scope_seed_enqueue_result->>'enqueued_candidate_count', '')), '')::integer,
        NULLIF(BTRIM(COALESCE(v_scope_seed_result->>'enqueued_count', '')), '')::integer,
        0
      ),
      'force_refresh', COALESCE(v_force_refresh, false),
      'next_cursor', COALESCE(v_scope_seed_result->'next_cursor', NULL::jsonb),
      'has_more', COALESCE(NULLIF(BTRIM(COALESCE(v_scope_seed_result->>'has_more', '')), '')::boolean, false),
      'delta_queued_count', COALESCE(NULLIF(BTRIM(COALESCE(v_scope_seed_enqueue_result->>'delta_queued_count', '')), '')::integer, 0),
      'legacy_queued_count', COALESCE(NULLIF(BTRIM(COALESCE(v_scope_seed_enqueue_result->>'legacy_queued_count', '')), '')::integer, 0),
      'scope_seed_result', COALESCE(v_scope_seed_result, '{}'::jsonb)
    );
  END IF;

  IF COALESCE(v_payload_json->>'limit', '') ~ '^[0-9]+$' THEN
    v_page_limit := LEAST(GREATEST((v_payload_json->>'limit')::integer, 1), 100);
  ELSIF COALESCE(v_payload_json#>>'{cursor,limit}', '') ~ '^[0-9]+$' THEN
    v_page_limit := LEAST(GREATEST((v_payload_json#>>'{cursor,limit}')::integer, 1), 100);
  ELSE
    v_page_limit := 100;
  END IF;

  BEGIN
    v_cursor_scope_ordinal := COALESCE(
      NULLIF(BTRIM(COALESCE(v_payload_json#>>'{cursor,last_scope_ordinal}', '')), '')::bigint,
      NULLIF(BTRIM(COALESCE(v_payload_json->>'last_scope_ordinal', '')), '')::bigint,
      -1
    );
  EXCEPTION WHEN OTHERS THEN
    v_cursor_scope_ordinal := -1;
  END;

  WITH page_scope AS (
    SELECT scope_row.candidate_id,
           scope_row.scope_ordinal,
           ROW_NUMBER() OVER (ORDER BY scope_row.scope_ordinal, scope_row.candidate_id) AS page_ordinal
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = p_session_id
      AND scope_row.scope_ordinal > COALESCE(v_cursor_scope_ordinal, -1)
    ORDER BY scope_row.scope_ordinal, scope_row.candidate_id
    LIMIT (v_page_limit + 1)
  ),
  selected_scope AS (
    SELECT page_scope.candidate_id,
           page_scope.scope_ordinal,
           page_scope.page_ordinal
    FROM page_scope
    WHERE page_scope.page_ordinal <= v_page_limit
  )
  SELECT
    COALESCE(jsonb_agg(to_jsonb(selected_scope.candidate_id::text) ORDER BY selected_scope.scope_ordinal, selected_scope.candidate_id), '[]'::jsonb),
    CASE
      WHEN EXISTS (SELECT 1 FROM page_scope WHERE page_scope.page_ordinal > v_page_limit) THEN
        jsonb_build_object(
          'last_scope_ordinal',
          (SELECT selected_cursor.scope_ordinal FROM selected_scope AS selected_cursor ORDER BY selected_cursor.scope_ordinal DESC, selected_cursor.candidate_id DESC LIMIT 1)
        )
      ELSE NULL::jsonb
    END
  INTO
    v_page_candidate_ids,
    v_page_next_cursor
  FROM selected_scope;

  IF COALESCE(jsonb_array_length(v_page_candidate_ids), 0) > 0 THEN
    v_page_enqueue_result := public.pay_workbench_enqueue_candidate_refresh_many(
      p_session_id => p_session_id,
      p_candidate_ids => jsonb_build_object(
        'candidate_ids', v_page_candidate_ids,
        'skip_candidate_ids', CASE WHEN jsonb_typeof(v_payload_json->'skip_candidate_ids') = 'array' THEN v_payload_json->'skip_candidate_ids' ELSE '[]'::jsonb END,
        'force_refresh', COALESCE(v_force_refresh, false),
        'user_requested_refresh', COALESCE(v_force_refresh, false)
      ),
      p_reason => COALESCE(p_reason, 'SESSION_SCOPE_PAGE_LINE_WORK'),
      p_actor_user_id => v_actor_user_id
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', NULL::text,
    'paged', true,
    'limit', v_page_limit,
    'cursor_scope_ordinal', v_cursor_scope_ordinal,
    'candidate_count', COALESCE(jsonb_array_length(v_page_candidate_ids), 0),
    'enqueued_candidate_count', COALESCE((v_page_enqueue_result->>'enqueued_candidate_count')::integer, 0),
    'force_refresh', COALESCE(v_force_refresh, false),
    'next_cursor', v_page_next_cursor,
    'has_more', v_page_next_cursor IS NOT NULL,
    'delta_queued_count', COALESCE((v_page_enqueue_result->>'delta_queued_count')::integer, 0),
    'legacy_queued_count', COALESCE((v_page_enqueue_result->>'legacy_queued_count')::integer, 0),
    'clone_skipped_ready_count', COALESCE((v_page_enqueue_result->>'clone_skipped_ready_count')::integer, 0),
    'enqueue_result', COALESCE(v_page_enqueue_result, '{}'::jsonb)
  );
END;
$function$;

-- pay_workbench_enqueue_stage_continuation(uuid,uuid,text,jsonb,uuid,jsonb,uuid,text,integer,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_stage_continuation(p_session_id uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_job_type text DEFAULT NULL::text, p_cursor_json jsonb DEFAULT NULL::jsonb, p_source_job_id uuid DEFAULT NULL::uuid, p_result_json jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_priority integer DEFAULT NULL::integer, p_limit integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_source_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_job_type text := CASE
    WHEN UPPER(BTRIM(COALESCE(p_job_type, ''))) IN (
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
      'CANDIDATE_SOURCE_BUILD',
      'CANDIDATE_SOURCE_BUILD_CHUNK',
      'SOURCE_BUILD',
      'SOURCE_BUILD_PAGE',
      'WORKBENCH_SOURCE_BUILD'
    ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    WHEN UPPER(BTRIM(COALESCE(p_job_type, ''))) IN (
      'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'CANDIDATE_DELTA_REFRESH',
      'DELTA_REFRESH'
    ) THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    WHEN UPPER(BTRIM(COALESCE(p_job_type, ''))) IN (
      'WORKBENCH_SESSION_CLONE_REBASE',
      'SESSION_CLONE_REBASE',
      'CLONE_REBASE'
    ) THEN 'WORKBENCH_SESSION_CLONE_REBASE'
    ELSE UPPER(BTRIM(COALESCE(p_job_type, '')))
  END;
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), 'WORKBENCH_STAGE_CONTINUATION');
  v_result_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_result_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_result_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_actor_user_id uuid := p_actor_user_id;
  v_cursor_json jsonb := NULL::jsonb;
  v_cursor_token text := 'none';
  v_session_signature_token text := 'none';
  v_candidate_key text := 'ALL';
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_priority integer := 50;
  v_line_work_action text := NULL::text;
  v_next_recommended_action text := NULL::text;
  v_progress_state text := NULL::text;
  v_scope_status text := NULL::text;
  v_source_job_session_version bigint := NULL::bigint;
  v_payload_core_json jsonb := '{}'::jsonb;
  v_payload_stage_json jsonb := '{}'::jsonb;
  v_payload_cursor_json jsonb := '{}'::jsonb;
  v_payload_source_json jsonb := '{}'::jsonb;
  v_payload_result_summary_json jsonb := '{}'::jsonb;
  v_payload_json jsonb := '{}'::jsonb;
  v_reuse_patch_json jsonb := '{}'::jsonb;
  v_dedupe_key text := NULL::text;
  v_job_id uuid := NULL::uuid;
  v_job_status text := NULL::text;
  v_job_was_inserted boolean := false;
  v_stale_running_seconds integer := 180;
  v_stale_cutoff timestamptz := NULL::timestamptz;
  v_superseded_stale_count integer := 0;
  v_source_build_run_id_token text := 'none';
  v_source_change_seq_token text := 'none';
  v_projection_run_id_token text := 'none';
  v_projection_class text := 'UNKNOWN';
  v_delta_phase text := 'INIT_PREFLIGHT';
  v_delta_write_phase_token text := 'none';
  v_delta_next_phase text := NULL::text;
  v_refresh_scope_kind text := NULL::text;
  v_source_build_allow_full_fallback boolean := false;
  v_pay_channel_scope text := NULL::text;
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_source_seed_cursor_json jsonb := '{}'::jsonb;
  v_clone_source_session_id_text text := NULL::text;
  v_clone_target_session_id_text text := NULL::text;
  v_clone_mode text := NULL::text;
  v_candidate_cursor_json jsonb := '{}'::jsonb;
  v_feature_flags_json jsonb := '{}'::jsonb;
  v_session_progress_update_applied boolean := false;
  v_session_progress_lock_skipped boolean := false;
  v_session_progress_lock_skip_reason text := NULL::text;
  v_session_progress_update_row_count integer := 0;
  v_original_dedupe_key text := NULL::text;
  v_self_reuse_prevented boolean := false;
  v_self_reuse_retry_count integer := 0;
  v_insert_row_count integer := 0;
  v_live_candidate_source_change_seq bigint := 0;
  v_cursor_source_change_seq bigint := 0;
  v_projection_run_source_change_seq bigint := 0;
  v_effective_continuation_source_seq bigint := 0;
  v_normalised_delta_family_key text := NULL::text;
  v_economic_build_id uuid := NULL::uuid;
  v_private_stage text := NULL::text;
  v_private_cursor_kind text := NULL::text;
  v_private_stage_version integer := NULL::integer;
  v_private_cursor_start_hash text := NULL::text;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CONTINUATION_SESSION_ID_REQUIRED')::text;
  END IF;

  IF v_job_type = '' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_JOB_TYPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CONTINUATION_JOB_TYPE_REQUIRED', 'session_id', p_session_id::text)::text;
  END IF;

  IF v_job_type NOT IN (
    'WORKBENCH_SESSION_SCOPE_SEED',
    'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'WORKBENCH_CANDIDATE_DELTA_REFRESH',
    'WORKBENCH_SESSION_CLONE_REBASE',
    'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
    'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
    'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_UNSUPPORTED_JOB_TYPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_UNSUPPORTED_JOB_TYPE',
              'session_id', p_session_id::text,
              'job_type', v_job_type
            )::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CURSOR_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_CURSOR_MUST_BE_OBJECT',
              'session_id', p_session_id::text,
              'job_type', v_job_type,
              'cursor_type', jsonb_typeof(p_cursor_json)
            )::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status,
              'discarded_at_utc', v_session_row.discarded_at_utc
            )::text;
  END IF;

  v_actor_user_id := COALESCE(v_actor_user_id, v_session_row.actor_user_id);
  v_session_signature_token := md5(COALESCE(v_session_row.session_signature, ''));
  v_stale_running_seconds := 25;
  v_stale_cutoff := v_now - make_interval(secs => v_stale_running_seconds);

  IF p_source_job_id IS NOT NULL THEN
    SELECT source_job.*
    INTO v_source_job_row
    FROM public.banking_pay_workbench_jobs AS source_job
    WHERE source_job.id = p_source_job_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_NOT_FOUND',
                'session_id', p_session_id::text,
                'source_job_id', p_source_job_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF v_source_job_row.session_id IS DISTINCT FROM p_session_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_MISMATCH',
                'session_id', p_session_id::text,
                'source_job_id', p_source_job_id::text,
                'source_job_session_id', CASE WHEN v_source_job_row.session_id IS NULL THEN NULL ELSE v_source_job_row.session_id::text END,
                'job_type', v_job_type
              )::text;
    END IF;

    IF v_source_job_row.snapshot_run_id IS DISTINCT FROM v_session_row.source_snapshot_run_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SNAPSHOT_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SNAPSHOT_MISMATCH',
                'session_id', p_session_id::text,
                'source_job_id', p_source_job_id::text,
                'source_job_snapshot_run_id', CASE WHEN v_source_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_source_job_row.snapshot_run_id::text END,
                'session_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF COALESCE(v_source_job_row.payload_json->>'session_version', '') ~ '^[0-9]+$' THEN
      v_source_job_session_version := (v_source_job_row.payload_json->>'session_version')::bigint;

      IF COALESCE(v_source_job_session_version, 0) <> COALESCE(v_session_row.version, 0) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_VERSION_STALE'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_SESSION_VERSION_STALE',
                  'session_id', p_session_id::text,
                  'source_job_id', p_source_job_id::text,
                  'source_job_session_version', v_source_job_session_version,
                  'current_session_version', COALESCE(v_session_row.version, 0),
                  'job_type', v_job_type
                )::text;
      END IF;
    END IF;
  END IF;

  v_source_build_run_id_token := COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,source_build_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(p_cursor_json->>'source_build_run_id', '')), ''),
    'none'
  );
  v_source_change_seq_token := COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'source_change_seq', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_change_seq', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_change_sequence', '')), ''),
    NULLIF(BTRIM(COALESCE(p_cursor_json->>'source_change_seq', '')), ''),
    'none'
  );

  v_projection_run_id_token := COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'projection_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_result_json#>>'{cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_result_json#>>'{next_cursor_json,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_result_json#>>'{next_cursor_json,cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'projection_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{cursor_json,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{cursor_json,cursor,projection_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(p_cursor_json->>'projection_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(p_cursor_json#>>'{cursor,projection_run_id}', '')), ''),
    'none'
  );
  v_projection_class := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'projection_class', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'projection_class', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'projection_class', ''))), ''),
    'UNKNOWN'
  );
  v_delta_phase := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'next_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'next_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'phase', ''))), ''),
    'INIT_PREFLIGHT'
  );
  v_delta_next_phase := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'next_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'next_phase', ''))), ''),
    NULL::text
  );
  v_delta_write_phase_token := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'write_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'write_phase', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'write_phase', ''))), ''),
    'none'
  );
  /*
    A source-build result reports two related but different scopes:
      - requested_refresh_scope_kind: the caller's semantic scope for this run;
      - refresh_scope_kind / actual_refresh_scope_kind: the collection strategy used for this page.

    Full-live candidate builds intentionally page through internally targeted timesheet
    sets to avoid large aggregation.  Cursor continuations must preserve the requested
    scope, not the page's actual internal strategy; otherwise a CANDIDATE_FULL_LIVE
    run can be mis-enqueued as TARGETED_TIMESHEETS with no requested ids.
  */
  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND UPPER(BTRIM(COALESCE(v_reason, ''))) = 'SOURCE_BUILD_CURSOR_CONTINUATION' THEN
    v_refresh_scope_kind := COALESCE(
      NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'requested_refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'requested_refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json#>>'{source_build_diagnostics,collect,requested_refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', ''))), ''),
      NULL::text
    );
  ELSIF v_job_type IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED') THEN
    v_refresh_scope_kind := COALESCE(
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'requested_refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json#>>'{source_build_diagnostics,collect,requested_refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'requested_refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', ''))), ''),
      NULL::text
    );
  ELSE
    v_refresh_scope_kind := COALESCE(
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'refresh_scope_kind', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,refresh_scope_kind}', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'requested_refresh_scope_kind', ''))), ''),
      NULL::text
    );
  END IF;

  IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := CASE
      WHEN v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 'CANDIDATE_FULL_LIVE'
      ELSE NULL::text
    END;
  END IF;

  v_pay_channel_scope := COALESCE(
    NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'pay_channel_scope', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'pay_channel_scope', ''))), ''),
    NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,pay_channel_scope}', ''))), ''),
    NULL::text
  );

  SELECT scope_arrays.array_json
  INTO v_targeted_timesheet_ids_json
  FROM (
    VALUES
      (10, v_source_job_row.payload_json->'targeted_timesheet_ids_requested'),
      (20, v_source_job_row.payload_json#>'{source_build,targeted_timesheet_ids_requested}'),
      (30, v_source_job_row.payload_json->'targeted_timesheet_ids'),
      (40, v_source_job_row.payload_json#>'{source_build,targeted_timesheet_ids}'),
      (50, v_result_json->'targeted_timesheet_ids_requested'),
      (60, v_result_json#>'{source_build,targeted_timesheet_ids_requested}'),
      (70, v_result_json->'targeted_timesheet_ids'),
      (80, v_result_json#>'{source_build,targeted_timesheet_ids}'),
      (90, p_cursor_json->'targeted_timesheet_ids')
  ) AS scope_arrays(priority, array_json)
  WHERE jsonb_typeof(scope_arrays.array_json) = 'array'
    AND jsonb_array_length(scope_arrays.array_json) > 0
  ORDER BY scope_arrays.priority
  LIMIT 1;

  v_targeted_timesheet_ids_json := COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb);

  SELECT scope_arrays.array_json
  INTO v_linked_timesheet_ids_json
  FROM (
    VALUES
      (10, v_source_job_row.payload_json->'linked_timesheet_ids_requested'),
      (20, v_source_job_row.payload_json#>'{source_build,linked_timesheet_ids_requested}'),
      (30, v_source_job_row.payload_json->'linked_timesheet_ids'),
      (40, v_source_job_row.payload_json#>'{source_build,linked_timesheet_ids}'),
      (50, v_result_json->'linked_timesheet_ids_requested'),
      (60, v_result_json#>'{source_build,linked_timesheet_ids_requested}'),
      (70, v_result_json->'linked_timesheet_ids'),
      (80, v_result_json#>'{source_build,linked_timesheet_ids}'),
      (90, p_cursor_json->'linked_timesheet_ids')
  ) AS scope_arrays(priority, array_json)
  WHERE jsonb_typeof(scope_arrays.array_json) = 'array'
    AND jsonb_array_length(scope_arrays.array_json) > 0
  ORDER BY scope_arrays.priority
  LIMIT 1;

  v_linked_timesheet_ids_json := COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb);

  IF v_job_type IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED')
     AND v_refresh_scope_kind = 'CANDIDATE_FULL_LIVE' THEN
    v_targeted_timesheet_ids_json := '[]'::jsonb;
    v_linked_timesheet_ids_json := '[]'::jsonb;
  END IF;


  IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
     AND p_candidate_id IS NOT NULL THEN
    SELECT COALESCE(change_counter.seq, 0)
    INTO v_live_candidate_source_change_seq
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

    v_cursor_source_change_seq := GREATEST(
      COALESCE(CASE WHEN COALESCE(p_cursor_json->>'source_change_seq', '') ~ '^\d{1,18}$' THEN (p_cursor_json->>'source_change_seq')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(p_cursor_json->>'source_change_sequence', '') ~ '^\d{1,18}$' THEN (p_cursor_json->>'source_change_sequence')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(p_cursor_json#>>'{cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (p_cursor_json#>>'{cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(p_cursor_json#>>'{cursor_json,source_change_seq}', '') ~ '^\d{1,18}$' THEN (p_cursor_json#>>'{cursor_json,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(p_cursor_json#>>'{cursor_json,cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (p_cursor_json#>>'{cursor_json,cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_result_json#>>'{cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_result_json#>>'{cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_result_json#>>'{next_cursor_json,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_result_json#>>'{next_cursor_json,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_result_json#>>'{next_cursor_json,cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_result_json#>>'{next_cursor_json,cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_source_job_row.payload_json#>>'{cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_source_job_row.payload_json#>>'{cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_source_job_row.payload_json#>>'{cursor_json,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_source_job_row.payload_json#>>'{cursor_json,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN COALESCE(v_source_job_row.payload_json#>>'{cursor_json,cursor,source_change_seq}', '') ~ '^\d{1,18}$' THEN (v_source_job_row.payload_json#>>'{cursor_json,cursor,source_change_seq}')::bigint END, 0),
      COALESCE(CASE WHEN v_source_change_seq_token ~ '^\d{1,18}$' THEN v_source_change_seq_token::bigint END, 0)
    );

    IF v_projection_run_id_token ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT COALESCE(projection_run.source_change_seq, 0)
      INTO v_projection_run_source_change_seq
      FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
      WHERE projection_run.id = v_projection_run_id_token::uuid;
    END IF;

    v_effective_continuation_source_seq := GREATEST(
      COALESCE(CASE WHEN v_source_change_seq_token ~ '^\d{1,18}$' THEN v_source_change_seq_token::bigint END, 0),
      COALESCE(v_cursor_source_change_seq, 0),
      COALESCE(v_projection_run_source_change_seq, 0)
    );

    v_normalised_delta_family_key := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'normalised_delta_family_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result_json->>'delta_family_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_result_json->>'delta_coalescing_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'normalised_delta_family_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'delta_family_key', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'delta_coalescing_key', '')), ''),
      NULL::text
    );

    IF (
      (COALESCE(v_cursor_source_change_seq, 0) > 0 AND COALESCE(v_live_candidate_source_change_seq, 0) > COALESCE(v_cursor_source_change_seq, 0))
      OR (COALESCE(v_projection_run_source_change_seq, 0) > 0 AND COALESCE(v_live_candidate_source_change_seq, 0) > COALESCE(v_projection_run_source_change_seq, 0))
      OR (COALESCE(v_cursor_source_change_seq, 0) > 0 AND v_source_change_seq_token ~ '^\d{1,18}$' AND v_source_change_seq_token::bigint > COALESCE(v_cursor_source_change_seq, 0))
      OR (COALESCE(v_projection_run_source_change_seq, 0) > 0 AND v_source_change_seq_token ~ '^\d{1,18}$' AND v_source_change_seq_token::bigint > COALESCE(v_projection_run_source_change_seq, 0))
    ) THEN
      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        COALESCE(p_source_job_id::text, p_session_id::text || ':' || p_candidate_id::text),
        'CONTINUATION_SUPPRESSED_NEWER_SOURCE_SEQ',
        NULL::jsonb,
        jsonb_build_object(
          'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
          'session_id', p_session_id::text,
          'candidate_id', p_candidate_id::text,
          'job_type', v_job_type,
          'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
          'normalised_delta_family_key', v_normalised_delta_family_key,
          'cursor_source_change_seq', v_cursor_source_change_seq,
          'projection_run_source_change_seq', v_projection_run_source_change_seq,
          'payload_source_change_seq', CASE WHEN v_source_change_seq_token ~ '^\d{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'live_candidate_source_change_seq', v_live_candidate_source_change_seq,
          'targeted_timesheet_ids', v_targeted_timesheet_ids_json,
          'linked_timesheet_ids', v_linked_timesheet_ids_json,
          'continuation_not_enqueued', true,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        ),
        'CONTINUATION_SUPPRESSED_NEWER_SOURCE_SEQ',
        v_actor_user_id
      );

      RETURN jsonb_build_object(
        'ok', true,
        'job_id', NULL::text,
        'job_type', v_job_type,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
        'continuation_not_enqueued', true,
        'stale_continuation_suppressed', true,
        'more_due', false,
        'has_more', false,
        'made_progress', true,
        'reason', 'CONTINUATION_SUPPRESSED_NEWER_SOURCE_SEQ',
        'normalised_delta_family_key', v_normalised_delta_family_key,
        'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
        'cursor_source_change_seq', v_cursor_source_change_seq,
        'projection_run_source_change_seq', v_projection_run_source_change_seq,
        'live_candidate_source_change_seq', v_live_candidate_source_change_seq,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
    END IF;
  END IF;

  v_source_build_allow_full_fallback := LOWER(BTRIM(COALESCE(
    NULLIF(BTRIM(COALESCE(v_result_json->>'source_build_allow_full_fallback', '')), ''),
    NULLIF(BTRIM(COALESCE(v_result_json#>>'{source_build,allow_full_fallback}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_build_allow_full_fallback', '')), ''),
    NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json#>>'{source_build,allow_full_fallback}', '')), ''),
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
    v_clone_source_session_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'clone_from_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(p_cursor_json->>'source_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(p_cursor_json->>'clone_from_session_id', '')), '')
    );
    v_clone_target_session_id_text := COALESCE(
      NULLIF(BTRIM(COALESCE(v_result_json->>'target_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'target_session_id', '')), ''),
      NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'session_id', '')), ''),
      p_session_id::text
    );
    v_clone_mode := COALESCE(
      NULLIF(UPPER(BTRIM(COALESCE(v_result_json->>'clone_mode', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(v_source_job_row.payload_json->>'clone_mode', ''))), ''),
      NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'clone_mode', ''))), ''),
      'CERTIFIED_SIMPLE_ONLY'
    );
    v_candidate_cursor_json := CASE
      WHEN jsonb_typeof(p_cursor_json->'candidate_cursor') = 'object' THEN COALESCE(p_cursor_json->'candidate_cursor', '{}'::jsonb)
      WHEN jsonb_typeof(v_source_job_row.payload_json->'candidate_cursor') = 'object' THEN COALESCE(v_source_job_row.payload_json->'candidate_cursor', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;
    v_feature_flags_json := CASE
      WHEN jsonb_typeof(v_source_job_row.payload_json->'feature_flags') = 'object' THEN COALESCE(v_source_job_row.payload_json->'feature_flags', '{}'::jsonb)
      WHEN jsonb_typeof(p_cursor_json->'feature_flags') = 'object' THEN COALESCE(p_cursor_json->'feature_flags', '{}'::jsonb)
      ELSE '{}'::jsonb
    END;
  END IF;

  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND jsonb_array_length(COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb)) = 0
     AND jsonb_array_length(COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb)) = 0
     AND COALESCE(v_source_build_allow_full_fallback, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_TARGETED_IDS_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_TARGETED_IDS_REQUIRED',
              'session_id', p_session_id::text,
              'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
              'job_type', v_job_type,
              'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
              'reason', v_reason,
              'refresh_scope_kind', v_refresh_scope_kind,
              'cursor_requested_refresh_scope_kind', NULLIF(UPPER(BTRIM(COALESCE(p_cursor_json->>'requested_refresh_scope_kind', ''))), ''),
              'message', 'Refusing to enqueue TARGETED_TIMESHEETS source-build continuation without targeted_timesheet_ids or linked_timesheet_ids.'
            )::text;
  END IF;
  v_source_seed_cursor_json := jsonb_strip_nulls(jsonb_build_object(
    'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
    'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
    'projection_class', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_projection_class ELSE NULL::text END,
    'phase', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN v_delta_phase ELSE NULL::text END,
    'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
    'session_version', COALESCE(v_session_row.version, 0),
    'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'session_signature', v_session_row.session_signature,
    'source_row_cursor', 'START'
  ));

  IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND COALESCE(v_source_build_run_id_token, 'none') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_BUILD_RUN_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_BUILD_RUN_ID_REQUIRED',
              'session_id', p_session_id::text,
              'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
              'job_type', v_job_type,
              'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
              'message', 'WORKBENCH_CANDIDATE_SOURCE_BUILD continuation requires source_build_run_id from result, source payload, or cursor.'
            )::text;
  END IF;

  IF v_job_type = 'WORKBENCH_SESSION_SCOPE_SEED' OR v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
    IF p_candidate_id IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SESSION_JOB_CANDIDATE_NOT_ALLOWED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SESSION_JOB_CANDIDATE_NOT_ALLOWED',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
      v_line_work_action := 'CLONE_REBASE';
      v_next_recommended_action := 'CLONE_REBASE_CHUNK';
      v_progress_state := 'CLONE_REBASING';
      v_priority := COALESCE(p_priority, 42);
    ELSE
      v_line_work_action := 'SCOPE_SEED';
      v_next_recommended_action := 'SEED_SCOPE_CHUNK';
      v_progress_state := 'REFRESHING_CANDIDATES';
      v_priority := COALESCE(p_priority, 40);
    END IF;
  ELSE
    IF p_candidate_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_ID_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_ID_REQUIRED',
                'session_id', p_session_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    SELECT scope_row.*
    INTO v_scope_row
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = p_session_id
      AND scope_row.candidate_id = p_candidate_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_NOT_IN_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_CANDIDATE_NOT_IN_SCOPE',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    IF p_source_job_id IS NOT NULL
       AND v_source_job_row.candidate_id IS NOT NULL
       AND v_source_job_row.candidate_id IS DISTINCT FROM p_candidate_id THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_CANDIDATE_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_SOURCE_JOB_CANDIDATE_MISMATCH',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'source_job_id', p_source_job_id::text,
                'source_job_candidate_id', v_source_job_row.candidate_id::text,
                'job_type', v_job_type
              )::text;
    END IF;

    v_candidate_key := p_candidate_id::text;

    IF v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
      v_line_work_action := 'SOURCE_BUILD';
      v_next_recommended_action := 'BUILD_SOURCE_CHUNK';
      v_progress_state := 'REFRESHING_CANDIDATES';
      v_scope_status := 'SOURCE_BUILD_PENDING';
      v_priority := COALESCE(p_priority, 44);
    ELSIF v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' THEN
      v_line_work_action := 'SEED';
      v_next_recommended_action := 'SEED_LINE_WORK_CHUNK';
      v_progress_state := 'REFRESHING_CANDIDATES';
      v_scope_status := CASE
        WHEN UPPER(BTRIM(COALESCE(v_scope_row.status, ''))) = 'PENDING' THEN 'PENDING'
        ELSE 'LINE_WORK_PENDING'
      END;
      v_priority := COALESCE(p_priority, 45);
    ELSIF v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS' THEN
      v_line_work_action := 'PROCESS';
      v_next_recommended_action := 'PROCESS_LINE_WORK_CHUNK';
      v_progress_state := 'PROCESSING_LINE_WORK';
      v_scope_status := 'LINE_WORK_PENDING';
      v_priority := COALESCE(p_priority, 42);
    ELSIF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
      v_line_work_action := 'DELTA_REFRESH';
      v_next_recommended_action := 'DELTA_REFRESH_CHUNK';
      v_progress_state := 'DELTA_REFRESHING';
      v_scope_status := 'DELTA_REFRESH_PENDING';
      v_priority := COALESCE(p_priority, 43);
    ELSE
      v_line_work_action := 'MATERIALISE';
      v_next_recommended_action := 'MATERIALISE_PREVIEW_ROWS_CHUNK';
      v_progress_state := 'MATERIALISING_PREVIEW_ROWS';
      v_scope_status := 'LINE_WORK_READY';
      v_priority := COALESCE(p_priority, 41);
    END IF;
  END IF;

  v_priority := LEAST(GREATEST(COALESCE(v_priority, 50), 1), 999);

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    v_cursor_json := p_cursor_json;
    v_cursor_token := md5(p_cursor_json::text);
  ELSE
    v_cursor_json := NULL::jsonb;
    v_cursor_token := 'none';
  END IF;

  IF v_job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
    v_economic_build_id:=v_source_job_row.economic_build_id;
    v_private_stage:=upper(COALESCE(NULLIF(v_result_json->>'next_action',''),
      NULLIF(v_result_json->>'private_stage',''),NULLIF(v_cursor_json->>'cursor_kind','')));
    v_private_cursor_kind:=upper(NULLIF(v_cursor_json->>'cursor_kind',''));
    v_private_stage_version:=COALESCE((v_cursor_json->>'cursor_version')::integer,1);
    v_private_cursor_start_hash:=md5(v_cursor_json::text);
    IF v_economic_build_id IS NULL OR v_cursor_json IS NULL OR v_private_cursor_kind IS NULL
       OR v_private_stage NOT IN ('PREPARE_SCOPE','DEPENDENCY_CLOSURE','WORKSPACE_FACT',
         'RECONCILE_EXECUTE','SOURCE_PUBLISH','BOOTSTRAP_DISCOVERY','BUILD_CLEANUP')
       OR NOT (CASE v_private_stage
         WHEN 'PREPARE_SCOPE' THEN v_private_cursor_kind IN ('SCOPE_SELECT','SEED_SCOPE_SEAL')
         WHEN 'DEPENDENCY_CLOSURE' THEN v_private_cursor_kind IN ('DEPENDENCY_CLOSURE','DEPENDENCY_SCOPE_SEAL')
         WHEN 'WORKSPACE_FACT' THEN v_private_cursor_kind='WORKSPACE_FACT'
         WHEN 'RECONCILE_EXECUTE' THEN v_private_cursor_kind='RECONCILE_EXECUTE'
         WHEN 'SOURCE_PUBLISH' THEN v_private_cursor_kind='SOURCE_PUBLISH'
         WHEN 'BOOTSTRAP_DISCOVERY' THEN v_private_cursor_kind='BOOTSTRAP_DISCOVERY'
         WHEN 'BUILD_CLEANUP' THEN v_private_cursor_kind='BUILD_CLEANUP'
         ELSE false END)
       OR NULLIF(v_cursor_json->>'build_id','')::uuid IS DISTINCT FROM v_economic_build_id
       OR NULLIF(v_cursor_json->>'candidate_id','')::uuid IS DISTINCT FROM p_candidate_id
       OR v_private_stage_version<1 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_CURSOR_STAGE_MISMATCH'
        USING ERRCODE='22023';
    END IF;
    PERFORM 1 FROM private.banking_pay_workbench_economic_builds build_row
    WHERE build_row.id=v_economic_build_id AND build_row.candidate_id=p_candidate_id
      AND build_row.private_stage=v_private_stage
      AND build_row.captured_candidate_generation=COALESCE(
        NULLIF(v_cursor_json->>'captured_candidate_generation','')::bigint,
        build_row.captured_candidate_generation)
      AND build_row.source_change_seq=COALESCE(
        NULLIF(v_cursor_json->>'captured_source_change_seq','')::bigint,build_row.source_change_seq);
    IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_BUILD_STALE' USING ERRCODE='40001'; END IF;
  END IF;

  IF v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
    v_dedupe_key := 'WORKBENCH_SESSION_CLONE_REBASE'
      || ':session:' || p_session_id::text
      || ':source:' || COALESCE(v_clone_source_session_id_text, 'none')
      || ':target:' || COALESCE(v_clone_target_session_id_text, p_session_id::text)
      || ':cursor_hash:' || v_cursor_token;
  ELSIF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    v_dedupe_key := 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
      || ':session:' || p_session_id::text
      || ':candidate:' || COALESCE(v_candidate_key, 'ALL')
      || ':projection_run:' || COALESCE(v_projection_run_id_token, 'none')
      || ':phase:' || COALESCE(v_delta_phase, 'INIT_PREFLIGHT')
      || ':write_phase:' || COALESCE(v_delta_write_phase_token, 'none')
      || ':cursor_hash:' || v_cursor_token;
  ELSIF v_job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
    v_dedupe_key := 'source-build:'||p_session_id::text||':'||p_candidate_id::text||':'||
      v_economic_build_id::text||':'||v_private_stage||':'||v_private_cursor_start_hash;
  ELSE
    v_dedupe_key := 'WORKBENCH_STAGE_CONTINUATION'
      || ':' || v_job_type
      || ':session:' || p_session_id::text
      || ':version:' || COALESCE(v_session_row.version, 0)::text
      || ':snapshot:' || v_session_row.source_snapshot_run_id::text
      || ':signature:' || v_session_signature_token
      || ':candidate:' || COALESCE(v_candidate_key, 'ALL')
      || ':source_build:' || COALESCE(v_source_build_run_id_token, 'none')
      || ':source_change:' || COALESCE(v_source_change_seq_token, 'none')
      || ':cursor:' || v_cursor_token;
  END IF;

  v_payload_core_json := jsonb_build_object(
    'session_id', p_session_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'session_signature', v_session_row.session_signature,
    'session_signature_token', v_session_signature_token,
    'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'candidate_serial_key', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE public._pay_workbench_candidate_serial_key(p_candidate_id) END,
    'candidate_serial_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'candidate_serial_active_chain_id', CASE
      WHEN p_candidate_id IS NULL THEN NULL
      ELSE COALESCE(
        NULLIF(BTRIM(COALESCE(v_source_job_row.payload_json->>'candidate_serial_active_chain_id', '')), ''),
        CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END
      )
    END,
    'candidate_serial_source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'candidate_serial_reason', 'CANDIDATE_SERIAL_CONTINUATION_QUEUED',
    'candidate_serial_continuation', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE true END,
    'job_type', v_job_type,
    'dedupe_key', v_dedupe_key,
    'continuation', true
  );

  v_payload_stage_json := jsonb_build_object(
    'reason', v_reason,
    'continuation_reason', v_reason,
    'line_work_action', v_line_work_action,
    'next_recommended_action', v_next_recommended_action,
    'limit', v_limit,
    'line_limit', v_limit,
    'chunk_size', v_limit,
    'run_mode', 'BOUNDED_CONTINUATION',
    'source_build_required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'line_work_required', v_job_type NOT IN ('WORKBENCH_SESSION_SCOPE_SEED', 'WORKBENCH_SESSION_CLONE_REBASE', 'WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_DELTA_REFRESH'),
    'line_work_only', v_job_type NOT IN ('WORKBENCH_SESSION_SCOPE_SEED', 'WORKBENCH_SESSION_CLONE_REBASE', 'WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_DELTA_REFRESH'),
    'delta_refresh_required', v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
    'clone_rebase_required', v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE'
  );

  v_payload_cursor_json := jsonb_build_object(
    'cursor_json', v_cursor_json,
    'cursor', v_cursor_json,
    'cursor_token', v_cursor_token,
    'has_cursor', v_cursor_json IS NOT NULL
  );

  v_payload_source_json := jsonb_build_object(
    'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'source_result_has_more', COALESCE(v_result_json->'has_more', 'false'::jsonb),
    'source_result_next_cursor_present', COALESCE((v_result_json ? 'next_cursor') OR (v_result_json ? 'next_cursor_json') OR (v_result_json ? 'nextCursor'), false),
    'created_by_helper', 'pay_workbench_enqueue_stage_continuation',
    'created_at_utc', v_now::text
  );

  v_payload_result_summary_json := jsonb_build_object(
    'source_result_summary', jsonb_strip_nulls(jsonb_build_object(
      'ok', COALESCE(v_result_json->'ok', 'true'::jsonb),
      'seeded_count', v_result_json->'seeded_count',
      'new_scope_count', v_result_json->'new_scope_count',
      'enqueued_count', v_result_json->'enqueued_count',
      'reused_count', v_result_json->'reused_count',
      'processed_count', v_result_json->'processed_count',
      'ready_count_delta', v_result_json->'ready_count_delta',
      'materialised_count', v_result_json->'materialised_count',
      'materialized_count', v_result_json->'materialized_count',
      'new_preview_row_count', v_result_json->'new_preview_row_count',
      'new_selected_row_count', v_result_json->'new_selected_row_count',
      'source_rows_written', v_result_json->'source_rows_written',
      'current_source_row_count', v_result_json->'current_source_row_count',
      'source_page_count', v_result_json->'source_page_count',
      'timesheets_seen', v_result_json->'timesheets_seen',
      'fallback_used', v_result_json->'fallback_used',
      'cursor_advanced', v_result_json->'cursor_advanced',
      'error_count', v_result_json->'error_count',
      'has_more', v_result_json->'has_more'
    ))
  );

  v_payload_json := jsonb_strip_nulls(
    CASE
      WHEN p_source_job_id IS NOT NULL THEN
        COALESCE(v_source_job_row.payload_json, '{}'::jsonb) - ARRAY[
          'worker_id',
          'worker_claimed_at_utc',
          'worker_lease_seconds',
          'worker_lease_expires_at_utc',
          'worker_function',
          'result_json',
          'completion_json',
          'cursor_json',
          'cursor',
          'next_cursor_json',
          'next_cursor'
        ]::text[]
      ELSE '{}'::jsonb
    END
    || v_payload_core_json
    || v_payload_stage_json
    || v_payload_cursor_json
    || v_payload_source_json
    || v_payload_result_summary_json
    || CASE
      WHEN v_job_type IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED') THEN
        jsonb_build_object(
          'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
          'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'source_change_sequence', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'session_version', COALESCE(v_session_row.version, 0),
          'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
          'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
          'session_signature', v_session_row.session_signature
        )
        || jsonb_build_object(
          'refresh_scope_kind', v_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'pay_channel_scope', v_pay_channel_scope,
          'source_build_allow_full_fallback', COALESCE(v_source_build_allow_full_fallback, false),
          'source_build_cursor', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' THEN v_source_seed_cursor_json ELSE v_cursor_json END
        )
        || jsonb_build_object(
          'source_build', jsonb_strip_nulls(
            CASE
              WHEN jsonb_typeof(v_source_job_row.payload_json->'source_build') = 'object'
                THEN COALESCE(v_source_job_row.payload_json->'source_build', '{}'::jsonb)
              ELSE '{}'::jsonb
            END
            || jsonb_build_object(
              'required', v_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
              'run_id', NULLIF(v_source_build_run_id_token, 'none'),
              'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
              'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
              'source_change_sequence', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
              'session_version', COALESCE(v_session_row.version, 0),
              'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
              'session_signature', v_session_row.session_signature,
              'refresh_scope_kind', v_refresh_scope_kind,
              'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
              'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
              'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
              'linked_timesheet_ids_requested', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
              'pay_channel_scope', v_pay_channel_scope,
              'allow_full_fallback', COALESCE(v_source_build_allow_full_fallback, false),
              'limit', v_limit,
              'cursor', CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_SEED' THEN v_source_seed_cursor_json ELSE v_cursor_json END,
              'reason', v_reason
            )
          )
        )
      ELSE '{}'::jsonb
    END
    || CASE
      WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
        jsonb_build_object(
          'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
          'projection_class', v_projection_class,
          'projection_mode', 'DELTA',
          'phase', v_delta_phase,
          'next_phase', v_delta_next_phase,
          'cursor_json', v_cursor_json,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'source_change_sequence', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'latest_source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'normalised_delta_family_key', v_normalised_delta_family_key,
          'delta_family_key', v_normalised_delta_family_key,
          'delta_coalescing_key', v_normalised_delta_family_key,
          'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
          'delta_refresh_required', true,
          'source_build_required', false,
          'line_work_required', false,
          'legacy_fallback_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        )
      ELSE '{}'::jsonb
    END
    || CASE
      WHEN v_job_type = 'WORKBENCH_SESSION_CLONE_REBASE' THEN
        jsonb_build_object(
          'source_session_id', v_clone_source_session_id_text,
          'target_session_id', COALESCE(v_clone_target_session_id_text, p_session_id::text),
          'cursor_json', COALESCE(v_cursor_json, '{}'::jsonb),
          'candidate_cursor', COALESCE(v_candidate_cursor_json, '{}'::jsonb),
          'limit', v_limit,
          'line_limit', v_limit,
          'clone_mode', v_clone_mode,
          'feature_flags', COALESCE(v_feature_flags_json, '{}'::jsonb),
          'clone_rebase_required', true,
          'source_build_required', false,
          'line_work_required', false,
          'delta_refresh_required', false
        )
      ELSE '{}'::jsonb
    END
  );

  v_reuse_patch_json := jsonb_build_object(
    'last_reused_at_utc', v_now::text,
    'last_reuse_reason', v_reason,
    'last_source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'last_actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END
  );

  WITH superseded_stale_jobs AS (
    UPDATE public.banking_pay_workbench_jobs AS superseded_job
    SET status = 'FAILED',
        updated_at_utc = v_now,
        failed_at_utc = v_now,
        last_error_json = jsonb_build_object(
          'code', 'WORKBENCH_JOB_SUPERSEDED_BY_NEWER_SESSION_VERSION',
          'message', 'Superseded stale running workbench preview job while enqueueing newer session-version continuation.',
          'session_id', p_session_id::text,
          'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'job_type', v_job_type,
          'current_session_version', COALESCE(v_session_row.version, 0),
          'job_session_version', CASE
            WHEN COALESCE(superseded_job.payload_json->>'session_version', '') ~ '^[0-9]+$'
              THEN (superseded_job.payload_json->>'session_version')::bigint
            ELSE NULL::bigint
          END,
          'stale_running_seconds', v_stale_running_seconds,
          'last_activity_at_utc', COALESCE(superseded_job.updated_at_utc, superseded_job.started_at_utc, superseded_job.run_at_utc, superseded_job.created_at_utc),
          'superseded_at_utc', v_now
        ),
        payload_json = COALESCE(superseded_job.payload_json, '{}'::jsonb) || jsonb_build_object(
          'superseded_by_newer_session_version_at_utc', v_now::text,
          'superseded_by_session_version', COALESCE(v_session_row.version, 0),
          'superseded_by_dedupe_key', v_dedupe_key
        )
    WHERE superseded_job.session_id = p_session_id
      AND superseded_job.candidate_id IS NOT DISTINCT FROM p_candidate_id
      AND superseded_job.snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
      AND UPPER(BTRIM(COALESCE(superseded_job.job_type, ''))) = v_job_type
      AND UPPER(BTRIM(COALESCE(superseded_job.status, ''))) IN ('RUNNING', 'PROCESSING', 'CLAIMED', 'IN_PROGRESS')
      AND superseded_job.completed_at_utc IS NULL
      AND superseded_job.failed_at_utc IS NULL
      AND COALESCE(superseded_job.payload_json->>'cursor_token', 'none') = v_cursor_token
      AND COALESCE(superseded_job.payload_json->>'session_signature_token', 'none') = v_session_signature_token
      AND COALESCE(superseded_job.updated_at_utc, superseded_job.started_at_utc, superseded_job.run_at_utc, superseded_job.created_at_utc) <= v_stale_cutoff
      AND COALESCE(superseded_job.payload_json->>'session_version', '') ~ '^[0-9]+$'
      AND (superseded_job.payload_json->>'session_version')::bigint < COALESCE(v_session_row.version, 0)
    RETURNING superseded_job.id
  )
  SELECT COUNT(*)::integer
  INTO v_superseded_stale_count
  FROM superseded_stale_jobs;

  v_original_dedupe_key := v_dedupe_key;

  <<continuation_insert_attempt>>
  LOOP
    v_job_id := NULL::uuid;
    v_job_status := NULL::text;
    v_job_was_inserted := false;
    v_insert_row_count := 0;

  INSERT INTO public.banking_pay_workbench_jobs AS target_job (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    economic_build_id,
    private_stage,
    private_cursor_kind,
    private_cursor_json,
    private_stage_version,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    v_job_type,
    'QUEUED',
    v_priority,
    v_now,
    0,
    8,
    v_dedupe_key,
    v_session_row.source_snapshot_run_id,
    p_session_id,
    p_candidate_id,
    v_payload_json,
    v_economic_build_id,
    v_private_stage,
    v_private_cursor_kind,
    COALESCE(v_cursor_json,'{}'::jsonb),
    v_private_stage_version,
    v_now,
    v_now,
    NULL::timestamptz,
    NULL::timestamptz,
    NULL::timestamptz,
    NULL::jsonb
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET economic_build_id=COALESCE(target_job.economic_build_id,EXCLUDED.economic_build_id),
      private_stage=COALESCE(target_job.private_stage,EXCLUDED.private_stage),
      private_cursor_kind=COALESCE(target_job.private_cursor_kind,EXCLUDED.private_cursor_kind),
      private_cursor_json=CASE WHEN target_job.status='RUNNING' THEN target_job.private_cursor_json ELSE EXCLUDED.private_cursor_json END,
      private_stage_version=COALESCE(target_job.private_stage_version,EXCLUDED.private_stage_version),
      status = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
             AND COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
          THEN 'FAILED'
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN 'QUEUED'
        ELSE target_job.status
      END,
      priority = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) > v_stale_cutoff
          THEN target_job.priority
        ELSE LEAST(target_job.priority, EXCLUDED.priority)
      END,
      run_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
             AND COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
          THEN target_job.run_at_utc
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN v_now
        WHEN target_job.status = 'RUNNING' THEN target_job.run_at_utc
        ELSE LEAST(target_job.run_at_utc, EXCLUDED.run_at_utc)
      END,
      started_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
             AND COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
          THEN target_job.started_at_utc
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN NULL::timestamptz
        ELSE target_job.started_at_utc
      END,
      completed_at_utc = target_job.completed_at_utc,
      failed_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
             AND COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
          THEN v_now
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN NULL::timestamptz
        ELSE target_job.failed_at_utc
      END,
      last_error_json = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND target_job.completed_at_utc IS NULL
             AND target_job.failed_at_utc IS NULL
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
          THEN jsonb_build_object(
            'code', CASE
              WHEN COALESCE(target_job.attempt_count, 0) >= GREATEST(COALESCE(target_job.max_attempts, 8), 1)
                THEN 'STALE_RUNNING_WORKBENCH_JOB_MAX_ATTEMPTS'
              ELSE 'STALE_RUNNING_WORKBENCH_JOB_RECOVERED'
            END,
            'message', 'Recovered stale running workbench preview job during continuation enqueue.',
            'job_type', v_job_type,
            'session_id', p_session_id::text,
            'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
            'stale_running_seconds', v_stale_running_seconds,
            'recovered_at_utc', v_now
          )
        ELSE target_job.last_error_json
      END,
      payload_json = COALESCE(target_job.payload_json, '{}'::jsonb)
        || v_reuse_patch_json
        || CASE
          WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
               AND target_job.completed_at_utc IS NULL
               AND target_job.failed_at_utc IS NULL
               AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) <= v_stale_cutoff
            THEN jsonb_build_object(
              'stale_running_recovered_at_utc', v_now::text,
              'stale_running_recovered_by', 'pay_workbench_enqueue_stage_continuation'
            )
          ELSE '{}'::jsonb
        END,
      updated_at_utc = CASE
        WHEN UPPER(BTRIM(COALESCE(target_job.status, ''))) = 'RUNNING'
             AND COALESCE(target_job.updated_at_utc, target_job.started_at_utc, target_job.run_at_utc, target_job.created_at_utc) > v_stale_cutoff
          THEN target_job.updated_at_utc
        ELSE v_now
      END
  WHERE p_source_job_id IS NULL
     OR target_job.id IS DISTINCT FROM p_source_job_id
  RETURNING target_job.id,
            target_job.status,
            (xmax = 0)
  INTO v_job_id,
       v_job_status,
       v_job_was_inserted;

    GET DIAGNOSTICS v_insert_row_count = ROW_COUNT;

    IF COALESCE(v_insert_row_count, 0) = 0 THEN
      IF p_source_job_id IS NOT NULL
         AND EXISTS (
           SELECT 1
           FROM public.banking_pay_workbench_jobs AS self_reuse_source_job
           WHERE self_reuse_source_job.id = p_source_job_id
             AND self_reuse_source_job.dedupe_key = v_dedupe_key
             AND UPPER(BTRIM(COALESCE(self_reuse_source_job.status, ''))) IN ('QUEUED', 'RUNNING')
         ) THEN
        IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
          RETURN jsonb_build_object(
            'ok', true,
            'job_id', NULL::text,
            'job_type', v_job_type,
            'status', 'NOT_ENQUEUED',
            'session_id', p_session_id::text,
            'session_version', COALESCE(v_session_row.version, 0),
            'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
            'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
            'dedupe_key', v_dedupe_key,
            'cursor_token', v_cursor_token,
            'has_cursor', v_cursor_json IS NOT NULL,
            'limit', v_limit,
            'line_limit', v_limit,
            'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
            'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
            'refresh_scope_kind', v_refresh_scope_kind,
            'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
            'line_work_action', v_line_work_action,
            'next_recommended_action', v_next_recommended_action,
            'reused', false,
            'created', false,
            'superseded_stale_running_count', COALESCE(v_superseded_stale_count, 0),
            'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
            'projection_class', NULLIF(v_projection_class, ''),
            'phase', NULLIF(v_delta_phase, ''),
            'next_phase', NULLIF(v_delta_next_phase, ''),
            'delta_refresh_required', true,
            'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
            'continuation_reason', v_reason,
            'continuation_not_enqueued', true,
            'identical_cursor_self_reuse_suppressed', true,
            'self_reuse_prevented', true,
            'original_dedupe_key', COALESCE(v_original_dedupe_key, v_dedupe_key),
            'self_reuse_retry_count', COALESCE(v_self_reuse_retry_count, 0) + 1,
            'no_op', true,
            'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED'
          );
        END IF;
        IF v_self_reuse_prevented IS TRUE THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SELF_REUSE_BLOCKED'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'PAY_WORKBENCH_CONTINUATION_SELF_REUSE_BLOCKED',
                    'session_id', p_session_id::text,
                    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
                    'job_type', v_job_type,
                    'source_job_id', p_source_job_id::text,
                    'original_dedupe_key', v_original_dedupe_key,
                    'attempted_dedupe_key', v_dedupe_key,
                    'message', 'Continuation enqueue refused to return or update the currently running source job as its own continuation.'
                  )::text;
        END IF;

        v_self_reuse_prevented := true;
        v_self_reuse_retry_count := COALESCE(v_self_reuse_retry_count, 0) + 1;
        v_original_dedupe_key := COALESCE(v_original_dedupe_key, v_dedupe_key);
        v_dedupe_key := v_original_dedupe_key || ':after_source_job:' || p_source_job_id::text;

        v_payload_json := jsonb_strip_nulls(
          COALESCE(v_payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'dedupe_key', v_dedupe_key,
            'self_reuse_prevented', true,
            'continuation_self_reuse_prevented', true,
            'original_dedupe_key', v_original_dedupe_key,
            'self_reuse_safe_dedupe_key', v_dedupe_key,
            'self_reuse_source_job_id', p_source_job_id::text
          )
        );

        v_reuse_patch_json := COALESCE(v_reuse_patch_json, '{}'::jsonb)
          || jsonb_build_object(
            'self_reuse_prevented', true,
            'continuation_self_reuse_prevented', true,
            'original_dedupe_key', v_original_dedupe_key,
            'self_reuse_safe_dedupe_key', v_dedupe_key,
            'self_reuse_source_job_id', p_source_job_id::text
          );

        CONTINUE continuation_insert_attempt;
      END IF;

      RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_INSERT_RETURNED_NO_ROW'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CONTINUATION_INSERT_RETURNED_NO_ROW',
                'session_id', p_session_id::text,
                'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
                'job_type', v_job_type,
                'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
                'dedupe_key', v_dedupe_key,
                'message', 'Continuation insert/upsert returned no row without a recognised source-job self-reuse conflict.'
              )::text;
    END IF;

    IF p_source_job_id IS NOT NULL
       AND v_job_id IS NOT NULL
       AND v_job_id = p_source_job_id THEN
      IF v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
        RETURN jsonb_build_object(
          'ok', true,
          'job_id', NULL::text,
          'job_type', v_job_type,
          'status', 'NOT_ENQUEUED',
          'session_id', p_session_id::text,
          'session_version', COALESCE(v_session_row.version, 0),
          'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
          'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'dedupe_key', v_dedupe_key,
          'cursor_token', v_cursor_token,
          'has_cursor', v_cursor_json IS NOT NULL,
          'limit', v_limit,
          'line_limit', v_limit,
          'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
          'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
          'refresh_scope_kind', v_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
          'line_work_action', v_line_work_action,
          'next_recommended_action', v_next_recommended_action,
          'reused', false,
          'created', false,
          'superseded_stale_running_count', COALESCE(v_superseded_stale_count, 0),
          'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
          'projection_class', NULLIF(v_projection_class, ''),
          'phase', NULLIF(v_delta_phase, ''),
          'next_phase', NULLIF(v_delta_next_phase, ''),
          'delta_refresh_required', true,
          'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
          'continuation_reason', v_reason,
          'continuation_not_enqueued', true,
          'identical_cursor_self_reuse_suppressed', true,
          'self_reuse_prevented', true,
          'original_dedupe_key', COALESCE(v_original_dedupe_key, v_dedupe_key),
          'self_reuse_retry_count', COALESCE(v_self_reuse_retry_count, 0) + 1,
          'no_op', true,
          'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED'
        );
      END IF;
      IF v_self_reuse_prevented IS TRUE THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SELF_REUSE_BLOCKED'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'PAY_WORKBENCH_CONTINUATION_SELF_REUSE_BLOCKED',
                  'session_id', p_session_id::text,
                  'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
                  'job_type', v_job_type,
                  'source_job_id', p_source_job_id::text,
                  'original_dedupe_key', v_original_dedupe_key,
                  'attempted_dedupe_key', v_dedupe_key,
                  'message', 'Continuation helper still resolved to the current source job after self-reuse retry.'
                )::text;
      END IF;

      v_self_reuse_prevented := true;
      v_self_reuse_retry_count := COALESCE(v_self_reuse_retry_count, 0) + 1;
      v_original_dedupe_key := COALESCE(v_original_dedupe_key, v_dedupe_key);
      v_dedupe_key := v_original_dedupe_key || ':after_source_job:' || p_source_job_id::text;

      v_payload_json := jsonb_strip_nulls(
        COALESCE(v_payload_json, '{}'::jsonb)
        || jsonb_build_object(
          'dedupe_key', v_dedupe_key,
          'self_reuse_prevented', true,
          'continuation_self_reuse_prevented', true,
          'original_dedupe_key', v_original_dedupe_key,
          'self_reuse_safe_dedupe_key', v_dedupe_key,
          'self_reuse_source_job_id', p_source_job_id::text
        )
      );

      v_reuse_patch_json := COALESCE(v_reuse_patch_json, '{}'::jsonb)
        || jsonb_build_object(
          'self_reuse_prevented', true,
          'continuation_self_reuse_prevented', true,
          'original_dedupe_key', v_original_dedupe_key,
          'self_reuse_safe_dedupe_key', v_dedupe_key,
          'self_reuse_source_job_id', p_source_job_id::text
        );

      CONTINUE continuation_insert_attempt;
    END IF;

    EXIT continuation_insert_attempt;
  END LOOP;

  IF p_source_job_id IS NOT NULL
     AND v_job_id IS NOT NULL
     AND v_job_id = p_source_job_id
     AND v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'job_id', NULL::text,
      'job_type', v_job_type,
      'status', 'NOT_ENQUEUED',
      'session_id', p_session_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'dedupe_key', v_dedupe_key,
      'cursor_token', v_cursor_token,
      'has_cursor', v_cursor_json IS NOT NULL,
      'limit', v_limit,
      'line_limit', v_limit,
      'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
      'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
      'line_work_action', v_line_work_action,
      'next_recommended_action', v_next_recommended_action,
      'reused', false,
      'created', false,
      'superseded_stale_running_count', COALESCE(v_superseded_stale_count, 0),
      'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
      'projection_class', NULLIF(v_projection_class, ''),
      'phase', NULLIF(v_delta_phase, ''),
      'next_phase', NULLIF(v_delta_next_phase, ''),
      'delta_refresh_required', true,
      'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
      'continuation_reason', v_reason,
      'continuation_not_enqueued', true,
      'identical_cursor_self_reuse_suppressed', true,
      'self_reuse_prevented', true,
      'original_dedupe_key', COALESCE(v_original_dedupe_key, v_dedupe_key),
      'self_reuse_retry_count', COALESCE(v_self_reuse_retry_count, 0) + 1,
      'no_op', true,
      'reason', 'DELTA_IDENTICAL_CURSOR_SELF_REUSE_SUPPRESSED'
    );
  END IF;

  IF p_source_job_id IS NOT NULL
     AND v_job_id IS NOT NULL
     AND v_job_id = p_source_job_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_SELF_REUSE_BLOCKED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_SELF_REUSE_BLOCKED',
              'session_id', p_session_id::text,
              'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
              'job_type', v_job_type,
              'source_job_id', p_source_job_id::text,
              'original_dedupe_key', v_original_dedupe_key,
              'dedupe_key', v_dedupe_key,
              'message', 'Continuation helper refused to return the current source job as its own continuation.'
            )::text;
  END IF;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CONTINUATION_JOB_ID_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CONTINUATION_JOB_ID_MISSING',
              'session_id', p_session_id::text,
              'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
              'job_type', v_job_type,
              'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
              'dedupe_key', v_dedupe_key
            )::text;
  END IF;

  IF p_candidate_id IS NOT NULL THEN
    UPDATE public.banking_pay_workbench_session_scope AS scope_update
    SET status = v_scope_status,
        pending_job_id = v_job_id,
        dirty = CASE WHEN v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' THEN true ELSE false END,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE scope_update.session_id = p_session_id
      AND scope_update.candidate_id = p_candidate_id;
  END IF;

  BEGIN
    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS session_progress_lock
    WHERE session_progress_lock.id = p_session_id
      AND UPPER(BTRIM(COALESCE(session_progress_lock.status, ''))) = 'OPEN'
      AND session_progress_lock.discarded_at_utc IS NULL
      AND COALESCE(session_progress_lock.version, 1) = COALESCE(v_session_row.version, 1)
      AND session_progress_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
      AND session_progress_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
    FOR UPDATE NOWAIT;

    IF FOUND THEN
      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET progress_state = v_progress_state,
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb) || jsonb_build_object(
            'last_continuation_enqueue_at_utc', v_now::text,
            'last_continuation_job_id', v_job_id::text,
            'last_continuation_job_type', v_job_type,
            'last_continuation_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
            'last_continuation_reused', NOT v_job_was_inserted,
            'next_recommended_action', v_next_recommended_action,
            'phase', v_progress_state,
            'continuation_session_progress_locking', 'NOWAIT',
            'continuation_session_progress_update_applied', true,
            'continuation_session_progress_lock_skipped', false
          ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = p_session_id;

      GET DIAGNOSTICS v_session_progress_update_row_count = ROW_COUNT;
      v_session_progress_update_applied := COALESCE(v_session_progress_update_row_count, 0) > 0;
      v_session_progress_lock_skipped := COALESCE(v_session_progress_update_row_count, 0) <= 0;
      IF v_session_progress_lock_skipped THEN
        v_session_progress_lock_skip_reason := 'SESSION_UPDATE_NOT_APPLIED';
      END IF;
    ELSE
      v_session_progress_update_applied := false;
      v_session_progress_lock_skipped := true;
      v_session_progress_lock_skip_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
    END IF;
  EXCEPTION
    WHEN lock_not_available THEN
      v_session_progress_update_applied := false;
      v_session_progress_lock_skipped := true;
      v_session_progress_lock_skip_reason := 'SESSION_LOCK_NOT_AVAILABLE';
  END;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL::jsonb,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', v_job_type,
      'status', v_job_status,
      'session_id', p_session_id::text,
      'session_version', COALESCE(v_session_row.version, 0),
      'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'dedupe_key', v_dedupe_key,
      'cursor_token', v_cursor_token,
      'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
      'continuation_reason', v_reason,
      'reused', NOT v_job_was_inserted,
      'superseded_stale_running_count', COALESCE(v_superseded_stale_count, 0),
      'session_progress_update_applied', COALESCE(v_session_progress_update_applied, false),
      'session_progress_lock_skipped', COALESCE(v_session_progress_lock_skipped, false),
      'session_progress_lock_skip_reason', v_session_progress_lock_skip_reason,
      'self_reuse_prevented', COALESCE(v_self_reuse_prevented, false),
      'original_dedupe_key', CASE WHEN COALESCE(v_self_reuse_prevented, false) THEN v_original_dedupe_key ELSE NULL::text END,
      'self_reuse_retry_count', COALESCE(v_self_reuse_retry_count, 0)
    ),
    'WORKBENCH_STAGE_CONTINUATION_ENQUEUE',
    v_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', v_job_type,
    'status', v_job_status,
    'session_id', p_session_id::text,
    'session_version', COALESCE(v_session_row.version, 0),
    'snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'dedupe_key', v_dedupe_key,
    'cursor_token', v_cursor_token,
    'has_cursor', v_cursor_json IS NOT NULL,
    'limit', v_limit,
    'line_limit', v_limit,
    'source_build_run_id', NULLIF(v_source_build_run_id_token, 'none'),
    'source_change_seq', CASE WHEN v_source_change_seq_token ~ '^[0-9]{1,18}$' THEN v_source_change_seq_token::bigint ELSE NULL::bigint END,
    'refresh_scope_kind', v_refresh_scope_kind,
    'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids_json, '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids_json, '[]'::jsonb),
    'line_work_action', v_line_work_action,
    'next_recommended_action', v_next_recommended_action,
    'reused', NOT v_job_was_inserted,
    'created', v_job_was_inserted,
    'superseded_stale_running_count', COALESCE(v_superseded_stale_count, 0),
    'session_progress_update_applied', COALESCE(v_session_progress_update_applied, false),
    'session_progress_lock_skipped', COALESCE(v_session_progress_lock_skipped, false),
    'session_progress_lock_skip_reason', v_session_progress_lock_skip_reason,
    'projection_run_id', NULLIF(v_projection_run_id_token, 'none'),
    'projection_class', NULLIF(v_projection_class, ''),
    'phase', NULLIF(v_delta_phase, ''),
    'next_phase', NULLIF(v_delta_next_phase, ''),
    'delta_refresh_required', v_job_type = 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
    'source_job_id', CASE WHEN p_source_job_id IS NULL THEN NULL ELSE p_source_job_id::text END,
    'continuation_reason', v_reason,
    'self_reuse_prevented', COALESCE(v_self_reuse_prevented, false),
    'original_dedupe_key', CASE WHEN COALESCE(v_self_reuse_prevented, false) THEN v_original_dedupe_key ELSE NULL::text END,
    'self_reuse_retry_count', COALESCE(v_self_reuse_retry_count, 0)
  );
END;
$function$;

-- pay_workbench_fail_job(uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_fail_job(p_job_id uuid, p_error_json jsonb, p_retry_after_seconds integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := now();
  v_job_type text;
  v_canonical_job_type text := NULL::text;
  v_attempt_count integer;
  v_max_attempts integer;
  v_retry_after_seconds integer;
  v_next_run_at_utc timestamptz;
  v_new_status text;
  v_failed_at_utc timestamptz;
  v_job_snapshot_run_id uuid := NULL::uuid;
  v_job_session_id uuid := NULL::uuid;
  v_job_candidate_id uuid := NULL::uuid;
  v_job_dedupe_key text := NULL;
  v_job_created_at_utc timestamptz := NULL::timestamptz;
  v_job_payload_json jsonb := '{}'::jsonb;
  v_job_source_change_seq bigint := 0;
  v_job_session_version bigint := 0;
  v_live_candidate_change_seq bigint := 0;
  v_snapshot_state_status text := NULL;
  v_snapshot_state_source_change_seq bigint := 0;
  v_current_session_status text := NULL;
  v_current_session_version bigint := 0;
  v_current_session_snapshot_run_id uuid := NULL::uuid;
  v_session_candidate_status text := NULL;
  v_session_candidate_source_change_seq bigint := 0;
  v_session_candidate_session_version bigint := 0;
  v_other_active_job_id uuid := NULL::uuid;
  v_completed_equivalent_job_id uuid := NULL::uuid;
  v_is_obsolete boolean := false;
  v_obsolete_reason text := NULL;
  v_error_code text := UPPER(COALESCE(p_error_json->>'code', ''));
  v_error_message text := UPPER(COALESCE(p_error_json->>'message', ''));
  v_is_statement_timeout boolean := false;
  v_is_no_change_loop boolean := false;
  v_failed_line_work_count integer := 0;
  v_failed_source_row_count integer := 0;
  v_terminal_scope_updated_count integer := 0;
  v_source_build_run_id_text text := NULL::text;
  v_invalid_source_build_without_run_id boolean := false;
  v_economic_build_id uuid := NULL::uuid;
  v_private_stage text := NULL::text;
  v_attempt_id uuid := NULL::uuid;
  v_scale_block boolean := false;
  v_is_deterministic_stage_error boolean := false;
  v_terminal_repair_result jsonb := '{}'::jsonb;
  v_terminal_scope_status text := NULL::text;
  v_terminal_scope_pending_job_id uuid := NULL::uuid;
  v_terminal_scope_error_json jsonb := NULL::jsonb;
  v_terminal_owner_valid boolean := false;
BEGIN
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required';
  END IF;

  IF p_error_json IS NULL THEN
    RAISE EXCEPTION 'error_json is required';
  END IF;

  SELECT j.job_type,
         j.attempt_count,
         j.max_attempts,
         j.snapshot_run_id,
         j.session_id,
         j.candidate_id,
         j.dedupe_key,
         j.created_at_utc,
         COALESCE(j.payload_json, '{}'::jsonb),
         j.economic_build_id,
         j.private_stage
  INTO v_job_type,
       v_attempt_count,
       v_max_attempts,
       v_job_snapshot_run_id,
       v_job_session_id,
       v_job_candidate_id,
       v_job_dedupe_key,
       v_job_created_at_utc,
       v_job_payload_json,
       v_economic_build_id,
       v_private_stage
  FROM public.banking_pay_workbench_jobs AS j
  WHERE j.id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_jobs row % not found', p_job_id;
  END IF;

  v_job_source_change_seq := COALESCE(
    CASE
      WHEN COALESCE(v_job_payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
        THEN (v_job_payload_json->>'source_change_seq')::bigint
      ELSE 0::bigint
    END,
    0::bigint
  );
  v_job_session_version := COALESCE(
    CASE
      WHEN COALESCE(v_job_payload_json->>'session_version', '') ~ '^[0-9]+$'
        THEN (v_job_payload_json->>'session_version')::bigint
      ELSE 0::bigint
    END,
    0::bigint
  );

  v_canonical_job_type := CASE
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE')
      THEN 'WORKBENCH_SESSION_SCOPE_SEED'
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE')
      THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE')
      THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK')
      THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
    WHEN UPPER(BTRIM(COALESCE(v_job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK')
      THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
    ELSE UPPER(BTRIM(COALESCE(v_job_type, '')))
  END;

  -- Source-stage terminalisation and orphan repair must share the same
  -- candidate-serial authority.  The initial job read above is deliberately
  -- unlocked; candidate ownership is established before the job/attempt rows.
  IF v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND v_job_candidate_id IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(v_job_candidate_id),
      24062027
    ));
  END IF;

  IF v_canonical_job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND v_economic_build_id IS NOT NULL THEN
    PERFORM 1 FROM public.banking_pay_workbench_jobs WHERE id=p_job_id FOR UPDATE;
    SELECT attempt.id INTO v_attempt_id
    FROM private.banking_pay_workbench_stage_attempts attempt
    WHERE attempt.job_id=p_job_id AND attempt.build_id=v_economic_build_id
      AND attempt.private_stage=v_private_stage AND attempt.attempt_status='STARTED'
    ORDER BY attempt.attempt_number DESC,attempt.id DESC LIMIT 1 FOR UPDATE;
    IF v_attempt_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_ATTEMPT_FAILURE_CONTEXT_REQUIRED' USING ERRCODE='40001';
    END IF;
    v_scale_block:=v_error_code IN ('BLOCKED_UNVALIDATED_RECONCILIATION_SCALE',
      'PAY_WORKBENCH_UNVALIDATED_RECONCILIATION_SCALE');
    v_is_deterministic_stage_error := v_error_code IN (
      'CERTIFIED_SOURCE_PREVIEW_SEMANTIC_PARITY_FAILED',
      'PAYMENT_CORRECTION_SCOPE_TYPE_REQUIRED',
      'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISSING',
      'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_MISMATCH',
      'PAYMENT_CORRECTION_WORKBENCH_FROZEN_SCOPE_VERSION_UNSUPPORTED'
    );
    v_is_obsolete:=v_error_code IN ('PAY_WORKBENCH_BUILD_NOT_CURRENT','PAY_WORKBENCH_RECONCILIATION_ATTEMPT_STALE',
      'PAY_WORKBENCH_GENERATION_CHANGED','PAY_WORKBENCH_SOURCE_SEQUENCE_CHANGED');
    v_obsolete_reason:=CASE WHEN v_is_obsolete THEN COALESCE(NULLIF(v_error_code,''),'BUILD_OBSOLETE') END;
    UPDATE private.banking_pay_workbench_stage_attempts SET
      attempt_status=CASE WHEN v_is_obsolete THEN 'OBSOLETE' ELSE 'FAILED' END,
      failed_at_utc=CASE WHEN v_is_obsolete THEN NULL ELSE clock_timestamp() END,
      obsolete_at_utc=CASE WHEN v_is_obsolete THEN clock_timestamp() ELSE NULL END,
      result_code=COALESCE(NULLIF(v_error_code,''),'STAGE_ERROR'),
      error_class=CASE
        WHEN v_scale_block THEN 'SCALE_BLOCK'
        WHEN v_is_obsolete THEN 'OBSOLETE'
        WHEN v_is_deterministic_stage_error THEN 'DETERMINISTIC_STAGE_ERROR'
        ELSE 'RETRYABLE_STAGE_ERROR'
      END,
      error_json=jsonb_strip_nulls(jsonb_build_object('code',p_error_json->>'code',
        'message',p_error_json->>'message','sqlstate',p_error_json->>'sqlstate')),
      updated_at_utc=clock_timestamp()
    WHERE id=v_attempt_id AND attempt_status='STARTED';
    IF v_scale_block THEN
      UPDATE private.banking_pay_workbench_economic_builds SET
        status='BLOCKED_UNVALIDATED_RECONCILIATION_SCALE',failure_json=p_error_json,
        updated_at_utc=clock_timestamp() WHERE id=v_economic_build_id;
      UPDATE public.banking_pay_workbench_jobs SET status='SUCCEEDED',completed_at_utc=clock_timestamp(),
        failed_at_utc=NULL,last_error_json=p_error_json,updated_at_utc=clock_timestamp()
      WHERE id=p_job_id AND status='RUNNING';
      RETURN jsonb_build_object('ok',true,'job_id',p_job_id,'status','SUCCEEDED',
        'result_code','BLOCKED_UNVALIDATED_RECONCILIATION_SCALE','retry_scheduled',false);
    ELSIF v_is_obsolete THEN
      UPDATE private.banking_pay_workbench_economic_builds SET status='OBSOLETE',
        obsolete_at_utc=clock_timestamp(),failure_json=p_error_json,updated_at_utc=clock_timestamp()
      WHERE id=v_economic_build_id AND status NOT IN ('COMPLETE','FAILED');
      UPDATE public.banking_pay_workbench_jobs SET status='SUCCEEDED',completed_at_utc=clock_timestamp(),
        failed_at_utc=NULL,last_error_json=p_error_json,updated_at_utc=clock_timestamp()
      WHERE id=p_job_id AND status='RUNNING';

      v_terminal_repair_result := public.pay_workbench_repair_orphaned_pending_source_build(
        p_session_id => v_job_session_id,
        p_candidate_id => v_job_candidate_id,
        p_limit => 1,
        p_now_utc => clock_timestamp(),
        p_reason => 'OBSOLETE_SOURCE_STAGE_ATOMIC_REPAIR'
      );

      SELECT terminal_scope.status,
             terminal_scope.pending_job_id,
             terminal_scope.error_json
      INTO v_terminal_scope_status,
           v_terminal_scope_pending_job_id,
           v_terminal_scope_error_json
      FROM public.banking_pay_workbench_session_scope AS terminal_scope
      WHERE terminal_scope.session_id = v_job_session_id
        AND terminal_scope.candidate_id = v_job_candidate_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_OBSOLETE_SCOPE_MISSING'
          USING ERRCODE = 'P0001';
      END IF;

      IF UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) = 'SOURCE_BUILD_PENDING'
         AND v_terminal_scope_pending_job_id IS NOT NULL THEN
        SELECT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_jobs AS terminal_owner
          WHERE terminal_owner.id = v_terminal_scope_pending_job_id
            AND terminal_owner.session_id = v_job_session_id
            AND terminal_owner.candidate_id = v_job_candidate_id
            AND UPPER(BTRIM(COALESCE(terminal_owner.status, ''))) IN ('QUEUED', 'RUNNING')
        )
        INTO v_terminal_owner_valid;
      ELSE
        v_terminal_owner_valid := false;
      END IF;

      IF UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) = 'SOURCE_BUILD_PENDING'
         AND v_terminal_owner_valid IS NOT TRUE THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_OBSOLETE_SUCCESSOR_NOT_PROVEN'
          USING ERRCODE = 'P0001';
      END IF;

      IF UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) = 'SOURCE_BUILD_ERROR'
         AND v_terminal_scope_pending_job_id IS NULL THEN
        UPDATE public.banking_pay_workbench_session_candidate_state AS terminal_candidate_state
        SET status = 'ERROR',
            pending_job_id = NULL::uuid,
            last_error_json = COALESCE(v_terminal_scope_error_json, p_error_json),
            updated_at_utc = clock_timestamp()
        WHERE terminal_candidate_state.session_id = v_job_session_id
          AND terminal_candidate_state.candidate_id = v_job_candidate_id;
      ELSIF UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) = 'SOURCE_BUILD_PENDING'
            AND v_terminal_owner_valid THEN
        UPDATE public.banking_pay_workbench_session_candidate_state AS terminal_candidate_state
        SET status = 'PENDING',
            pending_job_id = v_terminal_scope_pending_job_id,
            last_error_json = '{}'::jsonb,
            updated_at_utc = clock_timestamp()
        WHERE terminal_candidate_state.session_id = v_job_session_id
          AND terminal_candidate_state.candidate_id = v_job_candidate_id;
      END IF;

      RETURN jsonb_build_object('ok',true,'job_id',p_job_id,'status','SUCCEEDED',
        'result_code','OBSOLETE','retry_scheduled',false,
        'terminal_repair_result',v_terminal_repair_result,
        'terminal_scope_status',v_terminal_scope_status,
        'terminal_successor_job_id',v_terminal_scope_pending_job_id,
        'terminal_successor_proven',(
          UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) <> 'SOURCE_BUILD_PENDING'
          OR v_terminal_owner_valid
        ));
    END IF;
    v_retry_after_seconds:=COALESCE(p_retry_after_seconds,
      LEAST(300,GREATEST(1,power(2,LEAST(COALESCE(v_attempt_count,1),8))::integer)));
    IF v_is_deterministic_stage_error IS NOT TRUE
       AND COALESCE(v_attempt_count,0)<COALESCE(v_max_attempts,8) THEN
      v_next_run_at_utc:=clock_timestamp()+make_interval(secs=>v_retry_after_seconds);
      UPDATE public.banking_pay_workbench_jobs SET status='QUEUED',run_at_utc=v_next_run_at_utc,
        started_at_utc=NULL,failed_at_utc=NULL,last_error_json=p_error_json,
        updated_at_utc=clock_timestamp() WHERE id=p_job_id AND status='RUNNING';
      RETURN jsonb_build_object('ok',true,'job_id',p_job_id,'status','QUEUED',
        'attempt_count',v_attempt_count,'max_attempts',v_max_attempts,
        'retry_scheduled',true,'next_run_at_utc',v_next_run_at_utc);
    END IF;
    UPDATE private.banking_pay_workbench_economic_builds SET status='FAILED',
      failed_at_utc=clock_timestamp(),failure_json=p_error_json,updated_at_utc=clock_timestamp()
    WHERE id=v_economic_build_id;
    UPDATE public.banking_pay_workbench_jobs SET status='FAILED',failed_at_utc=clock_timestamp(),
      completed_at_utc=NULL,last_error_json=p_error_json,updated_at_utc=clock_timestamp()
    WHERE id=p_job_id AND status='RUNNING';

    v_terminal_repair_result := public.pay_workbench_repair_orphaned_pending_source_build(
      p_session_id => v_job_session_id,
      p_candidate_id => v_job_candidate_id,
      p_limit => 1,
      p_now_utc => clock_timestamp(),
      p_reason => 'TERMINAL_SOURCE_STAGE_FAILURE_ATOMIC_REPAIR'
    );

    SELECT terminal_scope.status,
           terminal_scope.pending_job_id,
           terminal_scope.error_json
    INTO v_terminal_scope_status,
         v_terminal_scope_pending_job_id,
         v_terminal_scope_error_json
    FROM public.banking_pay_workbench_session_scope AS terminal_scope
    WHERE terminal_scope.session_id = v_job_session_id
      AND terminal_scope.candidate_id = v_job_candidate_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_TERMINAL_FAILURE_SCOPE_MISSING'
        USING ERRCODE = 'P0001';
    END IF;

    IF UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) = 'SOURCE_BUILD_PENDING'
       AND v_terminal_scope_pending_job_id IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_jobs AS terminal_owner
        WHERE terminal_owner.id = v_terminal_scope_pending_job_id
          AND terminal_owner.session_id = v_job_session_id
          AND terminal_owner.candidate_id = v_job_candidate_id
          AND UPPER(BTRIM(COALESCE(terminal_owner.status, ''))) IN ('QUEUED', 'RUNNING')
      )
      INTO v_terminal_owner_valid;
    ELSE
      v_terminal_owner_valid := false;
    END IF;

    IF UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) = 'SOURCE_BUILD_PENDING'
       AND v_terminal_owner_valid IS NOT TRUE THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_TERMINAL_FAILURE_SUCCESSOR_NOT_PROVEN'
        USING ERRCODE = 'P0001';
    END IF;

    IF UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) = 'SOURCE_BUILD_ERROR'
       AND v_terminal_scope_pending_job_id IS NULL THEN
      UPDATE public.banking_pay_workbench_session_candidate_state AS terminal_candidate_state
      SET status = 'ERROR',
          pending_job_id = NULL::uuid,
          last_error_json = COALESCE(v_terminal_scope_error_json, p_error_json),
          updated_at_utc = clock_timestamp()
      WHERE terminal_candidate_state.session_id = v_job_session_id
        AND terminal_candidate_state.candidate_id = v_job_candidate_id;
    ELSIF UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) = 'SOURCE_BUILD_PENDING'
          AND v_terminal_owner_valid THEN
      UPDATE public.banking_pay_workbench_session_candidate_state AS terminal_candidate_state
      SET status = 'PENDING',
          pending_job_id = v_terminal_scope_pending_job_id,
          last_error_json = '{}'::jsonb,
          updated_at_utc = clock_timestamp()
      WHERE terminal_candidate_state.session_id = v_job_session_id
        AND terminal_candidate_state.candidate_id = v_job_candidate_id;
    END IF;

    RETURN jsonb_build_object('ok',true,'job_id',p_job_id,'status','FAILED',
      'attempt_count',v_attempt_count,'max_attempts',v_max_attempts,
      'retry_scheduled',false,
      'result_code',CASE
        WHEN v_is_deterministic_stage_error THEN 'DETERMINISTIC_STAGE_ERROR'
        ELSE 'ATTEMPT_EXHAUSTED'
      END,
      'terminal_repair_result',v_terminal_repair_result,
      'terminal_scope_status',v_terminal_scope_status,
      'terminal_successor_job_id',v_terminal_scope_pending_job_id,
      'terminal_successor_proven',(
        UPPER(BTRIM(COALESCE(v_terminal_scope_status, ''))) <> 'SOURCE_BUILD_PENDING'
        OR v_terminal_owner_valid
      ));
  END IF;

  v_is_statement_timeout := (
    v_error_code = '57014'
    OR v_error_message LIKE '%STATEMENT TIMEOUT%'
    OR v_error_message LIKE '%CANCELING STATEMENT DUE TO STATEMENT TIMEOUT%'
  );

  v_is_no_change_loop := (
    v_error_code IN ('SNAPSHOT_ALREADY_CURRENT', 'ALREADY_CURRENT', 'NO_EFFECTIVE_CHANGE', 'PAYEE_READINESS_NO_EFFECTIVE_CHANGE', 'STALE_SESSION_VERSION', 'SESSION_DISCARDED')
    OR v_error_message LIKE '%ALREADY CURRENT%'
    OR v_error_message LIKE '%NO EFFECTIVE CHANGE%'
    OR v_error_message LIKE '%STALE SESSION VERSION%'
    OR v_error_message LIKE '%SESSION DISCARDED%'
  );

  IF v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN
    v_source_build_run_id_text := NULLIF(BTRIM(COALESCE(
      v_job_payload_json->>'source_build_run_id',
      v_job_payload_json#>>'{source_build,source_build_run_id}',
      v_job_payload_json#>>'{source_build,run_id}',
      v_job_payload_json#>>'{cursor,source_build_run_id}',
      v_job_payload_json#>>'{cursor_json,source_build_run_id}',
      v_job_payload_json#>>'{result_json,source_build_run_id}',
      ''
    )), '');

    IF v_source_build_run_id_text IS NULL
       OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_source_build_run_id_text := NULL::text;
      v_invalid_source_build_without_run_id := true;
    END IF;
  END IF;

  IF v_job_type = 'SNAPSHOT_CANDIDATE_REFRESH' THEN
    IF v_job_snapshot_run_id IS NULL OR v_job_candidate_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_SNAPSHOT_CONTEXT';
    ELSE
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      SELECT COALESCE(snap.status, NULL), COALESCE(snap.source_change_seq, 0)
      INTO v_snapshot_state_status, v_snapshot_state_source_change_seq
      FROM public.banking_pay_snapshot_candidate_state AS snap
      WHERE snap.snapshot_run_id = v_job_snapshot_run_id
        AND snap.candidate_id = v_job_candidate_id
      LIMIT 1;

      SELECT j.id
      INTO v_other_active_job_id
      FROM public.banking_pay_workbench_jobs AS j
      WHERE j.id <> p_job_id
        AND j.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
        AND j.snapshot_run_id = v_job_snapshot_run_id
        AND j.candidate_id = v_job_candidate_id
        AND j.status IN ('QUEUED', 'RUNNING')
        AND COALESCE(
              CASE
                WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                  THEN (j.payload_json->>'source_change_seq')::bigint
                ELSE 0::bigint
              END,
              0::bigint
            ) >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq)
      ORDER BY COALESCE(
                 CASE
                   WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                     THEN (j.payload_json->>'source_change_seq')::bigint
                   ELSE 0::bigint
                 END,
                 0::bigint
               ) DESC,
               j.updated_at_utc DESC NULLS LAST,
               j.created_at_utc DESC NULLS LAST,
               j.id DESC
      LIMIT 1;

      IF v_live_candidate_change_seq > v_job_source_change_seq THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
      ELSIF v_other_active_job_id IS NOT NULL THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'MATCHING_ACTIVE_SNAPSHOT_JOB_EXISTS';
      ELSIF UPPER(COALESCE(v_snapshot_state_status, '')) = 'READY'
            AND v_snapshot_state_source_change_seq >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq) THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SNAPSHOT_ALREADY_CURRENT';
      END IF;
    END IF;
  ELSIF v_job_type = 'SESSION_CANDIDATE_RECOMPUTE' THEN
    IF v_job_session_id IS NULL OR v_job_candidate_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_SESSION_CONTEXT';
    ELSE
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
      INTO v_current_session_status, v_current_session_version
      FROM public.banking_pay_workbench_sessions AS ws
      WHERE ws.id = v_job_session_id
      LIMIT 1;

      IF v_current_session_status IS NULL OR UPPER(COALESCE(v_current_session_status, '')) <> 'OPEN' THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SESSION_NOT_OPEN';
      ELSE
        SELECT COALESCE(scs.status, NULL),
               COALESCE(scs.source_change_seq, 0),
               COALESCE(scs.session_version, 0)
        INTO v_session_candidate_status,
             v_session_candidate_source_change_seq,
             v_session_candidate_session_version
        FROM public.banking_pay_workbench_session_candidate_state AS scs
        WHERE scs.session_id = v_job_session_id
          AND scs.candidate_id = v_job_candidate_id
        LIMIT 1;

        SELECT j.id
        INTO v_other_active_job_id
        FROM public.banking_pay_workbench_jobs AS j
        WHERE j.id <> p_job_id
          AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
          AND j.session_id = v_job_session_id
          AND j.candidate_id = v_job_candidate_id
          AND j.status IN ('QUEUED', 'RUNNING')
          AND COALESCE(
                CASE
                  WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                    THEN (j.payload_json->>'session_version')::bigint
                  ELSE 0::bigint
                END,
                0::bigint
              ) >= v_current_session_version
          AND COALESCE(
                CASE
                  WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                    THEN (j.payload_json->>'source_change_seq')::bigint
                  ELSE 0::bigint
                END,
                0::bigint
              ) >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq)
        ORDER BY COALESCE(
                   CASE
                     WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                       THEN (j.payload_json->>'session_version')::bigint
                     ELSE 0::bigint
                   END,
                   0::bigint
                 ) DESC,
                 COALESCE(
                   CASE
                     WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                       THEN (j.payload_json->>'source_change_seq')::bigint
                     ELSE 0::bigint
                   END,
                   0::bigint
                 ) DESC,
                 j.updated_at_utc DESC NULLS LAST,
                 j.created_at_utc DESC NULLS LAST,
                 j.id DESC
        LIMIT 1;

        IF v_current_session_version > v_job_session_version THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
        ELSIF v_other_active_job_id IS NOT NULL THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'MATCHING_ACTIVE_SESSION_JOB_EXISTS';
        ELSIF UPPER(COALESCE(v_session_candidate_status, '')) = 'READY'
              AND v_session_candidate_session_version >= v_current_session_version
              AND v_session_candidate_source_change_seq >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq) THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SESSION_ALREADY_CURRENT';
        END IF;
      END IF;
    END IF;
  ELSIF v_canonical_job_type IN (
    'WORKBENCH_SESSION_SCOPE_SEED',
    'WORKBENCH_CANDIDATE_SOURCE_BUILD',
    'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
    'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
    'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
  ) THEN
    IF v_job_session_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_WORKBENCH_SESSION_CONTEXT';
    ELSE
      SELECT COALESCE(workbench_session.status, NULL),
             COALESCE(workbench_session.version, 0),
             workbench_session.source_snapshot_run_id
      INTO v_current_session_status,
           v_current_session_version,
           v_current_session_snapshot_run_id
      FROM public.banking_pay_workbench_sessions AS workbench_session
      WHERE workbench_session.id = v_job_session_id
      LIMIT 1;

      IF v_current_session_status IS NULL OR UPPER(COALESCE(v_current_session_status, '')) <> 'OPEN' THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SESSION_NOT_OPEN';
      ELSIF v_job_snapshot_run_id IS NOT NULL
            AND v_current_session_snapshot_run_id IS DISTINCT FROM v_job_snapshot_run_id THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SESSION_SNAPSHOT_MISMATCH';
      ELSIF v_job_session_version > 0
            AND v_current_session_version > v_job_session_version THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
      END IF;
    END IF;

    IF v_is_obsolete IS NOT TRUE
       AND v_canonical_job_type IN (
         'WORKBENCH_CANDIDATE_SOURCE_BUILD',
         'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
         'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
         'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
       ) THEN
      IF v_job_candidate_id IS NULL THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'INVALID_WORKBENCH_CANDIDATE_CONTEXT';
      ELSE
        SELECT COALESCE(scope_row.status, NULL)
        INTO v_session_candidate_status
        FROM public.banking_pay_workbench_session_scope AS scope_row
        WHERE scope_row.session_id = v_job_session_id
          AND scope_row.candidate_id = v_job_candidate_id
        LIMIT 1;

        IF v_session_candidate_status IS NULL THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'CANDIDATE_NOT_IN_SESSION_SCOPE';
        END IF;
      END IF;
    END IF;

    IF v_is_obsolete IS NOT TRUE
       AND v_job_candidate_id IS NOT NULL
       AND v_job_source_change_seq > 0 THEN
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      IF COALESCE(v_live_candidate_change_seq, 0) > COALESCE(v_job_source_change_seq, 0) THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
      END IF;
    END IF;

    IF v_is_obsolete IS NOT TRUE
       AND v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_source_build_run_id_text IS NOT NULL
       AND v_job_session_id IS NOT NULL
       AND v_job_candidate_id IS NOT NULL
       AND v_job_source_change_seq > 0 THEN
      SELECT completed_source_build.id
      INTO v_completed_equivalent_job_id
      FROM public.banking_pay_workbench_jobs AS completed_source_build
      CROSS JOIN LATERAL (
        SELECT NULLIF(BTRIM(COALESCE(
          completed_source_build.payload_json->>'source_build_run_id',
          completed_source_build.payload_json#>>'{source_build,source_build_run_id}',
          completed_source_build.payload_json#>>'{source_build,run_id}',
          completed_source_build.payload_json#>>'{cursor,source_build_run_id}',
          completed_source_build.payload_json#>>'{cursor_json,source_build_run_id}',
          completed_source_build.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') AS source_build_run_id_text
      ) AS completed_run
      CROSS JOIN LATERAL (
        SELECT CASE
          WHEN COALESCE(completed_source_build.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
            THEN (completed_source_build.payload_json->>'source_change_seq')::bigint
          WHEN COALESCE(completed_source_build.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]+$'
            THEN (completed_source_build.payload_json#>>'{source_build,source_change_seq}')::bigint
          ELSE 0::bigint
        END AS source_change_seq
      ) AS completed_seq
      CROSS JOIN LATERAL (
        SELECT CASE
          WHEN COALESCE(completed_source_build.payload_json->>'session_version', '') ~ '^[0-9]+$'
            THEN (completed_source_build.payload_json->>'session_version')::bigint
          WHEN COALESCE(completed_source_build.payload_json#>>'{source_build,session_version}', '') ~ '^[0-9]+$'
            THEN (completed_source_build.payload_json#>>'{source_build,session_version}')::bigint
          ELSE 0::bigint
        END AS session_version
      ) AS completed_version
      WHERE completed_source_build.id <> p_job_id
        AND completed_source_build.session_id = v_job_session_id
        AND completed_source_build.candidate_id = v_job_candidate_id
        AND completed_source_build.snapshot_run_id IS NOT DISTINCT FROM v_job_snapshot_run_id
        AND UPPER(BTRIM(COALESCE(completed_source_build.status, ''))) = 'SUCCEEDED'
        AND completed_source_build.completed_at_utc IS NOT NULL
        AND completed_source_build.failed_at_utc IS NULL
        AND completed_source_build.created_at_utc > v_job_created_at_utc
        AND CASE
              WHEN UPPER(BTRIM(COALESCE(completed_source_build.job_type, ''))) IN (
                'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                'CANDIDATE_SOURCE_BUILD',
                'CANDIDATE_SOURCE_BUILD_CHUNK',
                'SOURCE_BUILD',
                'SOURCE_BUILD_PAGE'
              ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              ELSE UPPER(BTRIM(COALESCE(completed_source_build.job_type, '')))
            END = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND completed_run.source_build_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND completed_run.source_build_run_id_text IS DISTINCT FROM v_source_build_run_id_text
        AND completed_seq.source_change_seq = v_job_source_change_seq
        AND (
          v_job_session_version <= 0
          OR completed_version.session_version = v_job_session_version
        )
        AND EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_source_lines AS completed_source_row
          WHERE completed_source_row.session_id = v_job_session_id
            AND completed_source_row.candidate_id = v_job_candidate_id
            AND completed_source_row.source_build_run_id = completed_run.source_build_run_id_text::uuid
            AND completed_source_row.source_change_seq = v_job_source_change_seq
            AND (
              v_job_session_version <= 0
              OR completed_source_row.session_version = v_job_session_version
            )
            AND UPPER(BTRIM(COALESCE(completed_source_row.status, ''))) = 'CURRENT'
        )
      ORDER BY completed_source_build.completed_at_utc DESC,
               completed_source_build.created_at_utc DESC,
               completed_source_build.id DESC
      LIMIT 1;

      IF v_completed_equivalent_job_id IS NOT NULL THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_NEWER_SUCCESSFUL_SOURCE_BUILD';
      END IF;
    END IF;
  ELSIF v_job_type = 'PAYEE_READINESS_ENSURE' THEN
    IF v_job_candidate_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_READINESS_CONTEXT';
    ELSE
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      IF v_job_session_id IS NOT NULL THEN
        SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
        INTO v_current_session_status, v_current_session_version
        FROM public.banking_pay_workbench_sessions AS ws
        WHERE ws.id = v_job_session_id
        LIMIT 1;

        IF v_current_session_status IS NULL OR UPPER(COALESCE(v_current_session_status, '')) <> 'OPEN' THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SESSION_NOT_OPEN';
        ELSIF v_current_session_version > v_job_session_version THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
        END IF;
      END IF;

      IF NOT v_is_obsolete AND v_live_candidate_change_seq > v_job_source_change_seq THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
      END IF;

      IF NOT v_is_obsolete THEN
        SELECT j.id
        INTO v_completed_equivalent_job_id
        FROM public.banking_pay_workbench_jobs AS j
        WHERE j.id <> p_job_id
          AND j.job_type = 'PAYEE_READINESS_ENSURE'
          AND j.dedupe_key = v_job_dedupe_key
          AND j.completed_at_utc IS NOT NULL
          AND j.failed_at_utc IS NULL
        ORDER BY j.completed_at_utc DESC, j.id DESC
        LIMIT 1;

        IF v_completed_equivalent_job_id IS NOT NULL THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'COMPLETED_EQUIVALENT_EXISTS';
        ELSE
          SELECT j.id
          INTO v_other_active_job_id
          FROM public.banking_pay_workbench_jobs AS j
          WHERE j.id <> p_job_id
            AND j.job_type = 'PAYEE_READINESS_ENSURE'
            AND j.dedupe_key = v_job_dedupe_key
            AND j.status IN ('QUEUED', 'RUNNING')
          ORDER BY j.updated_at_utc DESC NULLS LAST, j.created_at_utc DESC NULLS LAST, j.id DESC
          LIMIT 1;

          IF v_other_active_job_id IS NOT NULL THEN
            v_is_obsolete := true;
            v_obsolete_reason := 'MATCHING_ACTIVE_READINESS_JOB_EXISTS';
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_is_statement_timeout THEN
    v_retry_after_seconds := GREATEST(
      300,
      LEAST(
        COALESCE(p_retry_after_seconds, GREATEST(COALESCE(v_attempt_count, 1), 1) * 300),
        14400
      )
    );
  ELSE
    v_retry_after_seconds := GREATEST(
      5,
      LEAST(
        COALESCE(p_retry_after_seconds, GREATEST(30, LEAST(COALESCE(v_attempt_count, 1) * 60, 3600))),
        86400
      )
    );
  END IF;

  IF v_is_obsolete
     OR v_is_no_change_loop
     OR (
       v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
       AND v_invalid_source_build_without_run_id IS TRUE
     )
     OR COALESCE(v_attempt_count, 0) >= COALESCE(v_max_attempts, 8) THEN
    v_new_status := CASE
      WHEN v_canonical_job_type IN (
        'WORKBENCH_SESSION_SCOPE_SEED',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
        'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
        'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
      ) THEN 'FAILED'
      ELSE 'DEAD'
    END;
    v_next_run_at_utc := NULL;
  ELSE
    v_new_status := 'QUEUED';
    v_next_run_at_utc := v_now + make_interval(secs => v_retry_after_seconds);
  END IF;

  UPDATE public.banking_pay_workbench_jobs AS j
  SET status = v_new_status,
      run_at_utc = COALESCE(v_next_run_at_utc, j.run_at_utc),
      updated_at_utc = v_now,
      started_at_utc = CASE WHEN v_new_status = 'QUEUED' THEN NULL ELSE j.started_at_utc END,
      completed_at_utc = NULL,
      failed_at_utc = CASE WHEN v_new_status = 'QUEUED' THEN NULL ELSE v_now END,
      last_error_json = p_error_json,
      payload_json = jsonb_strip_nulls(
        COALESCE(j.payload_json, '{}'::jsonb)
        || jsonb_build_object('last_failure_json', p_error_json)
        || CASE
          WHEN v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
               AND v_invalid_source_build_without_run_id IS TRUE THEN
            jsonb_build_object(
              'invalid_source_build_without_run_id_failed_closed', true,
              'invalid_source_build_without_run_id_non_blocking', true,
              'non_blocking_terminal_failure', true,
              'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
              'non_blocking_terminal_failure_at_utc', v_now::text,
              'source_build_run_id_required', true,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          WHEN v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
               AND v_obsolete_reason = 'SUPERSEDED_BY_NEWER_SUCCESSFUL_SOURCE_BUILD' THEN
            jsonb_build_object(
              'superseded_at_utc', v_now::text,
              'superseded_reason', v_obsolete_reason,
              'superseded_by_job_id', v_completed_equivalent_job_id::text,
              'non_blocking_terminal_failure', true,
              'non_blocking_terminal_failure_reason', v_obsolete_reason,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ELSE '{}'::jsonb
        END
      )
  WHERE j.id = p_job_id
  RETURNING j.failed_at_utc
  INTO v_failed_at_utc;

  IF v_new_status = 'FAILED'
     AND v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
     AND v_is_obsolete IS NOT TRUE
     AND v_job_session_id IS NOT NULL
     AND v_job_candidate_id IS NOT NULL THEN
    IF v_source_build_run_id_text IS NULL THEN
      v_failed_source_row_count := 0;

      PERFORM public._audit_insert(
        'banking_pay_workbench_candidate_source_lines',
        v_job_candidate_id::text,
        'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_DID_NOT_MARK_ROWS_ERROR',
        jsonb_build_object(
          'session_id', v_job_session_id::text,
          'candidate_id', v_job_candidate_id::text,
          'bad_job_id', p_job_id::text,
          'source_build_run_id', NULL::text,
          'source_change_seq', CASE WHEN v_job_source_change_seq = 0 THEN NULL ELSE v_job_source_change_seq END,
          'old_status', 'CURRENT_OR_DIRTY',
          'reason', 'SOURCE_BUILD_JOB_MISSING_SOURCE_BUILD_RUN_ID',
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        ),
        jsonb_build_object(
          'session_id', v_job_session_id::text,
          'candidate_id', v_job_candidate_id::text,
          'bad_job_id', p_job_id::text,
          'source_build_run_id', NULL::text,
          'source_change_seq', CASE WHEN v_job_source_change_seq = 0 THEN NULL ELSE v_job_source_change_seq END,
          'affected_row_count', 0,
          'source_rows_marked_error_count', 0,
          'new_status', 'UNCHANGED',
          'reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        ),
        'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_DID_NOT_MARK_ROWS_ERROR',
        NULL
      );

      PERFORM public._audit_insert(
        'banking_pay_workbench_session_scope',
        v_job_candidate_id::text,
        'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_IGNORED',
        jsonb_build_object(
          'session_id', v_job_session_id::text,
          'candidate_id', v_job_candidate_id::text,
          'bad_job_id', p_job_id::text,
          'source_build_run_id', NULL::text,
          'source_change_seq', CASE WHEN v_job_source_change_seq = 0 THEN NULL ELSE v_job_source_change_seq END,
          'reason', 'SOURCE_BUILD_JOB_MISSING_SOURCE_BUILD_RUN_ID',
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        ),
        jsonb_build_object(
          'session_id', v_job_session_id::text,
          'candidate_id', v_job_candidate_id::text,
          'bad_job_id', p_job_id::text,
          'source_build_run_id', NULL::text,
          'source_change_seq', CASE WHEN v_job_source_change_seq = 0 THEN NULL ELSE v_job_source_change_seq END,
          'scope_status_changed', false,
          'session_progress_changed', false,
          'reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        ),
        'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_IGNORED',
        NULL
      );
    ELSE
      IF to_regclass('public.banking_pay_workbench_candidate_source_lines') IS NOT NULL THEN
        WITH failed_source_rows AS (
          UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
          SET status = 'ERROR',
              source_row_json = COALESCE(source_line.source_row_json, '{}'::jsonb)
                || jsonb_build_object(
                  'source_build_error', jsonb_build_object(
                    'code', 'WORKBENCH_SOURCE_BUILD_JOB_FAILED',
                    'job_id', p_job_id::text,
                    'canonical_job_type', v_canonical_job_type,
                    'source_build_run_id', v_source_build_run_id_text,
                    'failed_at_utc', v_now::text,
                    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                  )
                ),
              updated_at_utc = v_now
          WHERE source_line.session_id = v_job_session_id
            AND source_line.candidate_id = v_job_candidate_id
            AND source_line.status IN ('CURRENT', 'DIRTY')
            AND source_line.source_build_run_id::text = v_source_build_run_id_text
          RETURNING source_line.id
        )
        SELECT COUNT(*)::integer
        INTO v_failed_source_row_count
        FROM failed_source_rows;
      END IF;

      UPDATE public.banking_pay_workbench_session_scope AS source_scope_row
      SET status = 'SOURCE_BUILD_ERROR',
          pending_job_id = NULL::uuid,
          dirty = true,
          error_json = jsonb_build_object(
            'code', 'WORKBENCH_SOURCE_BUILD_JOB_FAILED',
            'message', 'Candidate source build could not be completed after all retry attempts.',
            'job_id', p_job_id::text,
            'canonical_job_type', v_canonical_job_type,
            'source_build_run_id', v_source_build_run_id_text,
            'source_rows_marked_error_count', COALESCE(v_failed_source_row_count, 0),
            'attempt_count', COALESCE(v_attempt_count, 0),
            'max_attempts', COALESCE(v_max_attempts, 8),
            'automatic_recovery_scheduled', false,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          ),
          updated_at_utc = v_now
      WHERE source_scope_row.session_id = v_job_session_id
        AND source_scope_row.candidate_id = v_job_candidate_id
        AND (
          source_scope_row.pending_job_id = p_job_id
          OR source_scope_row.pending_job_id IS NULL
        );

      GET DIAGNOSTICS v_terminal_scope_updated_count = ROW_COUNT;

      UPDATE public.banking_pay_workbench_sessions AS source_session_row
      SET progress_state = 'ERROR',
          progress_json = COALESCE(source_session_row.progress_json, '{}'::jsonb) || jsonb_build_object(
            'last_source_build_failure_at_utc', v_now::text,
            'last_source_build_failure_job_id', p_job_id::text,
            'last_source_build_failure_code', COALESCE(NULLIF(BTRIM(p_error_json->>'code'), ''), 'WORKBENCH_SOURCE_BUILD_JOB_FAILED'),
            'last_source_build_failure_source_build_run_id', v_source_build_run_id_text,
            'last_source_build_source_rows_marked_error_count', COALESCE(v_failed_source_row_count, 0)
          ),
          progress_counter_version = COALESCE(source_session_row.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE source_session_row.id = v_job_session_id
        AND v_terminal_scope_updated_count > 0;
    END IF;
  END IF;

  IF v_new_status = 'FAILED'
     AND v_canonical_job_type = 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
     AND v_is_obsolete IS NOT TRUE
     AND v_job_session_id IS NOT NULL
     AND v_job_candidate_id IS NOT NULL THEN
    WITH failed_lines AS (
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET status = 'ERROR',
          error_json = jsonb_build_object(
            'code', 'WORKBENCH_LINE_WORK_PROCESS_JOB_FAILED',
            'message', 'Candidate line work was marked failed because its process job failed terminally.',
            'job_id', p_job_id::text,
            'session_id', v_job_session_id::text,
            'candidate_id', v_job_candidate_id::text,
            'attempt_count', COALESCE(v_attempt_count, 0),
            'max_attempts', COALESCE(v_max_attempts, 8),
            'automatic_recovery_scheduled', false,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          ),
          updated_at_utc = v_now
      WHERE line_work.session_id = v_job_session_id
        AND line_work.candidate_id = v_job_candidate_id
        AND UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'PENDING'
        AND EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_session_scope AS owned_scope
          WHERE owned_scope.session_id = v_job_session_id
            AND owned_scope.candidate_id = v_job_candidate_id
            AND (
              owned_scope.pending_job_id = p_job_id
              OR owned_scope.pending_job_id IS NULL
            )
        )
      RETURNING line_work.id
    )
    SELECT COUNT(*)::integer
    INTO v_failed_line_work_count
    FROM failed_lines;

    IF COALESCE(v_failed_line_work_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_session_scope AS scope_row
      SET status = 'ERROR',
          pending_job_id = NULL::uuid,
          dirty = true,
          error_json = jsonb_build_object(
            'code', 'WORKBENCH_LINE_WORK_PROCESS_JOB_FAILED',
            'message', 'Candidate line work process job failed terminally.',
            'job_id', p_job_id::text,
            'line_work_failed_count', v_failed_line_work_count,
            'attempt_count', COALESCE(v_attempt_count, 0),
            'max_attempts', COALESCE(v_max_attempts, 8),
            'automatic_recovery_scheduled', false,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
          ),
          updated_at_utc = v_now
      WHERE scope_row.session_id = v_job_session_id
        AND scope_row.candidate_id = v_job_candidate_id
        AND (
          scope_row.pending_job_id = p_job_id
          OR scope_row.pending_job_id IS NULL
        );

      GET DIAGNOSTICS v_terminal_scope_updated_count = ROW_COUNT;

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET line_units_pending = GREATEST(COALESCE(session_row.line_units_pending, 0) - COALESCE(v_failed_line_work_count, 0), 0),
          line_units_failed = GREATEST(COALESCE(session_row.line_units_failed, 0) + COALESCE(v_failed_line_work_count, 0), 0),
          progress_state = 'ERROR',
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb) || jsonb_build_object(
            'last_line_process_failure_at_utc', v_now::text,
            'last_line_process_failure_job_id', p_job_id::text,
            'last_line_process_failure_code', COALESCE(NULLIF(BTRIM(p_error_json->>'code'), ''), 'WORKBENCH_LINE_WORK_PROCESS_JOB_FAILED'),
            'last_line_process_failure_count', v_failed_line_work_count
          ),
          progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_row.id = v_job_session_id
        AND v_terminal_scope_updated_count > 0;
    END IF;
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    p_job_id::text,
    CASE WHEN v_new_status = 'QUEUED' THEN 'REQUEUED' WHEN v_new_status = 'FAILED' THEN 'FAILED' ELSE 'DEAD' END,
    NULL,
    jsonb_build_object(
      'id', p_job_id::text,
      'job_type', v_job_type,
      'canonical_job_type', v_canonical_job_type,
      'status', v_new_status,
      'attempt_count', v_attempt_count,
      'max_attempts', v_max_attempts,
      'run_at_utc', v_next_run_at_utc,
      'failed_at_utc', v_failed_at_utc,
      'last_error_json', p_error_json,
      'retry_after_seconds', CASE WHEN v_new_status = 'QUEUED' THEN v_retry_after_seconds ELSE NULL END,
      'obsolete', v_is_obsolete,
      'obsolete_reason', v_obsolete_reason,
      'statement_timeout', v_is_statement_timeout,
      'deterministic_no_change_loop', v_is_no_change_loop,
      'source_build_run_id', v_source_build_run_id_text,
      'invalid_source_build_without_run_id_failed_closed', COALESCE(v_invalid_source_build_without_run_id, false),
      'invalid_source_build_without_run_id_non_blocking', COALESCE(v_invalid_source_build_without_run_id, false) AND v_new_status <> 'QUEUED',
      'superseded_by_job_id', CASE
        WHEN v_obsolete_reason = 'SUPERSEDED_BY_NEWER_SUCCESSFUL_SOURCE_BUILD'
          THEN v_completed_equivalent_job_id::text
        ELSE NULL::text
      END,
      'non_blocking_terminal_failure', (
        COALESCE(v_invalid_source_build_without_run_id, false)
        OR v_obsolete_reason = 'SUPERSEDED_BY_NEWER_SUCCESSFUL_SOURCE_BUILD'
      ) AND v_new_status <> 'QUEUED',
      'line_work_failed_count', COALESCE(v_failed_line_work_count, 0),
      'source_rows_marked_error_count', COALESCE(v_failed_source_row_count, 0)
    ),
    CASE
      WHEN v_new_status = 'QUEUED' THEN 'WORKBENCH_JOB_REQUEUED'
      WHEN v_new_status = 'FAILED'
           AND v_canonical_job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
           AND v_invalid_source_build_without_run_id IS TRUE THEN 'WORKBENCH_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED'
      WHEN v_new_status = 'FAILED' THEN 'WORKBENCH_JOB_FAILED'
      ELSE 'WORKBENCH_JOB_DEAD'
    END,
    NULL
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'status', v_new_status,
    'canonical_job_type', v_canonical_job_type,
    'attempt_count', v_attempt_count,
    'max_attempts', v_max_attempts,
    'retry_after_seconds', CASE WHEN v_new_status = 'QUEUED' THEN v_retry_after_seconds ELSE NULL END,
    'next_run_at_utc', v_next_run_at_utc,
    'failed_at_utc', v_failed_at_utc,
    'error_json', p_error_json,
    'obsolete', v_is_obsolete,
    'obsolete_reason', v_obsolete_reason,
    'statement_timeout', v_is_statement_timeout,
    'deterministic_no_change_loop', v_is_no_change_loop,
    'source_build_run_id', v_source_build_run_id_text,
    'invalid_source_build_without_run_id_failed_closed', COALESCE(v_invalid_source_build_without_run_id, false),
    'invalid_source_build_without_run_id_non_blocking', COALESCE(v_invalid_source_build_without_run_id, false) AND v_new_status <> 'QUEUED',
    'superseded_by_job_id', CASE
      WHEN v_obsolete_reason = 'SUPERSEDED_BY_NEWER_SUCCESSFUL_SOURCE_BUILD'
        THEN v_completed_equivalent_job_id::text
      ELSE NULL::text
    END,
    'non_blocking_terminal_failure', (
      COALESCE(v_invalid_source_build_without_run_id, false)
      OR v_obsolete_reason = 'SUPERSEDED_BY_NEWER_SUCCESSFUL_SOURCE_BUILD'
    ) AND v_new_status <> 'QUEUED',
    'line_work_failed_count', COALESCE(v_failed_line_work_count, 0),
    'source_rows_marked_error_count', COALESCE(v_failed_source_row_count, 0)
  );
END;
$function$;

-- pay_workbench_filters_sanitise_v1(jsonb,date,date)
CREATE OR REPLACE FUNCTION public.pay_workbench_filters_sanitise_v1(p_filters_json jsonb, p_pay_date date DEFAULT NULL::date, p_week_ending_cutoff date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filters jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_filters_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(p_filters_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_nested_filters jsonb := '{}'::jsonb;
  v_strip_keys text[] := ARRAY[
    'preview_context_summary',
    'paye_guardrails',
    'preview_decisions_json',
    'preview_decisions',
    'open_options',
    'options',
    'progress_json',
    'candidate_sample_rows_json',
    'scope_next_cursor_json',
    'pay_date',
    'payDate',
    'pay_date_text',
    'payDateText',
    'source_pay_date',
    'sourcePayDate',
    'target_pay_date',
    'targetPayDate',
    'pay_week',
    'payWeek',
    'pay_week_label',
    'payWeekLabel',
    'pay_week_start',
    'payWeekStart',
    'pay_week_end',
    'payWeekEnd',
    'pay_period_start',
    'payPeriodStart',
    'pay_period_end',
    'payPeriodEnd',
    'week_start',
    'weekStart',
    'week_end',
    'weekEnd',
    'week_ending_cutoff',
    'weekEndingCutoff',
    'source_snapshot_run_id',
    'snapshot_run_id',
    'source_session_id',
    'sourceSessionId',
    'target_session_id',
    'targetSessionId',
    'session_id',
    'sessionId',
    'session_version',
    'sessionVersion',
    'session_signature',
    'sessionSignature',
    'clone_from_session_id',
    'cloneFromSessionId',
    'existing_paye_draft',
    'eligibility',
    'today_uk',
    'worker_metadata',
    'job_metadata',
    'source_build',
    'clone_rebase',
    'clone_rebase_result',
    'cursor',
    'cursor_json',
    'page_cursor',
    'candidate_cursor',
    'last_cursor',
    'active_jobs',
    'pending_job_ids_json',
    'replacement_session_id',
    'replacement_idempotency_key'
  ];
BEGIN
  v_filters := v_filters - v_strip_keys;

  IF jsonb_typeof(v_filters->'filters') = 'object' THEN
    v_nested_filters := COALESCE(v_filters->'filters', '{}'::jsonb) - v_strip_keys;
    v_filters := jsonb_set(v_filters, '{filters}', v_nested_filters, true);
  END IF;

  IF jsonb_typeof(v_filters->'filter') = 'object' THEN
    v_nested_filters := COALESCE(v_filters->'filter', '{}'::jsonb) - v_strip_keys;
    v_filters := jsonb_set(v_filters, '{filter}', v_nested_filters, true);
  END IF;

  RETURN jsonb_strip_nulls(v_filters);
END;
$function$;

-- pay_workbench_finance_case_dirty_apply_job_process(uuid,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_finance_case_dirty_apply_job_process(p_job_id uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := clock_timestamp();
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_payload jsonb := '{}'::jsonb;
  v_cursor_json jsonb := '{}'::jsonb;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_finance_case_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_id uuid;
  v_candidate_total integer := 0;
  v_candidate_batch_count integer := 0;
  v_after_candidate_id uuid := NULL::uuid;
  v_last_candidate_id uuid := NULL::uuid;
  v_has_more boolean := false;
  v_next_cursor_json jsonb := '{}'::jsonb;
  v_payload_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_reason text := 'DIRTY_TRIGGER:FINANCE_CASE';
  v_enqueue_result jsonb := '{}'::jsonb;
  v_jobs_queued integer := 0;
  v_latest_source_change_seq bigint := 0;
  v_gate_candidate_id uuid := NULL::uuid;
  v_gate_result jsonb := '{}'::jsonb;
  v_gate_allowed_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_gate_blocked boolean := false;
  v_gate_blocked_candidate_id uuid := NULL::uuid;
  v_gate_last_allowed_candidate_id uuid := NULL::uuid;
BEGIN
  SELECT job_row.*
  INTO v_job
  FROM public.banking_pay_workbench_jobs AS job_row
  WHERE job_row.id = p_job_id;

  IF v_job.id IS NULL THEN
    RAISE EXCEPTION 'Banking Pay finance-case dirty apply job not found: %', p_job_id
      USING ERRCODE = 'P0002';
  END IF;
  IF UPPER(BTRIM(COALESCE(v_job.job_type, ''))) <> 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY' THEN
    RAISE EXCEPTION 'Job % is %, not WORKBENCH_FINANCE_CASE_DIRTY_APPLY', p_job_id, v_job.job_type
      USING ERRCODE = '22023';
  END IF;
  IF UPPER(BTRIM(COALESCE(v_job.status, ''))) <> 'RUNNING' THEN
    RAISE EXCEPTION 'Job % must be RUNNING before processing; status=%', p_job_id, v_job.status
      USING ERRCODE = '55000';
  END IF;

  IF v_job.scope_change_generation IS NOT NULL THEN
    PERFORM set_config(
      'cloudtms.banking_pay_inherited_scope_generation',
      v_job.scope_change_generation::text,
      true
    );
  END IF;

  v_payload := CASE
    WHEN jsonb_typeof(COALESCE(v_job.payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(v_job.payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_cursor_json := CASE
    WHEN jsonb_typeof(v_payload->'cursor_json') = 'object' THEN v_payload->'cursor_json'
    WHEN jsonb_typeof(v_payload->'next_cursor_json') = 'object' THEN v_payload->'next_cursor_json'
    WHEN jsonb_typeof(v_payload->'cursor') = 'object' THEN v_payload->'cursor'
    ELSE '{}'::jsonb
  END;
  v_reason := COALESCE(NULLIF(BTRIM(COALESCE(v_payload->>'reason_latest', v_payload->>'reason', '')), ''), v_reason);

  IF COALESCE(v_cursor_json->>'after_candidate_id', v_cursor_json->>'last_candidate_id', '') ~* v_uuid_re THEN
    v_after_candidate_id := COALESCE(v_cursor_json->>'after_candidate_id', v_cursor_json->>'last_candidate_id')::uuid;
  END IF;

  v_latest_source_change_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_payload->>'latest_source_change_seq', '') ~ '^\d+$' THEN (v_payload->>'latest_source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_seq', '') ~ '^\d+$' THEN (v_payload->>'source_change_seq')::bigint END, 0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_sequence', '') ~ '^\d+$' THEN (v_payload->>'source_change_sequence')::bigint END, 0)
  );

  SELECT COALESCE(array_agg(DISTINCT finance_cases.finance_case_id ORDER BY finance_cases.finance_case_id), ARRAY[]::uuid[])
  INTO v_finance_case_ids
  FROM (
    SELECT value_text::uuid AS finance_case_id
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_payload->'finance_case_ids') = 'array' THEN v_payload->'finance_case_ids' ELSE '[]'::jsonb END) AS raw_value(value_text)
    WHERE raw_value.value_text ~* v_uuid_re
    UNION ALL
    SELECT (v_payload->>'finance_case_id')::uuid
    WHERE COALESCE(v_payload->>'finance_case_id', '') ~* v_uuid_re
    UNION ALL
    SELECT (v_payload->>'old_finance_case_id')::uuid
    WHERE COALESCE(v_payload->>'old_finance_case_id', '') ~* v_uuid_re
    UNION ALL
    SELECT (v_payload->>'new_finance_case_id')::uuid
    WHERE COALESCE(v_payload->>'new_finance_case_id', '') ~* v_uuid_re
    UNION ALL
    SELECT (v_payload->>'scope_id')::uuid
    WHERE UPPER(BTRIM(COALESCE(v_payload->>'scope_kind', ''))) = 'FINANCE_CASE'
      AND COALESCE(v_payload->>'scope_id', '') ~* v_uuid_re
  ) AS finance_cases
  WHERE finance_cases.finance_case_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT payload_timesheets.timesheet_id ORDER BY payload_timesheets.timesheet_id), ARRAY[]::uuid[])
  INTO v_payload_targeted_timesheet_ids
  FROM (
    SELECT value_text::uuid AS timesheet_id
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_payload->'targeted_timesheet_ids') = 'array' THEN v_payload->'targeted_timesheet_ids' ELSE '[]'::jsonb END) AS raw_value(value_text)
    WHERE raw_value.value_text ~* v_uuid_re
  ) AS payload_timesheets
  WHERE payload_timesheets.timesheet_id IS NOT NULL;

  WITH candidate_source AS (
    SELECT value_text::uuid AS candidate_id
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_payload->'candidate_ids') = 'array' THEN v_payload->'candidate_ids' ELSE '[]'::jsonb END) AS raw_value(value_text)
    WHERE raw_value.value_text ~* v_uuid_re
    UNION ALL
    SELECT (v_payload->>'candidate_id')::uuid
    WHERE COALESCE(v_payload->>'candidate_id', '') ~* v_uuid_re
    UNION ALL
    SELECT derived_payload_candidate.candidate_id
    FROM public._pay_workbench_candidate_serial_candidate_ids(v_job.candidate_id, v_payload) AS derived_payload_candidate(candidate_id)
    WHERE derived_payload_candidate.candidate_id IS NOT NULL
    UNION ALL
    SELECT component_row.candidate_id
    FROM public.pay_finance_case_components AS component_row
    WHERE COALESCE(array_length(v_finance_case_ids, 1), 0) > 0
      AND component_row.finance_case_id = ANY(v_finance_case_ids)
    UNION ALL
    SELECT advance_row.candidate_id
    FROM public.pay_advances AS advance_row
    WHERE COALESCE(array_length(v_finance_case_ids, 1), 0) > 0
      AND advance_row.id = ANY(v_finance_case_ids)
  ), candidate_distinct AS (
    SELECT DISTINCT candidate_source.candidate_id
    FROM candidate_source
    WHERE candidate_source.candidate_id IS NOT NULL
  ), candidate_after_cursor AS (
    SELECT candidate_distinct.candidate_id
    FROM candidate_distinct
    WHERE v_after_candidate_id IS NULL OR candidate_distinct.candidate_id > v_after_candidate_id
  ), candidate_limited AS (
    SELECT candidate_after_cursor.candidate_id
    FROM candidate_after_cursor
    ORDER BY candidate_after_cursor.candidate_id
    LIMIT v_limit
  )
  SELECT
    COALESCE((SELECT count(*)::integer FROM candidate_after_cursor), 0),
    COALESCE((SELECT array_agg(candidate_limited.candidate_id ORDER BY candidate_limited.candidate_id) FROM candidate_limited), ARRAY[]::uuid[])
  INTO v_candidate_total, v_candidate_ids;

  v_candidate_batch_count := COALESCE(array_length(v_candidate_ids, 1), 0);
  IF v_candidate_batch_count > 0 THEN
    SELECT candidate_values.candidate_id
    INTO v_last_candidate_id
    FROM unnest(v_candidate_ids) AS candidate_values(candidate_id)
    ORDER BY candidate_values.candidate_id DESC
    LIMIT 1;
  END IF;
  v_has_more := COALESCE(v_candidate_total, 0) > COALESCE(v_candidate_batch_count, 0);
  v_next_cursor_json := CASE
    WHEN v_has_more IS TRUE AND v_last_candidate_id IS NOT NULL THEN jsonb_build_object(
      'after_candidate_id', v_last_candidate_id::text,
      'last_candidate_id', v_last_candidate_id::text
    )
    ELSE '{}'::jsonb
  END;

  v_gate_allowed_candidate_ids := ARRAY[]::uuid[];
  v_gate_blocked := false;
  v_gate_blocked_candidate_id := NULL::uuid;
  v_gate_last_allowed_candidate_id := NULL::uuid;

  FOREACH v_gate_candidate_id IN ARRAY v_candidate_ids
  LOOP
    v_gate_result := public._pay_workbench_candidate_serial_try_gate(
      p_job_id => v_job.id,
      p_candidate_id => v_gate_candidate_id,
      p_job_type => v_job.job_type,
      p_payload_json => v_payload || jsonb_build_object(
        'candidate_id', v_gate_candidate_id::text,
        'candidate_serial_candidate_id', v_gate_candidate_id::text,
        'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_gate_candidate_id),
        'finance_case_ids', COALESCE(to_jsonb(v_finance_case_ids), '[]'::jsonb),
        'cursor_json', v_cursor_json
      ),
      p_reason => 'CANDIDATE_SERIAL_FINANCE_CASE_DIRTY_GATE'
    );

    IF lower(BTRIM(COALESCE(v_gate_result->>'blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(v_gate_result->>'allowed', 'true'))) IN ('false', 'f', '0', 'no', 'n', 'off') THEN
      v_gate_blocked := true;
      v_gate_blocked_candidate_id := v_gate_candidate_id;
      EXIT;
    END IF;

    v_gate_allowed_candidate_ids := array_append(v_gate_allowed_candidate_ids, v_gate_candidate_id);
    v_gate_last_allowed_candidate_id := v_gate_candidate_id;
  END LOOP;

  IF v_gate_blocked IS TRUE THEN
    SELECT COALESCE(array_agg(DISTINCT allowed_candidate.candidate_id ORDER BY allowed_candidate.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM unnest(COALESCE(v_gate_allowed_candidate_ids, ARRAY[]::uuid[])) AS allowed_candidate(candidate_id)
    WHERE allowed_candidate.candidate_id IS NOT NULL;

    v_candidate_batch_count := COALESCE(array_length(v_candidate_ids, 1), 0);
    v_last_candidate_id := v_gate_last_allowed_candidate_id;
    v_has_more := true;
    v_next_cursor_json := jsonb_strip_nulls(
      CASE
        WHEN v_gate_last_allowed_candidate_id IS NOT NULL THEN
          jsonb_build_object(
            'after_candidate_id', v_gate_last_allowed_candidate_id::text,
            'last_candidate_id', v_gate_last_allowed_candidate_id::text
          )
        ELSE
          COALESCE(v_cursor_json, '{}'::jsonb)
      END
      || jsonb_build_object(
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'candidate_serial_blocked_at_utc', v_now::text,
        'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_FINANCE_CASE_DIRTY_DELAYED'),
        'candidate_serial_delayed', true
      )
    );

    PERFORM public._pay_workbench_candidate_serial_audit(
      'CANDIDATE_SERIAL_FINANCE_CASE_DIRTY_DELAYED',
      p_job_id,
      v_gate_blocked_candidate_id,
      COALESCE(v_gate_result, '{}'::jsonb) || jsonb_build_object(
        'job_type', v_job.job_type,
        'finance_case_ids', COALESCE(to_jsonb(v_finance_case_ids), '[]'::jsonb),
        'cursor_json', v_cursor_json,
        'next_cursor_json', v_next_cursor_json,
        'allowed_before_block_count', COALESCE(v_candidate_batch_count, 0),
        'blocked_candidate_preserved', true,
        'candidate_dirty_enqueue_skipped_for_blocked_candidate', true
      ),
      'CANDIDATE_SERIAL_FINANCE_CASE_DIRTY_DELAYED',
      NULL::uuid
    );

    IF COALESCE(v_candidate_batch_count, 0) = 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS job_update
      SET payload_json = public._pay_workbench_dirty_payload_merge(
            COALESCE(job_update.payload_json, '{}'::jsonb),
            jsonb_build_object(
              'processed_at_utc', v_now::text,
              'processed_candidate_count', 0,
              'processed_source_change_seq', v_latest_source_change_seq,
              'candidate_dirty_jobs_queued', 0,
              'candidate_serial_delayed', true,
              'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
              'candidate_serial_wait_reason', COALESCE(v_gate_result->>'reason', 'CANDIDATE_SERIAL_FINANCE_CASE_DIRTY_DELAYED'),
              'candidate_dirty_enqueue_skipped_for_blocked_candidate', true,
              'has_more', true,
              'rerun_required', true,
              'next_cursor_json', v_next_cursor_json,
              'cursor_json', v_next_cursor_json,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
          ),
          updated_at_utc = v_now
      WHERE job_update.id = p_job_id;

      RETURN jsonb_build_object(
        'ok', true,
        'job_id', p_job_id::text,
        'job_type', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
        'finance_case_count', COALESCE(array_length(v_finance_case_ids, 1), 0),
        'candidate_count', 0,
        'candidate_total_after_cursor', COALESCE(v_candidate_total, 0),
        'candidate_dirty_jobs_queued', 0,
        'candidate_serial_delayed', true,
        'candidate_serial_blocked_candidate_id', v_gate_blocked_candidate_id::text,
        'has_more', true,
        'next_cursor_json', v_next_cursor_json,
        'last_candidate_id', NULL::text,
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      );
    END IF;
  END IF;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    p_job_id::text,
    jsonb_build_object(
      'function_name', 'pay_workbench_finance_case_dirty_apply_job_process',
      'stage', 'dirty_worker_apply_start',
      'job_id', p_job_id::text,
      'finance_case_count', COALESCE(array_length(v_finance_case_ids, 1), 0),
      'candidate_total_after_cursor', COALESCE(v_candidate_total, 0),
      'candidate_count', COALESCE(v_candidate_batch_count, 0),
      'after_candidate_id', CASE WHEN v_after_candidate_id IS NULL THEN NULL ELSE v_after_candidate_id::text END,
      'has_more', COALESCE(v_has_more, false)
    )
  );

  IF COALESCE(array_length(v_finance_case_ids, 1), 0) = 0
     AND COALESCE(array_length(v_candidate_ids, 1), 0) = 0 THEN
    UPDATE public.banking_pay_workbench_jobs AS job_update
    SET payload_json = public._pay_workbench_dirty_payload_merge(
          COALESCE(job_update.payload_json, '{}'::jsonb),
          jsonb_build_object(
            'processed_at_utc', v_now::text,
            'processed_candidate_count', 0,
            'candidate_dirty_jobs_queued', 0,
            'processed_source_change_seq', v_latest_source_change_seq,
            'fail_closed_no_finance_case_or_candidate_scope', true,
            'has_more', false,
            'next_cursor_json', '{}'::jsonb
          )
        ),
        updated_at_utc = v_now
    WHERE job_update.id = p_job_id;

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', p_job_id::text,
      'job_type', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
      'finance_case_count', 0,
      'candidate_count', 0,
      'candidate_dirty_jobs_queued', 0,
      'fail_closed_no_finance_case_or_candidate_scope', true,
      'has_more', false,
      'next_cursor_json', '{}'::jsonb,
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    );
  END IF;

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP
    SELECT COALESCE(array_agg(DISTINCT timesheet_candidates.timesheet_id ORDER BY timesheet_candidates.timesheet_id), ARRAY[]::uuid[])
    INTO v_targeted_timesheet_ids
    FROM (
      SELECT unnest(v_payload_targeted_timesheet_ids) AS timesheet_id
      UNION ALL
      SELECT component_row.linked_timesheet_id
      FROM public.pay_finance_case_components AS component_row
      WHERE component_row.candidate_id = v_candidate_id
        AND component_row.linked_timesheet_id IS NOT NULL
        AND COALESCE(array_length(v_finance_case_ids, 1), 0) > 0
        AND component_row.finance_case_id = ANY(v_finance_case_ids)
      UNION ALL
      SELECT advance_row.linked_timesheet_id
      FROM public.pay_advances AS advance_row
      WHERE advance_row.candidate_id = v_candidate_id
        AND advance_row.linked_timesheet_id IS NOT NULL
        AND COALESCE(array_length(v_finance_case_ids, 1), 0) > 0
        AND advance_row.id = ANY(v_finance_case_ids)
    ) AS timesheet_candidates
    WHERE timesheet_candidates.timesheet_id IS NOT NULL;

    SELECT public.pay_workbench_dirty_event_enqueue(
      p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
      p_scope_kind => 'CANDIDATE',
      p_scope_id => v_candidate_id::text,
      p_candidate_id => v_candidate_id,
      p_targeted_timesheet_ids => v_targeted_timesheet_ids,
      p_linked_timesheet_ids => ARRAY[]::uuid[],
      p_payload_json => public._pay_workbench_dirty_payload_merge(
        v_payload,
        jsonb_build_object(
          'scope_kind', 'CANDIDATE',
          'scope_id', v_candidate_id::text,
          'candidate_id', v_candidate_id::text,
          'candidate_ids', to_jsonb(ARRAY[v_candidate_id]),
          'candidate_serial_key', public._pay_workbench_candidate_serial_key(v_candidate_id),
          'candidate_serial_candidate_id', v_candidate_id::text,
          'candidate_serial_active_chain_id', COALESCE(NULLIF(BTRIM(COALESCE(v_payload->>'candidate_serial_active_chain_id', '')), ''), v_job.id::text),
          'candidate_serial_source_job_id', v_job.id::text,
          'candidate_serial_reason', 'CANDIDATE_SERIAL_FINANCE_CASE_DIRTY_FANOUT_QUEUED',
          'finance_case_ids', COALESCE(to_jsonb(v_finance_case_ids), '[]'::jsonb),
          'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
          'linked_scope_recompute_required', true,
          'refresh_scope_kind', CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END,
          'reason', v_reason,
          'reason_latest', v_reason,
          'projection_class', 'FINANCE_CASE',
          'fallback_reason', 'FINANCE_CASE_DIRTY_APPLY_FANOUT',
          'source_build_required', true,
          'line_work_required', true,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      ),
      p_reason => v_reason,
      p_priority => -1000,
      p_run_at_utc => v_now
    )
    INTO v_enqueue_result;

    IF LOWER(BTRIM(COALESCE(v_enqueue_result->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_jobs_queued := v_jobs_queued + 1;
    END IF;
  END LOOP;

  UPDATE public.banking_pay_workbench_jobs AS job_update
  SET payload_json = public._pay_workbench_dirty_payload_merge(
        COALESCE(job_update.payload_json, '{}'::jsonb),
        jsonb_build_object(
          'processed_at_utc', v_now::text,
          'processed_candidate_count', COALESCE(v_candidate_batch_count, 0),
          'processed_source_change_seq', v_latest_source_change_seq,
          'candidate_dirty_jobs_queued', v_jobs_queued,
          'has_more', COALESCE(v_has_more, false),
          'next_cursor_json', COALESCE(v_next_cursor_json, '{}'::jsonb),
          'cursor_json', CASE WHEN v_has_more THEN COALESCE(v_next_cursor_json, '{}'::jsonb) ELSE '{}'::jsonb END
        )
      ),
      updated_at_utc = v_now
  WHERE job_update.id = p_job_id;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    p_job_id::text,
    jsonb_build_object(
      'function_name', 'pay_workbench_finance_case_dirty_apply_job_process',
      'stage', 'dirty_worker_apply_done',
      'job_id', p_job_id::text,
      'candidate_count', COALESCE(v_candidate_batch_count, 0),
      'jobs_queued', v_jobs_queued,
      'has_more', COALESCE(v_has_more, false),
      'next_cursor_json', COALESCE(v_next_cursor_json, '{}'::jsonb),
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'job_type', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'finance_case_count', COALESCE(array_length(v_finance_case_ids, 1), 0),
    'candidate_count', COALESCE(v_candidate_batch_count, 0),
    'candidate_total_after_cursor', COALESCE(v_candidate_total, 0),
    'candidate_dirty_jobs_queued', v_jobs_queued,
    'candidate_serial_delayed', COALESCE(v_gate_blocked, false),
    'candidate_serial_blocked_candidate_id', CASE WHEN v_gate_blocked_candidate_id IS NULL THEN NULL::text ELSE v_gate_blocked_candidate_id::text END,
    'has_more', COALESCE(v_has_more, false),
    'next_cursor_json', COALESCE(v_next_cursor_json, '{}'::jsonb),
    'last_candidate_id', CASE WHEN v_last_candidate_id IS NULL THEN NULL ELSE v_last_candidate_id::text END,
    'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
  );
END;
$function$;

-- pay_workbench_mark_candidate_dirty()
CREATE OR REPLACE FUNCTION public.pay_workbench_mark_candidate_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := clock_timestamp();
  v_trigger_table text := lower(TG_TABLE_NAME);
  v_new_row jsonb := '{}'::jsonb;
  v_old_row jsonb := '{}'::jsonb;
  v_previous_tsfin_row jsonb := '{}'::jsonb;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_id uuid;
  v_old_timesheet_id uuid := NULL::uuid;
  v_new_timesheet_id uuid := NULL::uuid;
  v_old_contract_id uuid := NULL::uuid;
  v_new_contract_id uuid := NULL::uuid;
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_old_payment_eligible boolean := false;
  v_new_payment_eligible boolean := false;
  v_authorise_boundary_changed boolean := false;
  v_authorise_boundary_is_authorise boolean := false;
  v_authorise_boundary_is_unauthorise boolean := false;
  v_archive_boundary_changed boolean := false;
  v_archive_boundary_is_archive boolean := false;
  v_archive_boundary_is_unarchive boolean := false;
  v_material_live_source_changed boolean := false;
  v_signal_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_signal_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_signal_batch_row record;
  v_signal_reason text := NULL::text;
  v_signal_result jsonb := '{}'::jsonb;
  v_tsfin_payability_state_changed boolean := false;
  v_timesheet_pay_state_settlement_changed boolean := false;
  v_timesheet_pay_state_summary_changed boolean := false;
  v_timesheet_pay_state_bookkeeping_ignored boolean := false;
  v_timesheet_pay_state_noop_ignored boolean := false;
  v_timesheet_pay_state_routing_reason text := NULL::text;
  v_tsfin_insert_authorise_like boolean := false;
  v_tsfin_insert_not_coalesced_reason text := NULL::text;
  v_tsfin_insert_coalesced_job_id uuid := NULL::uuid;
  v_tsfin_insert_coalesced_projection_run_id uuid := NULL::uuid;
  v_tsfin_insert_coalesced_session_id uuid := NULL::uuid;
  v_tsfin_insert_coalesced_source_change_seq bigint := NULL::bigint;
  v_lifecycle_context text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.lifecycle_mutation_context', true), '')), '');
  v_effective_lifecycle_context text := NULL::text;
  v_lifecycle_dedupe_keys text := '';
  v_lifecycle_dedupe_token text := '';
  v_explicit_banking_pay_action boolean := false;
  v_banking_pay_dirty_required boolean := false;
  v_ordinary_timesheet_edit_save_no_dirty boolean := false;
  v_entity_kind_old text := '';
  v_entity_kind_new text := '';
  v_umbrella_id_old uuid := NULL::uuid;
  v_umbrella_id_new uuid := NULL::uuid;
  v_scope_id text;
  v_reason text;
  v_payload_json jsonb := '{}'::jsonb;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_jobs_queued integer := 0;
  v_candidate_route_change boolean := false;
  v_route_source_method text := NULL::text;
  v_route_target_method text := NULL::text;
  v_route_operation_id text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_operation_id', true), '')), '');
  v_route_actor_user_id text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_actor_user_id', true), '')), '');
  v_route_reason text := NULLIF(BTRIM(COALESCE(current_setting('cloudtms.candidate_pay_method_change_reason', true), '')), '');
  v_route_scope_result jsonb := '{}'::jsonb;
  v_route_authoritative_sessions jsonb := '[]'::jsonb;
  v_route_replaced_source_session_ids jsonb := '[]'::jsonb;
  v_route_target_details jsonb := '[]'::jsonb;
  v_route_authorised_timesheet_ids jsonb := '[]'::jsonb;
  v_route_active_advance_timesheet_ids jsonb := '[]'::jsonb;
  v_route_retained_finance_timesheet_ids jsonb := '[]'::jsonb;
  v_route_authorised_timesheet_count integer := 0;
  v_route_active_advance_timesheet_count integer := 0;
  v_route_retained_finance_timesheet_count integer := 0;
  v_route_source_target_mismatch_count integer := 0;
  v_route_exact_scope boolean := false;
  v_route_coverage_complete boolean := false;
  v_route_targeted_scope_is_empty boolean := false;
  v_route_job_id uuid := NULL::uuid;
  v_route_job_status text := NULL::text;
  v_route_job_source_change_seq bigint := 0;
  v_route_dedupe_key text := NULL::text;
  v_internal_build_token uuid := NULL::uuid;
  v_internal_candidate_id uuid := NULL::uuid;
  v_internal_source_id uuid := NULL::uuid;
  v_internal_timesheet_id uuid := NULL::uuid;
  v_internal_logical_source_id uuid := NULL::uuid;
  v_internal_before_digest text := NULL::text;
  v_internal_after_digest text := NULL::text;
  v_expected_match_count integer := 0;
  v_delete_owner_candidate_id uuid := NULL::uuid;
  v_delete_context regclass := pg_catalog.to_regclass('pg_temp._bpay_candidate_delete_context_v1');
  v_delete_context_suppressed boolean := false;
  v_effect_capture_mode boolean := lower(COALESCE(current_setting('cloudtms.pay_workbench_effect_capture_mode',true),''))='capture';
BEGIN
  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    NULL::text,
    jsonb_build_object(
      'function_name', 'pay_workbench_mark_candidate_dirty',
      'stage', 'entry',
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'mutation_context', v_lifecycle_context,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  IF TG_OP <> 'DELETE' THEN
    v_new_row := to_jsonb(NEW);
  END IF;
  IF TG_OP <> 'INSERT' THEN
    v_old_row := to_jsonb(OLD);
  END IF;


  IF TG_OP='DELETE' AND v_delete_context IS NOT NULL THEN
    IF v_trigger_table='candidates' AND NULLIF(v_old_row->>'id','')~*v_uuid_re THEN
      v_delete_owner_candidate_id:=(v_old_row->>'id')::uuid;
    ELSIF NULLIF(v_old_row->>'candidate_id','')~*v_uuid_re THEN
      v_delete_owner_candidate_id:=(v_old_row->>'candidate_id')::uuid;
    ELSIF NULLIF(COALESCE(v_old_row->>'timesheet_id',v_old_row->>'linked_timesheet_id'),'')~*v_uuid_re THEN
      SELECT COALESCE(financial.candidate_id,contract_row.candidate_id)
      INTO v_delete_owner_candidate_id
      FROM (SELECT COALESCE(NULLIF(v_old_row->>'timesheet_id','')::uuid,
             NULLIF(v_old_row->>'linked_timesheet_id','')::uuid) AS timesheet_id) owner_key
      LEFT JOIN public.timesheets_financials financial
        ON financial.timesheet_id=owner_key.timesheet_id AND financial.is_current
      LEFT JOIN public.timesheets timesheet_row ON timesheet_row.timesheet_id=owner_key.timesheet_id
      LEFT JOIN public.contracts contract_row ON contract_row.id=timesheet_row.contract_id
      LIMIT 1;
    ELSIF NULLIF(v_old_row->>'contract_id','')~*v_uuid_re THEN
      SELECT contract_row.candidate_id INTO v_delete_owner_candidate_id
      FROM public.contracts contract_row WHERE contract_row.id=(v_old_row->>'contract_id')::uuid;
    ELSIF NULLIF(v_old_row->>'finance_case_id','')~*v_uuid_re THEN
      SELECT finance_case.candidate_id INTO v_delete_owner_candidate_id
      FROM public.pay_advances finance_case WHERE finance_case.id=(v_old_row->>'finance_case_id')::uuid;
    ELSIF NULLIF(v_old_row->>'finance_component_id','')~*v_uuid_re THEN
      SELECT component.candidate_id INTO v_delete_owner_candidate_id
      FROM public.pay_finance_case_components component
      WHERE component.id=(v_old_row->>'finance_component_id')::uuid;
    END IF;
  END IF;

  IF TG_OP='DELETE' AND v_delete_context IS NOT NULL
     AND v_delete_owner_candidate_id IS NOT NULL THEN
    IF EXISTS(
         SELECT 1 FROM pg_catalog.pg_class relation
         WHERE relation.oid=v_delete_context
           AND relation.relowner=current_user::regrole::oid AND relation.relpersistence='t'
           AND relation.relnamespace=pg_catalog.pg_my_temp_schema()
       )
       AND (SELECT array_agg(attribute.attname||':'||pg_catalog.format_type(attribute.atttypid,attribute.atttypmod)
              ORDER BY attribute.attnum)
            FROM pg_catalog.pg_attribute attribute
            WHERE attribute.attrelid=v_delete_context
              AND attribute.attnum>0 AND NOT attribute.attisdropped)
         =ARRAY['candidate_id:uuid','delete_operation_id:uuid','candidate_lock_key:bigint',
           'backend_pid:integer','transaction_id:bigint','created_at_utc:timestamp with time zone',
           'suppress:boolean'] THEN
      -- The delete context is optional.  Keep its only row read behind dynamic
      -- SQL so an ordinary finance DELETE cannot fail during statement planning
      -- merely because candidate deletion did not create the temporary table.
      EXECUTE $delete_context$
        SELECT EXISTS(
          SELECT 1
          FROM pg_temp._bpay_candidate_delete_context_v1 context
          WHERE context.candidate_id=$1 AND context.suppress
            AND context.candidate_lock_key=pg_catalog.hashtextextended(
              public._pay_workbench_candidate_serial_key(context.candidate_id),24062027)
            AND context.backend_pid=pg_catalog.pg_backend_pid()
            AND context.transaction_id=pg_catalog.txid_current()
            AND (SELECT count(*) FROM pg_temp._bpay_candidate_delete_context_v1)=1
        )
      $delete_context$ INTO v_delete_context_suppressed USING v_delete_owner_candidate_id;
    END IF;
    IF v_delete_context_suppressed THEN
      RETURN OLD;
    END IF;
  END IF;

  -- The retained pay_advances dirty trigger is recreated as BEFORE ROW.  It
  -- declares the exact full transition before the row mutation and suppresses
  -- only an owner-controlled effect inside the current sealed build scope.
  IF v_trigger_table='pay_advances'
     AND to_regclass('pg_temp._bpay_wb_sync_context_v1') IS NOT NULL
     AND to_regclass('pg_temp._bpay_wb_expected_effects') IS NOT NULL
     AND COALESCE(current_setting('cloudtms.pay_workbench_overpayment_sync_token',true),'')
       ~* v_uuid_re THEN
    v_internal_build_token:=current_setting(
      'cloudtms.pay_workbench_overpayment_sync_token',true)::uuid;
    SELECT build_row.candidate_id INTO v_internal_candidate_id
    FROM pg_temp._bpay_wb_sync_context_v1 sync_context
       JOIN private.banking_pay_workbench_economic_builds build_row
         ON build_row.id=sync_context.build_id AND build_row.build_token=sync_context.build_token
       JOIN private.banking_pay_workbench_stage_attempts attempt
         ON attempt.id=sync_context.attempt_id AND attempt.attempt_nonce=sync_context.attempt_nonce
        AND attempt.build_id=build_row.id AND attempt.attempt_status='STARTED'
    WHERE build_row.status='RECONCILING' AND build_row.private_stage='RECONCILE_EXECUTE'
      AND build_row.build_token=v_internal_build_token;
    IF v_internal_candidate_id IS NOT NULL THEN
      IF TG_WHEN<>'BEFORE' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CONFLICT' USING ERRCODE='23514';
      END IF;
      v_internal_source_id:=COALESCE(NULLIF(v_new_row->>'id','')::uuid,
        NULLIF(v_old_row->>'id','')::uuid);
      v_internal_timesheet_id:=COALESCE(NULLIF(v_new_row->>'linked_timesheet_id','')::uuid,
        NULLIF(v_old_row->>'linked_timesheet_id','')::uuid);
      v_internal_before_digest:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE md5(
        private.pay_workbench_finance_effect_normalise_row_v1(
          v_trigger_table,TG_OP,v_old_row,v_old_row)::text) END;
      v_internal_after_digest:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE md5(
        private.pay_workbench_finance_effect_normalise_row_v1(
          v_trigger_table,TG_OP,v_new_row,v_old_row)::text) END;
      IF v_internal_source_id IS NULL
         OR COALESCE(NULLIF(v_new_row->>'candidate_id','')::uuid,
              NULLIF(v_old_row->>'candidate_id','')::uuid)
            IS DISTINCT FROM v_internal_candidate_id
         OR (v_internal_timesheet_id IS NOT NULL AND NOT EXISTS(
           SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
           JOIN pg_temp._bpay_wb_sync_context_v1 sync_context
             ON sync_context.build_id=scope_row.build_id
           WHERE scope_row.timesheet_id=v_internal_timesheet_id
         )) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
      END IF;
      IF v_effect_capture_mode THEN
        INSERT INTO pg_temp._bpay_wb_expected_effects(
          build_token,candidate_id,timesheet_id,relation_name,operation,source_id,
          finance_case_id,finance_component_id,economic_key_type,economic_key_value,
          expected_before_digest,expected_after_digest,proposed,observed
        ) VALUES(
          v_internal_build_token,v_internal_candidate_id,v_internal_timesheet_id,
          v_trigger_table,TG_OP,v_internal_source_id,v_internal_source_id,NULL,NULL,NULL,
          v_internal_before_digest,v_internal_after_digest,true,false
        );
      ELSIF TG_OP='INSERT' THEN
        UPDATE pg_temp._bpay_wb_expected_effects expected
        SET actual_source_id=v_internal_source_id,proposed=true
        WHERE expected.ctid=(SELECT candidate.ctid
          FROM pg_temp._bpay_wb_expected_effects candidate
          WHERE candidate.build_token=v_internal_build_token
            AND candidate.candidate_id=v_internal_candidate_id
            AND candidate.timesheet_id IS NOT DISTINCT FROM v_internal_timesheet_id
            AND candidate.relation_name=v_trigger_table AND candidate.operation=TG_OP
            AND candidate.proposed IS NOT TRUE AND candidate.observed IS NOT TRUE
            AND candidate.expected_before_digest IS NULL
            AND candidate.expected_after_digest IS NOT DISTINCT FROM v_internal_after_digest
          ORDER BY candidate.source_id LIMIT 1)
        RETURNING expected.source_id INTO v_internal_logical_source_id;
        GET DIAGNOSTICS v_expected_match_count=ROW_COUNT;
        IF v_expected_match_count<>1 OR v_internal_logical_source_id IS NULL THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
        END IF;
        INSERT INTO pg_temp._bpay_wb_effect_identity_map_v1(
          relation_name,logical_source_id,actual_source_id)
        VALUES(v_trigger_table,v_internal_logical_source_id,v_internal_source_id);
      ELSE
        UPDATE pg_temp._bpay_wb_expected_effects expected SET proposed=true
        WHERE expected.build_token=v_internal_build_token
          AND expected.candidate_id=v_internal_candidate_id
          AND expected.timesheet_id IS NOT DISTINCT FROM v_internal_timesheet_id
          AND expected.relation_name=v_trigger_table AND expected.operation=TG_OP
          AND expected.source_id=v_internal_source_id
          AND expected.proposed IS NOT TRUE AND expected.observed IS NOT TRUE
          AND expected.expected_before_digest IS NOT DISTINCT FROM v_internal_before_digest
          AND expected.expected_after_digest IS NOT DISTINCT FROM v_internal_after_digest;
        GET DIAGNOSTICS v_expected_match_count=ROW_COUNT;
        IF v_expected_match_count<>1 THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
        END IF;
      END IF;
      IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;
  END IF;

  -- Natural-expiry fields are derived scheduler metadata.  An update confined
  -- to this allowlist must not create another generation or candidate build.
  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'pay_item_snoozes'
     AND (
       v_new_row - ARRAY[
         'natural_expiry_source_fingerprint',
         'natural_expiry_checked_fingerprint',
         'natural_expiry_checked_at_utc',
         'natural_expiry_state_changed',
         'natural_expiry_result_code'
       ]::text[]
     ) IS NOT DISTINCT FROM (
       v_old_row - ARRAY[
         'natural_expiry_source_fingerprint',
         'natural_expiry_checked_fingerprint',
         'natural_expiry_checked_at_utc',
         'natural_expiry_state_changed',
         'natural_expiry_result_code'
       ]::text[]
     ) THEN
    RETURN NEW;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re THEN
    v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid);
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re THEN
    v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid);
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', v_old_row->>'linked_timesheet_id', '')), '') ~* v_uuid_re THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', v_old_row->>'linked_timesheet_id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', v_new_row->>'linked_timesheet_id', '')), '') ~* v_uuid_re THEN
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', v_new_row->>'linked_timesheet_id', '')), '')::uuid;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '') ~* v_uuid_re THEN
    v_old_contract_id := NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '') ~* v_uuid_re THEN
    v_new_contract_id := NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '')::uuid;
  END IF;

  v_explicit_banking_pay_action := lower(BTRIM(COALESCE(current_setting('cloudtms.banking_pay_explicit_action', true), 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(current_setting('cloudtms.banking_pay_dirty_allowed', true), 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN (
      'timesheet_authorise',
      'timesheet_unauthorise',
      'timesheet_archive',
      'timesheet_unarchive',
      'authorise_timesheet',
      'unauthorise_timesheet',
      'archive_timesheet',
      'unarchive_timesheet',
      'banking_pay',
      'banking_pay_refresh',
      'banking_pay_dirty',
      'banking_pay_action',
      'banking_pay_recalculate',
      'banking_pay_decision',
      'banking_pay_case_resolution',
      'banking_pay_timesheet_advance',
      'banking_pay_patch'
    );

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('manual_timesheet_save', 'ordinary_timesheet_save', 'timesheet_manual_save', 'manual_save')
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', v_new_row->>'authorised_at_utc', '')), '') IS NULL
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', v_new_row->>'revoked_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_insert_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_server_present', false,
        'revoked_at_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_authorise_boundary_changed :=
      (
        NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      ) IS DISTINCT FROM (
        NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      );

    v_archive_boundary_changed :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL)
      IS DISTINCT FROM
      (NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL);

    v_material_live_source_changed :=
      (v_old_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
      OR (v_old_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
      OR (v_old_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
      OR (v_old_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
      OR (v_old_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
      OR (v_old_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
      OR (v_old_row->'additional_units_week') IS DISTINCT FROM (v_new_row->'additional_units_week')
      OR (v_old_row->'additional_units_per_day') IS DISTINCT FROM (v_new_row->'additional_units_per_day')
      OR (v_old_row->'week_ending_date') IS DISTINCT FROM (v_new_row->'week_ending_date')
      OR (v_old_row->'booking_id') IS DISTINCT FROM (v_new_row->'booking_id')
      OR (v_old_row->'line_type') IS DISTINCT FROM (v_new_row->'line_type')
      OR (v_old_row->'sheet_scope') IS DISTINCT FROM (v_new_row->'sheet_scope')
      OR (v_old_row->'reference_number') IS DISTINCT FROM (v_new_row->'reference_number')
      OR (v_old_row->'status') IS DISTINCT FROM (v_new_row->'status')
      OR (v_old_row->'submission_mode') IS DISTINCT FROM (v_new_row->'submission_mode')
      OR (v_old_row->'contract_id') IS DISTINCT FROM (v_new_row->'contract_id')
      OR (v_old_row->'is_adjustment') IS DISTINCT FROM (v_new_row->'is_adjustment')
      OR (v_old_row->'parent_timesheet_id') IS DISTINCT FROM (v_new_row->'parent_timesheet_id')
      OR (v_old_row->'correction_id') IS DISTINCT FROM (v_new_row->'correction_id')
      OR (v_old_row->'correction_kind') IS DISTINCT FROM (v_new_row->'correction_kind')
      OR (v_old_row->'adjustment_origin') IS DISTINCT FROM (v_new_row->'adjustment_origin');
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_authorise_boundary_changed :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL)
      IS DISTINCT FROM
      (NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL);

    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_material_live_source_changed :=
      (v_old_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
      OR (v_old_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
      OR (v_old_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
      OR (v_old_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
      OR (v_old_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
      OR (v_old_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
      OR (v_old_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
      OR (v_old_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
      OR (v_old_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
      OR (v_old_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
      OR (v_old_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
      OR (v_old_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
      OR (v_old_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
      OR (v_old_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
      OR (v_old_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
      OR (v_old_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
      OR (v_old_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
      OR (v_old_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
      OR (v_old_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
      OR (v_old_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
      OR (v_old_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
      OR (v_old_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
      OR (v_old_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
      OR (v_old_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
      OR (v_old_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
      OR (v_old_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
      OR (v_old_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
      OR (v_old_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
      OR (v_old_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
      OR (v_old_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
      OR (v_old_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
      OR (v_old_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
      OR (v_old_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
      OR (v_old_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
      OR (v_old_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
      OR (v_old_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
      OR (v_old_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
      OR (v_old_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
      OR (v_old_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
      OR (v_old_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
      OR (v_old_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
      OR (v_old_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
      OR (v_old_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
    ELSE
      -- Snapshot rotation demotes the previous row before inserting its
      -- replacement.  The demotion itself is bookkeeping, not a live-source
      -- economic change and must not mark a frozen Draft stale.
      v_material_live_source_changed := false;
    END IF;
  ELSIF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
    IF LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      SELECT COALESCE(to_jsonb(previous_financial_row), '{}'::jsonb)
      INTO v_previous_tsfin_row
      FROM public.timesheets_financials AS previous_financial_row
      WHERE previous_financial_row.timesheet_id = v_new_timesheet_id
        AND previous_financial_row.id IS DISTINCT FROM
          CASE
            WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re
              THEN NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
            ELSE NULL::uuid
          END
      ORDER BY
        previous_financial_row.timesheet_version DESC NULLS LAST,
        previous_financial_row.computed_at_utc DESC NULLS LAST,
        previous_financial_row.created_at DESC NULLS LAST,
        previous_financial_row.id DESC
      LIMIT 1;

      v_previous_tsfin_row := COALESCE(v_previous_tsfin_row, '{}'::jsonb);
      IF v_previous_tsfin_row = '{}'::jsonb THEN
        v_material_live_source_changed := true;
      ELSE
        v_material_live_source_changed :=
          (v_previous_tsfin_row->'pay_method') IS DISTINCT FROM (v_new_row->'pay_method')
          OR (v_previous_tsfin_row->'policy_snapshot_json') IS DISTINCT FROM (v_new_row->'policy_snapshot_json')
          OR (v_previous_tsfin_row->'rate_source_refs_json') IS DISTINCT FROM (v_new_row->'rate_source_refs_json')
          OR (v_previous_tsfin_row->'hours_day') IS DISTINCT FROM (v_new_row->'hours_day')
          OR (v_previous_tsfin_row->'hours_night') IS DISTINCT FROM (v_new_row->'hours_night')
          OR (v_previous_tsfin_row->'hours_sat') IS DISTINCT FROM (v_new_row->'hours_sat')
          OR (v_previous_tsfin_row->'hours_sun') IS DISTINCT FROM (v_new_row->'hours_sun')
          OR (v_previous_tsfin_row->'hours_bh') IS DISTINCT FROM (v_new_row->'hours_bh')
          OR (v_previous_tsfin_row->'pay_day') IS DISTINCT FROM (v_new_row->'pay_day')
          OR (v_previous_tsfin_row->'pay_night') IS DISTINCT FROM (v_new_row->'pay_night')
          OR (v_previous_tsfin_row->'pay_sat') IS DISTINCT FROM (v_new_row->'pay_sat')
          OR (v_previous_tsfin_row->'pay_sun') IS DISTINCT FROM (v_new_row->'pay_sun')
          OR (v_previous_tsfin_row->'pay_bh') IS DISTINCT FROM (v_new_row->'pay_bh')
          OR (v_previous_tsfin_row->'total_hours') IS DISTINCT FROM (v_new_row->'total_hours')
          OR (v_previous_tsfin_row->'total_pay_ex_vat') IS DISTINCT FROM (v_new_row->'total_pay_ex_vat')
          OR (v_previous_tsfin_row->'expenses_pay_ex_vat') IS DISTINCT FROM (v_new_row->'expenses_pay_ex_vat')
          OR (v_previous_tsfin_row->'travel_pay_ex_vat') IS DISTINCT FROM (v_new_row->'travel_pay_ex_vat')
          OR (v_previous_tsfin_row->'accommodation_pay_ex_vat') IS DISTINCT FROM (v_new_row->'accommodation_pay_ex_vat')
          OR (v_previous_tsfin_row->'other_pay_ex_vat') IS DISTINCT FROM (v_new_row->'other_pay_ex_vat')
          OR (v_previous_tsfin_row->'mileage_units') IS DISTINCT FROM (v_new_row->'mileage_units')
          OR (v_previous_tsfin_row->'mileage_pay_rate') IS DISTINCT FROM (v_new_row->'mileage_pay_rate')
          OR (v_previous_tsfin_row->'mileage_pay_ex_vat') IS DISTINCT FROM (v_new_row->'mileage_pay_ex_vat')
          OR (v_previous_tsfin_row->'additional_pay_ex_vat') IS DISTINCT FROM (v_new_row->'additional_pay_ex_vat')
          OR (v_previous_tsfin_row->'pay_wtr_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_wtr_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_rate_pct_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_rate_pct_snapshot')
          OR (v_previous_tsfin_row->'pay_vat_amount_snapshot') IS DISTINCT FROM (v_new_row->'pay_vat_amount_snapshot')
          OR (v_previous_tsfin_row->'pay_total_inc_vat_snapshot') IS DISTINCT FROM (v_new_row->'pay_total_inc_vat_snapshot')
          OR (v_previous_tsfin_row->'invoice_breakdown_json') IS DISTINCT FROM (v_new_row->'invoice_breakdown_json')
          OR (v_previous_tsfin_row->'additional_units_json') IS DISTINCT FROM (v_new_row->'additional_units_json')
          OR (v_previous_tsfin_row->'actual_schedule_json') IS DISTINCT FROM (v_new_row->'actual_schedule_json')
          OR (v_previous_tsfin_row->'worked_start_iso') IS DISTINCT FROM (v_new_row->'worked_start_iso')
          OR (v_previous_tsfin_row->'worked_end_iso') IS DISTINCT FROM (v_new_row->'worked_end_iso')
          OR (v_previous_tsfin_row->'break_start_iso') IS DISTINCT FROM (v_new_row->'break_start_iso')
          OR (v_previous_tsfin_row->'break_end_iso') IS DISTINCT FROM (v_new_row->'break_end_iso')
          OR (v_previous_tsfin_row->'break_minutes') IS DISTINCT FROM (v_new_row->'break_minutes')
          OR (v_previous_tsfin_row->'pay_on_hold') IS DISTINCT FROM (v_new_row->'pay_on_hold')
          OR (v_previous_tsfin_row->'pay_on_hold_reason') IS DISTINCT FROM (v_new_row->'pay_on_hold_reason')
          OR (v_previous_tsfin_row->'has_rate_issue') IS DISTINCT FROM (v_new_row->'has_rate_issue')
          OR (v_previous_tsfin_row->'has_pay_channel_issue') IS DISTINCT FROM (v_new_row->'has_pay_channel_issue')
          OR (v_previous_tsfin_row->'processing_status') IS DISTINCT FROM (v_new_row->'processing_status')
          OR (v_previous_tsfin_row->'locked_by_invoice_id') IS DISTINCT FROM (v_new_row->'locked_by_invoice_id')
          OR (v_previous_tsfin_row->'unlocked_by_credit_note_id') IS DISTINCT FROM (v_new_row->'unlocked_by_credit_note_id')
          OR (v_previous_tsfin_row->'candidate_id') IS DISTINCT FROM (v_new_row->'candidate_id')
          OR (v_previous_tsfin_row->'client_id') IS DISTINCT FROM (v_new_row->'client_id');
      END IF;
    END IF;
  END IF;

  IF (
       (TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets')
       OR (TG_OP IN ('INSERT', 'UPDATE') AND v_trigger_table = 'timesheets_financials')
     )
     AND (v_material_live_source_changed IS TRUE OR v_authorise_boundary_changed IS TRUE OR v_archive_boundary_changed IS TRUE) THEN
    SELECT COALESCE(array_agg(DISTINCT rotation_scope.family_timesheet_id ORDER BY rotation_scope.family_timesheet_id), ARRAY[]::uuid[])
    INTO v_signal_timesheet_ids
    FROM public._pay_timesheet_rotation_scope(
      ARRAY[COALESCE(v_new_timesheet_id, v_old_timesheet_id)]::uuid[]
    ) AS rotation_scope
    WHERE rotation_scope.family_timesheet_id IS NOT NULL;

    IF COALESCE(array_length(v_signal_timesheet_ids, 1), 0) = 0
       AND COALESCE(v_new_timesheet_id, v_old_timesheet_id) IS NOT NULL THEN
      v_signal_timesheet_ids := ARRAY[COALESCE(v_new_timesheet_id, v_old_timesheet_id)]::uuid[];
    END IF;

    SELECT COALESCE(array_agg(DISTINCT candidate_scope.candidate_id ORDER BY candidate_scope.candidate_id), ARRAY[]::uuid[])
    INTO v_signal_candidate_ids
    FROM (
      SELECT CASE
        WHEN NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re
          THEN NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS candidate_id
      UNION ALL
      SELECT CASE
        WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re
          THEN NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid
        ELSE NULL::uuid
      END
      UNION ALL
      SELECT financial_row.candidate_id
      FROM public.timesheets_financials AS financial_row
      WHERE financial_row.timesheet_id = ANY(COALESCE(v_signal_timesheet_ids, ARRAY[]::uuid[]))
      UNION ALL
      SELECT contract_row.candidate_id
      FROM public.timesheets AS timesheet_row
      JOIN public.contracts AS contract_row
        ON contract_row.id = timesheet_row.contract_id
      WHERE timesheet_row.timesheet_id = ANY(COALESCE(v_signal_timesheet_ids, ARRAY[]::uuid[]))
    ) AS candidate_scope
    WHERE candidate_scope.candidate_id IS NOT NULL;

    v_signal_reason := CASE
      WHEN v_archive_boundary_changed IS TRUE
           AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL
        THEN 'TIMESHEET_ARCHIVED_LIVE_SOURCE_CHANGED'
      WHEN v_archive_boundary_changed IS TRUE
        THEN 'TIMESHEET_UNARCHIVED_LIVE_SOURCE_CHANGED'
      WHEN v_authorise_boundary_changed IS TRUE
           AND (
             NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', v_new_row->>'authorised_at_utc', '')), '') IS NULL
             OR NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NOT NULL
           )
        THEN 'TIMESHEET_UNAUTHORISED_LIVE_SOURCE_CHANGED'
      WHEN v_authorise_boundary_changed IS TRUE
        THEN 'TIMESHEET_AUTHORISED_LIVE_SOURCE_CHANGED'
      ELSE 'TIMESHEET_MATERIAL_LIVE_SOURCE_CHANGED'
    END;

    FOR v_signal_batch_row IN
      SELECT DISTINCT pay_batch.id AS pay_batch_id
      FROM public.pay_batches AS pay_batch
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id = pay_batch.id
       AND batch_candidate.candidate_id = ANY(COALESCE(v_signal_candidate_ids, ARRAY[]::uuid[]))
      WHERE UPPER(BTRIM(COALESCE(pay_batch.status, ''))) = 'DRAFT'
        AND EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS batch_item
          LEFT JOIN public.pay_advances AS finance_case
            ON finance_case.id = batch_item.finance_case_id
          WHERE batch_item.pay_batch_candidate_id = batch_candidate.id
            AND batch_item.is_voided IS NOT TRUE
            AND (
              batch_item.timesheet_id = ANY(COALESCE(v_signal_timesheet_ids, ARRAY[]::uuid[]))
              OR finance_case.linked_timesheet_id = ANY(COALESCE(v_signal_timesheet_ids, ARRAY[]::uuid[]))
            )
        )
      ORDER BY pay_batch.id
    LOOP
      BEGIN
        v_signal_result := public.banking_pay_batch_signal_touch(
          p_pay_batch_id => v_signal_batch_row.pay_batch_id,
          p_change_reason => v_signal_reason,
          p_change_source => 'pay_workbench_mark_candidate_dirty',
          p_change_scope_json => jsonb_build_object(
            'stale_hint', true,
            'stale_reason', v_signal_reason,
            'candidate_ids', COALESCE(to_jsonb(v_signal_candidate_ids), '[]'::jsonb),
            'timesheet_ids', COALESCE(to_jsonb(v_signal_timesheet_ids), '[]'::jsonb),
            'trigger_table', v_trigger_table,
            'trigger_operation', TG_OP,
            'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
          ),
          p_touch_payment_status => false,
          p_touch_correction_progress => false,
          p_touch_alerts => true,
          p_touch_overview => true
        );
      EXCEPTION
        WHEN OTHERS THEN
          v_signal_result := jsonb_build_object(
            'ok', false,
            'error_code', SQLSTATE,
            'error_message', SQLERRM,
            'pay_batch_id', v_signal_batch_row.pay_batch_id::text
          );
          PERFORM public._temp_diag_log(
            'TEMP_TRIGGER_DIRTY_STAGE',
            'TEMP_BANKING_PAY_DIRTY',
            COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
            jsonb_build_object(
              'function_name', 'pay_workbench_mark_candidate_dirty',
              'stage', 'lightweight_draft_stale_signal_failed_non_blocking',
              'pay_batch_id', v_signal_batch_row.pay_batch_id::text,
              'signal_reason', v_signal_reason,
              'error_code', SQLSTATE,
              'error_message', SQLERRM,
              'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
            )
          );
      END;
    END LOOP;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    IF v_authorise_boundary_changed IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE
       AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    IF v_authorise_boundary_changed IS NOT TRUE AND v_explicit_banking_pay_action IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_timesheet_financials_edit_save_no_dirty', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'material_live_source_changed', v_material_live_source_changed, 'draft_stale_signal_only', v_material_live_source_changed, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  END IF;

  IF TG_OP = 'INSERT'
     AND v_trigger_table = 'timesheets_financials'
     AND v_explicit_banking_pay_action IS NOT TRUE
     AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN
    PERFORM public._temp_diag_log(
      'TEMP_TRIGGER_DIRTY_STAGE',
      'TEMP_BANKING_PAY_DIRTY',
      COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
      jsonb_build_object(
        'function_name', 'pay_workbench_mark_candidate_dirty',
        'stage', 'early_return_ordinary_timesheet_financials_insert_edit_save_no_dirty',
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'mutation_context', v_lifecycle_context,
        'authorised_at_utc_present', false,
        'explicit_banking_pay_action', false,
        'banking_pay_dirty_required', false,
        'source_build_required', false,
        'line_work_required', false,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
      )
    );
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheet_pay_state' THEN
    v_timesheet_pay_state_settlement_changed :=
      (v_old_row->'last_settled_snapshot_json') IS DISTINCT FROM (v_new_row->'last_settled_snapshot_json')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_signature', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_signature', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_pay_batch_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_pay_batch_id', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_at_utc', '')), '');

    v_timesheet_pay_state_summary_changed :=
      NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_status_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_status_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_icon_code', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_icon_code', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_pay_paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_pay_paid_at_utc', '')), '')
      OR NULLIF(BTRIM(COALESCE(v_old_row->>'summary_net_delta_ex_vat', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'summary_net_delta_ex_vat', '')), '');

    IF v_timesheet_pay_state_settlement_changed IS NOT TRUE THEN
      v_timesheet_pay_state_bookkeeping_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false);
      v_timesheet_pay_state_noop_ignored := COALESCE(v_timesheet_pay_state_summary_changed, false) IS NOT TRUE;

      PERFORM public._temp_diag_log(
        'TEMP_TRIGGER_DIRTY_STAGE',
        'TEMP_BANKING_PAY_DIRTY',
        COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text),
        jsonb_build_object(
          'function_name', 'pay_workbench_mark_candidate_dirty',
          'stage', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'early_return_timesheet_pay_state_bookkeeping_no_dirty'
            ELSE 'early_return_timesheet_pay_state_noop_no_dirty'
          END,
          'trigger_table', v_trigger_table,
          'trigger_op', TG_OP,
          'dirty_classification', CASE
            WHEN v_timesheet_pay_state_bookkeeping_ignored IS TRUE THEN 'TIMESHEET_PAY_STATE_BOOKKEEPING_IGNORED'
            ELSE 'TIMESHEET_PAY_STATE_NOOP_IGNORED'
          END,
          'timesheet_pay_state_settlement_changed', COALESCE(v_timesheet_pay_state_settlement_changed, false),
          'timesheet_pay_state_summary_changed', COALESCE(v_timesheet_pay_state_summary_changed, false),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
        )
      );
      RETURN NEW;
    END IF;

    v_timesheet_pay_state_routing_reason := 'SOURCE_BUILD_REQUIRED_PAY_STATE_SETTLED_BASELINE_CHANGE';
  END IF;

  IF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL
      AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL;
    IF v_old_payment_eligible IS NOT TRUE
       AND v_new_payment_eligible IS NOT TRUE
       AND v_archive_boundary_changed IS NOT TRUE THEN
      PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
      RETURN NEW;
    END IF;
  ELSIF TG_OP = 'UPDATE' AND v_trigger_table = 'timesheets_financials' THEN
    v_old_payment_eligible := NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    v_new_payment_eligible := NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL;
    IF v_old_payment_eligible IS NOT TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_tsfin_payability_state_changed :=
        NULLIF(BTRIM(COALESCE(v_old_row->>'paid_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'paid_by_user_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'paid_by_user_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'payment_reference', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'payment_reference', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_reason', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_reason', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'pay_on_hold_since_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'pay_on_hold_since_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_by_invoice_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_by_invoice_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'locked_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'locked_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'unlocked_by_credit_note_id', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'unlocked_by_credit_note_id', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_last_sent_at_utc', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_last_sent_at_utc', '')), '')
        OR NULLIF(BTRIM(COALESCE(v_old_row->>'remittance_send_count', '')), '') IS DISTINCT FROM NULLIF(BTRIM(COALESCE(v_new_row->>'remittance_send_count', '')), '');
      IF v_tsfin_payability_state_changed IS NOT TRUE THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'early_return_ordinary_unauthorised_edit', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'payability_state_changed', false, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        RETURN NEW;
      END IF;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table IN ('timesheets', 'timesheets_financials')
     AND v_authorise_boundary_changed IS TRUE THEN
    IF v_new_payment_eligible IS TRUE AND v_old_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF v_old_payment_eligible IS TRUE AND v_new_payment_eligible IS NOT TRUE THEN
      v_authorise_boundary_is_unauthorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN
      v_authorise_boundary_is_authorise := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN
      v_authorise_boundary_is_unauthorise := true;
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND v_trigger_table = 'timesheets'
     AND v_archive_boundary_changed IS TRUE THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NOT NULL THEN
      v_archive_boundary_is_archive := true;
    ELSIF NULLIF(BTRIM(COALESCE(v_old_row->>'archived_at_utc', '')), '') IS NOT NULL
       AND NULLIF(BTRIM(COALESCE(v_new_row->>'archived_at_utc', '')), '') IS NULL THEN
      v_archive_boundary_is_unarchive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN
      v_archive_boundary_is_archive := true;
    ELSIF lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN
      v_archive_boundary_is_unarchive := true;
    END IF;
  END IF;

  v_effective_lifecycle_context := CASE
    WHEN v_archive_boundary_is_archive IS TRUE THEN 'timesheet_archive'
    WHEN v_archive_boundary_is_unarchive IS TRUE THEN 'timesheet_unarchive'
    WHEN v_authorise_boundary_is_unauthorise IS TRUE THEN 'timesheet_unauthorise'
    WHEN v_authorise_boundary_is_authorise IS TRUE THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_authorise', 'authorise_timesheet') THEN 'timesheet_authorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unauthorise', 'unauthorise_timesheet') THEN 'timesheet_unauthorise'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_archive', 'archive_timesheet') THEN 'timesheet_archive'
    WHEN lower(BTRIM(COALESCE(v_lifecycle_context, ''))) IN ('timesheet_unarchive', 'unarchive_timesheet') THEN 'timesheet_unarchive'
    ELSE v_lifecycle_context
  END;

  v_banking_pay_dirty_required := v_authorise_boundary_changed IS TRUE
    OR v_archive_boundary_changed IS TRUE
    OR v_explicit_banking_pay_action IS TRUE
    OR (v_trigger_table = 'timesheet_pay_state' AND v_timesheet_pay_state_settlement_changed IS TRUE);
  v_ordinary_timesheet_edit_save_no_dirty := TG_OP = 'UPDATE'
    AND v_trigger_table IN ('timesheets', 'timesheets_financials')
    AND v_banking_pay_dirty_required IS NOT TRUE;

  IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL THEN
    v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    SELECT COALESCE(array_agg(DISTINCT timesheet_ids.timesheet_id ORDER BY timesheet_ids.timesheet_id), ARRAY[]::uuid[])
    INTO v_targeted_timesheet_ids
    FROM (
      SELECT v_old_timesheet_id AS timesheet_id
      UNION ALL
      SELECT v_new_timesheet_id AS timesheet_id
    ) AS timesheet_ids
    WHERE timesheet_ids.timesheet_id IS NOT NULL;
  END IF;

  IF v_trigger_table = 'candidates' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid);
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid);
    END IF;

    IF TG_OP = 'UPDATE' THEN
      v_route_source_method := UPPER(BTRIM(COALESCE(v_old_row->>'pay_method', '')));
      v_route_target_method := UPPER(BTRIM(COALESCE(v_new_row->>'pay_method', '')));
      v_candidate_route_change := v_route_source_method IN ('PAYE', 'UMBRELLA')
        AND v_route_target_method IN ('PAYE', 'UMBRELLA')
        AND v_route_source_method <> v_route_target_method;

      IF v_candidate_route_change IS TRUE THEN
        IF v_route_operation_id IS NULL OR v_route_operation_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_OPERATION_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;
        IF v_route_actor_user_id IS NULL OR v_route_actor_user_id !~* v_uuid_re THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_ACTOR_CONTEXT_REQUIRED'
            USING ERRCODE = '22023';
        END IF;

        v_route_scope_result := public.candidate_pay_method_change_refresh_scope_v1(
          NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid,
          v_route_source_method,
          v_route_target_method
        );

        v_route_exact_scope := LOWER(BTRIM(COALESCE(v_route_scope_result->>'exact_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
        v_route_coverage_complete := LOWER(BTRIM(COALESCE(v_route_scope_result->>'coverage_complete', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

        IF COALESCE(v_route_scope_result->>'ok', 'false') <> 'true'
           OR v_route_exact_scope IS NOT TRUE
           OR v_route_coverage_complete IS NOT TRUE
           OR jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_EXACT_SCOPE_UNAVAILABLE'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        IF EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(v_route_scope_result->'targeted_timesheet_ids') AS raw_target(value)
          WHERE raw_target.value !~* v_uuid_re
        ) THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_TARGET_SCOPE_INVALID'
            USING ERRCODE = 'P0001';
        END IF;

        SELECT COALESCE(array_agg(DISTINCT target_value::uuid ORDER BY target_value::uuid), ARRAY[]::uuid[])
        INTO v_targeted_timesheet_ids
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(v_route_scope_result->'targeted_timesheet_ids') = 'array'
              THEN v_route_scope_result->'targeted_timesheet_ids'
            ELSE '[]'::jsonb
          END
        ) AS target_values(target_value)
        WHERE target_value ~* v_uuid_re;

        v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
        v_route_targeted_scope_is_empty := COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 0;
        v_route_authoritative_sessions := COALESCE(v_route_scope_result->'authoritative_sessions', '[]'::jsonb);
        v_route_replaced_source_session_ids := COALESCE(v_route_scope_result->'replaced_source_session_ids', '[]'::jsonb);
        v_route_target_details := COALESCE(v_route_scope_result->'target_details', '[]'::jsonb);
        v_route_authorised_timesheet_ids := COALESCE(v_route_scope_result->'authorised_timesheet_ids', '[]'::jsonb);
        v_route_active_advance_timesheet_ids := COALESCE(v_route_scope_result->'active_advance_timesheet_ids', '[]'::jsonb);
        v_route_retained_finance_timesheet_ids := COALESCE(v_route_scope_result->'retained_finance_timesheet_ids', '[]'::jsonb);
        v_route_authorised_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'authorised_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'authorised_timesheet_count')::integer END,
          0
        );
        v_route_active_advance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'active_advance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'active_advance_timesheet_count')::integer END,
          0
        );
        v_route_retained_finance_timesheet_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'retained_finance_timesheet_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'retained_finance_timesheet_count')::integer END,
          0
        );
        v_route_source_target_mismatch_count := COALESCE(
          CASE WHEN COALESCE(v_route_scope_result->>'source_target_mismatch_count', '') ~ '^[0-9]{1,10}$'
            THEN (v_route_scope_result->>'source_target_mismatch_count')::integer END,
          0
        );

        IF COALESCE(v_route_scope_result->>'durable_job_id', '') !~* v_uuid_re
           OR LOWER(BTRIM(COALESCE(v_route_scope_result->>'durable_scope_persisted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_MISSING'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        v_route_job_id := (v_route_scope_result->>'durable_job_id')::uuid;
        v_route_job_status := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_status', '')), '');
        v_route_dedupe_key := NULLIF(BTRIM(COALESCE(v_route_scope_result->>'durable_job_dedupe_key', '')), '');
        v_route_job_source_change_seq := COALESCE(
          CASE
            WHEN COALESCE(v_route_scope_result->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (v_route_scope_result->>'source_change_seq')::bigint
            ELSE 0
          END,
          0
        );

        IF v_route_job_status NOT IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
           OR v_route_dedupe_key IS NULL
           OR v_route_job_source_change_seq <= 0 THEN
          RAISE EXCEPTION 'CANDIDATE_PAY_METHOD_CHANGE_DURABLE_QUEUE_INVALID'
            USING ERRCODE = 'P0001', DETAIL = COALESCE(v_route_scope_result, '{}'::jsonb)::text;
        END IF;

        FOR v_signal_batch_row IN
          SELECT DISTINCT pay_batch.id AS pay_batch_id
          FROM public.pay_batches AS pay_batch
          JOIN public.pay_batch_candidates AS batch_candidate
            ON batch_candidate.pay_batch_id = pay_batch.id
           AND batch_candidate.candidate_id = NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
          WHERE UPPER(BTRIM(COALESCE(pay_batch.status, ''))) = 'DRAFT'
          ORDER BY pay_batch.id
        LOOP
          BEGIN
            v_signal_result := public.banking_pay_batch_signal_touch(
              p_pay_batch_id => v_signal_batch_row.pay_batch_id,
              p_change_reason => 'CANDIDATE_PAY_METHOD_CHANGED',
              p_change_source => 'pay_workbench_mark_candidate_dirty',
              p_change_scope_json => jsonb_build_object(
                'stale_hint', true,
                'stale_reason', 'CANDIDATE_PAY_METHOD_CHANGED',
                'candidate_ids', jsonb_build_array(NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')),
                'source_pay_method', v_route_source_method,
                'target_pay_method', v_route_target_method,
                'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
                'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
              ),
              p_touch_payment_status => false,
              p_touch_correction_progress => false,
              p_touch_alerts => true,
              p_touch_overview => true
            );
          EXCEPTION
            WHEN OTHERS THEN
              v_signal_result := jsonb_build_object(
                'ok', false,
                'error_code', SQLSTATE,
                'error_message', SQLERRM,
                'pay_batch_id', v_signal_batch_row.pay_batch_id::text
              );
              PERFORM public._temp_diag_log(
                'TEMP_TRIGGER_DIRTY_STAGE',
                'TEMP_BANKING_PAY_DIRTY',
                NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), ''),
                jsonb_build_object(
                  'function_name', 'pay_workbench_mark_candidate_dirty',
                  'stage', 'candidate_route_draft_stale_signal_failed_non_blocking',
                  'pay_batch_id', v_signal_batch_row.pay_batch_id::text,
                  'error_code', SQLSTATE,
                  'error_message', SQLERRM,
                  'policy_x_authority_scope', 'FROZEN_DRAFT_INVALIDATION_HINT_ONLY'
                )
              );
          END;
        END LOOP;

        v_explicit_banking_pay_action := true;
        v_banking_pay_dirty_required := true;
        v_ordinary_timesheet_edit_save_no_dirty := false;
        v_effective_lifecycle_context := 'candidate_pay_method_change';
      END IF;
    END IF;
  END IF;

  IF v_trigger_table IN ('bank_name_checks', 'bank_payee_map') THEN
    v_entity_kind_old := UPPER(BTRIM(COALESCE(v_old_row->>'entity_kind', '')));
    v_entity_kind_new := UPPER(BTRIM(COALESCE(v_new_row->>'entity_kind', '')));
    IF v_entity_kind_old = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_old IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid;
    END IF;
    IF v_entity_kind_new = 'CANDIDATE' AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_candidate_ids := array_append(v_candidate_ids, NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid);
    ELSIF v_entity_kind_new IN ('UMBRELLA', 'UMBRELLA_COMPANY') AND NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_trigger_table = 'umbrellas' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid;
    END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN
      v_umbrella_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid;
    END IF;
  END IF;

  IF v_umbrella_id_old IS NOT NULL OR v_umbrella_id_new IS NOT NULL THEN
    FOR v_scope_id IN
      SELECT DISTINCT umbrella_scope.umbrella_id::text
      FROM (
        SELECT v_umbrella_id_old AS umbrella_id
        UNION ALL
        SELECT v_umbrella_id_new AS umbrella_id
      ) AS umbrella_scope
      WHERE umbrella_scope.umbrella_id IS NOT NULL
    LOOP
      v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;
      v_payload_json := jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'trigger_operation', TG_OP,
        'scope_kind', 'UMBRELLA',
        'scope_id', v_scope_id,
        'reason', v_reason,
        'fallback_reason', 'UMBRELLA_BANK_DETAIL_DIRTY',
        'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
        'source_build_required', true,
        'line_work_required', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
      PERFORM public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'CONTRACT_CLIENT_DIRTY_FANOUT',
        p_scope_kind => 'UMBRELLA',
        p_scope_id => v_scope_id,
        p_candidate_id => NULL::uuid,
        p_targeted_timesheet_ids => ARRAY[]::uuid[],
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      );
    END LOOP;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT candidate_candidates.candidate_id ORDER BY candidate_candidates.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS candidate_id
    UNION ALL
    SELECT contract_old.candidate_id FROM public.contracts AS contract_old WHERE contract_old.id = v_old_contract_id
    UNION ALL
    SELECT contract_new.candidate_id FROM public.contracts AS contract_new WHERE contract_new.id = v_new_contract_id
    UNION ALL
    SELECT financial_old.candidate_id FROM public.timesheets_financials AS financial_old WHERE financial_old.timesheet_id = v_old_timesheet_id AND financial_old.is_current = true
    UNION ALL
    SELECT financial_new.candidate_id FROM public.timesheets_financials AS financial_new WHERE financial_new.timesheet_id = v_new_timesheet_id AND financial_new.is_current = true
    UNION ALL
    SELECT timesheet_contract_old.candidate_id
    FROM public.timesheets AS timesheet_old
    JOIN public.contracts AS timesheet_contract_old ON timesheet_contract_old.id = timesheet_old.contract_id
    WHERE timesheet_old.timesheet_id = v_old_timesheet_id
    UNION ALL
    SELECT timesheet_contract_new.candidate_id
    FROM public.timesheets AS timesheet_new
    JOIN public.contracts AS timesheet_contract_new ON timesheet_contract_new.id = timesheet_new.contract_id
    WHERE timesheet_new.timesheet_id = v_new_timesheet_id
  ) AS candidate_candidates
  WHERE candidate_candidates.candidate_id IS NOT NULL;

  IF COALESCE(array_length(v_candidate_ids, 1), 0) = 0 THEN
    PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', COALESCE(v_new_timesheet_id::text, v_old_timesheet_id::text), jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'return_no_candidate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_reason := CASE
    WHEN v_candidate_route_change IS TRUE
      THEN 'CANDIDATE_PAY_METHOD_CHANGE:' || v_route_source_method || '_TO_' || v_route_target_method
    ELSE 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP
  END;

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP

    IF TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN
      v_tsfin_insert_not_coalesced_reason := NULL::text;
      v_tsfin_insert_coalesced_job_id := NULL::uuid;
      v_tsfin_insert_coalesced_projection_run_id := NULL::uuid;
      v_tsfin_insert_coalesced_session_id := NULL::uuid;
      v_tsfin_insert_coalesced_source_change_seq := NULL::bigint;
      v_tsfin_insert_authorise_like := v_new_timesheet_id IS NOT NULL
        AND COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) = 1
        AND NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NOT NULL
        AND COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') NOT IN ('false', 'f', '0', 'no', 'n', 'off');

      IF v_tsfin_insert_authorise_like IS TRUE THEN
        SELECT
          existing_delta.id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'projection_run_id', '') ~* v_uuid_re
              THEN (existing_delta.payload_json->>'projection_run_id')::uuid
            ELSE NULL::uuid
          END,
          existing_delta.session_id,
          CASE
            WHEN COALESCE(existing_delta.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_seq')::bigint
            WHEN COALESCE(existing_delta.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$'
              THEN (existing_delta.payload_json->>'source_change_sequence')::bigint
            ELSE NULL::bigint
          END
        INTO
          v_tsfin_insert_coalesced_job_id,
          v_tsfin_insert_coalesced_projection_run_id,
          v_tsfin_insert_coalesced_session_id,
          v_tsfin_insert_coalesced_source_change_seq
        FROM public.banking_pay_workbench_jobs AS existing_delta
        JOIN public.banking_pay_workbench_sessions AS existing_session
          ON existing_session.id = existing_delta.session_id
         AND UPPER(BTRIM(COALESCE(existing_session.status, ''))) = 'OPEN'
         AND existing_session.discarded_at_utc IS NULL
        WHERE existing_delta.candidate_id = v_candidate_id
          AND existing_delta.created_at_utc >= (v_now - INTERVAL '10 minutes')
          AND UPPER(BTRIM(COALESCE(existing_delta.status, ''))) IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
          AND UPPER(BTRIM(COALESCE(existing_delta.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH')
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'projection_class', ''))) = 'NORMAL_TIMESHEET'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_table', ''))) = 'TIMESHEETS'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'trigger_operation', existing_delta.payload_json->>'trigger_op', ''))) = 'UPDATE'
          AND UPPER(BTRIM(COALESCE(existing_delta.payload_json->>'mutation_context', existing_delta.payload_json->>'lifecycle_mutation_context', ''))) IN ('TIMESHEET_AUTHORISE', 'AUTHORISE_TIMESHEET')
          AND LOWER(BTRIM(COALESCE(existing_delta.payload_json->>'authorise_boundary_changed', existing_delta.payload_json#>>'{complexity_flags,authorise_boundary_changed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(existing_delta.payload_json->'targeted_timesheet_ids') = 'array'
                  THEN existing_delta.payload_json->'targeted_timesheet_ids'
                ELSE '[]'::jsonb
              END
            ) AS targeted_timesheet_id(value)
            WHERE targeted_timesheet_id.value ~* v_uuid_re
              AND targeted_timesheet_id.value::uuid = v_new_timesheet_id
          )
        ORDER BY existing_delta.created_at_utc DESC, existing_delta.id DESC
        LIMIT 1;

        IF v_tsfin_insert_coalesced_job_id IS NOT NULL THEN
          PERFORM public._temp_diag_log(
            'TEMP_TRIGGER_DIRTY_STAGE',
            'TEMP_BANKING_PAY_DIRTY',
            v_new_timesheet_id::text,
            jsonb_build_object(
              'function_name', 'pay_workbench_mark_candidate_dirty',
              'stage', 'early_return_timesheet_financials_insert_authorise_coalesced_no_dirty',
              'trigger_table', v_trigger_table,
              'trigger_op', TG_OP,
              'coalesced_with_timesheets_authorise_delta', true,
              'coalesced_source_change_seq', v_tsfin_insert_coalesced_source_change_seq,
              'coalesced_job_id', v_tsfin_insert_coalesced_job_id::text,
              'coalesced_projection_run_id', CASE WHEN v_tsfin_insert_coalesced_projection_run_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_projection_run_id::text END,
              'coalesced_session_id', CASE WHEN v_tsfin_insert_coalesced_session_id IS NULL THEN NULL ELSE v_tsfin_insert_coalesced_session_id::text END,
              'coalesced_candidate_id', v_candidate_id::text,
              'coalesced_timesheet_id', v_new_timesheet_id::text,
              'banking_pay_dirty_required', false,
              'source_build_required', false,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
              'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
            )
          );
          CONTINUE;
        END IF;

        v_tsfin_insert_not_coalesced_reason := 'NO_PRIOR_AUTHORISE_DELTA';
      ELSE
        v_tsfin_insert_not_coalesced_reason := CASE
          WHEN v_new_timesheet_id IS NULL THEN 'NO_TARGET_TIMESHEET'
          WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) <> 1 THEN 'MULTI_OR_EMPTY_TARGET_SCOPE'
          WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_utc', '')), '') IS NULL THEN 'UNAUTHORISED_INSERT'
          WHEN COALESCE(LOWER(BTRIM(COALESCE(v_new_row->>'is_current', 'true'))), 'true') IN ('false', 'f', '0', 'no', 'n', 'off') THEN 'NON_CURRENT_INSERT'
          ELSE 'UNKNOWN_SAFE_STATE'
        END;
      END IF;
    END IF;

    IF v_effective_lifecycle_context IN ('timesheet_authorise', 'timesheet_unauthorise', 'timesheet_archive', 'timesheet_unarchive') THEN
      v_lifecycle_dedupe_token := '|LIFECYCLE_DIRTY:' || v_effective_lifecycle_context || ':' || v_candidate_id::text || ':' || COALESCE(array_to_string(v_targeted_timesheet_ids, ','), '') || '|';
      v_lifecycle_dedupe_keys := COALESCE(current_setting('cloudtms.pay_dirty_dedupe_keys', true), '');
      IF POSITION(v_lifecycle_dedupe_token IN v_lifecycle_dedupe_keys) > 0 THEN
        PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END, jsonb_build_object('function_name', 'pay_workbench_mark_candidate_dirty', 'stage', 'dedupe_skip_lifecycle_duplicate', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'mutation_context', v_lifecycle_context, 'candidate_id', v_candidate_id::text, 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));
        CONTINUE;
      END IF;
      PERFORM set_config('cloudtms.pay_dirty_dedupe_keys', LEFT(v_lifecycle_dedupe_keys || v_lifecycle_dedupe_token, 60000), true);
    END IF;

    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'trigger_operation', TG_OP,
      'mutation_context', v_effective_lifecycle_context,
      'lifecycle_mutation_context', v_effective_lifecycle_context,
      'authorise_boundary_changed', COALESCE(v_authorise_boundary_is_authorise, false),
      'unauthorise_boundary_changed', COALESCE(v_authorise_boundary_is_unauthorise, false),
      'archive_boundary_changed', COALESCE(v_archive_boundary_is_archive, false),
      'unarchive_boundary_changed', COALESCE(v_archive_boundary_is_unarchive, false),
      'explicit_banking_pay_action', COALESCE(v_explicit_banking_pay_action, false) OR COALESCE(v_authorise_boundary_changed, false) OR COALESCE(v_archive_boundary_changed, false),
      'banking_pay_dirty_required', COALESCE(v_banking_pay_dirty_required, false),
      'ordinary_timesheet_edit_save_no_dirty', COALESCE(v_ordinary_timesheet_edit_save_no_dirty, false),
      'timesheets_financials_insert_not_coalesced_reason', CASE WHEN v_trigger_table = 'timesheets_financials' AND TG_OP = 'INSERT' THEN v_tsfin_insert_not_coalesced_reason ELSE NULL END,
      'timesheets_financials_insert_coalesced_authorise_delta', false,
      'scope_kind', 'CANDIDATE',
      'scope_id', v_candidate_id::text,
      'candidate_id', v_candidate_id::text,
      'reason', v_reason,
      'dirty_reason', v_reason,
      'timesheet_pay_state_settlement_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_settlement_changed, false) ELSE NULL END,
      'timesheet_pay_state_summary_changed', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_summary_changed, false) ELSE NULL END,
      'timesheet_pay_state_bookkeeping_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_bookkeeping_ignored, false) ELSE NULL END,
      'timesheet_pay_state_noop_ignored', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN COALESCE(v_timesheet_pay_state_noop_ignored, false) ELSE NULL END,
      'pay_state_dirty_routing_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'source_build_required_reason', CASE WHEN v_trigger_table = 'timesheet_pay_state' THEN v_timesheet_pay_state_routing_reason ELSE NULL END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(to_jsonb(v_targeted_timesheet_ids), '[]'::jsonb),
      'linked_timesheet_ids', '[]'::jsonb,
      'linked_scope_recompute_required', true,
      'source_build_required', true,
      'line_work_required', true,
      'line_work_only', false,
      'line_work_action', 'SOURCE_BUILD',
      'force_legacy', false,
      'force_broad_legacy', false,
      'projection_class', CASE
        WHEN v_candidate_route_change IS TRUE THEN 'PAYE_UMBRELLA_SWITCH'
        WHEN v_trigger_table IN ('timesheets', 'timesheets_financials')
             AND (v_authorise_boundary_changed IS TRUE OR v_archive_boundary_changed IS TRUE) THEN 'TIMESHEET_LIFECYCLE'
        ELSE 'DIRTY_TRIGGER'
      END,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );

    IF v_candidate_route_change IS TRUE THEN
      v_payload_json := v_payload_json
        || jsonb_strip_nulls(
          jsonb_build_object(
            'candidate_pay_method_change', true,
            'candidate_payment_status_changed', true,
            'pay_method_changed', true,
            'prospective_only', true,
            'old_pay_method', v_route_source_method,
            'new_pay_method', v_route_target_method,
            'route_change_operation_id', v_route_operation_id,
            'route_change_actor_user_id', v_route_actor_user_id,
            'actor_user_id', v_route_actor_user_id,
            'route_change_reason', COALESCE(v_route_reason, 'PAY_METHOD_CHANGE'),
            'route_change_source_method', v_route_source_method,
            'route_change_target_method', v_route_target_method,
            'authorised_timesheet_ids', v_route_authorised_timesheet_ids,
            'authorised_timesheet_count', v_route_authorised_timesheet_count,
            'active_advance_timesheet_ids', v_route_active_advance_timesheet_ids,
            'active_advance_timesheet_count', v_route_active_advance_timesheet_count,
            'retained_finance_timesheet_ids', v_route_retained_finance_timesheet_ids,
            'retained_finance_timesheet_count', v_route_retained_finance_timesheet_count,
            'source_target_mismatch_count', v_route_source_target_mismatch_count,
            'authoritative_sessions', v_route_authoritative_sessions,
            'replaced_source_session_ids', v_route_replaced_source_session_ids,
            'target_details', v_route_target_details,
            'coverage_basis', COALESCE(v_route_scope_result->>'coverage_basis', 'CANONICAL_TIMESHEETS_WITH_RETAINED_FINANCE_AUTHORITY'),
            'coverage_complete', v_route_coverage_complete,
            'exact_target_scope', v_route_exact_scope,
            'targeted_scope_is_empty', v_route_targeted_scope_is_empty
          )
          || jsonb_build_object(
            'contracts_changed', 0,
            'contract_weeks_changed', 0,
            'timesheets_changed', 0,
            'rates_changed', 0,
            'tsfin_repricing_rows', 0,
            'source_records_mutated', false,
            'economic_truth_mutation_allowed', false,
            'refresh_completion_requires_terminal_exact_scope', true,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'policy_x_dirtying_only', true
          )
        );
    END IF;

    IF v_candidate_route_change IS TRUE THEN
      v_enqueue_result := jsonb_build_object(
        'ok', true,
        'job_id', v_route_job_id::text,
        'job_type', 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        'status', v_route_job_status,
        'dedupe_key', v_route_dedupe_key,
        'scope_kind', 'CANDIDATE',
        'scope_id', v_candidate_id::text,
        'candidate_id', v_candidate_id::text,
        'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
        'latest_source_change_seq', v_route_job_source_change_seq,
        'exact_target_scope', true,
        'targeted_scope_is_empty', v_route_targeted_scope_is_empty,
        'durable_scope_persisted', true
      );
    ELSE
      SELECT public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind => 'CANDIDATE',
        p_scope_id => v_candidate_id::text,
        p_candidate_id => v_candidate_id,
        p_targeted_timesheet_ids => v_targeted_timesheet_ids,
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      )
      INTO v_enqueue_result;
    END IF;

    v_jobs_queued := v_jobs_queued + 1;
  END LOOP;

  PERFORM public._temp_diag_log(
    'TEMP_TRIGGER_DIRTY_STAGE',
    'TEMP_BANKING_PAY_DIRTY',
    CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN v_targeted_timesheet_ids[1]::text ELSE NULL::text END,
    jsonb_build_object(
      'function_name', 'pay_workbench_mark_candidate_dirty',
      'stage', CASE
        WHEN v_jobs_queued = 0 AND TG_OP = 'INSERT' AND v_trigger_table = 'timesheets_financials' THEN 'return_no_dirty_after_timesheet_financials_insert_coalesced'
        ELSE 'return_enqueued_dirty_priority'
      END,
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'mutation_context', v_lifecycle_context,
      'candidate_count', COALESCE(array_length(v_candidate_ids, 1), 0),
      'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0),
      'jobs_queued', v_jobs_queued,
      'queue_class', 'DIRTY_TRIGGER_PRIORITY',
      'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)
    )
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;

-- pay_workbench_mark_contract_client_dirty()
CREATE OR REPLACE FUNCTION public.pay_workbench_mark_contract_client_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := clock_timestamp();
  v_trigger_table text := lower(TG_TABLE_NAME);
  v_new_row jsonb := '{}'::jsonb;
  v_old_row jsonb := '{}'::jsonb;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_contract_id_old uuid := NULL::uuid;
  v_contract_id_new uuid := NULL::uuid;
  v_client_id_old uuid := NULL::uuid;
  v_client_id_new uuid := NULL::uuid;
  v_candidate_id_old uuid := NULL::uuid;
  v_candidate_id_new uuid := NULL::uuid;
  v_row_id_old uuid := NULL::uuid;
  v_row_id_new uuid := NULL::uuid;
  v_scope record;
  v_reason text;
  v_payload_json jsonb := '{}'::jsonb;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_jobs_queued integer := 0;
BEGIN
  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', NULL::text, jsonb_build_object('function_name', 'pay_workbench_mark_contract_client_dirty', 'stage', 'entry', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'queue_class', 'DIRTY_TRIGGER_PRIORITY'));

  IF TG_OP <> 'DELETE' THEN v_new_row := to_jsonb(NEW); END IF;
  IF TG_OP <> 'INSERT' THEN v_old_row := to_jsonb(OLD); END IF;

  IF v_trigger_table = 'contracts' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN v_contract_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN v_contract_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re THEN v_candidate_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re THEN v_candidate_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid; END IF;
    v_row_id_old := v_contract_id_old;
    v_row_id_new := v_contract_id_new;
  ELSIF v_trigger_table = 'client_settings' THEN
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN v_row_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN v_row_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid; END IF;
  ELSE
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '') ~* v_uuid_re THEN v_contract_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '') ~* v_uuid_re THEN v_contract_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '') ~* v_uuid_re THEN v_client_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'client_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re THEN v_candidate_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re THEN v_candidate_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '') ~* v_uuid_re THEN v_row_id_old := NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid; END IF;
    IF NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '') ~* v_uuid_re THEN v_row_id_new := NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid; END IF;
  END IF;

  v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;

  FOR v_scope IN
    WITH scope_rows AS (
      SELECT 1::integer AS source_order, 'CONTRACT'::text AS scope_kind, v_contract_id_old AS scope_id, v_contract_id_old AS contract_id, v_client_id_old AS client_id, v_candidate_id_old AS candidate_id, v_row_id_old AS row_id
      UNION ALL
      SELECT 2::integer, 'CONTRACT', v_contract_id_new, v_contract_id_new, v_client_id_new, v_candidate_id_new, v_row_id_new
      UNION ALL
      SELECT 1::integer, 'CLIENT', v_client_id_old, NULL::uuid, v_client_id_old, v_candidate_id_old, v_row_id_old
      UNION ALL
      SELECT 2::integer, 'CLIENT', v_client_id_new, NULL::uuid, v_client_id_new, v_candidate_id_new, v_row_id_new
    )
    SELECT
      scope_rows.scope_kind,
      scope_rows.scope_id,
      (array_agg(scope_rows.contract_id ORDER BY scope_rows.source_order DESC))[1] AS contract_id,
      (array_agg(scope_rows.client_id ORDER BY scope_rows.source_order DESC))[1] AS client_id,
      (array_agg(scope_rows.candidate_id ORDER BY scope_rows.source_order) FILTER (WHERE scope_rows.candidate_id IS NOT NULL))[1] AS candidate_id,
      COALESCE(array_agg(DISTINCT scope_rows.candidate_id ORDER BY scope_rows.candidate_id) FILTER (WHERE scope_rows.candidate_id IS NOT NULL), ARRAY[]::uuid[]) AS candidate_ids,
      (array_agg(scope_rows.row_id ORDER BY scope_rows.source_order DESC))[1] AS row_id
    FROM scope_rows
    WHERE scope_rows.scope_id IS NOT NULL
    GROUP BY scope_rows.scope_kind, scope_rows.scope_id
    ORDER BY scope_rows.scope_kind, scope_rows.scope_id
  LOOP
    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'trigger_operation', TG_OP,
      'scope_kind', v_scope.scope_kind,
      'scope_id', v_scope.scope_id::text,
      'contract_id', CASE WHEN v_scope.contract_id IS NULL THEN NULL ELSE v_scope.contract_id::text END,
      'client_id', CASE WHEN v_scope.client_id IS NULL THEN NULL ELSE v_scope.client_id::text END,
      'candidate_id', CASE WHEN v_scope.candidate_id IS NULL THEN NULL ELSE v_scope.candidate_id::text END,
      'candidate_ids', to_jsonb(v_scope.candidate_ids),
      'row_id', CASE WHEN v_scope.row_id IS NULL THEN NULL ELSE v_scope.row_id::text END,
      'reason', v_reason,
      'page_limit', 100,
      'force_legacy', true,
      'projection_class', 'CONTRACT_CLIENT_DIRTY',
      'fallback_reason', 'CONTRACT_CLIENT_OR_CLIENT_SETTINGS_DIRTY',
      'refresh_scope_kind', 'CANDIDATE_FULL_LIVE',
      'source_build_required', true,
      'line_work_required', true,
      'delta_refresh_required', false,
      'row_backed_scope_required', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );

    SELECT public.pay_workbench_dirty_event_enqueue(
      p_job_type => 'CONTRACT_CLIENT_DIRTY_FANOUT',
      p_scope_kind => v_scope.scope_kind,
      p_scope_id => v_scope.scope_id::text,
      p_candidate_id => NULL::uuid,
      p_targeted_timesheet_ids => ARRAY[]::uuid[],
      p_linked_timesheet_ids => ARRAY[]::uuid[],
      p_payload_json => v_payload_json,
      p_reason => v_reason,
      p_priority => -1000,
      p_run_at_utc => v_now
    )
    INTO v_enqueue_result;

    v_jobs_queued := v_jobs_queued + 1;
  END LOOP;

  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', NULL::text, jsonb_build_object('function_name', 'pay_workbench_mark_contract_client_dirty', 'stage', 'return_enqueued_dirty_priority', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'jobs_queued', v_jobs_queued, 'queue_class', 'DIRTY_TRIGGER_PRIORITY', 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$;

-- pay_workbench_mark_finance_case_dirty()
CREATE OR REPLACE FUNCTION public.pay_workbench_mark_finance_case_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_now timestamptz := clock_timestamp();
  v_trigger_table text := lower(TG_TABLE_NAME);
  v_new_row jsonb := '{}'::jsonb;
  v_old_row jsonb := '{}'::jsonb;
  v_uuid_re text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_old_finance_case_id uuid := NULL::uuid;
  v_new_finance_case_id uuid := NULL::uuid;
  v_finance_case_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_finance_case_id uuid;
  v_candidate_id uuid;
  v_scope_id text;
  v_reason text;
  v_payload_json jsonb := '{}'::jsonb;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_jobs_queued integer := 0;
  v_internal_build_token uuid := NULL::uuid;
  v_internal_candidate_id uuid := NULL::uuid;
  v_internal_source_id uuid := NULL::uuid;
  v_internal_timesheet_id uuid := NULL::uuid;
  v_internal_logical_source_id uuid := NULL::uuid;
  v_internal_finance_case_id uuid := NULL::uuid;
  v_internal_finance_component_id uuid := NULL::uuid;
  v_internal_before_digest text := NULL::text;
  v_internal_after_digest text := NULL::text;
  v_expected_match_count integer := 0;
  v_internal_economic_key_type text := NULL::text;
  v_internal_economic_key_value text := NULL::text;
  v_effect_capture_mode boolean := lower(COALESCE(current_setting('cloudtms.pay_workbench_effect_capture_mode',true),''))='capture';
BEGIN
  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', NULL::text, jsonb_build_object('function_name', 'pay_workbench_mark_finance_case_dirty', 'stage', 'entry', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'queue_class', 'DIRTY_TRIGGER_PRIORITY'));

  IF TG_OP <> 'DELETE' THEN v_new_row := to_jsonb(NEW); END IF;
  IF TG_OP <> 'INSERT' THEN v_old_row := to_jsonb(OLD); END IF;

  -- These three retained Workbench triggers are recreated as BEFORE ROW
  -- triggers by the V1.2.4 trigger artifact.  The exact transition identity and
  -- full before/after digests are therefore declared before the finance DML is
  -- applied.  The current build token and durable RPC-2 context are required;
  -- an effect outside the sealed build scope fails the reconciliation.
  IF to_regclass('pg_temp._bpay_wb_sync_context_v1') IS NOT NULL
     AND to_regclass('pg_temp._bpay_wb_expected_effects') IS NOT NULL
     AND COALESCE(current_setting('cloudtms.pay_workbench_overpayment_sync_token',true),'')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_internal_build_token:=current_setting('cloudtms.pay_workbench_overpayment_sync_token',true)::uuid;
    SELECT build_row.candidate_id INTO v_internal_candidate_id
    FROM private.banking_pay_workbench_economic_builds build_row
    JOIN pg_temp._bpay_wb_sync_context_v1 sync_context
      ON sync_context.build_id=build_row.id AND sync_context.build_token=build_row.build_token
    JOIN private.banking_pay_workbench_stage_attempts attempt
      ON attempt.id=sync_context.attempt_id AND attempt.attempt_nonce=sync_context.attempt_nonce
      AND attempt.build_id=build_row.id AND attempt.attempt_status='STARTED'
    WHERE build_row.build_token=v_internal_build_token
      AND build_row.status='RECONCILING' AND build_row.private_stage='RECONCILE_EXECUTE';
    IF v_internal_candidate_id IS NOT NULL THEN
      IF TG_WHEN<>'BEFORE' THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CONFLICT' USING ERRCODE='23514';
      END IF;
      v_internal_source_id:=COALESCE(NULLIF(v_new_row->>'id','')::uuid,
        NULLIF(v_old_row->>'id','')::uuid,NULLIF(v_new_row->>'finance_case_id','')::uuid,
        NULLIF(v_old_row->>'finance_case_id','')::uuid);
      v_internal_timesheet_id:=COALESCE(NULLIF(v_new_row->>'linked_timesheet_id','')::uuid,
        NULLIF(v_old_row->>'linked_timesheet_id','')::uuid,NULLIF(v_new_row->>'timesheet_id','')::uuid,
        NULLIF(v_old_row->>'timesheet_id','')::uuid);
      IF v_internal_source_id IS NULL THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CONFLICT' USING ERRCODE='23514';
      END IF;
      v_internal_finance_case_id:=COALESCE(NULLIF(v_new_row->>'finance_case_id','')::uuid,
        NULLIF(v_old_row->>'finance_case_id','')::uuid,
        CASE WHEN v_trigger_table='pay_advances' THEN v_internal_source_id END);
      v_internal_finance_component_id:=COALESCE(
        NULLIF(v_new_row->>'finance_component_id','')::uuid,
        NULLIF(v_old_row->>'finance_component_id','')::uuid,
        CASE WHEN v_trigger_table='pay_finance_case_components' THEN v_internal_source_id END);
      -- Finance-case event rows do not carry their owner timesheet. Resolve it
      -- from the same stable parent identities used by the AFTER-statement
      -- observer so capture and execution cannot disagree merely because one
      -- side saw a nullable event payload.
      IF v_trigger_table='pay_finance_case_events' THEN
        SELECT COALESCE(component.linked_timesheet_id,finance_case.linked_timesheet_id)
        INTO v_internal_timesheet_id
        FROM (SELECT 1) anchor
        LEFT JOIN public.pay_finance_case_components component
          ON component.id=v_internal_finance_component_id
        LEFT JOIN public.pay_advances finance_case
          ON finance_case.id=COALESCE(v_internal_finance_case_id,component.finance_case_id);
      END IF;
      v_internal_economic_key_type:=COALESCE(NULLIF(btrim(v_new_row->>'component_key_type'),''),
        NULLIF(btrim(v_old_row->>'component_key_type'),''));
      v_internal_economic_key_value:=COALESCE(NULLIF(btrim(v_new_row->>'component_key_value'),''),
        NULLIF(btrim(v_old_row->>'component_key_value'),''));
      v_internal_before_digest:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE md5(
        private.pay_workbench_finance_effect_normalise_row_v1(
          v_trigger_table,TG_OP,v_old_row,v_old_row)::text) END;
      v_internal_after_digest:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE md5(
        private.pay_workbench_finance_effect_normalise_row_v1(
          v_trigger_table,TG_OP,v_new_row,v_old_row)::text) END;

      IF COALESCE(NULLIF(v_new_row->>'candidate_id','')::uuid,
           NULLIF(v_old_row->>'candidate_id','')::uuid,
           (SELECT finance_case.candidate_id FROM public.pay_advances finance_case
             WHERE finance_case.id=v_internal_finance_case_id))
           IS DISTINCT FROM v_internal_candidate_id
         OR (v_internal_timesheet_id IS NOT NULL AND NOT EXISTS(
           SELECT 1 FROM private.banking_pay_workbench_economic_build_scope scope_row
           JOIN pg_temp._bpay_wb_sync_context_v1 sync_context
             ON sync_context.build_id=scope_row.build_id
           WHERE scope_row.timesheet_id=v_internal_timesheet_id
         ))
         OR (v_trigger_table='pay_finance_case_components'
           AND v_internal_economic_key_type IS NOT NULL
           AND NOT EXISTS(
             SELECT 1 FROM private.banking_pay_workbench_economic_build_facts fact
             JOIN pg_temp._bpay_wb_sync_context_v1 sync_context
               ON sync_context.build_id=fact.build_id
             WHERE fact.economic_key_type=v_internal_economic_key_type
               AND fact.economic_key_value=v_internal_economic_key_value
           )
           AND NOT EXISTS(
             SELECT 1 FROM private.banking_pay_workbench_economic_build_facts fact
             JOIN pg_temp._bpay_wb_sync_context_v1 sync_context
               ON sync_context.build_id=fact.build_id
             WHERE fact.finance_component_id=v_internal_finance_component_id
           )) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
      END IF;
      IF v_effect_capture_mode THEN
        INSERT INTO pg_temp._bpay_wb_expected_effects(
          build_token,candidate_id,timesheet_id,relation_name,operation,source_id,
          finance_case_id,finance_component_id,economic_key_type,economic_key_value,
          expected_before_digest,expected_after_digest,proposed,observed
        ) VALUES(
          v_internal_build_token,v_internal_candidate_id,v_internal_timesheet_id,v_trigger_table,TG_OP,
          v_internal_source_id,v_internal_finance_case_id,v_internal_finance_component_id,
          v_internal_economic_key_type,v_internal_economic_key_value,
          v_internal_before_digest,v_internal_after_digest,true,false
        );
      ELSIF TG_OP='INSERT' THEN
        UPDATE pg_temp._bpay_wb_expected_effects expected
        SET actual_source_id=v_internal_source_id,proposed=true
        WHERE expected.ctid=(SELECT candidate.ctid
          FROM pg_temp._bpay_wb_expected_effects candidate
          WHERE candidate.build_token=v_internal_build_token
            AND candidate.candidate_id=v_internal_candidate_id
            AND candidate.timesheet_id IS NOT DISTINCT FROM v_internal_timesheet_id
            AND candidate.relation_name=v_trigger_table AND candidate.operation=TG_OP
            AND candidate.proposed IS NOT TRUE AND candidate.observed IS NOT TRUE
            AND candidate.economic_key_type IS NOT DISTINCT FROM v_internal_economic_key_type
            AND candidate.economic_key_value IS NOT DISTINCT FROM v_internal_economic_key_value
            AND candidate.expected_before_digest IS NULL
            AND candidate.expected_after_digest IS NOT DISTINCT FROM v_internal_after_digest
            AND (v_trigger_table<>'pay_finance_case_components' OR
              COALESCE((SELECT identity_map.actual_source_id
                FROM pg_temp._bpay_wb_effect_identity_map_v1 identity_map
                WHERE identity_map.relation_name='pay_advances'
                  AND identity_map.logical_source_id=candidate.finance_case_id),
                candidate.finance_case_id) IS NOT DISTINCT FROM v_internal_finance_case_id)
            AND (v_trigger_table<>'pay_finance_case_events' OR (
              COALESCE((SELECT identity_map.actual_source_id
                FROM pg_temp._bpay_wb_effect_identity_map_v1 identity_map
                WHERE identity_map.relation_name='pay_advances'
                  AND identity_map.logical_source_id=candidate.finance_case_id),
                candidate.finance_case_id) IS NOT DISTINCT FROM v_internal_finance_case_id
              AND COALESCE((SELECT identity_map.actual_source_id
                FROM pg_temp._bpay_wb_effect_identity_map_v1 identity_map
                WHERE identity_map.relation_name='pay_finance_case_components'
                  AND identity_map.logical_source_id=candidate.finance_component_id),
                candidate.finance_component_id) IS NOT DISTINCT FROM v_internal_finance_component_id))
          ORDER BY candidate.source_id LIMIT 1)
        RETURNING expected.source_id INTO v_internal_logical_source_id;
        GET DIAGNOSTICS v_expected_match_count=ROW_COUNT;
        IF v_expected_match_count<>1 OR v_internal_logical_source_id IS NULL THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
        END IF;
        INSERT INTO pg_temp._bpay_wb_effect_identity_map_v1(
          relation_name,logical_source_id,actual_source_id)
        VALUES(v_trigger_table,v_internal_logical_source_id,v_internal_source_id);
      ELSE
        UPDATE pg_temp._bpay_wb_expected_effects expected SET proposed=true
        WHERE expected.build_token=v_internal_build_token
          AND expected.candidate_id=v_internal_candidate_id
          AND expected.timesheet_id IS NOT DISTINCT FROM v_internal_timesheet_id
          AND expected.relation_name=v_trigger_table AND expected.operation=TG_OP
          AND expected.source_id=v_internal_source_id
          AND expected.finance_case_id IS NOT DISTINCT FROM v_internal_finance_case_id
          AND expected.finance_component_id IS NOT DISTINCT FROM v_internal_finance_component_id
          AND expected.economic_key_type IS NOT DISTINCT FROM v_internal_economic_key_type
          AND expected.economic_key_value IS NOT DISTINCT FROM v_internal_economic_key_value
          AND expected.proposed IS NOT TRUE AND expected.observed IS NOT TRUE
          AND expected.expected_before_digest IS NOT DISTINCT FROM v_internal_before_digest
          AND expected.expected_after_digest IS NOT DISTINCT FROM v_internal_after_digest;
        GET DIAGNOSTICS v_expected_match_count=ROW_COUNT;
        IF v_expected_match_count<>1 THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH' USING ERRCODE='23514';
        END IF;
      END IF;
      IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;
  END IF;

  -- A protected preview synchronisation deliberately records SYNC_SKIPPED as
  -- audit evidence.  That informational event must not dirty Banking Pay and
  -- enqueue the same protected synchronisation again.
  IF v_trigger_table = 'pay_finance_case_events'
     AND TG_OP <> 'DELETE'
     AND UPPER(BTRIM(COALESCE(v_new_row->>'event_type', ''))) = 'SYNC_SKIPPED' THEN
    RETURN NEW;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_old_row->>'finance_case_id', v_old_row->>'id', '')), '') ~* v_uuid_re THEN
    v_old_finance_case_id := NULLIF(BTRIM(COALESCE(v_old_row->>'finance_case_id', v_old_row->>'id', '')), '')::uuid;
  END IF;
  IF NULLIF(BTRIM(COALESCE(v_new_row->>'finance_case_id', v_new_row->>'id', '')), '') ~* v_uuid_re THEN
    v_new_finance_case_id := NULLIF(BTRIM(COALESCE(v_new_row->>'finance_case_id', v_new_row->>'id', '')), '')::uuid;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT finance_cases.finance_case_id ORDER BY finance_cases.finance_case_id), ARRAY[]::uuid[])
  INTO v_finance_case_ids
  FROM (
    SELECT v_old_finance_case_id AS finance_case_id
    UNION ALL
    SELECT v_new_finance_case_id AS finance_case_id
  ) AS finance_cases
  WHERE finance_cases.finance_case_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT candidates.candidate_id ORDER BY candidates.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM (
    SELECT CASE WHEN NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '') ~* v_uuid_re THEN NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid ELSE NULL::uuid END AS candidate_id
    UNION ALL
    SELECT CASE WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '') ~* v_uuid_re THEN NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid ELSE NULL::uuid END AS candidate_id
    UNION ALL
    SELECT component_old.candidate_id FROM public.pay_finance_case_components AS component_old WHERE component_old.finance_case_id = v_old_finance_case_id
    UNION ALL
    SELECT component_new.candidate_id FROM public.pay_finance_case_components AS component_new WHERE component_new.finance_case_id = v_new_finance_case_id
    UNION ALL
    SELECT advance_old.candidate_id FROM public.pay_advances AS advance_old WHERE advance_old.id = v_old_finance_case_id
    UNION ALL
    SELECT advance_new.candidate_id FROM public.pay_advances AS advance_new WHERE advance_new.id = v_new_finance_case_id
  ) AS candidates
  WHERE candidates.candidate_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT timesheets.timesheet_id ORDER BY timesheets.timesheet_id), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM (
    SELECT CASE WHEN NULLIF(BTRIM(COALESCE(v_old_row->>'linked_timesheet_id', v_old_row->>'timesheet_id', '')), '') ~* v_uuid_re THEN NULLIF(BTRIM(COALESCE(v_old_row->>'linked_timesheet_id', v_old_row->>'timesheet_id', '')), '')::uuid ELSE NULL::uuid END AS timesheet_id
    UNION ALL
    SELECT CASE WHEN NULLIF(BTRIM(COALESCE(v_new_row->>'linked_timesheet_id', v_new_row->>'timesheet_id', '')), '') ~* v_uuid_re THEN NULLIF(BTRIM(COALESCE(v_new_row->>'linked_timesheet_id', v_new_row->>'timesheet_id', '')), '')::uuid ELSE NULL::uuid END AS timesheet_id
  ) AS timesheets
  WHERE timesheets.timesheet_id IS NOT NULL;

  v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;

  IF COALESCE(array_length(v_finance_case_ids, 1), 0) > 0 THEN
    FOREACH v_finance_case_id IN ARRAY v_finance_case_ids
    LOOP
      v_payload_json := jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'trigger_operation', TG_OP,
        'scope_kind', 'FINANCE_CASE',
        'scope_id', v_finance_case_id::text,
        'finance_case_id', v_finance_case_id::text,
        'finance_case_ids', to_jsonb(v_finance_case_ids),
        'candidate_ids', to_jsonb(v_candidate_ids),
        'targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids),
        'reason', v_reason,
        'dirty_reason', v_reason,
        'refresh_scope_kind', CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END,
        'force_legacy', true,
        'projection_class', 'FINANCE_CASE',
        'fallback_reason', 'FINANCE_CASE_DIRTY_TRIGGER',
        'source_build_required', true,
        'line_work_required', true,
        'row_backed_scope_required', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );

      SELECT public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
        p_scope_kind => 'FINANCE_CASE',
        p_scope_id => v_finance_case_id::text,
        p_candidate_id => NULL::uuid,
        p_targeted_timesheet_ids => v_targeted_timesheet_ids,
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      )
      INTO v_enqueue_result;
      v_jobs_queued := v_jobs_queued + 1;
    END LOOP;
  ELSE
    FOREACH v_candidate_id IN ARRAY v_candidate_ids
    LOOP
      v_scope_id := v_candidate_id::text;
      v_payload_json := jsonb_build_object(
        'trigger_table', v_trigger_table,
        'trigger_op', TG_OP,
        'trigger_operation', TG_OP,
        'scope_kind', 'CANDIDATE',
        'scope_id', v_scope_id,
        'candidate_id', v_scope_id,
        'candidate_ids', to_jsonb(ARRAY[v_candidate_id]),
        'targeted_timesheet_ids', to_jsonb(v_targeted_timesheet_ids),
        'reason', v_reason,
        'dirty_reason', v_reason,
        'refresh_scope_kind', CASE WHEN COALESCE(array_length(v_targeted_timesheet_ids, 1), 0) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END,
        'projection_class', 'FINANCE_CASE',
        'fallback_reason', 'FINANCE_CASE_DIRTY_TRIGGER_NO_CASE_ID',
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );

      SELECT public.pay_workbench_dirty_event_enqueue(
        p_job_type => 'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind => 'CANDIDATE',
        p_scope_id => v_scope_id,
        p_candidate_id => v_candidate_id,
        p_targeted_timesheet_ids => v_targeted_timesheet_ids,
        p_linked_timesheet_ids => ARRAY[]::uuid[],
        p_payload_json => v_payload_json,
        p_reason => v_reason,
        p_priority => -1000,
        p_run_at_utc => v_now
      )
      INTO v_enqueue_result;
      v_jobs_queued := v_jobs_queued + 1;
    END LOOP;
  END IF;

  PERFORM public._temp_diag_log('TEMP_TRIGGER_DIRTY_STAGE', 'TEMP_BANKING_PAY_DIRTY', NULL::text, jsonb_build_object('function_name', 'pay_workbench_mark_finance_case_dirty', 'stage', 'return_enqueued_dirty_priority', 'trigger_table', v_trigger_table, 'trigger_op', TG_OP, 'finance_case_count', COALESCE(array_length(v_finance_case_ids, 1), 0), 'candidate_count', COALESCE(array_length(v_candidate_ids, 1), 0), 'targeted_timesheet_count', COALESCE(array_length(v_targeted_timesheet_ids, 1), 0), 'jobs_queued', v_jobs_queued, 'queue_class', 'DIRTY_TRIGGER_PRIORITY', 'elapsed_ms', ROUND((EXTRACT(EPOCH FROM (clock_timestamp() - v_started_at)) * 1000)::numeric, 2)));

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$function$;

-- pay_workbench_operation_active_snoozes_v1(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_operation_active_snoozes_v1(p_operation_id uuid, p_workbench_session_id uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_today_uk date := (clock_timestamp() AT TIME ZONE 'Europe/London')::date;
  v_scope_ids jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_candidate_scope_ids, '[]'::jsonb)) = 'array'
      THEN COALESCE(p_candidate_scope_ids, '[]'::jsonb)
    ELSE '[]'::jsonb
  END;
  v_scope_filter_count integer := 0;
  v_selected_line_count integer := 0;
  v_active_snooze_count integer := 0;
  v_candidate_id uuid;
  v_snoozes jsonb := '[]'::jsonb;
  v_preview_row_ids jsonb := '[]'::jsonb;
  v_timesheet_ids jsonb := '[]'::jsonb;
  v_segment_stable_keys jsonb := '[]'::jsonb;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_DRAFT_SNOOZE_GUARD_OPERATION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_PAY_DRAFT_SNOOZE_GUARD_OPERATION_REQUIRED')::text;
  END IF;

  IF p_workbench_session_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_PAY_DRAFT_SNOOZE_GUARD_SESSION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_PAY_DRAFT_SNOOZE_GUARD_SESSION_REQUIRED')::text;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
      AND operation_row.workbench_session_id = p_workbench_session_id
      AND UPPER(BTRIM(COALESCE(operation_row.operation_type, ''))) = 'DRAFT_CREATE'
  ) THEN
    RAISE EXCEPTION 'BANKING_PAY_DRAFT_SNOOZE_GUARD_OPERATION_SESSION_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_DRAFT_SNOOZE_GUARD_OPERATION_SESSION_MISMATCH',
              'operation_id', p_operation_id::text,
              'workbench_session_id', p_workbench_session_id::text
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_scope_filter_count
  FROM jsonb_array_elements_text(v_scope_ids) AS scope_id(value)
  WHERE NULLIF(BTRIM(scope_id.value), '') IS NOT NULL;

  IF v_scope_filter_count > 100 THEN
    RAISE EXCEPTION 'BANKING_PAY_DRAFT_SNOOZE_GUARD_SCOPE_LIMIT_EXCEEDED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_DRAFT_SNOOZE_GUARD_SCOPE_LIMIT_EXCEEDED',
              'scope_count', v_scope_filter_count,
              'maximum_scope_count', 100
            )::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_draft_snooze_guard_scope;
  CREATE TEMP TABLE _bpay_draft_snooze_guard_scope (
    candidate_scope_id uuid NOT NULL,
    preview_row_id uuid,
    candidate_id uuid NOT NULL,
    timesheet_id uuid,
    booking_id text,
    segment_id text,
    segment_stable_key text,
    source_ref text
  ) ON COMMIT DROP;

  INSERT INTO pg_temp._bpay_draft_snooze_guard_scope (
    candidate_scope_id,
    preview_row_id,
    candidate_id,
    timesheet_id,
    booking_id,
    segment_id,
    segment_stable_key,
    source_ref
  )
  SELECT DISTINCT
    candidate_scope.id,
    CASE
      WHEN NULLIF(BTRIM(COALESCE(
        selected_line.line_json->>'preview_row_id',
        selected_line.line_json->>'previewRowId',
        selected_line.line_json->>'id',
        ''
      )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN NULLIF(BTRIM(COALESCE(
          selected_line.line_json->>'preview_row_id',
          selected_line.line_json->>'previewRowId',
          selected_line.line_json->>'id',
          ''
        )), '')::uuid
      ELSE NULL::uuid
    END,
    candidate_scope.candidate_id,
    CASE
      WHEN NULLIF(BTRIM(COALESCE(
        selected_line.line_json->>'timesheet_id',
        selected_line.line_json->>'timesheetId',
        selected_line.line_json->>'source_timesheet_id',
        selected_line.line_json->>'sourceTimesheetId',
        ''
      )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN NULLIF(BTRIM(COALESCE(
          selected_line.line_json->>'timesheet_id',
          selected_line.line_json->>'timesheetId',
          selected_line.line_json->>'source_timesheet_id',
          selected_line.line_json->>'sourceTimesheetId',
          ''
        )), '')::uuid
      ELSE NULL::uuid
    END,
    NULLIF(BTRIM(COALESCE(
      selected_line.line_json->>'booking_id',
      selected_line.line_json->>'bookingId',
      selected_line.line_json#>>'{timesheet,booking_id}',
      ''
    )), ''),
    NULLIF(BTRIM(COALESCE(
      selected_line.line_json->>'segment_id',
      selected_line.line_json->>'segmentId',
      selected_line.line_json->>'segment_identity',
      selected_line.line_json->>'seg_identity',
      selected_line.line_json#>>'{segment,id}',
      ''
    )), ''),
    NULLIF(BTRIM(COALESCE(
      selected_line.line_json->>'segment_stable_key',
      selected_line.line_json->>'segmentStableKey',
      selected_line.line_json#>>'{segment,stable_key}',
      selected_line.line_json#>>'{snooze_identity,segment_stable_key}',
      ''
    )), ''),
    NULLIF(BTRIM(COALESCE(
      selected_line.line_json->>'source_ref',
      selected_line.line_json->>'sourceRef',
      CASE
        WHEN NULLIF(BTRIM(COALESCE(selected_line.line_json->>'finance_case_id', '')), '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN 'advance:' || NULLIF(BTRIM(selected_line.line_json->>'finance_case_id'), '')
        ELSE NULL::text
      END,
      ''
    )), '')
  FROM public.banking_pay_operation_candidate_scope AS candidate_scope
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(candidate_scope.selected_canonical_preview_lines_json) = 'array'
        THEN candidate_scope.selected_canonical_preview_lines_json
      ELSE '[]'::jsonb
    END
  ) AS selected_line(line_json)
  WHERE candidate_scope.operation_id = p_operation_id
    AND candidate_scope.workbench_session_id = p_workbench_session_id
    AND (
      v_scope_filter_count = 0
      OR candidate_scope.id::text IN (
        SELECT BTRIM(scope_id.value)
        FROM jsonb_array_elements_text(v_scope_ids) AS scope_id(value)
      )
    )
  ;

  -- Compatibility fallback for legacy candidate-scope rows whose selected
  -- canonical line array is empty but selected preview-row IDs are present.
  INSERT INTO pg_temp._bpay_draft_snooze_guard_scope (
    candidate_scope_id,
    preview_row_id,
    candidate_id,
    timesheet_id,
    booking_id,
    segment_id,
    segment_stable_key,
    source_ref
  )
  SELECT DISTINCT
    candidate_scope.id,
    preview_row.id,
    candidate_scope.candidate_id,
    COALESCE(
      preview_row.timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(preview_row.row_json->>'timesheet_id', '')), '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(preview_row.row_json->>'timesheet_id'), '')::uuid
        ELSE NULL::uuid
      END
    ),
    NULLIF(BTRIM(COALESCE(
      preview_row.row_json->>'booking_id',
      preview_row.row_json->>'bookingId',
      preview_row.row_json#>>'{timesheet,booking_id}',
      ''
    )), ''),
    NULLIF(BTRIM(COALESCE(
      preview_row.row_json->>'segment_id',
      preview_row.row_json->>'segmentId',
      preview_row.row_json->>'segment_identity',
      preview_row.row_json->>'seg_identity',
      ''
    )), ''),
    NULLIF(BTRIM(COALESCE(
      preview_row.row_json->>'segment_stable_key',
      preview_row.row_json->>'segmentStableKey',
      preview_row.row_json#>>'{segment,stable_key}',
      preview_row.row_json#>>'{snooze_identity,segment_stable_key}',
      ''
    )), ''),
    NULLIF(BTRIM(COALESCE(
      preview_row.row_json->>'source_ref',
      preview_row.row_json->>'sourceRef',
      CASE
        WHEN NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_case_id', '')), '')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN 'advance:' || NULLIF(BTRIM(preview_row.row_json->>'finance_case_id'), '')
        ELSE NULL::text
      END,
      ''
    )), '')
  FROM public.banking_pay_operation_candidate_scope AS candidate_scope
  CROSS JOIN LATERAL jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(candidate_scope.selected_preview_row_ids_json) = 'array'
        THEN candidate_scope.selected_preview_row_ids_json
      ELSE '[]'::jsonb
    END
  ) AS selected_preview_id(value)
  JOIN public.banking_pay_workbench_preview_rows AS preview_row
    ON preview_row.session_id = p_workbench_session_id
   AND preview_row.candidate_id = candidate_scope.candidate_id
   AND preview_row.id::text = BTRIM(selected_preview_id.value)
  WHERE candidate_scope.operation_id = p_operation_id
    AND candidate_scope.workbench_session_id = p_workbench_session_id
    AND jsonb_array_length(
      CASE
        WHEN jsonb_typeof(candidate_scope.selected_canonical_preview_lines_json) = 'array'
          THEN candidate_scope.selected_canonical_preview_lines_json
        ELSE '[]'::jsonb
      END
    ) = 0
    AND (
      v_scope_filter_count = 0
      OR candidate_scope.id::text IN (
        SELECT BTRIM(scope_id.value)
        FROM jsonb_array_elements_text(v_scope_ids) AS scope_id(value)
      )
    )
  ;

  UPDATE pg_temp._bpay_draft_snooze_guard_scope AS guard_scope
  SET booking_id = COALESCE(guard_scope.booking_id, NULLIF(BTRIM(COALESCE(timesheet_row.booking_id, '')), ''))
  FROM public.timesheets AS timesheet_row
  WHERE guard_scope.timesheet_id = timesheet_row.timesheet_id
    AND guard_scope.booking_id IS NULL;

  SELECT COUNT(*)::integer
  INTO v_selected_line_count
  FROM pg_temp._bpay_draft_snooze_guard_scope;

  IF v_selected_line_count > 5000 THEN
    RAISE EXCEPTION 'BANKING_PAY_DRAFT_SNOOZE_GUARD_SELECTED_LINE_LIMIT_EXCEEDED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_PAY_DRAFT_SNOOZE_GUARD_SELECTED_LINE_LIMIT_EXCEEDED',
              'selected_line_count', v_selected_line_count,
              'maximum_selected_line_count', 5000
            )::text;
  END IF;

  FOR v_candidate_id IN
    SELECT DISTINCT guard_scope.candidate_id
    FROM pg_temp._bpay_draft_snooze_guard_scope AS guard_scope
    ORDER BY guard_scope.candidate_id
  LOOP
    PERFORM pg_advisory_xact_lock(
      pg_catalog.hashtext('public.banking_pay_candidate_snooze_guard'),
      pg_catalog.hashtext(v_candidate_id::text)
    );
  END LOOP;

  DROP TABLE IF EXISTS pg_temp._bpay_draft_active_snoozes;
  CREATE TEMP TABLE _bpay_draft_active_snoozes ON COMMIT DROP AS
  SELECT DISTINCT
    guard_scope.candidate_scope_id,
    guard_scope.preview_row_id,
    guard_scope.candidate_id,
    guard_scope.timesheet_id,
    guard_scope.segment_stable_key AS selected_segment_stable_key,
    guard_scope.source_ref AS selected_source_ref,
    snooze_row.id AS snooze_id,
    snooze_row.snooze_kind,
    snooze_row.snooze_until_date,
    snooze_row.timesheet_id AS snooze_timesheet_id,
    snooze_row.booking_id AS snooze_booking_id,
    snooze_row.segment_id AS snooze_segment_id,
    snooze_row.segment_stable_key AS snooze_segment_stable_key,
    snooze_row.source_ref AS snooze_source_ref,
    CASE
      WHEN guard_scope.source_ref IS NOT NULL THEN 'EXACT_SOURCE_REF'
      ELSE 'LEGACY_TIMESHEET_SEGMENT'
    END AS match_scope
  FROM pg_temp._bpay_draft_snooze_guard_scope AS guard_scope
  JOIN public.pay_item_snoozes AS snooze_row
    ON snooze_row.candidate_id = guard_scope.candidate_id
   AND snooze_row.cleared_at_utc IS NULL
   AND snooze_row.cancelled_at_utc IS NULL
   AND (
     snooze_row.snooze_until_date IS NULL
     OR snooze_row.snooze_until_date >= v_today_uk
   )
   AND (
     (
       guard_scope.source_ref IS NOT NULL
       AND LOWER(NULLIF(BTRIM(COALESCE(snooze_row.source_ref, '')), '')) = LOWER(guard_scope.source_ref)
     )
     OR (
       guard_scope.source_ref IS NULL
       AND snooze_row.source_ref IS NULL
       AND (
         (guard_scope.timesheet_id IS NOT NULL AND snooze_row.timesheet_id = guard_scope.timesheet_id)
         OR (
           guard_scope.booking_id IS NOT NULL
           AND NULLIF(BTRIM(COALESCE(snooze_row.booking_id, '')), '') = guard_scope.booking_id
         )
       )
       AND (
         (
           snooze_row.segment_stable_key IS NULL
           AND snooze_row.segment_id IS NULL
         )
         OR (
           guard_scope.segment_stable_key IS NOT NULL
           AND NULLIF(BTRIM(COALESCE(snooze_row.segment_stable_key, '')), '') = guard_scope.segment_stable_key
         )
         OR (
           guard_scope.segment_stable_key IS NULL
           AND guard_scope.segment_id IS NOT NULL
           AND NULLIF(BTRIM(COALESCE(snooze_row.segment_id, '')), '') = guard_scope.segment_id
         )
       )
     )
   );

  SELECT COUNT(*)::integer
  INTO v_active_snooze_count
  FROM pg_temp._bpay_draft_active_snoozes;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'snooze_id', active_snooze.snooze_id::text,
        'candidate_scope_id', active_snooze.candidate_scope_id::text,
        'preview_row_id', CASE WHEN active_snooze.preview_row_id IS NULL THEN NULL ELSE active_snooze.preview_row_id::text END,
        'candidate_id', active_snooze.candidate_id::text,
        'timesheet_id', CASE WHEN active_snooze.timesheet_id IS NULL THEN NULL ELSE active_snooze.timesheet_id::text END,
        'segment_stable_key', active_snooze.selected_segment_stable_key,
        'snooze_kind', active_snooze.snooze_kind,
        'snooze_until_date', CASE WHEN active_snooze.snooze_until_date IS NULL THEN NULL ELSE active_snooze.snooze_until_date::text END,
        'indefinite', active_snooze.snooze_until_date IS NULL,
        'source_ref', active_snooze.selected_source_ref,
        'snooze_source_ref', active_snooze.snooze_source_ref,
        'source_match_scope', active_snooze.match_scope,
        'identity_type', CASE
          WHEN active_snooze.selected_source_ref ~* '^timesheet-expense:' THEN 'TIMESHEET_EXPENSE'
          WHEN active_snooze.selected_source_ref IS NOT NULL THEN 'EXACT_SOURCE'
          WHEN active_snooze.selected_segment_stable_key IS NOT NULL THEN 'TIMESHEET_SEGMENT'
          ELSE 'TIMESHEET'
        END
      ))
      ORDER BY active_snooze.candidate_id, active_snooze.timesheet_id, active_snooze.snooze_id
    ),
    '[]'::jsonb
  )
  INTO v_snoozes
  FROM pg_temp._bpay_draft_active_snoozes AS active_snooze;

  SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
  INTO v_preview_row_ids
  FROM (
    SELECT DISTINCT active_snooze.preview_row_id::text AS value
    FROM pg_temp._bpay_draft_active_snoozes AS active_snooze
    WHERE active_snooze.preview_row_id IS NOT NULL
  ) AS preview_values;

  SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
  INTO v_timesheet_ids
  FROM (
    SELECT DISTINCT active_snooze.timesheet_id::text AS value
    FROM pg_temp._bpay_draft_active_snoozes AS active_snooze
    WHERE active_snooze.timesheet_id IS NOT NULL
  ) AS timesheet_values;

  SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
  INTO v_segment_stable_keys
  FROM (
    SELECT DISTINCT active_snooze.selected_segment_stable_key AS value
    FROM pg_temp._bpay_draft_active_snoozes AS active_snooze
    WHERE active_snooze.selected_segment_stable_key IS NOT NULL
  ) AS segment_values;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'workbench_session_id', p_workbench_session_id::text,
    'london_current_date', v_today_uk::text,
    'selected_line_count', v_selected_line_count,
    'active_snooze_count', v_active_snooze_count,
    'affected_preview_row_ids', v_preview_row_ids,
    'affected_timesheet_ids', v_timesheet_ids,
    'affected_segment_stable_keys', v_segment_stable_keys,
    'snoozes', v_snoozes,
    'active_snoozes', v_snoozes,
    'refresh_required', v_active_snooze_count > 0,
    'next_action', CASE WHEN v_active_snooze_count > 0 THEN 'REFRESH_WORKBENCH' ELSE 'CONTINUE_DRAFT' END
  );
END;
$function$;

-- pay_workbench_patch_preview_after_batch_mutation_cancel_safe_v1(uuid,uuid,text,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_patch_preview_after_batch_mutation_cancel_safe_v1(p_session_id uuid, p_pay_batch_id uuid, p_operation_type text, p_actor_user_id uuid DEFAULT NULL::uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_result jsonb := '{}'::jsonb;
  v_operation_type text := UPPER(BTRIM(COALESCE(p_operation_type, '')));
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_candidate_id uuid;
  v_changed_finance_case_ids uuid[] := ARRAY[]::uuid[];
  v_enqueue_result jsonb := '{}'::jsonb;
  v_job_id uuid;
  v_full_refresh_count integer := 0;
  v_candidate_full_refresh_count integer := 0;
  v_superseded_targeted_job_count integer := 0;
  v_superseded_targeted_job_chunk_count integer := 0;
  v_superseded_finance_dirty_job_count integer := 0;
  v_full_refresh_job_ids jsonb := '[]'::jsonb;
  v_preserved_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_preserved_selected_row_count integer := 0;
  v_cancelled_row_unselected_count integer := 0;
  v_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_requested_refresh_scope text := 'CANDIDATE_FULL_LIVE';
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_attestation jsonb := '{}'::jsonb;
  v_republication_result jsonb := '{}'::jsonb;
  v_candidate_state_result jsonb := '{}'::jsonb;
  v_physical_currentness jsonb := '{}'::jsonb;
  v_candidate_currentness jsonb := '{}'::jsonb;
  v_direct_current_candidate_ids jsonb := '[]'::jsonb;
  v_physical_currentness_results jsonb := '[]'::jsonb;
  v_direct_current_count integer := 0;
  v_repair_owner_count integer := 0;
  v_post_cancel_patch_digest text := NULL::text;
  v_progress_recompute jsonb := '{}'::jsonb;
  v_post_commit_authority jsonb := '{}'::jsonb;
  v_preceding_scope_proven boolean := false;
BEGIN
  -- Preserve the last certified source authority before the generic overlay
  -- patch deliberately marks the scope non-current.  The saved authority is
  -- used only to republish the same immutable source rows; it is never used to
  -- derive or recalculate post-Draft economics.
  DROP TABLE IF EXISTS pg_temp._bpay_cancel_safe_original_authority;
  CREATE TEMPORARY TABLE pg_temp._bpay_cancel_safe_original_authority(
    candidate_id uuid PRIMARY KEY,
    attestation jsonb NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp._bpay_cancel_safe_original_authority(candidate_id,attestation)
  SELECT scope_row.candidate_id,
         COALESCE(scope_row.certified_preview_publication_attestation_json,'{}'::jsonb)
  FROM public.banking_pay_workbench_session_scope AS scope_row
  JOIN public.pay_batch_candidates AS batch_candidate
    ON batch_candidate.candidate_id=scope_row.candidate_id
   AND batch_candidate.pay_batch_id=p_pay_batch_id
  WHERE scope_row.session_id=p_session_id
  ORDER BY scope_row.candidate_id;

  v_result := public.pay_workbench_patch_preview_after_batch_mutation(
    p_session_id,
    p_pay_batch_id,
    p_operation_type,
    p_actor_user_id,
    COALESCE(p_options_json,'{}'::jsonb) || jsonb_build_object('defer_complex_enqueue',true)
  );

  IF COALESCE((v_result->>'ok')::boolean, true) IS NOT TRUE
     OR v_operation_type NOT IN ('DRAFT_DELETE', 'DRAFT_CANCEL') THEN
    RETURN v_result;
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
    AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
    AND session_row.discarded_at_utc IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CANCEL_FULL_REFRESH_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CANCEL_FULL_REFRESH_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  v_post_cancel_patch_digest:=NULLIF(BTRIM(COALESCE(v_result->>'post_cancel_patch_digest','')),'');

  -- Cancelling a draft returns its rows to the live workbench, but it must not
  -- silently select those rows again. Persist an explicit selection snapshot
  -- before the full-candidate refresh is queued so the materialiser preserves
  -- every unrelated selection while restoring the cancelled rows unselected.
  UPDATE public.banking_pay_workbench_preview_rows AS cancelled_preview_row
  SET selected = false,
      selection_state = CASE
        WHEN UPPER(BTRIM(COALESCE(cancelled_preview_row.status, ''))) = 'READY' THEN 'UNSELECTED'
        ELSE 'NOT_SELECTABLE'
      END,
      row_json = jsonb_strip_nulls(
        COALESCE(cancelled_preview_row.row_json, '{}'::jsonb)
        || jsonb_build_object(
          'selected', false,
          'selection_state', CASE
            WHEN UPPER(BTRIM(COALESCE(cancelled_preview_row.status, ''))) = 'READY' THEN 'UNSELECTED'
            ELSE 'NOT_SELECTABLE'
          END,
          'selection_user_override', CASE
            WHEN COALESCE((SELECT setting.banking_pay_selection_intent_identity_v1_enabled
                             FROM public.settings_defaults AS setting WHERE setting.id=1),false)
              THEN 'UNSELECTED' ELSE cancelled_preview_row.row_json->>'selection_user_override' END,
          'selection_origin', CASE
            WHEN COALESCE((SELECT setting.banking_pay_selection_intent_identity_v1_enabled
                             FROM public.settings_defaults AS setting WHERE setting.id=1),false)
              THEN 'POST_CANCEL_RETURN_UNSELECTED' ELSE cancelled_preview_row.row_json->>'selection_origin' END,
          'selection_user_override_at_utc', CASE
            WHEN COALESCE((SELECT setting.banking_pay_selection_intent_identity_v1_enabled
                             FROM public.settings_defaults AS setting WHERE setting.id=1),false)
              THEN v_now::text ELSE cancelled_preview_row.row_json->>'selection_user_override_at_utc' END,
          'post_cancel_selection_restored', true,
          'post_cancel_selection_restored_at_utc', v_now::text,
          'post_cancel_selection_pay_batch_id', p_pay_batch_id::text
        )
      ),
      updated_at_utc = v_now
  WHERE cancelled_preview_row.session_id = p_session_id
    AND cancelled_preview_row.session_version = v_session.version
    AND EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(v_result->'patched_row_ids', '[]'::jsonb)) = 'array'
            THEN COALESCE(v_result->'patched_row_ids', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS patched_preview_row_id(value)
      WHERE patched_preview_row_id.value = cancelled_preview_row.id::text
    );

  GET DIAGNOSTICS v_cancelled_row_unselected_count = ROW_COUNT;

  SELECT COALESCE(
           jsonb_agg(to_jsonb(selected_preview_row.id::text) ORDER BY selected_preview_row.row_ordinal, selected_preview_row.id),
           '[]'::jsonb
         ),
         COUNT(*)::integer
  INTO v_preserved_selected_preview_row_ids,
       v_preserved_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_preview_row
  WHERE selected_preview_row.session_id = p_session_id
    AND selected_preview_row.session_version = v_session.version
    AND LOWER(COALESCE(NULLIF(BTRIM(selected_preview_row.section), ''), 'canonical_preview_lines')) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_preview_row.status, ''))) = 'READY'
    AND COALESCE(selected_preview_row.selected, false) IS TRUE
    AND UPPER(BTRIM(COALESCE(selected_preview_row.selection_state, ''))) = 'SELECTED';

  UPDATE public.banking_pay_workbench_sessions AS selection_session
  SET selected_row_count = COALESCE(v_preserved_selected_row_count, 0),
      server_selected_preview_row_ids = COALESCE(v_preserved_selected_preview_row_ids, '[]'::jsonb),
      server_selected_preview_row_ids_provided = true,
      progress_json = COALESCE(selection_session.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_post_cancel_selection_reconcile_at_utc', v_now::text,
          'last_post_cancel_selection_pay_batch_id', p_pay_batch_id::text,
          'last_post_cancel_unselected_row_count', COALESCE(v_cancelled_row_unselected_count, 0),
          'selection_intent_v1', COALESCE(selection_session.progress_json->'selection_intent_v1', '{}'::jsonb)
            || jsonb_build_object(
              'canonical_preview_lines', jsonb_build_object(
                'mode', 'EXPLICIT_INCLUDE',
                'section', 'canonical_preview_lines',
                'identity', 'preview_row_id_with_session_section_candidate_row_key_conflict_identity',
                'updated_at_utc', v_now::text,
                'updated_by_user_id', COALESCE(p_actor_user_id, v_session.actor_user_id)::text,
                'source_selection_mode', 'POST_CANCEL_RECONCILE',
                'source_selection_action', 'RETURN_CANCELLED_ROWS_UNSELECTED',
                'server_selected_preview_row_ids_provided', true,
                'selected_row_count', COALESCE(v_preserved_selected_row_count, 0)
              )
            )
        ),
      progress_counter_version = COALESCE(selection_session.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE selection_session.id = p_session_id;

  DROP TABLE IF EXISTS pg_temp._bpay_cancel_safe_route_candidates;
  CREATE TEMPORARY TABLE pg_temp._bpay_cancel_safe_route_candidates(
    candidate_id uuid PRIMARY KEY,
    direct_current boolean NOT NULL DEFAULT false,
    currentness_reason text NULL,
    repair_job_id uuid NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp._bpay_cancel_safe_route_candidates(candidate_id)
  SELECT DISTINCT candidate_value.value::uuid
  FROM jsonb_array_elements_text(
    CASE WHEN jsonb_typeof(v_result->'affected_candidate_ids')='array'
      THEN v_result->'affected_candidate_ids' ELSE '[]'::jsonb END
  ) AS candidate_value(value)
  WHERE candidate_value.value
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ORDER BY candidate_value.value::uuid;

  -- The fast direct branch does not recalculate economics. It asks the
  -- existing certified publisher to reconstruct the preview byte-for-byte
  -- from the already-current bounded source, then proves the physical rows.
  -- Unsupported authority kinds fail closed to one canonical repair owner.
  FOR v_candidate_id IN
    SELECT route_candidate.candidate_id
    FROM pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
    ORDER BY route_candidate.candidate_id
  LOOP
    PERFORM pg_advisory_xact_lock(
      hashtextextended(public._pay_workbench_candidate_serial_key(v_candidate_id),24062027)
    );

    SELECT scope_row.* INTO v_scope
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id=p_session_id
      AND scope_row.candidate_id=v_candidate_id
    FOR UPDATE;
    SELECT COALESCE(original_authority.attestation,'{}'::jsonb)
    INTO v_attestation
    FROM pg_temp._bpay_cancel_safe_original_authority AS original_authority
    WHERE original_authority.candidate_id=v_candidate_id;
    v_attestation:=COALESCE(v_attestation,'{}'::jsonb);
    v_republication_result:='{}'::jsonb;

    IF v_attestation->>'attestation_version'='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
       AND v_attestation->>'contract_version'='3'
       AND v_attestation->>'semantic_contract_version'='READY_TO_PAY_SEMANTIC_V2'
       AND v_attestation->>'authority_kind'='BOUNDED_FULL_SOURCE_BUILD'
       AND COALESCE(v_attestation->>'economic_build_id','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND COALESCE(v_attestation->>'source_build_run_id','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND COALESCE(v_attestation->>'completion_job_id','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND COALESCE(v_attestation->>'source_change_seq','')~'^[0-9]{1,18}$'
       AND COALESCE(v_attestation->>'session_version','')~'^[1-9][0-9]{0,18}$'
       AND (v_attestation->>'session_version')::bigint=v_session.version THEN
      BEGIN
        v_republication_result:=private.pay_workbench_publish_certified_source_preview_v1(
          p_session_id,v_candidate_id,
          (v_attestation->>'economic_build_id')::uuid,
          (v_attestation->>'source_build_run_id')::uuid,
          (v_attestation->>'source_change_seq')::bigint,
          (v_attestation->>'session_version')::bigint,
          (v_attestation->>'completion_job_id')::uuid,
          -- This branch is intentionally restricted to an already-certified
          -- BOUNDED_FULL_SOURCE_BUILD.  Republish its complete retained source
          -- as candidate-wide authority even where the historical request that
          -- escalated to that full build was originally labelled TARGETED.
          -- Reusing that stale request label would make the publisher demand a
          -- targeted-scope certificate that is irrelevant to the completed
          -- full-candidate source and can leave one public row DIRTY.
          'CANDIDATE_FULL_LIVE',
          '[]'::jsonb,'[]'::jsonb,
          jsonb_build_object(
            'contract_version',3,
            'semantic_contract_version','READY_TO_PAY_SEMANTIC_V2',
            'authority_kind','BOUNDED_FULL_SOURCE_BUILD',
            'invocation_kind','DUPLICATE_REPLAY_REPAIR',
            'final_state',CASE WHEN COALESCE((v_attestation->>'source_row_count')::integer,0)=0
              THEN 'SOURCE_EMPTY' ELSE 'READY' END
          )
        );
      EXCEPTION WHEN OTHERS THEN
        v_republication_result:=jsonb_build_object(
          'ok',false,'code','POST_CANCEL_EXACT_REPUBLICATION_REJECTED',
          'sqlstate',SQLSTATE
        );
      END;
    END IF;

    -- The certified publisher owns physical source/preview parity and its V3
    -- attestation; the caller owns the session lifecycle transition.  Mirror
    -- the established terminal-completion contract only after the publisher
    -- has proved the retained full source exactly, then recompute candidate
    -- state before the independent physical-currentness fence below.
    IF COALESCE((v_republication_result->>'ok')::boolean,false)
       AND COALESCE((v_republication_result->>'parity_complete')::boolean,false) THEN
      UPDATE public.banking_pay_workbench_session_scope AS republished_scope
      SET status=CASE
            WHEN COALESCE((v_republication_result->>'source_row_count')::integer,0)=0
              THEN 'SOURCE_EMPTY' ELSE 'MATERIALISED' END,
          seeded=true,
          dirty=false,
          pending_job_id=NULL::uuid,
          error_json=NULL::jsonb,
          updated_at_utc=v_now
      WHERE republished_scope.session_id=p_session_id
        AND republished_scope.candidate_id=v_candidate_id;

      v_candidate_state_result:=public.pay_workbench_delta_update_candidate_state_v1(
        p_session_id,
        v_candidate_id,
        (v_attestation->>'source_build_run_id')::uuid,
        jsonb_build_object(
          'context','DELTA_REFRESH',
          'source_change_seq',(v_attestation->>'source_change_seq')::bigint,
          'session_version',(v_attestation->>'session_version')::bigint,
          'authority_kind','BOUNDED_FULL_SOURCE_BUILD',
          'invocation_kind','POST_CANCEL_EXACT_REPUBLICATION'
        )
      );

      PERFORM public.pay_workbench_session_recompute_progress_counters(
        p_session_id,true,'POST_CANCEL_EXACT_REPUBLICATION',true
      );
    END IF;

    EXECUTE 'SELECT private.pay_workbench_candidate_physical_currentness_page_v1($1,$2,$3,$4)'
      INTO v_physical_currentness
      USING p_session_id,ARRAY[v_candidate_id],'TERMINAL_CURRENT',
        jsonb_build_object('contract_version',1,'allow_active_owner',false);
    v_candidate_currentness:=COALESCE(v_physical_currentness->'candidate_results'->0,'{}'::jsonb);
    v_physical_currentness_results:=v_physical_currentness_results||jsonb_build_array(
      v_candidate_currentness||jsonb_build_object(
        'republication',v_republication_result,
        'candidate_state_adoption',v_candidate_state_result
      )
    );

    IF COALESCE((v_candidate_currentness->>'terminal_current')::boolean,false) THEN
      UPDATE pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
      SET direct_current=true,currentness_reason=v_candidate_currentness->>'currentness_reason'
      WHERE route_candidate.candidate_id=v_candidate_id;
      v_direct_current_count:=v_direct_current_count+1;
      v_direct_current_candidate_ids:=v_direct_current_candidate_ids||jsonb_build_array(v_candidate_id::text);
    ELSE
      UPDATE pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
      SET currentness_reason=v_candidate_currentness->>'currentness_reason'
      WHERE route_candidate.candidate_id=v_candidate_id;
    END IF;
  END LOOP;

  -- The Worker may supply these identifiers, but the cancelled frozen batch is
  -- the fail-closed authority. Reading its retained (now voided) items makes the
  -- race guard independent of optional response fields.
  WITH finance_case_scope AS (
    SELECT batch_item.finance_case_id
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = batch_item.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id = p_pay_batch_id
      AND batch_item.finance_case_id IS NOT NULL

    UNION ALL

    SELECT raw_value.value_text::uuid
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(p_options_json->'changed_finance_case_ids') = 'array'
          THEN p_options_json->'changed_finance_case_ids'
        ELSE '[]'::jsonb
      END
    ) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

    UNION ALL

    SELECT raw_value.value_text::uuid
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(p_options_json#>'{cancellation_result,changed_scope_json,changed_finance_case_ids}') = 'array'
          THEN p_options_json#>'{cancellation_result,changed_scope_json,changed_finance_case_ids}'
        ELSE '[]'::jsonb
      END
    ) AS raw_value(value_text)
    WHERE raw_value.value_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  SELECT COALESCE(
    array_agg(DISTINCT finance_case_scope.finance_case_id ORDER BY finance_case_scope.finance_case_id),
    ARRAY[]::uuid[]
  )
  INTO v_changed_finance_case_ids
  FROM finance_case_scope
  WHERE finance_case_scope.finance_case_id IS NOT NULL;

  -- Component restoration and reservation release enqueue finance-case dirty
  -- work in the cancellation transaction. If allowed to fan out afterwards it
  -- can narrow the scope to one linked timesheet and overwrite the correct
  -- candidate-wide recovery allocation. Only still-QUEUED jobs for finance
  -- cases frozen into this cancelled batch are superseded. A supersession is a
  -- successful terminal orchestration result, not a processing failure. Keep
  -- the reason as immutable payload audit evidence while the replacement full
  -- candidate refresh remains responsible for rebuilding the live preview.
  -- RUNNING jobs and all unrelated finance cases are deliberately outside this
  -- update.
  -- Do not terminalise queued finance/targeted work before canonical owner
  -- election.  The enqueue owner now decides whether existing work is covered,
  -- coalesced or genuinely superseded; RUNNING work is never killed here.
  v_superseded_finance_dirty_job_count := 0;

  FOR v_candidate_id IN
    SELECT route_candidate.candidate_id
    FROM pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
    WHERE route_candidate.direct_current IS NOT TRUE
    ORDER BY route_candidate.candidate_id
  LOOP
    v_superseded_targeted_job_chunk_count := 0;
    v_post_commit_authority:=COALESCE(
      p_options_json->'post_commit_authorities_v3'->v_candidate_id::text,'{}'::jsonb
    );
    v_preceding_scope_proven:=
      COALESCE(v_post_commit_authority->>'contract_version','')
        ='POST_FINANCIAL_TERMINAL_AUTHORITY_V3'
      AND COALESCE((v_post_commit_authority->>'admitted')::boolean,false)
      AND COALESCE(v_post_commit_authority->>'candidate_id','')=v_candidate_id::text
      AND COALESCE(v_post_commit_authority->>'dirty_generation','') ~ '^[0-9]{1,18}$'
      AND COALESCE(v_post_commit_authority->>'scope_change_tx_token','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    SELECT COALESCE(
      jsonb_agg(DISTINCT batch_item.timesheet_id::text ORDER BY batch_item.timesheet_id::text),
      '[]'::jsonb
    )
    INTO v_targeted_timesheet_ids
    FROM public.pay_batch_items AS batch_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id=batch_item.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id=p_pay_batch_id
      AND batch_candidate.candidate_id=v_candidate_id
      AND batch_item.timesheet_id IS NOT NULL;

    v_requested_refresh_scope:=CASE
      WHEN jsonb_array_length(COALESCE(v_targeted_timesheet_ids,'[]'::jsonb))>0
        THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END;

    v_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => v_session.source_snapshot_run_id,
      p_candidate_id => v_candidate_id,
      p_reason => 'POST_DRAFT_CANCEL_CURRENT_AUTHORITY_REFRESH',
      p_actor_user_id => COALESCE(p_actor_user_id, v_session.actor_user_id),
      p_payload_json => jsonb_build_object(
        'session_id', p_session_id::text,
        'source_session_id', p_session_id::text,
        'source_snapshot_run_id', v_session.source_snapshot_run_id::text,
        'snapshot_run_id', v_session.source_snapshot_run_id::text,
        'session_version', v_session.version,
        'session_signature', v_session.session_signature,
        'operation_type', v_operation_type,
        'pay_batch_id', p_pay_batch_id::text,
        'enqueue_origin', 'PAYMENT_CANCEL_CANONICAL_REFRESH_V3',
        'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids,'[]'::jsonb),
        'targeted_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids,'[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_targeted_timesheet_ids,'[]'::jsonb),
        'linked_timesheet_ids_requested', COALESCE(v_targeted_timesheet_ids,'[]'::jsonb),
        'refresh_scope_kind', v_requested_refresh_scope,
        'pay_channel_scope', 'ALL',
        'projection_class', 'POST_DRAFT_CANCEL_CURRENT_AUTHORITY',
        'fallback_reason', 'CERTIFIED_CANCELLATION_REVERSION_REJECTED',
        'canonical_route_ladder_required', true,
        'source_publication_baseline_required', true,
        'required_physical_publication_contract_version', 1,
        'bounded_scope_state_precedes_job',v_preceding_scope_proven,
        'scope_change_tx_token',CASE WHEN v_preceding_scope_proven
          THEN v_post_commit_authority->>'scope_change_tx_token' ELSE NULL END,
        'scope_change_generation',CASE WHEN v_preceding_scope_proven
          THEN (v_post_commit_authority->>'dirty_generation')::bigint ELSE NULL END,
        'correction_request_id',p_options_json->>'correction_request_id',
        'correction_operation_id',v_post_commit_authority->>'operation_id',
        'correction_held_dirty_job_id',v_post_commit_authority->>'held_dirty_job_id',
        'post_commit_authority_digest',v_post_commit_authority->>'authority_digest',
        'post_cancel_patch_digest',v_post_cancel_patch_digest,
        'superseded_finance_dirty_job_count', v_superseded_finance_dirty_job_count,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    );

    IF COALESCE((v_enqueue_result->>'ok')::boolean,true) IS NOT TRUE
       OR (
         COALESCE(v_enqueue_result->>'job_id','')
           !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         AND UPPER(BTRIM(COALESCE(v_enqueue_result->>'owner_resolution',''))) NOT IN (
           'ACTIVE_CURRENT_OWNER_COVERS_REQUEST','COMPLETE_CURRENT_AUTHORITY','STALE_INCOMING_REQUEST'
         )
         AND COALESCE((v_enqueue_result->>'coalesced')::boolean,false) IS NOT TRUE
       ) THEN
      RAISE EXCEPTION 'PAYMENT_CANCEL_FULL_REFRESH_JOB_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAYMENT_CANCEL_FULL_REFRESH_JOB_INVALID',
                'session_id', p_session_id::text,
                'candidate_id', v_candidate_id::text,
                'pay_batch_id', p_pay_batch_id::text,
                'enqueue_result', v_enqueue_result
              )::text;
    END IF;

    EXECUTE 'SELECT private.pay_workbench_candidate_physical_currentness_page_v1($1,$2,$3,$4)'
      INTO v_physical_currentness
      USING p_session_id,ARRAY[v_candidate_id],'TERMINAL_CURRENT',
        jsonb_build_object('contract_version',1,'allow_active_owner',true);
    v_candidate_currentness:=COALESCE(v_physical_currentness->'candidate_results'->0,'{}'::jsonb);
    v_physical_currentness_results:=v_physical_currentness_results||jsonb_build_array(
      v_candidate_currentness||jsonb_build_object('enqueue_result',v_enqueue_result)
    );

    IF COALESCE((v_candidate_currentness->>'current_or_active_owner')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'PAYMENT_CANCEL_CURRENT_OR_REPAIR_OWNER_REQUIRED'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','PAYMENT_CANCEL_CURRENT_OR_REPAIR_OWNER_REQUIRED',
          'session_id',p_session_id,'candidate_id',v_candidate_id,
          'pay_batch_id',p_pay_batch_id,
          'currentness_reason',v_candidate_currentness->>'currentness_reason'
        )::text;
    END IF;

    IF COALESCE(v_candidate_currentness->>'active_owner_job_id','')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_job_id:=(v_candidate_currentness->>'active_owner_job_id')::uuid;
      UPDATE pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
      SET repair_job_id=v_job_id,currentness_reason=v_candidate_currentness->>'currentness_reason'
      WHERE route_candidate.candidate_id=v_candidate_id;
      v_repair_owner_count:=v_repair_owner_count+1;
      v_full_refresh_job_ids := v_full_refresh_job_ids || jsonb_build_array(v_job_id::text);
      v_full_refresh_count := v_full_refresh_count + 1;
      IF v_requested_refresh_scope='CANDIDATE_FULL_LIVE' THEN
        v_candidate_full_refresh_count:=v_candidate_full_refresh_count+1;
      END IF;
    ELSIF COALESCE((v_candidate_currentness->>'terminal_current')::boolean,false) THEN
      UPDATE pg_temp._bpay_cancel_safe_route_candidates AS route_candidate
      SET direct_current=true,currentness_reason=v_candidate_currentness->>'currentness_reason'
      WHERE route_candidate.candidate_id=v_candidate_id;
      v_direct_current_count:=v_direct_current_count+1;
      v_direct_current_candidate_ids:=v_direct_current_candidate_ids||jsonb_build_array(v_candidate_id::text);
    END IF;
  END LOOP;

  v_progress_recompute:=public.pay_workbench_session_recompute_progress_counters(
    p_session_id,true,'POST_CANCEL_PHYSICAL_CURRENTNESS_FINALISE',true
  );

  RETURN v_result || jsonb_build_object(
    'targeted_refresh_enqueued', v_full_refresh_count > 0,
    'targeted_refresh_enqueued_count', v_full_refresh_count,
    'full_candidate_refresh_enqueued', v_candidate_full_refresh_count > 0,
    'full_candidate_refresh_enqueued_count', v_candidate_full_refresh_count,
    'full_candidate_refresh_job_ids', v_full_refresh_job_ids,
    'superseded_targeted_refresh_job_count', v_superseded_targeted_job_count,
    'superseded_finance_dirty_job_count', v_superseded_finance_dirty_job_count,
    'changed_finance_case_count', COALESCE(array_length(v_changed_finance_case_ids, 1), 0),
    'cancelled_row_unselected_count', COALESCE(v_cancelled_row_unselected_count, 0),
    'server_selected_preview_row_ids', COALESCE(v_preserved_selected_preview_row_ids, '[]'::jsonb),
    'server_selected_preview_row_ids_provided', true,
    'selected_row_count', COALESCE(v_preserved_selected_row_count, 0),
    'post_cancel_patch_digest',v_post_cancel_patch_digest,
    'physical_currentness_checked',true,
    'physical_currentness_proven',v_direct_current_count=(SELECT COUNT(*) FROM pg_temp._bpay_cancel_safe_route_candidates),
    'direct_current_patch_applied',v_direct_current_count>0,
    'direct_current_candidate_count',v_direct_current_count,
    'direct_current_candidate_ids',v_direct_current_candidate_ids,
    'repair_job_created_or_reused',v_repair_owner_count>0,
    'repair_owner_count',v_repair_owner_count,
    'physical_currentness_results',v_physical_currentness_results,
    'progress_recompute',v_progress_recompute,
    'final_scope_status',CASE
      WHEN v_repair_owner_count>0 THEN 'SOURCE_BUILD_PENDING'
      WHEN v_direct_current_count>0 THEN 'MATERIALISED'
      ELSE 'NOT_REQUIRED' END,
    'nudge_required',v_repair_owner_count>0,
    'refresh_scope_kind', CASE
      WHEN v_candidate_full_refresh_count>0 AND v_candidate_full_refresh_count=v_full_refresh_count THEN 'CANDIDATE_FULL_LIVE'
      WHEN v_full_refresh_count>0 THEN 'CANONICAL_ROUTE_LADDER'
      ELSE NULL::text END,
    'source_session_preserved', true,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
    'policy_x_checked', true
  );
END;
$function$;

-- pay_workbench_patch_preview_after_batch_mutation(uuid,uuid,text,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_patch_preview_after_batch_mutation(p_session_id uuid, p_pay_batch_id uuid, p_operation_type text, p_actor_user_id uuid DEFAULT NULL::uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_options_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_options_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_options_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_operation_type text := UPPER(BTRIM(COALESCE(p_operation_type, '')));
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_patch_enabled boolean := true;
  v_affected_candidate_count integer := 0;
  v_affected_row_count integer := 0;
  v_patched_row_count integer := 0;
  v_targeted_refresh_enqueued_count integer := 0;
  v_complex_candidate_count integer := 0;
  v_missing_key_candidate_count integer := 0;
  v_complex_refresh_candidate_ids jsonb := '[]'::jsonb;
  v_missing_key_candidate_ids jsonb := '[]'::jsonb;
  v_refresh_candidate_row record;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_enqueue_job_id_text text := NULL::text;
  v_enqueue_job_id uuid := NULL::uuid;
  v_enqueue_job_type text := NULL::text;
  v_enqueue_job_status text := NULL::text;
  v_enqueue_source_build_run_id_text text := NULL::text;
  v_session_preview_row_count integer := 0;
  v_session_selected_row_count integer := 0;
  v_session_section_counts_json jsonb := '{}'::jsonb;
  v_session_candidate_samples_json jsonb := '[]'::jsonb;
  v_affected_candidate_ids_json jsonb := '[]'::jsonb;
  v_patched_row_ids_json jsonb := '[]'::jsonb;
  v_affected_timesheet_ids_json jsonb := '[]'::jsonb;
  v_affected_economic_keys_json jsonb := '[]'::jsonb;
  v_targeted_refresh_candidate_ids_json jsonb := '[]'::jsonb;
  v_candidate_state_results_json jsonb := '[]'::jsonb;
  v_candidate_state_result jsonb := '{}'::jsonb;
  v_candidate_state_candidate_id uuid := NULL::uuid;
  v_patch_projection_run_id uuid := gen_random_uuid();
  v_selected_before_count integer := 0;
  v_selected_after_count integer := 0;
  v_ready_before_count integer := 0;
  v_ready_after_count integer := 0;
  v_selected_count_delta integer := 0;
  v_ready_count_delta integer := 0;
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_is_cancel_delete boolean := false;
  v_supplied_item_scope_count integer := 0;
  v_exact_item_scope_count integer := 0;
  v_invalid_item_scope_count integer := 0;
  v_out_of_batch_item_scope_count integer := 0;
  v_has_specific_scope_selector boolean := false;
  v_whole_batch_scope_proven boolean := false;
  v_cancel_delete_total_item_count integer := 0;
  v_cancel_delete_voided_item_count integer := 0;
  v_scope_resolution_mode text := NULL::text;
  v_scope_diagnostic_json jsonb := '{}'::jsonb;
  v_defer_complex_enqueue boolean := lower(btrim(COALESCE(v_options_json->>'defer_complex_enqueue','false')))
    IN ('true','t','1','yes','y','on');
  v_draft_adoption_result jsonb := '{}'::jsonb;
  v_draft_operation_id uuid := NULL::uuid;
  v_post_cancel_patch_digest text := NULL::text;
  v_active_noncurrent_row_count_after_patch integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL OR p_pay_batch_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'patch_applied', false,
      'replacement_session_required', false,
      'fallback_required', true,
      'fallback_reason', 'SESSION_ID_AND_PAY_BATCH_ID_REQUIRED',
      'affected_candidate_count', 0,
      'affected_row_count', 0,
      'patched_row_count', 0,
      'targeted_refresh_enqueued_count', 0,
      'complex_refresh_candidate_ids', '[]'::jsonb
    );
  END IF;

  IF v_operation_type NOT IN ('DRAFT_CREATE', 'DRAFT_DELETE', 'DRAFT_CANCEL', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE') THEN
    RETURN jsonb_build_object(
      'ok', false,
      'patch_applied', false,
      'replacement_session_required', false,
      'fallback_required', true,
      'fallback_reason', 'UNSUPPORTED_BATCH_MUTATION_OPERATION',
      'operation_type', v_operation_type,
      'affected_candidate_count', 0,
      'affected_row_count', 0,
      'patched_row_count', 0,
      'targeted_refresh_enqueued_count', 0,
      'complex_refresh_candidate_ids', '[]'::jsonb
    );
  END IF;

  v_is_cancel_delete := v_operation_type IN ('DRAFT_DELETE', 'DRAFT_CANCEL');

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
    AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
    AND session_row.discarded_at_utc IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'patch_applied', false,
      'replacement_session_required', false,
      'fallback_required', true,
      'fallback_reason', 'WORKBENCH_SESSION_NOT_OPEN',
      'affected_candidate_count', 0,
      'affected_row_count', 0,
      'patched_row_count', 0,
      'targeted_refresh_enqueued_count', 0,
      'complex_refresh_candidate_ids', '[]'::jsonb
    );
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'patch_applied', false,
      'replacement_session_required', false,
      'fallback_required', true,
      'fallback_reason', 'PAY_BATCH_NOT_FOUND',
      'affected_candidate_count', 0,
      'affected_row_count', 0,
      'patched_row_count', 0,
      'targeted_refresh_enqueued_count', 0,
      'complex_refresh_candidate_ids', '[]'::jsonb
    );
  END IF;

  IF v_batch_row.source_workbench_session_id IS NOT NULL
     AND v_batch_row.source_workbench_session_id IS DISTINCT FROM p_session_id
     AND lower(BTRIM(COALESCE(v_options_json->>'allow_cross_session_patch', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RETURN jsonb_build_object(
      'ok', false,
      'patch_applied', false,
      'replacement_session_required', false,
      'fallback_required', true,
      'fallback_reason', 'PAY_BATCH_SESSION_MISMATCH',
      'source_workbench_session_id', v_batch_row.source_workbench_session_id::text,
      'affected_candidate_count', 0,
      'affected_row_count', 0,
      'patched_row_count', 0,
      'targeted_refresh_enqueued_count', 0,
      'complex_refresh_candidate_ids', '[]'::jsonb
    );
  END IF;

  SELECT lower(BTRIM(COALESCE(to_jsonb(settings_row)->>'banking_pay_workbench_patch_after_batch_mutation_enabled', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on')
  INTO v_patch_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1
  LIMIT 1;

  v_patch_enabled := COALESCE(v_patch_enabled, true);

  IF v_patch_enabled IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'patch_applied', false,
      'replacement_session_required', false,
      'fallback_required', true,
      'fallback_reason', 'PATCH_AFTER_BATCH_MUTATION_DISABLED',
      'affected_candidate_count', 0,
      'affected_row_count', 0,
      'patched_row_count', 0,
      'targeted_refresh_enqueued_count', 0,
      'complex_refresh_candidate_ids', '[]'::jsonb
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_batch_mutation_supplied_item_ids;
  CREATE TEMP TABLE _bpay_batch_mutation_supplied_item_ids ON COMMIT DROP AS
  WITH option_item_arrays(path_name, value_json) AS (
    VALUES
      ('changed_pay_batch_item_ids', v_options_json->'changed_pay_batch_item_ids'),
      ('cancelled_pay_batch_item_ids', v_options_json->'cancelled_pay_batch_item_ids'),
      ('voided_pay_batch_item_ids', v_options_json->'voided_pay_batch_item_ids'),
      ('pay_batch_item_ids', v_options_json->'pay_batch_item_ids'),
      ('selected_pay_batch_item_ids', v_options_json->'selected_pay_batch_item_ids'),
      ('expected_pay_batch_item_ids', v_options_json->'expected_pay_batch_item_ids'),
      ('cancellation_result.changed_pay_batch_item_ids', v_options_json#>'{cancellation_result,changed_pay_batch_item_ids}'),
      ('cancellation_result.cancelled_pay_batch_item_ids', v_options_json#>'{cancellation_result,cancelled_pay_batch_item_ids}'),
      ('cancellation_result.voided_pay_batch_item_ids', v_options_json#>'{cancellation_result,voided_pay_batch_item_ids}'),
      ('cancellation_result.process_result.changed_pay_batch_item_ids', v_options_json#>'{cancellation_result,process_result,changed_pay_batch_item_ids}'),
      ('cancellation_result.process_result.changed_scope_json.changed_pay_batch_item_ids', v_options_json#>'{cancellation_result,process_result,changed_scope_json,changed_pay_batch_item_ids}'),
      ('cancellation_result.changed_scope_json.changed_pay_batch_item_ids', v_options_json#>'{cancellation_result,changed_scope_json,changed_pay_batch_item_ids}'),
      ('process_result.changed_pay_batch_item_ids', v_options_json#>'{process_result,changed_pay_batch_item_ids}'),
      ('process_result.changed_scope_json.changed_pay_batch_item_ids', v_options_json#>'{process_result,changed_scope_json,changed_pay_batch_item_ids}'),
      ('result.changed_pay_batch_item_ids', v_options_json#>'{result,changed_pay_batch_item_ids}'),
      ('result.changed_scope_json.changed_pay_batch_item_ids', v_options_json#>'{result,changed_scope_json,changed_pay_batch_item_ids}'),
      ('result.process_result.changed_pay_batch_item_ids', v_options_json#>'{result,process_result,changed_pay_batch_item_ids}'),
      ('result.process_result.changed_scope_json.changed_pay_batch_item_ids', v_options_json#>'{result,process_result,changed_scope_json,changed_pay_batch_item_ids}'),
      ('selection_json.pay_batch_item_ids', v_options_json#>'{selection_json,pay_batch_item_ids}'),
      ('selection_json.selected_pay_batch_item_ids', v_options_json#>'{selection_json,selected_pay_batch_item_ids}'),
      ('selection_json.expected_pay_batch_item_ids', v_options_json#>'{selection_json,expected_pay_batch_item_ids}'),
      ('confirmation_json.pay_batch_item_ids', v_options_json#>'{confirmation_json,pay_batch_item_ids}'),
      ('confirmation_json.selected_pay_batch_item_ids', v_options_json#>'{confirmation_json,selected_pay_batch_item_ids}'),
      ('confirmation_json.expected_pay_batch_item_ids', v_options_json#>'{confirmation_json,expected_pay_batch_item_ids}')
  ), raw_item_values AS (
    SELECT option_item_arrays.path_name,
           item_array_values.raw_value
    FROM option_item_arrays
    CROSS JOIN LATERAL jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(option_item_arrays.value_json) = 'array' THEN option_item_arrays.value_json
        ELSE '[]'::jsonb
      END
    ) AS item_array_values(raw_value)
    UNION ALL
    SELECT option_item_arrays.path_name,
           TRIM(BOTH '"' FROM option_item_arrays.value_json::text) AS raw_value
    FROM option_item_arrays
    WHERE jsonb_typeof(option_item_arrays.value_json) = 'string'
  ), cleaned_item_values AS (
    SELECT raw_item_values.path_name,
           NULLIF(BTRIM(COALESCE(raw_item_values.raw_value, '')), '') AS clean_value
    FROM raw_item_values
  )
  SELECT DISTINCT
    cleaned_item_values.path_name,
    cleaned_item_values.clean_value AS raw_pay_batch_item_id,
    CASE
      WHEN cleaned_item_values.clean_value ~* v_uuid_regex THEN cleaned_item_values.clean_value::uuid
      ELSE NULL::uuid
    END AS pay_batch_item_id
  FROM cleaned_item_values
  WHERE cleaned_item_values.clean_value IS NOT NULL;

  SELECT COUNT(DISTINCT supplied_item.pay_batch_item_id)::integer
  INTO v_supplied_item_scope_count
  FROM pg_temp._bpay_batch_mutation_supplied_item_ids AS supplied_item
  WHERE supplied_item.pay_batch_item_id IS NOT NULL;

  SELECT COUNT(DISTINCT supplied_item.raw_pay_batch_item_id)::integer
  INTO v_invalid_item_scope_count
  FROM pg_temp._bpay_batch_mutation_supplied_item_ids AS supplied_item
  WHERE supplied_item.pay_batch_item_id IS NULL;

  DROP TABLE IF EXISTS pg_temp._bpay_batch_mutation_exact_item_ids;
  CREATE TEMP TABLE _bpay_batch_mutation_exact_item_ids ON COMMIT DROP AS
  SELECT DISTINCT supplied_item.pay_batch_item_id
  FROM pg_temp._bpay_batch_mutation_supplied_item_ids AS supplied_item
  JOIN public.pay_batch_items AS exact_batch_item
    ON exact_batch_item.id = supplied_item.pay_batch_item_id
  JOIN public.pay_batch_candidates AS exact_batch_candidate
    ON exact_batch_candidate.id = exact_batch_item.pay_batch_candidate_id
  WHERE exact_batch_candidate.pay_batch_id = p_pay_batch_id
    AND supplied_item.pay_batch_item_id IS NOT NULL;

  SELECT COUNT(*)::integer
  INTO v_exact_item_scope_count
  FROM pg_temp._bpay_batch_mutation_exact_item_ids AS exact_item;

  v_out_of_batch_item_scope_count := GREATEST(COALESCE(v_supplied_item_scope_count, 0) - COALESCE(v_exact_item_scope_count, 0), 0);

  SELECT EXISTS (
    WITH option_scope_objects(path_name, object_json) AS (
      VALUES
        ('root', v_options_json),
        ('selection_json', v_options_json->'selection_json'),
        ('confirmation_json', v_options_json->'confirmation_json'),
        ('cancellation_result', v_options_json->'cancellation_result'),
        ('process_result', v_options_json->'process_result'),
        ('result', v_options_json->'result')
    )
    SELECT 1
    FROM option_scope_objects
    CROSS JOIN LATERAL jsonb_each(
      CASE
        WHEN jsonb_typeof(option_scope_objects.object_json) = 'object' THEN option_scope_objects.object_json
        ELSE '{}'::jsonb
      END
    ) AS scope_entry(selector_key, selector_value)
    WHERE scope_entry.selector_key = ANY(ARRAY[
      'pay_batch_candidate_id',
      'pay_batch_candidate_ids',
      'payBatchCandidateId',
      'payBatchCandidateIds',
      'pay_bank_transfer_id',
      'pay_bank_transfer_ids',
      'payBankTransferId',
      'payBankTransferIds',
      'pay_batch_item_id',
      'pay_batch_item_ids',
      'payBatchItemId',
      'payBatchItemIds',
      'selected_pay_batch_item_ids',
      'expected_pay_batch_item_ids',
      'candidate_id',
      'candidate_ids',
      'candidateId',
      'candidateIds',
      'umbrella_id',
      'umbrella_ids',
      'umbrellaId',
      'umbrellaIds',
      'transfer_group_key',
      'transfer_group_keys',
      'transferGroupKey',
      'transferGroupKeys',
      'finance_case_id',
      'finance_case_ids',
      'financeCaseId',
      'financeCaseIds',
      'finance_component_id',
      'finance_component_ids',
      'financeComponentId',
      'financeComponentIds',
      'reservation_id',
      'reservation_ids',
      'reservationId',
      'reservationIds',
      'item_type',
      'item_types',
      'selected_scope_keys',
      'selectedScopeKeys',
      'selected_row_keys',
      'selectedRowKeys',
      'current_page_row_keys',
      'currentPageRowKeys'
    ]::text[])
      AND (
        (jsonb_typeof(scope_entry.selector_value) = 'array' AND jsonb_array_length(scope_entry.selector_value) > 0)
        OR (jsonb_typeof(scope_entry.selector_value) = 'string' AND NULLIF(TRIM(BOTH '"' FROM scope_entry.selector_value::text), '') IS NOT NULL)
        OR jsonb_typeof(scope_entry.selector_value) IN ('number', 'boolean', 'object')
      )
  )
  INTO v_has_specific_scope_selector;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE COALESCE(batch_item.is_voided, false) IS TRUE)::integer
  INTO v_cancel_delete_total_item_count,
       v_cancel_delete_voided_item_count
  FROM public.pay_batch_candidates AS batch_candidate
  JOIN public.pay_batch_items AS batch_item
    ON batch_item.pay_batch_candidate_id = batch_candidate.id
  WHERE batch_candidate.pay_batch_id = p_pay_batch_id;

  WITH scope_values(raw_value) AS (
    VALUES
      (v_options_json->>'scope_type'),
      (v_options_json->>'scopeType'),
      (v_options_json->>'scope'),
      (v_options_json->>'cancel_scope'),
      (v_options_json->>'cancelScope'),
      (v_options_json->>'operation_scope'),
      (v_options_json->>'operationScope'),
      (v_options_json#>>'{selection_json,scope_type}'),
      (v_options_json#>>'{selection_json,scopeType}'),
      (v_options_json#>>'{selection_json,scope}'),
      (v_options_json#>>'{selection_json,cancel_scope}'),
      (v_options_json#>>'{selection_json,cancelScope}'),
      (v_options_json#>>'{selection_json,operation_scope}'),
      (v_options_json#>>'{selection_json,operationScope}'),
      (v_options_json#>>'{confirmation_json,scope_type}'),
      (v_options_json#>>'{confirmation_json,scopeType}'),
      (v_options_json#>>'{confirmation_json,scope}'),
      (v_options_json#>>'{confirmation_json,cancel_scope}'),
      (v_options_json#>>'{confirmation_json,cancelScope}'),
      (v_options_json#>>'{confirmation_json,operation_scope}'),
      (v_options_json#>>'{confirmation_json,operationScope}'),
      (v_options_json#>>'{cancellation_result,scope_type}'),
      (v_options_json#>>'{cancellation_result,scopeType}'),
      (v_options_json#>>'{cancellation_result,scope}'),
      (v_options_json#>>'{cancellation_result,cancel_scope}'),
      (v_options_json#>>'{cancellation_result,cancelScope}'),
      (v_options_json#>>'{cancellation_result,operation_scope}'),
      (v_options_json#>>'{cancellation_result,operationScope}')
  ), whole_batch_flags(raw_value) AS (
    VALUES
      (v_options_json->>'whole_batch'),
      (v_options_json->>'wholeBatch'),
      (v_options_json->>'all_items'),
      (v_options_json->>'allItems'),
      (v_options_json->>'delete_entire_batch'),
      (v_options_json->>'deleteEntireBatch'),
      (v_options_json->>'whole_batch_overview_action'),
      (v_options_json->>'wholeBatchOverviewAction'),
      (v_options_json#>>'{selection_json,whole_batch}'),
      (v_options_json#>>'{selection_json,wholeBatch}'),
      (v_options_json#>>'{selection_json,all_items}'),
      (v_options_json#>>'{selection_json,allItems}'),
      (v_options_json#>>'{selection_json,delete_entire_batch}'),
      (v_options_json#>>'{selection_json,deleteEntireBatch}'),
      (v_options_json#>>'{selection_json,whole_batch_overview_action}'),
      (v_options_json#>>'{selection_json,wholeBatchOverviewAction}'),
      (v_options_json#>>'{confirmation_json,whole_batch}'),
      (v_options_json#>>'{confirmation_json,wholeBatch}'),
      (v_options_json#>>'{confirmation_json,all_items}'),
      (v_options_json#>>'{confirmation_json,allItems}'),
      (v_options_json#>>'{confirmation_json,delete_entire_batch}'),
      (v_options_json#>>'{confirmation_json,deleteEntireBatch}'),
      (v_options_json#>>'{confirmation_json,whole_batch_overview_action}'),
      (v_options_json#>>'{confirmation_json,wholeBatchOverviewAction}'),
      (v_options_json#>>'{cancellation_result,whole_batch}'),
      (v_options_json#>>'{cancellation_result,wholeBatch}'),
      (v_options_json#>>'{cancellation_result,all_items}'),
      (v_options_json#>>'{cancellation_result,allItems}'),
      (v_options_json#>>'{cancellation_result,delete_entire_batch}'),
      (v_options_json#>>'{cancellation_result,deleteEntireBatch}'),
      (v_options_json#>>'{cancellation_result,whole_batch_overview_action}'),
      (v_options_json#>>'{cancellation_result,wholeBatchOverviewAction}')
  )
  SELECT (
    v_is_cancel_delete IS TRUE
    AND COALESCE(v_exact_item_scope_count, 0) = 0
    AND COALESCE(v_has_specific_scope_selector, false) IS NOT TRUE
    AND (
      EXISTS (
        SELECT 1
        FROM scope_values AS scope_value
        WHERE UPPER(BTRIM(COALESCE(scope_value.raw_value, ''))) IN ('BATCH', 'WHOLE_BATCH', 'ALL', 'PAY_BATCH')
      )
      OR EXISTS (
        SELECT 1
        FROM whole_batch_flags AS whole_batch_flag
        WHERE lower(BTRIM(COALESCE(whole_batch_flag.raw_value, ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
    )
  )
  INTO v_whole_batch_scope_proven;

  v_scope_resolution_mode := CASE
    WHEN v_is_cancel_delete IS NOT TRUE THEN 'ACTIVE_NON_VOIDED_ITEMS'
    WHEN COALESCE(v_exact_item_scope_count, 0) > 0 THEN 'EXACT_ITEM_IDS'
    WHEN COALESCE(v_whole_batch_scope_proven, false) IS TRUE THEN 'WHOLE_BATCH_VOIDED_ITEMS'
    ELSE 'UNPROVEN_CANCEL_DELETE_SCOPE'
  END;

  v_scope_diagnostic_json := jsonb_build_object(
    'scope_resolution_mode', v_scope_resolution_mode,
    'operation_type', v_operation_type,
    'supplied_item_scope_count', COALESCE(v_supplied_item_scope_count, 0),
    'exact_item_scope_count', COALESCE(v_exact_item_scope_count, 0),
    'invalid_item_scope_count', COALESCE(v_invalid_item_scope_count, 0),
    'out_of_batch_item_scope_count', COALESCE(v_out_of_batch_item_scope_count, 0),
    'has_specific_scope_selector', COALESCE(v_has_specific_scope_selector, false),
    'whole_batch_scope_proven', COALESCE(v_whole_batch_scope_proven, false),
    'batch_item_count', COALESCE(v_cancel_delete_total_item_count, 0),
    'voided_batch_item_count', COALESCE(v_cancel_delete_voided_item_count, 0)
  );

  IF v_is_cancel_delete IS TRUE
     AND COALESCE(v_supplied_item_scope_count, 0) > 0
     AND (COALESCE(v_invalid_item_scope_count, 0) > 0 OR COALESCE(v_out_of_batch_item_scope_count, 0) > 0) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'patch_applied', false,
      'replacement_session_required', false,
      'fallback_required', true,
      'fallback_reason', 'DRAFT_CANCEL_DELETE_INVALID_OR_OUT_OF_BATCH_ITEM_SCOPE',
      'operation_type', v_operation_type,
      'pay_batch_id', p_pay_batch_id::text,
      'affected_candidate_count', 0,
      'affected_row_count', 0,
      'patched_row_count', 0,
      'targeted_refresh_enqueued_count', 0,
      'complex_refresh_candidate_ids', '[]'::jsonb,
      'scope_resolution_mode', v_scope_resolution_mode,
      'scope_diagnostic', v_scope_diagnostic_json
    );
  END IF;

  IF v_is_cancel_delete IS TRUE
     AND COALESCE(v_exact_item_scope_count, 0) = 0
     AND COALESCE(v_whole_batch_scope_proven, false) IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', false,
      'patch_applied', false,
      'replacement_session_required', false,
      'fallback_required', true,
      'fallback_reason', 'DRAFT_CANCEL_DELETE_ITEM_SCOPE_NOT_PROVEN',
      'operation_type', v_operation_type,
      'pay_batch_id', p_pay_batch_id::text,
      'affected_candidate_count', 0,
      'affected_row_count', 0,
      'patched_row_count', 0,
      'targeted_refresh_enqueued_count', 0,
      'complex_refresh_candidate_ids', '[]'::jsonb,
      'scope_resolution_mode', v_scope_resolution_mode,
      'scope_diagnostic', v_scope_diagnostic_json
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_batch_mutation_keys;
  CREATE TEMP TABLE _bpay_batch_mutation_keys ON COMMIT DROP AS
  SELECT DISTINCT
    batch_candidate.candidate_id,
    COALESCE(
      batch_item.timesheet_id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) = 'OVERPAYMENT_RECOVERY'
         AND NULLIF(BTRIM(COALESCE(batch_item.frozen_source_basis_json->>'timesheet_id', '')), '')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (BTRIM(batch_item.frozen_source_basis_json->>'timesheet_id'))::uuid
        ELSE NULL::uuid
      END,
      CASE
        WHEN UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) = 'OVERPAYMENT_RECOVERY'
         AND NULLIF(BTRIM(COALESCE(batch_item.frozen_source_basis_json->>'linked_timesheet_id', '')), '')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (BTRIM(batch_item.frozen_source_basis_json->>'linked_timesheet_id'))::uuid
        ELSE NULL::uuid
      END,
      CASE
        WHEN UPPER(BTRIM(COALESCE(batch_item.item_type, ''))) = 'OVERPAYMENT_RECOVERY'
         AND NULLIF(BTRIM(COALESCE(
           batch_item.frozen_component_snapshot_json#>>'{source_basis_json,linked_timesheet_id}',
           ''
         )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (BTRIM(
          batch_item.frozen_component_snapshot_json#>>'{source_basis_json,linked_timesheet_id}'
        ))::uuid
        ELSE NULL::uuid
      END
    ) AS timesheet_id,
    NULLIF(BTRIM(COALESCE(
      batch_item.frozen_component_key_type,
      batch_item.frozen_source_basis_json->>'key_type',
      batch_item.frozen_source_basis_json->>'component_key_type',
      batch_item.frozen_component_snapshot_json->>'key_type',
      batch_item.frozen_component_snapshot_json->>'component_key_type',
      CASE
        WHEN batch_item.item_type IN ('SEGMENT_DELTA', 'TIMESHEET_DELTA') THEN 'TS_TOTAL'
        WHEN batch_item.item_type IN ('MILEAGE_DELTA') THEN 'EXPENSE_CODE'
        WHEN batch_item.item_type IN ('EXPENSE_DELTA') THEN 'EXPENSE_CODE'
        ELSE NULL::text
      END
    )), '') AS key_type,
    NULLIF(BTRIM(COALESCE(
      batch_item.frozen_component_key_value,
      batch_item.frozen_source_basis_json->>'key_value',
      batch_item.frozen_source_basis_json->>'component_key_value',
      batch_item.frozen_component_snapshot_json->>'key_value',
      batch_item.frozen_component_snapshot_json->>'component_key_value',
      batch_item.segment_key,
      batch_item.source_ref,
      CASE WHEN batch_item.item_type = 'MILEAGE_DELTA' THEN 'MILEAGE' ELSE NULL::text END
    )), '') AS key_value,
    p_pay_batch_id AS pay_batch_id,
    batch_item.id AS pay_batch_item_id,
    COALESCE(batch_item.is_voided, false) AS batch_item_is_voided,
    batch_item.finance_case_id,
    batch_item.item_type,
    batch_item.pay_channel
  FROM public.pay_batch_candidates AS batch_candidate
  JOIN public.pay_batch_items AS batch_item
    ON batch_item.pay_batch_candidate_id = batch_candidate.id
  WHERE batch_candidate.pay_batch_id = p_pay_batch_id
    AND (
      (
        v_is_cancel_delete IS NOT TRUE
        AND COALESCE(batch_item.is_voided, false) IS NOT TRUE
      )
      OR (
        v_is_cancel_delete IS TRUE
        AND COALESCE(v_exact_item_scope_count, 0) > 0
        AND EXISTS (
          SELECT 1
          FROM pg_temp._bpay_batch_mutation_exact_item_ids AS exact_item
          WHERE exact_item.pay_batch_item_id = batch_item.id
        )
      )
      OR (
        v_is_cancel_delete IS TRUE
        AND COALESCE(v_exact_item_scope_count, 0) = 0
        AND COALESCE(v_whole_batch_scope_proven, false) IS TRUE
        AND COALESCE(batch_item.is_voided, false) IS TRUE
      )
    );

  SELECT COUNT(DISTINCT affected_key.candidate_id)::integer
  INTO v_affected_candidate_count
  FROM pg_temp._bpay_batch_mutation_keys AS affected_key;

  SELECT COALESCE(jsonb_agg(DISTINCT affected_key.candidate_id::text ORDER BY affected_key.candidate_id::text), '[]'::jsonb)
  INTO v_affected_candidate_ids_json
  FROM pg_temp._bpay_batch_mutation_keys AS affected_key
  WHERE affected_key.candidate_id IS NOT NULL;

  SELECT COALESCE(jsonb_agg(DISTINCT affected_key.timesheet_id::text ORDER BY affected_key.timesheet_id::text), '[]'::jsonb)
  INTO v_affected_timesheet_ids_json
  FROM pg_temp._bpay_batch_mutation_keys AS affected_key
  WHERE affected_key.timesheet_id IS NOT NULL;

  SELECT COALESCE(jsonb_agg(economic_key_rows.economic_key_json ORDER BY economic_key_rows.economic_key_json::text), '[]'::jsonb)
  INTO v_affected_economic_keys_json
  FROM (
    SELECT DISTINCT jsonb_build_object(
      'candidate_id', affected_key.candidate_id::text,
      'timesheet_id', CASE WHEN affected_key.timesheet_id IS NULL THEN NULL ELSE affected_key.timesheet_id::text END,
      'key_type', affected_key.key_type,
      'key_value', affected_key.key_value
    ) AS economic_key_json
    FROM pg_temp._bpay_batch_mutation_keys AS affected_key
    WHERE affected_key.key_type IS NOT NULL
      AND affected_key.key_value IS NOT NULL
  ) AS economic_key_rows;

  IF COALESCE(v_affected_candidate_count, 0) = 0 THEN
    IF v_is_cancel_delete IS TRUE
       AND COALESCE(v_cancel_delete_voided_item_count, 0) > 0 THEN
      RETURN jsonb_build_object(
        'ok', false,
        'patch_applied', false,
        'replacement_session_required', false,
        'fallback_required', true,
        'fallback_reason', 'DRAFT_CANCEL_DELETE_PATCH_SCOPE_EMPTY_WITH_VOIDED_ITEMS',
        'operation_type', v_operation_type,
        'pay_batch_id', p_pay_batch_id::text,
        'affected_candidate_count', 0,
        'affected_row_count', 0,
        'patched_row_count', 0,
        'targeted_refresh_enqueued_count', 0,
        'complex_refresh_candidate_ids', '[]'::jsonb,
        'scope_resolution_mode', v_scope_resolution_mode,
        'scope_diagnostic', v_scope_diagnostic_json
      );
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'patch_applied', true,
      'replacement_session_required', false,
      'affected_candidate_count', 0,
      'affected_row_count', 0,
      'patched_row_count', 0,
      'targeted_refresh_enqueued_count', 0,
      'complex_refresh_candidate_ids', '[]'::jsonb,
      'scope_resolution_mode', v_scope_resolution_mode,
      'scope_diagnostic', v_scope_diagnostic_json
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_batch_mutation_candidates;
  CREATE TEMP TABLE _bpay_batch_mutation_candidates ON COMMIT DROP AS
  SELECT
    candidate_keys.candidate_id,
    COALESCE(array_agg(DISTINCT candidate_keys.timesheet_id ORDER BY candidate_keys.timesheet_id) FILTER (WHERE candidate_keys.timesheet_id IS NOT NULL), ARRAY[]::uuid[]) AS timesheet_ids,
    bool_or(candidate_keys.key_type IS NULL OR candidate_keys.key_value IS NULL OR candidate_keys.timesheet_id IS NULL) AS has_missing_economic_key,
    bool_or(candidate_keys.finance_case_id IS NOT NULL) AS has_batch_finance_case
  FROM pg_temp._bpay_batch_mutation_keys AS candidate_keys
  GROUP BY candidate_keys.candidate_id;

  ALTER TABLE pg_temp._bpay_batch_mutation_candidates
    ADD COLUMN has_complexity boolean NOT NULL DEFAULT false,
    ADD COLUMN targeted_refresh_job_id uuid NULL;

  -- Invalidate the old terminal projection before a deferred cancellation
  -- patch changes any preview row. The cancel-safe wrapper must republish the
  -- exact certified source or bind one canonical repair owner before commit.
  IF v_is_cancel_delete IS TRUE AND v_defer_complex_enqueue IS TRUE THEN
    UPDATE public.banking_pay_workbench_session_scope AS invalidated_scope
    SET status='SOURCE_BUILD_PENDING',
        dirty=true,
        certified_preview_publication_parity_ok=false,
        certified_preview_publication_attestation_json=jsonb_strip_nulls(
          COALESCE(invalidated_scope.certified_preview_publication_attestation_json,'{}'::jsonb)
          || jsonb_build_object(
            'superseded_by_post_cancel_patch',true,
            'superseded_by_pay_batch_id',p_pay_batch_id::text,
            'superseded_by_operation_type',v_operation_type,
            'superseded_at_utc',v_now::text
          )
        ),
        updated_at_utc=v_now
    FROM pg_temp._bpay_batch_mutation_candidates AS affected_candidate
    WHERE invalidated_scope.session_id=p_session_id
      AND invalidated_scope.candidate_id=affected_candidate.candidate_id;

    UPDATE public.banking_pay_workbench_session_candidate_state AS invalidated_state
    SET status='PENDING',last_error_json='{}'::jsonb,updated_at_utc=v_now
    FROM pg_temp._bpay_batch_mutation_candidates AS affected_candidate
    WHERE invalidated_state.session_id=p_session_id
      AND invalidated_state.candidate_id=affected_candidate.candidate_id;
  END IF;

  UPDATE pg_temp._bpay_batch_mutation_candidates AS candidate_update
  SET has_complexity = COALESCE(candidate_update.has_batch_finance_case, false)
    OR EXISTS (
      SELECT 1
      FROM public.pay_finance_case_components AS component_row
      WHERE component_row.candidate_id = candidate_update.candidate_id
        AND component_row.closed_at_utc IS NULL
        AND (
          COALESCE(array_length(candidate_update.timesheet_ids, 1), 0) = 0
          OR component_row.linked_timesheet_id IS NULL
          OR component_row.linked_timesheet_id = ANY(candidate_update.timesheet_ids)
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.pay_advances AS advance_row
      WHERE advance_row.candidate_id = candidate_update.candidate_id
        AND UPPER(COALESCE(advance_row.status::text, '')) IN ('ACTIVE', 'PAUSED')
        AND advance_row.cleared_at_utc IS NULL
        AND advance_row.written_off_at_utc IS NULL
        AND (
          COALESCE(array_length(candidate_update.timesheet_ids, 1), 0) = 0
          OR advance_row.linked_timesheet_id IS NULL
          OR advance_row.linked_timesheet_id = ANY(candidate_update.timesheet_ids)
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.timesheet_payment_overrides AS override_row
      WHERE override_row.candidate_id = candidate_update.candidate_id
        AND override_row.override_type = 'ADVANCE_THIS_PAYMENT'
        AND override_row.consumed_at_utc IS NULL
        AND override_row.cleared_at_utc IS NULL
        AND (
          COALESCE(array_length(candidate_update.timesheet_ids, 1), 0) = 0
          OR override_row.timesheet_id = ANY(candidate_update.timesheet_ids)
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.ts_pay_adjustments AS adjustment_row
      WHERE adjustment_row.candidate_id = candidate_update.candidate_id
        AND adjustment_row.paid_at_utc IS NULL
        AND (
          COALESCE(array_length(candidate_update.timesheet_ids, 1), 0) = 0
          OR adjustment_row.timesheet_id = ANY(candidate_update.timesheet_ids)
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_session_case_resolutions AS resolution_row
      WHERE resolution_row.session_id = p_session_id
        AND resolution_row.candidate_id = candidate_update.candidate_id
        AND (
          COALESCE(array_length(candidate_update.timesheet_ids, 1), 0) = 0
          OR resolution_row.timesheet_id IS NULL
          OR resolution_row.timesheet_id = ANY(candidate_update.timesheet_ids)
        )
    )
  WHERE EXISTS (
    SELECT 1
    FROM pg_temp._bpay_batch_mutation_keys AS affected_key
    WHERE affected_key.candidate_id = candidate_update.candidate_id
  );

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(candidate_row.candidate_id::text ORDER BY candidate_row.candidate_id), '[]'::jsonb)
  INTO v_complex_candidate_count,
       v_complex_refresh_candidate_ids
  FROM pg_temp._bpay_batch_mutation_candidates AS candidate_row
  WHERE candidate_row.has_complexity IS TRUE;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(candidate_row.candidate_id::text ORDER BY candidate_row.candidate_id), '[]'::jsonb)
  INTO v_missing_key_candidate_count,
       v_missing_key_candidate_ids
  FROM pg_temp._bpay_batch_mutation_candidates AS candidate_row
  WHERE COALESCE(candidate_row.has_missing_economic_key, false) IS TRUE;


  DROP TABLE IF EXISTS pg_temp._bpay_batch_mutation_existing_preview_rows;
  CREATE TEMP TABLE _bpay_batch_mutation_existing_preview_rows ON COMMIT DROP AS
  SELECT
    preview_row.id,
    preview_row.candidate_id,
    preview_row.timesheet_id,
    preview_row.key_type,
    preview_row.key_value,
    preview_row.section,
    preview_row.selected,
    preview_row.selection_state,
    preview_row.status
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  JOIN pg_temp._bpay_batch_mutation_keys AS affected_key
    ON affected_key.candidate_id = preview_row.candidate_id
   AND preview_row.timesheet_id IS NOT DISTINCT FROM affected_key.timesheet_id
   AND preview_row.key_type IS NOT DISTINCT FROM affected_key.key_type
   AND preview_row.key_value IS NOT DISTINCT FROM affected_key.key_value
  WHERE preview_row.session_id = p_session_id
    AND preview_row.session_version = v_session_row.version
    AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) IN ('READY', 'DIRTY');

  IF v_operation_type IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE') THEN
    UPDATE public.banking_pay_workbench_preview_rows AS preview_update
    SET selected = false,
        selection_state = 'NOT_SELECTABLE',
        status = 'READY',
        row_json = jsonb_strip_nulls(
          COALESCE(preview_update.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'post_draft_overlay_applied', true,
            'post_draft_overlay_active', true,
            'post_draft_unavailable', true,
            'post_draft_unavailable_reason', 'ACTIVE_BATCH_RESERVATION',
            'post_draft_overlay_operation_type', v_operation_type,
            'post_draft_overlay_pay_batch_id', p_pay_batch_id::text,
            'post_draft_overlay_at_utc', v_now::text,
            'post_draft_effective_draftable', false,
            'post_draft_effective_is_ready_for_draft', false,
            'post_draft_effective_selection_allowed', false,
            'post_draft_effective_readiness_state', 'NOT_SELECTABLE',
            'post_draft_effective_presentation_section', 'DRAFTED',
            'selected', false,
            'selection_state', 'NOT_SELECTABLE'
          )
        ),
        updated_at_utc = v_now
    FROM pg_temp._bpay_batch_mutation_keys AS affected_key
    WHERE preview_update.session_id = p_session_id
      AND preview_update.candidate_id = affected_key.candidate_id
      AND UPPER(BTRIM(COALESCE(preview_update.status, ''))) = 'READY'
      AND preview_update.timesheet_id IS NOT DISTINCT FROM affected_key.timesheet_id
      AND preview_update.key_type IS NOT DISTINCT FROM affected_key.key_type
      AND preview_update.key_value IS NOT DISTINCT FROM affected_key.key_value;

    GET DIAGNOSTICS v_patched_row_count = ROW_COUNT;
    v_affected_row_count := v_patched_row_count;
  ELSE
    DROP TABLE IF EXISTS pg_temp._bpay_batch_mutation_restore_rows;
    CREATE TEMP TABLE _bpay_batch_mutation_restore_rows ON COMMIT DROP AS
    SELECT
      preview_row.id AS preview_row_id,
      preview_row.candidate_id,
      preview_row.timesheet_id,
      preview_row.key_type,
      preview_row.key_value,
      preview_row.row_json,
      candidate_row.has_complexity,
      candidate_row.has_missing_economic_key,
      outstanding_row.outstanding_ex_vat,
      outstanding_row.reservation_overrun_detected,
      public.pay_workbench_preview_line_contract_ok(
        preview_row.row_json,
        jsonb_build_object(
          'timesheet_id', preview_row.timesheet_id::text,
          'key_type', preview_row.key_type,
          'key_value', preview_row.key_value
        ),
        preview_row.section
      ) AS contract_result_json
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    JOIN pg_temp._bpay_batch_mutation_keys AS affected_key
      ON affected_key.candidate_id = preview_row.candidate_id
     AND preview_row.timesheet_id IS NOT DISTINCT FROM affected_key.timesheet_id
     AND preview_row.key_type IS NOT DISTINCT FROM affected_key.key_type
     AND preview_row.key_value IS NOT DISTINCT FROM affected_key.key_value
    JOIN pg_temp._bpay_batch_mutation_candidates AS candidate_row
      ON candidate_row.candidate_id = preview_row.candidate_id
    LEFT JOIN public._pay_outstanding_components(
      (SELECT COALESCE(array_agg(DISTINCT key_row.timesheet_id ORDER BY key_row.timesheet_id), ARRAY[]::uuid[]) FROM pg_temp._bpay_batch_mutation_keys AS key_row WHERE key_row.timesheet_id IS NOT NULL),
      p_pay_batch_id
    ) AS outstanding_row
      ON outstanding_row.timesheet_id = preview_row.timesheet_id
     AND outstanding_row.key_type = preview_row.key_type
     AND outstanding_row.key_value = preview_row.key_value
    WHERE preview_row.session_id = p_session_id
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) IN ('READY', 'DIRTY');

    UPDATE public.banking_pay_workbench_preview_rows AS preview_update
    SET selected = CASE
          WHEN restore_row.has_complexity IS NOT TRUE
           AND restore_row.has_missing_economic_key IS NOT TRUE
           AND COALESCE(restore_row.reservation_overrun_detected, false) IS NOT TRUE
           AND COALESCE(restore_row.outstanding_ex_vat, 0) > 0
           AND COALESCE((restore_row.contract_result_json->>'ok')::boolean, false) IS TRUE
           AND COALESCE((restore_row.contract_result_json->>'materialisable')::boolean, false) IS TRUE
           AND lower(BTRIM(COALESCE(restore_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           AND lower(BTRIM(COALESCE(restore_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           AND lower(BTRIM(COALESCE(restore_row.row_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          THEN true
          ELSE false
        END,
        selection_state = CASE
          WHEN restore_row.has_complexity IS NOT TRUE
           AND restore_row.has_missing_economic_key IS NOT TRUE
           AND COALESCE(restore_row.reservation_overrun_detected, false) IS NOT TRUE
           AND COALESCE(restore_row.outstanding_ex_vat, 0) > 0
           AND COALESCE((restore_row.contract_result_json->>'ok')::boolean, false) IS TRUE
           AND COALESCE((restore_row.contract_result_json->>'materialisable')::boolean, false) IS TRUE
           AND lower(BTRIM(COALESCE(restore_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           AND lower(BTRIM(COALESCE(restore_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           AND lower(BTRIM(COALESCE(restore_row.row_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          THEN 'SELECTED'
          ELSE 'NOT_SELECTABLE'
        END,
        status = CASE
          WHEN restore_row.has_complexity IS TRUE OR restore_row.has_missing_economic_key IS TRUE THEN 'DIRTY'
          ELSE 'READY'
        END,
        row_json = jsonb_strip_nulls(
          COALESCE(preview_update.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'post_draft_overlay_applied', true,
            'post_draft_overlay_active', false,
            'post_draft_unavailable', false,
            'post_draft_unavailable_reason', NULL::text,
            'post_draft_overlay_operation_type', v_operation_type,
            'post_draft_overlay_pay_batch_id', p_pay_batch_id::text,
            'post_draft_overlay_at_utc', v_now::text,
            'post_draft_effective_draftable', NULL::boolean,
            'post_draft_effective_is_ready_for_draft', NULL::boolean,
            'post_draft_effective_selection_allowed', NULL::boolean,
            'post_draft_effective_readiness_state', NULL::text,
            'post_draft_effective_presentation_section', NULL::text,
            'restore_checked', true,
            'selected', CASE
              WHEN restore_row.has_complexity IS NOT TRUE
               AND restore_row.has_missing_economic_key IS NOT TRUE
               AND COALESCE(restore_row.reservation_overrun_detected, false) IS NOT TRUE
               AND COALESCE(restore_row.outstanding_ex_vat, 0) > 0
               AND COALESCE((restore_row.contract_result_json->>'ok')::boolean, false) IS TRUE
               AND COALESCE((restore_row.contract_result_json->>'materialisable')::boolean, false) IS TRUE
               AND lower(BTRIM(COALESCE(restore_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND lower(BTRIM(COALESCE(restore_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND lower(BTRIM(COALESCE(restore_row.row_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              THEN true
              ELSE false
            END,
            'selection_state', CASE
              WHEN restore_row.has_complexity IS NOT TRUE
               AND restore_row.has_missing_economic_key IS NOT TRUE
               AND COALESCE(restore_row.reservation_overrun_detected, false) IS NOT TRUE
               AND COALESCE(restore_row.outstanding_ex_vat, 0) > 0
               AND COALESCE((restore_row.contract_result_json->>'ok')::boolean, false) IS TRUE
               AND COALESCE((restore_row.contract_result_json->>'materialisable')::boolean, false) IS TRUE
               AND lower(BTRIM(COALESCE(restore_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND lower(BTRIM(COALESCE(restore_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND lower(BTRIM(COALESCE(restore_row.row_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              THEN 'SELECTED'
              ELSE 'NOT_SELECTABLE'
            END
          )
        ),
        updated_at_utc = v_now
    FROM pg_temp._bpay_batch_mutation_restore_rows AS restore_row
    WHERE preview_update.id = restore_row.preview_row_id;

    GET DIAGNOSTICS v_patched_row_count = ROW_COUNT;
    v_affected_row_count := v_patched_row_count;
  END IF;

  IF NOT v_defer_complex_enqueue THEN
  FOR v_refresh_candidate_row IN
    SELECT
      candidate_row.candidate_id,
      candidate_row.timesheet_ids,
      candidate_row.has_missing_economic_key,
      candidate_row.has_complexity
    FROM pg_temp._bpay_batch_mutation_candidates AS candidate_row
    WHERE v_operation_type IN ('DRAFT_DELETE', 'DRAFT_CANCEL')
      AND (
        candidate_row.has_missing_economic_key IS TRUE
        OR candidate_row.has_complexity IS TRUE
      )
    ORDER BY candidate_row.candidate_id
  LOOP
    v_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => v_session_row.source_snapshot_run_id,
      p_candidate_id => v_refresh_candidate_row.candidate_id,
      p_reason => 'BATCH_MUTATION_COMPLEX_OR_UNCERTAIN',
      p_actor_user_id => COALESCE(p_actor_user_id, v_session_row.actor_user_id),
      p_payload_json => jsonb_strip_nulls(
        jsonb_build_object(
          'session_id', p_session_id::text,
          'source_session_id', p_session_id::text,
          'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
          'session_version', v_session_row.version,
          'session_signature', v_session_row.session_signature,
          'operation_type', v_operation_type,
          'pay_batch_id', p_pay_batch_id::text,
          'enqueue_origin', 'PAY_WORKBENCH_PATCH_PREVIEW_AFTER_BATCH_MUTATION',
          'force_legacy', true
        )
        || jsonb_build_object(
          'targeted_timesheet_ids', COALESCE(to_jsonb(v_refresh_candidate_row.timesheet_ids), '[]'::jsonb),
          'linked_timesheet_ids', '[]'::jsonb,
          'refresh_scope_kind', CASE WHEN COALESCE(array_length(v_refresh_candidate_row.timesheet_ids, 1), 0) > 0 THEN 'TARGETED_TIMESHEETS' ELSE 'CANDIDATE_FULL_LIVE' END,
          'pay_channel_scope', 'ALL',
          'projection_mode', 'LEGACY',
          'projection_class', CASE WHEN v_refresh_candidate_row.has_missing_economic_key IS TRUE THEN 'TARGET_SCOPE_MISSING' ELSE 'POST_DRAFT_PATCH_COMPLEX' END,
          'fallback_reason', CASE WHEN v_refresh_candidate_row.has_missing_economic_key IS TRUE THEN 'POST_DRAFT_PATCH_MISSING_ECONOMIC_KEY' ELSE 'POST_DRAFT_CANCEL_COMPLEX_REFRESH_REQUIRED' END,
          'source_build_required', true,
          'line_work_required', true,
          'delta_refresh_required', false,
          'complex_refresh_required', true,
          'scope_resolution_mode', v_scope_resolution_mode,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
        )
      )
    );

    v_enqueue_job_id_text := NULLIF(BTRIM(COALESCE(v_enqueue_result->>'job_id', '')), '');

    IF v_enqueue_job_id_text IS NULL OR v_enqueue_job_id_text !~* v_uuid_regex THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BATCH_MUTATION_CANONICAL_REFRESH_JOB_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_BATCH_MUTATION_CANONICAL_REFRESH_JOB_REQUIRED',
                'session_id', p_session_id::text,
                'candidate_id', v_refresh_candidate_row.candidate_id::text,
                'pay_batch_id', p_pay_batch_id::text,
                'operation_type', v_operation_type,
                'enqueue_result', COALESCE(v_enqueue_result, '{}'::jsonb)
              )::text;
    END IF;

    v_enqueue_job_id := v_enqueue_job_id_text::uuid;
    v_enqueue_job_type := NULL::text;
    v_enqueue_job_status := NULL::text;
    v_enqueue_source_build_run_id_text := NULL::text;

    SELECT
      active_job.job_type,
      active_job.status,
      NULLIF(BTRIM(COALESCE(
        active_job.payload_json->>'source_build_run_id',
        active_job.payload_json#>>'{source_build,source_build_run_id}',
        active_job.payload_json#>>'{source_build,run_id}',
        ''
      )), '')
    INTO
      v_enqueue_job_type,
      v_enqueue_job_status,
      v_enqueue_source_build_run_id_text
    FROM public.banking_pay_workbench_jobs AS active_job
    WHERE active_job.id = v_enqueue_job_id
      AND active_job.session_id = p_session_id
      AND active_job.candidate_id = v_refresh_candidate_row.candidate_id
    FOR UPDATE;

    IF NOT FOUND
       OR UPPER(BTRIM(COALESCE(v_enqueue_job_type, ''))) <> 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
       OR UPPER(BTRIM(COALESCE(v_enqueue_job_status, ''))) NOT IN ('QUEUED', 'RUNNING')
       OR v_enqueue_source_build_run_id_text IS NULL
       OR v_enqueue_source_build_run_id_text !~* v_uuid_regex THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BATCH_MUTATION_CANONICAL_REFRESH_JOB_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_BATCH_MUTATION_CANONICAL_REFRESH_JOB_INVALID',
                'session_id', p_session_id::text,
                'candidate_id', v_refresh_candidate_row.candidate_id::text,
                'pay_batch_id', p_pay_batch_id::text,
                'operation_type', v_operation_type,
                'job_id', v_enqueue_job_id_text,
                'job_type', v_enqueue_job_type,
                'job_status', v_enqueue_job_status,
                'source_build_run_id', v_enqueue_source_build_run_id_text
              )::text;
    END IF;

    UPDATE pg_temp._bpay_batch_mutation_candidates AS candidate_update
    SET targeted_refresh_job_id = v_enqueue_job_id
    WHERE candidate_update.candidate_id = v_refresh_candidate_row.candidate_id;

    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS scope_check
    WHERE scope_check.session_id = p_session_id
      AND scope_check.candidate_id = v_refresh_candidate_row.candidate_id
      AND UPPER(BTRIM(COALESCE(scope_check.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(scope_check.dirty, false) IS TRUE
      AND scope_check.pending_job_id = v_enqueue_job_id
      AND scope_check.error_json IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BATCH_MUTATION_SCOPE_BIND_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_BATCH_MUTATION_SCOPE_BIND_REQUIRED',
                'session_id', p_session_id::text,
                'candidate_id', v_refresh_candidate_row.candidate_id::text,
                'job_id', v_enqueue_job_id::text,
                'source_build_run_id', v_enqueue_source_build_run_id_text,
                'message', 'The canonical candidate refresh helper did not bind the workbench scope to the validated successor job.'
              )::text;
    END IF;

    v_targeted_refresh_enqueued_count := v_targeted_refresh_enqueued_count + 1;
  END LOOP;
  END IF;

  SELECT COALESCE(jsonb_agg(DISTINCT candidate_row.candidate_id::text ORDER BY candidate_row.candidate_id::text), '[]'::jsonb)
  INTO v_targeted_refresh_candidate_ids_json
  FROM pg_temp._bpay_batch_mutation_candidates AS candidate_row
  WHERE v_operation_type IN ('DRAFT_DELETE', 'DRAFT_CANCEL')
    AND (
      candidate_row.has_missing_economic_key IS TRUE
      OR candidate_row.has_complexity IS TRUE
    );

  DROP TABLE IF EXISTS pg_temp._bpay_batch_mutation_current_preview_rows;
  CREATE TEMP TABLE _bpay_batch_mutation_current_preview_rows ON COMMIT DROP AS
  SELECT preview_row.id,
         preview_row.candidate_id,
         preview_row.selected,
         preview_row.selection_state,
         preview_row.status
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  JOIN pg_temp._bpay_batch_mutation_existing_preview_rows AS existing_row
    ON existing_row.id = preview_row.id
  WHERE preview_row.updated_at_utc = v_now;

  SELECT COALESCE(jsonb_agg(current_row.id::text ORDER BY current_row.id::text), '[]'::jsonb)
  INTO v_patched_row_ids_json
  FROM pg_temp._bpay_batch_mutation_current_preview_rows AS current_row;

  v_post_cancel_patch_digest:=CASE WHEN v_is_cancel_delete IS TRUE THEN
    encode(extensions.digest(convert_to(concat_ws('|',
      'POST_CANCEL_RETURN_PATCH_V1',p_session_id::text,v_session_row.version::text,
      p_pay_batch_id::text,v_operation_type,
      COALESCE(v_options_json->>'correction_request_id',''),
      COALESCE(v_affected_candidate_ids_json::text,'[]'),
      COALESCE(v_patched_row_ids_json::text,'[]'),
      COALESCE(v_affected_economic_keys_json::text,'[]')
    ),'UTF8'),'sha256'),'hex') ELSE NULL::text END;

  SELECT COUNT(*)::integer
  INTO v_active_noncurrent_row_count_after_patch
  FROM public.banking_pay_workbench_preview_rows AS noncurrent_row
  WHERE noncurrent_row.session_id=p_session_id
    AND noncurrent_row.session_version=v_session_row.version
    AND noncurrent_row.candidate_id IN (
      SELECT affected_candidate.candidate_id
      FROM pg_temp._bpay_batch_mutation_candidates AS affected_candidate
    )
    AND UPPER(BTRIM(COALESCE(noncurrent_row.status,''))) IN (
      'DIRTY','PENDING','DELTA_PENDING','RUNNING','QUEUED','ERROR','FAILED'
    );

  SELECT COUNT(*) FILTER (WHERE existing_row.selected IS TRUE AND existing_row.selection_state = 'SELECTED' AND UPPER(BTRIM(COALESCE(existing_row.status, ''))) = 'READY')::integer,
         COUNT(*) FILTER (WHERE current_row.selected IS TRUE AND current_row.selection_state = 'SELECTED' AND UPPER(BTRIM(COALESCE(current_row.status, ''))) = 'READY')::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(existing_row.status, ''))) = 'READY')::integer,
         COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(current_row.status, ''))) = 'READY')::integer
  INTO v_selected_before_count,
       v_selected_after_count,
       v_ready_before_count,
       v_ready_after_count
  FROM pg_temp._bpay_batch_mutation_existing_preview_rows AS existing_row
  JOIN pg_temp._bpay_batch_mutation_current_preview_rows AS current_row
    ON current_row.id = existing_row.id;

  v_selected_count_delta := COALESCE(v_selected_after_count, 0) - COALESCE(v_selected_before_count, 0);
  v_ready_count_delta := COALESCE(v_ready_after_count, 0) - COALESCE(v_ready_before_count, 0);

  DROP TABLE IF EXISTS pg_temp._bpay_batch_mutation_effective_preview_rows;
  CREATE TEMP TABLE _bpay_batch_mutation_effective_preview_rows ON COMMIT DROP AS
  SELECT
    preview_row.id,
    preview_row.candidate_id,
    preview_row.section,
    preview_row.row_key,
    preview_row.row_ordinal,
    preview_row.selected,
    preview_row.selection_state
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.session_version = v_session_row.version
    AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
    AND NOT (
      COALESCE(
        lower(BTRIM(COALESCE(preview_row.row_json->>'post_draft_unavailable', '')))
          IN ('true', 't', '1', 'yes', 'y', 'on'),
        false
      )
      OR (
        COALESCE(
          lower(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', '')))
            IN ('true', 't', '1', 'yes', 'y', 'on'),
          false
        )
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_operation_type', '')))
          IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
        AND lower(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_active', 'true')))
          NOT IN ('false', 'f', '0', 'no', 'n', 'off')
      )
    );

  SELECT
    COUNT(*)::integer,
    COUNT(*) FILTER (
      WHERE effective_row.selected IS TRUE
        AND UPPER(BTRIM(COALESCE(effective_row.selection_state, ''))) = 'SELECTED'
    )::integer
  INTO v_session_preview_row_count,
       v_session_selected_row_count
  FROM pg_temp._bpay_batch_mutation_effective_preview_rows AS effective_row;

  SELECT COALESCE(
           jsonb_object_agg(section_count.section, section_count.row_count ORDER BY section_count.section),
           '{}'::jsonb
         )
  INTO v_session_section_counts_json
  FROM (
    SELECT effective_row.section,
           COUNT(*)::integer AS row_count
    FROM pg_temp._bpay_batch_mutation_effective_preview_rows AS effective_row
    GROUP BY effective_row.section
  ) AS section_count;

  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'id', sample_row.id::text,
               'row_key', sample_row.row_key,
               'section', sample_row.section,
               'selected', COALESCE(sample_row.selected, false),
               'candidate_id', sample_row.candidate_id::text,
               'selection_state', sample_row.selection_state
             )
             ORDER BY sample_row.section, sample_row.row_ordinal, sample_row.id
           ),
           '[]'::jsonb
         )
  INTO v_session_candidate_samples_json
  FROM (
    SELECT effective_row.*
    FROM pg_temp._bpay_batch_mutation_effective_preview_rows AS effective_row
    ORDER BY effective_row.section, effective_row.row_ordinal, effective_row.id
    LIMIT 25
  ) AS sample_row;

  IF NOT (v_is_cancel_delete IS TRUE AND v_defer_complex_enqueue IS TRUE)
     AND to_regprocedure('public.pay_workbench_delta_update_candidate_state_v1(uuid,uuid,uuid,jsonb)') IS NOT NULL THEN
    FOR v_candidate_state_candidate_id IN
      SELECT candidate_row.candidate_id
      FROM pg_temp._bpay_batch_mutation_candidates AS candidate_row
      ORDER BY candidate_row.candidate_id
    LOOP
      v_candidate_state_result := public.pay_workbench_delta_update_candidate_state_v1(
        p_session_id,
        v_candidate_state_candidate_id,
        v_patch_projection_run_id,
        jsonb_build_object(
          'context', 'POST_DRAFT_PATCH',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_type', v_operation_type,
          'affected_economic_keys', COALESCE(v_affected_economic_keys_json, '[]'::jsonb),
          'patched_row_ids', COALESCE(v_patched_row_ids_json, '[]'::jsonb)
        )
      );
      v_candidate_state_results_json := v_candidate_state_results_json || jsonb_build_array(v_candidate_state_result);
    END LOOP;
  ELSIF NOT (v_is_cancel_delete IS TRUE AND v_defer_complex_enqueue IS TRUE) THEN
    v_candidate_state_results_json := jsonb_build_array(jsonb_build_object(
      'ok', false,
      'fallback_required', true,
      'fallback_reason', 'PAY_WORKBENCH_DELTA_UPDATE_CANDIDATE_STATE_V1_MISSING'
    ));
  END IF;

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET progress_state = CASE
        WHEN COALESCE(v_targeted_refresh_enqueued_count, 0) > 0
          OR (v_is_cancel_delete IS TRUE AND v_defer_complex_enqueue IS TRUE)
          THEN 'REFRESHING_CANDIDATES'
        WHEN UPPER(BTRIM(COALESCE(session_update.progress_state, ''))) IN ('READY', 'READY_EMPTY')
          THEN CASE WHEN COALESCE(v_session_preview_row_count, 0) = 0 THEN 'READY_EMPTY' ELSE 'READY' END
        ELSE session_update.progress_state
      END,
      preview_row_count = GREATEST(COALESCE(v_session_preview_row_count, 0), 0),
      selected_row_count = GREATEST(COALESCE(v_session_selected_row_count, 0), 0),
      section_counts_json = COALESCE(v_session_section_counts_json, '{}'::jsonb),
      candidate_sample_rows_json = COALESCE(v_session_candidate_samples_json, '[]'::jsonb),
      server_selected_preview_row_ids = CASE
        WHEN v_operation_type IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE') THEN (
          SELECT COALESCE(jsonb_agg(selected_id.value ORDER BY selected_id.ordinality), '[]'::jsonb)
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(COALESCE(session_update.server_selected_preview_row_ids, '[]'::jsonb)) = 'array'
                THEN COALESCE(session_update.server_selected_preview_row_ids, '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          ) WITH ORDINALITY AS selected_id(value, ordinality)
          WHERE NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(COALESCE(v_patched_row_ids_json, '[]'::jsonb)) AS patched_id(value)
            WHERE patched_id.value = selected_id.value
          )
        )
        ELSE session_update.server_selected_preview_row_ids
      END,
      progress_json = jsonb_strip_nulls(
        COALESCE(session_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_batch_mutation_patch_at_utc', v_now::text,
          'last_batch_mutation_patch_pay_batch_id', p_pay_batch_id::text,
          'last_batch_mutation_patch_operation_type', v_operation_type,
          'last_batch_mutation_patch_rows', COALESCE(v_patched_row_count, 0),
          'last_batch_mutation_refresh_enqueued', COALESCE(v_targeted_refresh_enqueued_count, 0),
          'last_batch_mutation_patched_row_ids', COALESCE(v_patched_row_ids_json, '[]'::jsonb),
          'last_batch_mutation_affected_candidate_ids', COALESCE(v_affected_candidate_ids_json, '[]'::jsonb),
          'last_batch_mutation_affected_timesheet_ids', COALESCE(v_affected_timesheet_ids_json, '[]'::jsonb),
          'last_batch_mutation_scope_resolution_mode', v_scope_resolution_mode,
          'last_batch_mutation_scope_diagnostic', COALESCE(v_scope_diagnostic_json, '{}'::jsonb),
          'preview_row_count', GREATEST(COALESCE(v_session_preview_row_count, 0), 0),
          'selected_row_count', GREATEST(COALESCE(v_session_selected_row_count, 0), 0),
          'selected_eligible_ready_row_count', GREATEST(COALESCE(v_session_selected_row_count, 0), 0),
          'selected_rows_available', GREATEST(COALESCE(v_session_selected_row_count, 0), 0) > 0,
          'ready_for_draft', GREATEST(COALESCE(v_session_selected_row_count, 0), 0) > 0,
          'can_create_draft', GREATEST(COALESCE(v_session_selected_row_count, 0), 0) > 0,
          'section_counts_json', COALESCE(v_session_section_counts_json, '{}'::jsonb),
          'section_counts', COALESCE(v_session_section_counts_json, '{}'::jsonb),
          'candidate_sample_rows_json', COALESCE(v_session_candidate_samples_json, '[]'::jsonb),
          'progress_state', CASE
            WHEN COALESCE(v_targeted_refresh_enqueued_count, 0) > 0
              OR (v_is_cancel_delete IS TRUE AND v_defer_complex_enqueue IS TRUE)
              THEN 'REFRESHING_CANDIDATES'
            WHEN COALESCE(v_session_preview_row_count, 0) = 0 THEN 'READY_EMPTY'
            ELSE 'READY'
          END,
          'phase', CASE
            WHEN COALESCE(v_targeted_refresh_enqueued_count, 0) > 0
              OR (v_is_cancel_delete IS TRUE AND v_defer_complex_enqueue IS TRUE)
              THEN 'REFRESHING_CANDIDATES'
            WHEN COALESCE(v_session_preview_row_count, 0) = 0 THEN 'READY_EMPTY'
            ELSE 'READY'
          END,
          'ready_empty', COALESCE(v_session_preview_row_count, 0) = 0,
          'rows_available', COALESCE(v_session_preview_row_count, 0) > 0,
          'has_materialised_preview_rows', COALESCE(v_session_preview_row_count, 0) > 0,
          'status_text', CASE
            WHEN COALESCE(v_targeted_refresh_enqueued_count, 0) > 0
              OR (v_is_cancel_delete IS TRUE AND v_defer_complex_enqueue IS TRUE)
              THEN 'Preparing payment preview.'
            WHEN COALESCE(v_session_preview_row_count, 0) = 0 THEN 'No payable rows found.'
            ELSE 'Payment preview is ready.'
          END,
          'next_recommended_action', CASE
            WHEN COALESCE(v_targeted_refresh_enqueued_count, 0) > 0
              OR (v_is_cancel_delete IS TRUE AND v_defer_complex_enqueue IS TRUE)
              THEN 'WAIT_FOR_WORKER'
            ELSE 'READ_PREVIEW_PAGE'
          END
        )
      ),
      progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  IF v_operation_type='DRAFT_CREATE'
     AND COALESCE(v_options_json->>'operation_id','') ~* v_uuid_regex THEN
    v_draft_operation_id:=(v_options_json->>'operation_id')::uuid;
    v_draft_adoption_result:=private.pay_workbench_draft_create_adoption_finalize_v1(
      v_draft_operation_id,p_pay_batch_id,p_session_id,
      ARRAY(
        SELECT candidate_row.candidate_id
        FROM pg_temp._bpay_batch_mutation_candidates AS candidate_row
        ORDER BY candidate_row.candidate_id
      ),
      jsonb_build_object('operation_type',v_operation_type)
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'patch_applied', true,
    'replacement_session_required', false,
    'affected_candidate_count', COALESCE(v_affected_candidate_count, 0),
    'affected_row_count', COALESCE(v_affected_row_count, 0),
    'patched_row_count', COALESCE(v_patched_row_count, 0),
    'targeted_refresh_enqueued_count', COALESCE(v_targeted_refresh_enqueued_count, 0),
    'targeted_refresh_enqueued', COALESCE(v_targeted_refresh_enqueued_count, 0) > 0,
    'complex_enqueue_deferred',v_defer_complex_enqueue,
    'replacement_session_required', false,
    'replacement_session_created', false,
    'affected_candidate_ids', COALESCE(v_affected_candidate_ids_json, '[]'::jsonb),
    'patched_row_ids', COALESCE(v_patched_row_ids_json, '[]'::jsonb),
    'affected_timesheet_ids', COALESCE(v_affected_timesheet_ids_json, '[]'::jsonb),
    'affected_economic_keys', COALESCE(v_affected_economic_keys_json, '[]'::jsonb),
    'targeted_refresh_candidate_ids', COALESCE(v_targeted_refresh_candidate_ids_json, '[]'::jsonb),
    'candidate_state_results', COALESCE(v_candidate_state_results_json, '[]'::jsonb),
    'post_cancel_patch_digest',v_post_cancel_patch_digest,
    'active_noncurrent_row_count_after_patch',COALESCE(v_active_noncurrent_row_count_after_patch,0),
    'physical_currentness_checked',false,
    'physical_currentness_proven',false,
    'shadow_compare_failed', false,
    'complex_refresh_candidate_ids', COALESCE(v_complex_refresh_candidate_ids, '[]'::jsonb),
    'missing_key_candidate_ids', COALESCE(v_missing_key_candidate_ids, '[]'::jsonb),
    'operation_type', v_operation_type,
    'pay_batch_id', p_pay_batch_id::text,
    'scope_resolution_mode', v_scope_resolution_mode,
    'scope_diagnostic', COALESCE(v_scope_diagnostic_json, '{}'::jsonb),
    'draft_create_adoption',COALESCE(v_draft_adoption_result,'{}'::jsonb),
    'post_action_refresh', jsonb_build_object(
      'mode', 'PATCH_EXISTING_SESSION',
      'patch_applied', true,
      'patched_session_id', p_session_id::text,
      'replacement_session_created', false,
      'affected_candidate_ids', COALESCE(v_affected_candidate_ids_json, '[]'::jsonb),
      'patched_row_ids', COALESCE(v_patched_row_ids_json, '[]'::jsonb),
      'affected_timesheet_ids', COALESCE(v_affected_timesheet_ids_json, '[]'::jsonb),
      'affected_economic_keys', COALESCE(v_affected_economic_keys_json, '[]'::jsonb),
      'targeted_refresh_candidate_ids', COALESCE(v_targeted_refresh_candidate_ids_json, '[]'::jsonb),
      'targeted_refresh_enqueued', COALESCE(v_targeted_refresh_enqueued_count, 0) > 0,
      'scope_resolution_mode', v_scope_resolution_mode,
      'scope_diagnostic', COALESCE(v_scope_diagnostic_json, '{}'::jsonb),
      'shadow_compare_failed', false
    )
  );
END;
$function$;

-- pay_workbench_prepare_draft_allocation_rows_seed(uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_prepare_draft_allocation_rows_seed(p_operation_id uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(candidate_scopes_processed integer, allocation_rows_inserted integer, allocation_rows_reused integer, failures integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_scope_ids jsonb := COALESCE(p_candidate_scope_ids, '[]'::jsonb);
  v_scope_id_count integer := 0;
  v_candidate_scopes_processed integer := 0;
  v_expected_count integer := 0;
  v_inserted integer := 0;
  v_reused integer := 0;
  v_malformed_allocation_preview_rows jsonb := '[]'::jsonb;
  v_synthetic_total_allocation_preview_rows jsonb := '[]'::jsonb;
  v_semantic_draft_guard_enabled boolean := false;
  v_source_publication_identity_enforce_enabled boolean := false;
  v_semantic_draft_failures jsonb := '[]'::jsonb;
  v_semantic_source_failure_count integer := 0;
  v_plan_scope_ids jsonb := '[]'::jsonb;
  v_plan_drift_details jsonb := '[]'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed: p_operation_id is required';
  END IF;

  IF p_candidate_scope_ids IS NOT NULL AND jsonb_typeof(p_candidate_scope_ids) <> 'array' THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed requires p_candidate_scope_ids to be null or a JSON array';
  END IF;

  IF p_candidate_scope_ids IS NOT NULL THEN
    v_scope_id_count := jsonb_array_length(v_scope_ids);
    IF v_scope_id_count = 0 THEN
      RAISE EXCEPTION 'DRAFT_ALLOCATION_SCOPE_EMPTY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'DRAFT_ALLOCATION_SCOPE_EMPTY', 'operation_id', p_operation_id::text, 'message', 'DRAFT_CREATE allocation seeding requires at least one candidate scope id.')::text;
    END IF;
    IF v_scope_id_count > 100 THEN
      RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed candidate scope id array exceeds the 100 row cap: %', v_scope_id_count;
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
      WHERE NOT ((supplied_scope.scope_value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
    ) THEN
      RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed requires candidate scope ids to be UUID strings';
    END IF;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed operation not found: %', p_operation_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.operation_type, ''))) <> 'DRAFT_CREATE' THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation.operation_type;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.status, ''))) IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed cannot seed allocation rows for terminal operation % with status %', p_operation_id, v_operation.status;
  END IF;

  SELECT COALESCE(settings_row.banking_pay_workbench_semantic_ready_draft_guard_v2_enabled, false),
         COALESCE(settings_row.banking_pay_source_publication_identity_enforce_v1_enabled, false)
  INTO v_semantic_draft_guard_enabled,v_source_publication_identity_enforce_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_allocation_scope_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_allocation_scope_rows ON COMMIT DROP AS
  SELECT scope_row.*
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND (
      (
        p_candidate_scope_ids IS NULL
        AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) IN ('PENDING', 'SCOPED')
      )
      OR (
        p_candidate_scope_ids IS NOT NULL
        AND scope_row.id IN (
          SELECT (supplied_scope.scope_value #>> '{}')::uuid
          FROM jsonb_array_elements(v_scope_ids) AS supplied_scope(scope_value)
        )
      )
    )
  ORDER BY scope_row.chunk_sequence NULLS LAST, scope_row.pay_channel, scope_row.candidate_id, scope_row.id
  LIMIT 100;

  SELECT COUNT(*)::integer
  INTO v_candidate_scopes_processed
  FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope;

  IF p_candidate_scope_ids IS NOT NULL AND COALESCE(v_candidate_scopes_processed, 0) <> COALESCE(v_scope_id_count, 0) THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_allocation_rows_seed one or more candidate scope ids do not belong to operation %', p_operation_id;
  END IF;

  IF COALESCE(v_candidate_scopes_processed, 0) = 0 THEN
    RETURN QUERY SELECT 0::integer, 0::integer, 0::integer, 0::integer;
    RETURN;
  END IF;

  SELECT COALESCE(jsonb_agg(selected_scope.id::text ORDER BY selected_scope.id::text), '[]'::jsonb)
  INTO v_plan_scope_ids
  FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_allocation_preview_candidates;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_allocation_preview_candidates ON COMMIT DROP AS
  WITH scope_selected_lines AS (
    SELECT
      selected_scope.operation_id,
      selected_scope.id AS candidate_scope_id,
      selected_scope.pay_batch_id,
      selected_scope.workbench_session_id,
      selected_scope.source_session_version,
      selected_scope.candidate_id,
      selected_scope.pay_channel,
      selected_scope.candidate_totals_json,
      selected_scope.allocation_basis_json AS scope_allocation_basis_json,
      line_values.value AS line_json,
      line_values.ordinality::bigint AS line_ordinal
    FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(selected_scope.selected_canonical_preview_lines_json) = 'array'
          AND jsonb_array_length(selected_scope.selected_canonical_preview_lines_json) > 0
          THEN selected_scope.selected_canonical_preview_lines_json
        WHEN jsonb_typeof(selected_scope.effective_canonical_preview_lines_json) = 'array'
          AND jsonb_array_length(selected_scope.effective_canonical_preview_lines_json) > 0
          THEN selected_scope.effective_canonical_preview_lines_json
        ELSE '[]'::jsonb
      END
    ) WITH ORDINALITY AS line_values(value, ordinality)
  ), normalised_scope_lines_raw AS (
    SELECT
      scope_selected_lines.operation_id,
      scope_selected_lines.candidate_scope_id,
      scope_selected_lines.pay_batch_id,
      scope_selected_lines.workbench_session_id,
      scope_selected_lines.source_session_version,
      scope_selected_lines.candidate_id,
      scope_selected_lines.pay_channel,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'preview_row_id', scope_selected_lines.line_json->>'preview_row_pk', scope_selected_lines.line_json->>'row_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'preview_row_id', scope_selected_lines.line_json->>'preview_row_pk', scope_selected_lines.line_json->>'row_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS preview_row_id,
      NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'row_key', scope_selected_lines.line_json->>'source_ref', '')), '') AS row_key,
      CASE WHEN COALESCE(scope_selected_lines.line_json->>'row_ordinal', '') ~ '^[0-9]+$' THEN (scope_selected_lines.line_json->>'row_ordinal')::bigint ELSE scope_selected_lines.line_ordinal END AS row_ordinal,
      scope_selected_lines.line_json AS row_json,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json#>>'{economic_key,timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json#>>'{economic_key,timesheet_id}', '')), '')::uuid
        ELSE NULL::uuid
      END AS economic_key_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'timesheet_id', scope_selected_lines.line_json->>'real_business_timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'timesheet_id', scope_selected_lines.line_json->>'real_business_timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS top_level_timesheet_id,
      COALESCE(NULLIF(BTRIM(scope_selected_lines.line_json->>'section'), ''), 'canonical_preview_lines') AS section,
      UPPER(NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json#>>'{economic_key,key_type}', scope_selected_lines.line_json->>'key_type', scope_selected_lines.line_json->>'component_key_type', '')), '')) AS key_type,
      NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json#>>'{economic_key,key_value}', scope_selected_lines.line_json->>'key_value', scope_selected_lines.line_json->>'component_key_value', '')), '') AS key_value,
      UPPER(NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'selection_state', 'SELECTED')), '')) AS selection_state,
      UPPER(NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'status', 'READY')), '')) AS line_status,
      LOWER(BTRIM(COALESCE(scope_selected_lines.line_json->>'selected', 'true'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS line_selected,
      (
        COALESCE(scope_selected_lines.line_json->>'projection_path', '') = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
        OR scope_selected_lines.line_json ? 'projection_run_id'
      ) AS is_delta_projection,
      LOWER(BTRIM(COALESCE(scope_selected_lines.line_json->>'projection_certified', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS projection_certified,
      COALESCE(
        NULLIF(BTRIM(scope_selected_lines.line_json->>'policy_x_authority_scope'), ''),
        NULLIF(BTRIM(scope_selected_lines.line_json#>>'{contract_json,policy_x_authority_scope}'), ''),
        NULLIF(BTRIM(scope_selected_lines.line_json#>>'{contract,policy_x_authority_scope}'), ''),
        ''
      ) AS policy_x_authority_scope,
      (
        LOWER(BTRIM(COALESCE(scope_selected_lines.line_json->>'post_draft_overlay_applied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          UPPER(BTRIM(COALESCE(scope_selected_lines.line_json->>'post_draft_overlay_operation_type', ''))) IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
          OR LOWER(BTRIM(COALESCE(scope_selected_lines.line_json->>'selected', 'true'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          OR UPPER(BTRIM(COALESCE(scope_selected_lines.line_json->>'selection_state', 'SELECTED'))) <> 'SELECTED'
          OR UPPER(BTRIM(COALESCE(scope_selected_lines.line_json->>'status', 'READY'))) <> 'READY'
        )
      ) AS post_draft_overlay_unavailable,
      CASE WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'finance_case_id', '')), '')::uuid ELSE NULL::uuid END AS finance_case_id,
      CASE WHEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'finance_component_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'finance_component_id', '')), '')::uuid ELSE NULL::uuid END AS finance_component_id,
      UPPER(COALESCE(NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'line_type', '')), ''), NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'case_type', '')), ''), 'PREVIEW_ROW')) AS allocation_type,
      UPPER(NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'item_direction', scope_selected_lines.line_json->>'direction', '')), '')) AS item_direction,
      component_probe.single_fixed_reimbursement_key_type,
      component_probe.single_fixed_reimbursement_key_value,
      NULLIF(BTRIM(COALESCE(scope_selected_lines.line_json->>'source_ref', scope_selected_lines.line_json->>'row_key', '')), '') AS source_ref,
      CASE
        WHEN COALESCE(scope_selected_lines.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((scope_selected_lines.line_json->>'amount_ex_vat')::numeric, 2)
        WHEN COALESCE(scope_selected_lines.line_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((scope_selected_lines.line_json->>'preview_amount_ex_vat')::numeric, 2)
        WHEN COALESCE(scope_selected_lines.line_json->>'allocated_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND((scope_selected_lines.line_json->>'allocated_amount')::numeric, 2)
        ELSE NULL::numeric
      END AS allocated_amount
    FROM scope_selected_lines
    CROSS JOIN LATERAL (
      SELECT
        CASE
          WHEN component_counts.object_component_count = 1
           AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_type
          ELSE NULL::text
        END AS single_fixed_reimbursement_key_type,
        CASE
          WHEN component_counts.object_component_count = 1
           AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_value
          ELSE NULL::text
        END AS single_fixed_reimbursement_key_value
      FROM (
        SELECT
          (COUNT(*) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
          ))::integer AS object_component_count,
          (COUNT(*) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ))::integer AS fixed_reimbursement_component_count,
          MAX(UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), ''))) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ) AS fixed_reimbursement_key_type,
          MAX(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '')) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ) AS fixed_reimbursement_key_value
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(scope_selected_lines.line_json->'case_components') = 'array' THEN scope_selected_lines.line_json->'case_components'
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS component_counts
    ) AS component_probe
  ), allocation_timesheet_refs AS (
    SELECT normalised_scope_lines_raw.economic_key_timesheet_id AS timesheet_id
    FROM normalised_scope_lines_raw
    WHERE normalised_scope_lines_raw.economic_key_timesheet_id IS NOT NULL
    UNION
    SELECT normalised_scope_lines_raw.top_level_timesheet_id AS timesheet_id
    FROM normalised_scope_lines_raw
    WHERE normalised_scope_lines_raw.top_level_timesheet_id IS NOT NULL
  ), allocation_timesheet_id_array AS (
    SELECT COALESCE(
      array_agg(DISTINCT allocation_timesheet_refs.timesheet_id ORDER BY allocation_timesheet_refs.timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM allocation_timesheet_refs
  ), allocation_rotation_scope AS (
    SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
      rotation_scope.requested_timesheet_id,
      COALESCE(rotation_scope.canonical_timesheet_id, rotation_scope.requested_timesheet_id) AS canonical_timesheet_id,
      (rotation_scope.family_timesheet_id IS NOT NULL AND rotation_scope.family_is_current IS NOT NULL) AS rotation_scope_resolved
    FROM allocation_timesheet_id_array
    JOIN public._pay_timesheet_rotation_scope(allocation_timesheet_id_array.timesheet_ids) AS rotation_scope
      ON true
    ORDER BY
      rotation_scope.requested_timesheet_id,
      rotation_scope.family_is_current DESC NULLS LAST,
      rotation_scope.family_version DESC NULLS LAST,
      rotation_scope.family_timesheet_id
  ), normalised_scope_lines AS (
    SELECT
      normalised_scope_lines_raw.operation_id,
      normalised_scope_lines_raw.candidate_scope_id,
      normalised_scope_lines_raw.pay_batch_id,
      normalised_scope_lines_raw.workbench_session_id,
      normalised_scope_lines_raw.source_session_version,
      normalised_scope_lines_raw.candidate_id,
      normalised_scope_lines_raw.pay_channel,
      normalised_scope_lines_raw.preview_row_id,
      normalised_scope_lines_raw.row_key,
      normalised_scope_lines_raw.row_ordinal,
      jsonb_strip_nulls(
        normalised_scope_lines_raw.row_json
        || CASE
          WHEN COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id) IS NULL THEN '{}'::jsonb
          ELSE jsonb_build_object(
            'timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id)::text,
            'real_business_timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id)::text,
            'economic_key', COALESCE(normalised_scope_lines_raw.row_json->'economic_key', '{}'::jsonb)
              || jsonb_build_object('timesheet_id', COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id)::text)
          )
        END
        || CASE
          WHEN normalised_scope_lines_raw.top_level_timesheet_id IS NOT NULL
           AND normalised_scope_lines_raw.top_level_timesheet_id IS DISTINCT FROM COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id)
          THEN jsonb_build_object('rotation_requested_timesheet_id', normalised_scope_lines_raw.top_level_timesheet_id::text)
          ELSE '{}'::jsonb
        END
      ) AS row_json,
      COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id, normalised_scope_lines_raw.economic_key_timesheet_id, normalised_scope_lines_raw.top_level_timesheet_id) AS timesheet_id,
      normalised_scope_lines_raw.section,
      normalised_scope_lines_raw.key_type,
      normalised_scope_lines_raw.key_value,
      normalised_scope_lines_raw.selection_state,
      normalised_scope_lines_raw.line_status,
      normalised_scope_lines_raw.line_selected,
      normalised_scope_lines_raw.is_delta_projection,
      normalised_scope_lines_raw.projection_certified,
      normalised_scope_lines_raw.policy_x_authority_scope,
      normalised_scope_lines_raw.post_draft_overlay_unavailable,
      (
        normalised_scope_lines_raw.preview_row_id IS NULL
        OR backing_preview_row.id IS NULL
        OR UPPER(BTRIM(COALESCE(backing_preview_row.status, ''))) <> 'READY'
        OR COALESCE(backing_preview_row.selected, false) IS NOT TRUE
        OR UPPER(BTRIM(COALESCE(backing_preview_row.selection_state, ''))) <> 'SELECTED'
        OR backing_preview_row.candidate_id IS DISTINCT FROM normalised_scope_lines_raw.candidate_id
        OR private.pay_workbench_preview_effective_section_v1(
             backing_preview_row.section,
             backing_preview_row.row_json
           ) IS DISTINCT FROM COALESCE(NULLIF(BTRIM(normalised_scope_lines_raw.section), ''), 'canonical_preview_lines')
        OR NULLIF(BTRIM(backing_preview_row.row_key), '') IS DISTINCT FROM NULLIF(BTRIM(normalised_scope_lines_raw.row_key), '')
        OR (
          normalised_scope_lines_raw.finance_case_id IS NULL
          AND backing_preview_row.timesheet_id IS NULL
        )
        OR (
          normalised_scope_lines_raw.finance_case_id IS NULL
          AND backing_preview_row.timesheet_id IS DISTINCT FROM COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id, normalised_scope_lines_raw.economic_key_timesheet_id, normalised_scope_lines_raw.top_level_timesheet_id)
        )
        OR UPPER(NULLIF(BTRIM(COALESCE(backing_preview_row.key_type, backing_preview_row.row_json#>>'{economic_key,key_type}', backing_preview_row.row_json->>'component_key_type', '')), '')) IS DISTINCT FROM normalised_scope_lines_raw.key_type
        OR NULLIF(BTRIM(COALESCE(backing_preview_row.key_value, backing_preview_row.row_json#>>'{economic_key,key_value}', backing_preview_row.row_json->>'component_key_value', '')), '') IS DISTINCT FROM normalised_scope_lines_raw.key_value
        OR COALESCE(
          NULLIF(BTRIM(backing_preview_row.row_json->>'policy_x_authority_scope'), ''),
          NULLIF(BTRIM(backing_preview_row.row_json#>>'{contract_json,policy_x_authority_scope}'), ''),
          NULLIF(BTRIM(backing_preview_row.row_json#>>'{contract,policy_x_authority_scope}'), ''),
          ''
        ) <> 'PRE_DRAFT_LIVE_TRUTH'
        OR (
          (
            COALESCE(backing_preview_row.row_json->>'projection_path', '') = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
            OR backing_preview_row.row_json ? 'projection_run_id'
          )
          AND LOWER(BTRIM(COALESCE(backing_preview_row.row_json->>'projection_certified', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        OR (
          backing_preview_row.row_json ? 'selected'
          AND (LOWER(BTRIM(COALESCE(backing_preview_row.row_json->>'selected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) IS DISTINCT FROM COALESCE(backing_preview_row.selected, false)
        )
        OR (
          backing_preview_row.row_json ? 'selection_state'
          AND UPPER(BTRIM(COALESCE(backing_preview_row.row_json->>'selection_state', ''))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(backing_preview_row.selection_state, '')))
        )
        OR (
          backing_preview_row.row_json ? 'status'
          AND UPPER(BTRIM(COALESCE(backing_preview_row.row_json->>'status', ''))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(backing_preview_row.status, '')))
        )
        OR (
          LOWER(BTRIM(COALESCE(backing_preview_row.row_json->>'post_draft_overlay_applied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND (
            UPPER(BTRIM(COALESCE(backing_preview_row.row_json->>'post_draft_overlay_operation_type', ''))) IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
            OR LOWER(BTRIM(COALESCE(backing_preview_row.row_json->>'selected', 'true'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            OR UPPER(BTRIM(COALESCE(backing_preview_row.row_json->>'selection_state', backing_preview_row.selection_state, ''))) <> 'SELECTED'
            OR UPPER(BTRIM(COALESCE(backing_preview_row.row_json->>'status', backing_preview_row.status, ''))) <> 'READY'
          )
        )
      ) AS backing_table_state_invalid,
      CASE
        WHEN normalised_scope_lines_raw.preview_row_id IS NULL THEN 'ALLOCATION_BACKING_PREVIEW_ROW_ID_MISSING'
        WHEN backing_preview_row.id IS NULL THEN 'ALLOCATION_BACKING_PREVIEW_ROW_NOT_CURRENT'
        WHEN UPPER(BTRIM(COALESCE(backing_preview_row.status, ''))) <> 'READY' THEN 'ALLOCATION_BACKING_PREVIEW_ROW_NOT_READY'
        WHEN COALESCE(backing_preview_row.selected, false) IS NOT TRUE THEN 'ALLOCATION_BACKING_PREVIEW_ROW_NOT_SELECTED'
        WHEN UPPER(BTRIM(COALESCE(backing_preview_row.selection_state, ''))) <> 'SELECTED' THEN 'ALLOCATION_BACKING_PREVIEW_ROW_SELECTION_STATE_INVALID'
        WHEN backing_preview_row.candidate_id IS DISTINCT FROM normalised_scope_lines_raw.candidate_id THEN 'ALLOCATION_BACKING_PREVIEW_ROW_CANDIDATE_MISMATCH'
        WHEN private.pay_workbench_preview_effective_section_v1(
               backing_preview_row.section,
               backing_preview_row.row_json
             ) IS DISTINCT FROM COALESCE(NULLIF(BTRIM(normalised_scope_lines_raw.section), ''), 'canonical_preview_lines') THEN 'ALLOCATION_BACKING_PREVIEW_ROW_SECTION_MISMATCH'
        WHEN NULLIF(BTRIM(backing_preview_row.row_key), '') IS DISTINCT FROM NULLIF(BTRIM(normalised_scope_lines_raw.row_key), '') THEN 'ALLOCATION_BACKING_PREVIEW_ROW_KEY_MISMATCH'
        WHEN normalised_scope_lines_raw.finance_case_id IS NULL AND backing_preview_row.timesheet_id IS NULL THEN 'ALLOCATION_BACKING_PREVIEW_ROW_ECONOMIC_KEY_MISSING'
        WHEN normalised_scope_lines_raw.finance_case_id IS NULL AND backing_preview_row.timesheet_id IS DISTINCT FROM COALESCE(economic_key_rotation.canonical_timesheet_id, top_level_rotation.canonical_timesheet_id, normalised_scope_lines_raw.economic_key_timesheet_id, normalised_scope_lines_raw.top_level_timesheet_id) THEN 'ALLOCATION_BACKING_PREVIEW_ROW_TIMESHEET_MISMATCH'
        WHEN UPPER(NULLIF(BTRIM(COALESCE(backing_preview_row.key_type, backing_preview_row.row_json#>>'{economic_key,key_type}', backing_preview_row.row_json->>'component_key_type', '')), '')) IS DISTINCT FROM normalised_scope_lines_raw.key_type THEN 'ALLOCATION_BACKING_PREVIEW_ROW_KEY_TYPE_MISMATCH'
        WHEN NULLIF(BTRIM(COALESCE(backing_preview_row.key_value, backing_preview_row.row_json#>>'{economic_key,key_value}', backing_preview_row.row_json->>'component_key_value', '')), '') IS DISTINCT FROM normalised_scope_lines_raw.key_value THEN 'ALLOCATION_BACKING_PREVIEW_ROW_KEY_VALUE_MISMATCH'
        WHEN COALESCE(NULLIF(BTRIM(backing_preview_row.row_json->>'policy_x_authority_scope'), ''), NULLIF(BTRIM(backing_preview_row.row_json#>>'{contract_json,policy_x_authority_scope}'), ''), NULLIF(BTRIM(backing_preview_row.row_json#>>'{contract,policy_x_authority_scope}'), ''), '') <> 'PRE_DRAFT_LIVE_TRUTH' THEN 'ALLOCATION_BACKING_PREVIEW_ROW_POLICY_X_AUTHORITY_INVALID'
        WHEN (COALESCE(backing_preview_row.row_json->>'projection_path', '') = 'WORKBENCH_CANDIDATE_DELTA_REFRESH' OR backing_preview_row.row_json ? 'projection_run_id') AND LOWER(BTRIM(COALESCE(backing_preview_row.row_json->>'projection_certified', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'ALLOCATION_BACKING_PREVIEW_ROW_DELTA_NOT_CERTIFIED'
        WHEN LOWER(BTRIM(COALESCE(backing_preview_row.row_json->>'post_draft_overlay_applied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 'ALLOCATION_BACKING_PREVIEW_ROW_POST_DRAFT_OVERLAY_UNAVAILABLE'
        WHEN (
          (backing_preview_row.row_json ? 'selected' AND (LOWER(BTRIM(COALESCE(backing_preview_row.row_json->>'selected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) IS DISTINCT FROM COALESCE(backing_preview_row.selected, false))
          OR (backing_preview_row.row_json ? 'selection_state' AND UPPER(BTRIM(COALESCE(backing_preview_row.row_json->>'selection_state', ''))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(backing_preview_row.selection_state, ''))))
          OR (backing_preview_row.row_json ? 'status' AND UPPER(BTRIM(COALESCE(backing_preview_row.row_json->>'status', ''))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(backing_preview_row.status, ''))))
        ) THEN 'ALLOCATION_BACKING_PREVIEW_ROW_TABLE_JSON_CONFLICT'
        ELSE NULL::text
      END AS backing_table_state_failure_reason,
      normalised_scope_lines_raw.finance_case_id,
      normalised_scope_lines_raw.finance_component_id,
      normalised_scope_lines_raw.allocation_type,
      normalised_scope_lines_raw.item_direction,
      normalised_scope_lines_raw.single_fixed_reimbursement_key_type,
      normalised_scope_lines_raw.single_fixed_reimbursement_key_value,
      normalised_scope_lines_raw.source_ref,
      normalised_scope_lines_raw.allocated_amount,
      CASE
        WHEN normalised_scope_lines_raw.economic_key_timesheet_id IS NULL AND normalised_scope_lines_raw.top_level_timesheet_id IS NULL THEN false
        WHEN normalised_scope_lines_raw.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN normalised_scope_lines_raw.top_level_timesheet_id IS NOT NULL AND COALESCE(top_level_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND top_level_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM top_level_rotation.canonical_timesheet_id THEN true
        ELSE false
      END AS rotation_validation_failed,
      CASE
        WHEN normalised_scope_lines_raw.economic_key_timesheet_id IS NULL AND normalised_scope_lines_raw.top_level_timesheet_id IS NULL THEN NULL::text
        WHEN normalised_scope_lines_raw.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN 'ALLOCATION_ECONOMIC_KEY_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN normalised_scope_lines_raw.top_level_timesheet_id IS NOT NULL AND COALESCE(top_level_rotation.rotation_scope_resolved, false) = false THEN 'ALLOCATION_LINE_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND top_level_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM top_level_rotation.canonical_timesheet_id THEN 'ALLOCATION_LINE_AND_ECONOMIC_KEY_CANONICAL_TIMESHEET_MISMATCH'
        ELSE NULL::text
      END AS rotation_failure_reason
    FROM normalised_scope_lines_raw
    LEFT JOIN allocation_rotation_scope AS economic_key_rotation
      ON economic_key_rotation.requested_timesheet_id = normalised_scope_lines_raw.economic_key_timesheet_id
    LEFT JOIN allocation_rotation_scope AS top_level_rotation
      ON top_level_rotation.requested_timesheet_id = normalised_scope_lines_raw.top_level_timesheet_id
    LEFT JOIN public.banking_pay_workbench_preview_rows AS backing_preview_row
      ON backing_preview_row.id = normalised_scope_lines_raw.preview_row_id
     AND (
       normalised_scope_lines_raw.workbench_session_id IS NULL
       OR backing_preview_row.session_id = normalised_scope_lines_raw.workbench_session_id
     )
     AND (
       normalised_scope_lines_raw.source_session_version IS NULL
       OR backing_preview_row.session_version = normalised_scope_lines_raw.source_session_version
     )
  )
  SELECT
    normalised_scope_lines.*,
    jsonb_strip_nulls(jsonb_build_object(
      'timesheet_id', CASE WHEN normalised_scope_lines.timesheet_id IS NULL THEN NULL ELSE normalised_scope_lines.timesheet_id::text END,
      'key_type', normalised_scope_lines.key_type,
      'key_value', normalised_scope_lines.key_value
    )) AS economic_key_json,
    public.pay_workbench_preview_line_contract_ok(
      p_line_json => jsonb_strip_nulls(
        normalised_scope_lines.row_json
        || jsonb_build_object(
          'row_key', normalised_scope_lines.row_key,
          'preview_row_pk', CASE WHEN normalised_scope_lines.preview_row_id IS NULL THEN NULL ELSE normalised_scope_lines.preview_row_id::text END,
          'selection_state', normalised_scope_lines.selection_state
        )
      ),
      p_economic_key_json => jsonb_strip_nulls(jsonb_build_object(
        'timesheet_id', CASE WHEN normalised_scope_lines.timesheet_id IS NULL THEN NULL ELSE normalised_scope_lines.timesheet_id::text END,
        'key_type', normalised_scope_lines.key_type,
        'key_value', normalised_scope_lines.key_value
      )),
      p_target_section => normalised_scope_lines.section
    ) AS preview_contract_json
  FROM normalised_scope_lines
  ORDER BY normalised_scope_lines.pay_channel, normalised_scope_lines.candidate_id, normalised_scope_lines.row_ordinal, normalised_scope_lines.preview_row_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'preview_row_id', invalid_rows.preview_row_id::text,
           'row_key', invalid_rows.row_key,
           'candidate_id', invalid_rows.candidate_id::text,
           'candidate_scope_id', invalid_rows.candidate_scope_id::text,
           'reasons', COALESCE(invalid_rows.preview_contract_json->'reasons', '[]'::jsonb)
             || CASE WHEN invalid_rows.rotation_validation_failed IS TRUE THEN jsonb_build_array(invalid_rows.rotation_failure_reason) ELSE '[]'::jsonb END
             || CASE WHEN invalid_rows.backing_table_state_invalid IS TRUE THEN jsonb_build_array(COALESCE(invalid_rows.backing_table_state_failure_reason, 'ALLOCATION_BACKING_PREVIEW_ROW_STATE_INVALID')) ELSE '[]'::jsonb END
             || CASE
               WHEN invalid_rows.single_fixed_reimbursement_key_type IS NOT NULL
                AND (
                  invalid_rows.key_type IS DISTINCT FROM invalid_rows.single_fixed_reimbursement_key_type
                  OR invalid_rows.key_value IS DISTINCT FROM invalid_rows.single_fixed_reimbursement_key_value
                ) THEN jsonb_build_array('POLICY_X_REIMBURSEMENT_KEY_MISMATCH')
               ELSE '[]'::jsonb
             END
             || CASE
               WHEN ROUND(COALESCE(invalid_rows.allocated_amount, 0), 2) < 0
                AND NOT (
                  invalid_rows.allocation_type IN ('OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT')
                  AND invalid_rows.finance_case_id IS NOT NULL
                  AND (invalid_rows.item_direction IS NULL OR invalid_rows.item_direction = 'DEDUCTION')
                ) THEN jsonb_build_array('NEGATIVE_ENTITLEMENT_MUST_ROUTE_TO_FINANCE_CASE')
               ELSE '[]'::jsonb
             END
         ) ORDER BY invalid_rows.row_ordinal, invalid_rows.preview_row_id), '[]'::jsonb)
  INTO v_malformed_allocation_preview_rows
  FROM (
    SELECT candidate_row.*
    FROM pg_temp.tmp_pay_workbench_allocation_preview_candidates AS candidate_row
    WHERE candidate_row.rotation_validation_failed IS TRUE
       OR LOWER(BTRIM(COALESCE(candidate_row.preview_contract_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR LOWER(BTRIM(COALESCE(candidate_row.preview_contract_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR candidate_row.preview_row_id IS NULL
       OR COALESCE(candidate_row.backing_table_state_invalid, false) IS TRUE
       OR lower(COALESCE(candidate_row.section, '')) <> 'canonical_preview_lines'
       OR UPPER(BTRIM(COALESCE(candidate_row.selection_state, ''))) <> 'SELECTED'
       OR UPPER(BTRIM(COALESCE(candidate_row.line_status, ''))) <> 'READY'
       OR COALESCE(candidate_row.line_selected, false) IS NOT TRUE
       OR (COALESCE(candidate_row.is_delta_projection, false) IS TRUE AND COALESCE(candidate_row.projection_certified, false) IS NOT TRUE)
       OR COALESCE(candidate_row.policy_x_authority_scope, '') <> 'PRE_DRAFT_LIVE_TRUTH'
       OR (candidate_row.timesheet_id IS NULL AND candidate_row.finance_case_id IS NULL)
       OR COALESCE(candidate_row.post_draft_overlay_unavailable, false) IS TRUE
       OR candidate_row.pay_channel NOT IN ('PAYE', 'UMBRELLA')
       OR (
         candidate_row.key_type NOT IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
         AND NOT (candidate_row.finance_case_id IS NOT NULL AND candidate_row.key_type IN ('CASE_TOTAL','FINANCE_COMPONENT'))
       )
       OR candidate_row.key_value IS NULL
       OR (
         candidate_row.single_fixed_reimbursement_key_type IS NOT NULL
         AND (
           candidate_row.key_type IS DISTINCT FROM candidate_row.single_fixed_reimbursement_key_type
           OR candidate_row.key_value IS DISTINCT FROM candidate_row.single_fixed_reimbursement_key_value
         )
       )
       OR (candidate_row.key_type = 'TS_DAY' AND candidate_row.key_value !~ '^\d{4}-\d{2}-\d{2}$')
       OR candidate_row.allocated_amount IS NULL
       OR ROUND(COALESCE(candidate_row.allocated_amount, 0), 2) = 0
       OR (
         ROUND(COALESCE(candidate_row.allocated_amount, 0), 2) < 0
         AND NOT (
           candidate_row.allocation_type IN ('OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT')
           AND candidate_row.finance_case_id IS NOT NULL
           AND (candidate_row.item_direction IS NULL OR candidate_row.item_direction = 'DEDUCTION')
         )
       )
    ORDER BY candidate_row.row_ordinal, candidate_row.preview_row_id
    LIMIT 25
  ) AS invalid_rows;

  IF jsonb_array_length(COALESCE(v_malformed_allocation_preview_rows, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE',
              'operation_id', p_operation_id::text,
              'malformed_selected_preview_rows', COALESCE(v_malformed_allocation_preview_rows, '[]'::jsonb),
              'message', 'Selected preview rows cannot be converted into allocation rows because they are not valid draftable Ready to Pay rows.'
            )::text;
  END IF;

  -- A set of individually valid deduction rows is not by itself a valid Draft
  -- candidate.  Headroom is candidate-local and is calculated only from the
  -- positive ordinary rows actually selected into this Draft operation.
  IF COALESCE(v_semantic_draft_guard_enabled, false) THEN
    SELECT COUNT(*)::integer
    INTO v_semantic_source_failure_count
    FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope
    WHERE selected_scope.allocation_basis_json#>>'{source_publication_attestation,attestation_version}'
            IS DISTINCT FROM 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
       OR selected_scope.allocation_basis_json#>>'{source_publication_attestation,semantic_contract_version}'
            IS DISTINCT FROM 'READY_TO_PAY_SEMANTIC_V2'
       OR COALESCE((selected_scope.allocation_basis_json#>>'{source_publication_attestation,semantic_ready}')::boolean,false)
            IS NOT TRUE
       OR NULLIF(selected_scope.allocation_basis_json->>'semantic_proof_digest','') IS NULL
       OR NULLIF(selected_scope.allocation_basis_json->>'source_build_run_id','') IS NULL
       OR (
         v_source_publication_identity_enforce_enabled
         AND COALESCE(selected_scope.allocation_basis_json->>'source_publication_id','')
           !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       )
       OR (
         COALESCE(selected_scope.allocation_basis_json->>'source_publication_id','')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         AND NOT EXISTS (
           SELECT 1
           FROM public.banking_pay_workbench_session_scope AS source_scope
           WHERE source_scope.session_id=selected_scope.workbench_session_id
             AND source_scope.candidate_id=selected_scope.candidate_id
             AND source_scope.certified_preview_publication_parity_ok IS TRUE
             AND source_scope.certified_preview_publication_session_version=selected_scope.source_session_version
             AND source_scope.certified_preview_publication_source_publication_id=
                   (selected_scope.allocation_basis_json->>'source_publication_id')::uuid
             AND source_scope.certified_preview_publication_attestation_json->>'source_publication_id'=
                   selected_scope.allocation_basis_json->>'source_publication_id'
         )
       );

    IF v_semantic_source_failure_count > 0 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_SOURCE_SEMANTIC_CERTIFICATION_REQUIRED'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','PAY_WORKBENCH_DRAFT_SOURCE_SEMANTIC_CERTIFICATION_REQUIRED',
          'candidate_scope_count',v_semantic_source_failure_count,
          'message','Allocation seeding requires the V3 semantic source frozen by Draft scope creation.'
        )::text;
    END IF;

    WITH candidate_semantics AS (
      SELECT
        candidate_row.candidate_id,
        candidate_row.candidate_scope_id,
        ROUND(COALESCE(SUM(candidate_row.allocated_amount) FILTER (
          WHERE candidate_row.allocated_amount > 0
            AND candidate_row.allocation_type = 'TIMESHEET_PAYMENT'
            AND COALESCE((candidate_row.preview_contract_json->>'ok')::boolean, false)
            AND COALESCE((candidate_row.preview_contract_json->>'selection_allowed')::boolean, false)
        ), 0), 2) AS selected_positive_ordinary_amount,
        ROUND(COALESCE(SUM(candidate_row.allocated_amount) FILTER (
          WHERE candidate_row.allocated_amount < 0
            AND candidate_row.allocation_type IN (
              'OVERPAYMENT_RECOVERY',
              'MANUAL_DEBT_RECOVERY',
              'PAYMENT_ADVANCE_REPAYMENT',
              'LOAN_REPAYMENT'
            )
            AND candidate_row.finance_case_id IS NOT NULL
            AND (candidate_row.item_direction IS NULL OR candidate_row.item_direction = 'DEDUCTION')
            AND COALESCE((candidate_row.preview_contract_json->>'ok')::boolean, false)
            AND COALESCE((candidate_row.preview_contract_json->>'selection_allowed')::boolean, false)
        ), 0), 2) AS selected_deduction_amount
      FROM pg_temp.tmp_pay_workbench_allocation_preview_candidates AS candidate_row
      WHERE candidate_row.line_selected IS TRUE
        AND UPPER(COALESCE(candidate_row.selection_state, '')) = 'SELECTED'
        AND UPPER(COALESCE(candidate_row.line_status, '')) = 'READY'
      GROUP BY candidate_row.candidate_id, candidate_row.candidate_scope_id
    ), failed AS (
      SELECT
        candidate_semantics.*,
        ROUND(candidate_semantics.selected_positive_ordinary_amount
          + candidate_semantics.selected_deduction_amount, 2) AS selected_candidate_result,
        CASE
          WHEN candidate_semantics.selected_deduction_amount < 0
           AND candidate_semantics.selected_positive_ordinary_amount <= 0
            THEN 'PAY_WORKBENCH_DRAFT_RECOVERY_WITHOUT_POSITIVE_HEADROOM'
          WHEN -candidate_semantics.selected_deduction_amount
             > candidate_semantics.selected_positive_ordinary_amount
            THEN 'PAY_WORKBENCH_DRAFT_DEDUCTION_EXCEEDS_SELECTED_HEADROOM'
          WHEN candidate_semantics.selected_positive_ordinary_amount
             + candidate_semantics.selected_deduction_amount < 0
            THEN 'PAY_WORKBENCH_DRAFT_CANDIDATE_RESULT_NEGATIVE'
          ELSE NULL
        END AS failure_code
      FROM candidate_semantics
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'candidate_id', failed.candidate_id::text,
      'candidate_scope_id', failed.candidate_scope_id::text,
      'selected_positive_ordinary_amount', failed.selected_positive_ordinary_amount,
      'selected_deduction_amount', failed.selected_deduction_amount,
      'selected_candidate_result', failed.selected_candidate_result,
      'code', failed.failure_code
    ) ORDER BY failed.candidate_id), '[]'::jsonb)
    INTO v_semantic_draft_failures
    FROM failed
    WHERE failed.failure_code IS NOT NULL;

    IF jsonb_array_length(COALESCE(v_semantic_draft_failures, '[]'::jsonb)) > 0 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_SELECTED_SEMANTIC_PROOF_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DRAFT_SELECTED_SEMANTIC_PROOF_FAILED',
                'operation_id', p_operation_id::text,
                'candidate_failures', v_semantic_draft_failures,
                'message', 'Draft selection requires positive ordinary entitlement for the same candidate, deductions within selected headroom, and a non-negative candidate result.'
              )::text;
    END IF;
  END IF;


  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'preview_row_id', CASE WHEN synthetic_total_rows.preview_row_id IS NULL THEN NULL ELSE synthetic_total_rows.preview_row_id::text END,
           'row_key', synthetic_total_rows.row_key,
           'candidate_id', synthetic_total_rows.candidate_id::text,
           'candidate_scope_id', synthetic_total_rows.candidate_scope_id::text,
           'timesheet_id', CASE WHEN synthetic_total_rows.timesheet_id IS NULL THEN NULL ELSE synthetic_total_rows.timesheet_id::text END,
           'key_type', synthetic_total_rows.key_type,
           'key_value', synthetic_total_rows.key_value,
           'allocated_amount', synthetic_total_rows.allocated_amount,
           'reason', 'RESOLVED_SYNTHETIC_TOTAL_ROW_ALLOCATION_BLOCKED'
         ) ORDER BY synthetic_total_rows.row_ordinal, synthetic_total_rows.preview_row_id), '[]'::jsonb)
  INTO v_synthetic_total_allocation_preview_rows
  FROM pg_temp.tmp_pay_workbench_allocation_preview_candidates AS synthetic_total_rows
  WHERE UPPER(BTRIM(COALESCE(synthetic_total_rows.key_type, synthetic_total_rows.row_json#>>'{economic_key,key_type}', ''))) = 'TS_TOTAL'
    AND UPPER(BTRIM(COALESCE(synthetic_total_rows.key_value, synthetic_total_rows.row_json#>>'{economic_key,key_value}', ''))) = 'TOTAL'
    AND LOWER(BTRIM(COALESCE(synthetic_total_rows.source_ref, synthetic_total_rows.row_key, synthetic_total_rows.row_json->>'row_key', synthetic_total_rows.row_json->>'line_key', synthetic_total_rows.row_json->>'source_ref', ''))) LIKE '%:non_segment:total%'
    AND (
      lower(btrim(coalesce(synthetic_total_rows.row_json->>'resolved_segment_rows_replace_source_total', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json#>>'{case_resolution_summary,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_applied}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_active}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR (
        COALESCE(synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_component_count}', '') ~ '^[0-9]+$'
        AND (synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_component_count}')::integer > 0
      )
      OR EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_workbench_allocation_preview_candidates AS sibling_segment
        WHERE sibling_segment.candidate_id = synthetic_total_rows.candidate_id
          AND sibling_segment.candidate_scope_id = synthetic_total_rows.candidate_scope_id
          AND sibling_segment.timesheet_id IS NOT DISTINCT FROM synthetic_total_rows.timesheet_id
          AND UPPER(BTRIM(COALESCE(sibling_segment.key_type, sibling_segment.row_json#>>'{economic_key,key_type}', ''))) = 'TS_DAY'
          AND LOWER(BTRIM(COALESCE(sibling_segment.source_ref, sibling_segment.row_key, sibling_segment.row_json->>'row_key', sibling_segment.row_json->>'line_key', sibling_segment.row_json->>'source_ref', ''))) LIKE '%:segment:%'
      )
    );

  IF jsonb_array_length(COALESCE(v_synthetic_total_allocation_preview_rows, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'RESOLVED_SYNTHETIC_TOTAL_ROW_ALLOCATION_BLOCKED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'RESOLVED_SYNTHETIC_TOTAL_ROW_ALLOCATION_BLOCKED',
              'operation_id', p_operation_id::text,
              'synthetic_total_allocation_preview_rows', COALESCE(v_synthetic_total_allocation_preview_rows, '[]'::jsonb),
              'message', 'A stale resolved-timesheet synthetic total row reached allocation scope. Refresh Banking Pay and try Create Draft again.'
            )::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_allocation_expected_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_allocation_expected_rows ON COMMIT DROP AS
  WITH selected_preview_rows AS (
    SELECT candidate_row.*
    FROM pg_temp.tmp_pay_workbench_allocation_preview_candidates AS candidate_row
    WHERE candidate_row.rotation_validation_failed IS NOT TRUE
      AND LOWER(BTRIM(COALESCE(candidate_row.preview_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(candidate_row.preview_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND candidate_row.preview_row_id IS NOT NULL
      AND COALESCE(candidate_row.backing_table_state_invalid, false) IS NOT TRUE
      AND lower(COALESCE(candidate_row.section, '')) = 'canonical_preview_lines'
      AND UPPER(BTRIM(COALESCE(candidate_row.selection_state, ''))) = 'SELECTED'
      AND UPPER(BTRIM(COALESCE(candidate_row.line_status, ''))) = 'READY'
      AND COALESCE(candidate_row.line_selected, false) IS TRUE
      AND (COALESCE(candidate_row.is_delta_projection, false) IS NOT TRUE OR COALESCE(candidate_row.projection_certified, false) IS TRUE)
      AND COALESCE(candidate_row.policy_x_authority_scope, '') = 'PRE_DRAFT_LIVE_TRUTH'
      AND (candidate_row.timesheet_id IS NOT NULL OR candidate_row.finance_case_id IS NOT NULL)
      AND COALESCE(candidate_row.post_draft_overlay_unavailable, false) IS NOT TRUE
      AND candidate_row.pay_channel IN ('PAYE', 'UMBRELLA')
      AND (
        candidate_row.key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
        OR (candidate_row.finance_case_id IS NOT NULL AND candidate_row.key_type IN ('CASE_TOTAL','FINANCE_COMPONENT'))
      )
      AND candidate_row.key_value IS NOT NULL
      AND NOT (
        candidate_row.single_fixed_reimbursement_key_type IS NOT NULL
        AND (
          candidate_row.key_type IS DISTINCT FROM candidate_row.single_fixed_reimbursement_key_type
          OR candidate_row.key_value IS DISTINCT FROM candidate_row.single_fixed_reimbursement_key_value
        )
      )
      AND NOT (candidate_row.key_type = 'TS_DAY' AND candidate_row.key_value !~ '^\d{4}-\d{2}-\d{2}$')
      AND candidate_row.allocated_amount IS NOT NULL
      AND ROUND(COALESCE(candidate_row.allocated_amount, 0), 2) <> 0
      AND (
        ROUND(COALESCE(candidate_row.allocated_amount, 0), 2) > 0
        OR (
          candidate_row.allocation_type IN ('OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT')
          AND candidate_row.finance_case_id IS NOT NULL
          AND (candidate_row.item_direction IS NULL OR candidate_row.item_direction = 'DEDUCTION')
        )
      )
  )
  , finance_component_source_rows AS (
    SELECT
      selected_preview_rows.*,
      component_element.ordinality::integer AS finance_component_ordinality,
      component_element.value AS finance_component_json,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(component_element.value->>'finance_component_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(component_element.value->>'finance_component_id', '')), '')::uuid
        ELSE selected_preview_rows.finance_component_id
      END AS effective_finance_component_id,
      UPPER(COALESCE(
        NULLIF(BTRIM(component_element.value->>'component_key_type'), ''),
        selected_preview_rows.key_type,
        'CASE_TOTAL'
      )) AS effective_key_type,
      COALESCE(
        NULLIF(BTRIM(component_element.value->>'component_key_value'), ''),
        selected_preview_rows.key_value,
        'TOTAL'
      ) AS effective_key_value,
      ROUND(COALESCE(
        CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'preview_due_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'allocated_source_due_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'target_pay_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'ready_preview_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'preview_component_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'component_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        ABS(COALESCE(selected_preview_rows.allocated_amount, 0))
      ), 2) AS raw_component_abs_amount,
      ROW_NUMBER() OVER (
        PARTITION BY selected_preview_rows.operation_id, selected_preview_rows.candidate_scope_id, selected_preview_rows.preview_row_id
        ORDER BY component_element.ordinality
      ) AS component_rn,
      COUNT(*) OVER (
        PARTITION BY selected_preview_rows.operation_id, selected_preview_rows.candidate_scope_id, selected_preview_rows.preview_row_id
      ) AS component_count,
      ROUND(SUM(ROUND(COALESCE(
        CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'preview_due_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'allocated_source_due_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'target_pay_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'ready_preview_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'preview_component_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'component_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        ABS(COALESCE(selected_preview_rows.allocated_amount, 0))
      ), 2)) OVER (
        PARTITION BY selected_preview_rows.operation_id, selected_preview_rows.candidate_scope_id, selected_preview_rows.preview_row_id
      ), 2) AS component_abs_amount_sum,
      ROUND(COALESCE(SUM(ROUND(COALESCE(
        CASE WHEN COALESCE(component_element.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'preview_due_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'allocated_source_due_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'target_pay_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'ready_preview_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'preview_component_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        CASE WHEN COALESCE(component_element.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ABS((component_element.value->>'component_amount_ex_vat')::numeric) ELSE NULL::numeric END,
        ABS(COALESCE(selected_preview_rows.allocated_amount, 0))
      ), 2)) OVER (
        PARTITION BY selected_preview_rows.operation_id, selected_preview_rows.candidate_scope_id, selected_preview_rows.preview_row_id
        ORDER BY component_element.ordinality
        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
      ), 0), 2) AS preceding_component_abs_amount
    FROM selected_preview_rows
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN selected_preview_rows.finance_case_id IS NOT NULL
         AND jsonb_typeof(selected_preview_rows.row_json->'case_components') = 'array'
         AND jsonb_array_length(selected_preview_rows.row_json->'case_components') > 0
          THEN selected_preview_rows.row_json->'case_components'
        ELSE '[]'::jsonb
      END
    ) WITH ORDINALITY AS component_element(value, ordinality)
    WHERE selected_preview_rows.finance_case_id IS NOT NULL
      AND jsonb_typeof(component_element.value) = 'object'
  ), allocation_expanded_rows AS (
    SELECT
      selected_preview_rows.operation_id,
      selected_preview_rows.candidate_scope_id,
      selected_preview_rows.pay_batch_id,
      selected_preview_rows.candidate_id,
      selected_preview_rows.preview_row_id,
      selected_preview_rows.row_key,
      selected_preview_rows.timesheet_id,
      selected_preview_rows.key_type,
      selected_preview_rows.key_value,
      selected_preview_rows.pay_channel,
      selected_preview_rows.finance_case_id,
      selected_preview_rows.finance_component_id,
      selected_preview_rows.allocation_type,
      selected_preview_rows.source_ref,
      selected_preview_rows.operation_id::text || ':allocation:' || selected_preview_rows.candidate_scope_id::text || ':' || selected_preview_rows.preview_row_id::text AS operation_source_key,
      selected_preview_rows.allocated_amount,
      selected_preview_rows.preview_contract_json,
      selected_preview_rows.item_direction,
      selected_preview_rows.row_json,
      selected_preview_rows.row_ordinal,
      NULL::jsonb AS finance_component_json,
      NULL::integer AS finance_component_ordinality
    FROM selected_preview_rows
    WHERE selected_preview_rows.finance_case_id IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM finance_component_source_rows AS component_probe
         WHERE component_probe.operation_id = selected_preview_rows.operation_id
           AND component_probe.candidate_scope_id = selected_preview_rows.candidate_scope_id
           AND component_probe.preview_row_id = selected_preview_rows.preview_row_id
       )

    UNION ALL

    SELECT
      finance_component_source_rows.operation_id,
      finance_component_source_rows.candidate_scope_id,
      finance_component_source_rows.pay_batch_id,
      finance_component_source_rows.candidate_id,
      finance_component_source_rows.preview_row_id,
      finance_component_source_rows.row_key,
      finance_component_source_rows.timesheet_id,
      finance_component_source_rows.effective_key_type AS key_type,
      finance_component_source_rows.effective_key_value AS key_value,
      finance_component_source_rows.pay_channel,
      finance_component_source_rows.finance_case_id,
      finance_component_source_rows.effective_finance_component_id AS finance_component_id,
      finance_component_source_rows.allocation_type,
      finance_component_source_rows.source_ref,
      finance_component_source_rows.operation_id::text || ':allocation:' || finance_component_source_rows.candidate_scope_id::text || ':' || finance_component_source_rows.preview_row_id::text || ':component:' || COALESCE(finance_component_source_rows.effective_finance_component_id::text, md5(finance_component_source_rows.finance_component_json::text)) AS operation_source_key,
      CASE
        WHEN ROUND(COALESCE(finance_component_source_rows.allocated_amount, 0), 2) < 0 THEN -1
        ELSE 1
      END * ROUND(
        LEAST(
          COALESCE(finance_component_source_rows.raw_component_abs_amount, 0),
          GREATEST(
            ABS(COALESCE(finance_component_source_rows.allocated_amount, 0))
              - COALESCE(finance_component_source_rows.preceding_component_abs_amount, 0),
            0
          )
        ),
        2
      ) AS allocated_amount,
      finance_component_source_rows.preview_contract_json,
      finance_component_source_rows.item_direction,
      jsonb_strip_nulls(
        finance_component_source_rows.row_json
        || jsonb_build_object(
          'finance_component_id', CASE WHEN finance_component_source_rows.effective_finance_component_id IS NULL THEN NULL ELSE finance_component_source_rows.effective_finance_component_id::text END,
          'component_key_type', finance_component_source_rows.effective_key_type,
          'component_key_value', finance_component_source_rows.effective_key_value,
          'key_type', finance_component_source_rows.effective_key_type,
          'key_value', finance_component_source_rows.effective_key_value,
          'component', finance_component_source_rows.finance_component_json
        )
      ) AS row_json,
      (finance_component_source_rows.row_ordinal * 1000 + finance_component_source_rows.finance_component_ordinality)::bigint AS row_ordinal,
      finance_component_source_rows.finance_component_json,
      finance_component_source_rows.finance_component_ordinality
    FROM finance_component_source_rows
    WHERE ROUND(COALESCE(finance_component_source_rows.raw_component_abs_amount, 0), 2) > 0
  )
  SELECT
    allocation_expanded_rows.operation_id,
    allocation_expanded_rows.candidate_scope_id,
    allocation_expanded_rows.pay_batch_id,
    allocation_expanded_rows.candidate_id,
    allocation_expanded_rows.preview_row_id,
    allocation_expanded_rows.row_key,
    allocation_expanded_rows.timesheet_id,
    allocation_expanded_rows.key_type,
    allocation_expanded_rows.key_value,
    allocation_expanded_rows.pay_channel,
    allocation_expanded_rows.finance_case_id,
    allocation_expanded_rows.finance_component_id,
    allocation_expanded_rows.allocation_type,
    allocation_expanded_rows.source_ref,
    allocation_expanded_rows.operation_source_key,
    allocation_expanded_rows.allocated_amount,
    jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'preview_row_id', allocation_expanded_rows.preview_row_id::text,
      'row_key', allocation_expanded_rows.row_key,
      'row_ordinal', allocation_expanded_rows.row_ordinal,
      'timesheet_id', CASE WHEN allocation_expanded_rows.timesheet_id IS NULL THEN NULL ELSE allocation_expanded_rows.timesheet_id::text END,
      'key_type', allocation_expanded_rows.key_type,
      'key_value', allocation_expanded_rows.key_value,
      'allocation_type', allocation_expanded_rows.allocation_type,
      'item_direction', allocation_expanded_rows.item_direction,
      'finance_case_id', CASE WHEN allocation_expanded_rows.finance_case_id IS NULL THEN NULL ELSE allocation_expanded_rows.finance_case_id::text END,
      'finance_component_id', CASE WHEN allocation_expanded_rows.finance_component_id IS NULL THEN NULL ELSE allocation_expanded_rows.finance_component_id::text END,
      'finance_component', allocation_expanded_rows.finance_component_json,
      'economic_key', jsonb_strip_nulls(jsonb_build_object(
        'timesheet_id', CASE WHEN allocation_expanded_rows.timesheet_id IS NULL THEN NULL ELSE allocation_expanded_rows.timesheet_id::text END,
        'key_type', allocation_expanded_rows.key_type,
        'key_value', allocation_expanded_rows.key_value
      )),
      'preview_contract', allocation_expanded_rows.preview_contract_json,
      'line', jsonb_strip_nulls(
        allocation_expanded_rows.row_json
        || jsonb_build_object(
          'row_key', allocation_expanded_rows.row_key,
          'preview_row_pk', allocation_expanded_rows.preview_row_id::text,
          'selection_state', 'SELECTED'
        )
      )
    ) AS allocation_basis_json,
    row_number() OVER (
      PARTITION BY
        allocation_expanded_rows.operation_id,
        allocation_expanded_rows.candidate_scope_id
      ORDER BY
        allocation_expanded_rows.row_ordinal,
        allocation_expanded_rows.preview_row_id,
        allocation_expanded_rows.operation_source_key
    )::integer AS sort_order
  FROM allocation_expanded_rows
  WHERE ROUND(COALESCE(allocation_expanded_rows.allocated_amount, 0), 2) <> 0;


  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'preview_row_id', synthetic_total_rows.preview_row_id::text,
           'row_key', synthetic_total_rows.row_key,
           'candidate_id', synthetic_total_rows.candidate_id::text,
           'candidate_scope_id', synthetic_total_rows.candidate_scope_id::text,
           'timesheet_id', CASE WHEN synthetic_total_rows.timesheet_id IS NULL THEN NULL ELSE synthetic_total_rows.timesheet_id::text END,
           'key_type', synthetic_total_rows.key_type,
           'key_value', synthetic_total_rows.key_value,
           'allocated_amount', synthetic_total_rows.allocated_amount,
           'reason', 'RESOLVED_SYNTHETIC_TOTAL_ROW_ALLOCATION_BLOCKED'
         ) ORDER BY synthetic_total_rows.sort_order, synthetic_total_rows.preview_row_id), '[]'::jsonb)
  INTO v_synthetic_total_allocation_preview_rows
  FROM pg_temp.tmp_pay_workbench_allocation_expected_rows AS synthetic_total_rows
  WHERE UPPER(BTRIM(COALESCE(synthetic_total_rows.key_type, synthetic_total_rows.allocation_basis_json#>>'{economic_key,key_type}', ''))) = 'TS_TOTAL'
    AND UPPER(BTRIM(COALESCE(synthetic_total_rows.key_value, synthetic_total_rows.allocation_basis_json#>>'{economic_key,key_value}', ''))) = 'TOTAL'
    AND LOWER(BTRIM(COALESCE(synthetic_total_rows.source_ref, synthetic_total_rows.row_key, synthetic_total_rows.allocation_basis_json#>>'{line,row_key}', synthetic_total_rows.allocation_basis_json#>>'{line,line_key}', synthetic_total_rows.allocation_basis_json#>>'{line,source_ref}', ''))) LIKE '%:non_segment:total%'
    AND (
      lower(btrim(coalesce(synthetic_total_rows.allocation_basis_json#>>'{line,resolved_segment_rows_replace_source_total}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.allocation_basis_json#>>'{line,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.allocation_basis_json#>>'{line,case_resolution_summary,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_applied}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_active}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR (
        COALESCE(synthetic_total_rows.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_component_count}', '') ~ '^[0-9]+$'
        AND (synthetic_total_rows.allocation_basis_json#>>'{line,case_resolution_summary,resolved_rate_component_count}')::integer > 0
      )
      OR EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_workbench_allocation_expected_rows AS sibling_segment
        WHERE sibling_segment.candidate_id = synthetic_total_rows.candidate_id
          AND sibling_segment.candidate_scope_id = synthetic_total_rows.candidate_scope_id
          AND sibling_segment.timesheet_id IS NOT DISTINCT FROM synthetic_total_rows.timesheet_id
          AND UPPER(BTRIM(COALESCE(sibling_segment.key_type, sibling_segment.allocation_basis_json#>>'{economic_key,key_type}', ''))) = 'TS_DAY'
          AND LOWER(BTRIM(COALESCE(sibling_segment.source_ref, sibling_segment.row_key, sibling_segment.allocation_basis_json#>>'{line,row_key}', sibling_segment.allocation_basis_json#>>'{line,line_key}', sibling_segment.allocation_basis_json#>>'{line,source_ref}', ''))) LIKE '%:segment:%'
      )
    );

  IF jsonb_array_length(COALESCE(v_synthetic_total_allocation_preview_rows, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'RESOLVED_SYNTHETIC_TOTAL_ROW_ALLOCATION_BLOCKED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'RESOLVED_SYNTHETIC_TOTAL_ROW_ALLOCATION_BLOCKED',
              'operation_id', p_operation_id::text,
              'synthetic_total_allocation_preview_rows', COALESCE(v_synthetic_total_allocation_preview_rows, '[]'::jsonb),
              'message', 'A stale resolved-timesheet synthetic total row reached allocation. Refresh Banking Pay and try Create Draft again.'
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_expected_count
  FROM pg_temp.tmp_pay_workbench_allocation_expected_rows AS expected_row_count;

  IF COALESCE(v_expected_count, 0) = 0 AND EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope
    WHERE COALESCE(selected_scope.candidate_totals_json->>'selected_row_count_seeded_in_page', '0') ~ '^[0-9]+$'
      AND (selected_scope.candidate_totals_json->>'selected_row_count_seeded_in_page')::integer > 0
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_allocation_rows AS existing_row
        WHERE existing_row.operation_id = p_operation_id
          AND existing_row.candidate_scope_id = selected_scope.id
      )
  ) THEN
    RAISE EXCEPTION 'DRAFT_ALLOCATION_ROWS_EMPTY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_ALLOCATION_ROWS_EMPTY',
              'operation_id', p_operation_id::text,
              'candidate_scopes_processed', COALESCE(v_candidate_scopes_processed, 0),
              'message', 'Row-backed candidate scope did not contain draftable selected preview lines for allocation.'
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_reused
  FROM public.banking_pay_operation_candidate_allocation_rows AS existing_row
  WHERE existing_row.operation_id = p_operation_id
    AND existing_row.candidate_scope_id IN (SELECT selected_scope.id FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope);

  IF COALESCE(v_expected_count, 0) > 0 THEN
    WITH inserted_rows AS (
      INSERT INTO public.banking_pay_operation_candidate_allocation_rows (
        operation_id,
        candidate_scope_id,
        pay_batch_id,
        candidate_id,
        pay_channel,
        finance_case_id,
        finance_component_id,
        allocation_type,
        source_ref,
        operation_source_key,
        allocated_amount,
        allocation_basis_json,
        sort_order,
        status,
        created_at_utc,
        updated_at_utc
      )
      SELECT
        expected_row.operation_id,
        expected_row.candidate_scope_id,
        expected_row.pay_batch_id,
        expected_row.candidate_id,
        expected_row.pay_channel,
        expected_row.finance_case_id,
        expected_row.finance_component_id,
        expected_row.allocation_type,
        expected_row.source_ref,
        expected_row.operation_source_key,
        expected_row.allocated_amount,
        expected_row.allocation_basis_json,
        expected_row.sort_order,
        'PENDING',
        v_now,
        v_now
      FROM pg_temp.tmp_pay_workbench_allocation_expected_rows AS expected_row
      ON CONFLICT (operation_id, operation_source_key) DO NOTHING
      RETURNING public.banking_pay_operation_candidate_allocation_rows.id
    )
    SELECT COUNT(*)::integer
    INTO v_inserted
    FROM inserted_rows;
  ELSE
    v_inserted := 0;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'allocation_source_key', plan_row.allocation_source_key,
           'existing_plan_digest', existing_row.allocation_basis_json#>>'{draft_finance_item_plan,plan_digest}',
           'current_plan_digest', plan_row.plan_digest
         ) ORDER BY plan_row.allocation_source_key), '[]'::jsonb)
  INTO v_plan_drift_details
  FROM private.pay_workbench_draft_finance_item_plan_v1(p_operation_id, v_plan_scope_ids) AS plan_row
  JOIN public.banking_pay_operation_candidate_allocation_rows AS existing_row
    ON existing_row.operation_id = plan_row.operation_id
   AND existing_row.operation_source_key = plan_row.allocation_source_key
  WHERE existing_row.allocation_basis_json ? 'draft_finance_item_plan'
    AND NULLIF(existing_row.allocation_basis_json#>>'{draft_finance_item_plan,plan_digest}', '')
        IS DISTINCT FROM plan_row.plan_digest;

  IF jsonb_array_length(COALESCE(v_plan_drift_details, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'DRAFT_FINANCE_ITEM_PLAN_DRIFT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_FINANCE_ITEM_PLAN_DRIFT',
              'operation_id', p_operation_id::text,
              'mismatches', v_plan_drift_details,
              'message', 'Frozen Draft finance allocation evidence no longer matches its canonical item plan.'
            )::text;
  END IF;

  WITH current_plan AS (
    SELECT *
    FROM private.pay_workbench_draft_finance_item_plan_v1(p_operation_id, v_plan_scope_ids)
  )
  UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
  SET allocation_basis_json = COALESCE(allocation_update.allocation_basis_json, '{}'::jsonb)
        || jsonb_build_object(
             'draft_finance_item_plan',
             jsonb_build_object(
               'contract_version', 1,
               'planned_item_key', current_plan.planned_item_key,
               'planned_item_type', current_plan.planned_item_type,
               'contribution_amount', current_plan.contribution_amount,
               'planned_item_amount', current_plan.planned_item_amount,
               'contribution_count', current_plan.contribution_count,
               'plan_digest', current_plan.plan_digest
             )
           ),
      updated_at_utc = v_now
  FROM current_plan
  WHERE allocation_update.operation_id = current_plan.operation_id
    AND allocation_update.operation_source_key = current_plan.allocation_source_key
    AND allocation_update.allocation_basis_json#>>'{draft_finance_item_plan,plan_digest}' IS DISTINCT FROM current_plan.plan_digest;

  UPDATE public.banking_pay_operation_candidate_scope AS scope_update
  SET status = CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_allocation_rows AS existing_row
          WHERE existing_row.operation_id = scope_update.operation_id
            AND existing_row.candidate_scope_id = scope_update.id
        ) THEN 'ALLOCATED'
        ELSE scope_update.status
      END,
      updated_at_utc = v_now
  WHERE scope_update.operation_id = p_operation_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_workbench_allocation_scope_rows AS selected_scope
      WHERE selected_scope.id = scope_update.id
    );

  UPDATE public.banking_pay_operations AS operation_update
  SET updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN QUERY
  SELECT
    COALESCE(v_candidate_scopes_processed, 0),
    COALESCE(v_inserted, 0),
    COALESCE(v_reused, 0),
    0::integer;
END;
$function$;

-- pay_workbench_prepare_draft_scope_seed(uuid,uuid,uuid,jsonb,text,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_prepare_draft_scope_seed(p_operation_id uuid, p_workbench_session_id uuid, p_actor_user_id uuid, p_selected_preview_row_ids jsonb DEFAULT NULL::jsonb, p_pay_channel_scope text DEFAULT NULL::text, p_same_week_paye_override_json jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(candidate_scope_count integer, selected_row_count integer, timesheet_count integer, finance_case_count integer, pay_channel_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation public.banking_pay_operations%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_filter text := UPPER(COALESCE(NULLIF(BTRIM(p_pay_channel_scope), ''), 'ALL'));
  v_selected_input_count integer := 0;
  v_candidate_scope_count integer := 0;
  v_selected_count integer := 0;
  v_timesheet_count integer := 0;
  v_finance_case_count integer := 0;
  v_pay_channel_count integer := 0;
  v_stale_selection_ids jsonb := '[]'::jsonb;
  v_missing_selection_ids jsonb := '[]'::jsonb;
  v_malformed_selected_preview_rows jsonb := '[]'::jsonb;
  v_synthetic_total_selected_preview_rows jsonb := '[]'::jsonb;
  v_selection_resolved_to_current boolean := false;
  v_resolved_current_selection_ids jsonb := '[]'::jsonb;
  v_resolved_selection_match_count integer := 0;
  v_resolved_selection_distinct_count integer := 0;
  v_active_workbench_job_count integer := 0;
  v_active_workbench_job_sample jsonb := '[]'::jsonb;
  v_stale_candidate_authority_count integer := 0;
  v_stale_candidate_authority_sample jsonb := '[]'::jsonb;
  v_scope_generation_start bigint := 0;
  v_scope_generation_final bigint := 0;
  v_scope_upstream_active_count integer := 0;
  v_scope_upstream_failed_count integer := 0;
  v_scope_blocker jsonb := '{}'::jsonb;
  v_scope_shadow_mode boolean := false;
  v_operation_scope_hash text := NULL::text;
  v_semantic_draft_guard_enabled boolean := false;
  v_semantic_draft_failures jsonb := '[]'::jsonb;
  v_semantic_source_failure_count integer := 0;
BEGIN
  perform public._ctms_assert_session_correction_residuals_draftable_v1(p_workbench_session_id,p_selected_preview_row_ids,'PAY_WORKBENCH_PREPARE_DRAFT');
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed: p_operation_id is required';
  END IF;

  IF p_workbench_session_id IS NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed: p_workbench_session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed: p_actor_user_id is required';
  END IF;

  IF v_scope_filter NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed unsupported pay channel scope: %', v_scope_filter;
  END IF;

  IF jsonb_typeof(COALESCE(p_same_week_paye_override_json, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed requires p_same_week_paye_override_json to be a JSON object';
  END IF;

  IF p_selected_preview_row_ids IS NOT NULL THEN
    IF jsonb_typeof(p_selected_preview_row_ids) <> 'array' THEN
      RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed requires p_selected_preview_row_ids to be null or a JSON array';
    END IF;

    v_selected_input_count := jsonb_array_length(p_selected_preview_row_ids);

    IF v_selected_input_count > 100 THEN
      RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed selected preview row input exceeds the 100 row cap: %', v_selected_input_count;
    END IF;
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed operation not found: %', p_operation_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.operation_type, ''))) <> 'DRAFT_CREATE' THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation.operation_type;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation.status, ''))) IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED') THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed cannot seed terminal operation % with status %', p_operation_id, v_operation.status;
  END IF;

  SELECT COALESCE(settings_row.banking_pay_workbench_semantic_ready_draft_guard_v2_enabled, false)
  INTO v_semantic_draft_guard_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1;

  IF v_operation.workbench_session_id IS NOT NULL AND v_operation.workbench_session_id <> p_workbench_session_id THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed operation % belongs to a different workbench session', p_operation_id;
  END IF;

  IF v_operation.actor_user_id IS NOT NULL AND v_operation.actor_user_id <> p_actor_user_id THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed operation % belongs to a different actor', p_operation_id;
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_workbench_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed workbench session not found: %', p_workbench_session_id;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session.status, ''))) <> 'OPEN' OR v_session.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'pay_workbench_prepare_draft_scope_seed workbench session % is not OPEN', p_workbench_session_id;
  END IF;

  IF v_session.replacement_session_id IS NOT NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'WORKBENCH_SESSION_REPLACED',
      'message', 'This payment workbench has been replaced. Refresh the Banking Pay workbench and create the draft from the current session.',
      'session_id', p_workbench_session_id::text,
      'replacement_session_id', v_session.replacement_session_id::text
    )::text;
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_scope_generation_start
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate_scope_generation';

  SELECT COALESCE(settings_row.banking_pay_workbench_scope_reconcile_shadow_mode, false)
  INTO v_scope_shadow_mode
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  IF v_scope_shadow_mode THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_RECONCILIATION_SHADOW_MODE'
      USING ERRCODE = 'P0001';
  END IF;

  IF COALESCE(v_session.scope_change_generation_applied, 0) <> v_scope_generation_start THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_RECONCILIATION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SCOPE_RECONCILIATION_REQUIRED',
              'session_id', p_workbench_session_id::text,
              'scope_change_generation_current', v_scope_generation_start,
              'scope_change_generation_applied', COALESCE(v_session.scope_change_generation_applied, 0),
              'message', 'Banking Pay is checking for recent candidate changes. Wait for the update to finish before creating a draft.'
            )::text;
  END IF;

  v_scope_blocker := public.pay_workbench_scope_blocker_state_v1(
    p_workbench_session_id,
    v_scope_generation_start,
    NULL::uuid
  );
  v_scope_upstream_active_count := COALESCE((v_scope_blocker->>'upstream_active_count')::integer, 0)
    + COALESCE((v_scope_blocker->>'session_active_count')::integer, 0);
  v_scope_upstream_failed_count := COALESCE((v_scope_blocker->>'upstream_unresolved_failure_count')::integer, 0)
    + COALESCE((v_scope_blocker->>'session_unresolved_failure_count')::integer, 0)
    + COALESCE((v_scope_blocker->>'session_scope_failed_count')::integer, 0)
    + COALESCE((v_scope_blocker->>'session_line_failed_count')::integer, 0);

  IF v_scope_upstream_failed_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_RECONCILIATION_FAILED'
      USING ERRCODE = 'P0001';
  END IF;

  IF v_scope_upstream_active_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_RECONCILIATION_REQUIRED'
      USING ERRCODE = 'P0001';
  END IF;

  WITH active_workbench_jobs AS (
    SELECT job_row.id,
           job_row.job_type,
           job_row.status,
           job_row.candidate_id,
           CASE
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH') THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE') THEN 'WORKBENCH_SESSION_CLONE_REBASE'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE') THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE') THEN 'WORKBENCH_SESSION_SCOPE_SEED'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK') THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
             ELSE UPPER(BTRIM(COALESCE(job_row.job_type, '')))
           END AS canonical_job_type
    FROM public.banking_pay_workbench_jobs AS job_row
    WHERE job_row.session_id = p_workbench_session_id
      AND UPPER(BTRIM(COALESCE(job_row.status, ''))) IN ('QUEUED', 'RUNNING')
  ), blocking_jobs AS (
    SELECT active_workbench_jobs.*
    FROM active_workbench_jobs
    WHERE active_workbench_jobs.canonical_job_type IN (
      'WORKBENCH_SESSION_SCOPE_SEED',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'WORKBENCH_SESSION_CLONE_REBASE',
      'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
      'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
      'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
    )
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(jsonb_build_object(
           'job_id', blocking_jobs.id::text,
           'job_type', blocking_jobs.job_type,
           'canonical_job_type', blocking_jobs.canonical_job_type,
           'status', blocking_jobs.status,
           'candidate_id', CASE WHEN blocking_jobs.candidate_id IS NULL THEN NULL ELSE blocking_jobs.candidate_id::text END
         ) ORDER BY blocking_jobs.canonical_job_type, blocking_jobs.id) FILTER (WHERE blocking_jobs.id IS NOT NULL), '[]'::jsonb)
  INTO v_active_workbench_job_count,
       v_active_workbench_job_sample
  FROM blocking_jobs;

  IF COALESCE(v_active_workbench_job_count, 0) > 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'WORKBENCH_REFRESH_IN_PROGRESS',
      'message', 'Banking Pay is refreshing this workbench. Wait for the refresh to finish, review the selection, and then create the draft.',
      'session_id', p_workbench_session_id::text,
      'active_workbench_job_count', COALESCE(v_active_workbench_job_count, 0),
      'active_workbench_jobs', COALESCE(v_active_workbench_job_sample, '[]'::jsonb)
    )::text;
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET workbench_session_id = COALESCE(operation_update.workbench_session_id, p_workbench_session_id),
      actor_user_id = COALESCE(operation_update.actor_user_id, p_actor_user_id),
      scope_freeze_status = 'SEEDING',
      source_scope_seed_complete = false,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_draft_scope_supplied_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_draft_scope_supplied_ids ON COMMIT DROP AS
  SELECT DISTINCT BTRIM(supplied_id.value) AS supplied_id
  FROM jsonb_array_elements_text(COALESCE(p_selected_preview_row_ids, '[]'::jsonb)) AS supplied_id(value)
  WHERE p_selected_preview_row_ids IS NOT NULL
    AND BTRIM(supplied_id.value) <> '';

  IF p_selected_preview_row_ids IS NOT NULL AND COALESCE(v_selected_input_count, 0) > 0 THEN
    DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_draft_scope_resolved_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_draft_scope_resolved_ids ON COMMIT DROP AS
    WITH supplied_ids AS (
      SELECT supplied_id.supplied_id
      FROM pg_temp.tmp_pay_workbench_draft_scope_supplied_ids AS supplied_id
    ),
    direct_current_matches AS (
      SELECT DISTINCT
        supplied_ids.supplied_id,
        current_preview_row.id::text AS resolved_id
      FROM supplied_ids
      JOIN public.banking_pay_workbench_preview_rows AS current_preview_row
        ON current_preview_row.session_id = p_workbench_session_id
       AND current_preview_row.session_version = v_session.version
       AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
       AND COALESCE(current_preview_row.selected, false) = true
       AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
       AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
       AND (
         current_preview_row.id::text = supplied_ids.supplied_id
         OR current_preview_row.row_key = supplied_ids.supplied_id
         OR current_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
         OR current_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
         OR current_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
       )
    ),
    operation_contracts AS (
      SELECT
        contract_entry.ordinality::integer AS contract_index,
        NULLIF(BTRIM(COALESCE(
          contract_entry.value->>'preview_row_id',
          contract_entry.value->>'materialised_preview_row_id',
          contract_entry.value->>'row_id',
          contract_entry.value->>'id',
          contract_entry.value->>'selected_preview_row_id'
        )), '') AS supplied_id,
        NULLIF(BTRIM(COALESCE(contract_entry.value->>'presentation_preview_row_id', contract_entry.value->>'line_id', '')), '') AS presentation_preview_row_id,
        NULLIF(BTRIM(COALESCE(contract_entry.value->>'row_key', '')), '') AS row_key,
        COALESCE(NULLIF(BTRIM(contract_entry.value->>'section'), ''), 'canonical_preview_lines') AS section,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(contract_entry.value->>'candidate_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(contract_entry.value->>'candidate_id', '')), '')::uuid
          ELSE NULL::uuid
        END AS candidate_id,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(contract_entry.value#>>'{economic_key,timesheet_id}', contract_entry.value->>'timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(contract_entry.value#>>'{economic_key,timesheet_id}', contract_entry.value->>'timesheet_id', '')), '')::uuid
          ELSE NULL::uuid
        END AS timesheet_id,
        NULLIF(BTRIM(COALESCE(contract_entry.value#>>'{economic_key,key_type}', contract_entry.value->>'key_type', '')), '') AS key_type,
        NULLIF(BTRIM(COALESCE(contract_entry.value#>>'{economic_key,key_value}', contract_entry.value->>'key_value', '')), '') AS key_value,
        UPPER(NULLIF(BTRIM(COALESCE(contract_entry.value->>'pay_channel', '')), '')) AS pay_channel
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(v_operation.input_json->'draft_selected_preview_row_contracts', '[]'::jsonb)) = 'array'
            THEN COALESCE(v_operation.input_json->'draft_selected_preview_row_contracts', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS contract_entry(value, ordinality)
      WHERE jsonb_typeof(contract_entry.value) = 'object'
    ),
    operation_contract_timesheet_ids AS (
      SELECT COALESCE(
        array_agg(DISTINCT operation_contracts.timesheet_id ORDER BY operation_contracts.timesheet_id),
        array[]::uuid[]
      ) AS timesheet_ids
      FROM operation_contracts
      WHERE operation_contracts.timesheet_id IS NOT NULL
    ),
    operation_contract_rotation AS (
      SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
        rotation_scope.requested_timesheet_id,
        COALESCE(rotation_scope.canonical_timesheet_id, rotation_scope.requested_timesheet_id) AS canonical_timesheet_id
      FROM operation_contract_timesheet_ids
      JOIN public._pay_timesheet_rotation_scope(operation_contract_timesheet_ids.timesheet_ids) AS rotation_scope
        ON true
      ORDER BY
        rotation_scope.requested_timesheet_id,
        rotation_scope.family_is_current DESC NULLS LAST,
        rotation_scope.family_version DESC NULLS LAST,
        rotation_scope.family_timesheet_id
    ),
    operation_contract_current_matches AS (
      SELECT DISTINCT
        supplied_ids.supplied_id,
        current_preview_row.id::text AS resolved_id
      FROM supplied_ids
      JOIN operation_contracts AS operation_contract
        ON (
          operation_contract.supplied_id = supplied_ids.supplied_id
          OR operation_contract.presentation_preview_row_id = supplied_ids.supplied_id
          OR operation_contract.row_key = supplied_ids.supplied_id
        )
      LEFT JOIN operation_contract_rotation
        ON operation_contract_rotation.requested_timesheet_id = operation_contract.timesheet_id
      JOIN public.banking_pay_workbench_preview_rows AS current_preview_row
        ON current_preview_row.session_id = p_workbench_session_id
       AND current_preview_row.session_version = v_session.version
       AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
       AND COALESCE(current_preview_row.selected, false) = true
       AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
       AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND operation_contract.candidate_id IS NOT NULL
       AND operation_contract.timesheet_id IS NOT NULL
       AND operation_contract.row_key IS NOT NULL
       AND operation_contract.key_type IS NOT NULL
       AND operation_contract.key_value IS NOT NULL
       AND current_preview_row.candidate_id IS NOT DISTINCT FROM operation_contract.candidate_id
       AND current_preview_row.timesheet_id IS NOT DISTINCT FROM COALESCE(operation_contract_rotation.canonical_timesheet_id, operation_contract.timesheet_id)
       AND COALESCE(NULLIF(BTRIM(current_preview_row.section), ''), 'canonical_preview_lines') = COALESCE(NULLIF(BTRIM(operation_contract.section), ''), 'canonical_preview_lines')
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_type, current_preview_row.row_json#>>'{economic_key,key_type}', current_preview_row.row_json->>'component_key_type', '')), '') IS NOT DISTINCT FROM operation_contract.key_type
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_value, current_preview_row.row_json#>>'{economic_key,key_value}', current_preview_row.row_json->>'component_key_value', '')), '') IS NOT DISTINCT FROM operation_contract.key_value
       AND NULLIF(BTRIM(current_preview_row.row_key), '') IS NOT DISTINCT FROM NULLIF(BTRIM(operation_contract.row_key), '')
       AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
       AND (
         operation_contract.pay_channel IS NULL
         OR operation_contract.pay_channel = ''
         OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = operation_contract.pay_channel
       )
    ),
    historical_preview_inputs AS (
      SELECT DISTINCT
        supplied_ids.supplied_id,
        any_preview_row.candidate_id,
        COALESCE(NULLIF(BTRIM(any_preview_row.section), ''), 'canonical_preview_lines') AS section,
        any_preview_row.row_key,
        any_preview_row.timesheet_id,
        NULLIF(BTRIM(COALESCE(any_preview_row.key_type, any_preview_row.row_json#>>'{economic_key,key_type}', any_preview_row.row_json->>'component_key_type', '')), '') AS key_type,
        NULLIF(BTRIM(COALESCE(any_preview_row.key_value, any_preview_row.row_json#>>'{economic_key,key_value}', any_preview_row.row_json->>'component_key_value', '')), '') AS key_value,
        UPPER(NULLIF(BTRIM(COALESCE(any_preview_row.row_json->>'pay_channel', any_preview_row.row_json->>'current_pay_method', any_preview_row.row_json->>'candidate_pay_method', '')), '')) AS pay_channel
      FROM supplied_ids
      JOIN public.banking_pay_workbench_preview_rows AS any_preview_row
        ON any_preview_row.session_id = p_workbench_session_id
       AND (
         any_preview_row.id::text = supplied_ids.supplied_id
         OR any_preview_row.row_key = supplied_ids.supplied_id
         OR any_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
         OR any_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
         OR any_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
       )
      WHERE any_preview_row.timesheet_id IS NOT NULL
        AND any_preview_row.row_key IS NOT NULL
    ),
    historical_timesheet_ids AS (
      SELECT COALESCE(
        array_agg(DISTINCT historical_preview_inputs.timesheet_id ORDER BY historical_preview_inputs.timesheet_id),
        array[]::uuid[]
      ) AS timesheet_ids
      FROM historical_preview_inputs
    ),
    historical_rotation AS (
      SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
        rotation_scope.requested_timesheet_id,
        COALESCE(rotation_scope.canonical_timesheet_id, rotation_scope.requested_timesheet_id) AS canonical_timesheet_id
      FROM historical_timesheet_ids
      JOIN public._pay_timesheet_rotation_scope(historical_timesheet_ids.timesheet_ids) AS rotation_scope
        ON true
      ORDER BY
        rotation_scope.requested_timesheet_id,
        rotation_scope.family_is_current DESC NULLS LAST,
        rotation_scope.family_version DESC NULLS LAST,
        rotation_scope.family_timesheet_id
    ),
    historical_preview_current_matches AS (
      SELECT DISTINCT
        historical_preview_inputs.supplied_id,
        current_preview_row.id::text AS resolved_id
      FROM historical_preview_inputs
      JOIN historical_rotation
        ON historical_rotation.requested_timesheet_id = historical_preview_inputs.timesheet_id
      JOIN public.banking_pay_workbench_preview_rows AS current_preview_row
        ON current_preview_row.session_id = p_workbench_session_id
       AND current_preview_row.session_version = v_session.version
       AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
       AND COALESCE(current_preview_row.selected, false) = true
       AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
       AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND current_preview_row.candidate_id IS NOT DISTINCT FROM historical_preview_inputs.candidate_id
       AND current_preview_row.timesheet_id IS NOT DISTINCT FROM historical_rotation.canonical_timesheet_id
       AND COALESCE(NULLIF(BTRIM(current_preview_row.section), ''), 'canonical_preview_lines') = historical_preview_inputs.section
       AND NULLIF(BTRIM(current_preview_row.row_key), '') IS NOT DISTINCT FROM NULLIF(BTRIM(historical_preview_inputs.row_key), '')
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_type, current_preview_row.row_json#>>'{economic_key,key_type}', current_preview_row.row_json->>'component_key_type', '')), '') IS NOT DISTINCT FROM historical_preview_inputs.key_type
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_value, current_preview_row.row_json#>>'{economic_key,key_value}', current_preview_row.row_json->>'component_key_value', '')), '') IS NOT DISTINCT FROM historical_preview_inputs.key_value
       AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
       AND (
         historical_preview_inputs.pay_channel IS NULL
         OR historical_preview_inputs.pay_channel = ''
         OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = historical_preview_inputs.pay_channel
       )
    )
    SELECT
      supplied_ids.supplied_id,
      COALESCE(direct_current_matches.resolved_id, operation_contract_current_matches.resolved_id, historical_preview_current_matches.resolved_id) AS resolved_id
    FROM supplied_ids
    LEFT JOIN direct_current_matches
      ON direct_current_matches.supplied_id = supplied_ids.supplied_id
    LEFT JOIN operation_contract_current_matches
      ON operation_contract_current_matches.supplied_id = supplied_ids.supplied_id
    LEFT JOIN historical_preview_current_matches
      ON historical_preview_current_matches.supplied_id = supplied_ids.supplied_id;

    SELECT COUNT(*)::integer,
           COUNT(DISTINCT resolved_selection.resolved_id)::integer,
           COALESCE(jsonb_agg(to_jsonb(resolved_selection.resolved_id) ORDER BY resolved_selection.resolved_id), '[]'::jsonb)
    INTO v_resolved_selection_match_count, v_resolved_selection_distinct_count, v_resolved_current_selection_ids
    FROM pg_temp.tmp_pay_workbench_draft_scope_resolved_ids AS resolved_selection
    WHERE NULLIF(BTRIM(COALESCE(resolved_selection.resolved_id, '')), '') IS NOT NULL;

    IF COALESCE(v_resolved_selection_match_count, 0) = COALESCE(v_selected_input_count, 0)
       AND COALESCE(v_resolved_selection_distinct_count, 0) = COALESCE(v_selected_input_count, 0) THEN
      SELECT EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_workbench_draft_scope_resolved_ids AS resolved_selection
        WHERE resolved_selection.resolved_id IS DISTINCT FROM resolved_selection.supplied_id
      )
      INTO v_selection_resolved_to_current;

      TRUNCATE TABLE pg_temp.tmp_pay_workbench_draft_scope_supplied_ids;

      INSERT INTO pg_temp.tmp_pay_workbench_draft_scope_supplied_ids (supplied_id)
      SELECT resolved_selection.resolved_id
      FROM pg_temp.tmp_pay_workbench_draft_scope_resolved_ids AS resolved_selection
      WHERE NULLIF(BTRIM(COALESCE(resolved_selection.resolved_id, '')), '') IS NOT NULL
      ORDER BY resolved_selection.resolved_id;
    END IF;
  END IF;

  IF p_selected_preview_row_ids IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(supplied_ids.supplied_id) ORDER BY supplied_ids.supplied_id), '[]'::jsonb)
    INTO v_stale_selection_ids
    FROM pg_temp.tmp_pay_workbench_draft_scope_supplied_ids AS supplied_ids
    WHERE EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS any_preview_row
      WHERE any_preview_row.session_id = p_workbench_session_id
        AND (
          any_preview_row.id::text = supplied_ids.supplied_id
          OR any_preview_row.row_key = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
        )
    )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS current_preview_row
        WHERE current_preview_row.session_id = p_workbench_session_id
          AND current_preview_row.session_version = v_session.version
          AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
          AND (
            current_preview_row.id::text = supplied_ids.supplied_id
            OR current_preview_row.row_key = supplied_ids.supplied_id
            OR current_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
            OR current_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
            OR current_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
          )
      );

    SELECT COALESCE(jsonb_agg(to_jsonb(supplied_ids.supplied_id) ORDER BY supplied_ids.supplied_id), '[]'::jsonb)
    INTO v_missing_selection_ids
    FROM pg_temp.tmp_pay_workbench_draft_scope_supplied_ids AS supplied_ids
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS any_preview_row
      WHERE any_preview_row.session_id = p_workbench_session_id
        AND (
          any_preview_row.id::text = supplied_ids.supplied_id
          OR any_preview_row.row_key = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
        )
    );

    IF jsonb_array_length(COALESCE(v_stale_selection_ids, '[]'::jsonb)) > 0
       OR jsonb_array_length(COALESCE(v_missing_selection_ids, '[]'::jsonb)) > 0 THEN
      RAISE EXCEPTION 'WORKBENCH_STALE_SELECTION'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_STALE_SELECTION',
                'session_id', p_workbench_session_id::text,
                'session_version', v_session.version,
                'operation_id', p_operation_id::text,
                'rejected_preview_row_ids', COALESCE(v_stale_selection_ids, '[]'::jsonb) || COALESCE(v_missing_selection_ids, '[]'::jsonb),
                'stale_preview_row_ids', COALESCE(v_stale_selection_ids, '[]'::jsonb),
                'missing_preview_row_ids', COALESCE(v_missing_selection_ids, '[]'::jsonb),
                'message', 'Selected preview rows are not part of the current ready workbench session version. Refresh the preview page and try again.'
              )::text;
    END IF;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_draft_scope_selected_candidates;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_draft_scope_selected_candidates ON COMMIT DROP AS
  WITH selected_base_raw AS (
    SELECT
      preview_row.id AS preview_row_id,
      preview_row.row_key,
      preview_row.session_id,
      preview_row.candidate_id,
      private.pay_workbench_preview_effective_section_v1(
        preview_row.section,
        preview_row.row_json
      ) AS section,
      preview_row.selection_state,
      preview_row.status AS table_status,
      COALESCE(preview_row.selected, false) AS table_selected,
      preview_row.row_ordinal,
      preview_row.row_json,
      preview_row.timesheet_id,
      UPPER(NULLIF(BTRIM(COALESCE(preview_row.key_type, preview_row.row_json#>>'{economic_key,key_type}', preview_row.row_json->>'component_key_type', '')), '')) AS key_type,
      NULLIF(BTRIM(COALESCE(preview_row.key_value, preview_row.row_json#>>'{economic_key,key_value}', preview_row.row_json->>'component_key_value', '')), '') AS key_value,
      UPPER(NULLIF(BTRIM(COALESCE(preview_row.row_json->>'pay_channel', preview_row.row_json->>'current_pay_method', preview_row.row_json->>'candidate_pay_method', '')), '')) AS pay_channel,
      UPPER(NULLIF(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', preview_row.row_json->>'case_type', '')), '')) AS line_type,
      UPPER(NULLIF(BTRIM(COALESCE(preview_row.row_json->>'case_type', '')), '')) AS case_type,
      UPPER(NULLIF(BTRIM(COALESCE(preview_row.row_json->>'item_direction', preview_row.row_json->>'direction', '')), '')) AS item_direction,
      CASE WHEN NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_case_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_case_id', '')), '')::uuid ELSE NULL::uuid END AS finance_case_id,
      CASE WHEN NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_component_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_component_id', '')), '')::uuid ELSE NULL::uuid END AS finance_component_id,
      CASE WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN ROUND((preview_row.row_json->>'amount_ex_vat')::numeric, 2) ELSE NULL::numeric END AS amount_ex_vat,
      (
        COALESCE(preview_row.row_json->>'projection_path', '') = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
        OR preview_row.row_json ? 'projection_run_id'
      ) AS is_delta_projection,
      LOWER(BTRIM(COALESCE(preview_row.row_json->>'projection_certified', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS projection_certified,
      COALESCE(
        NULLIF(BTRIM(preview_row.row_json->>'policy_x_authority_scope'), ''),
        NULLIF(BTRIM(preview_row.row_json#>>'{contract_json,policy_x_authority_scope}'), ''),
        NULLIF(BTRIM(preview_row.row_json#>>'{contract,policy_x_authority_scope}'), ''),
        ''
      ) AS policy_x_authority_scope,
      (
        (
          LOWER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND (
            UPPER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_operation_type', ''))) IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
            OR LOWER(BTRIM(COALESCE(preview_row.row_json->>'selected', 'true'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            OR UPPER(BTRIM(COALESCE(preview_row.row_json->>'selection_state', preview_row.selection_state, ''))) <> 'SELECTED'
            OR UPPER(BTRIM(COALESCE(preview_row.row_json->>'status', preview_row.status, ''))) <> 'READY'
          )
        )
        OR EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS active_item
          JOIN public.pay_batch_candidates AS active_candidate
            ON active_candidate.id = active_item.pay_batch_candidate_id
          JOIN public.pay_batches AS active_batch
            ON active_batch.id = active_candidate.pay_batch_id
          WHERE active_candidate.candidate_id = preview_row.candidate_id
            AND COALESCE(active_item.is_voided, false) = false
            AND active_batch.cancelled_at_utc IS NULL
            AND UPPER(BTRIM(COALESCE(active_batch.status, ''))) IN (
              'DRAFT', 'DRAFT_CREATED', 'READY', 'WAITING_BANK_CONFIRM', 'PARTIAL',
              'FAILED', 'BLOCKED_FUNDS', 'SCHEDULED', 'EXECUTING',
              'AWAITING_AUTHORISATION', 'AUTHORISED_FOR_PAYMENT'
            )
            AND (
              (
                COALESCE(
                  active_item.timesheet_id,
                  CASE
                    WHEN UPPER(BTRIM(COALESCE(active_item.item_type, ''))) = 'OVERPAYMENT_RECOVERY'
                     AND NULLIF(BTRIM(COALESCE(active_item.frozen_source_basis_json->>'timesheet_id', '')), '')
                       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN BTRIM(active_item.frozen_source_basis_json->>'timesheet_id')::uuid
                    ELSE NULL::uuid
                  END,
                  CASE
                    WHEN UPPER(BTRIM(COALESCE(active_item.item_type, ''))) = 'OVERPAYMENT_RECOVERY'
                     AND NULLIF(BTRIM(COALESCE(active_item.frozen_source_basis_json->>'linked_timesheet_id', '')), '')
                       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN BTRIM(active_item.frozen_source_basis_json->>'linked_timesheet_id')::uuid
                    ELSE NULL::uuid
                  END,
                  CASE
                    WHEN UPPER(BTRIM(COALESCE(active_item.item_type, ''))) = 'OVERPAYMENT_RECOVERY'
                     AND NULLIF(BTRIM(COALESCE(
                       active_item.frozen_component_snapshot_json#>>'{source_basis_json,linked_timesheet_id}',
                       ''
                     )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      THEN BTRIM(
                        active_item.frozen_component_snapshot_json#>>'{source_basis_json,linked_timesheet_id}'
                      )::uuid
                    ELSE NULL::uuid
                  END
                ) = preview_row.timesheet_id
                AND (
                  (
                    NULLIF(BTRIM(COALESCE(active_item.frozen_component_key_type, '')), '') IS NOT NULL
                    AND NULLIF(BTRIM(COALESCE(active_item.frozen_component_key_value, '')), '') IS NOT NULL
                    AND UPPER(BTRIM(active_item.frozen_component_key_type))
                      = UPPER(BTRIM(COALESCE(preview_row.key_type, preview_row.row_json->>'key_type', '')))
                    AND BTRIM(active_item.frozen_component_key_value)
                      = BTRIM(COALESCE(preview_row.key_value, preview_row.row_json->>'key_value', ''))
                  )
                  OR (
                    NULLIF(BTRIM(COALESCE(active_item.frozen_component_key_type, '')), '') IS NULL
                    AND NULLIF(BTRIM(COALESCE(active_item.frozen_component_key_value, '')), '') IS NULL
                  )
                )
              )
              OR active_item.finance_component_id::text
                = NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_component_id', '')), '')
              OR active_item.finance_case_id::text
                = NULLIF(BTRIM(COALESCE(preview_row.row_json->>'finance_case_id', '')), '')
              OR (
                NULLIF(BTRIM(COALESCE(preview_row.row_json->>'canonical_correction_key', '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(
                  active_item.frozen_component_snapshot_json->>'canonical_correction_key',
                  active_item.frozen_resolution_payload_json->>'canonical_correction_key',
                  ''
                )), '') = NULLIF(BTRIM(COALESCE(
                  preview_row.row_json->>'canonical_correction_key',
                  ''
                )), '')
              )
            )
        )
      ) AS post_draft_overlay_unavailable,
      (
        (preview_row.row_json ? 'selected' AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'selected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') IS DISTINCT FROM COALESCE(preview_row.selected, false))
        OR (preview_row.row_json ? 'selection_state' AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'selection_state', ''))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))))
        OR (preview_row.row_json ? 'status' AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'status', ''))) IS DISTINCT FROM UPPER(BTRIM(COALESCE(preview_row.status, ''))))
      ) AS table_state_conflicts_row_json
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_workbench_session_id
      AND preview_row.session_version = v_session.version
      AND COALESCE(preview_row.selected, false) = true
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
      AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(preview_row.row_json->>'pay_channel', preview_row.row_json->>'current_pay_method', preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
      AND (
        p_selected_preview_row_ids IS NULL
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_pay_workbench_draft_scope_supplied_ids AS supplied_id
          WHERE supplied_id.supplied_id IN (preview_row.id::text, preview_row.row_key, preview_row.row_json->>'preview_row_id', preview_row.row_json->>'row_id', preview_row.row_json->>'line_id')
        )
      )
      AND (
        p_selected_preview_row_ids IS NOT NULL
        OR NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_scope AS existing_scope
          WHERE existing_scope.operation_id = p_operation_id
            AND existing_scope.workbench_session_id = p_workbench_session_id
            AND existing_scope.candidate_id = preview_row.candidate_id
            AND existing_scope.pay_channel = UPPER(BTRIM(COALESCE(preview_row.row_json->>'pay_channel', preview_row.row_json->>'current_pay_method', preview_row.row_json->>'candidate_pay_method', '')))
        )
      )
    ORDER BY preview_row.row_ordinal, preview_row.id
    LIMIT 100
  ), selected_timesheet_ids AS (
    SELECT COALESCE(
      array_agg(DISTINCT selected_base_raw.timesheet_id ORDER BY selected_base_raw.timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM selected_base_raw
    WHERE selected_base_raw.timesheet_id IS NOT NULL
  ), selected_rotation_scope AS (
    SELECT DISTINCT ON (rotation_scope.requested_timesheet_id)
      rotation_scope.requested_timesheet_id,
      COALESCE(rotation_scope.canonical_timesheet_id, rotation_scope.requested_timesheet_id) AS canonical_timesheet_id,
      (rotation_scope.family_timesheet_id IS NOT NULL AND rotation_scope.family_is_current IS NOT NULL) AS rotation_scope_resolved,
      COALESCE(rotation_scope.requested_is_canonical, false) AS requested_is_canonical
    FROM selected_timesheet_ids
    JOIN public._pay_timesheet_rotation_scope(selected_timesheet_ids.timesheet_ids) AS rotation_scope
      ON true
    ORDER BY
      rotation_scope.requested_timesheet_id,
      rotation_scope.family_is_current DESC NULLS LAST,
      rotation_scope.family_version DESC NULLS LAST,
      rotation_scope.family_timesheet_id
  ), selected_base AS (
    SELECT
      selected_base_raw.preview_row_id,
      selected_base_raw.row_key,
      selected_base_raw.session_id,
      selected_base_raw.candidate_id,
      selected_base_raw.section,
      selected_base_raw.selection_state,
      selected_base_raw.table_status,
      selected_base_raw.table_selected,
      selected_base_raw.is_delta_projection,
      selected_base_raw.projection_certified,
      selected_base_raw.policy_x_authority_scope,
      selected_base_raw.post_draft_overlay_unavailable,
      selected_base_raw.table_state_conflicts_row_json,
      selected_base_raw.row_ordinal,
      jsonb_strip_nulls(
        CASE
          WHEN selected_base_raw.timesheet_id IS NULL OR selected_rotation_scope.canonical_timesheet_id IS NULL THEN selected_base_raw.row_json
          ELSE selected_base_raw.row_json
            || jsonb_build_object(
              'timesheet_id', selected_rotation_scope.canonical_timesheet_id::text,
              'real_business_timesheet_id', selected_rotation_scope.canonical_timesheet_id::text,
              'economic_key', COALESCE(selected_base_raw.row_json->'economic_key', '{}'::jsonb)
                || jsonb_build_object('timesheet_id', selected_rotation_scope.canonical_timesheet_id::text)
            )
            || CASE
              WHEN selected_base_raw.timesheet_id IS DISTINCT FROM selected_rotation_scope.canonical_timesheet_id THEN jsonb_build_object(
                'rotation_requested_timesheet_id', selected_base_raw.timesheet_id::text
              )
              ELSE '{}'::jsonb
            END
        END
      ) AS row_json,
      COALESCE(selected_rotation_scope.canonical_timesheet_id, selected_base_raw.timesheet_id) AS timesheet_id,
      selected_base_raw.key_type,
      selected_base_raw.key_value,
      selected_base_raw.pay_channel,
      selected_base_raw.line_type,
      selected_base_raw.case_type,
      selected_base_raw.item_direction,
      selected_base_raw.finance_case_id,
      selected_base_raw.finance_component_id,
      selected_base_raw.amount_ex_vat,
      CASE
        WHEN selected_base_raw.timesheet_id IS NULL THEN false
        WHEN COALESCE(selected_rotation_scope.rotation_scope_resolved, false) = false THEN true
        WHEN selected_rotation_scope.canonical_timesheet_id IS NULL THEN true
        WHEN COALESCE(selected_rotation_scope.requested_is_canonical, false) = false THEN true
        ELSE false
      END AS rotation_validation_failed,
      CASE
        WHEN selected_base_raw.timesheet_id IS NULL THEN NULL::text
        WHEN COALESCE(selected_rotation_scope.rotation_scope_resolved, false) = false THEN 'SELECTED_PREVIEW_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN selected_rotation_scope.canonical_timesheet_id IS NULL THEN 'SELECTED_PREVIEW_CANONICAL_TIMESHEET_NOT_RESOLVED'
        WHEN COALESCE(selected_rotation_scope.requested_is_canonical, false) = false THEN 'SELECTED_PREVIEW_TIMESHEET_NOT_CANONICAL_REFRESH_REQUIRED'
        ELSE NULL::text
      END AS rotation_failure_reason
    FROM selected_base_raw
    LEFT JOIN selected_rotation_scope
      ON selected_rotation_scope.requested_timesheet_id = selected_base_raw.timesheet_id
  )
  SELECT
    selected_base.*,
    jsonb_strip_nulls(jsonb_build_object(
      'timesheet_id', CASE WHEN selected_base.timesheet_id IS NULL THEN NULL ELSE selected_base.timesheet_id::text END,
      'key_type', selected_base.key_type,
      'key_value', selected_base.key_value
    )) AS economic_key_json,
    public.pay_workbench_preview_line_contract_ok(
      p_line_json => jsonb_strip_nulls(
        selected_base.row_json
        || jsonb_build_object(
          'row_key', selected_base.row_key,
          'preview_row_pk', selected_base.preview_row_id::text,
          'selection_state', selected_base.selection_state
        )
      ),
      p_economic_key_json => jsonb_strip_nulls(jsonb_build_object(
        'timesheet_id', CASE WHEN selected_base.timesheet_id IS NULL THEN NULL ELSE selected_base.timesheet_id::text END,
        'key_type', selected_base.key_type,
        'key_value', selected_base.key_value
      )),
      p_target_section => selected_base.section
    ) AS preview_contract_json
  FROM selected_base;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'preview_row_id', invalid_rows.preview_row_id::text,
           'row_key', invalid_rows.row_key,
           'candidate_id', invalid_rows.candidate_id::text,
           'reasons', COALESCE(invalid_rows.preview_contract_json->'reasons', '[]'::jsonb)
             || CASE WHEN invalid_rows.rotation_validation_failed IS TRUE THEN jsonb_build_array(invalid_rows.rotation_failure_reason) ELSE '[]'::jsonb END
             || CASE
               WHEN ROUND(COALESCE(invalid_rows.amount_ex_vat, 0), 2) < 0
                AND NOT (
                  invalid_rows.finance_case_id IS NOT NULL
                  AND (invalid_rows.item_direction IS NULL OR invalid_rows.item_direction = 'DEDUCTION')
                  AND invalid_rows.line_type IN ('OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY','PAYMENT_ADVANCE_REPAYMENT','LOAN_REPAYMENT')
                ) THEN jsonb_build_array('NEGATIVE_ENTITLEMENT_MUST_ROUTE_TO_FINANCE_CASE')
               ELSE '[]'::jsonb
             END
         ) ORDER BY invalid_rows.row_ordinal, invalid_rows.preview_row_id), '[]'::jsonb)
  INTO v_malformed_selected_preview_rows
  FROM (
    SELECT selected_candidate.*
    FROM pg_temp.tmp_pay_workbench_draft_scope_selected_candidates AS selected_candidate
    WHERE selected_candidate.rotation_validation_failed IS TRUE
       OR LOWER(BTRIM(COALESCE(selected_candidate.preview_contract_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR LOWER(BTRIM(COALESCE(selected_candidate.preview_contract_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
       OR UPPER(BTRIM(COALESCE(selected_candidate.section, ''))) <> 'CANONICAL_PREVIEW_LINES'
       OR UPPER(BTRIM(COALESCE(selected_candidate.selection_state, ''))) <> 'SELECTED'
       OR UPPER(BTRIM(COALESCE(selected_candidate.table_status, ''))) <> 'READY'
       OR COALESCE(selected_candidate.table_selected, false) IS NOT TRUE
       OR (COALESCE(selected_candidate.is_delta_projection, false) IS TRUE AND COALESCE(selected_candidate.projection_certified, false) IS NOT TRUE)
       OR COALESCE(selected_candidate.policy_x_authority_scope, '') <> 'PRE_DRAFT_LIVE_TRUTH'
       OR selected_candidate.timesheet_id IS NULL
       OR COALESCE(selected_candidate.post_draft_overlay_unavailable, false) IS TRUE
       OR COALESCE(selected_candidate.table_state_conflicts_row_json, false) IS TRUE
       OR UPPER(BTRIM(COALESCE(selected_candidate.key_type, ''))) NOT IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
       OR selected_candidate.key_value IS NULL
       OR (selected_candidate.key_type = 'TS_DAY' AND selected_candidate.key_value !~ '^\d{4}-\d{2}-\d{2}$')
       OR selected_candidate.amount_ex_vat IS NULL
       OR ROUND(COALESCE(selected_candidate.amount_ex_vat, 0), 2) = 0
       OR (
         ROUND(COALESCE(selected_candidate.amount_ex_vat, 0), 2) < 0
         AND NOT (
           selected_candidate.finance_case_id IS NOT NULL
           AND (selected_candidate.item_direction IS NULL OR selected_candidate.item_direction = 'DEDUCTION')
           AND selected_candidate.line_type IN ('OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY','PAYMENT_ADVANCE_REPAYMENT','LOAN_REPAYMENT')
         )
       )
    ORDER BY selected_candidate.row_ordinal, selected_candidate.preview_row_id
    LIMIT 25
  ) AS invalid_rows;

  IF jsonb_array_length(COALESCE(v_malformed_selected_preview_rows, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE',
              'operation_id', p_operation_id::text,
              'workbench_session_id', p_workbench_session_id::text,
              'malformed_selected_preview_rows', COALESCE(v_malformed_selected_preview_rows, '[]'::jsonb),
              'message', 'Selected preview rows are not valid draftable Ready to Pay rows. Refresh the preview and try again.'
            )::text;
  END IF;

  -- Candidate-set Draft defence.  Individually valid finance deductions are
  -- allowed only where the rows selected in this same candidate scope contain
  -- enough positive ordinary entitlement.  Display parents, blocked rows,
  -- nominal debt, and another candidate's pay never create headroom.
  IF COALESCE(v_semantic_draft_guard_enabled, false) THEN
    SELECT COUNT(*)::integer
    INTO v_semantic_source_failure_count
    FROM (
      SELECT DISTINCT selected_candidate.candidate_id
      FROM pg_temp.tmp_pay_workbench_draft_scope_selected_candidates AS selected_candidate
    ) AS selected_scope
    LEFT JOIN public.banking_pay_workbench_session_scope AS source_scope
      ON source_scope.session_id=p_workbench_session_id
     AND source_scope.candidate_id=selected_scope.candidate_id
    WHERE source_scope.id IS NULL
       OR source_scope.certified_preview_publication_parity_ok IS NOT TRUE
       OR source_scope.certified_preview_publication_session_version IS DISTINCT FROM v_session.version
       OR source_scope.certified_preview_publication_attestation_json->>'attestation_version'
            IS DISTINCT FROM 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
       OR source_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
            IS DISTINCT FROM 'READY_TO_PAY_SEMANTIC_V2'
       OR COALESCE((source_scope.certified_preview_publication_attestation_json->>'semantic_ready')::boolean,false)
            IS NOT TRUE;

    IF v_semantic_source_failure_count > 0 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_SOURCE_SEMANTIC_CERTIFICATION_REQUIRED'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','PAY_WORKBENCH_DRAFT_SOURCE_SEMANTIC_CERTIFICATION_REQUIRED',
          'candidate_count',v_semantic_source_failure_count,
          'message','Draft creation requires a current V3 semantically certified Ready-to-Pay source.'
        )::text;
    END IF;

    WITH candidate_semantics AS (
      SELECT
        selected_candidate.candidate_id,
        ROUND(COALESCE(SUM(selected_candidate.amount_ex_vat) FILTER (
          WHERE selected_candidate.amount_ex_vat > 0
            AND selected_candidate.line_type = 'TIMESHEET_PAYMENT'
            AND COALESCE((selected_candidate.preview_contract_json->>'ok')::boolean, false)
            AND COALESCE((selected_candidate.preview_contract_json->>'selection_allowed')::boolean, false)
        ), 0), 2) AS selected_positive_ordinary_amount,
        ROUND(COALESCE(SUM(selected_candidate.amount_ex_vat) FILTER (
          WHERE selected_candidate.amount_ex_vat < 0
            AND selected_candidate.line_type IN (
              'OVERPAYMENT_RECOVERY',
              'MANUAL_DEBT_RECOVERY',
              'PAYMENT_ADVANCE_REPAYMENT',
              'LOAN_REPAYMENT'
            )
            AND selected_candidate.finance_case_id IS NOT NULL
            AND (selected_candidate.item_direction IS NULL OR selected_candidate.item_direction = 'DEDUCTION')
            AND COALESCE((selected_candidate.preview_contract_json->>'ok')::boolean, false)
            AND COALESCE((selected_candidate.preview_contract_json->>'selection_allowed')::boolean, false)
        ), 0), 2) AS selected_deduction_amount
      FROM pg_temp.tmp_pay_workbench_draft_scope_selected_candidates AS selected_candidate
      WHERE selected_candidate.table_selected IS TRUE
        AND UPPER(COALESCE(selected_candidate.selection_state, '')) = 'SELECTED'
        AND UPPER(COALESCE(selected_candidate.table_status, '')) = 'READY'
      GROUP BY selected_candidate.candidate_id
    ), failed AS (
      SELECT
        candidate_semantics.*,
        ROUND(candidate_semantics.selected_positive_ordinary_amount
          + candidate_semantics.selected_deduction_amount, 2) AS selected_candidate_result,
        CASE
          WHEN candidate_semantics.selected_deduction_amount < 0
           AND candidate_semantics.selected_positive_ordinary_amount <= 0
            THEN 'PAY_WORKBENCH_DRAFT_RECOVERY_WITHOUT_POSITIVE_HEADROOM'
          WHEN -candidate_semantics.selected_deduction_amount
             > candidate_semantics.selected_positive_ordinary_amount
            THEN 'PAY_WORKBENCH_DRAFT_DEDUCTION_EXCEEDS_SELECTED_HEADROOM'
          WHEN candidate_semantics.selected_positive_ordinary_amount
             + candidate_semantics.selected_deduction_amount < 0
            THEN 'PAY_WORKBENCH_DRAFT_CANDIDATE_RESULT_NEGATIVE'
          ELSE NULL
        END AS failure_code
      FROM candidate_semantics
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'candidate_id', failed.candidate_id::text,
      'selected_positive_ordinary_amount', failed.selected_positive_ordinary_amount,
      'selected_deduction_amount', failed.selected_deduction_amount,
      'selected_candidate_result', failed.selected_candidate_result,
      'code', failed.failure_code
    ) ORDER BY failed.candidate_id), '[]'::jsonb)
    INTO v_semantic_draft_failures
    FROM failed
    WHERE failed.failure_code IS NOT NULL;

    IF jsonb_array_length(COALESCE(v_semantic_draft_failures, '[]'::jsonb)) > 0 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_SELECTED_SEMANTIC_PROOF_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_DRAFT_SELECTED_SEMANTIC_PROOF_FAILED',
                'operation_id', p_operation_id::text,
                'workbench_session_id', p_workbench_session_id::text,
                'candidate_failures', v_semantic_draft_failures,
                'message', 'Draft selection requires positive ordinary entitlement for the same candidate, deductions within selected headroom, and a non-negative candidate result.'
              )::text;
    END IF;
  END IF;

  /*
   * Final pre-draft defence: selected rows must come from the current adopted
   * candidate authority. This performs only bounded validation and never
   * rebuilds or recalculates economics inside draft creation.
   */
  WITH selected_candidates AS (
    SELECT DISTINCT selected_candidate.candidate_id
    FROM pg_temp.tmp_pay_workbench_draft_scope_selected_candidates
      AS selected_candidate
  ), selected_candidate_authority AS (
    SELECT
      selected_candidates.candidate_id,
      COALESCE(candidate_state.status, 'MISSING') AS candidate_state_status,
      COALESCE(candidate_state.source_change_seq, -1) AS candidate_state_source_change_seq,
      COALESCE(change_counter.seq, 0) AS live_source_change_seq,
      EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_candidate_source_lines AS stale_source
        WHERE stale_source.session_id = p_workbench_session_id
          AND stale_source.candidate_id = selected_candidates.candidate_id
          AND stale_source.session_version = v_session.version
          AND stale_source.source_change_seq >=
              COALESCE(candidate_state.source_change_seq, -1)
          AND UPPER(BTRIM(COALESCE(stale_source.status, ''))) IN (
            'DIRTY', 'PENDING', 'PROCESSING', 'RUNNING', 'QUEUED'
          )
      ) AS has_incomplete_source,
      EXISTS (
        SELECT 1
        FROM (
          SELECT current_source.line_key, current_source.timesheet_id
          FROM public.banking_pay_workbench_candidate_source_lines AS current_source
          WHERE current_source.session_id = p_workbench_session_id
            AND current_source.candidate_id = selected_candidates.candidate_id
            AND current_source.session_version = v_session.version
            AND UPPER(BTRIM(COALESCE(current_source.status, ''))) = 'CURRENT'
          GROUP BY current_source.line_key, current_source.timesheet_id
          HAVING COUNT(*) > 1
        ) AS duplicate_source
      ) AS has_duplicate_current_source,
      EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_candidate_line_work AS incomplete_line
        WHERE incomplete_line.session_id = p_workbench_session_id
          AND incomplete_line.candidate_id = selected_candidates.candidate_id
          AND (
            COALESCE(incomplete_line.work_payload_json->>'source_change_seq', '')
              !~ '^[0-9]+$'
            OR (incomplete_line.work_payload_json->>'source_change_seq')::bigint >=
                 COALESCE(candidate_state.source_change_seq, -1)
          )
          AND UPPER(BTRIM(COALESCE(incomplete_line.status, ''))) IN (
            'DIRTY', 'PENDING', 'PROCESSING', 'RUNNING', 'QUEUED'
          )
      ) AS has_incomplete_line_work,
      EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS dirty_preview
        WHERE dirty_preview.session_id = p_workbench_session_id
          AND dirty_preview.candidate_id = selected_candidates.candidate_id
          AND dirty_preview.session_version = v_session.version
          AND (
            COALESCE(dirty_preview.row_json->>'source_change_seq', '')
              !~ '^[0-9]+$'
            OR (dirty_preview.row_json->>'source_change_seq')::bigint >=
                 COALESCE(candidate_state.source_change_seq, -1)
          )
          AND UPPER(BTRIM(COALESCE(dirty_preview.status, ''))) IN (
            'DIRTY', 'PENDING', 'PROCESSING', 'RUNNING', 'QUEUED'
          )
      ) AS has_dirty_preview
    FROM selected_candidates
    LEFT JOIN public.banking_pay_workbench_session_candidate_state AS candidate_state
      ON candidate_state.session_id = p_workbench_session_id
     AND candidate_state.candidate_id = selected_candidates.candidate_id
    LEFT JOIN public.app_change_counters AS change_counter
      ON change_counter.entity_key =
           'pay_candidate:' || selected_candidates.candidate_id::text
  ), invalid_candidates AS (
    SELECT
      selected_candidate_authority.*,
      CASE
        WHEN UPPER(BTRIM(COALESCE(selected_candidate_authority.candidate_state_status, ''))) <> 'READY'
          THEN 'CANDIDATE_STATE_NOT_READY'
        WHEN selected_candidate_authority.candidate_state_source_change_seq
               IS DISTINCT FROM selected_candidate_authority.live_source_change_seq
          THEN 'CANDIDATE_STATE_SEQUENCE_STALE'
        WHEN selected_candidate_authority.has_incomplete_source
          THEN 'SOURCE_FAMILY_INCOMPLETE'
        WHEN selected_candidate_authority.has_duplicate_current_source
          THEN 'SOURCE_FAMILY_DUPLICATED'
        WHEN selected_candidate_authority.has_incomplete_line_work
          THEN 'LINE_WORK_NOT_TERMINAL'
        WHEN selected_candidate_authority.has_dirty_preview
          THEN 'PREVIEW_ROWS_NOT_CURRENT'
        ELSE NULL::text
      END AS stale_reason
    FROM selected_candidate_authority
  )
  SELECT
    COUNT(*)::integer,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'candidate_id', invalid_candidates.candidate_id::text,
          'reason', invalid_candidates.stale_reason,
          'candidate_state_status', invalid_candidates.candidate_state_status,
          'candidate_state_source_change_seq',
            invalid_candidates.candidate_state_source_change_seq,
          'live_source_change_seq',
            invalid_candidates.live_source_change_seq
        )
        ORDER BY invalid_candidates.candidate_id
      ) FILTER (WHERE invalid_candidates.stale_reason IS NOT NULL),
      '[]'::jsonb
    )
  INTO
    v_stale_candidate_authority_count,
    v_stale_candidate_authority_sample
  FROM invalid_candidates
  WHERE invalid_candidates.stale_reason IS NOT NULL;

  IF COALESCE(v_stale_candidate_authority_count, 0) > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_STALE_CANDIDATE_AUTHORITY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_DRAFT_STALE_CANDIDATE_AUTHORITY',
              'operation_id', p_operation_id::text,
              'workbench_session_id', p_workbench_session_id::text,
              'affected_candidates',
                COALESCE(v_stale_candidate_authority_sample, '[]'::jsonb),
              'message',
                'Banking Pay changed and is refreshing. No draft was created. Review the current rows and try again.'
            )::text;
  END IF;


  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'preview_row_id', synthetic_total_rows.preview_row_id::text,
           'row_key', synthetic_total_rows.row_key,
           'candidate_id', synthetic_total_rows.candidate_id::text,
           'timesheet_id', CASE WHEN synthetic_total_rows.timesheet_id IS NULL THEN NULL ELSE synthetic_total_rows.timesheet_id::text END,
           'key_type', synthetic_total_rows.key_type,
           'key_value', synthetic_total_rows.key_value,
           'amount_ex_vat', synthetic_total_rows.amount_ex_vat,
           'reason', 'RESOLVED_SYNTHETIC_TOTAL_ROW_SELECTED'
         ) ORDER BY synthetic_total_rows.row_ordinal, synthetic_total_rows.preview_row_id), '[]'::jsonb)
  INTO v_synthetic_total_selected_preview_rows
  FROM pg_temp.tmp_pay_workbench_draft_scope_selected_candidates AS synthetic_total_rows
  WHERE UPPER(BTRIM(COALESCE(synthetic_total_rows.key_type, synthetic_total_rows.row_json#>>'{economic_key,key_type}', ''))) = 'TS_TOTAL'
    AND UPPER(BTRIM(COALESCE(synthetic_total_rows.key_value, synthetic_total_rows.row_json#>>'{economic_key,key_value}', ''))) = 'TOTAL'
    AND LOWER(BTRIM(COALESCE(synthetic_total_rows.row_key, synthetic_total_rows.row_json->>'row_key', synthetic_total_rows.row_json->>'line_key', synthetic_total_rows.row_json->>'source_ref', ''))) LIKE '%:non_segment:total%'
    AND (
      lower(btrim(coalesce(synthetic_total_rows.row_json->>'resolved_segment_rows_replace_source_total', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json#>>'{case_resolution_summary,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_applied}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_active}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR (
        COALESCE(synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_component_count}', '') ~ '^[0-9]+$'
        AND (synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_component_count}')::integer > 0
      )
      OR EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_workbench_draft_scope_selected_candidates AS sibling_segment
        WHERE sibling_segment.candidate_id = synthetic_total_rows.candidate_id
          AND sibling_segment.timesheet_id IS NOT DISTINCT FROM synthetic_total_rows.timesheet_id
          AND UPPER(BTRIM(COALESCE(sibling_segment.key_type, sibling_segment.row_json#>>'{economic_key,key_type}', ''))) = 'TS_DAY'
          AND LOWER(BTRIM(COALESCE(sibling_segment.row_key, sibling_segment.row_json->>'row_key', sibling_segment.row_json->>'line_key', sibling_segment.row_json->>'source_ref', ''))) LIKE '%:segment:%'
      )
    );

  IF jsonb_array_length(COALESCE(v_synthetic_total_selected_preview_rows, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'RESOLVED_SYNTHETIC_TOTAL_ROW_NOT_DRAFTABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'RESOLVED_SYNTHETIC_TOTAL_ROW_NOT_DRAFTABLE',
              'operation_id', p_operation_id::text,
              'workbench_session_id', p_workbench_session_id::text,
              'synthetic_total_selected_preview_rows', COALESCE(v_synthetic_total_selected_preview_rows, '[]'::jsonb),
              'message', 'A selected resolved timesheet row is stale and cannot be drafted. Refresh Banking Pay and try Create Draft again.'
            )::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_draft_scope_selected_page;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_draft_scope_selected_page ON COMMIT DROP AS
  SELECT selected_candidate.*
  FROM pg_temp.tmp_pay_workbench_draft_scope_selected_candidates AS selected_candidate
  WHERE selected_candidate.rotation_validation_failed IS NOT TRUE
    AND LOWER(BTRIM(COALESCE(selected_candidate.preview_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(selected_candidate.preview_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND lower(COALESCE(selected_candidate.section, '')) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_candidate.selection_state, ''))) = 'SELECTED'
    AND UPPER(BTRIM(COALESCE(selected_candidate.table_status, ''))) = 'READY'
    AND COALESCE(selected_candidate.table_selected, false) IS TRUE
    AND (COALESCE(selected_candidate.is_delta_projection, false) IS NOT TRUE OR COALESCE(selected_candidate.projection_certified, false) IS TRUE)
    AND COALESCE(selected_candidate.policy_x_authority_scope, '') = 'PRE_DRAFT_LIVE_TRUTH'
    AND selected_candidate.timesheet_id IS NOT NULL
    AND COALESCE(selected_candidate.post_draft_overlay_unavailable, false) IS NOT TRUE
    AND COALESCE(selected_candidate.table_state_conflicts_row_json, false) IS NOT TRUE
    AND selected_candidate.pay_channel IN ('PAYE', 'UMBRELLA')
    AND selected_candidate.key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
    AND selected_candidate.key_value IS NOT NULL
    AND NOT (selected_candidate.key_type = 'TS_DAY' AND selected_candidate.key_value !~ '^\d{4}-\d{2}-\d{2}$')
    AND selected_candidate.amount_ex_vat IS NOT NULL
    AND ROUND(COALESCE(selected_candidate.amount_ex_vat, 0), 2) <> 0
    AND (
      ROUND(COALESCE(selected_candidate.amount_ex_vat, 0), 2) > 0
      OR (
        selected_candidate.finance_case_id IS NOT NULL
        AND (selected_candidate.item_direction IS NULL OR selected_candidate.item_direction = 'DEDUCTION')
        AND selected_candidate.line_type IN ('OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY','PAYMENT_ADVANCE_REPAYMENT','LOAN_REPAYMENT')
      )
    )
  ORDER BY selected_candidate.row_ordinal, selected_candidate.preview_row_id
  LIMIT 100;

  IF NOT EXISTS (SELECT 1 FROM pg_temp.tmp_pay_workbench_draft_scope_selected_page) THEN
    IF COALESCE(v_selected_input_count, 0) > 0 THEN
      RAISE EXCEPTION 'DRAFT_CANDIDATE_SCOPE_EMPTY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'DRAFT_CANDIDATE_SCOPE_EMPTY',
                'operation_id', p_operation_id::text,
                'workbench_session_id', p_workbench_session_id::text,
                'selected_input_count', v_selected_input_count,
                'message', 'Selected preview rows did not produce any valid row-backed candidate scope rows.'
              )::text;
    END IF;
    UPDATE public.banking_pay_operations
    SET scope_freeze_status = 'NONE',
        source_scope_seed_complete = false,
        updated_at_utc = v_now
    WHERE id = p_operation_id;
    RETURN QUERY SELECT 0::integer, 0::integer, 0::integer, 0::integer, 0::integer;
    RETURN;
  END IF;

  INSERT INTO public.banking_pay_operation_candidate_scope (
    operation_id,
    workbench_session_id,
    source_snapshot_run_id,
    source_session_version,
    candidate_id,
    pay_channel,
    pay_batch_id,
    selected_preview_row_ids_json,
    selected_timesheet_ids_json,
    selected_finance_case_ids_json,
    effective_payees_json,
    effective_case_resolution_states_json,
    effective_canonical_preview_lines_json,
    selected_canonical_preview_lines_json,
    baseline_component_rows_json,
    candidate_totals_json,
    allocation_basis_json,
    scope_hash,
    chunk_sequence,
    status,
    created_at_utc,
    updated_at_utc
  )
  SELECT
    p_operation_id,
    p_workbench_session_id,
    v_session.source_snapshot_run_id,
    v_session.version,
    selected_page.candidate_id,
    selected_page.pay_channel,
    v_operation.pay_batch_id,
    COALESCE(jsonb_agg(to_jsonb(selected_page.preview_row_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
    COALESCE(jsonb_agg(to_jsonb(selected_page.timesheet_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id) FILTER (WHERE selected_page.timesheet_id IS NOT NULL), '[]'::jsonb),
    COALESCE(jsonb_agg(to_jsonb(selected_page.finance_case_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id) FILTER (WHERE selected_page.finance_case_id IS NOT NULL), '[]'::jsonb),
    COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'preview_row_id', selected_page.preview_row_id::text,
      'row_key', selected_page.row_key,
      'pay_channel', selected_page.pay_channel,
      'payee', COALESCE(selected_page.row_json->'effective_payee', selected_page.row_json->'payee', selected_page.row_json->'payee_map')
    )) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id) FILTER (WHERE selected_page.row_json ? 'effective_payee' OR selected_page.row_json ? 'payee' OR selected_page.row_json ? 'payee_map'), '[]'::jsonb),
    jsonb_strip_nulls(jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'same_week_paye_override', COALESCE(p_same_week_paye_override_json, '{}'::jsonb),
      'rows', COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'preview_row_id', selected_page.preview_row_id::text,
        'row_key', selected_page.row_key,
        'finance_case_id', CASE WHEN selected_page.finance_case_id IS NULL THEN NULL ELSE selected_page.finance_case_id::text END,
        'case_resolution_summary', selected_page.row_json->'case_resolution_summary'
      )) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id) FILTER (WHERE selected_page.row_json ? 'case_resolution_summary' OR selected_page.finance_case_id IS NOT NULL), '[]'::jsonb)
    )),
    COALESCE(jsonb_agg(jsonb_strip_nulls(
      selected_page.row_json
      || jsonb_build_object(
        'source', 'banking_pay_workbench_preview_rows',
        'preview_row_id', selected_page.preview_row_id::text,
        'preview_row_pk', selected_page.preview_row_id::text,
        'row_key', selected_page.row_key,
        'row_ordinal', selected_page.row_ordinal,
        'candidate_id', selected_page.candidate_id::text,
        'timesheet_id', CASE WHEN selected_page.timesheet_id IS NULL THEN NULL ELSE selected_page.timesheet_id::text END,
        'finance_case_id', CASE WHEN selected_page.finance_case_id IS NULL THEN NULL ELSE selected_page.finance_case_id::text END,
        'finance_component_id', CASE WHEN selected_page.finance_component_id IS NULL THEN NULL ELSE selected_page.finance_component_id::text END,
        'line_type', selected_page.line_type,
        'case_type', selected_page.case_type,
        'item_direction', selected_page.item_direction,
        'pay_channel', selected_page.pay_channel,
        'section', selected_page.section,
        'selection_state', 'SELECTED',
        'status', 'READY',
        'amount_ex_vat', selected_page.amount_ex_vat,
        'key_type', selected_page.key_type,
        'key_value', selected_page.key_value,
        'economic_key', selected_page.economic_key_json,
        'preview_contract', selected_page.preview_contract_json,
        'draftable', true,
        'row_backed_draft_scope', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'effective', true
      )
    ) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
    COALESCE(jsonb_agg(jsonb_strip_nulls(
      selected_page.row_json
      || jsonb_build_object(
        'source', 'banking_pay_workbench_preview_rows',
        'preview_row_id', selected_page.preview_row_id::text,
        'preview_row_pk', selected_page.preview_row_id::text,
        'row_key', selected_page.row_key,
        'row_ordinal', selected_page.row_ordinal,
        'candidate_id', selected_page.candidate_id::text,
        'timesheet_id', CASE WHEN selected_page.timesheet_id IS NULL THEN NULL ELSE selected_page.timesheet_id::text END,
        'finance_case_id', CASE WHEN selected_page.finance_case_id IS NULL THEN NULL ELSE selected_page.finance_case_id::text END,
        'finance_component_id', CASE WHEN selected_page.finance_component_id IS NULL THEN NULL ELSE selected_page.finance_component_id::text END,
        'line_type', selected_page.line_type,
        'case_type', selected_page.case_type,
        'item_direction', selected_page.item_direction,
        'pay_channel', selected_page.pay_channel,
        'section', selected_page.section,
        'selection_state', 'SELECTED',
        'status', 'READY',
        'amount_ex_vat', selected_page.amount_ex_vat,
        'key_type', selected_page.key_type,
        'key_value', selected_page.key_value,
        'economic_key', selected_page.economic_key_json,
        'preview_contract', selected_page.preview_contract_json,
        'draftable', true,
        'row_backed_draft_scope', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      )
    ) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
    COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'preview_row_id', selected_page.preview_row_id::text,
      'row_key', selected_page.row_key,
      'row_ordinal', selected_page.row_ordinal,
      'timesheet_id', CASE WHEN selected_page.timesheet_id IS NULL THEN NULL ELSE selected_page.timesheet_id::text END,
      'candidate_id', selected_page.candidate_id::text,
      'pay_channel', selected_page.pay_channel,
      'economic_key', selected_page.economic_key_json,
      'amount_ex_vat', selected_page.amount_ex_vat,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    )) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
    jsonb_build_object(
      'selected_row_count_seeded_in_page', COUNT(*)::integer,
      'selected_amount_ex_vat_seeded_in_page', ROUND(COALESCE(SUM(selected_page.amount_ex_vat), 0), 2),
      'selected_preview_row_ids', COALESCE(jsonb_agg(to_jsonb(selected_page.preview_row_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
      'row_backed_draft_scope', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    jsonb_build_object(
      'source', 'banking_pay_workbench_preview_rows',
      'operation_id', p_operation_id::text,
      'workbench_session_id', p_workbench_session_id::text,
      'pay_channel_scope', v_scope_filter,
      'same_week_paye_override', COALESCE(p_same_week_paye_override_json, '{}'::jsonb),
      'selected_rows_are_row_backed', true,
      'selected_preview_row_ids', COALESCE(jsonb_agg(to_jsonb(selected_page.preview_row_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
      'economic_keyspace', 'timesheet_id,key_type,key_value',
      'source_publication_attestation', COALESCE((
        SELECT source_scope.certified_preview_publication_attestation_json
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = p_workbench_session_id
          AND source_scope.candidate_id = selected_page.candidate_id
          AND source_scope.certified_preview_publication_parity_ok IS TRUE
          AND source_scope.certified_preview_publication_session_version = v_session.version
        LIMIT 1
      ), '{}'::jsonb),
      'source_build_run_id', (
        SELECT source_scope.certified_preview_publication_source_build_run_id::text
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = p_workbench_session_id
          AND source_scope.candidate_id = selected_page.candidate_id
          AND source_scope.certified_preview_publication_parity_ok IS TRUE
          AND source_scope.certified_preview_publication_session_version = v_session.version
        LIMIT 1
      ),
      'source_publication_id', (
        SELECT source_scope.certified_preview_publication_source_publication_id::text
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = p_workbench_session_id
          AND source_scope.candidate_id = selected_page.candidate_id
          AND source_scope.certified_preview_publication_parity_ok IS TRUE
          AND source_scope.certified_preview_publication_session_version = v_session.version
        LIMIT 1
      ),
      'fast_reversion_eligible', COALESCE((
        SELECT source_scope.certified_preview_publication_source_publication_id IS NOT NULL
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = p_workbench_session_id
          AND source_scope.candidate_id = selected_page.candidate_id
          AND source_scope.certified_preview_publication_parity_ok IS TRUE
          AND source_scope.certified_preview_publication_session_version = v_session.version
        LIMIT 1
      ), false),
      'fast_reversion_ineligible_reason', CASE WHEN COALESCE((
        SELECT source_scope.certified_preview_publication_source_publication_id IS NOT NULL
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = p_workbench_session_id
          AND source_scope.candidate_id = selected_page.candidate_id
          AND source_scope.certified_preview_publication_parity_ok IS TRUE
          AND source_scope.certified_preview_publication_session_version = v_session.version
        LIMIT 1
      ), false) THEN NULL ELSE 'LEGACY_PHYSICAL_PUBLICATION_MISSING' END,
      'semantic_contract_version', (
        SELECT source_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = p_workbench_session_id
          AND source_scope.candidate_id = selected_page.candidate_id
          AND source_scope.certified_preview_publication_parity_ok IS TRUE
          AND source_scope.certified_preview_publication_session_version = v_session.version
        LIMIT 1
      ),
      'semantic_proof_digest', (
        SELECT source_scope.certified_preview_publication_attestation_json->>'semantic_proof_digest'
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = p_workbench_session_id
          AND source_scope.candidate_id = selected_page.candidate_id
          AND source_scope.certified_preview_publication_parity_ok IS TRUE
          AND source_scope.certified_preview_publication_session_version = v_session.version
        LIMIT 1
      ),
      'source_identity_digest', (
        SELECT source_scope.certified_preview_publication_attestation_json->>'source_identity_digest'
        FROM public.banking_pay_workbench_session_scope AS source_scope
        WHERE source_scope.session_id = p_workbench_session_id
          AND source_scope.candidate_id = selected_page.candidate_id
          AND source_scope.certified_preview_publication_parity_ok IS TRUE
          AND source_scope.certified_preview_publication_session_version = v_session.version
        LIMIT 1
      ),
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    md5(jsonb_build_object(
      'operation_id', p_operation_id::text,
      'workbench_session_id', p_workbench_session_id::text,
      'candidate_id', selected_page.candidate_id::text,
      'pay_channel', selected_page.pay_channel,
      'selected_preview_row_ids', COALESCE(jsonb_agg(to_jsonb(selected_page.preview_row_id::text) ORDER BY selected_page.row_ordinal, selected_page.preview_row_id), '[]'::jsonb),
      'source_session_version', v_session.version
    )::text),
    ROW_NUMBER() OVER (ORDER BY selected_page.pay_channel, selected_page.candidate_id)::integer,
    'SCOPED',
    v_now,
    v_now
  FROM pg_temp.tmp_pay_workbench_draft_scope_selected_page AS selected_page
  WHERE selected_page.pay_channel IN ('PAYE', 'UMBRELLA')
  GROUP BY selected_page.candidate_id, selected_page.pay_channel
  ON CONFLICT (operation_id, candidate_id, pay_channel)
  DO UPDATE
  SET workbench_session_id = EXCLUDED.workbench_session_id,
      source_snapshot_run_id = EXCLUDED.source_snapshot_run_id,
      source_session_version = EXCLUDED.source_session_version,
      pay_batch_id = COALESCE(public.banking_pay_operation_candidate_scope.pay_batch_id, EXCLUDED.pay_batch_id),
      selected_preview_row_ids_json = EXCLUDED.selected_preview_row_ids_json,
      selected_timesheet_ids_json = EXCLUDED.selected_timesheet_ids_json,
      selected_finance_case_ids_json = EXCLUDED.selected_finance_case_ids_json,
      effective_payees_json = EXCLUDED.effective_payees_json,
      effective_case_resolution_states_json = EXCLUDED.effective_case_resolution_states_json,
      effective_canonical_preview_lines_json = EXCLUDED.effective_canonical_preview_lines_json,
      selected_canonical_preview_lines_json = EXCLUDED.selected_canonical_preview_lines_json,
      baseline_component_rows_json = EXCLUDED.baseline_component_rows_json,
      candidate_totals_json = EXCLUDED.candidate_totals_json,
      allocation_basis_json = COALESCE(public.banking_pay_operation_candidate_scope.allocation_basis_json, '{}'::jsonb) || EXCLUDED.allocation_basis_json,
      scope_hash = EXCLUDED.scope_hash,
      chunk_sequence = EXCLUDED.chunk_sequence,
      status = CASE WHEN public.banking_pay_operation_candidate_scope.status IN ('PENDING', 'SCOPED') THEN 'SCOPED' ELSE public.banking_pay_operation_candidate_scope.status END,
      updated_at_utc = v_now;

  SELECT COUNT(DISTINCT selected_page.candidate_id::text || ':' || selected_page.pay_channel)::integer,
         COUNT(*)::integer,
         COUNT(DISTINCT selected_page.timesheet_id) FILTER (WHERE selected_page.timesheet_id IS NOT NULL)::integer,
         COUNT(DISTINCT selected_page.finance_case_id) FILTER (WHERE selected_page.finance_case_id IS NOT NULL)::integer,
         COUNT(DISTINCT selected_page.pay_channel)::integer
  INTO v_candidate_scope_count, v_selected_count, v_timesheet_count, v_finance_case_count, v_pay_channel_count
  FROM pg_temp.tmp_pay_workbench_draft_scope_selected_page AS selected_page;

  IF COALESCE(v_selected_count, 0) > 0 AND COALESCE(v_candidate_scope_count, 0) <= 0 THEN
    RAISE EXCEPTION 'DRAFT_CANDIDATE_SCOPE_EMPTY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'DRAFT_CANDIDATE_SCOPE_EMPTY',
              'operation_id', p_operation_id::text,
              'workbench_session_id', p_workbench_session_id::text,
              'selected_row_count', COALESCE(v_selected_count, 0),
              'message', 'Selected preview rows did not persist into candidate scope.'
            )::text;
  END IF;

  SELECT md5(COALESCE(string_agg(
           scope_row.candidate_id::text || ':' || scope_row.pay_channel || ':' || scope_row.scope_hash,
           '|' ORDER BY scope_row.pay_channel, scope_row.candidate_id
         ), ''))
  INTO v_operation_scope_hash
  FROM public.banking_pay_operation_candidate_scope AS scope_row
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.workbench_session_id = p_workbench_session_id;

  -- Finish every potentially large scope/JSON operation before taking the
  -- scalar generation lock. Only the final recheck and FROZEN seal follow it.
  SELECT COUNT(*)::integer
  INTO v_active_workbench_job_count
  FROM public.banking_pay_workbench_jobs AS blocking_job
  WHERE blocking_job.session_id = p_workbench_session_id
    AND blocking_job.status IN ('QUEUED', 'RUNNING')
    AND blocking_job.job_type IN (
      'WORKBENCH_SESSION_SCOPE_SEED',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'WORKBENCH_SESSION_CLONE_REBASE',
      'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
      'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
      'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
    );

  v_scope_blocker := public.pay_workbench_scope_blocker_state_v1(
    p_workbench_session_id,
    v_scope_generation_start,
    NULL::uuid
  );
  v_scope_upstream_active_count := COALESCE((v_scope_blocker->>'upstream_active_count')::integer, 0)
    + COALESCE((v_scope_blocker->>'session_active_count')::integer, 0);
  v_scope_upstream_failed_count := COALESCE((v_scope_blocker->>'upstream_unresolved_failure_count')::integer, 0)
    + COALESCE((v_scope_blocker->>'session_unresolved_failure_count')::integer, 0)
    + COALESCE((v_scope_blocker->>'session_scope_failed_count')::integer, 0)
    + COALESCE((v_scope_blocker->>'session_line_failed_count')::integer, 0);

  IF v_active_workbench_job_count > 0 OR v_scope_upstream_active_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_REFRESH_IN_PROGRESS'
      USING ERRCODE = 'P0001';
  END IF;

  IF v_scope_upstream_failed_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_RECONCILIATION_FAILED'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT change_counter.seq
  INTO v_scope_generation_final
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate_scope_generation'
  FOR UPDATE;

  IF COALESCE(v_scope_generation_final, 0) <> v_scope_generation_start
     OR COALESCE(v_session.scope_change_generation_applied, 0) <> COALESCE(v_scope_generation_final, 0) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_CHANGED_BEFORE_FREEZE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SCOPE_CHANGED_BEFORE_FREEZE',
              'scope_change_generation_start', v_scope_generation_start,
              'scope_change_generation_final', COALESCE(v_scope_generation_final, 0),
              'message', 'Banking Pay changed while the draft scope was being prepared. Review the refreshed rows and try again.'
            )::text;
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'draft_scope_last_seeded_at_utc', v_now::text,
          'draft_scope_last_selected_row_count', COALESCE(v_selected_count, 0),
          'draft_scope_last_candidate_scope_count', COALESCE(v_candidate_scope_count, 0),
          'draft_scope_selection_resolved_to_current', COALESCE(v_selection_resolved_to_current, false),
          'draft_scope_resolved_current_selected_preview_row_ids', COALESCE(v_resolved_current_selection_ids, '[]'::jsonb)
        )
      ),
      scope_freeze_status = 'FROZEN',
      frozen_scope_change_generation = v_scope_generation_final,
      scope_frozen_at_utc = v_now,
      source_scope_seed_complete = true,
      frozen_candidate_scope_count = COALESCE(v_candidate_scope_count, 0),
      frozen_selected_row_count = COALESCE(v_selected_count, 0),
      frozen_operation_scope_hash = v_operation_scope_hash,
      frozen_source_session_version = v_session.version,
      frozen_source_snapshot_run_id = v_session.source_snapshot_run_id,
      post_freeze_scope_status = 'NONE',
      post_freeze_observed_generation = NULL::bigint,
      post_freeze_relevant_generation = NULL::bigint,
      post_freeze_scope_checked_at_utc = NULL::timestamptz,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN QUERY
  SELECT
    COALESCE(v_candidate_scope_count, 0),
    COALESCE(v_selected_count, 0),
    COALESCE(v_timesheet_count, 0),
    COALESCE(v_finance_case_count, 0),
    COALESCE(v_pay_channel_count, 0);
END;
$function$;

-- pay_workbench_prepare_draft(uuid,uuid,jsonb,text,text,boolean,boolean,uuid,timestamp with time zone,uuid,boolean,boolean)
CREATE OR REPLACE FUNCTION public.pay_workbench_prepare_draft(p_session_id uuid, p_actor_user_id uuid, p_selected_preview_row_ids jsonb DEFAULT NULL::jsonb, p_pay_channel_scope text DEFAULT NULL::text, p_override_reason text DEFAULT NULL::text, p_override_continue boolean DEFAULT false, p_override_verified boolean DEFAULT false, p_override_verified_by_user_id uuid DEFAULT NULL::uuid, p_override_verified_at_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_operation_id uuid DEFAULT NULL::uuid, p_operation_mode boolean DEFAULT false, p_allow_legacy_unchunked boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_scope_filter text := UPPER(BTRIM(COALESCE(NULLIF(p_pay_channel_scope, ''), 'ALL')));
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_mode boolean := (COALESCE(p_operation_mode, false) = true OR p_operation_id IS NOT NULL);
  v_input_count integer := 0;
  v_sample_row_count integer := 0;
  v_sample_candidate_count integer := 0;
  v_sample_paye_count integer := 0;
  v_sample_umbrella_count integer := 0;
  v_selected_ready_row_count integer := 0;
  v_selected_ready_paye_row_count integer := 0;
  v_selected_ready_umbrella_row_count integer := 0;
  v_scope_selected_ready_row_count integer := 0;
  v_no_rows_block_reason_code text := NULL::text;
  v_no_rows_block_message text := NULL::text;
  v_ready_selected_exists boolean := false;
  v_unready_selected_exists boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_paye_create_blocked boolean := false;
  v_paye_override_required boolean := false;
  v_paye_scope_blocked boolean := false;
  v_paye_block_reason_code text := NULL::text;
  v_paye_block_message text := NULL::text;
  v_selected_sample jsonb := '[]'::jsonb;
  v_stale_selection_ids jsonb := '[]'::jsonb;
  v_missing_selection_ids jsonb := '[]'::jsonb;
  v_current_unready_selected_exists boolean := false;
  v_malformed_selected_exists boolean := false;
  v_malformed_selected_sample jsonb := '[]'::jsonb;
  v_synthetic_total_selected_exists boolean := false;
  v_synthetic_total_selected_sample jsonb := '[]'::jsonb;
  v_direct_current_selection_match_count integer := 0;
  v_current_ready_selected_row_count integer := 0;
  v_selection_resolved_to_current boolean := false;
  v_resolved_current_selection_ids jsonb := '[]'::jsonb;
  v_resolved_selection_match_count integer := 0;
  v_resolved_selection_distinct_count integer := 0;
  v_active_workbench_job_count integer := 0;
  v_active_workbench_job_sample jsonb := '[]'::jsonb;
  v_expected_progress_counter_version bigint := NULL::bigint;
  v_expected_progress_counter_version_text text := NULL::text;
  v_expected_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_expected_selected_preview_row_count integer := 0;
  v_expected_selected_preview_row_distinct_count integer := 0;
  v_current_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_current_selected_preview_row_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_PROGRESS');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF v_scope_filter NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be ALL, PAYE, or UMBRELLA';
  END IF;

  IF COALESCE(p_allow_legacy_unchunked, false) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PREPARE_DRAFT_LEGACY_UNCHUNKED_DISABLED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_PREPARE_DRAFT_LEGACY_UNCHUNKED_DISABLED',
              'message', 'Legacy all-at-once draft creation is permanently disabled. Use the operation-scoped DRAFT_CREATE runner.',
              'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
              'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END
            )::text;
  END IF;

  IF p_selected_preview_row_ids IS NOT NULL THEN
    IF jsonb_typeof(p_selected_preview_row_ids) <> 'array' THEN
      RAISE EXCEPTION 'selected_preview_row_ids must be a JSON array when supplied';
    END IF;

    v_input_count := jsonb_array_length(p_selected_preview_row_ids);

    IF v_input_count > 100 THEN
      RAISE EXCEPTION 'selected_preview_row_ids exceeds the 100 row operation-validation cap: %', v_input_count;
    END IF;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  IF v_operation_mode IS NOT TRUE THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_REQUIRED',
      'message', 'Normal draft creation must use the scalable DRAFT_CREATE operation flow. Legacy all-at-once draft creation is disabled for the full row-backed cutover.',
      'session_id', p_session_id::text,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_ID_REQUIRED',
      'message', 'pay_workbench_prepare_draft operation mode requires p_operation_id.',
      'session_id', p_session_id::text
    )::text;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_NOT_FOUND',
      'message', 'pay_workbench_prepare_draft operation mode could not find the supplied operation.',
      'session_id', p_session_id::text,
      'operation_id', p_operation_id::text
    )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation_row.operation_type, ''))) <> 'DRAFT_CREATE' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_TYPE_INVALID',
      'message', 'pay_workbench_prepare_draft operation mode requires a DRAFT_CREATE operation.',
      'session_id', p_session_id::text,
      'operation_id', p_operation_id::text,
      'operation_type', v_operation_row.operation_type
    )::text;
  END IF;

  IF v_operation_row.workbench_session_id IS DISTINCT FROM p_session_id THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_SESSION_MISMATCH',
      'message', 'pay_workbench_prepare_draft operation must already be bound to this exact workbench session.',
      'session_id', p_session_id::text,
      'operation_id', p_operation_id::text,
      'operation_workbench_session_id', CASE WHEN v_operation_row.workbench_session_id IS NULL THEN NULL ELSE v_operation_row.workbench_session_id::text END
    )::text;
  END IF;

  IF v_operation_row.actor_user_id IS DISTINCT FROM p_actor_user_id THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_ACTOR_MISMATCH',
      'message', 'pay_workbench_prepare_draft operation must already be bound to this exact actor.',
      'session_id', p_session_id::text,
      'operation_id', p_operation_id::text
    )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation_row.status, ''))) <> 'RUNNING' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_STATUS_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_STATUS_INVALID',
              'operation_id', p_operation_id::text,
              'status', v_operation_row.status,
              'required_status', 'RUNNING'
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_operation_row.phase, ''))) NOT IN ('INITIALISE', 'VALIDATE_SESSION') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_PHASE_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_PHASE_INVALID',
              'operation_id', p_operation_id::text,
              'phase', v_operation_row.phase,
              'allowed_phases', jsonb_build_array('INITIALISE', 'VALIDATE_SESSION')
            )::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  -- Workbench sessions are intentionally shared across authenticated Banking Pay
  -- users. session.actor_user_id records who created the session; operation.actor_user_id
  -- above remains the authoritative audit actor for this draft operation.

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN' OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  IF v_session_row.replacement_session_id IS NOT NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'WORKBENCH_SESSION_REPLACED',
      'message', 'This payment workbench has been replaced. Refresh the Banking Pay workbench and create the draft from the current session.',
      'session_id', p_session_id::text,
      'replacement_session_id', v_session_row.replacement_session_id::text
    )::text;
  END IF;

  -- Atomic final selection-review guard. The Worker records the exact global
  -- selected set and progress revision reviewed by the user before starting the
  -- operation. Holding the session row lock prevents a concurrent selection
  -- mutation from passing between this comparison and draft preparation.
  v_expected_progress_counter_version_text := NULLIF(
    BTRIM(COALESCE(v_operation_row.input_json->>'expected_workbench_progress_counter_version', '')),
    ''
  );

  IF v_expected_progress_counter_version_text IS NULL
     OR LENGTH(v_expected_progress_counter_version_text) > 18
     OR v_expected_progress_counter_version_text !~ '^[0-9]+$' THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED',
              'message', 'Banking Pay changed before the draft could start. Review the latest selection, then click Create Draft again.',
              'session_id', p_session_id::text,
              'operation_id', p_operation_id::text,
              'reason', 'EXPECTED_PROGRESS_REVISION_MISSING_OR_INVALID'
            )::text;
  END IF;

  v_expected_progress_counter_version := v_expected_progress_counter_version_text::bigint;

  IF COALESCE(v_session_row.progress_counter_version, 0)::bigint IS DISTINCT FROM v_expected_progress_counter_version THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED',
              'message', 'Banking Pay was changed by another user or window. Review the latest selection, then click Create Draft again.',
              'session_id', p_session_id::text,
              'operation_id', p_operation_id::text,
              'expected_progress_counter_version', v_expected_progress_counter_version,
              'current_progress_counter_version', COALESCE(v_session_row.progress_counter_version, 0)
            )::text;
  END IF;

  v_expected_selected_preview_row_ids := COALESCE(
    v_operation_row.input_json->'expected_workbench_selected_preview_row_ids',
    'null'::jsonb
  );

  IF jsonb_typeof(v_expected_selected_preview_row_ids) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED',
              'message', 'Banking Pay changed before the draft could start. Review the latest selection, then click Create Draft again.',
              'session_id', p_session_id::text,
              'operation_id', p_operation_id::text,
              'reason', 'EXPECTED_SELECTION_MISSING_OR_INVALID'
            )::text;
  END IF;

  v_expected_selected_preview_row_count := jsonb_array_length(v_expected_selected_preview_row_ids);

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(v_expected_selected_preview_row_ids) AS expected_item(value)
    WHERE BTRIM(expected_item.value) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED',
              'message', 'Banking Pay changed before the draft could start. Review the latest selection, then click Create Draft again.',
              'session_id', p_session_id::text,
              'operation_id', p_operation_id::text,
              'reason', 'EXPECTED_SELECTION_ROW_ID_INVALID'
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_expected_selected_preview_row_distinct_count
  FROM (
    SELECT DISTINCT LOWER(BTRIM(expected_item.value)) AS preview_row_id
    FROM jsonb_array_elements_text(v_expected_selected_preview_row_ids) AS expected_item(value)
  ) AS distinct_expected_rows;

  IF v_expected_selected_preview_row_count IS DISTINCT FROM v_expected_selected_preview_row_distinct_count THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED',
              'message', 'Banking Pay changed before the draft could start. Review the latest selection, then click Create Draft again.',
              'session_id', p_session_id::text,
              'operation_id', p_operation_id::text,
              'reason', 'EXPECTED_SELECTION_CONTAINS_DUPLICATES'
            )::text;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(expected_rows.preview_row_id) ORDER BY expected_rows.preview_row_id), '[]'::jsonb)
  INTO v_expected_selected_preview_row_ids
  FROM (
    SELECT DISTINCT LOWER(BTRIM(expected_item.value)) AS preview_row_id
    FROM jsonb_array_elements_text(v_expected_selected_preview_row_ids) AS expected_item(value)
  ) AS expected_rows;

  SELECT COALESCE(jsonb_agg(to_jsonb(current_rows.preview_row_id) ORDER BY current_rows.preview_row_id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_current_selected_preview_row_ids,
       v_current_selected_preview_row_count
  FROM (
    SELECT preview_row.id::text AS preview_row_id
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND preview_row.session_version = v_session_row.version
      AND LOWER(private.pay_workbench_preview_effective_section_v1(
            preview_row.section,
            preview_row.row_json
          )) = 'canonical_preview_lines'
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
      AND COALESCE(preview_row.selected, false) = true
      AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
  ) AS current_rows;

  IF v_current_selected_preview_row_count IS DISTINCT FROM v_expected_selected_preview_row_count
     OR v_current_selected_preview_row_ids IS DISTINCT FROM v_expected_selected_preview_row_ids THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SELECTION_CHANGED_REVIEW_REQUIRED',
              'message', 'Banking Pay was changed by another user or window. Review the latest selection, then click Create Draft again.',
              'session_id', p_session_id::text,
              'operation_id', p_operation_id::text,
              'expected_progress_counter_version', v_expected_progress_counter_version,
              'current_progress_counter_version', COALESCE(v_session_row.progress_counter_version, 0),
              'expected_selected_preview_row_count', v_expected_selected_preview_row_count,
              'current_selected_preview_row_count', v_current_selected_preview_row_count
            )::text;
  END IF;

  WITH active_workbench_jobs AS (
    SELECT job_row.id,
           job_row.job_type,
           job_row.status,
           job_row.candidate_id,
           CASE
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH', 'CANDIDATE_DELTA_REFRESH', 'DELTA_REFRESH') THEN 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_SESSION_CLONE_REBASE', 'SESSION_CLONE_REBASE', 'CLONE_REBASE') THEN 'WORKBENCH_SESSION_CLONE_REBASE'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_SOURCE_BUILD', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK', 'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE', 'CANDIDATE_SOURCE_BUILD', 'CANDIDATE_SOURCE_BUILD_CHUNK', 'SOURCE_BUILD', 'SOURCE_BUILD_PAGE') THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_SESSION_SCOPE_SEED', 'SESSION_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED', 'WORKBENCH_SCOPE_SEED_PAGE', 'SCOPE_SEED_PAGE') THEN 'WORKBENCH_SESSION_SCOPE_SEED'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_SEED', 'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE', 'CANDIDATE_LINE_WORK_SEED', 'CANDIDATE_LINE_WORK_SEED_PAGE', 'LINE_WORK_SEED_PAGE', 'SNAPSHOT_CANDIDATE_REFRESH', 'CANDIDATE_REFRESH') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_SEED'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_CANDIDATE_LINE_WORK_PROCESS', 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'CANDIDATE_LINE_WORK_PROCESS', 'CANDIDATE_LINE_WORK_PROCESS_CHUNK', 'LINE_WORK_PROCESS', 'LINE_WORK_PROCESS_CHUNK') THEN 'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS'
             WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN ('WORKBENCH_PREVIEW_ROWS_MATERIALISE', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE', 'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK', 'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROWS_MATERIALISE', 'PREVIEW_ROWS_MATERIALIZE', 'PREVIEW_ROWS_MATERIALISE_CHUNK', 'PREVIEW_ROWS_MATERIALIZE_CHUNK', 'PREVIEW_ROW_MATERIALISE_CHUNK', 'PREVIEW_ROW_MATERIALIZE_CHUNK') THEN 'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
             ELSE UPPER(BTRIM(COALESCE(job_row.job_type, '')))
           END AS canonical_job_type
    FROM public.banking_pay_workbench_jobs AS job_row
    WHERE job_row.session_id = p_session_id
      AND UPPER(BTRIM(COALESCE(job_row.status, ''))) IN ('QUEUED', 'RUNNING')
  ), blocking_jobs AS (
    SELECT active_workbench_jobs.*
    FROM active_workbench_jobs
    WHERE active_workbench_jobs.canonical_job_type IN (
      'WORKBENCH_SESSION_SCOPE_SEED',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'WORKBENCH_SESSION_CLONE_REBASE',
      'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
      'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
      'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
    )
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(jsonb_build_object(
           'job_id', blocking_jobs.id::text,
           'job_type', blocking_jobs.job_type,
           'canonical_job_type', blocking_jobs.canonical_job_type,
           'status', blocking_jobs.status,
           'candidate_id', CASE WHEN blocking_jobs.candidate_id IS NULL THEN NULL ELSE blocking_jobs.candidate_id::text END
         ) ORDER BY blocking_jobs.canonical_job_type, blocking_jobs.id) FILTER (WHERE blocking_jobs.id IS NOT NULL), '[]'::jsonb)
  INTO v_active_workbench_job_count,
       v_active_workbench_job_sample
  FROM blocking_jobs;

  IF COALESCE(v_active_workbench_job_count, 0) > 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'WORKBENCH_REFRESH_IN_PROGRESS',
      'message', 'Banking Pay is refreshing this workbench. Wait for the refresh to finish, review the selection, and then create the draft.',
      'session_id', p_session_id::text,
      'active_workbench_job_count', COALESCE(v_active_workbench_job_count, 0),
      'active_workbench_jobs', COALESCE(v_active_workbench_job_sample, '[]'::jsonb)
    )::text;
  END IF;

  UPDATE public.banking_pay_operations AS operation_update
  SET updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids ON COMMIT DROP AS
  SELECT DISTINCT BTRIM(supplied_id.value) AS supplied_id
  FROM jsonb_array_elements_text(COALESCE(p_selected_preview_row_ids, '[]'::jsonb)) AS supplied_id(value)
  WHERE p_selected_preview_row_ids IS NOT NULL
    AND BTRIM(supplied_id.value) <> '';

  IF p_selected_preview_row_ids IS NOT NULL AND COALESCE(v_input_count, 0) > 0 THEN
    DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_prepare_draft_resolved_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_prepare_draft_resolved_ids ON COMMIT DROP AS
    WITH supplied_ids AS (
      SELECT supplied_id.supplied_id
      FROM pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids AS supplied_id
    ),
    direct_current_matches AS (
      SELECT DISTINCT
        supplied_ids.supplied_id,
        current_preview_row.id::text AS resolved_id
      FROM supplied_ids
      JOIN public.banking_pay_workbench_preview_rows AS current_preview_row
        ON current_preview_row.session_id = p_session_id
       AND current_preview_row.session_version = v_session_row.version
       AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
       AND COALESCE(current_preview_row.selected, false) = true
       AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
       AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND (
         current_preview_row.id::text = supplied_ids.supplied_id
         OR current_preview_row.row_key = supplied_ids.supplied_id
         OR current_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
         OR current_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
         OR current_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
       )
    ),
    historical_candidates AS (
      SELECT
        supplied_ids.supplied_id,
        historical_preview_row.id AS historical_preview_id,
        historical_preview_row.session_version,
        historical_preview_row.row_ordinal,
        historical_preview_row.candidate_id,
        historical_preview_row.timesheet_id,
        historical_preview_row.row_key,
        private.pay_workbench_preview_effective_section_v1(
          historical_preview_row.section,
          historical_preview_row.row_json
        ) AS section,
        NULLIF(BTRIM(COALESCE(historical_preview_row.key_type, historical_preview_row.row_json#>>'{economic_key,key_type}', historical_preview_row.row_json->>'component_key_type', '')), '') AS key_type,
        NULLIF(BTRIM(COALESCE(historical_preview_row.key_value, historical_preview_row.row_json#>>'{economic_key,key_value}', historical_preview_row.row_json->>'component_key_value', '')), '') AS key_value,
        UPPER(BTRIM(COALESCE(historical_preview_row.row_json->>'pay_channel', historical_preview_row.row_json->>'current_pay_method', historical_preview_row.row_json->>'candidate_pay_method', ''))) AS pay_channel,
        ROW_NUMBER() OVER (
          PARTITION BY supplied_ids.supplied_id
          ORDER BY historical_preview_row.session_version DESC, historical_preview_row.updated_at_utc DESC NULLS LAST, historical_preview_row.created_at_utc DESC NULLS LAST, historical_preview_row.id DESC
        ) AS match_rank
      FROM supplied_ids
      JOIN public.banking_pay_workbench_preview_rows AS historical_preview_row
        ON historical_preview_row.session_id = p_session_id
       AND (
         historical_preview_row.id::text = supplied_ids.supplied_id
         OR historical_preview_row.row_key = supplied_ids.supplied_id
         OR historical_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
         OR historical_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
         OR historical_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
       )
    ),
    historical_best AS (
      SELECT
        historical_candidates.supplied_id,
        historical_candidates.candidate_id,
        historical_candidates.timesheet_id,
        historical_candidates.row_key,
        historical_candidates.section,
        historical_candidates.key_type,
        historical_candidates.key_value,
        historical_candidates.pay_channel
      FROM historical_candidates
      WHERE historical_candidates.match_rank = 1
    ),
    economic_key_current_matches AS (
      SELECT DISTINCT
        historical_best.supplied_id,
        current_preview_row.id::text AS resolved_id
      FROM historical_best
      JOIN public.banking_pay_workbench_preview_rows AS current_preview_row
        ON current_preview_row.session_id = p_session_id
       AND current_preview_row.session_version = v_session_row.version
       AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
       AND COALESCE(current_preview_row.selected, false) = true
       AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
       AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND current_preview_row.candidate_id IS NOT DISTINCT FROM historical_best.candidate_id
       AND current_preview_row.timesheet_id IS NOT DISTINCT FROM historical_best.timesheet_id
       AND private.pay_workbench_preview_effective_section_v1(
             current_preview_row.section,
             current_preview_row.row_json
           ) = COALESCE(NULLIF(BTRIM(historical_best.section), ''), 'canonical_preview_lines')
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_type, current_preview_row.row_json#>>'{economic_key,key_type}', current_preview_row.row_json->>'component_key_type', '')), '') IS NOT DISTINCT FROM historical_best.key_type
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_value, current_preview_row.row_json#>>'{economic_key,key_value}', current_preview_row.row_json->>'component_key_value', '')), '') IS NOT DISTINCT FROM historical_best.key_value
       AND NULLIF(BTRIM(current_preview_row.row_key), '') IS NOT DISTINCT FROM NULLIF(BTRIM(historical_best.row_key), '')
       AND (
         historical_best.pay_channel IS NULL
         OR historical_best.pay_channel = ''
         OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = historical_best.pay_channel
       )
    ),
    operation_contracts AS (
      SELECT
        contract_entry.ordinality::integer AS contract_index,
        NULLIF(BTRIM(COALESCE(
          contract_entry.value->>'preview_row_id',
          contract_entry.value->>'materialised_preview_row_id',
          contract_entry.value->>'row_id',
          contract_entry.value->>'id',
          contract_entry.value->>'selected_preview_row_id'
        )), '') AS supplied_id,
        NULLIF(BTRIM(COALESCE(contract_entry.value->>'presentation_preview_row_id', contract_entry.value->>'line_id', '')), '') AS presentation_preview_row_id,
        NULLIF(BTRIM(COALESCE(contract_entry.value->>'row_key', '')), '') AS row_key,
        COALESCE(NULLIF(BTRIM(contract_entry.value->>'section'), ''), 'canonical_preview_lines') AS section,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(contract_entry.value->>'candidate_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(contract_entry.value->>'candidate_id', '')), '')::uuid
          ELSE NULL::uuid
        END AS candidate_id,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(contract_entry.value->>'timesheet_id', contract_entry.value#>>'{economic_key,timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN NULLIF(BTRIM(COALESCE(contract_entry.value->>'timesheet_id', contract_entry.value#>>'{economic_key,timesheet_id}', '')), '')::uuid
          ELSE NULL::uuid
        END AS timesheet_id,
        NULLIF(BTRIM(COALESCE(contract_entry.value->>'key_type', contract_entry.value#>>'{economic_key,key_type}', '')), '') AS key_type,
        NULLIF(BTRIM(COALESCE(contract_entry.value->>'key_value', contract_entry.value#>>'{economic_key,key_value}', '')), '') AS key_value,
        UPPER(NULLIF(BTRIM(COALESCE(contract_entry.value->>'pay_channel', '')), '')) AS pay_channel
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(COALESCE(v_operation_row.input_json->'draft_selected_preview_row_contracts', '[]'::jsonb)) = 'array'
            THEN COALESCE(v_operation_row.input_json->'draft_selected_preview_row_contracts', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS contract_entry(value, ordinality)
      WHERE jsonb_typeof(contract_entry.value) = 'object'
    ),
    operation_contract_current_matches AS (
      SELECT DISTINCT
        supplied_ids.supplied_id,
        current_preview_row.id::text AS resolved_id
      FROM supplied_ids
      JOIN operation_contracts AS operation_contract
        ON (
          operation_contract.supplied_id = supplied_ids.supplied_id
          OR operation_contract.presentation_preview_row_id = supplied_ids.supplied_id
          OR operation_contract.row_key = supplied_ids.supplied_id
        )
      JOIN public.banking_pay_workbench_preview_rows AS current_preview_row
        ON current_preview_row.session_id = p_session_id
       AND current_preview_row.session_version = v_session_row.version
       AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
       AND COALESCE(current_preview_row.selected, false) = true
       AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
       AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       AND operation_contract.candidate_id IS NOT NULL
       AND operation_contract.timesheet_id IS NOT NULL
       AND operation_contract.row_key IS NOT NULL
       AND operation_contract.key_type IS NOT NULL
       AND operation_contract.key_value IS NOT NULL
       AND current_preview_row.candidate_id IS NOT DISTINCT FROM operation_contract.candidate_id
       AND current_preview_row.timesheet_id IS NOT DISTINCT FROM operation_contract.timesheet_id
       AND private.pay_workbench_preview_effective_section_v1(
             current_preview_row.section,
             current_preview_row.row_json
           ) = COALESCE(NULLIF(BTRIM(operation_contract.section), ''), 'canonical_preview_lines')
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_type, current_preview_row.row_json#>>'{economic_key,key_type}', current_preview_row.row_json->>'component_key_type', '')), '') IS NOT DISTINCT FROM operation_contract.key_type
       AND NULLIF(BTRIM(COALESCE(current_preview_row.key_value, current_preview_row.row_json#>>'{economic_key,key_value}', current_preview_row.row_json->>'component_key_value', '')), '') IS NOT DISTINCT FROM operation_contract.key_value
       AND NULLIF(BTRIM(current_preview_row.row_key), '') IS NOT DISTINCT FROM NULLIF(BTRIM(operation_contract.row_key), '')
       AND (
         operation_contract.pay_channel IS NULL
         OR operation_contract.pay_channel = ''
         OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = operation_contract.pay_channel
       )
    )
    SELECT
      supplied_ids.supplied_id,
      COALESCE(direct_current_matches.resolved_id, economic_key_current_matches.resolved_id, operation_contract_current_matches.resolved_id) AS resolved_id
    FROM supplied_ids
    LEFT JOIN direct_current_matches
      ON direct_current_matches.supplied_id = supplied_ids.supplied_id
    LEFT JOIN economic_key_current_matches
      ON economic_key_current_matches.supplied_id = supplied_ids.supplied_id
    LEFT JOIN operation_contract_current_matches
      ON operation_contract_current_matches.supplied_id = supplied_ids.supplied_id;

    SELECT COUNT(*)::integer,
           COUNT(DISTINCT resolved_selection.resolved_id)::integer,
           COALESCE(jsonb_agg(to_jsonb(resolved_selection.resolved_id) ORDER BY resolved_selection.resolved_id), '[]'::jsonb)
    INTO v_resolved_selection_match_count, v_resolved_selection_distinct_count, v_resolved_current_selection_ids
    FROM pg_temp.tmp_pay_workbench_prepare_draft_resolved_ids AS resolved_selection
    WHERE NULLIF(BTRIM(COALESCE(resolved_selection.resolved_id, '')), '') IS NOT NULL;

    IF COALESCE(v_resolved_selection_match_count, 0) = COALESCE(v_input_count, 0)
       AND COALESCE(v_resolved_selection_distinct_count, 0) = COALESCE(v_input_count, 0) THEN
      SELECT EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_workbench_prepare_draft_resolved_ids AS resolved_selection
        WHERE resolved_selection.resolved_id IS DISTINCT FROM resolved_selection.supplied_id
      )
      INTO v_selection_resolved_to_current;

      TRUNCATE TABLE pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids;

      INSERT INTO pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids (supplied_id)
      SELECT resolved_selection.resolved_id
      FROM pg_temp.tmp_pay_workbench_prepare_draft_resolved_ids AS resolved_selection
      WHERE NULLIF(BTRIM(COALESCE(resolved_selection.resolved_id, '')), '') IS NOT NULL
      ORDER BY resolved_selection.resolved_id;
    ELSE
      SELECT COUNT(*)::integer
      INTO v_current_ready_selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS current_preview_row
      WHERE current_preview_row.session_id = p_session_id
        AND current_preview_row.session_version = v_session_row.version
        AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
        AND COALESCE(current_preview_row.selected, false) = true
        AND UPPER(BTRIM(COALESCE(current_preview_row.selection_state, ''))) = 'SELECTED'
        AND UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
        AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(current_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(current_preview_row.row_json->>'pay_channel', current_preview_row.row_json->>'current_pay_method', current_preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter);
    END IF;
  END IF;

  IF p_selected_preview_row_ids IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(supplied_ids.supplied_id) ORDER BY supplied_ids.supplied_id), '[]'::jsonb)
    INTO v_stale_selection_ids
    FROM pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids AS supplied_ids
    WHERE EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS any_preview_row
      WHERE any_preview_row.session_id = p_session_id
        AND (
          any_preview_row.id::text = supplied_ids.supplied_id
          OR any_preview_row.row_key = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
        )
    )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_preview_rows AS current_preview_row
        WHERE current_preview_row.session_id = p_session_id
          AND current_preview_row.session_version = v_session_row.version
          AND UPPER(BTRIM(COALESCE(current_preview_row.status, ''))) = 'READY'
          AND (
            current_preview_row.id::text = supplied_ids.supplied_id
            OR current_preview_row.row_key = supplied_ids.supplied_id
            OR current_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
            OR current_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
            OR current_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
          )
      );

    SELECT COALESCE(jsonb_agg(to_jsonb(supplied_ids.supplied_id) ORDER BY supplied_ids.supplied_id), '[]'::jsonb)
    INTO v_missing_selection_ids
    FROM pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids AS supplied_ids
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS any_preview_row
      WHERE any_preview_row.session_id = p_session_id
        AND (
          any_preview_row.id::text = supplied_ids.supplied_id
          OR any_preview_row.row_key = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'preview_row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'row_id' = supplied_ids.supplied_id
          OR any_preview_row.row_json->>'line_id' = supplied_ids.supplied_id
        )
    );

    IF jsonb_array_length(COALESCE(v_stale_selection_ids, '[]'::jsonb)) > 0
       OR jsonb_array_length(COALESCE(v_missing_selection_ids, '[]'::jsonb)) > 0 THEN
      RAISE EXCEPTION 'WORKBENCH_STALE_SELECTION'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_STALE_SELECTION',
                'session_id', p_session_id::text,
                'session_version', v_session_row.version,
                'rejected_preview_row_ids', COALESCE(v_stale_selection_ids, '[]'::jsonb) || COALESCE(v_missing_selection_ids, '[]'::jsonb),
                'stale_preview_row_ids', COALESCE(v_stale_selection_ids, '[]'::jsonb),
                'missing_preview_row_ids', COALESCE(v_missing_selection_ids, '[]'::jsonb),
                'message', 'Selected preview rows are not part of the current ready workbench session version. Refresh the preview page and try again.'
              )::text;
    END IF;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_preview_rows AS blocked_selected_row
    WHERE blocked_selected_row.session_id = p_session_id
      AND blocked_selected_row.session_version = v_session_row.version
      AND COALESCE(blocked_selected_row.selected, false) = true
      AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(blocked_selected_row.row_json->>'pay_channel', blocked_selected_row.row_json->>'current_pay_method', blocked_selected_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
      AND (
        p_selected_preview_row_ids IS NULL
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids AS supplied_id
          WHERE supplied_id.supplied_id IN (blocked_selected_row.id::text, blocked_selected_row.row_key, blocked_selected_row.row_json->>'preview_row_id', blocked_selected_row.row_json->>'row_id', blocked_selected_row.row_json->>'line_id')
        )
      )
      AND (
        UPPER(BTRIM(COALESCE(blocked_selected_row.status, ''))) <> 'READY'
        OR UPPER(BTRIM(COALESCE(blocked_selected_row.selection_state, ''))) <> 'SELECTED'
      )
  )
  INTO v_current_unready_selected_exists;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE full_ready_selected.pay_channel = 'PAYE')::integer,
         COUNT(*) FILTER (WHERE full_ready_selected.pay_channel = 'UMBRELLA')::integer,
         COUNT(*) FILTER (WHERE v_scope_filter = 'ALL' OR full_ready_selected.pay_channel = v_scope_filter)::integer
  INTO v_selected_ready_row_count,
       v_selected_ready_paye_row_count,
       v_selected_ready_umbrella_row_count,
       v_scope_selected_ready_row_count
  FROM (
    SELECT
      UPPER(BTRIM(COALESCE(full_preview_row.row_json->>'pay_channel', full_preview_row.row_json->>'current_pay_method', full_preview_row.row_json->>'candidate_pay_method', ''))) AS pay_channel
    FROM public.banking_pay_workbench_preview_rows AS full_preview_row
    WHERE full_preview_row.session_id = p_session_id
      AND full_preview_row.session_version = v_session_row.version
      AND UPPER(BTRIM(COALESCE(full_preview_row.status, ''))) = 'READY'
      AND COALESCE(full_preview_row.selected, false) = true
      AND UPPER(BTRIM(COALESCE(full_preview_row.selection_state, ''))) = 'SELECTED'
      AND UPPER(BTRIM(COALESCE(full_preview_row.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
      AND LOWER(BTRIM(COALESCE(full_preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(full_preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND UPPER(BTRIM(COALESCE(full_preview_row.row_json->>'pay_channel', full_preview_row.row_json->>'current_pay_method', full_preview_row.row_json->>'candidate_pay_method', ''))) IN ('PAYE', 'UMBRELLA')
      AND (
        p_selected_preview_row_ids IS NULL
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids AS supplied_id
          WHERE supplied_id.supplied_id IN (full_preview_row.id::text, full_preview_row.row_key, full_preview_row.row_json->>'preview_row_id', full_preview_row.row_json->>'row_id', full_preview_row.row_json->>'line_id')
        )
      )
  ) AS full_ready_selected;

  IF COALESCE(v_scope_selected_ready_row_count, 0) = 0 THEN
    v_no_rows_block_reason_code := CASE
      WHEN v_scope_filter = 'PAYE' THEN 'NO_PAYE_ROWS_FOR_DRAFT_SCOPE'
      WHEN v_scope_filter = 'UMBRELLA' THEN 'NO_UMBRELLA_ROWS_FOR_DRAFT_SCOPE'
      ELSE 'NO_SELECTED_READY_ROWS'
    END;

    v_no_rows_block_message := CASE
      WHEN v_scope_filter = 'PAYE' THEN 'No PAYE rows are available for Create Draft. Choose Umbrella only or select PAYE-ready rows.'
      WHEN v_scope_filter = 'UMBRELLA' THEN 'No Umbrella rows are available for Create Draft. Choose PAYE only or select Umbrella-ready rows.'
      ELSE 'No selected Ready to Pay rows are available for Create Draft.'
    END;

    UPDATE public.banking_pay_operations AS operation_update
    SET progress_json = jsonb_strip_nulls(
          COALESCE(operation_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'draft_prepare_validated_at_utc', v_now::text,
            'draft_prepare_scope', v_scope_filter,
            'draft_prepare_block_reason_code', v_no_rows_block_reason_code,
            'draft_prepare_selected_ready_row_count', COALESCE(v_selected_ready_row_count, 0),
            'draft_prepare_selected_ready_paye_row_count', COALESCE(v_selected_ready_paye_row_count, 0),
            'draft_prepare_selected_ready_umbrella_row_count', COALESCE(v_selected_ready_umbrella_row_count, 0),
            'draft_prepare_scope_selected_ready_row_count', COALESCE(v_scope_selected_ready_row_count, 0),
            'draft_prepare_input_selection_count', COALESCE(v_input_count, 0),
            'draft_prepare_selection_resolved_to_current', COALESCE(v_selection_resolved_to_current, false)
          )
        ),
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'session_id', p_session_id::text,
      'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'session_version', v_session_row.version,
      'pay_date', CASE WHEN v_session_row.pay_date IS NULL THEN NULL ELSE v_session_row.pay_date::text END,
      'week_ending_cutoff', CASE WHEN v_session_row.week_ending_cutoff IS NULL THEN NULL ELSE v_session_row.week_ending_cutoff::text END,
      'pay_channel_scope', v_scope_filter,
      'selected_preview_row_count_known', true,
      'selected_preview_row_sample_count', 0,
      'selected_candidate_sample_count', 0,
      'paye_selected_row_sample_count', 0,
      'umbrella_selected_row_sample_count', 0,
      'selected_ready_row_count', COALESCE(v_selected_ready_row_count, 0),
      'selected_ready_paye_row_count', COALESCE(v_selected_ready_paye_row_count, 0),
      'selected_ready_umbrella_row_count', COALESCE(v_selected_ready_umbrella_row_count, 0),
      'scope_selected_ready_row_count', COALESCE(v_scope_selected_ready_row_count, 0),
      'scope_counts', jsonb_build_object(
        'selected_ready_total', COALESCE(v_selected_ready_row_count, 0),
        'selected_ready_paye', COALESCE(v_selected_ready_paye_row_count, 0),
        'selected_ready_umbrella', COALESCE(v_selected_ready_umbrella_row_count, 0),
        'selected_ready_for_scope', COALESCE(v_scope_selected_ready_row_count, 0)
      ),
      'selected_row_sample', '[]'::jsonb,
      'input_selected_preview_row_count', COALESCE(v_input_count, 0),
      'selection_resolved_to_current', COALESCE(v_selection_resolved_to_current, false),
      'resolved_current_selected_preview_row_ids', COALESCE(v_resolved_current_selection_ids, '[]'::jsonb),
      'same_week_paye_override', jsonb_build_object(
        'guardrails', '{}'::jsonb,
        'create_blocked', false,
        'override_required', false,
        'scope_blocked', false,
        'block_reason_code', NULL,
        'block_message', NULL,
        'override_reason_present', (NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS NOT NULL),
        'override_continue', COALESCE(p_override_continue, false),
        'override_verified', COALESCE(p_override_verified, false),
        'override_verified_by_user_id', CASE WHEN p_override_verified_by_user_id IS NULL THEN NULL ELSE p_override_verified_by_user_id::text END,
        'override_verified_at_utc', CASE WHEN p_override_verified_at_utc IS NULL THEN NULL ELSE p_override_verified_at_utc::text END
      ),
      'next_phase', 'BLOCKED',
      'block_reason_code', v_no_rows_block_reason_code,
      'message', v_no_rows_block_message,
      'requires_row_backed_scope_seed', false
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_prepare_draft_selected_sample;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_prepare_draft_selected_sample ON COMMIT DROP AS
  WITH selected_rows AS (
    SELECT
      preview_row.id,
      preview_row.row_key,
      preview_row.candidate_id,
      preview_row.timesheet_id,
      preview_row.row_ordinal,
      UPPER(BTRIM(COALESCE(preview_row.row_json->>'pay_channel', preview_row.row_json->>'current_pay_method', preview_row.row_json->>'candidate_pay_method', ''))) AS pay_channel,
      preview_row.status,
      preview_row.selection_state,
      preview_row.selected,
      preview_row.key_type,
      preview_row.key_value,
      private.pay_workbench_preview_effective_section_v1(
        preview_row.section,
        preview_row.row_json
      ) AS section,
      preview_row.row_json,
      jsonb_strip_nulls(jsonb_build_object(
        'timesheet_id', CASE WHEN preview_row.timesheet_id IS NULL THEN NULL ELSE preview_row.timesheet_id::text END,
        'key_type', NULLIF(BTRIM(COALESCE(preview_row.key_type, preview_row.row_json#>>'{economic_key,key_type}', preview_row.row_json->>'component_key_type', '')), ''),
        'key_value', NULLIF(BTRIM(COALESCE(preview_row.key_value, preview_row.row_json#>>'{economic_key,key_value}', preview_row.row_json->>'component_key_value', '')), '')
      )) AS economic_key_json
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND preview_row.session_version = v_session_row.version
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
      AND COALESCE(preview_row.selected, false) = true
      AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
      AND (v_scope_filter = 'ALL' OR UPPER(BTRIM(COALESCE(preview_row.row_json->>'pay_channel', preview_row.row_json->>'current_pay_method', preview_row.row_json->>'candidate_pay_method', ''))) = v_scope_filter)
      AND (
        p_selected_preview_row_ids IS NULL
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_pay_workbench_prepare_draft_supplied_ids AS supplied_id
          WHERE supplied_id.supplied_id IN (preview_row.id::text, preview_row.row_key, preview_row.row_json->>'preview_row_id', preview_row.row_json->>'row_id', preview_row.row_json->>'line_id')
        )
      )
    ORDER BY preview_row.row_ordinal, preview_row.id
    LIMIT 101
  )
  SELECT
    selected_rows.*,
    public.pay_workbench_preview_line_contract_ok(
      p_line_json => jsonb_strip_nulls(
        selected_rows.row_json
        || jsonb_build_object(
          'row_key', selected_rows.row_key,
          'preview_row_pk', selected_rows.id::text,
          'selection_state', selected_rows.selection_state
        )
      ),
      p_economic_key_json => selected_rows.economic_key_json,
      p_target_section => COALESCE(NULLIF(BTRIM(selected_rows.section), ''), 'canonical_preview_lines')
    ) AS preview_contract_json
  FROM selected_rows;


  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'preview_row_id', synthetic_total_rows.id::text,
           'row_key', synthetic_total_rows.row_key,
           'candidate_id', synthetic_total_rows.candidate_id::text,
           'timesheet_id', CASE WHEN synthetic_total_rows.timesheet_id IS NULL THEN NULL ELSE synthetic_total_rows.timesheet_id::text END,
           'key_type', synthetic_total_rows.key_type,
           'key_value', synthetic_total_rows.key_value,
           'amount_ex_vat', synthetic_total_rows.row_json->>'amount_ex_vat',
           'reason', 'RESOLVED_SYNTHETIC_TOTAL_ROW_SELECTED'
         ) ORDER BY synthetic_total_rows.row_ordinal, synthetic_total_rows.id), '[]'::jsonb)
  INTO v_synthetic_total_selected_sample
  FROM pg_temp.tmp_pay_workbench_prepare_draft_selected_sample AS synthetic_total_rows
  WHERE UPPER(BTRIM(COALESCE(synthetic_total_rows.key_type, synthetic_total_rows.row_json#>>'{economic_key,key_type}', ''))) = 'TS_TOTAL'
    AND UPPER(BTRIM(COALESCE(synthetic_total_rows.key_value, synthetic_total_rows.row_json#>>'{economic_key,key_value}', ''))) = 'TOTAL'
    AND LOWER(BTRIM(COALESCE(synthetic_total_rows.row_key, synthetic_total_rows.row_json->>'row_key', synthetic_total_rows.row_json->>'line_key', synthetic_total_rows.row_json->>'source_ref', ''))) LIKE '%:non_segment:total%'
    AND (
      lower(btrim(coalesce(synthetic_total_rows.row_json->>'resolved_segment_rows_replace_source_total', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json->>'has_resolved_rate', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json#>>'{case_resolution_summary,has_resolved_rate}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_applied}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR lower(btrim(coalesce(synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_active}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
      OR (
        COALESCE(synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_component_count}', '') ~ '^[0-9]+$'
        AND (synthetic_total_rows.row_json#>>'{case_resolution_summary,resolved_rate_component_count}')::integer > 0
      )
      OR EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_workbench_prepare_draft_selected_sample AS sibling_segment
        WHERE sibling_segment.candidate_id = synthetic_total_rows.candidate_id
          AND sibling_segment.timesheet_id IS NOT DISTINCT FROM synthetic_total_rows.timesheet_id
          AND UPPER(BTRIM(COALESCE(sibling_segment.key_type, sibling_segment.row_json#>>'{economic_key,key_type}', ''))) = 'TS_DAY'
          AND LOWER(BTRIM(COALESCE(sibling_segment.row_key, sibling_segment.row_json->>'row_key', sibling_segment.row_json->>'line_key', sibling_segment.row_json->>'source_ref', ''))) LIKE '%:segment:%'
      )
    );

  v_synthetic_total_selected_exists := jsonb_array_length(COALESCE(v_synthetic_total_selected_sample, '[]'::jsonb)) > 0;

  IF COALESCE(v_synthetic_total_selected_exists, false) THEN
    RAISE EXCEPTION 'RESOLVED_SYNTHETIC_TOTAL_ROW_NOT_DRAFTABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'RESOLVED_SYNTHETIC_TOTAL_ROW_NOT_DRAFTABLE',
              'session_id', p_session_id::text,
              'session_version', v_session_row.version,
              'operation_id', p_operation_id::text,
              'synthetic_total_selected_preview_rows', COALESCE(v_synthetic_total_selected_sample, '[]'::jsonb),
              'message', 'A selected resolved timesheet row is stale and cannot be drafted. Refresh Banking Pay and try Create Draft again.'
            )::text;
  END IF;

  SELECT EXISTS (
           SELECT 1
           FROM pg_temp.tmp_pay_workbench_prepare_draft_selected_sample AS malformed_sample
           WHERE LOWER(BTRIM(COALESCE(malformed_sample.preview_contract_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              OR LOWER(BTRIM(COALESCE(malformed_sample.preview_contract_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              OR UPPER(BTRIM(COALESCE(malformed_sample.selection_state, ''))) <> 'SELECTED'
              OR UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'presentation_section', ''))) <> 'READY_TO_PAY'
              OR (
                LOWER(BTRIM(COALESCE(malformed_sample.row_json->>'post_draft_overlay_applied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                AND (
                  UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'selection_state', malformed_sample.selection_state, ''))) <> 'SELECTED'
                  OR UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'post_draft_overlay_operation_type', ''))) IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
                )
              )
              OR (
                UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'projection_path', ''))) = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
                AND (
                  LOWER(BTRIM(COALESCE(malformed_sample.row_json->>'projection_certified', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
                  OR UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'policy_x_authority_scope', ''))) <> 'PRE_DRAFT_LIVE_TRUTH'
                  OR malformed_sample.economic_key_json IS NULL
                  OR malformed_sample.economic_key_json = '{}'::jsonb
                  OR NULLIF(BTRIM(COALESCE(malformed_sample.economic_key_json->>'key_type', '')), '') IS NULL
                  OR NULLIF(BTRIM(COALESCE(malformed_sample.economic_key_json->>'key_value', '')), '') IS NULL
                  OR NULLIF(BTRIM(COALESCE(malformed_sample.economic_key_json->>'timesheet_id', '')), '') IS NULL
                )
              )
         )
  INTO v_malformed_selected_exists;

  IF COALESCE(v_malformed_selected_exists, false) THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'preview_row_id', malformed_rows.id::text,
             'row_key', malformed_rows.row_key,
             'candidate_id', malformed_rows.candidate_id::text,
             'reasons', COALESCE(malformed_rows.preview_contract_json->'reasons', '[]'::jsonb)
           ) ORDER BY malformed_rows.row_ordinal, malformed_rows.id), '[]'::jsonb)
    INTO v_malformed_selected_sample
    FROM (
      SELECT malformed_sample.*
      FROM pg_temp.tmp_pay_workbench_prepare_draft_selected_sample AS malformed_sample
      WHERE LOWER(BTRIM(COALESCE(malformed_sample.preview_contract_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         OR LOWER(BTRIM(COALESCE(malformed_sample.preview_contract_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         OR UPPER(BTRIM(COALESCE(malformed_sample.selection_state, ''))) <> 'SELECTED'
         OR UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'presentation_section', ''))) <> 'READY_TO_PAY'
         OR (
           LOWER(BTRIM(COALESCE(malformed_sample.row_json->>'post_draft_overlay_applied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           AND (
             UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'selection_state', malformed_sample.selection_state, ''))) <> 'SELECTED'
             OR UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'post_draft_overlay_operation_type', ''))) IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
           )
         )
         OR (
           UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'projection_path', ''))) = 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
           AND (
             LOWER(BTRIM(COALESCE(malformed_sample.row_json->>'projection_certified', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
             OR UPPER(BTRIM(COALESCE(malformed_sample.row_json->>'policy_x_authority_scope', ''))) <> 'PRE_DRAFT_LIVE_TRUTH'
             OR malformed_sample.economic_key_json IS NULL
             OR malformed_sample.economic_key_json = '{}'::jsonb
             OR NULLIF(BTRIM(COALESCE(malformed_sample.economic_key_json->>'key_type', '')), '') IS NULL
             OR NULLIF(BTRIM(COALESCE(malformed_sample.economic_key_json->>'key_value', '')), '') IS NULL
             OR NULLIF(BTRIM(COALESCE(malformed_sample.economic_key_json->>'timesheet_id', '')), '') IS NULL
           )
         )
      ORDER BY malformed_sample.row_ordinal, malformed_sample.id
      LIMIT 25
    ) AS malformed_rows;

    RAISE EXCEPTION 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'MALFORMED_PREVIEW_ROW_NOT_DRAFTABLE',
              'session_id', p_session_id::text,
              'session_version', v_session_row.version,
              'operation_id', p_operation_id::text,
              'malformed_selected_preview_rows', COALESCE(v_malformed_selected_sample, '[]'::jsonb),
              'message', 'Selected preview rows are not valid draftable Ready to Pay rows. Refresh the preview and try again.'
            )::text;
  END IF;

  SELECT COUNT(*)::integer,
         COUNT(DISTINCT selected_sample.candidate_id)::integer,
         COUNT(*) FILTER (WHERE selected_sample.pay_channel = 'PAYE')::integer,
         COUNT(*) FILTER (WHERE selected_sample.pay_channel = 'UMBRELLA')::integer,
         EXISTS (
           SELECT 1
           FROM pg_temp.tmp_pay_workbench_prepare_draft_selected_sample AS ready_sample
           WHERE ready_sample.pay_channel IN ('PAYE', 'UMBRELLA')
             AND COALESCE(ready_sample.selected, false) = true
             AND UPPER(BTRIM(COALESCE(ready_sample.selection_state, ''))) = 'SELECTED'
             AND UPPER(BTRIM(COALESCE(ready_sample.status, ''))) = 'READY'
             AND LOWER(BTRIM(COALESCE(ready_sample.preview_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             AND LOWER(BTRIM(COALESCE(ready_sample.preview_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             AND UPPER(BTRIM(COALESCE(ready_sample.row_json->>'presentation_section', ''))) = 'READY_TO_PAY'
         ),
         EXISTS (
           SELECT 1
           FROM pg_temp.tmp_pay_workbench_prepare_draft_selected_sample AS blocked_sample
           WHERE UPPER(BTRIM(COALESCE(blocked_sample.status, ''))) IN ('DIRTY', 'ERROR', 'FAILED')
              OR UPPER(BTRIM(COALESCE(blocked_sample.selection_state, ''))) <> 'SELECTED'
              OR (
                LOWER(BTRIM(COALESCE(blocked_sample.row_json->>'post_draft_overlay_applied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                AND (
                  UPPER(BTRIM(COALESCE(blocked_sample.row_json->>'selection_state', blocked_sample.selection_state, ''))) <> 'SELECTED'
                  OR UPPER(BTRIM(COALESCE(blocked_sample.row_json->>'post_draft_overlay_operation_type', ''))) IN ('DRAFT_CREATE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLE')
                )
              )
              OR LOWER(BTRIM(COALESCE(blocked_sample.preview_contract_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              OR LOWER(BTRIM(COALESCE(blocked_sample.preview_contract_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              OR UPPER(BTRIM(COALESCE(blocked_sample.row_json->>'presentation_section', ''))) <> 'READY_TO_PAY'
         )
  INTO v_sample_row_count, v_sample_candidate_count, v_sample_paye_count, v_sample_umbrella_count, v_ready_selected_exists, v_unready_selected_exists
  FROM pg_temp.tmp_pay_workbench_prepare_draft_selected_sample AS selected_sample;

  v_unready_selected_exists := COALESCE(v_unready_selected_exists, false) OR COALESCE(v_current_unready_selected_exists, false);

  IF COALESCE(v_sample_row_count, 0) = 0 THEN
    RAISE EXCEPTION 'No selected preview rows are available for session % and scope %', p_session_id, v_scope_filter;
  END IF;

  IF v_ready_selected_exists IS NOT TRUE THEN
    RAISE EXCEPTION 'No selected preview rows are READY and draftable for session % and scope %', p_session_id, v_scope_filter;
  END IF;

  IF v_unready_selected_exists THEN
    RAISE EXCEPTION 'Selected preview rows include dirty, failed, excluded, or non-selectable rows for session %', p_session_id;
  END IF;

  IF v_scope_filter IN ('ALL', 'PAYE') AND COALESCE(v_selected_ready_paye_row_count, 0) > 0 THEN
    PERFORM pg_advisory_xact_lock(94201, 1);

    v_paye_guardrails := public.pay_paye_guardrails(
      p_pay_date => v_session_row.pay_date,
      p_ignore_pay_batch_id => NULL::uuid,
      p_actor_user_id => p_actor_user_id
    );

    v_paye_create_blocked := COALESCE((v_paye_guardrails->>'create_paye_blocked')::boolean, false);
    v_paye_override_required := COALESCE((v_paye_guardrails->>'override_required')::boolean, false);

    IF v_paye_create_blocked THEN
      v_paye_scope_blocked := true;
      v_paye_block_reason_code := 'PAYE_DRAFT_ALREADY_EXISTS';
      v_paye_block_message := COALESCE(v_paye_guardrails #>> '{ui,existing_draft_block,message}', 'A PAYE draft batch already exists. Cancel or delete the existing PAYE draft before creating another PAYE draft.');
    ELSIF v_paye_override_required THEN
      IF NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS NULL THEN
        v_paye_scope_blocked := true;
        v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_REASON_REQUIRED';
        v_paye_block_message := 'A same-week PAYE override reason is required before creating another PAYE batch in the same Monday-based payroll week.';
      ELSIF COALESCE(p_override_continue, false) = false THEN
        v_paye_scope_blocked := true;
        v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_CONTINUE_REQUIRED';
        v_paye_block_message := 'Explicit continuation is required before creating another PAYE batch in the same Monday-based payroll week.';
      ELSIF COALESCE(p_override_verified, false) = false OR p_override_verified_by_user_id IS NULL OR p_override_verified_by_user_id <> p_actor_user_id OR p_override_verified_at_utc IS NULL THEN
        v_paye_scope_blocked := true;
        v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFICATION_REQUIRED';
        v_paye_block_message := 'Valid password reauthentication and 2FA verification are required before creating another PAYE batch in the same Monday-based payroll week.';
      END IF;
    END IF;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'preview_row_id', sample_rows.id::text,
           'row_key', sample_rows.row_key,
           'candidate_id', sample_rows.candidate_id::text,
           'pay_channel', sample_rows.pay_channel,
           'row_ordinal', sample_rows.row_ordinal
         ) ORDER BY sample_rows.row_ordinal, sample_rows.id), '[]'::jsonb)
  INTO v_selected_sample
  FROM (
    SELECT selected_sample.*
    FROM pg_temp.tmp_pay_workbench_prepare_draft_selected_sample AS selected_sample
    ORDER BY selected_sample.row_ordinal, selected_sample.id
    LIMIT 25
  ) AS sample_rows;

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'draft_prepare_validated_at_utc', v_now::text,
          'draft_prepare_scope', v_scope_filter,
          'draft_prepare_sample_row_count', COALESCE(v_sample_row_count, 0),
          'draft_prepare_sample_candidate_count', COALESCE(v_sample_candidate_count, 0),
          'draft_prepare_selected_ready_row_count', COALESCE(v_selected_ready_row_count, 0),
          'draft_prepare_selected_ready_paye_row_count', COALESCE(v_selected_ready_paye_row_count, 0),
          'draft_prepare_selected_ready_umbrella_row_count', COALESCE(v_selected_ready_umbrella_row_count, 0),
          'draft_prepare_scope_selected_ready_row_count', COALESCE(v_scope_selected_ready_row_count, 0),
          'draft_prepare_input_selection_count', COALESCE(v_input_count, 0),
          'draft_prepare_selection_resolved_to_current', COALESCE(v_selection_resolved_to_current, false)
        )
      ),
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_mode', true,
    'operation_id', p_operation_id::text,
    'session_id', p_session_id::text,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'session_version', v_session_row.version,
    'pay_date', CASE WHEN v_session_row.pay_date IS NULL THEN NULL ELSE v_session_row.pay_date::text END,
    'week_ending_cutoff', CASE WHEN v_session_row.week_ending_cutoff IS NULL THEN NULL ELSE v_session_row.week_ending_cutoff::text END,
    'pay_channel_scope', v_scope_filter,
    'selected_preview_row_count_known', true,
    'selected_preview_row_sample_count', COALESCE(v_sample_row_count, 0),
    'selected_candidate_sample_count', COALESCE(v_sample_candidate_count, 0),
    'paye_selected_row_sample_count', COALESCE(v_sample_paye_count, 0),
    'umbrella_selected_row_sample_count', COALESCE(v_sample_umbrella_count, 0),
    'selected_ready_row_count', COALESCE(v_selected_ready_row_count, 0),
    'selected_ready_paye_row_count', COALESCE(v_selected_ready_paye_row_count, 0),
    'selected_ready_umbrella_row_count', COALESCE(v_selected_ready_umbrella_row_count, 0),
    'scope_selected_ready_row_count', COALESCE(v_scope_selected_ready_row_count, 0),
    'scope_counts', jsonb_build_object(
      'selected_ready_total', COALESCE(v_selected_ready_row_count, 0),
      'selected_ready_paye', COALESCE(v_selected_ready_paye_row_count, 0),
      'selected_ready_umbrella', COALESCE(v_selected_ready_umbrella_row_count, 0),
      'selected_ready_for_scope', COALESCE(v_scope_selected_ready_row_count, 0)
    ),
    'selected_row_sample', COALESCE(v_selected_sample, '[]'::jsonb),
    'input_selected_preview_row_count', COALESCE(v_input_count, 0),
    'selection_resolved_to_current', COALESCE(v_selection_resolved_to_current, false),
    'resolved_current_selected_preview_row_ids', COALESCE(v_resolved_current_selection_ids, '[]'::jsonb),
    'same_week_paye_override', jsonb_build_object(
      'guardrails', COALESCE(v_paye_guardrails, '{}'::jsonb),
      'create_blocked', v_paye_create_blocked,
      'override_required', v_paye_override_required,
      'scope_blocked', v_paye_scope_blocked,
      'block_reason_code', v_paye_block_reason_code,
      'block_message', v_paye_block_message,
      'override_reason_present', (NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS NOT NULL),
      'override_continue', COALESCE(p_override_continue, false),
      'override_verified', COALESCE(p_override_verified, false),
      'override_verified_by_user_id', CASE WHEN p_override_verified_by_user_id IS NULL THEN NULL ELSE p_override_verified_by_user_id::text END,
      'override_verified_at_utc', CASE WHEN p_override_verified_at_utc IS NULL THEN NULL ELSE p_override_verified_at_utc::text END
    ),
    'next_phase', CASE WHEN v_paye_scope_blocked THEN 'AWAIT_SAME_WEEK_PAYE_OVERRIDE' ELSE 'SEED_CANDIDATE_SCOPE' END,
    'requires_row_backed_scope_seed', (v_paye_scope_blocked IS NOT TRUE),
    'message', CASE WHEN v_paye_scope_blocked THEN v_paye_block_message ELSE 'Workbench draft validation passed. Continue with operation-scoped draft creation.' END
  );
END;
$function$;

-- pay_workbench_preview_line_contract_ok(jsonb,jsonb,text)
CREATE OR REPLACE FUNCTION public.pay_workbench_preview_line_contract_ok(p_line_json jsonb DEFAULT '{}'::jsonb, p_economic_key_json jsonb DEFAULT NULL::jsonb, p_target_section text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_line_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_line_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_line_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_economic_key_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_economic_key_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_economic_key_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_target_section_input text := NULLIF(BTRIM(COALESCE(p_target_section, '')), '');
  v_target_section text := CASE
    WHEN v_target_section_input IS NULL THEN public.pay_workbench_preview_section_from_line_json(v_line_json)
    ELSE public.pay_workbench_preview_section_from_line_json(v_line_json || jsonb_build_object('target_section', v_target_section_input))
  END;
  v_presentation_section text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'presentation_section', v_line_json->>'readiness_state', '')), ''));
  v_source_kind text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'source_kind', v_line_json->>'source_type', '')), ''));
  v_line_key text := NULLIF(BTRIM(COALESCE(v_line_json->>'line_key', v_line_json->>'row_key', v_line_json->>'preview_row_id', v_line_json->>'line_id', '')), '');
  v_line_type text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'line_type', v_line_json->>'case_type', '')), ''));
  v_case_type text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'case_type', '')), ''));
  v_item_direction text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'item_direction', v_line_json->>'direction', '')), ''));
  v_finance_case_id_text text := NULLIF(BTRIM(COALESCE(v_line_json->>'finance_case_id', '')), '');
  v_finance_case_id_present boolean := false;
  v_is_recognised_finance_deduction boolean := false;
  v_key_type text := UPPER(NULLIF(BTRIM(COALESCE(v_economic_key_json->>'key_type', v_line_json#>>'{economic_key,key_type}', v_line_json->>'component_key_type', v_line_json->>'key_type', '')), ''));
  v_key_value text := NULLIF(BTRIM(COALESCE(v_economic_key_json->>'key_value', v_line_json#>>'{economic_key,key_value}', v_line_json->>'component_key_value', v_line_json->>'key_value', '')), '');
  v_amount_text text := NULLIF(BTRIM(COALESCE(v_line_json->>'amount_ex_vat', v_line_json->>'preview_amount_ex_vat', v_line_json->>'section_amount_ex_vat', '')), '');
  v_amount numeric := NULL::numeric;
  v_draftable boolean := false;
  v_is_ready_for_draft boolean := false;
  v_is_excluded boolean := false;
  v_materialisable boolean := false;
  v_selection_allowed boolean := false;
  v_ok boolean := false;
  v_reasons jsonb := '[]'::jsonb;
  v_reason_count integer := 0;
BEGIN
  IF jsonb_typeof(COALESCE(p_line_json, '{}'::jsonb)) <> 'object' THEN
    v_reasons := v_reasons || jsonb_build_array('LINE_JSON_NOT_OBJECT');
  END IF;

  IF v_source_kind IN (
    'TIMESHEET_SNAPSHOT',
    'TIMESHEET_SNAPSHOT_EVIDENCE',
    'RAW_TIMESHEET_SNAPSHOT',
    'INTERNAL_ONLY',
    'NO_DELTA',
    'EXCLUDED'
  ) THEN
    v_reasons := v_reasons || jsonb_build_array('INTERNAL_OR_RAW_SOURCE_KIND');
  END IF;

  IF v_amount_text IS NOT NULL AND v_amount_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_amount := ROUND(v_amount_text::numeric, 2);
  END IF;

  v_finance_case_id_present := COALESCE(v_finance_case_id_text, '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  v_is_recognised_finance_deduction := (
    COALESCE(v_finance_case_id_present, false)
    AND (v_item_direction IS NULL OR v_item_direction = 'DEDUCTION')
    AND (
      v_line_type = 'OVERPAYMENT_RECOVERY'
      OR v_line_type IN ('MANUAL_DEBT_RECOVERY', 'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT')
    )
  );

  v_draftable := LOWER(BTRIM(COALESCE(v_line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_is_ready_for_draft := LOWER(BTRIM(COALESCE(v_line_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_is_excluded := LOWER(BTRIM(COALESCE(v_line_json->>'is_excluded_from_allocation', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_target_section = 'canonical_preview_lines' THEN
    v_materialisable := true;

    IF COALESCE(v_draftable, false) IS NOT TRUE THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_NOT_DRAFTABLE');
    END IF;

    IF COALESCE(v_is_ready_for_draft, false) IS NOT TRUE THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_NOT_READY_FOR_DRAFT');
    END IF;

    IF COALESCE(v_is_excluded, false) THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_EXCLUDED_FROM_ALLOCATION');
    END IF;

    IF v_presentation_section IS DISTINCT FROM 'READY_TO_PAY' THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_PRESENTATION_SECTION_INVALID');
    END IF;

    IF v_amount IS NULL THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_AMOUNT_MISSING');
    ELSIF ROUND(COALESCE(v_amount, 0), 2) = 0 THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_AMOUNT_ZERO');
    ELSIF ROUND(COALESCE(v_amount, 0), 2) < 0
       AND COALESCE(v_is_recognised_finance_deduction, false) IS NOT TRUE THEN
      v_reasons := v_reasons || jsonb_build_array('NEGATIVE_ENTITLEMENT_MUST_ROUTE_TO_FINANCE_CASE');
    END IF;

    IF v_key_type IS NULL OR v_key_value IS NULL THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_ECONOMIC_KEY_MISSING');
    ELSIF v_key_type = 'TS_DAY' AND v_key_value !~ '^\d{4}-\d{2}-\d{2}$' THEN
      v_reasons := v_reasons || jsonb_build_array('READY_ROW_TS_DAY_KEY_NOT_DATE');
    END IF;

    IF v_line_key LIKE 'timesheet_snapshot:%' THEN
      v_reasons := v_reasons || jsonb_build_array('RAW_TIMESHEET_SNAPSHOT_ROW_KEY_REJECTED');
    END IF;

  ELSIF v_target_section IN ('cases_resolutions', 'blocked_for_pay') THEN
    v_materialisable := true;
    v_selection_allowed := false;

    IF v_presentation_section IS NULL THEN
      v_reasons := v_reasons || jsonb_build_array('DISPLAY_ROW_PRESENTATION_SECTION_MISSING');
    END IF;

    IF COALESCE(v_draftable, false) THEN
      v_reasons := v_reasons || jsonb_build_array('DISPLAY_ROW_MUST_NOT_BE_DRAFTABLE');
    END IF;
  ELSE
    v_materialisable := false;
  END IF;

  SELECT jsonb_array_length(v_reasons)
  INTO v_reason_count;

  v_ok := COALESCE(v_materialisable, false) AND COALESCE(v_reason_count, 0) = 0;

  IF v_target_section = 'canonical_preview_lines' AND COALESCE(v_ok, false) THEN
    v_selection_allowed := true;
  END IF;

  RETURN jsonb_build_object(
    'ok', COALESCE(v_ok, false),
    'materialisable', COALESCE(v_materialisable, false),
    'target_section', v_target_section,
    'presentation_section', v_presentation_section,
    'source_kind', v_source_kind,
    'line_type', v_line_type,
    'case_type', v_case_type,
    'item_direction', v_item_direction,
    'finance_case_id', v_finance_case_id_text,
    'is_recognised_finance_deduction', COALESCE(v_is_recognised_finance_deduction, false),
    'line_key', v_line_key,
    'draftable', COALESCE(v_draftable, false),
    'is_ready_for_draft', COALESCE(v_is_ready_for_draft, false)
  )
  || jsonb_build_object(
    'is_excluded_from_allocation', COALESCE(v_is_excluded, false),
    'selection_allowed', COALESCE(v_selection_allowed, false),
    'amount_ex_vat', v_amount,
    'key_type', v_key_type,
    'key_value', v_key_value,
    'reason_count', COALESCE(v_reason_count, 0),
    'reasons', COALESCE(v_reasons, '[]'::jsonb),
    'status', CASE WHEN COALESCE(v_ok, false) THEN 'OK' ELSE 'NOT_OK' END
  );
END;
$function$;

-- pay_workbench_preview_line_economic_key(jsonb,uuid,text,jsonb,text,text)
CREATE OR REPLACE FUNCTION public.pay_workbench_preview_line_economic_key(p_line_json jsonb DEFAULT '{}'::jsonb, p_timesheet_id uuid DEFAULT NULL::uuid, p_item_type text DEFAULT NULL::text, p_segment_json jsonb DEFAULT NULL::jsonb, p_key_type_hint text DEFAULT NULL::text, p_key_value_hint text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_line_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_line_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_line_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_segment_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_segment_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_segment_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_timesheet_id uuid := p_timesheet_id;
  v_timesheet_id_text text := NULL::text;
  v_line_type text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'line_type', v_line_json->>'case_type', '')), ''));
  v_item_type text := UPPER(NULLIF(BTRIM(COALESCE(p_item_type, v_line_json->>'item_type', v_line_json->>'allocation_type', v_line_type, '')), ''));
  v_key_type_hint text := UPPER(NULLIF(BTRIM(COALESCE(
    p_key_type_hint,
    v_segment_json->>'component_key_type',
    v_segment_json->>'key_type',
    v_line_json#>>'{economic_key,key_type}',
    v_line_json->>'component_key_type',
    v_line_json->>'key_type',
    v_line_json->>'frozen_component_key_type',
    v_line_json#>>'{source_basis_json,component_key_type}',
    v_line_json#>>'{source_basis_json,key_type}',
    v_line_json#>>'{frozen_source_basis_json,component_key_type}',
    v_line_json#>>'{frozen_source_basis_json,key_type}',
    ''
  )), ''));
  v_key_value_hint text := NULLIF(BTRIM(COALESCE(
    p_key_value_hint,
    v_segment_json->>'component_key_value',
    v_segment_json->>'key_value',
    v_line_json#>>'{economic_key,key_value}',
    v_line_json->>'component_key_value',
    v_line_json->>'key_value',
    v_line_json->>'frozen_component_key_value',
    v_line_json#>>'{source_basis_json,component_key_value}',
    v_line_json#>>'{source_basis_json,key_value}',
    v_line_json#>>'{frozen_source_basis_json,component_key_value}',
    v_line_json#>>'{frozen_source_basis_json,key_value}',
    ''
  )), '');
  v_work_date_text text := NULLIF(BTRIM(COALESCE(
    v_segment_json->>'work_date',
    v_segment_json->>'date',
    v_line_json->>'work_date',
    v_line_json->>'date',
    v_line_json#>>'{source_basis_json,work_date}',
    v_line_json#>>'{source_basis_json,date}',
    v_line_json#>>'{frozen_source_basis_json,work_date}',
    v_line_json#>>'{frozen_source_basis_json,date}',
    ''
  )), '');
  v_work_date date := NULL::date;
  v_manual_key_value text := NULL::text;
  v_source_json jsonb := '{}'::jsonb;
  v_resolved_timesheet_id uuid := NULL::uuid;
  v_resolved_key_type text := NULL::text;
  v_resolved_key_value text := NULL::text;
  v_resolved_source text := NULL::text;
  v_failure_reason text := NULL::text;
  v_case_component_count integer := 0;
  v_single_case_component_json jsonb := '{}'::jsonb;
  v_single_component_key_type text := NULL::text;
  v_single_component_key_value text := NULL::text;
  v_single_component_classification text := NULL::text;
  v_line_amount_ex_vat numeric := NULL::numeric;
  v_single_component_amount_ex_vat numeric := NULL::numeric;
  v_has_segment_identity boolean := false;
BEGIN
  v_has_segment_identity := NULLIF(BTRIM(COALESCE(
    v_segment_json->>'segment_id',
    v_segment_json->>'segment_key',
    v_segment_json->>'segment_stable_key',
    v_segment_json->>'ref_num',
    v_segment_json->>'work_date',
    v_segment_json->>'date',
    v_line_json->>'segment_id',
    v_line_json->>'segment_key',
    v_line_json->>'segment_stable_key',
    v_line_json->>'ref_num',
    v_line_json#>>'{source_basis_json,segment_id}',
    v_line_json#>>'{source_basis_json,segment_key}',
    v_line_json#>>'{source_basis_json,segment_stable_key}',
    ''
  )), '') IS NOT NULL;

  IF COALESCE(v_line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_line_amount_ex_vat := ROUND((v_line_json->>'amount_ex_vat')::numeric, 2);
  ELSIF COALESCE(v_line_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_line_amount_ex_vat := ROUND((v_line_json->>'preview_amount_ex_vat')::numeric, 2);
  ELSIF COALESCE(v_line_json->>'section_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_line_amount_ex_vat := ROUND((v_line_json->>'section_amount_ex_vat')::numeric, 2);
  END IF;

  IF jsonb_typeof(COALESCE(v_line_json->'case_components', '[]'::jsonb)) = 'array' THEN
    SELECT
      COUNT(*)::integer,
      COALESCE((ARRAY_AGG(case_component.value ORDER BY case_component.ordinality))[1], '{}'::jsonb)
    INTO v_case_component_count, v_single_case_component_json
    FROM jsonb_array_elements(COALESCE(v_line_json->'case_components', '[]'::jsonb)) WITH ORDINALITY AS case_component(value, ordinality)
    WHERE case_component.value IS NOT NULL
      AND jsonb_typeof(case_component.value) = 'object';
  END IF;

  IF COALESCE(v_case_component_count, 0) = 1 THEN
    v_single_component_key_type := UPPER(NULLIF(BTRIM(COALESCE(v_single_case_component_json->>'component_key_type', '')), ''));
    v_single_component_key_value := NULLIF(BTRIM(COALESCE(v_single_case_component_json->>'component_key_value', '')), '');
    v_single_component_classification := UPPER(NULLIF(BTRIM(COALESCE(v_single_case_component_json->>'classification', '')), ''));

    IF COALESCE(v_single_case_component_json->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'preview_due_amount_ex_vat')::numeric, 2);
    ELSIF COALESCE(v_single_case_component_json->>'allocated_source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'allocated_source_due_amount_ex_vat')::numeric, 2);
    ELSIF COALESCE(v_single_case_component_json->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'target_pay_ex_vat')::numeric, 2);
    ELSIF COALESCE(v_single_case_component_json->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'component_amount_ex_vat')::numeric, 2);
    ELSIF COALESCE(v_single_case_component_json->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'source_pay_ex_vat')::numeric, 2);
    ELSIF COALESCE(v_single_case_component_json->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      v_single_component_amount_ex_vat := ROUND((v_single_case_component_json->>'remaining_source_amount')::numeric, 2);
    END IF;

    IF v_single_component_key_type IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
       AND (v_single_component_classification IS NULL OR v_single_component_classification = 'REIMBURSEMENT_GROSS_FIXED')
       AND v_single_component_key_value IS NOT NULL
       AND (
         v_key_type_hint IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
         OR (
           COALESCE(v_has_segment_identity, false) IS FALSE
           AND v_line_amount_ex_vat IS NOT NULL
           AND v_single_component_amount_ex_vat IS NOT NULL
           AND ROUND(ABS(v_line_amount_ex_vat), 2) = ROUND(ABS(v_single_component_amount_ex_vat), 2)
         )
         OR (
           COALESCE(v_has_segment_identity, false) IS FALSE
           AND v_key_type_hint IS NULL
           AND COALESCE(v_item_type, '') NOT IN ('SEGMENT_DELTA')
         )
       ) THEN
      v_key_type_hint := v_single_component_key_type;
      v_key_value_hint := v_single_component_key_value;
      v_item_type := CASE
        WHEN v_single_component_key_type = 'EXPENSE_CODE'
         AND UPPER(COALESCE(v_single_component_key_value, '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        ELSE 'EXPENSE_DELTA'
      END;
    END IF;
  END IF;

  v_timesheet_id_text := CASE
    WHEN v_timesheet_id IS NOT NULL THEN NULL::text
    ELSE NULLIF(BTRIM(COALESCE(
      v_line_json#>>'{economic_key,timesheet_id}',
      v_line_json->>'real_business_timesheet_id',
      v_line_json->>'timesheet_id',
      v_line_json#>>'{source_basis_json,timesheet_id}',
      v_line_json#>>'{frozen_source_basis_json,timesheet_id}',
      ''
    )), '')
  END;

  IF v_timesheet_id IS NULL
     AND v_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_timesheet_id := v_timesheet_id_text::uuid;
  END IF;

  IF v_item_type IN ('TIMESHEET_PAYMENT', 'TIMESHEET', 'HOURS', 'SEGMENT') THEN
    v_item_type := 'SEGMENT_DELTA';
  ELSIF v_item_type IN ('MANUAL_ADJUSTMENT_CARRY_FORWARD', 'MANUAL_CREDIT_PAYOUT') THEN
    v_item_type := 'MANUAL_CARRY_FORWARD';
  ELSIF v_item_type IN ('LOAN_PAYOUT', 'PAYMENT_ADVANCE_REPAYMENT', 'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY', 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT') THEN
    v_item_type := COALESCE(
      CASE
        WHEN v_key_type_hint IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN v_key_type_hint = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        WHEN v_key_type_hint = 'EXPENSE_CODE' AND UPPER(COALESCE(v_key_value_hint, '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        WHEN v_key_type_hint IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
        ELSE NULL::text
      END,
      'ADJUSTMENT_DELTA'
    );
  ELSIF v_item_type IS NULL THEN
    v_item_type := CASE
      WHEN v_key_type_hint IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
      WHEN v_key_type_hint = 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
      WHEN v_key_type_hint = 'EXPENSE_CODE' AND UPPER(COALESCE(v_key_value_hint, '')) = 'MILEAGE' THEN 'MILEAGE_DELTA'
      WHEN v_key_type_hint IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
      ELSE NULL::text
    END;
  END IF;

  IF v_item_type = 'MANUAL_CARRY_FORWARD' THEN
    v_manual_key_value := NULLIF(BTRIM(COALESCE(
      v_line_json->>'manual_adjustment_carry_forward_id',
      REPLACE(v_line_json->>'source_ref', 'carry_forward:', ''),
      REPLACE(v_line_json->>'preview_row_id', 'carry_forward:', ''),
      v_line_json->>'operation_source_key',
      ''
    )), '');

    IF v_manual_key_value IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', true,
        'timesheet_id', CASE WHEN v_timesheet_id IS NULL THEN NULL ELSE v_timesheet_id::text END,
        'key_type', 'MANUAL_CARRY_FORWARD',
        'key_value', v_manual_key_value,
        'key_resolution_source', 'PRE_DRAFT_MANUAL_CARRY_FORWARD_KEY',
        'key_resolution_failure_reason', NULL::text,
        'item_type', 'MANUAL_CARRY_FORWARD',
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
    END IF;
  END IF;

  IF v_work_date_text IS NOT NULL AND v_work_date_text ~ '^\d{4}-\d{2}-\d{2}$' THEN
    v_work_date := v_work_date_text::date;
  END IF;

  v_source_json := jsonb_strip_nulls(
    COALESCE(v_line_json, '{}'::jsonb)
    || jsonb_build_object(
      'timesheet_id', CASE WHEN v_timesheet_id IS NULL THEN NULL ELSE v_timesheet_id::text END,
      'item_type', v_item_type,
      'work_date', CASE WHEN v_work_date IS NULL THEN NULL ELSE v_work_date::text END,
      'date', CASE WHEN v_work_date IS NULL THEN NULL ELSE v_work_date::text END
    )
    || jsonb_build_object(
      'segment_id', NULLIF(BTRIM(COALESCE(v_segment_json->>'segment_id', v_line_json->>'segment_id', '')), ''),
      'segment_key', NULLIF(BTRIM(COALESCE(v_segment_json->>'segment_key', v_line_json->>'segment_key', '')), ''),
      'segment_stable_key', NULLIF(BTRIM(COALESCE(v_segment_json->>'segment_stable_key', v_line_json->>'segment_stable_key', '')), ''),
      'ref_num', NULLIF(BTRIM(COALESCE(v_segment_json->>'ref_num', v_line_json->>'ref_num', '')), ''),
      'component_key_type', v_key_type_hint,
      'component_key_value', v_key_value_hint,
      'segment_json', v_segment_json
    )
  );

  SELECT
    resolved_key.timesheet_id,
    resolved_key.key_type,
    resolved_key.key_value,
    resolved_key.key_resolution_source,
    resolved_key.key_resolution_failure_reason
  INTO
    v_resolved_timesheet_id,
    v_resolved_key_type,
    v_resolved_key_value,
    v_resolved_source,
    v_failure_reason
  FROM public._pay_policy_x_resolve_pre_draft_economic_key(
    p_timesheet_id => v_timesheet_id,
    p_live_source_json => v_source_json,
    p_item_type => v_item_type,
    p_key_type_hint => v_key_type_hint,
    p_key_value_hint => v_key_value_hint,
    p_work_date => v_work_date
  ) AS resolved_key;

  RETURN jsonb_build_object(
    'ok', (v_resolved_key_type IS NOT NULL AND v_resolved_key_value IS NOT NULL),
    'timesheet_id', CASE WHEN v_resolved_timesheet_id IS NULL THEN NULL ELSE v_resolved_timesheet_id::text END,
    'key_type', v_resolved_key_type,
    'key_value', v_resolved_key_value,
    'key_resolution_source', v_resolved_source,
    'key_resolution_failure_reason', v_failure_reason,
    'item_type', v_item_type,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- pay_workbench_preview_rows_materialise_chunk(uuid,uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_preview_rows_materialise_chunk(p_session_id uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100);
  v_cursor_scope_ordinal bigint := -1;
  v_cursor_line_ordinal bigint := -1;
  v_cursor_line_work_id uuid := NULL::uuid;
  v_cursor_has_scope boolean := false;
  v_raw_count integer := 0;
  v_materialised_count integer := 0;
  v_new_preview_row_count integer := 0;
  v_new_selected_row_count integer := 0;
  v_suppressed_preview_row_count integer := 0;
  v_materialise_error_count integer := 0;
  v_next_cursor jsonb := NULL::jsonb;
  v_last_returned_scope_ordinal bigint := NULL::bigint;
  v_last_returned_line_ordinal bigint := NULL::bigint;
  v_last_returned_line_work_id uuid := NULL::uuid;
  v_section_delta_json jsonb := '{}'::jsonb;
  v_affected_candidate_sample jsonb := '[]'::jsonb;
  v_scope_pending_delta integer := 0;
  v_scope_ready_delta integer := 0;
  v_scope_failed_delta integer := 0;
  v_scope_error_candidate_count integer := 0;
  v_selection_intent_mode text := '';
  v_explicit_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_reconciled_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_reconciled_selected_row_count integer := 0;
  v_candidate_state_candidate_id uuid := NULL::uuid;
  v_candidate_state_source_change_seq bigint := 0;
  v_candidate_state_source_build_run_id uuid := NULL::uuid;
  v_candidate_state_result jsonb := '{}'::jsonb;
  v_candidate_state_update_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) = 'object' THEN
    BEGIN
      IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_scope_ordinal', p_cursor_json->>'cursor_scope_ordinal', '')), '') IS NOT NULL THEN
        v_cursor_scope_ordinal := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_scope_ordinal', p_cursor_json->>'cursor_scope_ordinal', '')), '')::bigint;
        v_cursor_has_scope := true;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_cursor_scope_ordinal := -1;
      v_cursor_has_scope := false;
    END;

    BEGIN
      v_cursor_line_ordinal := COALESCE(
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_ordinal', '')), '')::bigint,
        NULLIF(BTRIM(COALESCE(p_cursor_json->>'cursor_ordinal', '')), '')::bigint,
        -1
      );
    EXCEPTION WHEN OTHERS THEN
      v_cursor_line_ordinal := -1;
    END;

    IF NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_work_id', p_cursor_json->>'last_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_line_work_id := NULLIF(BTRIM(COALESCE(p_cursor_json->>'last_line_work_id', p_cursor_json->>'last_id', '')), '')::uuid;
    END IF;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  v_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    ''
  )));
  IF v_selection_intent_mode NOT IN ('IMPLICIT_ALL', 'EXPLICIT_INCLUDE') THEN
    v_selection_intent_mode := CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false) THEN 'EXPLICIT_INCLUDE'
      ELSE ''
    END;
  END IF;
  v_explicit_selected_preview_row_ids := CASE
    WHEN jsonb_typeof(COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb)) = 'array'
      THEN COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  IF p_candidate_id IS NOT NULL THEN
    SELECT COALESCE(scope_check.scope_ordinal, 0)::bigint
    INTO v_cursor_scope_ordinal
    FROM public.banking_pay_workbench_session_scope AS scope_check
    WHERE scope_check.session_id = p_session_id
      AND scope_check.candidate_id = p_candidate_id
    LIMIT 1;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_CANDIDATE_NOT_IN_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_PREVIEW_ROWS_MATERIALISE_CANDIDATE_NOT_IN_SCOPE',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text
              )::text;
    END IF;
  ELSIF v_cursor_has_scope IS NOT TRUE THEN
    v_cursor_scope_ordinal := -1;
    v_cursor_line_ordinal := -1;
    v_cursor_line_work_id := NULL::uuid;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_preview_materialise;
  CREATE TEMP TABLE _tmp_pay_wb_preview_materialise ON COMMIT DROP AS
  WITH ready_rows AS (
    SELECT
      line_work.id,
      line_work.session_id,
      line_work.candidate_id,
      line_work.timesheet_id,
      line_work.line_key,
      line_work.line_ordinal,
      line_work.result_row_json,
      COALESCE(scope_row.scope_ordinal, 0)::bigint AS scope_ordinal,
      ROW_NUMBER() OVER (
        ORDER BY COALESCE(scope_row.scope_ordinal, 0), line_work.line_ordinal, line_work.id
      ) AS page_ordinal
    FROM public.banking_pay_workbench_candidate_line_work AS line_work
    JOIN public.banking_pay_workbench_session_scope AS scope_row
      ON scope_row.session_id = line_work.session_id
     AND scope_row.candidate_id = line_work.candidate_id
    WHERE line_work.session_id = p_session_id
      AND (p_candidate_id IS NULL OR line_work.candidate_id = p_candidate_id)
      AND UPPER(BTRIM(COALESCE(line_work.status, ''))) = 'READY'
      AND line_work.result_row_json IS NOT NULL
      AND jsonb_typeof(line_work.result_row_json) = 'object'
      AND LOWER(BTRIM(COALESCE(line_work.result_row_json#>>'{preview_contract,ok}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(line_work.result_row_json#>>'{preview_contract,materialisable}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND public.pay_workbench_preview_section_from_line_json(line_work.result_row_json) IN (
        'canonical_preview_lines',
        'cases_resolutions',
        'blocked_for_pay'
      )
      AND (
        (
          NULLIF(BTRIM(COALESCE(line_work.result_row_json->>'source_build_run_id', '')), '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND COALESCE(line_work.result_row_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
          AND EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_candidate_source_lines AS accepted_source
            WHERE accepted_source.session_id = line_work.session_id
              AND accepted_source.candidate_id = line_work.candidate_id
              AND accepted_source.status = 'CURRENT'
              AND accepted_source.source_build_run_id =
                    (line_work.result_row_json->>'source_build_run_id')::uuid
              AND accepted_source.source_change_seq =
                    (line_work.result_row_json->>'source_change_seq')::bigint
              AND accepted_source.line_key = line_work.line_key
              AND accepted_source.timesheet_id IS NOT DISTINCT FROM line_work.timesheet_id
          )
        )
        OR (
          /*
           * Projection-only rows are a legacy/current delta fallback.  They
           * must never make a source-built row from an older accepted run
           * materialisable after the same line key has moved to a newer
           * source-build run.
           */
          NULLIF(BTRIM(COALESCE(line_work.result_row_json->>'source_build_run_id', '')), '') IS NULL
          AND
          NULLIF(BTRIM(COALESCE(line_work.result_row_json->>'projection_run_id', '')), '')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_candidate_delta_projection_runs AS accepted_projection
            WHERE accepted_projection.id =
                    (line_work.result_row_json->>'projection_run_id')::uuid
              AND accepted_projection.session_id = line_work.session_id
              AND accepted_projection.candidate_id = line_work.candidate_id
              AND UPPER(BTRIM(COALESCE(accepted_projection.status, ''))) = 'COMPLETED'
              AND UPPER(BTRIM(COALESCE(accepted_projection.write_phase, ''))) = 'WRITE_COMPLETE'
              AND COALESCE(accepted_projection.fallback_required, false) IS NOT TRUE
          )
        )
      )
      AND (
        COALESCE(scope_row.scope_ordinal, 0)::bigint > COALESCE(v_cursor_scope_ordinal, -1)
        OR (
          COALESCE(scope_row.scope_ordinal, 0)::bigint = COALESCE(v_cursor_scope_ordinal, -1)
          AND line_work.line_ordinal > COALESCE(v_cursor_line_ordinal, -1)
        )
        OR (
          COALESCE(scope_row.scope_ordinal, 0)::bigint = COALESCE(v_cursor_scope_ordinal, -1)
          AND line_work.line_ordinal = COALESCE(v_cursor_line_ordinal, -1)
          AND v_cursor_line_work_id IS NOT NULL
          AND line_work.id > v_cursor_line_work_id
        )
      )
    ORDER BY COALESCE(scope_row.scope_ordinal, 0), line_work.line_ordinal, line_work.id
    LIMIT (v_limit + 1)
  ), ready_source_rows AS (
    SELECT
      ready_rows.*,
      ready_rows.timesheet_id AS line_work_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(ready_rows.result_row_json#>>'{economic_key,timesheet_id}', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(ready_rows.result_row_json#>>'{economic_key,timesheet_id}', '')), '')::uuid
        ELSE NULL::uuid
      END AS economic_key_timesheet_id,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(ready_rows.result_row_json->>'timesheet_id', ready_rows.result_row_json->>'real_business_timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(ready_rows.result_row_json->>'timesheet_id', ready_rows.result_row_json->>'real_business_timesheet_id', '')), '')::uuid
        ELSE NULL::uuid
      END AS result_row_timesheet_id
    FROM ready_rows
  ), ready_timesheet_refs AS (
    SELECT ready_source_rows.id, 'LINE_WORK'::text AS source_label, ready_source_rows.line_work_timesheet_id AS source_timesheet_id
    FROM ready_source_rows
    WHERE ready_source_rows.line_work_timesheet_id IS NOT NULL
    UNION ALL
    SELECT ready_source_rows.id, 'ECONOMIC_KEY'::text AS source_label, ready_source_rows.economic_key_timesheet_id AS source_timesheet_id
    FROM ready_source_rows
    WHERE ready_source_rows.economic_key_timesheet_id IS NOT NULL
    UNION ALL
    SELECT ready_source_rows.id, 'RESULT_ROW'::text AS source_label, ready_source_rows.result_row_timesheet_id AS source_timesheet_id
    FROM ready_source_rows
    WHERE ready_source_rows.result_row_timesheet_id IS NOT NULL
  ), ready_timesheet_id_array AS (
    SELECT COALESCE(
      array_agg(DISTINCT ready_timesheet_refs.source_timesheet_id ORDER BY ready_timesheet_refs.source_timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM ready_timesheet_refs
  ), rotation_scope_rows AS (
    SELECT
      rotation_scope.requested_timesheet_id,
      rotation_scope.canonical_timesheet_id,
      rotation_scope.family_timesheet_id,
      rotation_scope.family_is_current,
      rotation_scope.family_version,
      rotation_scope.requested_is_canonical
    FROM ready_timesheet_id_array
    JOIN public._pay_timesheet_rotation_scope(ready_timesheet_id_array.timesheet_ids) AS rotation_scope
      ON true
  ), rotation_scope_by_requested AS (
    SELECT DISTINCT ON (rotation_scope_rows.requested_timesheet_id)
      rotation_scope_rows.requested_timesheet_id,
      COALESCE(rotation_scope_rows.canonical_timesheet_id, rotation_scope_rows.requested_timesheet_id) AS canonical_timesheet_id,
      (rotation_scope_rows.family_timesheet_id IS NOT NULL AND rotation_scope_rows.family_is_current IS NOT NULL) AS rotation_scope_resolved
    FROM rotation_scope_rows
    WHERE rotation_scope_rows.requested_timesheet_id IS NOT NULL
    ORDER BY
      rotation_scope_rows.requested_timesheet_id,
      rotation_scope_rows.family_is_current DESC NULLS LAST,
      rotation_scope_rows.family_version DESC NULLS LAST,
      rotation_scope_rows.family_timesheet_id
  ), canonical_ready_rows AS (
    SELECT
      ready_source_rows.id,
      ready_source_rows.session_id,
      ready_source_rows.candidate_id,
      COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) AS timesheet_id,
      ready_source_rows.line_work_timesheet_id,
      ready_source_rows.economic_key_timesheet_id,
      ready_source_rows.result_row_timesheet_id,
      ready_source_rows.line_key,
      ready_source_rows.line_ordinal,
      CASE
        WHEN COALESCE(ready_source_rows.scope_ordinal, 0) > 0 THEN (ready_source_rows.scope_ordinal * 1000000) + ready_source_rows.line_ordinal
        ELSE ready_source_rows.line_ordinal
      END AS stable_row_ordinal,
      jsonb_strip_nulls(
        CASE
          WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) IS NULL THEN ready_source_rows.result_row_json
          ELSE ready_source_rows.result_row_json
            || jsonb_build_object(
              'timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text,
              'real_business_timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text,
              'economic_key', COALESCE(ready_source_rows.result_row_json->'economic_key', '{}'::jsonb)
                || jsonb_build_object('timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text)
            )
            || CASE
              WHEN ready_source_rows.line_work_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)
                OR ready_source_rows.economic_key_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)
                OR ready_source_rows.result_row_timesheet_id IS DISTINCT FROM COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)
              THEN jsonb_build_object(
                'rotation_requested_timesheet_ids', jsonb_strip_nulls(jsonb_build_object(
                  'line_work_timesheet_id', CASE WHEN ready_source_rows.line_work_timesheet_id IS NULL THEN NULL ELSE ready_source_rows.line_work_timesheet_id::text END,
                  'economic_key_timesheet_id', CASE WHEN ready_source_rows.economic_key_timesheet_id IS NULL THEN NULL ELSE ready_source_rows.economic_key_timesheet_id::text END,
                  'result_row_timesheet_id', CASE WHEN ready_source_rows.result_row_timesheet_id IS NULL THEN NULL ELSE ready_source_rows.result_row_timesheet_id::text END
                ))
              )
              ELSE '{}'::jsonb
            END
        END
      ) AS result_row_json,
      ready_source_rows.scope_ordinal,
      ready_source_rows.page_ordinal,
      public.pay_workbench_preview_section_from_line_json(
        CASE
          WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) IS NULL THEN ready_source_rows.result_row_json
          ELSE ready_source_rows.result_row_json
            || jsonb_build_object(
              'timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text,
              'economic_key', COALESCE(ready_source_rows.result_row_json->'economic_key', '{}'::jsonb)
                || jsonb_build_object('timesheet_id', COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id)::text)
            )
        END
      ) AS target_section,
      CASE
        WHEN ready_source_rows.line_work_timesheet_id IS NULL
         AND ready_source_rows.economic_key_timesheet_id IS NULL
         AND ready_source_rows.result_row_timesheet_id IS NULL THEN false
        WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) IS NULL THEN true
        WHEN ready_source_rows.line_work_timesheet_id IS NOT NULL AND COALESCE(line_work_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN ready_source_rows.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN ready_source_rows.result_row_timesheet_id IS NOT NULL AND COALESCE(result_row_rotation.rotation_scope_resolved, false) = false THEN true
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM economic_key_rotation.canonical_timesheet_id THEN true
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND result_row_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM result_row_rotation.canonical_timesheet_id THEN true
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND result_row_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM result_row_rotation.canonical_timesheet_id THEN true
        ELSE false
      END AS rotation_validation_failed,
      CASE
        WHEN ready_source_rows.line_work_timesheet_id IS NULL
         AND ready_source_rows.economic_key_timesheet_id IS NULL
         AND ready_source_rows.result_row_timesheet_id IS NULL THEN NULL::text
        WHEN COALESCE(line_work_rotation.canonical_timesheet_id, economic_key_rotation.canonical_timesheet_id, result_row_rotation.canonical_timesheet_id) IS NULL THEN 'ROTATION_CANONICAL_TIMESHEET_NOT_RESOLVED'
        WHEN ready_source_rows.line_work_timesheet_id IS NOT NULL AND COALESCE(line_work_rotation.rotation_scope_resolved, false) = false THEN 'LINE_WORK_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN ready_source_rows.economic_key_timesheet_id IS NOT NULL AND COALESCE(economic_key_rotation.rotation_scope_resolved, false) = false THEN 'ECONOMIC_KEY_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN ready_source_rows.result_row_timesheet_id IS NOT NULL AND COALESCE(result_row_rotation.rotation_scope_resolved, false) = false THEN 'RESULT_ROW_TIMESHEET_ROTATION_SCOPE_UNRESOLVED'
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM economic_key_rotation.canonical_timesheet_id THEN 'LINE_WORK_AND_ECONOMIC_KEY_CANONICAL_TIMESHEET_MISMATCH'
        WHEN line_work_rotation.canonical_timesheet_id IS NOT NULL
         AND result_row_rotation.canonical_timesheet_id IS NOT NULL
         AND line_work_rotation.canonical_timesheet_id IS DISTINCT FROM result_row_rotation.canonical_timesheet_id THEN 'LINE_WORK_AND_RESULT_ROW_CANONICAL_TIMESHEET_MISMATCH'
        WHEN economic_key_rotation.canonical_timesheet_id IS NOT NULL
         AND result_row_rotation.canonical_timesheet_id IS NOT NULL
         AND economic_key_rotation.canonical_timesheet_id IS DISTINCT FROM result_row_rotation.canonical_timesheet_id THEN 'ECONOMIC_KEY_AND_RESULT_ROW_CANONICAL_TIMESHEET_MISMATCH'
        ELSE NULL::text
      END AS rotation_failure_reason
    FROM ready_source_rows
    LEFT JOIN rotation_scope_by_requested AS line_work_rotation
      ON line_work_rotation.requested_timesheet_id = ready_source_rows.line_work_timesheet_id
    LEFT JOIN rotation_scope_by_requested AS economic_key_rotation
      ON economic_key_rotation.requested_timesheet_id = ready_source_rows.economic_key_timesheet_id
    LEFT JOIN rotation_scope_by_requested AS result_row_rotation
      ON result_row_rotation.requested_timesheet_id = ready_source_rows.result_row_timesheet_id
  ), component_probe_rows AS (
    SELECT
      canonical_ready_rows.*,
      component_probe.selected_amount_ex_vat AS fixed_reimbursement_original_amount_ex_vat,
      component_probe.selected_amount_ex_vat AS economic_original_amount_ex_vat,
      component_probe.economic_key_type,
      component_probe.economic_key_value,
      component_probe.single_fixed_reimbursement_key_type,
      component_probe.single_fixed_reimbursement_key_value,
      (
        NULLIF(BTRIM(COALESCE(canonical_ready_rows.result_row_json->>'source_family_key', '')), '') LIKE 'correction-chain:%'
        AND jsonb_typeof(canonical_ready_rows.result_row_json->'correction_chain_residual') = 'object'
        AND jsonb_typeof(canonical_ready_rows.result_row_json->'correction_chain_component') = 'object'
      ) AS is_correction_chain_residual
    FROM canonical_ready_rows
    CROSS JOIN LATERAL (
      SELECT
        CASE WHEN NULLIF(BTRIM(COALESCE(canonical_ready_rows.result_row_json->>'amount_ex_vat', canonical_ready_rows.result_row_json->>'preview_amount_ex_vat', '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(NULLIF(BTRIM(COALESCE(canonical_ready_rows.result_row_json->>'amount_ex_vat', canonical_ready_rows.result_row_json->>'preview_amount_ex_vat', '')), '')::numeric, 2)
          ELSE NULL::numeric
        END AS selected_amount_ex_vat,
        UPPER(NULLIF(BTRIM(COALESCE(canonical_ready_rows.result_row_json#>>'{economic_key,key_type}', canonical_ready_rows.result_row_json->>'key_type', '')), '')) AS economic_key_type,
        NULLIF(BTRIM(COALESCE(canonical_ready_rows.result_row_json#>>'{economic_key,key_value}', canonical_ready_rows.result_row_json->>'key_value', '')), '') AS economic_key_value,
        CASE
          WHEN component_counts.object_component_count = 1
           AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_type
          ELSE NULL::text
        END AS single_fixed_reimbursement_key_type,
        CASE
          WHEN component_counts.object_component_count = 1
           AND component_counts.fixed_reimbursement_component_count = 1 THEN component_counts.fixed_reimbursement_key_value
          ELSE NULL::text
        END AS single_fixed_reimbursement_key_value
      FROM (
        SELECT
          (COUNT(*) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
          ))::integer AS object_component_count,
          (COUNT(*) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ))::integer AS fixed_reimbursement_component_count,
          MAX(UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), ''))) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ) AS fixed_reimbursement_key_type,
          MAX(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '')) FILTER (
            WHERE component_element.value IS NOT NULL
              AND jsonb_typeof(component_element.value) = 'object'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'classification', '')), '')) = 'REIMBURSEMENT_GROSS_FIXED'
              AND UPPER(NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '')) IN ('EXPENSE_CODE', 'ADDITIONAL_CODE')
              AND NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') IS NOT NULL
          ) AS fixed_reimbursement_key_value
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(canonical_ready_rows.result_row_json->'case_components') = 'array' THEN canonical_ready_rows.result_row_json->'case_components'
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS component_counts
    ) AS component_probe
  ), outstanding_timesheet_ids AS (
    SELECT COALESCE(
      array_agg(DISTINCT component_probe_rows.timesheet_id ORDER BY component_probe_rows.timesheet_id),
      array[]::uuid[]
    ) AS timesheet_ids
    FROM component_probe_rows
    WHERE component_probe_rows.page_ordinal <= v_limit
      AND component_probe_rows.rotation_validation_failed IS NOT TRUE
      AND component_probe_rows.timesheet_id IS NOT NULL
      AND (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        OR (
          component_probe_rows.is_correction_chain_residual IS NOT TRUE
          AND component_probe_rows.target_section = 'canonical_preview_lines'
          AND component_probe_rows.economic_key_type IS NOT NULL
          AND component_probe_rows.economic_key_value IS NOT NULL
          AND component_probe_rows.economic_original_amount_ex_vat IS NOT NULL
          AND ROUND(COALESCE(component_probe_rows.economic_original_amount_ex_vat, 0), 2) > 0
        )
      )
  ), outstanding_component_rows AS (
    SELECT
      outstanding_components.timesheet_id,
      outstanding_components.key_type,
      outstanding_components.key_value,
      outstanding_components.truth_ex_vat,
      outstanding_components.baseline_ex_vat,
      outstanding_components.reserved_ex_vat,
      outstanding_components.outstanding_ex_vat
    FROM outstanding_timesheet_ids
    JOIN public._pay_outstanding_components(outstanding_timesheet_ids.timesheet_ids, NULL::uuid) AS outstanding_components
      ON true
  ), selected_rows_base AS (
    SELECT
      component_probe_rows.*,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        AND (
          UPPER(NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', component_probe_rows.result_row_json->>'key_type', '')), '')) IS DISTINCT FROM component_probe_rows.single_fixed_reimbursement_key_type
          OR NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', component_probe_rows.result_row_json->>'key_value', '')), '') IS DISTINCT FROM component_probe_rows.single_fixed_reimbursement_key_value
        )
      ) AS fixed_reimbursement_key_mismatch,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        AND component_probe_rows.fixed_reimbursement_original_amount_ex_vat IS NOT NULL
        AND ROUND(ABS(COALESCE(component_probe_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0
        AND (
          fixed_outstanding_component_rows.outstanding_ex_vat IS NULL
          OR ROUND(COALESCE(fixed_outstanding_component_rows.outstanding_ex_vat, 0), 2) <= 0
        )
      ) AS fixed_reimbursement_not_outstanding,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        AND component_probe_rows.fixed_reimbursement_original_amount_ex_vat IS NOT NULL
        AND ROUND(ABS(COALESCE(component_probe_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0
        AND fixed_outstanding_component_rows.outstanding_ex_vat IS NOT NULL
        AND ROUND(COALESCE(fixed_outstanding_component_rows.outstanding_ex_vat, 0), 2) = 0
        AND UPPER(NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', component_probe_rows.result_row_json->>'key_type', '')), '')) = component_probe_rows.single_fixed_reimbursement_key_type
        AND NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', component_probe_rows.result_row_json->>'key_value', '')), '') = component_probe_rows.single_fixed_reimbursement_key_value
      ) AS suppress_zero_outstanding_fixed_reimbursement,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        AND component_probe_rows.fixed_reimbursement_original_amount_ex_vat IS NOT NULL
        AND ROUND(ABS(COALESCE(component_probe_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0
        AND fixed_outstanding_component_rows.outstanding_ex_vat IS NOT NULL
        AND ROUND(COALESCE(fixed_outstanding_component_rows.outstanding_ex_vat, 0), 2) < 0
        AND UPPER(NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', component_probe_rows.result_row_json->>'key_type', '')), '')) = component_probe_rows.single_fixed_reimbursement_key_type
        AND NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', component_probe_rows.result_row_json->>'key_value', '')), '') = component_probe_rows.single_fixed_reimbursement_key_value
      ) AS suppress_negative_outstanding_fixed_reimbursement,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
        AND component_probe_rows.fixed_reimbursement_original_amount_ex_vat IS NOT NULL
        AND fixed_outstanding_component_rows.outstanding_ex_vat IS NOT NULL
        AND ROUND(COALESCE(fixed_outstanding_component_rows.outstanding_ex_vat, 0), 2) > 0
        AND ROUND(ABS(COALESCE(component_probe_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > ROUND(ABS(COALESCE(fixed_outstanding_component_rows.outstanding_ex_vat, 0)), 2)
        AND UPPER(NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', component_probe_rows.result_row_json->>'key_type', '')), '')) = component_probe_rows.single_fixed_reimbursement_key_type
        AND NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', component_probe_rows.result_row_json->>'key_value', '')), '') = component_probe_rows.single_fixed_reimbursement_key_value
      ) AS clamp_fixed_reimbursement_to_outstanding,
      ROUND(COALESCE(fixed_outstanding_component_rows.outstanding_ex_vat, 0), 2) AS fixed_reimbursement_outstanding_ex_vat,
      ROUND(COALESCE(effective_economic_outstanding.outstanding_ex_vat, 0), 2) AS economic_outstanding_ex_vat,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NULL
        AND component_probe_rows.is_correction_chain_residual IS NOT TRUE
        AND component_probe_rows.target_section = 'canonical_preview_lines'
        AND component_probe_rows.economic_key_type IS NOT NULL
        AND component_probe_rows.economic_key_value IS NOT NULL
        AND component_probe_rows.economic_original_amount_ex_vat IS NOT NULL
        AND ROUND(COALESCE(component_probe_rows.economic_original_amount_ex_vat, 0), 2) > 0
        AND effective_economic_outstanding.outstanding_ex_vat IS NOT NULL
        AND ROUND(COALESCE(effective_economic_outstanding.outstanding_ex_vat, 0), 2) = 0
      ) AS suppress_zero_outstanding_economic_key,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NULL
        AND component_probe_rows.is_correction_chain_residual IS NOT TRUE
        AND component_probe_rows.target_section = 'canonical_preview_lines'
        AND component_probe_rows.economic_key_type IS NOT NULL
        AND component_probe_rows.economic_key_value IS NOT NULL
        AND component_probe_rows.economic_original_amount_ex_vat IS NOT NULL
        AND ROUND(COALESCE(component_probe_rows.economic_original_amount_ex_vat, 0), 2) > 0
        AND effective_economic_outstanding.outstanding_ex_vat IS NOT NULL
        AND ROUND(COALESCE(effective_economic_outstanding.outstanding_ex_vat, 0), 2) < 0
      ) AS suppress_negative_outstanding_economic_key,
      (
        component_probe_rows.single_fixed_reimbursement_key_type IS NULL
        AND component_probe_rows.is_correction_chain_residual IS NOT TRUE
        AND component_probe_rows.target_section = 'canonical_preview_lines'
        AND component_probe_rows.economic_key_type IS NOT NULL
        AND component_probe_rows.economic_key_value IS NOT NULL
        AND component_probe_rows.economic_original_amount_ex_vat IS NOT NULL
        AND ROUND(COALESCE(component_probe_rows.economic_original_amount_ex_vat, 0), 2) > 0
        AND effective_economic_outstanding.outstanding_ex_vat IS NOT NULL
        AND ROUND(COALESCE(effective_economic_outstanding.outstanding_ex_vat, 0), 2) > 0
        AND ROUND(ABS(COALESCE(component_probe_rows.economic_original_amount_ex_vat, 0)), 2) > ROUND(ABS(COALESCE(effective_economic_outstanding.outstanding_ex_vat, 0)), 2)
      ) AS clamp_economic_key_to_outstanding,
      CASE
        WHEN component_probe_rows.rotation_validation_failed IS NOT TRUE
         AND component_probe_rows.target_section = 'canonical_preview_lines'
         AND LOWER(BTRIM(COALESCE(component_probe_rows.result_row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         AND LOWER(BTRIM(COALESCE(component_probe_rows.result_row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         AND LOWER(BTRIM(COALESCE(component_probe_rows.result_row_json->>'is_excluded_from_allocation', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
         AND LOWER(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{preview_contract,selection_allowed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         AND NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', '')), '') IS NOT NULL
         AND NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', '')), '') IS NOT NULL
         AND NOT (
           component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
           AND (
             UPPER(NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_type}', component_probe_rows.result_row_json->>'key_type', '')), '')) IS DISTINCT FROM component_probe_rows.single_fixed_reimbursement_key_type
             OR NULLIF(BTRIM(COALESCE(component_probe_rows.result_row_json#>>'{economic_key,key_value}', component_probe_rows.result_row_json->>'key_value', '')), '') IS DISTINCT FROM component_probe_rows.single_fixed_reimbursement_key_value
           )
         )
         AND NOT (
           component_probe_rows.single_fixed_reimbursement_key_type IS NOT NULL
           AND component_probe_rows.fixed_reimbursement_original_amount_ex_vat IS NOT NULL
           AND ROUND(ABS(COALESCE(component_probe_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0
           AND (
             fixed_outstanding_component_rows.outstanding_ex_vat IS NULL
             OR ROUND(COALESCE(fixed_outstanding_component_rows.outstanding_ex_vat, 0), 2) <= 0
           )
         )
         AND NOT (
           component_probe_rows.single_fixed_reimbursement_key_type IS NULL
           AND component_probe_rows.target_section = 'canonical_preview_lines'
           AND component_probe_rows.economic_key_type IS NOT NULL
           AND component_probe_rows.economic_key_value IS NOT NULL
           AND component_probe_rows.economic_original_amount_ex_vat IS NOT NULL
           AND ROUND(COALESCE(component_probe_rows.economic_original_amount_ex_vat, 0), 2) > 0
           AND effective_economic_outstanding.outstanding_ex_vat IS NOT NULL
           AND ROUND(COALESCE(effective_economic_outstanding.outstanding_ex_vat, 0), 2) <= 0
         )
        THEN true
        ELSE false
      END AS target_selected
    FROM component_probe_rows
    LEFT JOIN outstanding_component_rows AS fixed_outstanding_component_rows
      ON fixed_outstanding_component_rows.timesheet_id = component_probe_rows.timesheet_id
     AND fixed_outstanding_component_rows.key_type = component_probe_rows.single_fixed_reimbursement_key_type
     AND fixed_outstanding_component_rows.key_value = component_probe_rows.single_fixed_reimbursement_key_value
    LEFT JOIN outstanding_component_rows AS economic_outstanding_component_rows
      ON economic_outstanding_component_rows.timesheet_id = component_probe_rows.timesheet_id
     AND economic_outstanding_component_rows.key_type = component_probe_rows.economic_key_type
     AND economic_outstanding_component_rows.key_value = component_probe_rows.economic_key_value
    LEFT JOIN LATERAL (
      SELECT CASE
        WHEN component_probe_rows.target_section = 'canonical_preview_lines'
         AND LOWER(BTRIM(COALESCE(component_probe_rows.result_row_json->>'has_resolved_rate', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         AND LOWER(BTRIM(COALESCE(
               component_probe_rows.result_row_json->>'case_resolution_satisfied_now',
               component_probe_rows.result_row_json#>>'{case_resolution_summary,case_resolution_satisfied_now}',
               'false'
             ))) IN ('true', 't', '1', 'yes', 'y', 'on')
         AND UPPER(BTRIM(COALESCE(
               component_probe_rows.result_row_json->>'resolved_rate_family',
               component_probe_rows.result_row_json#>>'{case_resolution_summary,resolved_rate_family}',
               ''
             ))) = 'BUCKETED'
         AND component_probe_rows.economic_original_amount_ex_vat IS NOT NULL
         AND ROUND(COALESCE(component_probe_rows.economic_original_amount_ex_vat, 0), 2) > 0
        THEN ROUND(GREATEST(
          COALESCE(component_probe_rows.economic_original_amount_ex_vat, 0)
          - COALESCE(economic_outstanding_component_rows.baseline_ex_vat, 0)
          - COALESCE(economic_outstanding_component_rows.reserved_ex_vat, 0),
          0
        ), 2)
        ELSE economic_outstanding_component_rows.outstanding_ex_vat
      END AS outstanding_ex_vat
    ) AS effective_economic_outstanding ON true
  ), selected_rows AS (
    SELECT
      selected_rows_base.*,
      CASE
        WHEN selected_rows_base.clamp_economic_key_to_outstanding IS TRUE THEN
          jsonb_build_object(
            'amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'preview_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'amount_display', selected_rows_base.economic_outstanding_ex_vat,
            'section_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'section_amount_display', selected_rows_base.economic_outstanding_ex_vat,
            'component_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'target_pay_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'ready_preview_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'preview_component_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'source_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'source_entitlement_amount_ex_vat', ABS(selected_rows_base.economic_original_amount_ex_vat),
            'source_reservation_amount_ex_vat', ABS(selected_rows_base.economic_outstanding_ex_vat),
            'remaining_source_amount', selected_rows_base.economic_outstanding_ex_vat,
            'frozen_source_amount', ABS(selected_rows_base.economic_outstanding_ex_vat),
            'frozen_target_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'pay_economic_outstanding_clamped', true,
            'pay_outstanding_clamped', true,
            'pay_outstanding_original_amount_ex_vat', selected_rows_base.economic_original_amount_ex_vat,
            'pay_outstanding_clamped_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'pay_outstanding_available_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
            'pay_outstanding_basis', CASE
              WHEN LOWER(BTRIM(COALESCE(selected_rows_base.result_row_json->>'has_resolved_rate', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
               AND UPPER(BTRIM(COALESCE(selected_rows_base.result_row_json->>'resolved_rate_family', selected_rows_base.result_row_json#>>'{case_resolution_summary,resolved_rate_family}', ''))) = 'BUCKETED'
              THEN 'CURRENT_RESOLVED_RATE_LESS_PROTECTED_AMOUNTS'
              ELSE 'CURRENT_ENTITLEMENT_LESS_PROTECTED_AMOUNTS'
            END,
            'pay_outstanding_blocked', false,
            'outstanding_block_reason', NULL
          )
          || jsonb_build_object(
            'preview_contract', COALESCE(selected_rows_base.result_row_json->'preview_contract', '{}'::jsonb)
              || jsonb_build_object(
                'amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'selection_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'source_entitlement_amount_ex_vat', ABS(selected_rows_base.economic_original_amount_ex_vat),
                'source_reservation_amount_ex_vat', ABS(selected_rows_base.economic_outstanding_ex_vat),
                'pay_outstanding_clamped', true
              ),
            'source_basis_json', COALESCE(selected_rows_base.result_row_json->'source_basis_json', '{}'::jsonb)
              || jsonb_build_object(
                'pay_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'source_pay_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'source_entitlement_amount_ex_vat', ABS(selected_rows_base.economic_original_amount_ex_vat),
                'source_reservation_amount_ex_vat', ABS(selected_rows_base.economic_outstanding_ex_vat),
                'pay_outstanding_clamped', true,
                'original_source_pay_ex_vat', selected_rows_base.economic_original_amount_ex_vat
              ),
            'frozen_source_basis_json', COALESCE(selected_rows_base.result_row_json->'frozen_source_basis_json', selected_rows_base.result_row_json->'source_basis_json', '{}'::jsonb)
              || jsonb_build_object(
                'pay_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'source_pay_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'source_entitlement_amount_ex_vat', ABS(selected_rows_base.economic_original_amount_ex_vat),
                'source_reservation_amount_ex_vat', ABS(selected_rows_base.economic_outstanding_ex_vat),
                'pay_outstanding_clamped', true,
                'original_source_pay_ex_vat', selected_rows_base.economic_original_amount_ex_vat
              ),
            'frozen_component_snapshot_json', COALESCE(selected_rows_base.result_row_json->'frozen_component_snapshot_json', '{}'::jsonb)
              || jsonb_build_object(
                'source_pay_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'target_pay_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'component_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'preview_component_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'pay_outstanding_clamped', true,
                'original_source_pay_ex_vat', selected_rows_base.economic_original_amount_ex_vat
              )
              || jsonb_build_object(
                'source_basis_json', COALESCE(selected_rows_base.result_row_json#>'{frozen_component_snapshot_json,source_basis_json}', '{}'::jsonb)
                  || jsonb_build_object(
                    'pay_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                    'source_pay_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                    'source_entitlement_amount_ex_vat', ABS(selected_rows_base.economic_original_amount_ex_vat),
                    'source_reservation_amount_ex_vat', ABS(selected_rows_base.economic_outstanding_ex_vat),
                    'pay_outstanding_clamped', true,
                    'original_source_pay_ex_vat', selected_rows_base.economic_original_amount_ex_vat
                  )
              )
          )
          || CASE
            WHEN jsonb_typeof(selected_rows_base.result_row_json->'case_resolution_summary') = 'object' THEN jsonb_build_object(
              'case_resolution_summary',
              selected_rows_base.result_row_json->'case_resolution_summary'
              || jsonb_build_object(
                'safe_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat,
                'pay_outstanding_clamped', true,
                'pay_outstanding_original_amount_ex_vat', selected_rows_base.economic_original_amount_ex_vat,
                'pay_outstanding_clamped_amount_ex_vat', selected_rows_base.economic_outstanding_ex_vat
              )
            )
            ELSE '{}'::jsonb
          END
        ELSE '{}'::jsonb
      END AS economic_outstanding_payload_json
    FROM selected_rows_base
  )
  SELECT selection_resolved.*,
         CASE
           WHEN selection_resolved.effective_selected IS TRUE THEN 'SELECTED'
           WHEN selection_resolved.target_selected IS TRUE THEN 'UNSELECTED'
           ELSE 'NOT_SELECTABLE'
         END AS effective_selection_state,
         CASE
           WHEN selection_resolved.target_selected THEN 'SELECTED'
           ELSE 'NOT_SELECTABLE'
         END AS target_selection_state
  FROM (
    SELECT selected_rows.*,
           existing_preview.id AS existing_preview_row_id,
           COALESCE(existing_preview.selected, false) AS existing_preview_selected,
           UPPER(BTRIM(COALESCE(existing_preview.selection_state, ''))) AS existing_preview_selection_state,
           CASE
             WHEN selected_rows.target_selected IS NOT TRUE THEN false
             WHEN existing_preview.id IS NOT NULL
              AND UPPER(BTRIM(COALESCE(existing_preview.selection_state, ''))) IN ('SELECTED', 'UNSELECTED')
              THEN COALESCE(existing_preview.selected, false)
             WHEN COALESCE(v_selection_intent_mode, '') = 'EXPLICIT_INCLUDE' THEN EXISTS (
               SELECT 1
               FROM jsonb_array_elements_text(COALESCE(v_explicit_selected_preview_row_ids, '[]'::jsonb)) AS explicit_id(value)
               WHERE BTRIM(explicit_id.value) = existing_preview.id::text
             )
             ELSE true
           END AS effective_selected
    FROM selected_rows
    LEFT JOIN public.banking_pay_workbench_preview_rows AS existing_preview
      ON existing_preview.session_id = p_session_id
     AND existing_preview.section = selected_rows.target_section
     AND existing_preview.candidate_id = selected_rows.candidate_id
     AND existing_preview.row_key = selected_rows.line_key
  ) AS selection_resolved;

  SELECT COUNT(*)::integer
  INTO v_raw_count
  FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows;

  SELECT COUNT(*)::integer,
         COUNT(*) FILTER (WHERE materialise_rows.effective_selected)::integer
  INTO v_new_preview_row_count, v_new_selected_row_count
  FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
  WHERE materialise_rows.page_ordinal <= v_limit
    AND materialise_rows.existing_preview_row_id IS NULL
    AND materialise_rows.rotation_validation_failed IS NOT TRUE
    AND materialise_rows.suppress_zero_outstanding_fixed_reimbursement IS NOT TRUE
    AND materialise_rows.suppress_negative_outstanding_fixed_reimbursement IS NOT TRUE
    AND materialise_rows.suppress_zero_outstanding_economic_key IS NOT TRUE
    AND materialise_rows.suppress_negative_outstanding_economic_key IS NOT TRUE;

  SELECT COUNT(*)::integer
  INTO v_suppressed_preview_row_count
  FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
  WHERE materialise_rows.page_ordinal <= v_limit
    AND (materialise_rows.suppress_zero_outstanding_fixed_reimbursement IS TRUE
     OR materialise_rows.suppress_negative_outstanding_fixed_reimbursement IS TRUE
     OR materialise_rows.suppress_zero_outstanding_economic_key IS TRUE
     OR materialise_rows.suppress_negative_outstanding_economic_key IS TRUE);

  SELECT COUNT(*)::integer
  INTO v_materialise_error_count
  FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
  WHERE materialise_rows.page_ordinal <= v_limit
    AND materialise_rows.rotation_validation_failed IS TRUE;

  SELECT COALESCE(jsonb_object_agg(section_delta.target_section, section_delta.section_count ORDER BY section_delta.target_section), '{}'::jsonb)
  INTO v_section_delta_json
  FROM (
    SELECT materialise_rows.target_section, COUNT(*)::integer AS section_count
    FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
    WHERE materialise_rows.page_ordinal <= v_limit
      AND materialise_rows.existing_preview_row_id IS NULL
      AND materialise_rows.rotation_validation_failed IS NOT TRUE
      AND materialise_rows.suppress_zero_outstanding_fixed_reimbursement IS NOT TRUE
      AND materialise_rows.suppress_negative_outstanding_fixed_reimbursement IS NOT TRUE
      AND materialise_rows.suppress_zero_outstanding_economic_key IS NOT TRUE
      AND materialise_rows.suppress_negative_outstanding_economic_key IS NOT TRUE
    GROUP BY materialise_rows.target_section
  ) AS section_delta;

  WITH selected_rows AS (
    SELECT materialise_rows.*
    FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
    WHERE materialise_rows.page_ordinal <= v_limit
  ), visible_rows AS (
    SELECT selected_rows.*
    FROM selected_rows
    WHERE selected_rows.rotation_validation_failed IS NOT TRUE
      AND selected_rows.suppress_zero_outstanding_fixed_reimbursement IS NOT TRUE
      AND selected_rows.suppress_negative_outstanding_fixed_reimbursement IS NOT TRUE
      AND selected_rows.suppress_zero_outstanding_economic_key IS NOT TRUE
      AND selected_rows.suppress_negative_outstanding_economic_key IS NOT TRUE
  ), suppressed_existing_preview AS (
    UPDATE public.banking_pay_workbench_preview_rows AS preview_row
    SET status = 'SUPERSEDED',
        selected = false,
        selection_state = 'SUPERSEDED',
        row_json = COALESCE(preview_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'materialisation_suppressed', true,
            'materialisation_suppressed_reason', CASE
              WHEN selected_rows.suppress_negative_outstanding_fixed_reimbursement IS TRUE
                OR selected_rows.suppress_negative_outstanding_economic_key IS TRUE THEN 'NEGATIVE_OUTSTANDING_ROUTED_TO_OVERPAYMENT'
              WHEN selected_rows.suppress_zero_outstanding_economic_key IS TRUE THEN 'ZERO_OUTSTANDING_ECONOMIC_KEY'
              ELSE 'ZERO_OUTSTANDING_FIXED_REIMBURSEMENT'
            END,
            'materialisation_suppressed_at_utc', v_now::text,
            'materialised_no_visible_preview_row', true,
            'pay_outstanding_blocked', true,
            'pay_outstanding_available_ex_vat', CASE
              WHEN selected_rows.suppress_zero_outstanding_economic_key IS TRUE
                OR selected_rows.suppress_negative_outstanding_economic_key IS TRUE THEN selected_rows.economic_outstanding_ex_vat
              ELSE selected_rows.fixed_reimbursement_outstanding_ex_vat
            END,
            'outstanding_block_reason', CASE
              WHEN selected_rows.suppress_negative_outstanding_fixed_reimbursement IS TRUE
                OR selected_rows.suppress_negative_outstanding_economic_key IS TRUE THEN 'NEGATIVE_OUTSTANDING_ROUTED_TO_OVERPAYMENT'
              WHEN selected_rows.suppress_zero_outstanding_economic_key IS TRUE THEN 'ECONOMIC_KEY_OUTSTANDING_NOT_AVAILABLE'
              ELSE 'REIMBURSEMENT_OUTSTANDING_NOT_AVAILABLE'
            END
          ),
        updated_at_utc = v_now
    FROM selected_rows
    WHERE (
        preview_row.id = selected_rows.existing_preview_row_id
        OR (
          preview_row.session_id = p_session_id
          AND preview_row.candidate_id = selected_rows.candidate_id
          AND preview_row.section = selected_rows.target_section
          AND preview_row.timesheet_id IS NOT DISTINCT FROM selected_rows.timesheet_id
          AND preview_row.key_type IS NOT DISTINCT FROM selected_rows.single_fixed_reimbursement_key_type
          AND preview_row.key_value IS NOT DISTINCT FROM selected_rows.single_fixed_reimbursement_key_value
          AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) <> 'OVERPAYMENT_RECOVERY'
        )
        OR (
          preview_row.session_id = p_session_id
          AND preview_row.candidate_id = selected_rows.candidate_id
          AND preview_row.section = selected_rows.target_section
          AND preview_row.timesheet_id IS NOT DISTINCT FROM selected_rows.timesheet_id
          AND preview_row.key_type IS NOT DISTINCT FROM selected_rows.economic_key_type
          AND preview_row.key_value IS NOT DISTINCT FROM selected_rows.economic_key_value
          AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) <> 'OVERPAYMENT_RECOVERY'
        )
      )
      AND (selected_rows.suppress_zero_outstanding_fixed_reimbursement IS TRUE
        OR selected_rows.suppress_negative_outstanding_fixed_reimbursement IS TRUE
        OR selected_rows.suppress_zero_outstanding_economic_key IS TRUE
        OR selected_rows.suppress_negative_outstanding_economic_key IS TRUE)
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) <> 'SUPERSEDED'
    RETURNING preview_row.id
  ), upserted_preview AS (
    INSERT INTO public.banking_pay_workbench_preview_rows (
      session_id,
      candidate_id,
      section,
      row_key,
      row_ordinal,
      row_json,
      timesheet_id,
      key_type,
      key_value,
      selected,
      selection_state,
      status,
      session_version,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_session_id,
      selected_rows.candidate_id,
      selected_rows.target_section,
      selected_rows.line_key,
      selected_rows.stable_row_ordinal,
      selected_rows.result_row_json
        || CASE
          WHEN selected_rows.fixed_reimbursement_key_mismatch THEN jsonb_build_object(
            'draftable', false,
            'is_ready_for_draft', false,
            'selection_allowed', false,
            'pay_outstanding_blocked', true,
            'outstanding_block_reason', 'REIMBURSEMENT_KEY_MISMATCH'
          )
          WHEN selected_rows.fixed_reimbursement_not_outstanding THEN jsonb_build_object(
            'draftable', false,
            'is_ready_for_draft', false,
            'selection_allowed', false,
            'pay_outstanding_blocked', true,
            'outstanding_block_reason', 'REIMBURSEMENT_OUTSTANDING_NOT_AVAILABLE'
          )
          WHEN selected_rows.clamp_fixed_reimbursement_to_outstanding THEN (
            jsonb_build_object(
              'amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'amount_display', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'section_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'section_non_segment_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
            )
            || jsonb_build_object(
              'ready_preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'source_entitlement_amount_ex_vat', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'source_reservation_amount_ex_vat', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'source_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
            )
            || jsonb_build_object(
              'source_basis_json', COALESCE(selected_rows.result_row_json->'source_basis_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'pay_outstanding_clamped', true,
                  'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                ),
              'frozen_source_basis_json', COALESCE(selected_rows.result_row_json->'frozen_source_basis_json', selected_rows.result_row_json->'source_basis_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'pay_outstanding_clamped', true,
                  'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                ),
              'frozen_component_snapshot_json', COALESCE(selected_rows.result_row_json->'frozen_component_snapshot_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                )
                || jsonb_build_object(
                  'source_basis_json', COALESCE(selected_rows.result_row_json#>'{frozen_component_snapshot_json,source_basis_json}', '{}'::jsonb)
                    || jsonb_build_object(
                      'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                      'pay_outstanding_clamped', true,
                      'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                    )
                )
            )
            || jsonb_build_object(
              'remaining_source_amount', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'frozen_source_amount', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'frozen_target_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_clamped', true,
              'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
            )
            || jsonb_build_object(
              'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_available_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_blocked', false,
              'outstanding_block_reason', NULL,
              'case_components', (
                SELECT COALESCE(jsonb_agg(
                  CASE
                    WHEN component_element.value IS NOT NULL
                     AND jsonb_typeof(component_element.value) = 'object' THEN
                      component_element.value
                      || jsonb_build_object(
                        'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'ready_preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                      )
                      || jsonb_build_object(
                        'remaining_source_amount', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'pay_outstanding_clamped', true,
                        'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat,
                        'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'source_basis_json', COALESCE(component_element.value->'source_basis_json', '{}'::jsonb)
                          || jsonb_build_object(
                            'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                            'pay_outstanding_clamped', true,
                            'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                          )
                      )
                    ELSE component_element.value
                  END
                  ORDER BY component_element.ordinality
                ), '[]'::jsonb)
                FROM jsonb_array_elements(
                  CASE
                    WHEN jsonb_typeof(selected_rows.result_row_json->'case_components') = 'array' THEN selected_rows.result_row_json->'case_components'
                    ELSE '[]'::jsonb
                  END
                ) WITH ORDINALITY AS component_element(value, ordinality)
              )
            )
            || CASE
              WHEN jsonb_typeof(selected_rows.result_row_json->'case_resolution_summary') = 'object' THEN jsonb_build_object(
                'case_resolution_summary',
                selected_rows.result_row_json->'case_resolution_summary'
                || jsonb_build_object(
                  'safe_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'blocked_case_amount_ex_vat', 0,
                  'unresolved_taxable_amount_ex_vat', 0,
                  'pay_outstanding_clamped', true,
                  'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat,
                  'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                )
              )
              ELSE '{}'::jsonb
            END
            || CASE
              WHEN COALESCE(selected_rows.result_row_json->>'section_amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
               AND COALESCE(selected_rows.result_row_json->>'amount_ex_vat', selected_rows.result_row_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
               AND ROUND(ABS(COALESCE(selected_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0 THEN jsonb_build_object(
                'section_amount_display', ROUND(
                  selected_rows.fixed_reimbursement_outstanding_ex_vat
                  * ((selected_rows.result_row_json->>'section_amount_display')::numeric / selected_rows.fixed_reimbursement_original_amount_ex_vat),
                  2
                )
              )
              ELSE '{}'::jsonb
            END
          )
          ELSE '{}'::jsonb
        END
        || CASE
          WHEN selected_rows.clamp_economic_key_to_outstanding IS TRUE THEN COALESCE(selected_rows.economic_outstanding_payload_json, '{}'::jsonb)
          ELSE '{}'::jsonb
        END
        || jsonb_build_object(
          'materialised_at_utc', v_now::text,
          'materialised_from_line_work_id', selected_rows.id::text,
          'scope_ordinal', selected_rows.scope_ordinal,
          'stable_row_ordinal', selected_rows.stable_row_ordinal,
          'section', selected_rows.target_section,
          'selected', selected_rows.effective_selected,
          'selection_state', selected_rows.effective_selection_state
        ),
      selected_rows.timesheet_id,
      NULLIF(BTRIM(COALESCE(selected_rows.result_row_json#>>'{economic_key,key_type}', '')), ''),
      NULLIF(BTRIM(COALESCE(selected_rows.result_row_json#>>'{economic_key,key_value}', '')), ''),
      selected_rows.effective_selected,
      selected_rows.effective_selection_state,
      'READY',
      COALESCE(v_session_row.version, 1),
      v_now,
      v_now
    FROM visible_rows AS selected_rows
    ON CONFLICT (session_id, section, candidate_id, row_key)
    DO UPDATE
    SET row_ordinal = EXCLUDED.row_ordinal,
        row_json = EXCLUDED.row_json,
        timesheet_id = EXCLUDED.timesheet_id,
        key_type = EXCLUDED.key_type,
        key_value = EXCLUDED.key_value,
        selected = COALESCE(EXCLUDED.selected, false),
        selection_state = COALESCE(NULLIF(BTRIM(EXCLUDED.selection_state), ''), 'NOT_SELECTABLE'),
        status = EXCLUDED.status,
        session_version = EXCLUDED.session_version,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_preview_rows.id
  ), marked_line_work AS (
    UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
    SET status = CASE WHEN selected_rows.rotation_validation_failed IS TRUE THEN 'ERROR' ELSE 'MATERIALISED' END,
        result_row_json = CASE
          WHEN selected_rows.rotation_validation_failed IS TRUE THEN
            COALESCE(line_work.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'draftable', false,
              'is_ready_for_draft', false,
              'selection_allowed', false,
              'row_processing_status', 'ERROR',
              'rotation_validation_failed', true,
              'rotation_failure_reason', selected_rows.rotation_failure_reason
            )
          WHEN selected_rows.suppress_zero_outstanding_fixed_reimbursement IS TRUE
            OR selected_rows.suppress_negative_outstanding_fixed_reimbursement IS TRUE
            OR selected_rows.suppress_zero_outstanding_economic_key IS TRUE
            OR selected_rows.suppress_negative_outstanding_economic_key IS TRUE THEN
            COALESCE(line_work.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'draftable', false,
              'is_ready_for_draft', false,
              'selection_allowed', false,
              'pay_outstanding_blocked', true,
              'pay_outstanding_available_ex_vat', CASE
                WHEN selected_rows.suppress_zero_outstanding_economic_key IS TRUE
                  OR selected_rows.suppress_negative_outstanding_economic_key IS TRUE THEN selected_rows.economic_outstanding_ex_vat
                ELSE selected_rows.fixed_reimbursement_outstanding_ex_vat
              END,
              'outstanding_block_reason', CASE
                WHEN selected_rows.suppress_negative_outstanding_fixed_reimbursement IS TRUE
                  OR selected_rows.suppress_negative_outstanding_economic_key IS TRUE THEN 'NEGATIVE_OUTSTANDING_ROUTED_TO_OVERPAYMENT'
                WHEN selected_rows.suppress_zero_outstanding_economic_key IS TRUE THEN 'ECONOMIC_KEY_OUTSTANDING_NOT_AVAILABLE'
                ELSE 'REIMBURSEMENT_OUTSTANDING_NOT_AVAILABLE'
              END
            )
            || jsonb_build_object(
              'materialisation_suppressed', true,
              'materialisation_suppressed_reason', CASE
                WHEN selected_rows.suppress_negative_outstanding_fixed_reimbursement IS TRUE
                  OR selected_rows.suppress_negative_outstanding_economic_key IS TRUE THEN 'NEGATIVE_OUTSTANDING_ROUTED_TO_OVERPAYMENT'
                WHEN selected_rows.suppress_zero_outstanding_economic_key IS TRUE THEN 'ZERO_OUTSTANDING_ECONOMIC_KEY'
                ELSE 'ZERO_OUTSTANDING_FIXED_REIMBURSEMENT'
              END,
              'materialisation_suppressed_at_utc', v_now::text,
              'materialised_no_visible_preview_row', true,
              'presentation_role', 'HIDDEN',
              'presentation_section', 'INTERNAL_ONLY'
            )
          WHEN selected_rows.clamp_fixed_reimbursement_to_outstanding IS TRUE THEN
            COALESCE(line_work.result_row_json, '{}'::jsonb)
            || jsonb_build_object(
              'amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'amount_display', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'section_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'section_non_segment_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
            )
            || jsonb_build_object(
              'ready_preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'source_entitlement_amount_ex_vat', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'source_reservation_amount_ex_vat', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'source_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
            )
            || jsonb_build_object(
              'source_basis_json', COALESCE(line_work.result_row_json->'source_basis_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'pay_outstanding_clamped', true,
                  'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                ),
              'frozen_source_basis_json', COALESCE(line_work.result_row_json->'frozen_source_basis_json', line_work.result_row_json->'source_basis_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'pay_outstanding_clamped', true,
                  'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                ),
              'frozen_component_snapshot_json', COALESCE(line_work.result_row_json->'frozen_component_snapshot_json', '{}'::jsonb)
                || jsonb_build_object(
                  'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                )
                || jsonb_build_object(
                  'source_basis_json', COALESCE(line_work.result_row_json#>'{frozen_component_snapshot_json,source_basis_json}', '{}'::jsonb)
                    || jsonb_build_object(
                      'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                      'pay_outstanding_clamped', true,
                      'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                    )
                )
            )
            || jsonb_build_object(
              'remaining_source_amount', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'frozen_source_amount', ABS(selected_rows.fixed_reimbursement_outstanding_ex_vat),
              'frozen_target_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_clamped', true,
              'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
            )
            || jsonb_build_object(
              'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_available_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
              'pay_outstanding_blocked', false,
              'outstanding_block_reason', NULL,
              'case_components', (
                SELECT COALESCE(jsonb_agg(
                  CASE
                    WHEN component_element.value IS NOT NULL
                     AND jsonb_typeof(component_element.value) = 'object' THEN
                      component_element.value
                      || jsonb_build_object(
                        'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'target_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'ready_preview_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'preview_component_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                      )
                      || jsonb_build_object(
                        'remaining_source_amount', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'pay_outstanding_clamped', true,
                        'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat,
                        'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                        'source_basis_json', COALESCE(component_element.value->'source_basis_json', '{}'::jsonb)
                          || jsonb_build_object(
                            'source_pay_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                            'pay_outstanding_clamped', true,
                            'original_source_pay_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat
                          )
                      )
                    ELSE component_element.value
                  END
                  ORDER BY component_element.ordinality
                ), '[]'::jsonb)
                FROM jsonb_array_elements(
                  CASE
                    WHEN jsonb_typeof(line_work.result_row_json->'case_components') = 'array' THEN line_work.result_row_json->'case_components'
                    ELSE '[]'::jsonb
                  END
                ) WITH ORDINALITY AS component_element(value, ordinality)
              )
            )
            || CASE
              WHEN jsonb_typeof(line_work.result_row_json->'case_resolution_summary') = 'object' THEN jsonb_build_object(
                'case_resolution_summary',
                line_work.result_row_json->'case_resolution_summary'
                || jsonb_build_object(
                  'safe_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat,
                  'blocked_case_amount_ex_vat', 0,
                  'unresolved_taxable_amount_ex_vat', 0,
                  'pay_outstanding_clamped', true,
                  'pay_outstanding_original_amount_ex_vat', selected_rows.fixed_reimbursement_original_amount_ex_vat,
                  'pay_outstanding_clamped_amount_ex_vat', selected_rows.fixed_reimbursement_outstanding_ex_vat
                )
              )
              ELSE '{}'::jsonb
            END
            || CASE
              WHEN COALESCE(line_work.result_row_json->>'section_amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
               AND ROUND(ABS(COALESCE(selected_rows.fixed_reimbursement_original_amount_ex_vat, 0)), 2) > 0 THEN jsonb_build_object(
                'section_amount_display', ROUND(
                  selected_rows.fixed_reimbursement_outstanding_ex_vat
                  * ((line_work.result_row_json->>'section_amount_display')::numeric / selected_rows.fixed_reimbursement_original_amount_ex_vat),
                  2
                )
              )
              ELSE '{}'::jsonb
            END
          ELSE line_work.result_row_json
        END
        || CASE
          WHEN selected_rows.clamp_economic_key_to_outstanding IS TRUE THEN COALESCE(selected_rows.economic_outstanding_payload_json, '{}'::jsonb)
          ELSE '{}'::jsonb
        END,
        error_json = CASE
          WHEN selected_rows.rotation_validation_failed IS TRUE THEN jsonb_build_object(
            'code', 'WORKBENCH_MATERIALISE_ROTATED_TIMESHEET_MISMATCH',
            'message', 'Ready line work timesheet identities did not resolve to one current canonical timesheet at preview materialisation.',
            'line_key', selected_rows.line_key,
            'line_ordinal', selected_rows.line_ordinal,
            'scope_ordinal', selected_rows.scope_ordinal,
            'reason', selected_rows.rotation_failure_reason
          )
          ELSE line_work.error_json
        END,
        updated_at_utc = v_now
    FROM selected_rows
    WHERE line_work.id = selected_rows.id
    RETURNING line_work.id
  )
  SELECT COUNT(*)::integer
  INTO v_materialised_count
  FROM marked_line_work;

  UPDATE public.banking_pay_workbench_preview_rows AS superseded_preview_row
  SET status = 'SUPERSEDED',
      selected = false,
      selection_state = 'SUPERSEDED',
      updated_at_utc = v_now
  WHERE superseded_preview_row.session_id = p_session_id
    AND (superseded_preview_row.session_version IS DISTINCT FROM COALESCE(v_session_row.version, 1))
    AND UPPER(BTRIM(COALESCE(superseded_preview_row.status, ''))) <> 'SUPERSEDED'
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
      WHERE materialise_rows.page_ordinal <= v_limit
        AND materialise_rows.candidate_id = superseded_preview_row.candidate_id
    );

  IF v_raw_count > v_limit THEN
    SELECT
      materialise_rows.scope_ordinal,
      materialise_rows.line_ordinal,
      materialise_rows.id
    INTO
      v_last_returned_scope_ordinal,
      v_last_returned_line_ordinal,
      v_last_returned_line_work_id
    FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
    WHERE materialise_rows.page_ordinal = v_limit;

    v_next_cursor := jsonb_build_object(
      'last_scope_ordinal', v_last_returned_scope_ordinal,
      'last_line_ordinal', v_last_returned_line_ordinal,
      'last_line_work_id', v_last_returned_line_work_id::text
    );
  ELSE
    v_next_cursor := NULL::jsonb;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_materialise_scope_delta;
  CREATE TEMP TABLE _tmp_pay_wb_materialise_scope_delta ON COMMIT DROP AS
  WITH affected_candidates AS (
    SELECT DISTINCT materialise_rows.candidate_id
    FROM pg_temp._tmp_pay_wb_preview_materialise AS materialise_rows
    WHERE materialise_rows.page_ordinal <= v_limit
  ), candidate_new_status AS (
    SELECT affected_candidates.candidate_id,
           CASE
             WHEN EXISTS (
               SELECT 1
               FROM public.banking_pay_workbench_candidate_line_work AS line_error
               WHERE line_error.session_id = p_session_id
                 AND line_error.candidate_id = affected_candidates.candidate_id
                 AND UPPER(BTRIM(COALESCE(line_error.status, ''))) = 'ERROR'
             ) THEN 'ERROR'
             WHEN EXISTS (
               SELECT 1
               FROM public.banking_pay_workbench_candidate_line_work AS line_remaining
               WHERE line_remaining.session_id = p_session_id
                 AND line_remaining.candidate_id = affected_candidates.candidate_id
                 AND UPPER(BTRIM(COALESCE(line_remaining.status, ''))) IN ('PENDING', 'READY')
             ) THEN 'LINE_WORK_READY'
             ELSE 'MATERIALISED'
           END AS new_status
    FROM affected_candidates
  )
  SELECT
    scope_row.candidate_id,
    UPPER(BTRIM(COALESCE(scope_row.status, 'PENDING'))) AS old_status,
    candidate_new_status.new_status
  FROM candidate_new_status
  JOIN public.banking_pay_workbench_session_scope AS scope_row
    ON scope_row.session_id = p_session_id
   AND scope_row.candidate_id = candidate_new_status.candidate_id;

  SELECT
    COALESCE(SUM(
      CASE
        WHEN scope_delta.new_status IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR') THEN 0
        ELSE 1
      END
      - CASE
        WHEN scope_delta.old_status IN ('READY', 'MATERIALISED', 'MATERIALIZED', 'ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR') THEN 0
        ELSE 1
      END
    ), 0)::integer,
    COALESCE(SUM(
      CASE WHEN scope_delta.new_status IN ('READY', 'MATERIALISED', 'MATERIALIZED') THEN 1 ELSE 0 END
      - CASE WHEN scope_delta.old_status IN ('READY', 'MATERIALISED', 'MATERIALIZED') THEN 1 ELSE 0 END
    ), 0)::integer,
    COALESCE(SUM(
      CASE WHEN scope_delta.new_status IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR') THEN 1 ELSE 0 END
      - CASE WHEN scope_delta.old_status IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR') THEN 1 ELSE 0 END
    ), 0)::integer,
    COUNT(*) FILTER (
      WHERE scope_delta.new_status IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR')
    )::integer
  INTO v_scope_pending_delta,
       v_scope_ready_delta,
       v_scope_failed_delta,
       v_scope_error_candidate_count
  FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta;

  UPDATE public.banking_pay_workbench_preview_rows AS obsolete_current_preview_row
  SET status = 'SUPERSEDED',
      selected = false,
      selection_state = 'SUPERSEDED',
      updated_at_utc = v_now
  WHERE obsolete_current_preview_row.session_id = p_session_id
    AND obsolete_current_preview_row.session_version = COALESCE(v_session_row.version, 1)
    AND UPPER(BTRIM(COALESCE(obsolete_current_preview_row.status, ''))) = 'READY'
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta
      WHERE scope_delta.candidate_id = obsolete_current_preview_row.candidate_id
        AND scope_delta.new_status = 'MATERIALISED'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_line_work AS line_work
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = obsolete_current_preview_row.candidate_id
        AND line_work.line_key = obsolete_current_preview_row.row_key
        AND public.pay_workbench_preview_section_from_line_json(line_work.result_row_json) = obsolete_current_preview_row.section
        AND UPPER(BTRIM(COALESCE(line_work.status, ''))) IN ('READY', 'MATERIALISED')
    );

  UPDATE public.banking_pay_workbench_session_scope AS scope_row
  SET status = scope_delta.new_status,
      dirty = scope_delta.new_status <> 'MATERIALISED',
      error_json = CASE
        WHEN scope_delta.new_status IN ('ERROR', 'FAILED', 'LINE_WORK_ERROR', 'LINE_WORK_PROCESS_ERROR') THEN COALESCE(
          scope_row.error_json,
          jsonb_build_object(
            'code', 'PREVIEW_ROW_MATERIALISATION_ERROR',
            'candidate_id', scope_row.candidate_id::text,
            'session_id', p_session_id::text
          )
        )
        ELSE NULL::jsonb
      END,
      updated_at_utc = v_now
  FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = scope_delta.candidate_id;

  /* Materialisation is the final full-refresh evidence boundary.  Publish the
     row-backed candidate state here so a completed source/line/preview job
     chain cannot leave the workbench reading an older READY snapshot. */
  IF to_regprocedure(
       'public.pay_workbench_delta_update_candidate_state_v1(uuid,uuid,uuid,jsonb)'
     ) IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_STATE_PUBLISHER_UNAVAILABLE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_CANDIDATE_STATE_PUBLISHER_UNAVAILABLE',
              'session_id', p_session_id::text
            )::text;
  END IF;

  FOR v_candidate_state_candidate_id IN
    SELECT scope_delta.candidate_id
    FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta
    WHERE scope_delta.new_status = 'MATERIALISED'
    ORDER BY scope_delta.candidate_id
    LIMIT 100
  LOOP
    SELECT GREATEST(
             COALESCE((
               SELECT MAX(source_line.source_change_seq)
               FROM public.banking_pay_workbench_candidate_source_lines
                 AS source_line
               WHERE source_line.session_id = p_session_id
                 AND source_line.candidate_id =
                     v_candidate_state_candidate_id
                 AND source_line.session_version =
                     COALESCE(v_session_row.version, 1)
                 AND UPPER(BTRIM(COALESCE(
                       source_line.status,
                       ''
                     ))) = 'CURRENT'
             ), 0),
             COALESCE((
               SELECT MAX(
                 CASE
                   WHEN COALESCE(
                          source_job.payload_json->>'source_change_seq',
                          source_job.payload_json->>
                            'source_change_sequence',
                          source_job.payload_json->
                            'result_json'->>'source_change_seq',
                          ''
                        ) ~ '^[0-9]{1,18}$'
                     THEN COALESCE(
                            source_job.payload_json->
                              'result_json'->>'source_change_seq',
                            source_job.payload_json->
                              'result_json'->>'source_change_sequence',
                            source_job.payload_json->
                              'completion_json'->>'source_change_seq',
                            source_job.payload_json->
                              'completion_json'->>'source_change_sequence',
                            source_job.payload_json->>
                              'source_change_seq',
                            source_job.payload_json->>
                              'source_change_sequence'
                          )::bigint
                   ELSE 0::bigint
                 END
               )
               FROM public.banking_pay_workbench_jobs AS source_job
               WHERE source_job.session_id = p_session_id
                 AND source_job.candidate_id =
                     v_candidate_state_candidate_id
                 AND UPPER(BTRIM(COALESCE(
                       source_job.status,
                       ''
                     ))) = 'SUCCEEDED'
                 AND UPPER(BTRIM(COALESCE(
                       source_job.job_type,
                       ''
                     ))) IN (
                       'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                       'CANDIDATE_SOURCE_BUILD'
                     )
             ), 0)
           )
    INTO v_candidate_state_source_change_seq;

    SELECT CASE
             WHEN COUNT(DISTINCT source_line.source_build_run_id) = 1
               THEN MIN(source_line.source_build_run_id::text)::uuid
             ELSE NULL::uuid
           END
    INTO v_candidate_state_source_build_run_id
    FROM public.banking_pay_workbench_candidate_source_lines AS source_line
    WHERE source_line.session_id = p_session_id
      AND source_line.candidate_id = v_candidate_state_candidate_id
      AND source_line.session_version = COALESCE(v_session_row.version, 1)
      AND source_line.source_change_seq =
          COALESCE(v_candidate_state_source_change_seq, 0)
      AND UPPER(BTRIM(COALESCE(source_line.status, ''))) = 'CURRENT';

    IF v_candidate_state_source_build_run_id IS NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_SOURCE_RUN_AMBIGUOUS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_SOURCE_RUN_AMBIGUOUS',
                'session_id', p_session_id::text,
                'candidate_id', v_candidate_state_candidate_id::text,
                'source_change_seq',
                  COALESCE(v_candidate_state_source_change_seq, 0)
              )::text;
    END IF;

    EXECUTE
      'SELECT public.pay_workbench_delta_update_candidate_state_v1($1,$2,$3,$4)'
    INTO v_candidate_state_result
    USING
      p_session_id,
      v_candidate_state_candidate_id,
      v_candidate_state_source_build_run_id,
      jsonb_build_object(
        'context', 'DELTA_REFRESH',
        'update_context', 'FULL_PREVIEW_MATERIALISATION',
        'source_change_seq',
          COALESCE(v_candidate_state_source_change_seq, 0),
        'session_version', COALESCE(v_session_row.version, 1),
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );

    IF COALESCE((v_candidate_state_result->>'ok')::boolean, false)
         IS NOT TRUE
       OR LOWER(BTRIM(COALESCE(
            v_candidate_state_result->>
              'stale_candidate_state_update_skipped',
            'false'
          ))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_CANDIDATE_STATE_PUBLISH_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_CANDIDATE_STATE_PUBLISH_FAILED',
                'session_id', p_session_id::text,
                'candidate_id',
                  v_candidate_state_candidate_id::text,
                'source_change_seq',
                  COALESCE(v_candidate_state_source_change_seq, 0),
                'publisher_status',
                  v_candidate_state_result->>'status',
                'publisher_reason',
                  COALESCE(
                    v_candidate_state_result->>'fallback_reason',
                    v_candidate_state_result->>'stale_guard'
                  )
              )::text;
    END IF;

    v_candidate_state_update_count :=
      v_candidate_state_update_count + 1;
  END LOOP;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'candidate_id', scope_delta.candidate_id::text,
           'old_status', scope_delta.old_status,
           'new_status', scope_delta.new_status
         ) ORDER BY scope_delta.candidate_id), '[]'::jsonb)
  INTO v_affected_candidate_sample
  FROM (
    SELECT scope_delta.*
    FROM pg_temp._tmp_pay_wb_materialise_scope_delta AS scope_delta
    ORDER BY scope_delta.candidate_id
    LIMIT 25
  ) AS scope_delta;

  UPDATE public.banking_pay_workbench_sessions AS session_row
  SET line_units_ready = GREATEST(COALESCE(session_row.line_units_ready, 0) - COALESCE(v_materialised_count, 0), 0),
      line_units_failed = GREATEST(COALESCE(session_row.line_units_failed, 0) + COALESCE(v_materialise_error_count, 0), 0),
      preview_row_count = GREATEST(COALESCE(session_row.preview_row_count, 0) + COALESCE(v_new_preview_row_count, 0), 0),
      selected_row_count = GREATEST(COALESCE(session_row.selected_row_count, 0) + COALESCE(v_new_selected_row_count, 0), 0),
      scope_ready_count = GREATEST(COALESCE(session_row.scope_ready_count, 0) + COALESCE(v_scope_ready_delta, 0), 0),
      scope_pending_count = GREATEST(COALESCE(session_row.scope_pending_count, 0) + COALESCE(v_scope_pending_delta, 0), 0),
      scope_failed_count = GREATEST(COALESCE(session_row.scope_failed_count, 0) + COALESCE(v_scope_failed_delta, 0), 0),
      section_counts_json = COALESCE((
        SELECT COALESCE(jsonb_object_agg(merged_counts.section_key, to_jsonb(merged_counts.section_count) ORDER BY merged_counts.section_key), '{}'::jsonb)
        FROM (
          SELECT all_keys.section_key,
                 GREATEST(
                   COALESCE(NULLIF(BTRIM(session_row.section_counts_json->>all_keys.section_key), '')::integer, 0)
                   + COALESCE(NULLIF(BTRIM(v_section_delta_json->>all_keys.section_key), '')::integer, 0),
                   0
                 ) AS section_count
          FROM (
            SELECT existing_sections.key AS section_key
            FROM jsonb_each(COALESCE(session_row.section_counts_json, '{}'::jsonb)) AS existing_sections(key, value)
            UNION
            SELECT delta_sections.key AS section_key
            FROM jsonb_each(COALESCE(v_section_delta_json, '{}'::jsonb)) AS delta_sections(key, value)
          ) AS all_keys
        ) AS merged_counts
      ), '{}'::jsonb),
      candidate_sample_rows_json = COALESCE(v_affected_candidate_sample, '[]'::jsonb),
      progress_state = CASE
        WHEN UPPER(BTRIM(COALESCE(session_row.progress_state, ''))) IN ('ERROR', 'FAILED')
          OR COALESCE(v_materialise_error_count, 0) > 0
          OR COALESCE(v_scope_error_candidate_count, 0) > 0 THEN 'ERROR'
        ELSE 'MATERIALISING_PREVIEW_ROWS'
      END,
      progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'phase', CASE
            WHEN UPPER(BTRIM(COALESCE(session_row.progress_state, ''))) IN ('ERROR', 'FAILED')
              OR COALESCE(v_materialise_error_count, 0) > 0
              OR COALESCE(v_scope_error_candidate_count, 0) > 0 THEN 'ERROR'
            ELSE 'MATERIALISING_PREVIEW_ROWS'
          END,
          'status_text', CASE
            WHEN UPPER(BTRIM(COALESCE(session_row.progress_state, ''))) IN ('ERROR', 'FAILED')
              OR COALESCE(v_materialise_error_count, 0) > 0
              OR COALESCE(v_scope_error_candidate_count, 0) > 0 THEN 'Payment preview could not be prepared for every candidate.'
            ELSE 'Finalising payment preview rows.'
          END,
          'next_recommended_action', CASE
            WHEN UPPER(BTRIM(COALESCE(session_row.progress_state, ''))) IN ('ERROR', 'FAILED')
              OR COALESCE(v_materialise_error_count, 0) > 0
              OR COALESCE(v_scope_error_candidate_count, 0) > 0 THEN 'REVIEW_ERRORS'
            ELSE 'WAIT_FOR_WORKER'
          END,
          'last_preview_materialise_at_utc', v_now::text,
          'last_preview_materialise_count', COALESCE(v_materialised_count, 0),
          'last_preview_materialise_selected_count', COALESCE(v_new_selected_row_count, 0),
          'last_preview_materialise_suppressed_count', COALESCE(v_suppressed_preview_row_count, 0),
          'last_preview_materialise_error_count', COALESCE(v_materialise_error_count, 0),
          'last_preview_materialise_has_more', v_next_cursor IS NOT NULL,
          'last_scope_pending_delta', COALESCE(v_scope_pending_delta, 0),
          'last_scope_ready_delta', COALESCE(v_scope_ready_delta, 0),
          'last_scope_failed_delta', COALESCE(v_scope_failed_delta, 0),
          'terminal_readiness_deferred', true,
          'terminal_readiness_deferred_to', 'pay_workbench_complete_job'
        ),
      progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE session_row.id = p_session_id;

  PERFORM public.pay_workbench_session_recompute_progress_counters(
    p_session_id,
    true,
    'PREVIEW_ROWS_MATERIALISE_SELECTION_RECONCILE',
    false
  );

  SELECT COALESCE(jsonb_agg(to_jsonb(current_selected_preview_row.id::text) ORDER BY current_selected_preview_row.row_ordinal, current_selected_preview_row.id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_reconciled_selected_preview_row_ids,
       v_reconciled_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS current_selected_preview_row
  WHERE current_selected_preview_row.session_id = p_session_id
    AND current_selected_preview_row.session_version = COALESCE(v_session_row.version, 1)
    AND lower(COALESCE(NULLIF(BTRIM(current_selected_preview_row.section), ''), 'canonical_preview_lines')) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(current_selected_preview_row.status, ''))) = 'READY'
    AND COALESCE(current_selected_preview_row.selected, false) = true
    AND UPPER(BTRIM(COALESCE(current_selected_preview_row.selection_state, ''))) = 'SELECTED';

  UPDATE public.banking_pay_workbench_sessions AS selection_summary_session
  SET selected_row_count = COALESCE(v_reconciled_selected_row_count, 0),
      server_selected_preview_row_ids = CASE
        WHEN COALESCE(v_selection_intent_mode, '') = 'EXPLICIT_INCLUDE'
          OR COALESCE(selection_summary_session.server_selected_preview_row_ids_provided, false) IS TRUE
          THEN COALESCE(v_reconciled_selected_preview_row_ids, '[]'::jsonb)
        ELSE selection_summary_session.server_selected_preview_row_ids
      END,
      server_selected_preview_row_ids_provided = CASE
        WHEN COALESCE(v_selection_intent_mode, '') = 'EXPLICIT_INCLUDE' THEN true
        ELSE COALESCE(selection_summary_session.server_selected_preview_row_ids_provided, false)
      END,
      updated_at_utc = v_now
  WHERE selection_summary_session.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'limit', v_limit,
    'cursor_scope_ordinal', COALESCE(v_cursor_scope_ordinal, -1),
    'cursor_line_ordinal', COALESCE(v_cursor_line_ordinal, -1),
    'cursor_line_work_id', CASE WHEN v_cursor_line_work_id IS NULL THEN NULL ELSE v_cursor_line_work_id::text END,
    'materialised_count', COALESCE(v_materialised_count, 0),
    'new_preview_row_count', COALESCE(v_new_preview_row_count, 0),
    'new_selected_row_count', COALESCE(v_new_selected_row_count, 0),
    'suppressed_preview_row_count', COALESCE(v_suppressed_preview_row_count, 0),
    'materialisation_error_count', COALESCE(v_materialise_error_count, 0)
  )
  || jsonb_build_object(
    'next_cursor', v_next_cursor,
    'has_more', v_next_cursor IS NOT NULL,
    'section_delta_counts', COALESCE(v_section_delta_json, '{}'::jsonb),
    'affected_candidates', COALESCE(v_affected_candidate_sample, '[]'::jsonb),
    'scope_counter_deltas', jsonb_build_object(
      'pending_delta', COALESCE(v_scope_pending_delta, 0),
      'ready_delta', COALESCE(v_scope_ready_delta, 0),
      'failed_delta', COALESCE(v_scope_failed_delta, 0)
    ),
    'terminal_readiness_deferred', true,
    'terminal_readiness_deferred_to', 'pay_workbench_complete_job',
    'candidate_state_update_count',
      COALESCE(v_candidate_state_update_count, 0),
    'stable_row_ordinal_scheme', 'scope_ordinal_times_1000000_plus_line_ordinal',
    'cursor_scheme', 'last_scope_ordinal_last_line_ordinal_last_line_work_id'
  );
END;
$function$;

-- pay_workbench_preview_section_from_line_json(jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_preview_section_from_line_json(p_line_json jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_line_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_line_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_line_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_source_kind text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'source_kind', v_line_json->>'source_type', '')), ''));
  v_raw_section text := LOWER(NULLIF(BTRIM(COALESCE(v_line_json->>'target_section', v_line_json->>'section', '')), ''));
  v_presentation_section text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'presentation_section', '')), ''));
  v_readiness_state text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'readiness_state', '')), ''));
  v_line_type text := UPPER(NULLIF(BTRIM(COALESCE(v_line_json->>'line_type', v_line_json->>'case_type', '')), ''));
  v_blocked_reason_count integer := 0;
  v_draftable boolean := false;
  v_is_ready_for_draft boolean := false;
BEGIN
  IF v_source_kind IN (
    'TIMESHEET_SNAPSHOT',
    'TIMESHEET_SNAPSHOT_EVIDENCE',
    'RAW_TIMESHEET_SNAPSHOT',
    'INTERNAL_ONLY',
    'NO_DELTA',
    'EXCLUDED'
  ) THEN
    RETURN 'internal_only';
  END IF;

  IF v_raw_section IN ('canonical_preview_lines', 'ready_to_pay', 'ready_preview_lines', 'preview_rows') THEN
    RETURN 'canonical_preview_lines';
  END IF;

  IF v_raw_section IN ('cases_resolutions', 'case_resolution_states', 'case_resolutions', 'cases', 'resolutions') THEN
    RETURN 'cases_resolutions';
  END IF;

  IF v_raw_section IN ('blocked_for_pay', 'blocked_preview_lines', 'blocked_items', 'blocked_now') THEN
    RETURN 'blocked_for_pay';
  END IF;

  IF v_raw_section IN ('internal_only', 'hidden', 'excluded', 'no_delta') THEN
    RETURN 'internal_only';
  END IF;

  IF v_presentation_section IN ('READY_TO_PAY', 'READY', 'PAYABLE_NOW') THEN
    RETURN 'canonical_preview_lines';
  END IF;

  IF v_presentation_section IN ('CASES_RESOLUTIONS', 'CASE_RESOLUTION', 'CASE_RESOLUTIONS', 'RESOLUTION_REQUIRED')
     OR v_readiness_state IN ('CASES_RESOLUTIONS', 'CASE_RESOLUTION', 'CASE_RESOLUTIONS', 'RESOLUTION_REQUIRED') THEN
    RETURN 'cases_resolutions';
  END IF;

  IF v_presentation_section IN ('BLOCKED_FOR_PAY', 'BLOCKED', 'DO_NOT_PAY')
     OR v_readiness_state IN ('BLOCKED_FOR_PAY', 'BLOCKED', 'DO_NOT_PAY') THEN
    RETURN 'blocked_for_pay';
  END IF;

  IF jsonb_typeof(v_line_json->'blocked_reason_codes') = 'array' THEN
    v_blocked_reason_count := jsonb_array_length(v_line_json->'blocked_reason_codes');
  END IF;

  IF LOWER(BTRIM(COALESCE(v_line_json->>'case_is_blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     OR COALESCE(v_blocked_reason_count, 0) > 0 THEN
    RETURN 'blocked_for_pay';
  END IF;

  v_draftable := LOWER(BTRIM(COALESCE(v_line_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_is_ready_for_draft := LOWER(BTRIM(COALESCE(v_line_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF COALESCE(v_draftable, false)
     OR (COALESCE(v_is_ready_for_draft, false) AND v_line_type IS NOT NULL) THEN
    RETURN 'canonical_preview_lines';
  END IF;

  RETURN 'internal_only';
END;
$function$;

-- pay_workbench_project_changed_timesheets_v1(uuid,uuid,uuid,uuid[],uuid[],jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_project_changed_timesheets_v1(p_session_id uuid, p_candidate_id uuid, p_projection_run_id uuid, p_targeted_timesheet_ids uuid[], p_linked_timesheet_ids uuid[], p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_today_uk date := (clock_timestamp() AT TIME ZONE 'Europe/London')::date;
  v_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_row public.banking_pay_workbench_session_scope%ROWTYPE;
  v_session_version bigint := NULL::bigint;
  v_source_change_seq bigint := 0;
  v_projection_mode text := UPPER(BTRIM(COALESCE(p_payload_json->>'projection_mode', 'DELTA')));
  v_projection_class text := UPPER(BTRIM(COALESCE(p_payload_json->>'projection_class', 'NORMAL_TIMESHEET')));
  v_pay_channel_scope text := UPPER(BTRIM(COALESCE(p_payload_json->>'pay_channel_scope', 'ALL')));
  v_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_family_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_all_affected_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_count integer := 0;
  v_affected_count integer := 0;
  v_valid_owner_count integer := 0;
  v_has_complexity boolean := false;
  v_complexity_flags jsonb := '{}'::jsonb;
  v_has_finance_case boolean := false;
  v_has_pay_advance boolean := false;
  v_has_timesheet_advance boolean := false;
  v_has_manual_adjustment boolean := false;
  v_has_case_resolution boolean := false;
  v_has_policy_key_failure boolean := false;
  v_has_economic_key_mismatch boolean := false;
  v_has_contract_failure boolean := false;
  v_has_reservation_overrun boolean := false;
  v_projected_row_count integer := 0;
  v_suppressed_row_count integer := 0;
  v_ready_row_count integer := 0;
  v_blocked_row_count integer := 0;
  v_selected_row_count integer := 0;
  v_settings_row public.settings_defaults%ROWTYPE;
  v_rail_provider text := 'CSV';
  v_rail_env text := 'PROD';
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_cursor_json jsonb := '{}'::jsonb;
  v_current_family_index integer := 0;
  v_current_timesheet_id uuid := NULL::uuid;
  v_current_timesheet_id_text text := NULL::text;
  v_component_offset integer := 0;
  v_row_ordinal_offset integer := 0;
  v_limit integer := 25;
  v_total_stage_row_count integer := 0;
  v_next_component_offset integer := 0;
  v_more_due boolean := false;
  v_key_parity_proven boolean := false;
  v_economic_key_parity_proven boolean := false;
  v_shadow_compare_enforced boolean := false;
  v_processed_timesheet_count integer := 0;
  v_processed_component_count integer := 0;
  v_live_eligible_timesheet_count integer := 0;
  v_live_ineligible_timesheet_count integer := 0;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  v_cursor_json := CASE
    WHEN jsonb_typeof(v_payload_json->'cursor') = 'object' THEN COALESCE(v_payload_json->'cursor', '{}'::jsonb)
    WHEN jsonb_typeof(v_payload_json->'cursor_json') = 'object' THEN COALESCE(v_payload_json->'cursor_json', '{}'::jsonb)
    WHEN jsonb_typeof(v_payload_json#>'{projection,cursor}') = 'object' THEN COALESCE(v_payload_json#>'{projection,cursor}', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  IF COALESCE(v_cursor_json->>'family_index', v_cursor_json->>'current_family_index', '') ~ '^[0-9]{1,9}$' THEN
    v_current_family_index := GREATEST((COALESCE(v_cursor_json->>'family_index', v_cursor_json->>'current_family_index'))::integer, 0);
  END IF;

  v_current_timesheet_id_text := NULLIF(BTRIM(COALESCE(v_cursor_json->>'timesheet_id', v_cursor_json->>'current_timesheet_id', '')), '');
  IF v_current_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_current_timesheet_id := v_current_timesheet_id_text::uuid;
  END IF;

  IF COALESCE(v_cursor_json->>'component_offset', v_cursor_json->>'current_component_offset', '') ~ '^[0-9]{1,9}$' THEN
    v_component_offset := GREATEST((COALESCE(v_cursor_json->>'component_offset', v_cursor_json->>'current_component_offset'))::integer, 0);
  END IF;

  IF COALESCE(v_cursor_json->>'row_ordinal_offset', '') ~ '^[0-9]{1,9}$' THEN
    v_row_ordinal_offset := GREATEST((v_cursor_json->>'row_ordinal_offset')::integer, 0);
  ELSE
    v_row_ordinal_offset := v_component_offset;
  END IF;

  IF COALESCE(v_payload_json->>'limit', v_payload_json->>'projection_limit', '') ~ '^[0-9]{1,9}$' THEN
    v_limit := LEAST(GREATEST((COALESCE(v_payload_json->>'limit', v_payload_json->>'projection_limit'))::integer, 1), 100);
  ELSE
    v_limit := 25;
  END IF;

  -- Row-key / line-key parity is produced by this projector only from deterministic
  -- legacy-compatible workbench key composition. It is never trusted from caller input.
  v_key_parity_proven := true;
  v_economic_key_parity_proven := true;
  v_shadow_compare_enforced := lower(BTRIM(COALESCE(v_payload_json->>'shadow_compare_enforced', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF p_session_id IS NULL OR p_candidate_id IS NULL OR p_projection_run_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'DELTA_PROJECT_INPUT_REQUIRED',
      'projected_row_count', 0
    );
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
    AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
    AND session_row.discarded_at_utc IS NULL;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'SESSION_OR_SCOPE_NOT_OPEN',
      'projected_row_count', 0
    );
  END IF;

  SELECT scope_row.*
  INTO v_scope_row
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'SESSION_OR_SCOPE_NOT_OPEN',
      'projected_row_count', 0
    );
  END IF;

  IF COALESCE(v_payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN
    v_session_version := (v_payload_json->>'session_version')::bigint;
  ELSE
    v_session_version := COALESCE(v_session_row.version, 1);
  END IF;

  IF v_session_version IS DISTINCT FROM v_session_row.version THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'SESSION_VERSION_MISMATCH_DURING_PROJECTION',
      'projected_row_count', 0,
      'session_version', v_session_row.version,
      'payload_session_version', v_session_version
    );
  END IF;

  IF COALESCE(v_payload_json->>'source_change_seq', v_payload_json->>'source_change_sequence', '') ~ '^-?[0-9]{1,18}$' THEN
    v_source_change_seq := COALESCE(v_payload_json->>'source_change_seq', v_payload_json->>'source_change_sequence')::bigint;
  ELSE
    v_source_change_seq := 0;
  END IF;

  IF v_projection_mode IS DISTINCT FROM 'DELTA'
     OR v_projection_class IS DISTINCT FROM 'NORMAL_TIMESHEET' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'PROJECTION_CLASS_REQUIRES_NON_TIMESHEET_PATCH_PATH',
      'projection_mode', v_projection_mode,
      'projection_class', v_projection_class,
      'projected_row_count', 0
    );
  END IF;


  SELECT COALESCE(array_agg(DISTINCT targeted_values.timesheet_id_value ORDER BY targeted_values.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_ids
  FROM unnest(COALESCE(p_targeted_timesheet_ids, ARRAY[]::uuid[])) AS targeted_values(timesheet_id_value)
  WHERE targeted_values.timesheet_id_value IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT linked_values.timesheet_id_value ORDER BY linked_values.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_linked_timesheet_ids
  FROM unnest(COALESCE(p_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_values(timesheet_id_value)
  WHERE linked_values.timesheet_id_value IS NOT NULL;

  v_targeted_count := COALESCE(array_length(v_targeted_timesheet_ids, 1), 0);

  IF v_targeted_count = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'TARGETED_TIMESHEET_IDS_REQUIRED',
      'projected_row_count', 0
    );
  END IF;

  SELECT settings_row.*
  INTO v_settings_row
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id ASC
  LIMIT 1;

  IF FOUND THEN
    v_rail_provider := UPPER(BTRIM(COALESCE(v_settings_row.rail_provider_default, 'CSV')));
    v_rail_env := UPPER(BTRIM(COALESCE(v_settings_row.rail_env_default, 'PROD')));
    v_need_name_check := COALESCE(v_settings_row.rail_supports_name_check, false)
                         AND UPPER(BTRIM(COALESCE(v_settings_row.rail_provider_default, 'CSV'))) <> 'CSV';
    v_requires_payee_map := UPPER(BTRIM(COALESCE(v_settings_row.rail_provider_default, 'CSV'))) <> 'CSV';
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS _bpay_delta_projection_rows (
    projection_run_id uuid NOT NULL,
    session_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    session_version bigint NOT NULL,
    source_change_seq bigint,
    timesheet_id uuid,
    canonical_timesheet_id uuid,
    section text NOT NULL,
    line_key text NOT NULL,
    row_key text NOT NULL,
    parent_line_key text,
    split_suffix text,
    source_ordinal bigint NOT NULL,
    row_ordinal bigint NOT NULL,
    pay_channel_scope text,
    refresh_scope_kind text NOT NULL,
    key_type text,
    key_value text,
    amount_ex_vat numeric,
    amount_inc_vat numeric,
    vat_amount numeric,
    draftable boolean NOT NULL DEFAULT false,
    is_ready_for_draft boolean NOT NULL DEFAULT false,
    selection_allowed boolean NOT NULL DEFAULT false,
    readiness_state text,
    blocked_reason_codes jsonb NOT NULL DEFAULT '[]'::jsonb,
    outstanding_state_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    source_row_json jsonb NOT NULL,
    economic_key_json jsonb NOT NULL,
    contract_json jsonb NOT NULL,
    work_payload_json jsonb NOT NULL,
    result_row_json jsonb NOT NULL,
    preview_row_json jsonb NOT NULL,
    contract_ok boolean NOT NULL DEFAULT false,
    materialisable boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;

  DELETE FROM pg_temp._bpay_delta_projection_rows AS existing_projection_rows
  WHERE existing_projection_rows.projection_run_id = p_projection_run_id
    AND existing_projection_rows.session_id = p_session_id
    AND existing_projection_rows.candidate_id = p_candidate_id;

  DROP TABLE IF EXISTS pg_temp._bpay_delta_projection_scope;
  CREATE TEMP TABLE _bpay_delta_projection_scope ON COMMIT DROP AS
  SELECT DISTINCT
    rotation_scope.requested_timesheet_id,
    rotation_scope.booking_id,
    rotation_scope.canonical_timesheet_id,
    rotation_scope.family_timesheet_id,
    rotation_scope.family_is_current,
    rotation_scope.family_version,
    rotation_scope.requested_is_canonical
  FROM public._pay_timesheet_rotation_scope(v_targeted_timesheet_ids) AS rotation_scope
  WHERE rotation_scope.family_timesheet_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT scope_union.timesheet_id_value ORDER BY scope_union.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_family_timesheet_ids
  FROM (
    SELECT scope_rows.family_timesheet_id AS timesheet_id_value
    FROM pg_temp._bpay_delta_projection_scope AS scope_rows
    WHERE scope_rows.family_timesheet_id IS NOT NULL
    UNION ALL
    SELECT linked_values.timesheet_id_value
    FROM unnest(COALESCE(v_linked_timesheet_ids, ARRAY[]::uuid[])) AS linked_values(timesheet_id_value)
    WHERE linked_values.timesheet_id_value IS NOT NULL
  ) AS scope_union;

  SELECT COALESCE(array_agg(DISTINCT affected_values.timesheet_id_value ORDER BY affected_values.timesheet_id_value), ARRAY[]::uuid[])
  INTO v_all_affected_timesheet_ids
  FROM (
    SELECT target_values.timesheet_id_value
    FROM unnest(COALESCE(v_targeted_timesheet_ids, ARRAY[]::uuid[])) AS target_values(timesheet_id_value)
    WHERE target_values.timesheet_id_value IS NOT NULL
    UNION ALL
    SELECT family_values.timesheet_id_value
    FROM unnest(COALESCE(v_family_timesheet_ids, ARRAY[]::uuid[])) AS family_values(timesheet_id_value)
    WHERE family_values.timesheet_id_value IS NOT NULL
  ) AS affected_values;

  v_affected_count := COALESCE(array_length(v_all_affected_timesheet_ids, 1), 0);

  IF v_affected_count = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'TARGET_SCOPE_MISSING',
      'projected_row_count', 0
    );
  END IF;

  SELECT COUNT(DISTINCT affected_owner.timesheet_id_value)::integer
  INTO v_valid_owner_count
  FROM unnest(v_all_affected_timesheet_ids) AS affected_owner(timesheet_id_value)
  JOIN public.timesheets AS timesheet_row
    ON timesheet_row.timesheet_id = affected_owner.timesheet_id_value
  LEFT JOIN public.contracts AS contract_row
    ON contract_row.id = timesheet_row.contract_id
  WHERE contract_row.candidate_id = p_candidate_id
     OR EXISTS (
       SELECT 1
       FROM public.timesheets_financials AS tsfin_owner
       WHERE tsfin_owner.timesheet_id = affected_owner.timesheet_id_value
         AND tsfin_owner.candidate_id = p_candidate_id
     );

  IF COALESCE(v_valid_owner_count, 0) <> v_affected_count THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'TARGET_SCOPE_NOT_IN_CANDIDATE',
      'projected_row_count', 0,
      'affected_timesheet_count', v_affected_count,
      'valid_owner_count', COALESCE(v_valid_owner_count, 0)
    );
  END IF;

  -- Snooze identity and presentation are resolved by the canonical live-truth
  -- source builder.  DELTA must not duplicate or broaden segment matching.
  IF EXISTS (
    SELECT 1
    FROM public.pay_item_snoozes AS snooze_row
    WHERE snooze_row.candidate_id = p_candidate_id
      AND snooze_row.cleared_at_utc IS NULL
      AND snooze_row.cancelled_at_utc IS NULL
      AND (
        snooze_row.snooze_until_date IS NULL
        OR snooze_row.snooze_until_date >= v_today_uk
      )
      AND (
        snooze_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
        OR (
          snooze_row.booking_id IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM public.timesheets AS snooze_timesheet
            WHERE snooze_timesheet.timesheet_id = ANY(v_all_affected_timesheet_ids)
              AND snooze_timesheet.booking_id = snooze_row.booking_id
          )
        )
      )
  ) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'ACTIVE_SNOOZE_REQUIRES_CANONICAL_SOURCE_BUILD',
      'projected_row_count', 0,
      'affected_timesheet_count', v_affected_count,
      'london_current_date', v_today_uk::text
    );
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_finance_case_components AS component_row
    WHERE component_row.candidate_id = p_candidate_id
      AND component_row.closed_at_utc IS NULL
      AND (
        component_row.linked_timesheet_id IS NULL
        OR component_row.linked_timesheet_id = ANY(v_all_affected_timesheet_ids)
      )
  )
  INTO v_has_finance_case;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_advances AS advance_row
    WHERE advance_row.candidate_id = p_candidate_id
      AND UPPER(COALESCE(advance_row.status::text, '')) IN ('ACTIVE', 'PAUSED')
      AND advance_row.cleared_at_utc IS NULL
      AND advance_row.written_off_at_utc IS NULL
      AND (
        advance_row.linked_timesheet_id IS NULL
        OR advance_row.linked_timesheet_id = ANY(v_all_affected_timesheet_ids)
      )
  )
  INTO v_has_pay_advance;

  SELECT EXISTS (
    SELECT 1
    FROM public.timesheet_payment_overrides AS override_row
    WHERE override_row.candidate_id = p_candidate_id
      AND override_row.override_type = 'ADVANCE_THIS_PAYMENT'
      AND override_row.consumed_at_utc IS NULL
      AND override_row.cleared_at_utc IS NULL
      AND override_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
  )
  INTO v_has_timesheet_advance;

  SELECT EXISTS (
    SELECT 1
    FROM public.ts_pay_adjustments AS adjustment_row
    WHERE adjustment_row.candidate_id = p_candidate_id
      AND adjustment_row.paid_at_utc IS NULL
      AND adjustment_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
  )
  INTO v_has_manual_adjustment;

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_session_case_resolutions AS resolution_row
    WHERE resolution_row.session_id = p_session_id
      AND resolution_row.candidate_id = p_candidate_id
      AND (
        resolution_row.timesheet_id IS NULL
        OR resolution_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
      )
  )
  INTO v_has_case_resolution;

  v_has_complexity := COALESCE(v_has_finance_case, false)
                      OR COALESCE(v_has_pay_advance, false)
                      OR COALESCE(v_has_timesheet_advance, false)
                      OR COALESCE(v_has_manual_adjustment, false)
                      OR COALESCE(v_has_case_resolution, false);

  v_complexity_flags := jsonb_build_object(
    'has_finance_case', COALESCE(v_has_finance_case, false),
    'has_pay_advance', COALESCE(v_has_pay_advance, false),
    'has_timesheet_advance', COALESCE(v_has_timesheet_advance, false),
    'has_manual_adjustment', COALESCE(v_has_manual_adjustment, false),
    'has_case_resolution', COALESCE(v_has_case_resolution, false)
  );

  IF v_has_complexity IS TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'COMPLEXITY_DISCOVERED_DURING_PROJECTION',
      'projected_row_count', 0,
      'complexity_flags', v_complexity_flags
    );
  END IF;

  -- PRE_DRAFT_LIVE_TRUTH eligibility is a hard publication precondition for
  -- targeted normal-timesheet DELTA. Entitlement/outstanding rows alone are not
  -- enough: unauthorised/PENDING_AUTH live truth must be a successful zero-row
  -- cleanup rather than a payable preview row.
  SELECT
    COUNT(*) FILTER (WHERE live_truth.live_pay_eligible IS TRUE)::integer,
    COUNT(*) FILTER (WHERE live_truth.live_pay_eligible IS NOT TRUE)::integer
  INTO v_live_eligible_timesheet_count,
       v_live_ineligible_timesheet_count
  FROM (
    SELECT
      affected_values.timesheet_id_value,
      (
        timesheet_row.timesheet_id IS NOT NULL
        AND timesheet_row.authorised_at_server IS NOT NULL
        AND timesheet_row.revoked_at IS NULL
        AND timesheet_financial_row.timesheet_id IS NOT NULL
        AND timesheet_financial_row.authorised_at_utc IS NOT NULL
        AND UPPER(BTRIM(COALESCE(timesheet_financial_row.processing_status::text, ''))) = 'READY_FOR_INVOICE'
        AND COALESCE(timesheet_financial_row.pay_on_hold, false) IS NOT TRUE
        AND COALESCE(timesheet_financial_row.has_rate_issue, false) IS NOT TRUE
        AND COALESCE(timesheet_financial_row.has_pay_channel_issue, false) IS NOT TRUE
      ) AS live_pay_eligible
    FROM unnest(COALESCE(v_all_affected_timesheet_ids, ARRAY[]::uuid[])) AS affected_values(timesheet_id_value)
    LEFT JOIN public.timesheets AS timesheet_row
      ON timesheet_row.timesheet_id = affected_values.timesheet_id_value
     AND timesheet_row.is_current = true
    LEFT JOIN public.timesheets_financials AS timesheet_financial_row
      ON timesheet_financial_row.timesheet_id = affected_values.timesheet_id_value
     AND timesheet_financial_row.is_current = true
  ) AS live_truth;

  v_complexity_flags := COALESCE(v_complexity_flags, '{}'::jsonb)
    || jsonb_build_object(
      'pre_draft_live_truth_gate', 'STRICT_READY_FOR_INVOICE_AUTHORISED',
      'live_pay_eligible_timesheet_count', COALESCE(v_live_eligible_timesheet_count, 0),
      'live_pay_ineligible_timesheet_count', COALESCE(v_live_ineligible_timesheet_count, 0)
    );

  DROP TABLE IF EXISTS pg_temp._bpay_delta_project_stage;
  CREATE TEMP TABLE _bpay_delta_project_stage ON COMMIT DROP AS
  WITH candidate_context AS (
    SELECT
      candidate_row.id AS candidate_id,
      candidate_row.tms_ref AS candidate_tms_ref,
      candidate_row.display_name AS candidate_display_name,
      UPPER(BTRIM(COALESCE(candidate_row.pay_method, 'PAYE'))) AS candidate_pay_method,
      candidate_row.umbrella_id AS candidate_umbrella_id,
      candidate_row.bank_details_hash AS candidate_bank_hash,
      candidate_row.account_holder AS candidate_account_holder,
      candidate_row.sort_code AS candidate_sort_code,
      candidate_row.account_number AS candidate_account_number,
      candidate_row.bank_name AS candidate_bank_name,
      umbrella_row.name AS umbrella_name,
      umbrella_row.enabled AS umbrella_enabled,
      umbrella_row.bank_details_hash AS umbrella_bank_hash,
      umbrella_row.sort_code AS umbrella_sort_code,
      umbrella_row.account_number AS umbrella_account_number,
      umbrella_row.bank_name AS umbrella_bank_name
    FROM public.candidates AS candidate_row
    LEFT JOIN public.umbrellas AS umbrella_row
      ON umbrella_row.id = candidate_row.umbrella_id
    WHERE candidate_row.id = p_candidate_id
  ), payee_context AS (
    SELECT
      candidate_context.candidate_id,
      candidate_context.candidate_tms_ref,
      candidate_context.candidate_display_name,
      candidate_context.candidate_pay_method,
      CASE WHEN candidate_context.candidate_pay_method = 'PAYE' THEN 'CANDIDATE' ELSE 'UMBRELLA' END AS payee_entity_kind,
      CASE WHEN candidate_context.candidate_pay_method = 'PAYE' THEN candidate_context.candidate_id ELSE candidate_context.candidate_umbrella_id END AS payee_entity_id,
      CASE WHEN candidate_context.candidate_pay_method = 'PAYE' THEN NULLIF(BTRIM(COALESCE(candidate_context.candidate_bank_hash, '')), '') ELSE NULLIF(BTRIM(COALESCE(candidate_context.umbrella_bank_hash, '')), '') END AS payee_bank_hash,
      CASE WHEN candidate_context.candidate_pay_method = 'PAYE' THEN NULLIF(BTRIM(COALESCE(candidate_context.candidate_account_holder, candidate_context.candidate_display_name, '')), '') ELSE NULLIF(BTRIM(COALESCE(candidate_context.umbrella_name, '')), '') END AS payee_account_holder,
      CASE WHEN candidate_context.candidate_pay_method = 'PAYE' THEN NULLIF(BTRIM(COALESCE(candidate_context.candidate_sort_code, '')), '') ELSE NULLIF(BTRIM(COALESCE(candidate_context.umbrella_sort_code, '')), '') END AS payee_sort_code,
      CASE WHEN candidate_context.candidate_pay_method = 'PAYE' THEN NULLIF(BTRIM(COALESCE(candidate_context.candidate_account_number, '')), '') ELSE NULLIF(BTRIM(COALESCE(candidate_context.umbrella_account_number, '')), '') END AS payee_account_number,
      CASE WHEN candidate_context.candidate_pay_method = 'PAYE' THEN NULLIF(BTRIM(COALESCE(candidate_context.candidate_bank_name, '')), '') ELSE NULLIF(BTRIM(COALESCE(candidate_context.umbrella_bank_name, '')), '') END AS payee_bank_name,
      COALESCE(candidate_context.umbrella_enabled, false) AS umbrella_enabled
    FROM candidate_context
  ), payee_readiness AS (
    SELECT
      payee_context.*,
      COALESCE(name_check_row.status, 'UNVERIFIED') AS name_check_status,
      COALESCE(name_check_row.has_override, false) AS name_check_has_override,
      (payee_map_row.payee_id IS NOT NULL) AS payee_map_present,
      (
        payee_context.payee_entity_id IS NULL
        OR payee_context.payee_bank_hash IS NULL
        OR payee_context.payee_account_holder IS NULL
        OR payee_context.payee_sort_code IS NULL
        OR payee_context.payee_account_number IS NULL
      ) AS is_missing_bank_details,
      (
        payee_context.payee_entity_kind = 'UMBRELLA'
        AND COALESCE(payee_context.umbrella_enabled, false) IS NOT TRUE
      ) AS is_umbrella_inactive
    FROM payee_context
    LEFT JOIN LATERAL (
      SELECT
        bank_name_check_row.status,
        (bank_name_check_row.override_reason IS NOT NULL AND bank_name_check_row.override_hash IS NOT DISTINCT FROM payee_context.payee_bank_hash) AS has_override
      FROM public.bank_name_checks AS bank_name_check_row
      WHERE bank_name_check_row.rail_provider = v_rail_provider
        AND bank_name_check_row.rail_env = v_rail_env
        AND bank_name_check_row.entity_kind = payee_context.payee_entity_kind
        AND bank_name_check_row.entity_id = payee_context.payee_entity_id
        AND bank_name_check_row.bank_details_hash IS NOT DISTINCT FROM payee_context.payee_bank_hash
      ORDER BY bank_name_check_row.checked_at_utc DESC NULLS LAST,
               bank_name_check_row.updated_at_utc DESC,
               bank_name_check_row.created_at_utc DESC,
               bank_name_check_row.id DESC
      LIMIT 1
    ) AS name_check_row ON true
    LEFT JOIN LATERAL (
      SELECT bank_payee_map_row.payee_id
      FROM public.bank_payee_map AS bank_payee_map_row
      WHERE bank_payee_map_row.rail_provider = v_rail_provider
        AND bank_payee_map_row.rail_env = v_rail_env
        AND bank_payee_map_row.entity_kind = payee_context.payee_entity_kind
        AND bank_payee_map_row.entity_id = payee_context.payee_entity_id
        AND bank_payee_map_row.bank_details_hash IS NOT DISTINCT FROM payee_context.payee_bank_hash
      ORDER BY bank_payee_map_row.updated_at_utc DESC,
               bank_payee_map_row.created_at_utc DESC,
               bank_payee_map_row.id DESC
      LIMIT 1
    ) AS payee_map_row ON true
  ), payee_blockers AS (
    SELECT
      payee_readiness.*,
      (
        CASE WHEN payee_readiness.is_missing_bank_details THEN jsonb_build_array('BLOCKED_BANK_DETAILS') ELSE '[]'::jsonb END
        || CASE WHEN payee_readiness.is_umbrella_inactive THEN jsonb_build_array('BLOCKED_UMBRELLA_INACTIVE') ELSE '[]'::jsonb END
        || CASE WHEN v_need_name_check AND COALESCE(payee_readiness.name_check_status, 'UNVERIFIED') <> 'PASS' AND COALESCE(payee_readiness.name_check_has_override, false) IS NOT TRUE THEN jsonb_build_array('BLOCKED_NAME_CHECK') ELSE '[]'::jsonb END
        || CASE WHEN v_requires_payee_map AND COALESCE(payee_readiness.payee_map_present, false) IS NOT TRUE THEN jsonb_build_array('BLOCKED_NO_PAYEE_MAP') ELSE '[]'::jsonb END
      ) AS payee_blocked_reason_codes
    FROM payee_readiness
  ), entitlement_rows AS (
    SELECT
      entitlement_row.timesheet_id,
      UPPER(BTRIM(COALESCE(entitlement_row.key_type, ''))) AS key_type,
      NULLIF(BTRIM(COALESCE(entitlement_row.key_value, '')), '') AS key_value,
      ROUND(COALESCE(entitlement_row.truth_ex_vat, 0), 2) AS truth_ex_vat,
      ROUND(COALESCE(entitlement_row.truth_inc_vat, entitlement_row.truth_ex_vat, 0), 2) AS truth_inc_vat,
      ROUND(COALESCE(outstanding_row.outstanding_ex_vat, entitlement_row.truth_ex_vat, 0), 2) AS outstanding_ex_vat,
      ROUND(COALESCE(outstanding_row.outstanding_inc_vat, entitlement_row.truth_inc_vat, entitlement_row.truth_ex_vat, 0), 2) AS outstanding_inc_vat,
      COALESCE(outstanding_row.reserved_ex_vat, 0) AS reserved_ex_vat,
      COALESCE(outstanding_row.reservation_overrun_detected, false) AS reservation_overrun_detected
    FROM public._pay_current_timesheet_entitlement_components(v_all_affected_timesheet_ids) AS entitlement_row
    LEFT JOIN public._pay_outstanding_components(v_all_affected_timesheet_ids) AS outstanding_row
      ON outstanding_row.timesheet_id = entitlement_row.timesheet_id
     AND outstanding_row.key_type = entitlement_row.key_type
     AND outstanding_row.key_value = entitlement_row.key_value
    WHERE entitlement_row.key_type IS NOT NULL
      AND BTRIM(entitlement_row.key_type) <> ''
      AND entitlement_row.key_value IS NOT NULL
      AND BTRIM(entitlement_row.key_value) <> ''
  ), current_timesheet_rows AS (
    SELECT DISTINCT ON (timesheet_row.timesheet_id)
      timesheet_row.timesheet_id,
      timesheet_row.booking_id,
      timesheet_row.reference_number,
      timesheet_row.week_ending_date,
      timesheet_row.line_type::text AS timesheet_line_type,
      timesheet_row.sheet_scope::text AS sheet_scope,
      timesheet_row.authorised_at_server,
      timesheet_row.revoked_at,
      timesheet_row.contract_id,
      contract_week_row.id AS contract_week_id,
      COALESCE(timesheet_financial_row.client_id, contract_row.client_id) AS client_id,
      client_row.name AS client_name,
      COALESCE(timesheet_financial_row.role, contract_row.role, timesheet_row.job_title_norm) AS role,
      COALESCE(timesheet_financial_row.band, timesheet_row.band, contract_row.band) AS band,
      contract_row.display_site,
      contract_row.ward_hint,
      COALESCE(timesheet_row.worked_start_iso, timesheet_financial_row.worked_start_iso) AS worked_start_iso,
      COALESCE(timesheet_row.worked_end_iso, timesheet_financial_row.worked_end_iso) AS worked_end_iso,
      COALESCE(timesheet_row.break_start_iso, timesheet_financial_row.break_start_iso) AS break_start_iso,
      COALESCE(timesheet_row.break_end_iso, timesheet_financial_row.break_end_iso) AS break_end_iso,
      COALESCE(timesheet_row.break_minutes, timesheet_financial_row.break_minutes) AS break_minutes,
      CASE
        WHEN jsonb_typeof(timesheet_financial_row.actual_schedule_json) = 'object' THEN timesheet_financial_row.actual_schedule_json
        WHEN jsonb_typeof(timesheet_financial_row.actual_schedule_json) = 'array' THEN (
          SELECT financial_schedule_item.value
          FROM jsonb_array_elements(timesheet_financial_row.actual_schedule_json) AS financial_schedule_item(value)
          WHERE financial_schedule_item.value IS NOT NULL
            AND jsonb_typeof(financial_schedule_item.value) = 'object'
          LIMIT 1
        )
        WHEN jsonb_typeof(timesheet_row.actual_schedule_json) = 'object' THEN timesheet_row.actual_schedule_json
        WHEN jsonb_typeof(timesheet_row.actual_schedule_json) = 'array' THEN (
          SELECT timesheet_schedule_item.value
          FROM jsonb_array_elements(timesheet_row.actual_schedule_json) AS timesheet_schedule_item(value)
          WHERE timesheet_schedule_item.value IS NOT NULL
            AND jsonb_typeof(timesheet_schedule_item.value) = 'object'
          LIMIT 1
        )
        ELSE NULL::jsonb
      END AS effective_daily_schedule_json,
      COALESCE(timesheet_financial_row.invoice_breakdown_json, '{}'::jsonb) AS invoice_breakdown_json,
      ROUND(COALESCE(timesheet_financial_row.total_hours, 0), 6) AS total_hours,
      ROUND(COALESCE(timesheet_financial_row.total_pay_ex_vat, 0), 2) AS total_pay_ex_vat,
      ROUND(COALESCE(timesheet_financial_row.total_charge_ex_vat, 0), 2) AS total_charge_ex_vat,
      ROUND(COALESCE(timesheet_financial_row.expenses_charge_ex_vat, 0), 2) AS expenses_charge_ex_vat,
      ROUND(COALESCE(timesheet_financial_row.travel_charge_ex_vat, 0), 2) AS travel_charge_ex_vat,
      ROUND(COALESCE(timesheet_financial_row.accommodation_charge_ex_vat, 0), 2) AS accommodation_charge_ex_vat,
      ROUND(COALESCE(timesheet_financial_row.other_charge_ex_vat, 0), 2) AS other_charge_ex_vat,
      ROUND(COALESCE(timesheet_financial_row.mileage_charge_ex_vat, 0), 2) AS mileage_charge_ex_vat,
      CASE
        WHEN COALESCE(active_settled.active_settled_component_count, 0) > 0 THEN '{}'::jsonb
        ELSE COALESCE(timesheet_pay_state.last_settled_snapshot_json, '{}'::jsonb)
      END AS expense_baseline_json,
      ROUND(COALESCE(timesheet_financial_row.hours_day, 0), 6) AS hours_day,
      ROUND(COALESCE(timesheet_financial_row.hours_night, 0), 6) AS hours_night,
      ROUND(COALESCE(timesheet_financial_row.hours_sat, 0), 6) AS hours_sat,
      ROUND(COALESCE(timesheet_financial_row.hours_sun, 0), 6) AS hours_sun,
      ROUND(COALESCE(timesheet_financial_row.hours_bh, 0), 6) AS hours_bh,
      COALESCE(timesheet_financial_row.pay_method, candidate_context.candidate_pay_method) AS timesheet_pay_method,
      timesheet_financial_row.authorised_at_utc AS financial_authorised_at_utc,
      UPPER(BTRIM(COALESCE(timesheet_financial_row.processing_status::text, ''))) AS financial_processing_status,
      COALESCE(timesheet_financial_row.pay_on_hold, false) AS pay_on_hold,
      COALESCE(timesheet_financial_row.has_rate_issue, false) AS has_rate_issue,
      COALESCE(timesheet_financial_row.has_pay_channel_issue, false) AS has_pay_channel_issue,
      (
        timesheet_row.authorised_at_server IS NOT NULL
        AND timesheet_row.revoked_at IS NULL
        AND timesheet_financial_row.timesheet_id IS NOT NULL
        AND timesheet_financial_row.authorised_at_utc IS NOT NULL
        AND UPPER(BTRIM(COALESCE(timesheet_financial_row.processing_status::text, ''))) = 'READY_FOR_INVOICE'
        AND COALESCE(timesheet_financial_row.pay_on_hold, false) IS NOT TRUE
        AND COALESCE(timesheet_financial_row.has_rate_issue, false) IS NOT TRUE
        AND COALESCE(timesheet_financial_row.has_pay_channel_issue, false) IS NOT TRUE
      ) AS live_pay_eligible
    FROM public.timesheets AS timesheet_row
    LEFT JOIN public.timesheets_financials AS timesheet_financial_row
      ON timesheet_financial_row.timesheet_id = timesheet_row.timesheet_id
     AND timesheet_financial_row.is_current = true
    LEFT JOIN public.timesheet_pay_state AS timesheet_pay_state
      ON timesheet_pay_state.timesheet_id = timesheet_row.timesheet_id
    LEFT JOIN LATERAL (
      SELECT COUNT(*)::integer AS active_settled_component_count
      FROM public._pay_active_settled_components(ARRAY[timesheet_row.timesheet_id]::uuid[]) AS active_component
    ) AS active_settled ON true
    LEFT JOIN public.contracts AS contract_row
      ON contract_row.id = timesheet_row.contract_id
    LEFT JOIN public.clients AS client_row
      ON client_row.id = COALESCE(timesheet_financial_row.client_id, contract_row.client_id)
    LEFT JOIN public.contract_weeks AS contract_week_row
      ON contract_week_row.timesheet_id = timesheet_row.timesheet_id
    CROSS JOIN candidate_context
    WHERE timesheet_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
      AND timesheet_row.is_current = true
    ORDER BY timesheet_row.timesheet_id, timesheet_row.is_current DESC, timesheet_row.version DESC, timesheet_row.updated_at DESC, contract_week_row.updated_at DESC NULLS LAST, contract_week_row.id
  ), projected_components AS (
    SELECT
      entitlement_rows.timesheet_id,
      COALESCE(scope_choice.canonical_timesheet_id, entitlement_rows.timesheet_id) AS canonical_timesheet_id,
      current_timesheet_rows.booking_id,
      current_timesheet_rows.reference_number,
      current_timesheet_rows.week_ending_date,
      current_timesheet_rows.contract_id,
      current_timesheet_rows.contract_week_id,
      current_timesheet_rows.client_id,
      current_timesheet_rows.client_name,
      current_timesheet_rows.role,
      current_timesheet_rows.band,
      current_timesheet_rows.display_site,
      current_timesheet_rows.ward_hint,
      current_timesheet_rows.timesheet_line_type,
      current_timesheet_rows.sheet_scope,
      current_timesheet_rows.worked_start_iso,
      current_timesheet_rows.worked_end_iso,
      current_timesheet_rows.break_start_iso,
      current_timesheet_rows.break_end_iso,
      current_timesheet_rows.break_minutes,
      current_timesheet_rows.effective_daily_schedule_json,
      current_timesheet_rows.invoice_breakdown_json,
      current_timesheet_rows.total_hours,
      current_timesheet_rows.total_pay_ex_vat,
      current_timesheet_rows.total_charge_ex_vat,
      current_timesheet_rows.expenses_charge_ex_vat,
      current_timesheet_rows.travel_charge_ex_vat,
      current_timesheet_rows.accommodation_charge_ex_vat,
      current_timesheet_rows.other_charge_ex_vat,
      current_timesheet_rows.mileage_charge_ex_vat,
      current_timesheet_rows.expense_baseline_json,
      current_timesheet_rows.hours_day,
      current_timesheet_rows.hours_night,
      current_timesheet_rows.hours_sat,
      current_timesheet_rows.hours_sun,
      current_timesheet_rows.hours_bh,
      current_timesheet_rows.authorised_at_server,
      current_timesheet_rows.financial_authorised_at_utc,
      current_timesheet_rows.financial_processing_status,
      current_timesheet_rows.pay_on_hold,
      current_timesheet_rows.has_rate_issue,
      current_timesheet_rows.has_pay_channel_issue,
      current_timesheet_rows.live_pay_eligible,
      UPPER(BTRIM(COALESCE(current_timesheet_rows.timesheet_pay_method, payee_blockers.candidate_pay_method, 'PAYE'))) AS effective_pay_method,
      entitlement_rows.key_type,
      entitlement_rows.key_value,
      entitlement_rows.truth_ex_vat,
      entitlement_rows.truth_inc_vat,
      entitlement_rows.outstanding_ex_vat,
      entitlement_rows.outstanding_inc_vat,
      entitlement_rows.reserved_ex_vat,
      entitlement_rows.reservation_overrun_detected,
      payee_blockers.candidate_tms_ref,
      payee_blockers.candidate_display_name,
      payee_blockers.payee_entity_kind,
      payee_blockers.payee_entity_id,
      payee_blockers.payee_bank_hash,
      payee_blockers.name_check_status,
      payee_blockers.name_check_has_override,
      payee_blockers.payee_map_present,
      payee_blockers.payee_blocked_reason_codes,
      EXISTS (
        SELECT 1
        FROM public.pay_item_snoozes AS snooze_row
        WHERE snooze_row.candidate_id = p_candidate_id
          AND snooze_row.cleared_at_utc IS NULL
          AND snooze_row.cancelled_at_utc IS NULL
          AND (snooze_row.snooze_until_date IS NULL OR snooze_row.snooze_until_date >= v_today_uk)
          AND (
            snooze_row.timesheet_id = entitlement_rows.timesheet_id
            OR snooze_row.timesheet_id = ANY(v_all_affected_timesheet_ids)
          )
      ) AS has_active_snooze
    FROM entitlement_rows
    JOIN current_timesheet_rows
      ON current_timesheet_rows.timesheet_id = entitlement_rows.timesheet_id
     AND current_timesheet_rows.live_pay_eligible IS TRUE
    CROSS JOIN payee_blockers
    LEFT JOIN LATERAL (
      SELECT scope_rows.canonical_timesheet_id
      FROM pg_temp._bpay_delta_projection_scope AS scope_rows
      WHERE scope_rows.family_timesheet_id = entitlement_rows.timesheet_id
      ORDER BY scope_rows.family_is_current DESC NULLS LAST,
               scope_rows.family_version DESC NULLS LAST,
               scope_rows.family_timesheet_id
      LIMIT 1
    ) AS scope_choice ON true
  ), projected_timesheet_contract AS (
    SELECT DISTINCT ON (projected_components.timesheet_id)
      projected_components.timesheet_id,
      projected_components.canonical_timesheet_id,
      projected_components.booking_id,
      projected_components.reference_number,
      projected_components.client_id,
      projected_components.client_name,
      projected_components.role,
      projected_components.band,
      projected_components.display_site,
      projected_components.ward_hint,
      projected_components.sheet_scope,
      projected_components.worked_start_iso,
      projected_components.worked_end_iso,
      projected_components.break_start_iso,
      projected_components.break_end_iso,
      projected_components.break_minutes,
      projected_components.effective_daily_schedule_json,
      projected_components.invoice_breakdown_json,
      projected_components.total_hours,
      projected_components.total_pay_ex_vat,
      projected_components.total_charge_ex_vat,
      projected_components.hours_day,
      projected_components.hours_night,
      projected_components.hours_sat,
      projected_components.hours_sun,
      projected_components.hours_bh
    FROM projected_components
    ORDER BY projected_components.timesheet_id,
             CASE WHEN projected_components.key_type = 'TS_DAY' THEN 0 ELSE 1 END,
             projected_components.key_type,
             projected_components.key_value
  ), timesheet_segment_rows AS (
    SELECT
      projected_timesheet_contract.timesheet_id,
      COALESCE(
        jsonb_agg(segment_output.segment_json ORDER BY segment_output.segment_order)
          FILTER (WHERE segment_output.segment_json IS NOT NULL),
        '[]'::jsonb
      ) AS timesheet_segment_rows_json,
      COUNT(*) FILTER (WHERE segment_output.segment_json IS NOT NULL)::integer AS timesheet_segment_count
    FROM projected_timesheet_contract
    LEFT JOIN LATERAL (
      SELECT
        segment_source.segment_order,
        jsonb_strip_nulls(
          jsonb_build_object(
            'timesheet_id', projected_timesheet_contract.timesheet_id::text,
            'real_business_timesheet_id', projected_timesheet_contract.timesheet_id::text,
            'candidate_id', p_candidate_id::text,
            'booking_id', projected_timesheet_contract.booking_id,
            'segment_id', segment_source.segment_id,
            'segment_key', segment_source.segment_key,
            'segment_stable_key', segment_source.segment_stable_key,
            'date', segment_source.work_date_text,
            'work_date', segment_source.work_date_text,
            'linked_shift_date', segment_source.work_date_text,
            'client_id', CASE WHEN projected_timesheet_contract.client_id IS NULL THEN NULL ELSE projected_timesheet_contract.client_id::text END,
            'client_name', projected_timesheet_contract.client_name,
            'role', projected_timesheet_contract.role,
            'job_title', projected_timesheet_contract.role,
            'band', projected_timesheet_contract.band,
            'display_site', projected_timesheet_contract.display_site,
            'ward_hint', projected_timesheet_contract.ward_hint,
            'ref_num', segment_source.ref_num,
            'reference_number', projected_timesheet_contract.reference_number,
            'nhsp_shift_id', segment_source.nhsp_shift_id,
            'shift_id', segment_source.shift_id,
            'external_row_key', segment_source.external_row_key,
            'hr_request_id', segment_source.hr_request_id,
            'request_id', segment_source.request_id,
            'source_system', segment_source.source_system,
            'latest_import_id', segment_source.latest_import_id
          )
          || jsonb_build_object(
            'start_utc', segment_source.start_utc_text,
            'end_utc', segment_source.end_utc_text,
            'start', segment_source.start_text,
            'start_time', segment_source.start_text,
            'finish', segment_source.finish_text,
            'finish_time', segment_source.finish_text,
            'end', segment_source.finish_text,
            'break_start', segment_source.break_start_text,
            'break_end', segment_source.break_end_text,
            'break_mins', segment_source.break_mins,
            'break_minutes', segment_source.break_mins,
            'breaks', COALESCE(segment_source.breaks_json, '[]'::jsonb),
            'source_pay_amount_ex_vat', segment_source.source_pay_amount_ex_vat,
            'hours', segment_source.hours,
            'units', segment_source.hours
          )
          || jsonb_build_object(
            'snooze_identity', jsonb_strip_nulls(jsonb_build_object(
              'identity_type', 'SEGMENT',
              'candidate_id', p_candidate_id::text,
              'timesheet_id', projected_timesheet_contract.timesheet_id::text,
              'booking_id', projected_timesheet_contract.booking_id,
              'segment_id', segment_source.segment_id,
              'segment_key', segment_source.segment_key,
              'segment_stable_key', segment_source.segment_stable_key,
              'source_ref', segment_source.ref_num,
              'date', segment_source.work_date_text
            )),
            'snooze_state', 'NONE',
            'whole_timesheet_snooze_action_blocked', false,
            'segment_snooze_action_blocked', false
          )
        ) AS segment_json
      FROM (
        SELECT
          segment_values.ordinality::integer AS segment_order,
          NULLIF(BTRIM(COALESCE(
            segment_values.segment_json->>'date',
            segment_values.segment_json->>'work_date',
            segment_values.segment_json->>'linked_shift_date',
            segment_values.segment_json->>'shift_date',
            segment_values.segment_json->>'day',
            ''
          )), '') AS work_date_text,
          COALESCE(
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'segment_id', '')), ''),
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'segment_key', '')), ''),
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'segment_stable_key', '')), ''),
            'ts:' || projected_timesheet_contract.timesheet_id::text || ':' || segment_values.ordinality::text
          ) AS segment_id,
          COALESCE(
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'segment_key', '')), ''),
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'segment_id', '')), ''),
            'ts:' || projected_timesheet_contract.timesheet_id::text || ':' || segment_values.ordinality::text
          ) AS segment_key,
          COALESCE(
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'segment_stable_key', '')), ''),
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'segment_id', '')), ''),
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'segment_key', '')), ''),
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'date', segment_values.segment_json->>'work_date', '')), ''),
            'timesheet:' || COALESCE(projected_timesheet_contract.booking_id, projected_timesheet_contract.timesheet_id::text) || ':' || segment_values.ordinality::text
          ) AS segment_stable_key,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'nhsp_shift_id','')), '') AS nhsp_shift_id,
          COALESCE(
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'shift_id','')), ''),
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'nhsp_shift_id','')), '')
          ) AS shift_id,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'external_row_key','')), '') AS external_row_key,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'hr_request_id','')), '') AS hr_request_id,
          COALESCE(
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'request_id','')), ''),
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'hr_request_id','')), '')
          ) AS request_id,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'source_system','')), '') AS source_system,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'latest_import_id','')), '') AS latest_import_id,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'ref_num', segment_values.segment_json->>'reference_number', projected_timesheet_contract.reference_number, '')), '') AS ref_num,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'start_utc', segment_values.segment_json->>'worked_start_utc', '')), '') AS start_utc_text,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'end_utc', segment_values.segment_json->>'finish_utc', segment_values.segment_json->>'worked_end_utc', '')), '') AS end_utc_text,
          COALESCE(
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'start', segment_values.segment_json->>'start_time', segment_values.segment_json->>'worked_start', '')), ''),
            CASE
              WHEN NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'start_utc', segment_values.segment_json->>'worked_start_utc', '')), '') ~ '^\d{4}-\d{2}-\d{2}[ T]'
                THEN to_char(((COALESCE(segment_values.segment_json->>'start_utc', segment_values.segment_json->>'worked_start_utc'))::timestamptz AT TIME ZONE 'Europe/London'), 'HH24:MI')
              ELSE NULL::text
            END
          ) AS start_text,
          COALESCE(
            NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'finish', segment_values.segment_json->>'finish_time', segment_values.segment_json->>'end', segment_values.segment_json->>'end_time', segment_values.segment_json->>'worked_end', '')), ''),
            CASE
              WHEN NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'end_utc', segment_values.segment_json->>'finish_utc', segment_values.segment_json->>'worked_end_utc', '')), '') ~ '^\d{4}-\d{2}-\d{2}[ T]'
                THEN to_char(((COALESCE(segment_values.segment_json->>'end_utc', segment_values.segment_json->>'finish_utc', segment_values.segment_json->>'worked_end_utc'))::timestamptz AT TIME ZONE 'Europe/London'), 'HH24:MI')
              ELSE NULL::text
            END
          ) AS finish_text,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'break_start', segment_values.segment_json->>'breakStart', '')), '') AS break_start_text,
          NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'break_end', segment_values.segment_json->>'breakEnd', '')), '') AS break_end_text,
          CASE
            WHEN NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'break_mins', segment_values.segment_json->>'break_minutes', segment_values.segment_json->>'breakMinutes', '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN ROUND((COALESCE(segment_values.segment_json->>'break_mins', segment_values.segment_json->>'break_minutes', segment_values.segment_json->>'breakMinutes'))::numeric, 0)
            ELSE NULL::numeric
          END AS break_mins,
          CASE WHEN jsonb_typeof(segment_values.segment_json->'breaks') = 'array' THEN segment_values.segment_json->'breaks' ELSE '[]'::jsonb END AS breaks_json,
          CASE
            WHEN NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'pay_amount_ex_vat', segment_values.segment_json->>'amount_ex_vat', segment_values.segment_json->>'pay_amount', '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN ROUND((COALESCE(segment_values.segment_json->>'pay_amount_ex_vat', segment_values.segment_json->>'amount_ex_vat', segment_values.segment_json->>'pay_amount'))::numeric, 2)
            ELSE NULL::numeric
          END AS source_pay_amount_ex_vat,
          CASE
            WHEN NULLIF(BTRIM(COALESCE(segment_values.segment_json->>'hours', segment_values.segment_json->>'units', '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN ROUND((COALESCE(segment_values.segment_json->>'hours', segment_values.segment_json->>'units'))::numeric, 6)
            ELSE NULL::numeric
          END AS hours
        FROM jsonb_array_elements(
          CASE
            WHEN projected_timesheet_contract.invoice_breakdown_json IS NOT NULL
             AND jsonb_typeof(projected_timesheet_contract.invoice_breakdown_json) = 'object'
             AND UPPER(COALESCE(projected_timesheet_contract.invoice_breakdown_json->>'mode', '')) = 'SEGMENTS'
             AND jsonb_typeof(projected_timesheet_contract.invoice_breakdown_json->'segments') = 'array'
              THEN projected_timesheet_contract.invoice_breakdown_json->'segments'
            ELSE '[]'::jsonb
          END
        ) WITH ORDINALITY AS segment_values(segment_json, ordinality)
        WHERE segment_values.segment_json IS NOT NULL
          AND jsonb_typeof(segment_values.segment_json) = 'object'

        UNION ALL

        SELECT
          1 AS segment_order,
          COALESCE(
            CASE WHEN projected_timesheet_contract.worked_start_iso IS NOT NULL THEN ((projected_timesheet_contract.worked_start_iso AT TIME ZONE 'Europe/London')::date)::text ELSE NULL::text END,
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'date', '')), ''),
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'work_date', '')), ''),
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'ymd', '')), ''),
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'date_ymd', '')), '')
          ) AS work_date_text,
          'ts:' || projected_timesheet_contract.timesheet_id::text AS segment_id,
          'ts:' || projected_timesheet_contract.timesheet_id::text AS segment_key,
          'timesheet:' || COALESCE(projected_timesheet_contract.booking_id, projected_timesheet_contract.timesheet_id::text) AS segment_stable_key,
          NULL::text AS nhsp_shift_id,
          NULL::text AS shift_id,
          NULL::text AS external_row_key,
          NULL::text AS hr_request_id,
          NULL::text AS request_id,
          NULL::text AS source_system,
          NULL::text AS latest_import_id,
          NULLIF(BTRIM(COALESCE(projected_timesheet_contract.reference_number, '')), '') AS ref_num,
          CASE WHEN projected_timesheet_contract.worked_start_iso IS NULL THEN NULL::text ELSE projected_timesheet_contract.worked_start_iso::text END AS start_utc_text,
          CASE WHEN projected_timesheet_contract.worked_end_iso IS NULL THEN NULL::text ELSE projected_timesheet_contract.worked_end_iso::text END AS end_utc_text,
          COALESCE(
            CASE WHEN projected_timesheet_contract.worked_start_iso IS NOT NULL THEN to_char((projected_timesheet_contract.worked_start_iso AT TIME ZONE 'Europe/London'), 'HH24:MI') ELSE NULL::text END,
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'start', '')), ''),
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'start_time', '')), ''),
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'worked_start', '')), '')
          ) AS start_text,
          COALESCE(
            CASE WHEN projected_timesheet_contract.worked_end_iso IS NOT NULL THEN to_char((projected_timesheet_contract.worked_end_iso AT TIME ZONE 'Europe/London'), 'HH24:MI') ELSE NULL::text END,
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'finish', '')), ''),
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'finish_time', '')), ''),
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'end', '')), ''),
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'worked_end', '')), '')
          ) AS finish_text,
          COALESCE(
            CASE WHEN projected_timesheet_contract.break_start_iso IS NOT NULL THEN to_char((projected_timesheet_contract.break_start_iso AT TIME ZONE 'Europe/London'), 'HH24:MI') ELSE NULL::text END,
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'break_start', '')), '')
          ) AS break_start_text,
          COALESCE(
            CASE WHEN projected_timesheet_contract.break_end_iso IS NOT NULL THEN to_char((projected_timesheet_contract.break_end_iso AT TIME ZONE 'Europe/London'), 'HH24:MI') ELSE NULL::text END,
            NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'break_end', '')), '')
          ) AS break_end_text,
          COALESCE(
            projected_timesheet_contract.break_minutes::numeric,
            CASE WHEN NULLIF(BTRIM(COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'break_minutes', projected_timesheet_contract.effective_daily_schedule_json->>'break_mins', projected_timesheet_contract.effective_daily_schedule_json->>'breakMinutes', '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN ROUND((COALESCE(projected_timesheet_contract.effective_daily_schedule_json->>'break_minutes', projected_timesheet_contract.effective_daily_schedule_json->>'break_mins', projected_timesheet_contract.effective_daily_schedule_json->>'breakMinutes'))::numeric, 0)
              ELSE NULL::numeric
            END,
            CASE
              WHEN projected_timesheet_contract.break_start_iso IS NOT NULL AND projected_timesheet_contract.break_end_iso IS NOT NULL
                THEN GREATEST(0::numeric, ROUND((EXTRACT(EPOCH FROM (projected_timesheet_contract.break_end_iso - projected_timesheet_contract.break_start_iso)) / 60.0)::numeric, 0))
              ELSE NULL::numeric
            END
          ) AS break_mins,
          CASE
            WHEN jsonb_typeof(projected_timesheet_contract.effective_daily_schedule_json->'breaks') = 'array' THEN projected_timesheet_contract.effective_daily_schedule_json->'breaks'
            WHEN projected_timesheet_contract.break_start_iso IS NOT NULL AND projected_timesheet_contract.break_end_iso IS NOT NULL THEN jsonb_build_array(jsonb_build_object(
              'start', to_char((projected_timesheet_contract.break_start_iso AT TIME ZONE 'Europe/London'), 'HH24:MI'),
              'end', to_char((projected_timesheet_contract.break_end_iso AT TIME ZONE 'Europe/London'), 'HH24:MI'),
              'break_mins', COALESCE(projected_timesheet_contract.break_minutes::numeric, GREATEST(0::numeric, ROUND((EXTRACT(EPOCH FROM (projected_timesheet_contract.break_end_iso - projected_timesheet_contract.break_start_iso)) / 60.0)::numeric, 0)))
            ))
            ELSE '[]'::jsonb
          END AS breaks_json,
          ROUND(COALESCE(projected_timesheet_contract.total_pay_ex_vat, 0), 2) AS source_pay_amount_ex_vat,
          ROUND(COALESCE(projected_timesheet_contract.total_hours, 0), 6) AS hours
        WHERE NOT (
            projected_timesheet_contract.invoice_breakdown_json IS NOT NULL
            AND jsonb_typeof(projected_timesheet_contract.invoice_breakdown_json) = 'object'
            AND UPPER(COALESCE(projected_timesheet_contract.invoice_breakdown_json->>'mode', '')) = 'SEGMENTS'
            AND jsonb_typeof(projected_timesheet_contract.invoice_breakdown_json->'segments') = 'array'
          )
          AND UPPER(BTRIM(COALESCE(projected_timesheet_contract.sheet_scope, ''))) = 'DAILY'
      ) AS segment_source
      WHERE segment_source.work_date_text ~ '^\d{4}-\d{2}-\d{2}$'
    ) AS segment_output ON true
    GROUP BY projected_timesheet_contract.timesheet_id
  ), projected_component_flags AS (
    SELECT
      projected_components.*,
      COALESCE(timesheet_segment_rows.timesheet_segment_rows_json, '[]'::jsonb) AS timesheet_segment_rows_json,
      COALESCE(timesheet_segment_rows.timesheet_segment_count, 0) AS timesheet_segment_count,
      BOOL_OR(projected_components.key_type = 'TS_DAY') OVER (PARTITION BY projected_components.timesheet_id) AS timesheet_has_ts_day_component
    FROM projected_components
    LEFT JOIN timesheet_segment_rows
      ON timesheet_segment_rows.timesheet_id = projected_components.timesheet_id
  ), row_identity AS (
    SELECT
      projected_component_flags.*,
      CASE
        WHEN projected_component_flags.key_type = 'TS_TOTAL' THEN projected_component_flags.canonical_timesheet_id::text || ':non_segment:total'
        WHEN projected_component_flags.key_type = 'TS_DAY' THEN projected_component_flags.canonical_timesheet_id::text || ':segment:' || lower(regexp_replace(projected_component_flags.key_value, '[^0-9A-Za-z_-]+', '_', 'g'))
        WHEN projected_component_flags.key_type = 'EXPENSE_CODE' THEN projected_component_flags.canonical_timesheet_id::text || ':component:expense:' || md5(projected_component_flags.key_value)
        WHEN projected_component_flags.key_type = 'ADDITIONAL_CODE' THEN projected_component_flags.canonical_timesheet_id::text || ':component:additional:' || md5(projected_component_flags.key_value)
        ELSE projected_component_flags.canonical_timesheet_id::text || ':component:' || lower(regexp_replace(projected_component_flags.key_type, '[^0-9A-Za-z_-]+', '_', 'g')) || ':' || md5(projected_component_flags.key_value)
      END AS row_key,
      CASE
        WHEN projected_component_flags.key_type = 'TS_TOTAL' THEN projected_component_flags.canonical_timesheet_id::text || ':non_segment:total'
        WHEN projected_component_flags.key_type = 'TS_DAY' THEN projected_component_flags.canonical_timesheet_id::text || ':segment:' || lower(regexp_replace(projected_component_flags.key_value, '[^0-9A-Za-z_-]+', '_', 'g'))
        WHEN projected_component_flags.key_type = 'EXPENSE_CODE' THEN projected_component_flags.canonical_timesheet_id::text || ':component:expense:' || md5(projected_component_flags.key_value)
        WHEN projected_component_flags.key_type = 'ADDITIONAL_CODE' THEN projected_component_flags.canonical_timesheet_id::text || ':component:additional:' || md5(projected_component_flags.key_value)
        ELSE projected_component_flags.canonical_timesheet_id::text || ':component:' || lower(regexp_replace(projected_component_flags.key_type, '[^0-9A-Za-z_-]+', '_', 'g')) || ':' || md5(projected_component_flags.key_value)
      END AS line_key,
      CASE
        WHEN projected_component_flags.outstanding_ex_vat <= 0 THEN true
        ELSE false
      END AS suppress_zero_or_negative_outstanding,
      (
        projected_component_flags.payee_blocked_reason_codes
        || CASE WHEN projected_component_flags.has_active_snooze THEN jsonb_build_array('BLOCKED_TIMESHEET_SNOOZE') ELSE '[]'::jsonb END
        || CASE WHEN projected_component_flags.outstanding_ex_vat <= 0 THEN jsonb_build_array('ECONOMIC_KEY_OUTSTANDING_NOT_AVAILABLE') ELSE '[]'::jsonb END
        || CASE
          WHEN projected_component_flags.key_type = 'EXPENSE_CODE'
           AND UPPER(projected_component_flags.key_value) NOT IN ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
            THEN jsonb_build_array('EXPENSE_SOURCE_IDENTITY_UNAVAILABLE')
          ELSE '[]'::jsonb
        END
      ) AS blocked_reason_codes
    FROM projected_component_flags
  ), row_segment_contract AS (
    SELECT
      row_identity.*,
      COALESCE(row_segments.row_segment_rows_json, '[]'::jsonb) AS row_segment_rows_json,
      COALESCE(row_segments.row_segment_count, 0) AS row_segment_count,
      row_segments.first_segment_json,
      COALESCE(
        row_segments.top_level_work_date_text,
        CASE WHEN row_identity.key_type = 'TS_DAY' AND row_identity.key_value ~ '^\d{4}-\d{2}-\d{2}$' THEN row_identity.key_value ELSE NULL::text END
      ) AS row_work_date_text
    FROM row_identity
    LEFT JOIN LATERAL (
      WITH selected_segments AS (
        SELECT
          source_segment.segment_json,
          source_segment.ordinality,
          CASE
            WHEN COALESCE(source_segment.segment_json->>'source_pay_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN ROUND((source_segment.segment_json->>'source_pay_amount_ex_vat')::numeric, 2)
            ELSE NULL::numeric
          END AS source_pay_amount_ex_vat
        FROM jsonb_array_elements(COALESCE(row_identity.timesheet_segment_rows_json, '[]'::jsonb)) WITH ORDINALITY AS source_segment(segment_json, ordinality)
        WHERE source_segment.segment_json IS NOT NULL
          AND jsonb_typeof(source_segment.segment_json) = 'object'
          AND (
            (
              row_identity.key_type = 'TS_DAY'
              AND row_identity.key_value ~ '^\d{4}-\d{2}-\d{2}$'
              AND COALESCE(source_segment.segment_json->>'date', source_segment.segment_json->>'work_date', source_segment.segment_json->>'linked_shift_date') = row_identity.key_value
            )
            OR (
              row_identity.key_type = 'TS_TOTAL'
              AND COALESCE(row_identity.timesheet_has_ts_day_component, false) IS NOT TRUE
            )
          )
      ), selected_stats AS (
        SELECT
          COUNT(*)::integer AS selected_count,
          COUNT(*) FILTER (WHERE selected_segments.source_pay_amount_ex_vat IS NOT NULL)::integer AS selected_source_amount_count
        FROM selected_segments
      ), materialised_segments AS (
        SELECT
          selected_segments.segment_json,
          selected_segments.ordinality,
          CASE
            WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL')
             AND selected_stats.selected_count = 1 THEN row_identity.outstanding_ex_vat
            WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN selected_segments.source_pay_amount_ex_vat
            ELSE NULL::numeric
          END AS display_amount_ex_vat
        FROM selected_segments
        CROSS JOIN selected_stats
        WHERE selected_stats.selected_count > 0
          AND (
            (
              row_identity.key_type IN ('TS_DAY', 'TS_TOTAL')
              AND selected_stats.selected_count = 1
            )
            OR (
              row_identity.key_type IN ('TS_DAY', 'TS_TOTAL')
              AND selected_stats.selected_source_amount_count = selected_stats.selected_count
            )
          )
      )
      SELECT
        COALESCE(
          jsonb_agg(
            jsonb_strip_nulls(
              materialised_segments.segment_json
              || jsonb_build_object(
                'presentation_section', 'READY_TO_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', row_identity.line_key,
                'presentation_line_id', row_identity.line_key || ':segment:' || materialised_segments.ordinality::text,
                'preview_parent_row_id', row_identity.row_key,
                'component_key_type', row_identity.key_type,
                'component_key_value', row_identity.key_value,
                'source_basis_json', materialised_segments.segment_json
              )
              || CASE
                WHEN materialised_segments.display_amount_ex_vat IS NOT NULL THEN jsonb_build_object(
                  'pay_amount_ex_vat', ROUND(materialised_segments.display_amount_ex_vat, 2),
                  'amount_ex_vat', ROUND(materialised_segments.display_amount_ex_vat, 2),
                  'pay_amount', ROUND(materialised_segments.display_amount_ex_vat, 2)
                )
                ELSE '{}'::jsonb
              END
            )
            ORDER BY materialised_segments.ordinality
          ),
          '[]'::jsonb
        ) AS row_segment_rows_json,
        COUNT(*)::integer AS row_segment_count,
        (ARRAY_AGG(materialised_segments.segment_json ORDER BY materialised_segments.ordinality))[1] AS first_segment_json,
        (ARRAY_AGG(COALESCE(materialised_segments.segment_json->>'date', materialised_segments.segment_json->>'work_date', materialised_segments.segment_json->>'linked_shift_date') ORDER BY materialised_segments.ordinality))[1] AS top_level_work_date_text
      FROM materialised_segments
    ) AS row_segments ON true
  ), expense_identity_base AS (
    SELECT
      row_segment_contract.*,
      CASE UPPER(row_segment_contract.key_value)
        WHEN 'EXPENSES' THEN ROUND(
          COALESCE(row_segment_contract.expenses_charge_ex_vat, 0)
          - COALESCE(NULLIF(row_segment_contract.expense_baseline_json #>> '{expenses,expenses_charge_ex_vat}', '')::numeric, 0),
          2
        )
        WHEN 'TRAVEL' THEN ROUND(
          COALESCE(row_segment_contract.travel_charge_ex_vat, 0)
          - COALESCE(NULLIF(row_segment_contract.expense_baseline_json #>> '{expenses,travel_charge_ex_vat}', '')::numeric, 0),
          2
        )
        WHEN 'ACCOMMODATION' THEN ROUND(
          COALESCE(row_segment_contract.accommodation_charge_ex_vat, 0)
          - COALESCE(NULLIF(row_segment_contract.expense_baseline_json #>> '{expenses,accommodation_charge_ex_vat}', '')::numeric, 0),
          2
        )
        WHEN 'OTHER' THEN ROUND(
          COALESCE(row_segment_contract.other_charge_ex_vat, 0)
          - COALESCE(NULLIF(row_segment_contract.expense_baseline_json #>> '{expenses,other_charge_ex_vat}', '')::numeric, 0),
          2
        )
        WHEN 'MILEAGE' THEN ROUND(
          COALESCE(row_segment_contract.mileage_charge_ex_vat, 0)
          - COALESCE(NULLIF(row_segment_contract.expense_baseline_json #>> '{expenses,mileage_charge_ex_vat}', '')::numeric, 0),
          2
        )
        ELSE NULL::numeric
      END AS expense_source_charge_ex_vat
    FROM row_segment_contract
  ), expense_identity AS (
    SELECT
      expense_identity_base.*,
      CASE
        WHEN expense_identity_base.key_type = 'EXPENSE_CODE'
         AND UPPER(expense_identity_base.key_value) IN ('EXPENSES', 'TRAVEL', 'ACCOMMODATION', 'OTHER', 'MILEAGE')
        THEN jsonb_strip_nulls(jsonb_build_object(
          'timesheet_id', expense_identity_base.canonical_timesheet_id::text,
          'expense_code', UPPER(expense_identity_base.key_value),
          'source_charge_ex_vat', expense_identity_base.expense_source_charge_ex_vat,
          'source_pay_ex_vat', ROUND(COALESCE(expense_identity_base.outstanding_ex_vat, 0), 2)
        ))
        ELSE NULL::jsonb
      END AS expense_source_basis_json
    FROM expense_identity_base
  ), expense_identity_final AS (
    SELECT
      expense_identity.*,
      CASE
        WHEN expense_identity.expense_source_basis_json IS NOT NULL
          THEN MD5(expense_identity.expense_source_basis_json::text)
        ELSE NULL::text
      END AS expense_source_basis_fingerprint,
      CASE
        WHEN expense_identity.expense_source_basis_json IS NOT NULL
          THEN LOWER(
            'timesheet-expense:' || expense_identity.canonical_timesheet_id::text || ':' ||
            UPPER(expense_identity.key_value) || ':' || MD5(expense_identity.expense_source_basis_json::text)
          )
        ELSE NULL::text
      END AS expense_source_ref
    FROM expense_identity
  ), line_json_rows AS (
    SELECT
      row_identity.*,
      (jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE) AS row_is_ready,
      CASE
        WHEN jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE THEN 'canonical_preview_lines'
        ELSE 'blocked_for_pay'
      END AS target_section,
      CASE
        WHEN jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE THEN 'READY_TO_PAY'
        ELSE 'BLOCKED_FOR_PAY'
      END AS presentation_section,
      jsonb_strip_nulls(
        jsonb_build_object(
          'projection_path', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
          'projection_run_id', p_projection_run_id::text,
          'projection_class', v_projection_class,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'candidate_id', p_candidate_id::text,
          'timesheet_id', CASE
            WHEN row_identity.key_type = 'EXPENSE_CODE' THEN row_identity.canonical_timesheet_id::text
            ELSE row_identity.timesheet_id::text
          END,
          'real_business_timesheet_id', CASE
            WHEN row_identity.key_type = 'EXPENSE_CODE' THEN row_identity.canonical_timesheet_id::text
            ELSE row_identity.timesheet_id::text
          END,
          'canonical_timesheet_id', row_identity.canonical_timesheet_id::text,
          'booking_id', row_identity.booking_id,
          'line_key', row_identity.line_key,
          'row_key', row_identity.row_key,
          'preview_row_id', row_identity.row_key,
          'line_id', row_identity.line_key,
          'presentation_line_id', row_identity.line_key,
          'presentation_parent_line_id', CASE
            WHEN row_identity.key_type = 'EXPENSE_CODE' THEN row_identity.canonical_timesheet_id::text
            ELSE row_identity.line_key
          END,
          'presentation_role', 'PARENT',
          'source_kind', 'VALID_PREVIEW_LINE',
          'line_type', 'TIMESHEET_PAYMENT',
          'row_key_line_key_parity_proven', COALESCE(v_key_parity_proven, false),
          'economic_key_parity_proven', COALESCE(v_economic_key_parity_proven, false),
          'projection_certified', COALESCE(v_key_parity_proven, false),
          'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false)
        )
        || jsonb_build_object(
          'item_type', CASE
            WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
            WHEN row_identity.key_type = 'EXPENSE_CODE' AND UPPER(row_identity.key_value) = 'MILEAGE' THEN 'MILEAGE_DELTA'
            WHEN row_identity.key_type IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
            ELSE 'ADJUSTMENT_DELTA'
          END,
          'component_key_type', row_identity.key_type,
          'component_key_value', row_identity.key_value,
          'key_type', row_identity.key_type,
          'key_value', row_identity.key_value,
          'amount_ex_vat', row_identity.outstanding_ex_vat,
          'preview_amount_ex_vat', row_identity.outstanding_ex_vat,
          'section_amount_ex_vat', row_identity.outstanding_ex_vat,
          'amount_inc_vat', row_identity.outstanding_inc_vat,
          'vat_amount', ROUND(row_identity.outstanding_inc_vat - row_identity.outstanding_ex_vat, 2),
          'pay_channel', CASE WHEN row_identity.effective_pay_method = 'PAYE' THEN 'PAYE' ELSE 'UMBRELLA' END,
          'pay_channel_scope', v_pay_channel_scope,
          'presentation_section', CASE WHEN jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE THEN 'READY_TO_PAY' ELSE 'BLOCKED_FOR_PAY' END,
          'target_section', CASE WHEN jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE THEN 'canonical_preview_lines' ELSE 'blocked_for_pay' END,
          'section', CASE WHEN jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE THEN 'canonical_preview_lines' ELSE 'blocked_for_pay' END,
          'draftable', (jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE),
          'is_ready_for_draft', (jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE),
          'selection_allowed', (jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE),
          'readiness_state', CASE WHEN jsonb_array_length(row_identity.blocked_reason_codes) = 0 AND row_identity.suppress_zero_or_negative_outstanding IS NOT TRUE THEN 'READY_TO_PAY' ELSE 'BLOCKED_FOR_PAY' END,
          'blocked_reason_codes', row_identity.blocked_reason_codes,
          'display_name', row_identity.candidate_display_name,
          'candidate_display_name', row_identity.candidate_display_name,
          'candidate_name', row_identity.candidate_display_name,
          'candidate_tms_ref', row_identity.candidate_tms_ref,
          'tms_ref', row_identity.candidate_tms_ref,
          'client_id', CASE WHEN row_identity.client_id IS NULL THEN NULL ELSE row_identity.client_id::text END,
          'client_name', row_identity.client_name,
          'week_ending_date', CASE WHEN row_identity.week_ending_date IS NULL THEN NULL ELSE row_identity.week_ending_date::text END,
          'contract_id', CASE WHEN row_identity.contract_id IS NULL THEN NULL ELSE row_identity.contract_id::text END,
          'contract_week_id', CASE WHEN row_identity.contract_week_id IS NULL THEN NULL ELSE row_identity.contract_week_id::text END,
          'role', row_identity.role,
          'job_title', row_identity.role,
          'band', row_identity.band,
          'display_site', row_identity.display_site,
          'ward_hint', row_identity.ward_hint,
          'reference_number', row_identity.reference_number,
          'paye_treatment', CASE WHEN row_identity.effective_pay_method = 'PAYE' THEN 'GROSS_ADD' ELSE 'NONE' END,
          'source_function', 'pay_workbench_project_changed_timesheets_v1',
          'live_pay_eligibility_proven', true,
          'live_pay_eligibility_status', 'ELIGIBLE'
        )
        || jsonb_build_object(
          'date', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.row_work_date_text ELSE NULL::text END,
          'work_date', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.row_work_date_text ELSE NULL::text END,
          'linked_shift_date', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.row_work_date_text ELSE NULL::text END,
          'start', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.first_segment_json->>'start' ELSE NULL::text END,
          'start_time', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.first_segment_json->>'start_time' ELSE NULL::text END,
          'finish', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.first_segment_json->>'finish' ELSE NULL::text END,
          'finish_time', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.first_segment_json->>'finish_time' ELSE NULL::text END,
          'break_start', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.first_segment_json->>'break_start' ELSE NULL::text END,
          'break_end', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.first_segment_json->>'break_end' ELSE NULL::text END,
          'break_mins', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.first_segment_json->>'break_mins' ELSE NULL::text END,
          'break_minutes', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN row_identity.first_segment_json->>'break_minutes' ELSE NULL::text END,
          'breaks', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') AND jsonb_typeof(row_identity.first_segment_json->'breaks') = 'array' THEN row_identity.first_segment_json->'breaks' ELSE NULL::jsonb END,
          'section_segment_rows', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN COALESCE(row_identity.row_segment_rows_json, '[]'::jsonb) ELSE '[]'::jsonb END,
          'segment_rows', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN COALESCE(row_identity.row_segment_rows_json, '[]'::jsonb) ELSE '[]'::jsonb END,
          'section_segment_count', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN COALESCE(row_identity.row_segment_count, 0) ELSE 0 END,
          'segment_count', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN COALESCE(row_identity.row_segment_count, 0) ELSE 0 END
        )
        || jsonb_build_object(
          'total_segment_count', COALESCE(row_identity.timesheet_segment_count, 0),
          'ready_segment_count', COALESCE(row_identity.row_segment_count, 0),
          'blocked_visible_segment_count', 0,
          'hidden_indefinite_segment_count', 0,
          'is_partially_ready', false,
          'is_partially_blocked', false,
          'section_non_segment_amount_ex_vat', CASE WHEN row_identity.key_type IN ('TS_DAY', 'TS_TOTAL') THEN 0::numeric ELSE row_identity.outstanding_ex_vat END,
          'resolved_segment_rows_replace_source_total', false,
          'has_active_timesheet_snooze', false,
          'has_active_segment_snoozes', false,
          'active_segment_snooze_count', 0,
          'active_segment_dated_snooze_count', 0,
          'active_segment_indefinite_snooze_count', 0,
          'whole_timesheet_snooze_action_blocked', false,
          'segment_snooze_action_blocked', false,
          'source_ref', CASE WHEN row_identity.key_type = 'EXPENSE_CODE' THEN row_identity.expense_source_ref ELSE NULL::text END,
          'expense_code', CASE WHEN row_identity.key_type = 'EXPENSE_CODE' THEN UPPER(row_identity.key_value) ELSE NULL::text END,
          'expense_label', CASE UPPER(row_identity.key_value)
            WHEN 'EXPENSES' THEN 'Expenses'
            WHEN 'TRAVEL' THEN 'Travel'
            WHEN 'ACCOMMODATION' THEN 'Accommodation'
            WHEN 'OTHER' THEN 'Other'
            WHEN 'MILEAGE' THEN 'Mileage'
            ELSE NULL::text
          END,
          'expense_source_basis_json', CASE WHEN row_identity.key_type = 'EXPENSE_CODE' THEN row_identity.expense_source_basis_json ELSE NULL::jsonb END,
          'expense_source_basis_fingerprint', CASE WHEN row_identity.key_type = 'EXPENSE_CODE' THEN row_identity.expense_source_basis_fingerprint ELSE NULL::text END,
          'source_basis_fingerprint', CASE WHEN row_identity.key_type = 'EXPENSE_CODE' THEN row_identity.expense_source_basis_fingerprint ELSE NULL::text END,
          'snooze_identity', CASE
            WHEN row_identity.key_type = 'EXPENSE_CODE' THEN jsonb_strip_nulls(jsonb_build_object(
              'identity_type', 'TIMESHEET_EXPENSE',
              'candidate_id', p_candidate_id::text,
              'timesheet_id', row_identity.canonical_timesheet_id::text,
              'booking_id', row_identity.booking_id,
              'segment_id', NULL,
              'segment_stable_key', NULL,
              'source_ref', row_identity.expense_source_ref,
              'expense_code', UPPER(row_identity.key_value),
              'source_basis_fingerprint', row_identity.expense_source_basis_fingerprint
            ))
            ELSE jsonb_strip_nulls(jsonb_build_object(
              'identity_type', 'TIMESHEET',
              'candidate_id', p_candidate_id::text,
              'timesheet_id', row_identity.timesheet_id::text,
              'booking_id', row_identity.booking_id
            ))
          END,
          'snooze_state', 'NONE'
        )
        || jsonb_build_object(
          'economic_key', jsonb_build_object(
            'timesheet_id', CASE
              WHEN row_identity.key_type = 'EXPENSE_CODE' THEN row_identity.canonical_timesheet_id::text
              ELSE row_identity.timesheet_id::text
            END,
            'key_type', row_identity.key_type,
            'key_value', row_identity.key_value
          ),
          'source_basis_json', CASE
            WHEN row_identity.key_type = 'EXPENSE_CODE' THEN row_identity.expense_source_basis_json
            ELSE jsonb_build_object(
              'timesheet_id', row_identity.timesheet_id::text,
              'component_key_type', row_identity.key_type,
              'component_key_value', row_identity.key_value,
              'source_pay_ex_vat', row_identity.truth_ex_vat,
              'pay_amount_ex_vat', row_identity.outstanding_ex_vat,
              'live_truth_used', true,
              'live_pay_eligibility_proven', true,
              'live_pay_eligibility_status', 'ELIGIBLE',
              'financial_processing_status', row_identity.financial_processing_status,
              'authorised_at_server', CASE WHEN row_identity.authorised_at_server IS NULL THEN NULL ELSE row_identity.authorised_at_server::text END,
              'financial_authorised_at_utc', CASE WHEN row_identity.financial_authorised_at_utc IS NULL THEN NULL ELSE row_identity.financial_authorised_at_utc::text END
            )
          END,
          'live_pay_eligibility', jsonb_build_object(
            'proven', true,
            'status', 'ELIGIBLE',
            'gate', 'STRICT_READY_FOR_INVOICE_AUTHORISED',
            'authorised_at_server_present', row_identity.authorised_at_server IS NOT NULL,
            'financial_authorised_at_utc_present', row_identity.financial_authorised_at_utc IS NOT NULL,
            'financial_processing_status', row_identity.financial_processing_status,
            'pay_on_hold', row_identity.pay_on_hold,
            'has_rate_issue', row_identity.has_rate_issue,
            'has_pay_channel_issue', row_identity.has_pay_channel_issue
          ),
          'outstanding_state_json', jsonb_build_object(
            'truth_ex_vat', row_identity.truth_ex_vat,
            'reserved_ex_vat', row_identity.reserved_ex_vat,
            'outstanding_ex_vat', row_identity.outstanding_ex_vat,
            'reservation_overrun_detected', row_identity.reservation_overrun_detected
          ),
          'payee_context', jsonb_build_object(
            'payee_entity_kind', row_identity.payee_entity_kind,
            'payee_entity_id', CASE WHEN row_identity.payee_entity_id IS NULL THEN NULL ELSE row_identity.payee_entity_id::text END,
            'payee_bank_hash', row_identity.payee_bank_hash,
            'name_check_status', row_identity.name_check_status,
            'name_check_has_override', row_identity.name_check_has_override,
            'payee_map_present', row_identity.payee_map_present
          )
        )
      ) AS line_json
    FROM expense_identity_final AS row_identity
  ), economic_checked AS (
    SELECT
      line_json_rows.*,
      policy_key.timesheet_id AS policy_timesheet_id,
      policy_key.key_type AS policy_key_type,
      policy_key.key_value AS policy_key_value,
      policy_key.key_resolution_failure_reason,
      public.pay_workbench_preview_line_economic_key(
        line_json_rows.line_json,
        CASE
          WHEN line_json_rows.key_type = 'EXPENSE_CODE' THEN line_json_rows.canonical_timesheet_id
          ELSE line_json_rows.timesheet_id
        END,
        CASE
          WHEN line_json_rows.key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
          WHEN line_json_rows.key_type = 'EXPENSE_CODE' AND UPPER(line_json_rows.key_value) = 'MILEAGE' THEN 'MILEAGE_DELTA'
          WHEN line_json_rows.key_type IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
          ELSE 'ADJUSTMENT_DELTA'
        END,
        '{}'::jsonb,
        line_json_rows.key_type,
        line_json_rows.key_value
      ) AS workbench_economic_key_json
    FROM line_json_rows
    LEFT JOIN LATERAL public._pay_policy_x_resolve_pre_draft_economic_key(
      p_timesheet_id => CASE
        WHEN line_json_rows.key_type = 'EXPENSE_CODE' THEN line_json_rows.canonical_timesheet_id
        ELSE line_json_rows.timesheet_id
      END,
      p_live_source_json => line_json_rows.line_json,
      p_item_type => CASE
        WHEN line_json_rows.key_type IN ('TS_DAY', 'TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN line_json_rows.key_type = 'EXPENSE_CODE' AND UPPER(line_json_rows.key_value) = 'MILEAGE' THEN 'MILEAGE_DELTA'
        WHEN line_json_rows.key_type IN ('EXPENSE_CODE', 'ADDITIONAL_CODE') THEN 'EXPENSE_DELTA'
        ELSE 'ADJUSTMENT_DELTA'
      END,
      p_key_type_hint => line_json_rows.key_type,
      p_key_value_hint => line_json_rows.key_value,
      p_work_date => CASE WHEN line_json_rows.key_type = 'TS_DAY' AND line_json_rows.key_value ~ '^\d{4}-\d{2}-\d{2}$' THEN line_json_rows.key_value::date ELSE NULL::date END
    ) AS policy_key ON true
  ), contracted AS (
    SELECT
      economic_checked.*,
      jsonb_build_object(
        'timesheet_id', CASE
          WHEN economic_checked.key_type = 'EXPENSE_CODE' THEN economic_checked.canonical_timesheet_id::text
          ELSE economic_checked.timesheet_id::text
        END,
        'key_type', economic_checked.key_type,
        'key_value', economic_checked.key_value,
        'key_resolution_source', economic_checked.workbench_economic_key_json->>'key_resolution_source',
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      ) AS economic_key_json,
      public.pay_workbench_preview_line_contract_ok(
        economic_checked.line_json,
        jsonb_build_object(
          'timesheet_id', CASE
            WHEN economic_checked.key_type = 'EXPENSE_CODE' THEN economic_checked.canonical_timesheet_id::text
            ELSE economic_checked.timesheet_id::text
          END,
          'key_type', economic_checked.key_type,
          'key_value', economic_checked.key_value
        ),
        economic_checked.target_section
      ) AS contract_result_json
    FROM economic_checked
  )
  SELECT
    contracted.*,
    COALESCE((contracted.contract_result_json->>'ok')::boolean, false) AS contract_ok,
    COALESCE((contracted.contract_result_json->>'materialisable')::boolean, false) AS materialisable,
    (
      contracted.key_resolution_failure_reason IS NOT NULL
      OR COALESCE((contracted.workbench_economic_key_json->>'ok')::boolean, false) IS NOT TRUE
      OR contracted.policy_key_type IS DISTINCT FROM contracted.key_type
      OR contracted.policy_key_value IS DISTINCT FROM contracted.key_value
      OR contracted.workbench_economic_key_json->>'key_type' IS DISTINCT FROM contracted.key_type
      OR contracted.workbench_economic_key_json->>'key_value' IS DISTINCT FROM contracted.key_value
    ) AS has_economic_key_failure
  FROM contracted;

  SELECT EXISTS (
    SELECT 1
    FROM pg_temp._bpay_delta_project_stage AS stage_rows
    WHERE COALESCE(stage_rows.reservation_overrun_detected, false) IS TRUE
  )
  INTO v_has_reservation_overrun;

  SELECT EXISTS (
    SELECT 1
    FROM pg_temp._bpay_delta_project_stage AS stage_rows
    WHERE COALESCE(stage_rows.has_economic_key_failure, false) IS TRUE
  )
  INTO v_has_policy_key_failure;

  SELECT EXISTS (
    SELECT 1
    FROM pg_temp._bpay_delta_project_stage AS stage_rows
    WHERE stage_rows.suppress_zero_or_negative_outstanding IS NOT TRUE
      AND COALESCE(stage_rows.contract_ok, false) IS NOT TRUE
  )
  INTO v_has_contract_failure;

  IF v_has_reservation_overrun IS TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'RESERVATION_OVERRUN_DETECTED_DURING_PROJECTION',
      'projected_row_count', 0
    );
  END IF;

  IF v_has_policy_key_failure IS TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'POLICY_X_ECONOMIC_KEY_MISMATCH_DURING_PROJECTION',
      'projected_row_count', 0
    );
  END IF;

  IF v_has_contract_failure IS TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'fallback_required', true,
      'fallback_reason', 'PREVIEW_CONTRACT_MISMATCH_DURING_PROJECTION',
      'projected_row_count', 0
    );
  END IF;

  SELECT COUNT(*)::integer
  INTO v_total_stage_row_count
  FROM pg_temp._bpay_delta_project_stage AS stage_rows
  WHERE stage_rows.suppress_zero_or_negative_outstanding IS NOT TRUE;

  DROP TABLE IF EXISTS pg_temp._bpay_delta_project_stage_chunk;
  CREATE TEMP TABLE _bpay_delta_project_stage_chunk ON COMMIT DROP AS
  SELECT numbered_stage_rows.*
  FROM (
    SELECT
      stage_rows.*,
      ROW_NUMBER() OVER (ORDER BY stage_rows.timesheet_id, stage_rows.key_type, stage_rows.key_value) AS component_index
    FROM pg_temp._bpay_delta_project_stage AS stage_rows
    WHERE stage_rows.suppress_zero_or_negative_outstanding IS NOT TRUE
  ) AS numbered_stage_rows
  WHERE numbered_stage_rows.component_index > COALESCE(v_component_offset, 0)
    AND numbered_stage_rows.component_index <= COALESCE(v_component_offset, 0) + COALESCE(v_limit, 25);

  INSERT INTO pg_temp._bpay_delta_projection_rows (
    projection_run_id,
    session_id,
    candidate_id,
    session_version,
    source_change_seq,
    timesheet_id,
    canonical_timesheet_id,
    section,
    line_key,
    row_key,
    parent_line_key,
    split_suffix,
    source_ordinal,
    row_ordinal,
    pay_channel_scope,
    refresh_scope_kind,
    key_type,
    key_value,
    amount_ex_vat,
    amount_inc_vat,
    vat_amount,
    draftable,
    is_ready_for_draft,
    selection_allowed,
    readiness_state,
    blocked_reason_codes,
    outstanding_state_json,
    source_row_json,
    economic_key_json,
    contract_json,
    work_payload_json,
    result_row_json,
    preview_row_json,
    contract_ok,
    materialisable
  )
  SELECT
    p_projection_run_id,
    p_session_id,
    p_candidate_id,
    v_session_version,
    v_source_change_seq,
    CASE
      WHEN stage_rows.key_type = 'EXPENSE_CODE' THEN stage_rows.canonical_timesheet_id
      ELSE stage_rows.timesheet_id
    END,
    stage_rows.canonical_timesheet_id,
    stage_rows.target_section,
    stage_rows.line_key,
    stage_rows.row_key,
    CASE
      WHEN stage_rows.key_type = 'EXPENSE_CODE' THEN stage_rows.canonical_timesheet_id::text
      ELSE stage_rows.line_key
    END,
    CASE
      WHEN stage_rows.key_type = 'EXPENSE_CODE' THEN 'component:expense:' || md5(stage_rows.key_value)
      ELSE stage_rows.key_type || ':' || md5(stage_rows.key_value)
    END,
    (COALESCE(v_scope_row.scope_ordinal, 0) * 1000000 + COALESCE(stage_rows.component_index, 0))::bigint,
    (COALESCE(v_scope_row.scope_ordinal, 0) * 1000000 + COALESCE(stage_rows.component_index, 0))::bigint,
    v_pay_channel_scope,
    'TARGETED_TIMESHEETS',
    stage_rows.key_type,
    stage_rows.key_value,
    stage_rows.outstanding_ex_vat,
    stage_rows.outstanding_inc_vat,
    ROUND(stage_rows.outstanding_inc_vat - stage_rows.outstanding_ex_vat, 2),
    stage_rows.row_is_ready,
    stage_rows.row_is_ready,
    stage_rows.row_is_ready,
    CASE WHEN stage_rows.row_is_ready THEN 'READY_TO_PAY' ELSE 'BLOCKED_FOR_PAY' END,
    stage_rows.blocked_reason_codes,
    jsonb_build_object(
      'truth_ex_vat', stage_rows.truth_ex_vat,
      'reserved_ex_vat', stage_rows.reserved_ex_vat,
      'outstanding_ex_vat', stage_rows.outstanding_ex_vat,
      'reservation_overrun_detected', stage_rows.reservation_overrun_detected
    ),
    stage_rows.line_json,
    stage_rows.economic_key_json,
    jsonb_build_object(
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'economic_identity', jsonb_build_object(
        'timesheet_id', stage_rows.timesheet_id::text,
        'key_type', stage_rows.key_type,
        'key_value', stage_rows.key_value
      ),
      'projection_certified', COALESCE(v_key_parity_proven, false),
      'projection_run_id', p_projection_run_id::text,
      'row_key_line_key_parity_proven', COALESCE(v_key_parity_proven, false),
      'economic_key_parity_proven', COALESCE(v_economic_key_parity_proven, false),
      'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false),
      'live_pay_eligibility_proven', true,
      'live_pay_eligibility_status', 'ELIGIBLE',
      'preview_contract', stage_rows.contract_result_json
    ),
    jsonb_build_object(
      'projection_path', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
      'projection_run_id', p_projection_run_id::text,
      'source_row_json', stage_rows.line_json,
      'economic_key_json', stage_rows.economic_key_json,
      'contract_json', stage_rows.contract_result_json,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    stage_rows.line_json
      || jsonb_build_object(
        'projection_path', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', p_projection_run_id::text,
        'row_processing_status', CASE WHEN stage_rows.materialisable THEN 'MATERIALISED' ELSE 'SKIPPED' END,
        'economic_key', stage_rows.economic_key_json,
        'preview_contract', stage_rows.contract_result_json
      ),
    stage_rows.line_json
      || jsonb_build_object(
        'projection_path', 'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'projection_run_id', p_projection_run_id::text,
        'projection_certified', COALESCE(v_key_parity_proven, false),
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
        'row_key_line_key_parity_proven', COALESCE(v_key_parity_proven, false),
        'economic_key_parity_proven', COALESCE(v_economic_key_parity_proven, false),
        'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false),
        'target_selected', stage_rows.row_is_ready,
        'target_selection_state', CASE WHEN stage_rows.row_is_ready THEN 'SELECTED' ELSE 'NOT_SELECTABLE' END
      ),
    stage_rows.contract_ok,
    stage_rows.materialisable
  FROM pg_temp._bpay_delta_project_stage_chunk AS stage_rows;

  GET DIAGNOSTICS v_projected_row_count = ROW_COUNT;

  v_next_component_offset := COALESCE(v_component_offset, 0) + COALESCE(v_projected_row_count, 0);
  v_more_due := COALESCE(v_total_stage_row_count, 0) > COALESCE(v_next_component_offset, 0);

  SELECT COUNT(*)::integer
  INTO v_suppressed_row_count
  FROM pg_temp._bpay_delta_project_stage AS stage_rows
  WHERE stage_rows.suppress_zero_or_negative_outstanding IS TRUE;

  SELECT COUNT(*) FILTER (WHERE projection_rows.section = 'canonical_preview_lines')::integer,
         COUNT(*) FILTER (WHERE projection_rows.section <> 'canonical_preview_lines')::integer,
         COUNT(*) FILTER (WHERE projection_rows.draftable AND projection_rows.is_ready_for_draft AND projection_rows.selection_allowed)::integer
  INTO v_ready_row_count,
       v_blocked_row_count,
       v_selected_row_count
  FROM pg_temp._bpay_delta_projection_rows AS projection_rows
  WHERE projection_rows.projection_run_id = p_projection_run_id
    AND projection_rows.session_id = p_session_id
    AND projection_rows.candidate_id = p_candidate_id;

  SELECT COUNT(DISTINCT stage_chunk_rows.timesheet_id)::integer,
         COUNT(*)::integer
  INTO v_processed_timesheet_count,
       v_processed_component_count
  FROM pg_temp._bpay_delta_project_stage_chunk AS stage_chunk_rows;

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run_update
  SET projected_row_count = COALESCE(v_next_component_offset, 0),
      projection_fingerprint = md5(
        COALESCE(p_session_id::text, '') || ':' ||
        COALESCE(p_candidate_id::text, '') || ':' ||
        COALESCE(v_session_version::text, '') || ':' ||
        COALESCE(v_source_change_seq::text, '') || ':' ||
        COALESCE(array_to_string(v_all_affected_timesheet_ids, ','), '') || ':' ||
        COALESCE(v_total_stage_row_count::text, '0')
      ),
      updated_at_utc = v_now
  WHERE projection_run_update.id = p_projection_run_id
    AND projection_run_update.session_id = p_session_id
    AND projection_run_update.candidate_id = p_candidate_id;

  RETURN jsonb_build_object(
    'ok', true,
    'fallback_required', false,
    'projection_run_id', p_projection_run_id::text,
    'projection_mode', v_projection_mode,
    'projection_class', v_projection_class,
    'projected_row_count', COALESCE(v_projected_row_count, 0),
    'processed_timesheet_count', COALESCE(v_processed_timesheet_count, 0),
    'processed_component_count', COALESCE(v_processed_component_count, 0),
    'suppressed_row_count', COALESCE(v_suppressed_row_count, 0),
    'ready_row_count', COALESCE(v_ready_row_count, 0),
    'blocked_row_count', COALESCE(v_blocked_row_count, 0),
    'selected_row_count', COALESCE(v_selected_row_count, 0),
    'targeted_timesheet_count', v_targeted_count,
    'affected_timesheet_count', v_affected_count,
    'live_pay_eligible_timesheet_count', COALESCE(v_live_eligible_timesheet_count, 0),
    'live_pay_ineligible_timesheet_count', COALESCE(v_live_ineligible_timesheet_count, 0),
    'component_offset', COALESCE(v_component_offset, 0),
    'next_component_offset', COALESCE(v_next_component_offset, 0),
    'total_projectable_row_count', COALESCE(v_total_stage_row_count, 0),
    'more_due', COALESCE(v_more_due, false),
    'has_more', COALESCE(v_more_due, false),
    'next_cursor_json', jsonb_build_object(
      'family_index', COALESCE(v_current_family_index, 0),
      'current_family_index', COALESCE(v_current_family_index, 0),
      'timesheet_id', CASE WHEN COALESCE(array_length(v_all_affected_timesheet_ids, 1), 0) = 0 THEN NULL ELSE v_all_affected_timesheet_ids[LEAST(GREATEST(COALESCE(v_next_component_offset, 0), 1), COALESCE(array_length(v_all_affected_timesheet_ids, 1), 1))]::text END,
      'current_timesheet_id', CASE WHEN COALESCE(array_length(v_all_affected_timesheet_ids, 1), 0) = 0 THEN NULL ELSE v_all_affected_timesheet_ids[LEAST(GREATEST(COALESCE(v_next_component_offset, 0), 1), COALESCE(array_length(v_all_affected_timesheet_ids, 1), 1))]::text END,
      'component_offset', COALESCE(v_next_component_offset, 0),
      'row_ordinal_offset', COALESCE(v_next_component_offset, 0)
    ),
    'row_key_line_key_parity_proven', COALESCE(v_key_parity_proven, false),
    'economic_key_parity_proven', COALESCE(v_economic_key_parity_proven, false),
    'shadow_compare_enforced', COALESCE(v_shadow_compare_enforced, false),
    'complexity_flags', v_complexity_flags
  );
END;
$function$;

-- pay_workbench_projection_lifecycle_repair(uuid,uuid,integer,integer,text)
CREATE OR REPLACE FUNCTION public.pay_workbench_projection_lifecycle_repair(p_session_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_safe_age_seconds integer DEFAULT 300, p_limit integer DEFAULT 100, p_reason text DEFAULT 'CLOSED_BY_PROJECTION_LIFECYCLE_REPAIR'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_safe_age_seconds integer := GREATEST(COALESCE(p_safe_age_seconds, 300), 0);
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 100), 1000));
  v_min_source_change_seq bigint := '-9223372036854775808'::bigint;
  v_repaired_rows jsonb := '[]'::jsonb;
  v_repaired_count integer := 0;
BEGIN
  WITH repair_candidates AS (
    SELECT
      running_run.id,
      running_run.session_id,
      running_run.candidate_id,
      running_run.session_version,
      running_run.source_change_seq,
      running_run.phase,
      running_run.write_phase,
      running_run.status,
      running_run.updated_at_utc,
      running_run.completed_at_utc,
      newer_terminal.id AS newer_terminal_projection_run_id,
      newer_terminal.source_change_seq AS newer_terminal_source_change_seq,
      newer_terminal.status AS newer_terminal_status,
      CASE
        WHEN newer_terminal.id IS NOT NULL THEN 'SUPERSEDED_BY_NEWER_SOURCE_CHANGE_SEQ'
        ELSE 'STALE_RUNNING_NO_ACTIVE_JOB'
      END AS cleanup_reason
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS running_run
    LEFT JOIN LATERAL (
      SELECT later_run.id,
             later_run.source_change_seq,
             later_run.status,
             later_run.completed_at_utc,
             later_run.updated_at_utc
      FROM public.banking_pay_workbench_candidate_delta_projection_runs AS later_run
      WHERE later_run.session_id = running_run.session_id
        AND later_run.candidate_id = running_run.candidate_id
        AND later_run.session_version = running_run.session_version
        AND COALESCE(later_run.source_change_seq, v_min_source_change_seq)
          > COALESCE(running_run.source_change_seq, v_min_source_change_seq)
        AND UPPER(BTRIM(COALESCE(later_run.status, ''))) IN ('COMPLETED', 'FAILED', 'FALLBACK_REQUIRED', 'BLOCKED')
      ORDER BY COALESCE(later_run.source_change_seq, v_min_source_change_seq) DESC,
               later_run.completed_at_utc DESC NULLS LAST,
               later_run.updated_at_utc DESC NULLS LAST,
               later_run.id DESC
      LIMIT 1
    ) AS newer_terminal ON true
    WHERE UPPER(BTRIM(COALESCE(running_run.status, ''))) = 'RUNNING'
      AND (p_session_id IS NULL OR running_run.session_id = p_session_id)
      AND (p_candidate_id IS NULL OR running_run.candidate_id = p_candidate_id)
      AND COALESCE(running_run.updated_at_utc, running_run.started_at_utc, v_now) <= v_now - make_interval(secs => v_safe_age_seconds)
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_jobs AS active_projection_job
        WHERE active_projection_job.payload_json->>'projection_run_id' = running_run.id::text
          AND UPPER(BTRIM(COALESCE(active_projection_job.status, ''))) IN ('QUEUED', 'RUNNING')
      )
    ORDER BY running_run.updated_at_utc ASC NULLS FIRST,
             running_run.started_at_utc ASC NULLS FIRST,
             running_run.id ASC
    LIMIT v_limit
    FOR UPDATE OF running_run SKIP LOCKED
  ), repaired AS (
    UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS run_update
    SET status = 'FAILED',
        fallback_required = COALESCE(run_update.fallback_required, false),
        fallback_reason = COALESCE(NULLIF(BTRIM(run_update.fallback_reason), ''), repair_candidates.cleanup_reason),
        diagnostics_json = jsonb_strip_nulls(
          COALESCE(run_update.diagnostics_json, '{}'::jsonb)
          || jsonb_build_object(
            'projection_lifecycle_repair', true,
            'cleanup_reason', repair_candidates.cleanup_reason,
            'repair_reason', COALESCE(NULLIF(BTRIM(p_reason), ''), 'CLOSED_BY_PROJECTION_LIFECYCLE_REPAIR'),
            'repair_at_utc', v_now::text,
            'safe_age_seconds', v_safe_age_seconds,
            'previous_status', repair_candidates.status,
            'previous_phase', repair_candidates.phase,
            'previous_write_phase', repair_candidates.write_phase,
            'previous_updated_at_utc', repair_candidates.updated_at_utc::text,
            'previous_completed_at_utc', CASE WHEN repair_candidates.completed_at_utc IS NULL THEN NULL ELSE repair_candidates.completed_at_utc::text END,
            'stale_running_no_active_job', true,
            'no_active_continuation_job', true,
            'closed_by_projection_lifecycle_repair', true,
            'newer_terminal_projection_run_id', CASE WHEN repair_candidates.newer_terminal_projection_run_id IS NULL THEN NULL ELSE repair_candidates.newer_terminal_projection_run_id::text END,
            'newer_terminal_source_change_seq', repair_candidates.newer_terminal_source_change_seq,
            'newer_terminal_status', repair_candidates.newer_terminal_status
          )
        ),
        updated_at_utc = v_now,
        completed_at_utc = COALESCE(run_update.completed_at_utc, v_now)
    FROM repair_candidates
    WHERE run_update.id = repair_candidates.id
    RETURNING
      run_update.id,
      run_update.session_id,
      run_update.candidate_id,
      run_update.session_version,
      run_update.source_change_seq,
      repair_candidates.cleanup_reason,
      repair_candidates.newer_terminal_projection_run_id,
      repair_candidates.newer_terminal_source_change_seq
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(jsonb_build_object(
           'projection_run_id', repaired.id::text,
           'session_id', repaired.session_id::text,
           'candidate_id', repaired.candidate_id::text,
           'session_version', repaired.session_version,
           'source_change_seq', repaired.source_change_seq,
           'status', 'FAILED',
           'cleanup_reason', repaired.cleanup_reason,
           'newer_terminal_projection_run_id', CASE WHEN repaired.newer_terminal_projection_run_id IS NULL THEN NULL ELSE repaired.newer_terminal_projection_run_id::text END,
           'newer_terminal_source_change_seq', repaired.newer_terminal_source_change_seq
         ) ORDER BY repaired.source_change_seq NULLS FIRST, repaired.id), '[]'::jsonb)
  INTO v_repaired_count,
       v_repaired_rows
  FROM repaired;

  RETURN jsonb_build_object(
    'ok', true,
    'server_utc', v_now,
    'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'safe_age_seconds', v_safe_age_seconds,
    'limit', v_limit,
    'reason', COALESCE(NULLIF(BTRIM(p_reason), ''), 'CLOSED_BY_PROJECTION_LIFECYCLE_REPAIR'),
    'repaired_count', COALESCE(v_repaired_count, 0),
    'terminal_status', 'FAILED',
    'rows', COALESCE(v_repaired_rows, '[]'::jsonb)
  );
END;
$function$;

-- pay_workbench_reconcile_successful_source_build(uuid,uuid,uuid,bigint,bigint,uuid,text,jsonb,jsonb,boolean)
CREATE OR REPLACE FUNCTION public.pay_workbench_reconcile_successful_source_build(p_session_id uuid, p_candidate_id uuid, p_source_build_run_id uuid, p_source_change_seq bigint, p_session_version bigint DEFAULT NULL::bigint, p_success_job_id uuid DEFAULT NULL::uuid, p_refresh_scope_kind text DEFAULT NULL::text, p_targeted_timesheet_ids jsonb DEFAULT '[]'::jsonb, p_linked_timesheet_ids jsonb DEFAULT '[]'::jsonb, p_recompute_session_progress boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_session_version bigint := NULL::bigint;
  v_refresh_scope_kind text := NULL::text;
  v_current_source_row_count integer := 0;
  v_current_source_identity_count integer := 0;
  v_source_rows_superseded integer := 0;
  v_source_build_jobs_superseded integer := 0;
  v_scope_rows_repaired integer := 0;
  v_progress_json jsonb := '{}'::jsonb;
  v_counter_reconciled boolean := false;
  v_progress_state text := NULL::text;
  v_section_counts_json jsonb := '{}'::jsonb;
  v_candidate_sample_rows_json jsonb := '[]'::jsonb;
  v_session_progress_lock_acquired boolean := false;
  v_reconciliation_deferred boolean := false;
  v_reconciliation_deferred_reason text := NULL::text;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  IF p_source_build_run_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_RUN_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_RUN_ID_REQUIRED')::text;
  END IF;

  IF p_source_change_seq IS NULL OR p_source_change_seq < 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SEQ_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SEQ_REQUIRED')::text;
  END IF;

  IF to_regclass('public.banking_pay_workbench_candidate_source_lines') IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'SOURCE_LINES_TABLE_MISSING',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq
    );
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECONCILE_SOURCE_BUILD_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  v_session_version := COALESCE(p_session_version, v_session_row.version);
  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(p_refresh_scope_kind, ''))), '');

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets;
  CREATE TEMPORARY TABLE pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets ON COMMIT DROP AS
    SELECT DISTINCT scope_ids.timesheet_id
    FROM (
      SELECT NULLIF(BTRIM(target_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p_targeted_timesheet_ids, '[]'::jsonb)) = 'array'
            THEN COALESCE(p_targeted_timesheet_ids, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS target_values(value)
      WHERE NULLIF(BTRIM(target_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'

      UNION

      SELECT NULLIF(BTRIM(linked_values.value), '')::uuid AS timesheet_id
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(COALESCE(p_linked_timesheet_ids, '[]'::jsonb)) = 'array'
            THEN COALESCE(p_linked_timesheet_ids, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS linked_values(value)
      WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS scope_ids
    WHERE scope_ids.timesheet_id IS NOT NULL;

  SELECT COUNT(*)::integer,
         COUNT(DISTINCT jsonb_build_object(
           'timesheet_id', COALESCE(current_source.timesheet_id::text, '00000000-0000-0000-0000-000000000000'),
           'line_key', current_source.line_key,
           'parent_line_key', COALESCE(current_source.parent_line_key, ''),
           'split_suffix', COALESCE(current_source.split_suffix, ''),
           'section', COALESCE(current_source.section, '')
         ))::integer
  INTO v_current_source_row_count,
       v_current_source_identity_count
  FROM public.banking_pay_workbench_candidate_source_lines AS current_source
  WHERE current_source.session_id = p_session_id
    AND current_source.candidate_id = p_candidate_id
    AND current_source.session_version = v_session_version
    AND current_source.source_build_run_id = p_source_build_run_id
    AND current_source.source_change_seq = p_source_change_seq
    AND current_source.status = 'CURRENT';

  IF COALESCE(v_current_source_row_count, 0) <= 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'SUCCESSFUL_SOURCE_BUILD_HAS_NO_CURRENT_SOURCE_ROWS',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq,
      'source_rows_superseded', 0,
      'source_build_jobs_superseded', 0,
      'scope_rows_repaired', 0,
      'deferred', false,
      'progress_recomputed', false,
      'counter_reconciled', false,
      'retry_safe', true
    );
  END IF;

  WITH current_identity AS (
    SELECT DISTINCT
      current_source.timesheet_id,
      current_source.line_key,
      current_source.parent_line_key,
      current_source.split_suffix,
      current_source.section
    FROM public.banking_pay_workbench_candidate_source_lines AS current_source
    WHERE current_source.session_id = p_session_id
      AND current_source.candidate_id = p_candidate_id
      AND current_source.session_version = v_session_version
      AND current_source.source_build_run_id = p_source_build_run_id
      AND current_source.source_change_seq = p_source_change_seq
      AND current_source.status = 'CURRENT'
  ), source_rows_to_supersede AS (
    SELECT older_source.id,
           older_source.status AS previous_status
    FROM public.banking_pay_workbench_candidate_source_lines AS older_source
    JOIN current_identity AS current_source
      ON COALESCE(older_source.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)
           = COALESCE(current_source.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)
     AND older_source.line_key = current_source.line_key
     AND COALESCE(older_source.parent_line_key, '') = COALESCE(current_source.parent_line_key, '')
     AND COALESCE(older_source.split_suffix, '') = COALESCE(current_source.split_suffix, '')
     AND COALESCE(older_source.section, '') = COALESCE(current_source.section, '')
    WHERE older_source.session_id = p_session_id
      AND older_source.candidate_id = p_candidate_id
      AND older_source.session_version = v_session_version
      AND older_source.source_change_seq < p_source_change_seq
      AND UPPER(BTRIM(COALESCE(older_source.status, ''))) IN ('CURRENT', 'DIRTY', 'ERROR')
      AND (
        v_refresh_scope_kind IS DISTINCT FROM 'TARGETED_TIMESHEETS'
        OR older_source.timesheet_id IS NULL
        OR older_source.timesheet_id IN (
          SELECT scoped_timesheets.timesheet_id
          FROM pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets AS scoped_timesheets
        )
        OR NOT EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets AS any_scoped_timesheets
        )
      )
  )
  UPDATE public.banking_pay_workbench_candidate_source_lines AS update_source
  SET status = 'SUPERSEDED',
      source_row_json = jsonb_strip_nulls(
        COALESCE(update_source.source_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_at_utc', v_now::text,
          'superseded_reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
          'superseded_by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
          'superseded_by_source_build_run_id', p_source_build_run_id::text,
          'superseded_by_source_change_seq', p_source_change_seq,
          'superseded_by_session_version', v_session_version,
          'previous_status', source_rows_to_supersede.previous_status,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'source_build_supersession', jsonb_build_object(
            'reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
            'at_utc', v_now::text,
            'by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
            'by_source_build_run_id', p_source_build_run_id::text,
            'by_source_change_seq', p_source_change_seq,
            'by_session_version', v_session_version,
            'refresh_scope_kind', v_refresh_scope_kind
          )
        )
      ),
      updated_at_utc = v_now
  FROM source_rows_to_supersede
  WHERE update_source.id = source_rows_to_supersede.id;

  GET DIAGNOSTICS v_source_rows_superseded = ROW_COUNT;

  WITH successful_scope_timesheets AS (
    SELECT DISTINCT current_source.timesheet_id
    FROM public.banking_pay_workbench_candidate_source_lines AS current_source
    WHERE current_source.session_id = p_session_id
      AND current_source.candidate_id = p_candidate_id
      AND current_source.session_version = v_session_version
      AND current_source.source_build_run_id = p_source_build_run_id
      AND current_source.source_change_seq = p_source_change_seq
      AND current_source.status = 'CURRENT'
      AND current_source.timesheet_id IS NOT NULL

    UNION

    SELECT scoped_timesheets.timesheet_id
    FROM pg_temp._tmp_pay_wb_reconcile_success_scope_timesheets AS scoped_timesheets
  ), source_build_jobs_to_supersede AS (
    SELECT
      job_row.id,
      job_seq.job_source_change_seq,
      job_scope_kind.job_refresh_scope_kind,
      job_scope.scoped_timesheet_count,
      job_scope.success_scope_overlap_count
    FROM public.banking_pay_workbench_jobs AS job_row
    CROSS JOIN LATERAL (
      SELECT CASE
        WHEN COALESCE(job_row.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json->>'source_change_seq')::bigint
        WHEN COALESCE(job_row.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json->>'source_change_sequence')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{source_build,source_change_seq}')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{source_build,source_change_sequence}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{source_build,source_change_sequence}')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{result_json,source_change_seq}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{result_json,source_change_seq}')::bigint
        WHEN COALESCE(job_row.payload_json#>>'{completion_json,result_json,source_change_seq}', '') ~ '^[0-9]{1,18}$'
          THEN (job_row.payload_json#>>'{completion_json,result_json,source_change_seq}')::bigint
        ELSE NULL::bigint
      END AS job_source_change_seq
    ) AS job_seq
    CROSS JOIN LATERAL (
      SELECT NULLIF(UPPER(BTRIM(COALESCE(
        job_row.payload_json->>'refresh_scope_kind',
        job_row.payload_json#>>'{source_build,refresh_scope_kind}',
        job_row.payload_json#>>'{preview_decisions_json,refresh_scope_kind}',
        job_row.payload_json#>>'{result_json,refresh_scope_kind}',
        job_row.payload_json#>>'{completion_json,result_json,refresh_scope_kind}',
        ''
      ))), '') AS job_refresh_scope_kind
    ) AS job_scope_kind
    CROSS JOIN LATERAL (
      SELECT
        COUNT(*)::integer AS scoped_timesheet_count,
        COUNT(*) FILTER (
          WHERE job_scope_timesheet_ids.timesheet_id IN (
            SELECT successful_scope_timesheets.timesheet_id
            FROM successful_scope_timesheets
          )
        )::integer AS success_scope_overlap_count
      FROM (
        SELECT DISTINCT parsed_job_scope_values.timesheet_id_text::uuid AS timesheet_id
        FROM (
          SELECT NULLIF(BTRIM(target_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'targeted_timesheet_ids') = 'array' THEN job_row.payload_json->'targeted_timesheet_ids'
              ELSE '[]'::jsonb
            END
          ) AS target_values(value)

          UNION

          SELECT NULLIF(BTRIM(target_requested_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'targeted_timesheet_ids_requested') = 'array' THEN job_row.payload_json->'targeted_timesheet_ids_requested'
              ELSE '[]'::jsonb
            END
          ) AS target_requested_values(value)

          UNION

          SELECT NULLIF(BTRIM(source_target_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json#>'{source_build,targeted_timesheet_ids}') = 'array' THEN job_row.payload_json#>'{source_build,targeted_timesheet_ids}'
              ELSE '[]'::jsonb
            END
          ) AS source_target_values(value)

          UNION

          SELECT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'linked_timesheet_ids') = 'array' THEN job_row.payload_json->'linked_timesheet_ids'
              ELSE '[]'::jsonb
            END
          ) AS linked_values(value)

          UNION

          SELECT NULLIF(BTRIM(linked_requested_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json->'linked_timesheet_ids_requested') = 'array' THEN job_row.payload_json->'linked_timesheet_ids_requested'
              ELSE '[]'::jsonb
            END
          ) AS linked_requested_values(value)

          UNION

          SELECT NULLIF(BTRIM(source_linked_values.value), '') AS timesheet_id_text
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(job_row.payload_json#>'{source_build,linked_timesheet_ids}') = 'array' THEN job_row.payload_json#>'{source_build,linked_timesheet_ids}'
              ELSE '[]'::jsonb
            END
          ) AS source_linked_values(value)

          UNION

          SELECT NULLIF(BTRIM(COALESCE(
            job_row.payload_json->>'timesheet_id',
            job_row.payload_json->>'real_business_timesheet_id',
            job_row.payload_json#>>'{trigger,timesheet_id}',
            job_row.payload_json#>>'{source_build,timesheet_id}',
            job_row.payload_json#>>'{source_build,real_business_timesheet_id}',
            job_row.payload_json#>>'{result_json,timesheet_id}',
            ''
          )), '') AS timesheet_id_text
        ) AS parsed_job_scope_values
        WHERE parsed_job_scope_values.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS job_scope_timesheet_ids
    ) AS job_scope
    WHERE job_row.session_id = p_session_id
      AND job_row.candidate_id = p_candidate_id
      AND UPPER(BTRIM(COALESCE(job_row.status, ''))) IN ('FAILED', 'DEAD')
      AND CASE
            WHEN UPPER(BTRIM(COALESCE(job_row.job_type, ''))) IN (
              'WORKBENCH_CANDIDATE_SOURCE_BUILD',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
              'CANDIDATE_SOURCE_BUILD',
              'CANDIDATE_SOURCE_BUILD_CHUNK',
              'SOURCE_BUILD',
              'SOURCE_BUILD_PAGE'
            ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            ELSE UPPER(BTRIM(COALESCE(job_row.job_type, '')))
          END = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
      AND NOT (
        COALESCE(job_row.payload_json, '{}'::jsonb) ? 'superseded_by_newer_session_version_at_utc'
        OR COALESCE(job_row.payload_json, '{}'::jsonb) ? 'superseded_at_utc'
        OR UPPER(BTRIM(COALESCE(job_row.last_error_json->>'code', ''))) = 'WORKBENCH_JOB_SUPERSEDED_BY_NEWER_SESSION_VERSION'
      )
      AND (
        COALESCE(job_row.payload_json->>'session_version', '') !~ '^[0-9]{1,18}$'
        OR (job_row.payload_json->>'session_version')::bigint = v_session_version
      )
      AND job_seq.job_source_change_seq < p_source_change_seq
      AND (
        v_refresh_scope_kind IS DISTINCT FROM 'TARGETED_TIMESHEETS'
        OR COALESCE(job_scope.success_scope_overlap_count, 0) > 0
        OR (
          COALESCE(job_scope.scoped_timesheet_count, 0) = 0
          AND COALESCE(job_scope_kind.job_refresh_scope_kind, '') IN ('', 'TARGETED_TIMESHEETS')
        )
      )
  )
  UPDATE public.banking_pay_workbench_jobs AS update_job
  SET payload_json = jsonb_strip_nulls(
        COALESCE(update_job.payload_json, '{}'::jsonb)
        || jsonb_build_object(
          'superseded_at_utc', v_now::text,
          'superseded_reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
          'superseded_by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
          'superseded_by_source_build_run_id', p_source_build_run_id::text,
          'superseded_by_source_change_seq', p_source_change_seq,
          'superseded_by_session_version', v_session_version,
          'superseded_refresh_scope_kind', v_refresh_scope_kind,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'source_build_supersession', jsonb_build_object(
            'reason', 'NEWER_SOURCE_BUILD_SUCCEEDED',
            'at_utc', v_now::text,
            'by_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
            'by_source_build_run_id', p_source_build_run_id::text,
            'by_source_change_seq', p_source_change_seq,
            'by_session_version', v_session_version,
            'refresh_scope_kind', v_refresh_scope_kind
          )
        )
      ),
      updated_at_utc = v_now
  FROM source_build_jobs_to_supersede
  WHERE update_job.id = source_build_jobs_to_supersede.id;

  GET DIAGNOSTICS v_source_build_jobs_superseded = ROW_COUNT;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET status = CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_work_pending
          WHERE line_work_pending.session_id = p_session_id
            AND line_work_pending.candidate_id = p_candidate_id
            AND UPPER(BTRIM(COALESCE(line_work_pending.status, ''))) IN ('PENDING', 'READY', 'RUNNING', 'PROCESSING', 'QUEUED')
        ) THEN scope_update.status
        WHEN EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_line_work AS line_work_ready
          WHERE line_work_ready.session_id = p_session_id
            AND line_work_ready.candidate_id = p_candidate_id
            AND UPPER(BTRIM(COALESCE(line_work_ready.status, ''))) IN ('MATERIALISED', 'MATERIALIZED')
        ) THEN 'MATERIALISED'
        ELSE 'SOURCE_READY'
      END,
      dirty = false,
      error_json = CASE
        WHEN scope_update.error_json IS NULL
          OR scope_update.error_json = '{}'::jsonb
          OR UPPER(BTRIM(COALESCE(scope_update.error_json->>'code', ''))) IN (
            'SOURCE_BUILD_ERROR',
            'WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
            'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
            '42P01'
          )
          THEN NULL::jsonb
        ELSE scope_update.error_json
      END,
      pending_job_id = CASE
        WHEN scope_update.pending_job_id = p_success_job_id THEN NULL::uuid
        WHEN scope_update.pending_job_id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.banking_pay_workbench_jobs AS active_pending_job
            WHERE active_pending_job.id = scope_update.pending_job_id
              AND UPPER(BTRIM(COALESCE(active_pending_job.status, ''))) IN ('QUEUED', 'RUNNING')
          ) THEN NULL::uuid
        ELSE scope_update.pending_job_id
      END,
      updated_at_utc = v_now
  WHERE scope_update.session_id = p_session_id
    AND scope_update.candidate_id = p_candidate_id
    AND (
      COALESCE(scope_update.dirty, false) IS TRUE
      OR UPPER(BTRIM(COALESCE(scope_update.status, ''))) IN ('SOURCE_BUILD_ERROR', 'ERROR', 'FAILED')
      OR UPPER(BTRIM(COALESCE(scope_update.error_json->>'code', ''))) IN (
        'SOURCE_BUILD_ERROR',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
        'PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_FAILED',
        '42P01'
      )
      OR scope_update.pending_job_id = p_success_job_id
    )
    AND EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_source_lines AS current_source_exists
      WHERE current_source_exists.session_id = p_session_id
        AND current_source_exists.candidate_id = p_candidate_id
        AND current_source_exists.session_version = v_session_version
        AND current_source_exists.source_build_run_id = p_source_build_run_id
        AND current_source_exists.source_change_seq = p_source_change_seq
        AND current_source_exists.status = 'CURRENT'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_source_lines AS unresolved_source_row
      WHERE unresolved_source_row.session_id = p_session_id
        AND unresolved_source_row.candidate_id = p_candidate_id
        AND unresolved_source_row.session_version = v_session_version
        AND UPPER(BTRIM(COALESCE(unresolved_source_row.status, ''))) IN ('DIRTY', 'ERROR')
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_jobs AS active_source_job
      WHERE active_source_job.session_id = p_session_id
        AND active_source_job.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(active_source_job.status, ''))) IN ('QUEUED', 'RUNNING')
        AND CASE
              WHEN UPPER(BTRIM(COALESCE(active_source_job.job_type, ''))) IN (
                'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                'CANDIDATE_SOURCE_BUILD',
                'CANDIDATE_SOURCE_BUILD_CHUNK',
                'SOURCE_BUILD',
                'SOURCE_BUILD_PAGE'
              ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
              ELSE UPPER(BTRIM(COALESCE(active_source_job.job_type, '')))
            END = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND (
          COALESCE(active_source_job.payload_json->>'session_version', '') !~ '^[0-9]{1,18}$'
          OR (active_source_job.payload_json->>'session_version')::bigint = v_session_version
        )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_line_work AS line_work_error
      WHERE line_work_error.session_id = p_session_id
        AND line_work_error.candidate_id = p_candidate_id
        AND UPPER(BTRIM(COALESCE(line_work_error.status, ''))) IN ('ERROR', 'FAILED')
    );

  GET DIAGNOSTICS v_scope_rows_repaired = ROW_COUNT;

  IF COALESCE(p_recompute_session_progress, true) THEN
    BEGIN
      PERFORM 1
      FROM public.banking_pay_workbench_sessions AS session_progress_lock
      WHERE session_progress_lock.id = p_session_id
        AND UPPER(BTRIM(COALESCE(session_progress_lock.status, ''))) = 'OPEN'
        AND session_progress_lock.discarded_at_utc IS NULL
        AND COALESCE(session_progress_lock.version, 1) = COALESCE(v_session_version, 1)
        AND session_progress_lock.source_snapshot_run_id IS NOT DISTINCT FROM v_session_row.source_snapshot_run_id
        AND session_progress_lock.session_signature IS NOT DISTINCT FROM v_session_row.session_signature
      FOR UPDATE NOWAIT;

      v_session_progress_lock_acquired := FOUND;
    EXCEPTION
      WHEN lock_not_available THEN
        v_session_progress_lock_acquired := false;
        v_reconciliation_deferred := true;
        v_reconciliation_deferred_reason := 'SESSION_LOCK_NOT_AVAILABLE';
    END;

    IF v_session_progress_lock_acquired THEN
      v_progress_json := public.pay_workbench_session_get_progress_light(p_session_id);

      IF COALESCE((v_progress_json->>'ok')::boolean, false) THEN
      v_progress_state := UPPER(BTRIM(COALESCE(v_progress_json->>'progress_state', v_progress_json->>'phase', '')));
      IF v_progress_state = '' THEN
        v_progress_state := v_session_row.progress_state;
      END IF;

      v_section_counts_json := CASE
        WHEN jsonb_typeof(v_progress_json->'section_counts_json') = 'object'
          THEN v_progress_json->'section_counts_json'
        ELSE '{}'::jsonb
      END;
      v_candidate_sample_rows_json := CASE
        WHEN jsonb_typeof(v_progress_json->'candidate_sample_rows_json') = 'array'
          THEN v_progress_json->'candidate_sample_rows_json'
        ELSE '[]'::jsonb
      END;

      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET scope_total_count = CASE WHEN COALESCE(v_progress_json->>'scope_total_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_total_count')::integer ELSE COALESCE(session_update.scope_total_count, 0) END,
          scope_seeded_count = CASE WHEN COALESCE(v_progress_json->>'scope_seeded_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_seeded_count')::integer ELSE COALESCE(session_update.scope_seeded_count, 0) END,
          scope_ready_count = CASE WHEN COALESCE(v_progress_json->>'scope_ready_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_ready_count')::integer ELSE COALESCE(session_update.scope_ready_count, 0) END,
          scope_pending_count = CASE WHEN COALESCE(v_progress_json->>'scope_pending_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_pending_count')::integer ELSE COALESCE(session_update.scope_pending_count, 0) END,
          scope_failed_count = CASE WHEN COALESCE(v_progress_json->>'scope_failed_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'scope_failed_count')::integer ELSE COALESCE(session_update.scope_failed_count, 0) END,
          line_units_total = CASE WHEN COALESCE(v_progress_json->>'line_units_total', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_total')::integer ELSE COALESCE(session_update.line_units_total, 0) END,
          line_units_pending = CASE WHEN COALESCE(v_progress_json->>'line_units_pending', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_pending')::integer ELSE COALESCE(session_update.line_units_pending, 0) END,
          line_units_ready = CASE WHEN COALESCE(v_progress_json->>'line_units_ready', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_ready')::integer ELSE COALESCE(session_update.line_units_ready, 0) END,
          line_units_failed = CASE WHEN COALESCE(v_progress_json->>'line_units_failed', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'line_units_failed')::integer ELSE COALESCE(session_update.line_units_failed, 0) END,
          preview_row_count = CASE WHEN COALESCE(v_progress_json->>'preview_row_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'preview_row_count')::integer ELSE COALESCE(session_update.preview_row_count, 0) END,
          selected_row_count = CASE WHEN COALESCE(v_progress_json->>'selected_row_count', '') ~ '^-?[0-9]+$' THEN (v_progress_json->>'selected_row_count')::integer ELSE COALESCE(session_update.selected_row_count, 0) END,
          section_counts_json = v_section_counts_json,
          candidate_sample_rows_json = v_candidate_sample_rows_json,
          progress_state = COALESCE(NULLIF(v_progress_state, ''), session_update.progress_state),
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || COALESCE(v_progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_source_build_reconciliation', jsonb_build_object(
                'applied_at_utc', v_now::text,
                'candidate_id', p_candidate_id::text,
                'source_build_run_id', p_source_build_run_id::text,
                'source_change_seq', p_source_change_seq,
                'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
                'source_build_jobs_superseded', COALESCE(v_source_build_jobs_superseded, 0),
                'scope_rows_repaired', COALESCE(v_scope_rows_repaired, 0)
              ),
              'counter_reconciled', true,
              'counter_reconciled_at_utc', v_now::text
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = p_session_id
      RETURNING session_update.*
      INTO v_session_row;

        v_counter_reconciled := true;
      END IF;
    ELSIF v_reconciliation_deferred IS NOT TRUE THEN
      v_reconciliation_deferred := true;
      v_reconciliation_deferred_reason := 'SESSION_NOT_OPEN_OR_CONTEXT_STALE';
    END IF;
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_source_build_reconciliation',
    p_session_id::text,
    'RECONCILE_SUCCESSFUL_SOURCE_BUILD',
    NULL::jsonb,
    jsonb_build_object(
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq,
      'success_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
      'refresh_scope_kind', v_refresh_scope_kind,
      'current_source_row_count', COALESCE(v_current_source_row_count, 0),
      'current_source_identity_count', COALESCE(v_current_source_identity_count, 0),
      'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
      'source_build_jobs_superseded', COALESCE(v_source_build_jobs_superseded, 0),
      'scope_rows_repaired', COALESCE(v_scope_rows_repaired, 0),
      'deferred', COALESCE(v_reconciliation_deferred, false),
      'deferred_reason', v_reconciliation_deferred_reason,
      'progress_recomputed', COALESCE(v_session_progress_lock_acquired, false) AND COALESCE(p_recompute_session_progress, true),
      'counter_reconciled', COALESCE(v_counter_reconciled, false),
      'retry_safe', COALESCE(v_reconciliation_deferred, false),
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    'NEWER_SOURCE_BUILD_SUCCEEDED',
    v_session_row.actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'skipped', false,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'session_version', v_session_version,
    'source_build_run_id', p_source_build_run_id::text,
    'source_change_seq', p_source_change_seq,
    'success_job_id', CASE WHEN p_success_job_id IS NULL THEN NULL ELSE p_success_job_id::text END,
    'refresh_scope_kind', v_refresh_scope_kind,
    'current_source_row_count', COALESCE(v_current_source_row_count, 0),
    'current_source_identity_count', COALESCE(v_current_source_identity_count, 0),
    'source_rows_superseded', COALESCE(v_source_rows_superseded, 0),
    'source_build_jobs_superseded', COALESCE(v_source_build_jobs_superseded, 0),
    'scope_rows_repaired', COALESCE(v_scope_rows_repaired, 0),
    'deferred', COALESCE(v_reconciliation_deferred, false),
    'reason', v_reconciliation_deferred_reason,
    'progress_recomputed', COALESCE(v_session_progress_lock_acquired, false) AND COALESCE(p_recompute_session_progress, true),
    'counter_reconciled', COALESCE(v_counter_reconciled, false),
    'progress_phase', CASE WHEN v_progress_json = '{}'::jsonb THEN NULL ELSE v_progress_json->>'phase' END,
    'progress_blocker_codes', CASE WHEN v_progress_json = '{}'::jsonb THEN '[]'::jsonb ELSE COALESCE(v_progress_json->'blocker_codes', '[]'::jsonb) END,
    'retry_safe', COALESCE(v_reconciliation_deferred, false),
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- pay_workbench_repair_invalid_source_build_poison(uuid,uuid,integer,timestamp with time zone,text)
CREATE OR REPLACE FUNCTION public.pay_workbench_repair_invalid_source_build_poison(p_session_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT 'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_POISON_REPAIR'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := COALESCE(p_now_utc, now());
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 10), 100));
  v_reason text := COALESCE(NULLIF(BTRIM(p_reason), ''), 'INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_POISON_REPAIR');
  v_repair_row record;
  v_processed_count integer := 0;
  v_repaired_count integer := 0;
  v_skipped_count integer := 0;
  v_restored_source_row_count integer := 0;
  v_total_restored_source_row_count integer := 0;
  v_requeued_line_seed_count integer := 0;
  v_repaired_scope_count integer := 0;
  v_repaired_session_count integer := 0;
  v_repairs_json jsonb := '[]'::jsonb;
  v_skips_json jsonb := '[]'::jsonb;
  v_source_rows_before_json jsonb := '{}'::jsonb;
  v_source_rows_after_json jsonb := '{}'::jsonb;
  v_bad_job_audit_before_json jsonb := '{}'::jsonb;
  v_bad_job_audit_after_json jsonb := '{}'::jsonb;
  v_line_seed_before_json jsonb := NULL::jsonb;
  v_line_seed_after_json jsonb := NULL::jsonb;
  v_scope_before_json jsonb := NULL::jsonb;
  v_scope_after_json jsonb := NULL::jsonb;
  v_session_before_json jsonb := NULL::jsonb;
  v_session_after_json jsonb := NULL::jsonb;
  v_progress_recompute_json jsonb := '{}'::jsonb;
  v_progress_recompute_failed boolean := false;
  v_progress_recompute_error_json jsonb := NULL::jsonb;
  v_source_row_object_id text := NULL::text;
  v_zero_repair_row record;
  v_zero_source_row_repaired_count integer := 0;
  v_corrected_source_build_job_queued_count integer := 0;
  v_corrected_source_build_job_reused_count integer := 0;
  v_corrected_source_build_job_succeeded_reused_count integer := 0;
  v_line_seed_attempt_count_reset_count integer := 0;
  v_zero_source_row_repairs_json jsonb := '[]'::jsonb;
  v_zero_source_row_skips_json jsonb := '[]'::jsonb;
  v_zero_corrected_job_id uuid := NULL::uuid;
  v_zero_corrected_job_status text := NULL::text;
  v_zero_corrected_job_payload_json jsonb := '{}'::jsonb;
  v_zero_existing_corrected_failed_job_id uuid := NULL::uuid;
  v_zero_source_change_seq bigint := 0;
  v_zero_session_version bigint := 0;
  v_zero_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_zero_pay_channel_scope text := 'ALL';
  v_zero_reason text := NULL::text;
  v_zero_source_session_id uuid := NULL::uuid;
  v_zero_source_session_id_text text := NULL::text;
  v_zero_source_session_version bigint := NULL::bigint;
  v_zero_source_session_signature text := NULL::text;
  v_zero_source_snapshot_run_id uuid := NULL::uuid;
  v_zero_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_zero_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_zero_source_build_seed_text text := NULL::text;
  v_zero_source_build_hash text := NULL::text;
  v_zero_source_build_run_id uuid := NULL::uuid;
  v_zero_corrected_dedupe_key text := NULL::text;
  v_zero_corrected_payload_json jsonb := '{}'::jsonb;
  v_zero_corrected_job_action text := NULL::text;
  v_zero_scope_before_json jsonb := NULL::jsonb;
  v_zero_scope_after_json jsonb := NULL::jsonb;
  v_zero_bad_job_before_json jsonb := NULL::jsonb;
  v_zero_bad_job_after_json jsonb := NULL::jsonb;
  v_zero_corrected_job_before_json jsonb := NULL::jsonb;
  v_zero_corrected_job_after_json jsonb := NULL::jsonb;
  v_zero_session_before_json jsonb := NULL::jsonb;
  v_zero_session_after_json jsonb := NULL::jsonb;
  v_post_recompute_progress_state text := NULL::text;
  v_post_recompute_scope_failed_count integer := NULL::integer;
  v_post_recompute_scope_pending_count integer := NULL::integer;
  v_orphan_repair_row record;
  v_orphan_enqueue_result jsonb := '{}'::jsonb;
  v_orphan_enqueue_error_json jsonb := NULL::jsonb;
  v_orphan_enqueue_job_id_text text := NULL::text;
  v_orphan_enqueue_job_id uuid := NULL::uuid;
  v_orphan_enqueue_job_type text := NULL::text;
  v_orphan_enqueue_job_status text := NULL::text;
  v_orphan_enqueue_source_build_run_id_text text := NULL::text;
  v_orphan_enqueue_valid boolean := false;
  v_orphan_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_orphan_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_orphan_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_orphan_pay_channel_scope text := 'ALL';
  v_orphan_source_change_seq bigint := 0;
  v_orphan_scope_before_json jsonb := NULL::jsonb;
  v_orphan_scope_after_json jsonb := NULL::jsonb;
  v_orphan_bad_job_before_json jsonb := NULL::jsonb;
  v_orphan_bad_job_after_json jsonb := NULL::jsonb;
  v_orphan_session_before_json jsonb := NULL::jsonb;
  v_orphan_session_after_json jsonb := NULL::jsonb;
  v_orphan_pending_repaired_count integer := 0;
  v_orphan_pending_failed_closed_count integer := 0;
  v_orphan_pending_repairs_json jsonb := '[]'::jsonb;
  v_orphan_pending_skips_json jsonb := '[]'::jsonb;
BEGIN
  FOR v_repair_row IN
    WITH poisoned_scope AS (
      SELECT
        scope_row.id AS scope_id,
        scope_row.session_id,
        scope_row.candidate_id,
        scope_row.status AS scope_status,
        scope_row.pending_job_id AS scope_pending_job_id,
        scope_row.dirty AS scope_dirty,
        scope_row.error_json AS scope_error_json,
        scope_row.updated_at_utc AS scope_updated_at_utc,
        NULLIF(BTRIM(COALESCE(
          scope_row.error_json->>'job_id',
          scope_row.error_json#>>'{job,job_id}',
          scope_row.error_json#>>'{source_build,job_id}',
          scope_row.error_json#>>'{last_error_json,job_id}',
          scope_row.error_json#>>'{job_error_json,job_id}',
          ''
        )), '') AS bad_job_id_text
      FROM public.banking_pay_workbench_session_scope AS scope_row
      WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SOURCE_BUILD_ERROR'
        AND (p_session_id IS NULL OR scope_row.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR scope_row.candidate_id = p_candidate_id)
      ORDER BY scope_row.updated_at_utc ASC, scope_row.id ASC
      LIMIT v_limit
      FOR UPDATE OF scope_row SKIP LOCKED
    ), bad_scope AS (
      SELECT
        poisoned_scope.*,
        bad_job_id.bad_job_id,
        bad_job.job_type AS bad_job_type,
        bad_job.status AS bad_job_status,
        bad_job.attempt_count AS bad_job_attempt_count,
        bad_job.max_attempts AS bad_job_max_attempts,
        bad_job.dedupe_key AS bad_job_dedupe_key,
        bad_job.payload_json AS bad_job_payload_json,
        bad_job.last_error_json AS bad_job_last_error_json,
        bad_job.created_at_utc AS bad_job_created_at_utc,
        bad_job.updated_at_utc AS bad_job_updated_at_utc,
        bad_job.failed_at_utc AS bad_job_failed_at_utc,
        NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') AS bad_source_build_run_id_text,
        COALESCE(app_counter.seq, 0)::bigint AS live_candidate_change_seq
      FROM poisoned_scope
      JOIN LATERAL (
        SELECT poisoned_scope.bad_job_id_text::uuid AS bad_job_id
        WHERE poisoned_scope.bad_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS bad_job_id ON true
      JOIN public.banking_pay_workbench_jobs AS bad_job
        ON bad_job.id = bad_job_id.bad_job_id
      LEFT JOIN public.app_change_counters AS app_counter
        ON app_counter.entity_key = 'pay_candidate:' || poisoned_scope.candidate_id::text
      WHERE bad_job.session_id = poisoned_scope.session_id
        AND bad_job.candidate_id = poisoned_scope.candidate_id
        AND UPPER(BTRIM(COALESCE(bad_job.job_type, ''))) IN (
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
          'CANDIDATE_SOURCE_BUILD',
          'CANDIDATE_SOURCE_BUILD_CHUNK',
          'SOURCE_BUILD',
          'SOURCE_BUILD_PAGE'
        )
        AND UPPER(BTRIM(COALESCE(bad_job.status, ''))) IN ('FAILED', 'DEAD')
        AND NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') IS NULL
        AND (
          COALESCE(bad_job.last_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
          OR COALESCE(poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%STALE_RUNNING_WORKBENCH_SOURCE_BUILD_FAILED%'
          OR COALESCE(poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%WORKBENCH_SOURCE_BUILD_JOB_FAILED%'
          OR COALESCE(bad_job.payload_json, '{}'::jsonb)::text ILIKE '%CLONE_REBASE_INELIGIBLE_SOURCE_BUILD%'
        )
    ), candidate_runs AS (
      SELECT
        bad_scope.*,
        source_line.source_build_run_id,
        source_line.source_change_seq,
        COUNT(*)::integer AS source_rows_error_count,
        MIN(source_line.created_at_utc) AS source_rows_first_created_at_utc,
        MAX(source_line.updated_at_utc) AS source_rows_last_updated_at_utc
      FROM bad_scope
      JOIN public.banking_pay_workbench_candidate_source_lines AS source_line
        ON source_line.session_id = bad_scope.session_id
       AND source_line.candidate_id = bad_scope.candidate_id
       AND UPPER(BTRIM(COALESCE(source_line.status, ''))) = 'ERROR'
      GROUP BY
        bad_scope.scope_id,
        bad_scope.session_id,
        bad_scope.candidate_id,
        bad_scope.scope_status,
        bad_scope.scope_pending_job_id,
        bad_scope.scope_dirty,
        bad_scope.scope_error_json,
        bad_scope.scope_updated_at_utc,
        bad_scope.bad_job_id_text,
        bad_scope.bad_job_id,
        bad_scope.bad_job_type,
        bad_scope.bad_job_status,
        bad_scope.bad_job_attempt_count,
        bad_scope.bad_job_max_attempts,
        bad_scope.bad_job_dedupe_key,
        bad_scope.bad_job_payload_json,
        bad_scope.bad_job_last_error_json,
        bad_scope.bad_job_created_at_utc,
        bad_scope.bad_job_updated_at_utc,
        bad_scope.bad_job_failed_at_utc,
        bad_scope.bad_source_build_run_id_text,
        bad_scope.live_candidate_change_seq,
        source_line.source_build_run_id,
        source_line.source_change_seq
    ), repair_choices AS (
      SELECT
        candidate_runs.*,
        good_source_job.id AS good_source_build_job_id,
        good_source_job.status AS good_source_build_job_status,
        good_source_job.updated_at_utc AS good_source_build_job_updated_at_utc,
        line_seed_job.id AS line_seed_job_id,
        line_seed_job.status AS line_seed_job_status,
        line_seed_job.attempt_count AS line_seed_attempt_count,
        line_seed_job.max_attempts AS line_seed_max_attempts,
        line_seed_job.updated_at_utc AS line_seed_updated_at_utc,
        line_seed_job.last_error_json AS line_seed_last_error_json
      FROM candidate_runs
      JOIN LATERAL (
        SELECT source_job.*
        FROM public.banking_pay_workbench_jobs AS source_job
        CROSS JOIN LATERAL (
          SELECT
            NULLIF(BTRIM(COALESCE(
              source_job.payload_json->>'source_build_run_id',
              source_job.payload_json#>>'{source_build,source_build_run_id}',
              source_job.payload_json#>>'{source_build,run_id}',
              source_job.payload_json#>>'{cursor,source_build_run_id}',
              source_job.payload_json#>>'{cursor_json,source_build_run_id}',
              source_job.payload_json#>>'{result_json,source_build_run_id}',
              ''
            )), '') AS source_build_run_id_text,
            COALESCE(
              CASE WHEN COALESCE(source_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
              CASE WHEN COALESCE(source_job.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
              CASE WHEN COALESCE(source_job.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json#>>'{source_build,source_change_seq}')::bigint ELSE NULL::bigint END,
              CASE WHEN COALESCE(source_job.payload_json#>>'{result_json,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (source_job.payload_json#>>'{result_json,source_change_seq}')::bigint ELSE NULL::bigint END
            ) AS source_change_seq
        ) AS source_job_extract
        WHERE source_job.session_id = candidate_runs.session_id
          AND source_job.candidate_id = candidate_runs.candidate_id
          AND source_job.id <> candidate_runs.bad_job_id
          AND UPPER(BTRIM(COALESCE(source_job.job_type, ''))) IN (
            'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
            'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
            'CANDIDATE_SOURCE_BUILD',
            'CANDIDATE_SOURCE_BUILD_CHUNK',
            'SOURCE_BUILD',
            'SOURCE_BUILD_PAGE'
          )
          AND UPPER(BTRIM(COALESCE(source_job.status, ''))) = 'SUCCEEDED'
          AND source_job_extract.source_build_run_id_text = candidate_runs.source_build_run_id::text
          AND (
            source_job_extract.source_change_seq IS NULL
            OR source_job_extract.source_change_seq = candidate_runs.source_change_seq
          )
        ORDER BY source_job.updated_at_utc DESC NULLS LAST, source_job.created_at_utc DESC NULLS LAST, source_job.id DESC
        LIMIT 1
      ) AS good_source_job ON true
      JOIN LATERAL (
        SELECT line_job.*
        FROM public.banking_pay_workbench_jobs AS line_job
        CROSS JOIN LATERAL (
          SELECT NULLIF(BTRIM(COALESCE(
            line_job.payload_json->>'source_build_run_id',
            line_job.payload_json#>>'{source_build,source_build_run_id}',
            line_job.payload_json#>>'{source_build,run_id}',
            line_job.payload_json#>>'{cursor,source_build_run_id}',
            line_job.payload_json#>>'{cursor_json,source_build_run_id}',
            line_job.payload_json#>>'{source_build_cursor,source_build_run_id}',
            line_job.payload_json#>>'{result_json,source_build_run_id}',
            ''
          )), '') AS source_build_run_id_text
        ) AS line_job_extract
        WHERE line_job.session_id = candidate_runs.session_id
          AND line_job.candidate_id = candidate_runs.candidate_id
          AND UPPER(BTRIM(COALESCE(line_job.job_type, ''))) IN (
            'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
            'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE',
            'CANDIDATE_LINE_WORK_SEED',
            'CANDIDATE_LINE_WORK_SEED_PAGE',
            'LINE_WORK_SEED_PAGE',
            'SNAPSHOT_CANDIDATE_REFRESH',
            'CANDIDATE_REFRESH'
          )
          AND UPPER(BTRIM(COALESCE(line_job.status, ''))) IN ('FAILED', 'DEAD')
          AND line_job_extract.source_build_run_id_text = candidate_runs.source_build_run_id::text
          AND COALESCE(line_job.last_error_json, '{}'::jsonb)::text ILIKE '%SOURCE_ROWS_MISSING%'
        ORDER BY line_job.updated_at_utc DESC NULLS LAST, line_job.created_at_utc DESC NULLS LAST, line_job.id DESC
        LIMIT 1
      ) AS line_seed_job ON true
      ORDER BY
        CASE WHEN candidate_runs.source_change_seq = candidate_runs.live_candidate_change_seq THEN 0 ELSE 1 END,
        candidate_runs.source_change_seq DESC,
        good_source_job.updated_at_utc DESC NULLS LAST,
        line_seed_job.updated_at_utc DESC NULLS LAST
      LIMIT v_limit
    )
    SELECT *
    FROM repair_choices
  LOOP
    v_processed_count := v_processed_count + 1;
    v_restored_source_row_count := 0;
    v_progress_recompute_json := '{}'::jsonb;
    v_progress_recompute_failed := false;
    v_progress_recompute_error_json := NULL::jsonb;
    v_line_seed_before_json := NULL::jsonb;
    v_line_seed_after_json := NULL::jsonb;
    v_scope_before_json := NULL::jsonb;
    v_scope_after_json := NULL::jsonb;
    v_session_before_json := NULL::jsonb;
    v_session_after_json := NULL::jsonb;
    v_source_row_object_id := v_repair_row.source_build_run_id::text;

    v_bad_job_audit_before_json := jsonb_build_object(
      'session_id', v_repair_row.session_id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'job_type', v_repair_row.bad_job_type,
      'status', v_repair_row.bad_job_status,
      'attempt_count', v_repair_row.bad_job_attempt_count,
      'max_attempts', v_repair_row.bad_job_max_attempts,
      'source_build_run_id', NULL::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'last_error_json', v_repair_row.bad_job_last_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    );
    SELECT COALESCE(jsonb_agg(status_counts.status_json ORDER BY status_counts.status), '[]'::jsonb)
    INTO v_source_rows_before_json
    FROM (
      SELECT
        source_line.status,
        jsonb_build_object(
          'status', source_line.status,
          'count', COUNT(*)::integer
        ) AS status_json
      FROM public.banking_pay_workbench_candidate_source_lines AS source_line
      WHERE source_line.session_id = v_repair_row.session_id
        AND source_line.candidate_id = v_repair_row.candidate_id
        AND source_line.source_build_run_id = v_repair_row.source_build_run_id
        AND source_line.source_change_seq = v_repair_row.source_change_seq
      GROUP BY source_line.status
    ) AS status_counts;

    WITH restored_source_rows AS (
      UPDATE public.banking_pay_workbench_candidate_source_lines AS source_line
      SET status = 'CURRENT',
          source_row_json = jsonb_strip_nulls(
            (COALESCE(source_line.source_row_json, '{}'::jsonb) - 'stale_source_build_error' - 'source_build_error')
            || jsonb_build_object(
              'source_build_poison_repair', jsonb_build_object(
                'code', 'SOURCE_BUILD_ROWS_RESTORED',
                'repaired_at_utc', v_now::text,
                'session_id', v_repair_row.session_id::text,
                'candidate_id', v_repair_row.candidate_id::text,
                'bad_job_id', v_repair_row.bad_job_id::text,
                'source_build_run_id', v_repair_row.source_build_run_id::text,
                'source_change_seq', v_repair_row.source_change_seq,
                'line_seed_job_id', v_repair_row.line_seed_job_id::text,
                'reason', v_reason,
                'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
              )
            )
          ),
          updated_at_utc = v_now
      WHERE source_line.session_id = v_repair_row.session_id
        AND source_line.candidate_id = v_repair_row.candidate_id
        AND source_line.source_build_run_id = v_repair_row.source_build_run_id
        AND source_line.source_change_seq = v_repair_row.source_change_seq
        AND UPPER(BTRIM(COALESCE(source_line.status, ''))) = 'ERROR'
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_source_lines AS existing_current_source_line
          WHERE existing_current_source_line.id <> source_line.id
            AND existing_current_source_line.session_id = source_line.session_id
            AND existing_current_source_line.candidate_id = source_line.candidate_id
            AND existing_current_source_line.session_version = source_line.session_version
            AND existing_current_source_line.source_change_seq = source_line.source_change_seq
            AND existing_current_source_line.source_build_run_id = source_line.source_build_run_id
            AND COALESCE(existing_current_source_line.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid) = COALESCE(source_line.timesheet_id, '00000000-0000-0000-0000-000000000000'::uuid)
            AND existing_current_source_line.line_key = source_line.line_key
            AND UPPER(BTRIM(COALESCE(existing_current_source_line.status, ''))) = 'CURRENT'
        )
      RETURNING source_line.id
    )
    SELECT COUNT(*)::integer
    INTO v_restored_source_row_count
    FROM restored_source_rows;

    SELECT COALESCE(jsonb_agg(status_counts.status_json ORDER BY status_counts.status), '[]'::jsonb)
    INTO v_source_rows_after_json
    FROM (
      SELECT
        source_line.status,
        jsonb_build_object(
          'status', source_line.status,
          'count', COUNT(*)::integer
        ) AS status_json
      FROM public.banking_pay_workbench_candidate_source_lines AS source_line
      WHERE source_line.session_id = v_repair_row.session_id
        AND source_line.candidate_id = v_repair_row.candidate_id
        AND source_line.source_build_run_id = v_repair_row.source_build_run_id
        AND source_line.source_change_seq = v_repair_row.source_change_seq
      GROUP BY source_line.status
    ) AS status_counts;

    PERFORM public._audit_insert(
      'banking_pay_workbench_candidate_source_lines',
      v_source_row_object_id,
      'SOURCE_BUILD_ROWS_RESTORED',
      jsonb_build_object(
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'status_counts', COALESCE(v_source_rows_before_json, '[]'::jsonb),
        'old_status', 'ERROR',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ),
      jsonb_build_object(
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'source_rows_restored_count', COALESCE(v_restored_source_row_count, 0),
        'affected_row_count', COALESCE(v_restored_source_row_count, 0),
        'status_counts', COALESCE(v_source_rows_after_json, '[]'::jsonb),
        'new_status', 'CURRENT',
        'reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ),
      'SOURCE_BUILD_ROWS_RESTORED',
      NULL
    );

    IF COALESCE(v_restored_source_row_count, 0) <= 0 THEN
      v_skipped_count := v_skipped_count + 1;
      v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'reason', 'NO_ERROR_SOURCE_ROWS_RESTORED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS bad_job_update
    SET payload_json = jsonb_strip_nulls(
          COALESCE(bad_job_update.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'invalid_source_build_without_run_id_failed_closed', true,
            'invalid_source_build_without_run_id_non_blocking', true,
            'non_blocking_terminal_failure', true,
            'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'non_blocking_terminal_failure_at_utc', v_now::text,
            'source_build_poison_repair_resolved', true,
            'source_build_poison_repair_resolved_at_utc', v_now::text,
            'source_build_poison_repair_reason', v_reason,
            'source_build_poison_repair_good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
            'source_build_poison_repair_source_build_run_id', v_repair_row.source_build_run_id::text,
            'source_build_poison_repair_source_change_seq', v_repair_row.source_change_seq,
            'source_build_poison_repair_line_seed_job_id', v_repair_row.line_seed_job_id::text,
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        ),
        updated_at_utc = v_now
    WHERE bad_job_update.id = v_repair_row.bad_job_id
    RETURNING jsonb_build_object(
      'session_id', v_repair_row.session_id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', bad_job_update.id::text,
      'job_type', bad_job_update.job_type,
      'status', bad_job_update.status,
      'retained_terminal', true,
      'hard_deleted', false,
      'bad_job_mutated', true,
      'source_build_run_id', NULL::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'non_blocking_terminal_failure', true,
      'invalid_source_build_without_run_id_non_blocking', true,
      'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
      'repaired_source_build_run_id', v_repair_row.source_build_run_id::text,
      'line_seed_job_id', v_repair_row.line_seed_job_id::text,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_bad_job_audit_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_repair_row.bad_job_id::text,
      'FAILED',
      v_bad_job_audit_before_json,
      v_bad_job_audit_after_json,
      'WORKBENCH_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', line_seed_job.id::text,
      'job_type', line_seed_job.job_type,
      'status', line_seed_job.status,
      'run_at_utc', line_seed_job.run_at_utc,
      'attempt_count', line_seed_job.attempt_count,
      'max_attempts', line_seed_job.max_attempts,
      'session_id', CASE WHEN line_seed_job.session_id IS NULL THEN NULL ELSE line_seed_job.session_id::text END,
      'candidate_id', CASE WHEN line_seed_job.candidate_id IS NULL THEN NULL ELSE line_seed_job.candidate_id::text END,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'last_error_json', line_seed_job.last_error_json,
      'failed_at_utc', line_seed_job.failed_at_utc,
      'updated_at_utc', line_seed_job.updated_at_utc,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_line_seed_before_json
    FROM public.banking_pay_workbench_jobs AS line_seed_job
    WHERE line_seed_job.id = v_repair_row.line_seed_job_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_jobs AS line_seed_job
    SET status = 'QUEUED',
        attempt_count = 0,
        run_at_utc = v_now,
        started_at_utc = NULL::timestamptz,
        completed_at_utc = NULL::timestamptz,
        failed_at_utc = NULL::timestamptz,
        last_error_json = NULL::jsonb,
        payload_json = jsonb_strip_nulls(
          (COALESCE(line_seed_job.payload_json, '{}'::jsonb) - 'last_failure_json')
          || jsonb_build_object(
            'source_build_poison_repair', jsonb_build_object(
              'code', 'WORKBENCH_LINE_SEED_REQUEUED_AFTER_SOURCE_BUILD_POISON_REPAIR',
              'requeued_at_utc', v_now::text,
              'session_id', v_repair_row.session_id::text,
              'candidate_id', v_repair_row.candidate_id::text,
              'bad_job_id', v_repair_row.bad_job_id::text,
              'source_build_run_id', v_repair_row.source_build_run_id::text,
              'source_change_seq', v_repair_row.source_change_seq,
              'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
              'attempt_count_reset_to', 0,
              'reason', v_reason,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          )
        ),
        updated_at_utc = v_now
    WHERE line_seed_job.id = v_repair_row.line_seed_job_id
      AND UPPER(BTRIM(COALESCE(line_seed_job.status, ''))) IN ('FAILED', 'DEAD')
    RETURNING jsonb_build_object(
      'id', line_seed_job.id::text,
      'job_type', line_seed_job.job_type,
      'status', line_seed_job.status,
      'run_at_utc', line_seed_job.run_at_utc,
      'attempt_count', line_seed_job.attempt_count,
      'max_attempts', line_seed_job.max_attempts,
      'session_id', CASE WHEN line_seed_job.session_id IS NULL THEN NULL ELSE line_seed_job.session_id::text END,
      'candidate_id', CASE WHEN line_seed_job.candidate_id IS NULL THEN NULL ELSE line_seed_job.candidate_id::text END,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'last_error_json', line_seed_job.last_error_json,
      'failed_at_utc', line_seed_job.failed_at_utc,
      'updated_at_utc', line_seed_job.updated_at_utc,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_line_seed_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_repair_row.line_seed_job_id::text,
      'REQUEUED',
      v_line_seed_before_json,
      v_line_seed_after_json,
      'WORKBENCH_LINE_SEED_REQUEUED_AFTER_SOURCE_BUILD_POISON_REPAIR',
      NULL
    );

    IF v_line_seed_after_json IS NOT NULL THEN
      v_line_seed_attempt_count_reset_count := v_line_seed_attempt_count_reset_count + 1;
    END IF;

    SELECT jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_scope_before_json
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.id = v_repair_row.scope_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_session_scope AS scope_row
    SET status = 'LINE_WORK_PENDING',
        dirty = true,
        pending_job_id = v_repair_row.line_seed_job_id,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE scope_row.id = v_repair_row.scope_id
      AND scope_row.session_id = v_repair_row.session_id
      AND scope_row.candidate_id = v_repair_row.candidate_id
    RETURNING jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_scope_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_scope',
      v_repair_row.candidate_id::text,
      'SOURCE_BUILD_POISON_REPAIRED',
      v_scope_before_json,
      v_scope_after_json,
      'SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_updated_at_utc', session_row.progress_updated_at_utc,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'session_id', session_row.id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_session_before_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_repair_row.session_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_sessions AS session_row
    SET progress_state = 'REFRESHING_CANDIDATES',
        progress_json = jsonb_strip_nulls(
          (
            public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true)
            - 'last_source_build_failure_at_utc'
            - 'last_source_build_failure_job_id'
            - 'last_source_build_failure_code'
            - 'last_source_build_failure_source_build_run_id'
            - 'last_source_build_source_rows_marked_error_count'
            - 'blocker_codes'
            - 'draft_blocker_codes'
            - 'session_blocker_codes'
          )
          || jsonb_build_object(
            'source_build_poison_repair', jsonb_build_object(
              'code', 'PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
              'repaired_at_utc', v_now::text,
              'session_id', v_repair_row.session_id::text,
              'candidate_id', v_repair_row.candidate_id::text,
              'bad_job_id', v_repair_row.bad_job_id::text,
              'source_build_run_id', v_repair_row.source_build_run_id::text,
              'source_change_seq', v_repair_row.source_change_seq,
              'line_seed_job_id', v_repair_row.line_seed_job_id::text,
              'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
              'reason', v_reason,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          )
        ),
        progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_row.id = v_repair_row.session_id;

    BEGIN
      v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_repair_row.session_id,
        p_apply => true,
        p_reason => 'SOURCE_BUILD_POISON_REPAIRED',
        p_write_progress_json => true
      );
    EXCEPTION WHEN OTHERS THEN
      v_progress_recompute_failed := true;
      v_progress_recompute_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_repair_row.session_id::text,
        'candidate_id', v_repair_row.candidate_id::text,
        'bad_job_id', v_repair_row.bad_job_id::text,
        'source_build_run_id', v_repair_row.source_build_run_id::text,
        'source_change_seq', v_repair_row.source_change_seq,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
      v_progress_recompute_json := COALESCE(v_progress_recompute_error_json, '{}'::jsonb);
    END;

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_updated_at_utc', session_row.progress_updated_at_utc,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'session_id', session_row.id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'line_seed_job_id', v_repair_row.line_seed_job_id::text,
      'restored_source_row_count', COALESCE(v_restored_source_row_count, 0),
      'recompute_failed', v_progress_recompute_failed,
      'recompute_json', COALESCE(v_progress_recompute_json, '{}'::jsonb),
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_session_after_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_repair_row.session_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      v_repair_row.session_id::text,
      'PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      v_session_before_json,
      v_session_after_json,
      'PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      NULL
    );

    v_repaired_count := v_repaired_count + 1;
    v_total_restored_source_row_count := v_total_restored_source_row_count + COALESCE(v_restored_source_row_count, 0);
    v_requeued_line_seed_count := v_requeued_line_seed_count + 1;
    v_repaired_scope_count := v_repaired_scope_count + 1;
    v_repaired_session_count := v_repaired_session_count + 1;

    v_repairs_json := v_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_repair_row.session_id::text,
      'candidate_id', v_repair_row.candidate_id::text,
      'bad_job_id', v_repair_row.bad_job_id::text,
      'good_source_build_job_id', v_repair_row.good_source_build_job_id::text,
      'source_build_run_id', v_repair_row.source_build_run_id::text,
      'source_change_seq', v_repair_row.source_change_seq,
      'line_seed_job_id', v_repair_row.line_seed_job_id::text,
      'source_rows_restored_count', COALESCE(v_restored_source_row_count, 0),
      'line_seed_requeued', true,
      'line_seed_attempt_count_reset', v_line_seed_after_json IS NOT NULL,
      'scope_repaired', true,
      'session_progress_repaired', true,
      'progress_recompute_failed', v_progress_recompute_failed,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));
  END LOOP;

  FOR v_zero_repair_row IN
    WITH zero_poisoned_scope AS (
      SELECT
        scope_row.id AS scope_id,
        scope_row.session_id,
        scope_row.candidate_id,
        scope_row.status AS scope_status,
        scope_row.pending_job_id AS scope_pending_job_id,
        scope_row.dirty AS scope_dirty,
        scope_row.error_json AS scope_error_json,
        scope_row.updated_at_utc AS scope_updated_at_utc,
        NULLIF(BTRIM(COALESCE(
          scope_row.error_json->>'job_id',
          scope_row.error_json#>>'{job,job_id}',
          scope_row.error_json#>>'{source_build,job_id}',
          scope_row.error_json#>>'{last_error_json,job_id}',
          scope_row.error_json#>>'{job_error_json,job_id}',
          ''
        )), '') AS bad_job_id_text
      FROM public.banking_pay_workbench_session_scope AS scope_row
      WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SOURCE_BUILD_ERROR'
        AND (p_session_id IS NULL OR scope_row.session_id = p_session_id)
        AND (p_candidate_id IS NULL OR scope_row.candidate_id = p_candidate_id)
      ORDER BY scope_row.updated_at_utc ASC, scope_row.id ASC
      LIMIT GREATEST(v_limit - v_processed_count, 0)
      FOR UPDATE OF scope_row SKIP LOCKED
    ), zero_bad_scope AS (
      SELECT
        zero_poisoned_scope.*,
        bad_job.id AS bad_job_id,
        bad_job.job_type AS bad_job_type,
        bad_job.status AS bad_job_status,
        bad_job.attempt_count AS bad_job_attempt_count,
        bad_job.max_attempts AS bad_job_max_attempts,
        bad_job.dedupe_key AS bad_job_dedupe_key,
        COALESCE(bad_job.payload_json, '{}'::jsonb) AS bad_job_payload_json,
        bad_job.last_error_json AS bad_job_last_error_json,
        bad_job.created_at_utc AS bad_job_created_at_utc,
        bad_job.updated_at_utc AS bad_job_updated_at_utc,
        bad_job.failed_at_utc AS bad_job_failed_at_utc,
        target_session.version AS target_session_version,
        target_session.session_signature AS target_session_signature,
        target_session.source_snapshot_run_id AS target_source_snapshot_run_id,
        COALESCE(app_counter.seq, 0)::bigint AS live_candidate_change_seq,
        NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') AS bad_source_build_run_id_text,
        COALESCE(
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.last_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (bad_job.last_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          0
        ) AS source_rows_marked_error_count,
        NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_session_id',
          bad_job.payload_json->>'clone_from_session_id',
          bad_job.payload_json#>>'{source_build,source_session_id}',
          bad_job.payload_json#>>'{source_build,clone_from_session_id}',
          zero_poisoned_scope.scope_error_json->>'source_session_id',
          zero_poisoned_scope.scope_error_json->>'clone_from_session_id',
          ''
        )), '') AS source_session_id_text,
        COALESCE(
          CASE WHEN COALESCE(bad_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(bad_job.payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json#>>'{source_build,source_change_seq}')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (zero_poisoned_scope.scope_error_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
          COALESCE(app_counter.seq, 0)::bigint,
          0::bigint
        ) AS repaired_source_change_seq,
        COALESCE(
          CASE WHEN COALESCE(bad_job.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json->>'session_version')::bigint ELSE NULL::bigint END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{source_build,session_version}', '') ~ '^[0-9]{1,18}$' THEN (bad_job.payload_json#>>'{source_build,session_version}')::bigint ELSE NULL::bigint END,
          target_session.version,
          1::bigint
        ) AS repaired_session_version,
        COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
          bad_job.payload_json->>'refresh_scope_kind',
          bad_job.payload_json#>>'{source_build,refresh_scope_kind}',
          zero_poisoned_scope.scope_error_json->>'refresh_scope_kind',
          ''
        ))), ''), 'CANDIDATE_FULL_LIVE') AS repaired_refresh_scope_kind,
        COALESCE(NULLIF(UPPER(BTRIM(COALESCE(
          bad_job.payload_json->>'pay_channel_scope',
          bad_job.payload_json#>>'{source_build,pay_channel_scope}',
          zero_poisoned_scope.scope_error_json->>'pay_channel_scope',
          ''
        ))), ''), 'ALL') AS repaired_pay_channel_scope,
        COALESCE(NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'fallback_reason',
          bad_job.payload_json->>'refresh_reason',
          bad_job.payload_json->>'reason',
          bad_job.payload_json#>>'{source_build,reason}',
          zero_poisoned_scope.scope_error_json->>'reason',
          ''
        )), ''), 'CLONE_REBASE_INELIGIBLE') AS repaired_reason
      FROM zero_poisoned_scope
      JOIN LATERAL (
        SELECT zero_poisoned_scope.bad_job_id_text::uuid AS bad_job_id
        WHERE zero_poisoned_scope.bad_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS bad_job_id ON true
      JOIN public.banking_pay_workbench_jobs AS bad_job
        ON bad_job.id = bad_job_id.bad_job_id
      JOIN public.banking_pay_workbench_sessions AS target_session
        ON target_session.id = zero_poisoned_scope.session_id
      LEFT JOIN public.app_change_counters AS app_counter
        ON app_counter.entity_key = 'pay_candidate:' || zero_poisoned_scope.candidate_id::text
      WHERE bad_job.session_id = zero_poisoned_scope.session_id
        AND bad_job.candidate_id = zero_poisoned_scope.candidate_id
        AND UPPER(BTRIM(COALESCE(bad_job.job_type, ''))) IN (
          'WORKBENCH_CANDIDATE_SOURCE_BUILD',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
          'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
          'CANDIDATE_SOURCE_BUILD',
          'CANDIDATE_SOURCE_BUILD_CHUNK',
          'SOURCE_BUILD',
          'SOURCE_BUILD_PAGE'
        )
        AND UPPER(BTRIM(COALESCE(bad_job.status, ''))) IN ('FAILED', 'DEAD')
        AND NULLIF(BTRIM(COALESCE(
          bad_job.payload_json->>'source_build_run_id',
          bad_job.payload_json#>>'{source_build,source_build_run_id}',
          bad_job.payload_json#>>'{source_build,run_id}',
          bad_job.payload_json#>>'{cursor,source_build_run_id}',
          bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
          bad_job.payload_json#>>'{result_json,source_build_run_id}',
          ''
        )), '') IS NULL
        AND (
          COALESCE(bad_job.last_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
          OR COALESCE(zero_poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
          OR COALESCE(bad_job.payload_json, '{}'::jsonb)::text ILIKE '%CLONE_REBASE_INELIGIBLE_SOURCE_BUILD%'
          OR COALESCE(zero_poisoned_scope.scope_error_json, '{}'::jsonb)::text ILIKE '%CLONE_REBASE_INELIGIBLE_SOURCE_BUILD%'
        )
        AND COALESCE(
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (zero_poisoned_scope.scope_error_json#>>'{job_error_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.last_error_json->>'source_rows_marked_error_count', '') ~ '^[0-9]+$' THEN (bad_job.last_error_json->>'source_rows_marked_error_count')::integer ELSE NULL::integer END,
          CASE WHEN COALESCE(bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}', '') ~ '^[0-9]+$' THEN (bad_job.payload_json#>>'{last_failure_json,source_rows_marked_error_count}')::integer ELSE NULL::integer END,
          0
        ) = 0
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_source_lines AS error_source_line
          WHERE error_source_line.session_id = zero_poisoned_scope.session_id
            AND error_source_line.candidate_id = zero_poisoned_scope.candidate_id
            AND UPPER(BTRIM(COALESCE(error_source_line.status, ''))) = 'ERROR'
        )
    ), zero_authority AS (
      SELECT
        zero_bad_scope.*,
        source_session.id AS source_session_id,
        source_session.version AS source_session_version,
        source_session.session_signature AS source_session_signature,
        source_session.source_snapshot_run_id AS source_snapshot_run_id,
        COALESCE(targeted_ids.targeted_timesheet_ids_json, '[]'::jsonb) AS targeted_timesheet_ids_json,
        COALESCE(linked_ids.linked_timesheet_ids_json, '[]'::jsonb) AS linked_timesheet_ids_json,
        CASE
          WHEN zero_bad_scope.source_session_id_text IS NULL THEN true
          WHEN zero_bad_scope.source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
               AND source_session.id IS NOT NULL THEN true
          ELSE false
        END AS authority_ok,
        CASE
          WHEN zero_bad_scope.source_session_id_text IS NOT NULL
               AND zero_bad_scope.source_session_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN 'ZERO_SOURCE_ROW_REPAIR_INVALID_SOURCE_SESSION_ID'
          WHEN zero_bad_scope.source_session_id_text IS NOT NULL
               AND source_session.id IS NULL
            THEN 'ZERO_SOURCE_ROW_REPAIR_SOURCE_SESSION_NOT_FOUND'
          WHEN zero_bad_scope.target_session_signature IS NULL
               OR zero_bad_scope.target_source_snapshot_run_id IS NULL
            THEN 'ZERO_SOURCE_ROW_REPAIR_INSUFFICIENT_SOURCE_BUILD_AUTHORITY'
          ELSE NULL::text
        END AS authority_skip_reason
      FROM zero_bad_scope
      LEFT JOIN public.banking_pay_workbench_sessions AS source_session
        ON source_session.id = CASE
          WHEN zero_bad_scope.source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN zero_bad_scope.source_session_id_text::uuid
          ELSE NULL::uuid
        END
      CROSS JOIN LATERAL (
        SELECT COALESCE(jsonb_agg(targeted_sorted.timesheet_id_text ORDER BY targeted_sorted.timesheet_id_text), '[]'::jsonb) AS targeted_timesheet_ids_json
        FROM (
          SELECT DISTINCT targeted_raw.timesheet_id_text
          FROM (
            SELECT NULLIF(BTRIM(targeted_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'targeted_timesheet_ids') = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'targeted_timesheet_ids'
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'targeted_timesheet_ids') = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->>'targeted_timesheet_ids')
                ELSE '[]'::jsonb
              END
            ) AS targeted_value(value)
            UNION ALL
            SELECT NULLIF(BTRIM(targeted_nested_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,targeted_timesheet_ids}')) = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,targeted_timesheet_ids}'
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,targeted_timesheet_ids}')) = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>>'{source_build,targeted_timesheet_ids}')
                ELSE '[]'::jsonb
              END
            ) AS targeted_nested_value(value)
          ) AS targeted_raw
          WHERE targeted_raw.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) AS targeted_sorted
      ) AS targeted_ids
      CROSS JOIN LATERAL (
        SELECT COALESCE(jsonb_agg(linked_sorted.timesheet_id_text ORDER BY linked_sorted.timesheet_id_text), '[]'::jsonb) AS linked_timesheet_ids_json
        FROM (
          SELECT DISTINCT linked_raw.timesheet_id_text
          FROM (
            SELECT NULLIF(BTRIM(linked_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'linked_timesheet_ids') = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'linked_timesheet_ids'
                WHEN jsonb_typeof(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->'linked_timesheet_ids') = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)->>'linked_timesheet_ids')
                ELSE '[]'::jsonb
              END
            ) AS linked_value(value)
            UNION ALL
            SELECT NULLIF(BTRIM(linked_nested_value.value), '') AS timesheet_id_text
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,linked_timesheet_ids}')) = 'array'
                  THEN COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,linked_timesheet_ids}'
                WHEN jsonb_typeof((COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>'{source_build,linked_timesheet_ids}')) = 'string'
                  THEN jsonb_build_array(COALESCE(zero_bad_scope.bad_job_payload_json, '{}'::jsonb)#>>'{source_build,linked_timesheet_ids}')
                ELSE '[]'::jsonb
              END
            ) AS linked_nested_value(value)
          ) AS linked_raw
          WHERE linked_raw.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ) AS linked_sorted
      ) AS linked_ids
    )
    SELECT *
    FROM zero_authority
  LOOP
    v_processed_count := v_processed_count + 1;
    v_progress_recompute_json := '{}'::jsonb;
    v_progress_recompute_failed := false;
    v_progress_recompute_error_json := NULL::jsonb;
    v_zero_corrected_job_id := NULL::uuid;
    v_zero_corrected_job_status := NULL::text;
    v_zero_corrected_job_payload_json := '{}'::jsonb;
    v_zero_existing_corrected_failed_job_id := NULL::uuid;
    v_zero_corrected_job_action := NULL::text;
    v_zero_source_change_seq := COALESCE(v_zero_repair_row.repaired_source_change_seq, 0);
    v_zero_session_version := COALESCE(v_zero_repair_row.repaired_session_version, v_zero_repair_row.target_session_version, 1);
    v_zero_refresh_scope_kind := COALESCE(NULLIF(UPPER(BTRIM(v_zero_repair_row.repaired_refresh_scope_kind)), ''), 'CANDIDATE_FULL_LIVE');
    v_zero_pay_channel_scope := COALESCE(NULLIF(UPPER(BTRIM(v_zero_repair_row.repaired_pay_channel_scope)), ''), 'ALL');
    v_zero_reason := COALESCE(NULLIF(BTRIM(v_zero_repair_row.repaired_reason), ''), 'CLONE_REBASE_INELIGIBLE');
    v_zero_source_session_id := v_zero_repair_row.source_session_id;
    v_zero_source_session_id_text := v_zero_repair_row.source_session_id_text;
    v_zero_source_session_version := v_zero_repair_row.source_session_version;
    v_zero_source_session_signature := v_zero_repair_row.source_session_signature;
    v_zero_source_snapshot_run_id := v_zero_repair_row.source_snapshot_run_id;
    v_zero_targeted_timesheet_ids_json := COALESCE(v_zero_repair_row.targeted_timesheet_ids_json, '[]'::jsonb);
    v_zero_linked_timesheet_ids_json := COALESCE(v_zero_repair_row.linked_timesheet_ids_json, '[]'::jsonb);

    IF COALESCE(v_zero_repair_row.authority_ok, false) IS NOT TRUE THEN
      v_skipped_count := v_skipped_count + 1;
      v_zero_source_row_skips_json := v_zero_source_row_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'reason', COALESCE(v_zero_repair_row.authority_skip_reason, 'ZERO_SOURCE_ROW_REPAIR_INSUFFICIENT_SOURCE_BUILD_AUTHORITY'),
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'reason', COALESCE(v_zero_repair_row.authority_skip_reason, 'ZERO_SOURCE_ROW_REPAIR_INSUFFICIENT_SOURCE_BUILD_AUTHORITY'),
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    v_zero_source_build_seed_text := concat_ws(
      ':',
      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
      'ZERO_SOURCE_ROW_POISON_REPAIR',
      'target_session_id', v_zero_repair_row.session_id::text,
      'target_session_version', COALESCE(v_zero_session_version, 1)::text,
      'target_session_signature', COALESCE(v_zero_repair_row.target_session_signature, ''),
      'target_snapshot_run_id', COALESCE(v_zero_repair_row.target_source_snapshot_run_id::text, ''),
      'source_session_id', COALESCE(v_zero_source_session_id::text, COALESCE(v_zero_source_session_id_text, '')),
      'source_session_version', COALESCE(v_zero_source_session_version::text, ''),
      'source_session_signature', COALESCE(v_zero_source_session_signature, ''),
      'source_snapshot_run_id', COALESCE(v_zero_source_snapshot_run_id::text, ''),
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'source_change_seq', COALESCE(v_zero_source_change_seq, 0)::text,
      'refresh_scope_kind', v_zero_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb)::text,
      'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb)::text,
      'pay_channel_scope', v_zero_pay_channel_scope,
      'clone_from_session_id', COALESCE(v_zero_source_session_id::text, COALESCE(v_zero_source_session_id_text, '')),
      'clone_to_session_id', v_zero_repair_row.session_id::text,
      'reason', v_zero_reason
    );
    v_zero_source_build_hash := md5(v_zero_source_build_seed_text);
    v_zero_source_build_run_id := (
      substr(v_zero_source_build_hash, 1, 8) || '-' ||
      substr(v_zero_source_build_hash, 9, 4) || '-' ||
      substr(v_zero_source_build_hash, 13, 4) || '-' ||
      substr(v_zero_source_build_hash, 17, 4) || '-' ||
      substr(v_zero_source_build_hash, 21, 12)
    )::uuid;
    v_zero_corrected_dedupe_key := 'WORKBENCH_CANDIDATE_SOURCE_BUILD:session:' || v_zero_repair_row.session_id::text || ':candidate:' || v_zero_repair_row.candidate_id::text || ':clone_ineligible:corrected:' || v_zero_source_build_run_id::text;

    v_zero_corrected_payload_json := jsonb_strip_nulls(
      jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'session_version', v_zero_session_version,
        'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
        'source_change_sequence', COALESCE(v_zero_source_change_seq, 0),
        'source_build_run_id', v_zero_source_build_run_id::text,
        'operation_type', 'CLONE_REBASE_INELIGIBLE_SOURCE_BUILD',
        'fallback_reason', v_zero_reason,
        'refresh_reason', v_zero_reason,
        'reason', v_zero_reason,
        'refresh_scope_kind', v_zero_refresh_scope_kind,
        'pay_channel_scope', v_zero_pay_channel_scope,
        'source_snapshot_run_id', v_zero_repair_row.target_source_snapshot_run_id::text,
        'snapshot_run_id', v_zero_repair_row.target_source_snapshot_run_id::text,
        'source_session_id', CASE WHEN v_zero_source_session_id IS NULL THEN NULL ELSE v_zero_source_session_id::text END,
        'clone_from_session_id', COALESCE(v_zero_source_session_id::text, v_zero_source_session_id_text),
        'clone_to_session_id', v_zero_repair_row.session_id::text,
        'target_session_signature', v_zero_repair_row.target_session_signature,
        'source_session_signature', v_zero_source_session_signature,
        'force_legacy', true,
        'source_build_required', true,
        'line_work_required', true,
        'delta_refresh_required', false
      )
      || jsonb_build_object(
        'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb),
        'zero_source_row_poison_repair', true,
        'zero_source_row_bad_job_id', v_zero_repair_row.bad_job_id::text,
        'zero_source_row_original_dedupe_key', v_zero_repair_row.bad_job_dedupe_key,
        'source_build_run_id_source', jsonb_build_object(
          'method', 'DETERMINISTIC_MD5_UUID_FROM_AUTHORITY_INPUTS',
          'seed_text', v_zero_source_build_seed_text,
          'target_session_id', v_zero_repair_row.session_id::text,
          'target_session_version', v_zero_session_version,
          'target_session_signature', v_zero_repair_row.target_session_signature,
          'target_snapshot_run_id', v_zero_repair_row.target_source_snapshot_run_id::text,
          'source_session_id', CASE WHEN v_zero_source_session_id IS NULL THEN NULL ELSE v_zero_source_session_id::text END,
          'source_session_version', v_zero_source_session_version,
          'source_session_signature', v_zero_source_session_signature,
          'source_snapshot_run_id', CASE WHEN v_zero_source_snapshot_run_id IS NULL THEN NULL ELSE v_zero_source_snapshot_run_id::text END,
          'candidate_id', v_zero_repair_row.candidate_id::text,
          'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
          'refresh_scope_kind', v_zero_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb),
          'pay_channel_scope', v_zero_pay_channel_scope,
          'clone_from_session_id', COALESCE(v_zero_source_session_id::text, v_zero_source_session_id_text),
          'clone_to_session_id', v_zero_repair_row.session_id::text
        )
      )
      || jsonb_build_object(
        'source_build', jsonb_build_object(
          'required', true,
          'run_id', v_zero_source_build_run_id::text,
          'source_build_run_id', v_zero_source_build_run_id::text,
          'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
          'source_change_sequence', COALESCE(v_zero_source_change_seq, 0),
          'session_version', v_zero_session_version,
          'refresh_scope_kind', v_zero_refresh_scope_kind,
          'pay_channel_scope', v_zero_pay_channel_scope,
          'targeted_timesheet_ids', COALESCE(v_zero_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_zero_linked_timesheet_ids_json, '[]'::jsonb),
          'reason', v_zero_reason
        ),
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      )
    );

    SELECT corrected_job.id,
           corrected_job.status,
           COALESCE(corrected_job.payload_json, '{}'::jsonb)
    INTO v_zero_corrected_job_id,
         v_zero_corrected_job_status,
         v_zero_corrected_job_payload_json
    FROM public.banking_pay_workbench_jobs AS corrected_job
    WHERE corrected_job.session_id = v_zero_repair_row.session_id
      AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
      AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
      AND corrected_job.status IN ('QUEUED', 'RUNNING')
    ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 ELSE 1 END,
             corrected_job.updated_at_utc DESC NULLS LAST,
             corrected_job.created_at_utc DESC NULLS LAST,
             corrected_job.id DESC
    LIMIT 1
    FOR UPDATE SKIP LOCKED;

    IF v_zero_corrected_job_id IS NOT NULL THEN
      v_zero_corrected_job_action := 'REUSED_ACTIVE_CORRECTED_SOURCE_BUILD_JOB';
      v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
    ELSE
      SELECT corrected_job.id,
             corrected_job.status,
             COALESCE(corrected_job.payload_json, '{}'::jsonb)
      INTO v_zero_corrected_job_id,
           v_zero_corrected_job_status,
           v_zero_corrected_job_payload_json
      FROM public.banking_pay_workbench_jobs AS corrected_job
      WHERE corrected_job.session_id = v_zero_repair_row.session_id
        AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
        AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
        AND corrected_job.status IN ('QUEUED', 'RUNNING')
      ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 ELSE 1 END,
               corrected_job.updated_at_utc DESC NULLS LAST,
               corrected_job.created_at_utc DESC NULLS LAST,
               corrected_job.id DESC
      LIMIT 1;

      IF v_zero_corrected_job_id IS NOT NULL THEN
        v_zero_corrected_job_action := 'REUSED_ACTIVE_CORRECTED_SOURCE_BUILD_JOB_NOT_LOCKED';
        v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
      ELSE
        SELECT corrected_job.id,
               corrected_job.status,
               COALESCE(corrected_job.payload_json, '{}'::jsonb)
        INTO v_zero_corrected_job_id,
             v_zero_corrected_job_status,
             v_zero_corrected_job_payload_json
        FROM public.banking_pay_workbench_jobs AS corrected_job
        WHERE corrected_job.session_id = v_zero_repair_row.session_id
          AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
          AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
          AND corrected_job.status = 'SUCCEEDED'
        ORDER BY corrected_job.completed_at_utc DESC NULLS LAST,
                 corrected_job.updated_at_utc DESC NULLS LAST,
                 corrected_job.created_at_utc DESC NULLS LAST,
                 corrected_job.id DESC
        LIMIT 1;

        IF v_zero_corrected_job_id IS NOT NULL THEN
          v_zero_corrected_job_action := 'REUSED_SUCCEEDED_CORRECTED_SOURCE_BUILD_JOB';
          v_corrected_source_build_job_succeeded_reused_count := v_corrected_source_build_job_succeeded_reused_count + 1;
        ELSE
          SELECT corrected_job.id
          INTO v_zero_existing_corrected_failed_job_id
          FROM public.banking_pay_workbench_jobs AS corrected_job
          CROSS JOIN LATERAL (
            SELECT NULLIF(BTRIM(COALESCE(
              corrected_job.payload_json->>'source_build_run_id',
              corrected_job.payload_json#>>'{source_build,source_build_run_id}',
              corrected_job.payload_json#>>'{source_build,run_id}',
              corrected_job.payload_json#>>'{cursor,source_build_run_id}',
              corrected_job.payload_json#>>'{cursor_json,source_build_run_id}',
              corrected_job.payload_json#>>'{result_json,source_build_run_id}',
              ''
            )), '') AS source_build_run_id_text
          ) AS corrected_extract
          WHERE corrected_job.session_id = v_zero_repair_row.session_id
            AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
            AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
            AND corrected_job.status IN ('FAILED', 'DEAD')
            AND corrected_extract.source_build_run_id_text = v_zero_source_build_run_id::text
          ORDER BY corrected_job.updated_at_utc DESC NULLS LAST,
                   corrected_job.created_at_utc DESC NULLS LAST,
                   corrected_job.id DESC
          LIMIT 1;

          IF v_zero_existing_corrected_failed_job_id IS NOT NULL THEN
            v_skipped_count := v_skipped_count + 1;
            v_zero_source_row_skips_json := v_zero_source_row_skips_json || jsonb_build_array(jsonb_build_object(
              'session_id', v_zero_repair_row.session_id::text,
              'candidate_id', v_zero_repair_row.candidate_id::text,
              'bad_job_id', v_zero_repair_row.bad_job_id::text,
              'corrected_failed_job_id', v_zero_existing_corrected_failed_job_id::text,
              'corrected_source_build_run_id', v_zero_source_build_run_id::text,
              'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ALREADY_FAILED_OR_DEAD',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ));
            v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
              'session_id', v_zero_repair_row.session_id::text,
              'candidate_id', v_zero_repair_row.candidate_id::text,
              'bad_job_id', v_zero_repair_row.bad_job_id::text,
              'corrected_failed_job_id', v_zero_existing_corrected_failed_job_id::text,
              'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ALREADY_FAILED_OR_DEAD',
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            ));
            CONTINUE;
          END IF;

          INSERT INTO public.banking_pay_workbench_jobs (
            job_type,
            status,
            priority,
            run_at_utc,
            dedupe_key,
            snapshot_run_id,
            session_id,
            candidate_id,
            payload_json,
            economic_build_id,
            private_stage,
            private_cursor_kind,
            private_cursor_json,
            private_stage_version,
            created_at_utc,
            updated_at_utc
          )
          VALUES (
            'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'QUEUED',
            60,
            v_now,
            v_zero_corrected_dedupe_key,
            v_zero_repair_row.target_source_snapshot_run_id,
            v_zero_repair_row.session_id,
            v_zero_repair_row.candidate_id,
            v_zero_corrected_payload_json,
            NULL::uuid,
            'BUILD_INITIALISE',
            'BUILD_INITIALISE',
            '{}'::jsonb,
            1,
            v_now,
            v_now
          )
          ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
          DO UPDATE
          SET run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
              priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
              payload_json = jsonb_strip_nulls(COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || EXCLUDED.payload_json),
              updated_at_utc = v_now
          WHERE public.banking_pay_workbench_jobs.status = 'QUEUED'
          RETURNING id, status, payload_json
          INTO v_zero_corrected_job_id, v_zero_corrected_job_status, v_zero_corrected_job_payload_json;

          IF v_zero_corrected_job_id IS NOT NULL THEN
            v_zero_corrected_job_action := 'QUEUED_CORRECTED_SOURCE_BUILD_JOB';
            v_corrected_source_build_job_queued_count := v_corrected_source_build_job_queued_count + 1;
          ELSE
            SELECT corrected_job.id,
                   corrected_job.status,
                   COALESCE(corrected_job.payload_json, '{}'::jsonb)
            INTO v_zero_corrected_job_id,
                 v_zero_corrected_job_status,
                 v_zero_corrected_job_payload_json
            FROM public.banking_pay_workbench_jobs AS corrected_job
            WHERE corrected_job.session_id = v_zero_repair_row.session_id
              AND corrected_job.candidate_id = v_zero_repair_row.candidate_id
              AND corrected_job.dedupe_key = v_zero_corrected_dedupe_key
              AND corrected_job.status IN ('QUEUED', 'RUNNING', 'SUCCEEDED')
            ORDER BY CASE WHEN corrected_job.status = 'QUEUED' THEN 0 WHEN corrected_job.status = 'RUNNING' THEN 1 ELSE 2 END,
                     corrected_job.updated_at_utc DESC NULLS LAST,
                     corrected_job.created_at_utc DESC NULLS LAST,
                     corrected_job.id DESC
            LIMIT 1;

            IF v_zero_corrected_job_id IS NOT NULL THEN
              v_zero_corrected_job_action := 'REUSED_CORRECTED_SOURCE_BUILD_JOB_AFTER_CONFLICT';
              IF v_zero_corrected_job_status = 'SUCCEEDED' THEN
                v_corrected_source_build_job_succeeded_reused_count := v_corrected_source_build_job_succeeded_reused_count + 1;
              ELSE
                v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
              END IF;
            END IF;
          END IF;
        END IF;
      END IF;
    END IF;

    IF v_zero_corrected_job_id IS NULL THEN
      v_skipped_count := v_skipped_count + 1;
      v_zero_source_row_skips_json := v_zero_source_row_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'corrected_source_build_run_id', v_zero_source_build_run_id::text,
        'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ENQUEUE_FAILED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      v_skips_json := v_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'reason', 'ZERO_SOURCE_ROW_CORRECTED_JOB_ENQUEUE_FAILED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    SELECT jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', bad_job.id::text,
      'job_type', bad_job.job_type,
      'status', bad_job.status,
      'attempt_count', bad_job.attempt_count,
      'max_attempts', bad_job.max_attempts,
      'dedupe_key', bad_job.dedupe_key,
      'payload_json', bad_job.payload_json,
      'last_error_json', bad_job.last_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_bad_job_before_json
    FROM public.banking_pay_workbench_jobs AS bad_job
    WHERE bad_job.id = v_zero_repair_row.bad_job_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_jobs AS bad_job_update
    SET payload_json = jsonb_strip_nulls(
          COALESCE(bad_job_update.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'invalid_source_build_without_run_id_failed_closed', true,
            'invalid_source_build_without_run_id_non_blocking', true,
            'non_blocking_terminal_failure', true,
            'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'non_blocking_terminal_failure_at_utc', v_now::text,
            'zero_source_row_repair_resolved', true,
            'zero_source_row_repair_resolved_at_utc', v_now::text,
            'zero_source_row_corrected_job_id', v_zero_corrected_job_id::text,
            'zero_source_row_corrected_source_build_run_id', v_zero_source_build_run_id::text,
            'zero_source_row_corrected_dedupe_key', v_zero_corrected_dedupe_key,
            'source_rows_marked_error_count', COALESCE(v_zero_repair_row.source_rows_marked_error_count, 0),
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        ),
        updated_at_utc = v_now
    WHERE bad_job_update.id = v_zero_repair_row.bad_job_id
    RETURNING jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', bad_job_update.id::text,
      'job_type', bad_job_update.job_type,
      'status', bad_job_update.status,
      'retained_terminal', true,
      'hard_deleted', false,
      'bad_job_mutated', true,
      'zero_source_row_repair_resolved', true,
      'non_blocking_terminal_failure', true,
      'invalid_source_build_without_run_id_non_blocking', true,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'corrected_dedupe_key', v_zero_corrected_dedupe_key,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_bad_job_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_zero_repair_row.bad_job_id::text,
      'ZERO_SOURCE_ROW_BAD_JOB_MARKED_NON_BLOCKING',
      v_zero_bad_job_before_json,
      v_zero_bad_job_after_json,
      'ZERO_SOURCE_ROW_INVALID_SOURCE_BUILD_WITHOUT_RUN_ID_FAILED_CLOSED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', corrected_job.id::text,
      'job_type', corrected_job.job_type,
      'status', corrected_job.status,
      'dedupe_key', corrected_job.dedupe_key,
      'session_id', CASE WHEN corrected_job.session_id IS NULL THEN NULL ELSE corrected_job.session_id::text END,
      'candidate_id', CASE WHEN corrected_job.candidate_id IS NULL THEN NULL ELSE corrected_job.candidate_id::text END,
      'source_build_run_id', v_zero_source_build_run_id::text,
      'payload_json', corrected_job.payload_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_corrected_job_after_json
    FROM public.banking_pay_workbench_jobs AS corrected_job
    WHERE corrected_job.id = v_zero_corrected_job_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_zero_corrected_job_id::text,
      COALESCE(v_zero_corrected_job_action, 'CORRECTED_SOURCE_BUILD_JOB_REUSED'),
      v_zero_corrected_job_before_json,
      v_zero_corrected_job_after_json,
      'ZERO_SOURCE_ROW_CORRECTED_SOURCE_BUILD_JOB_READY',
      NULL
    );

    SELECT jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'seeded', scope_row.seeded,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_scope_before_json
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.id = v_zero_repair_row.scope_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_session_scope AS scope_row
    SET status = 'SOURCE_BUILD_PENDING',
        pending_job_id = v_zero_corrected_job_id,
        seeded = false,
        dirty = true,
        error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE scope_row.id = v_zero_repair_row.scope_id
      AND scope_row.session_id = v_zero_repair_row.session_id
      AND scope_row.candidate_id = v_zero_repair_row.candidate_id
    RETURNING jsonb_build_object(
      'id', scope_row.id::text,
      'session_id', scope_row.session_id::text,
      'candidate_id', scope_row.candidate_id::text,
      'status', scope_row.status,
      'dirty', scope_row.dirty,
      'seeded', scope_row.seeded,
      'pending_job_id', CASE WHEN scope_row.pending_job_id IS NULL THEN NULL ELSE scope_row.pending_job_id::text END,
      'error_json', scope_row.error_json,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_scope_after_json;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_scope',
      v_zero_repair_row.candidate_id::text,
      'ZERO_SOURCE_ROW_SOURCE_BUILD_POISON_REPAIRED',
      v_zero_scope_before_json,
      v_zero_scope_after_json,
      'ZERO_SOURCE_ROW_SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'scope_failed_count', session_row.scope_failed_count,
      'scope_pending_count', session_row.scope_pending_count,
      'scope_ready_count', session_row.scope_ready_count,
      'blocker_codes', COALESCE(session_row.progress_json->'blocker_codes', '[]'::jsonb),
      'draft_blocker_codes', COALESCE(session_row.progress_json->'draft_blocker_codes', '[]'::jsonb),
      'session_blocker_codes', COALESCE(session_row.progress_json->'session_blocker_codes', '[]'::jsonb),
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_zero_session_before_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_zero_repair_row.session_id
    FOR UPDATE;

    UPDATE public.banking_pay_workbench_sessions AS session_row
    SET progress_state = 'REFRESHING_CANDIDATES',
        progress_json = jsonb_strip_nulls(
          public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true)
          - 'last_source_build_failure_at_utc'
          - 'last_source_build_failure_job_id'
          - 'last_source_build_failure_code'
          - 'last_source_build_failure_source_build_run_id'
          - 'last_source_build_source_rows_marked_error_count'
          - 'blocker_codes'
          - 'draft_blocker_codes'
          - 'session_blocker_codes'
        ),
        progress_counter_version = COALESCE(session_row.progress_counter_version, 0) + 1,
        progress_updated_at_utc = v_now,
        updated_at_utc = v_now
    WHERE session_row.id = v_zero_repair_row.session_id;

    BEGIN
      v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_zero_repair_row.session_id,
        p_apply => true,
        p_reason => 'ZERO_SOURCE_ROW_SOURCE_BUILD_POISON_REPAIRED',
        p_write_progress_json => true
      );
    EXCEPTION WHEN OTHERS THEN
      v_progress_recompute_failed := true;
      v_progress_recompute_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_zero_repair_row.session_id::text,
        'candidate_id', v_zero_repair_row.candidate_id::text,
        'bad_job_id', v_zero_repair_row.bad_job_id::text,
        'corrected_source_build_job_id', v_zero_corrected_job_id::text,
        'corrected_source_build_run_id', v_zero_source_build_run_id::text,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
      v_progress_recompute_json := COALESCE(v_progress_recompute_error_json, '{}'::jsonb);
    END;

    SELECT session_row.progress_state,
           session_row.scope_failed_count,
           session_row.scope_pending_count,
           jsonb_build_object(
             'id', session_row.id::text,
             'status', session_row.status,
             'progress_state', session_row.progress_state,
             'scope_failed_count', session_row.scope_failed_count,
             'scope_pending_count', session_row.scope_pending_count,
             'scope_ready_count', session_row.scope_ready_count,
             'blocker_codes', COALESCE(session_row.progress_json->'blocker_codes', '[]'::jsonb),
             'draft_blocker_codes', COALESCE(session_row.progress_json->'draft_blocker_codes', '[]'::jsonb),
             'session_blocker_codes', COALESCE(session_row.progress_json->'session_blocker_codes', '[]'::jsonb),
             'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
             'bad_job_id', v_zero_repair_row.bad_job_id::text,
             'corrected_source_build_job_id', v_zero_corrected_job_id::text,
             'corrected_source_build_run_id', v_zero_source_build_run_id::text,
             'recompute_failed', v_progress_recompute_failed,
             'recompute_json', COALESCE(v_progress_recompute_json, '{}'::jsonb),
             'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
           )
    INTO v_post_recompute_progress_state,
         v_post_recompute_scope_failed_count,
         v_post_recompute_scope_pending_count,
         v_zero_session_after_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_zero_repair_row.session_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      v_zero_repair_row.session_id::text,
      'ZERO_SOURCE_ROW_PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      v_zero_session_before_json,
      v_zero_session_after_json,
      'ZERO_SOURCE_ROW_PROGRESS_REPAIRED_AFTER_SOURCE_BUILD_POISON',
      NULL
    );

    v_zero_source_row_repaired_count := v_zero_source_row_repaired_count + 1;
    v_repaired_count := v_repaired_count + 1;
    v_repaired_scope_count := v_repaired_scope_count + 1;
    v_repaired_session_count := v_repaired_session_count + 1;

    v_zero_source_row_repairs_json := v_zero_source_row_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_job_status', v_zero_corrected_job_status,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'corrected_dedupe_key', v_zero_corrected_dedupe_key,
      'source_change_seq', COALESCE(v_zero_source_change_seq, 0),
      'scope_repaired', true,
      'session_progress_repaired', true,
      'progress_recompute_failed', v_progress_recompute_failed,
      'post_recompute_progress_state', v_post_recompute_progress_state,
      'post_recompute_scope_failed_count', v_post_recompute_scope_failed_count,
      'post_recompute_scope_pending_count', v_post_recompute_scope_pending_count,
      'corrected_job_action', v_zero_corrected_job_action,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));

    v_repairs_json := v_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_zero_repair_row.session_id::text,
      'candidate_id', v_zero_repair_row.candidate_id::text,
      'bad_job_id', v_zero_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_zero_corrected_job_id::text,
      'corrected_source_build_run_id', v_zero_source_build_run_id::text,
      'zero_source_row_repair', true,
      'scope_repaired', true,
      'session_progress_repaired', true,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));
  END LOOP;

  FOR v_orphan_repair_row IN
    SELECT
      scope_row.id AS scope_id,
      scope_row.session_id,
      scope_row.candidate_id,
      scope_row.status AS scope_status,
      scope_row.pending_job_id AS bad_job_id,
      scope_row.dirty AS scope_dirty,
      scope_row.seeded AS scope_seeded,
      scope_row.error_json AS scope_error_json,
      scope_row.updated_at_utc AS scope_updated_at_utc,
      bad_job.job_type AS bad_job_type,
      bad_job.status AS bad_job_status,
      bad_job.dedupe_key AS bad_job_dedupe_key,
      COALESCE(bad_job.payload_json, '{}'::jsonb) AS bad_job_payload_json,
      bad_job.last_error_json AS bad_job_last_error_json,
      bad_job.failed_at_utc AS bad_job_failed_at_utc,
      target_session.actor_user_id AS session_actor_user_id,
      target_session.version AS session_version,
      target_session.session_signature,
      target_session.source_snapshot_run_id,
      COALESCE(app_counter.seq, 0)::bigint AS live_candidate_change_seq
    FROM public.banking_pay_workbench_session_scope AS scope_row
    JOIN public.banking_pay_workbench_jobs AS bad_job
      ON bad_job.id = scope_row.pending_job_id
    JOIN public.banking_pay_workbench_sessions AS target_session
      ON target_session.id = scope_row.session_id
    LEFT JOIN public.app_change_counters AS app_counter
      ON app_counter.entity_key = 'pay_candidate:' || scope_row.candidate_id::text
    WHERE UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(scope_row.dirty, false) IS TRUE
      AND scope_row.pending_job_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(bad_job.job_type, ''))) IN (
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
        'CANDIDATE_SOURCE_BUILD',
        'CANDIDATE_SOURCE_BUILD_CHUNK',
        'SOURCE_BUILD',
        'SOURCE_BUILD_PAGE'
      )
      AND UPPER(BTRIM(COALESCE(bad_job.status, ''))) IN ('FAILED', 'DEAD')
      AND bad_job.session_id = scope_row.session_id
      AND bad_job.candidate_id = scope_row.candidate_id
      AND NULLIF(BTRIM(COALESCE(
        bad_job.payload_json->>'source_build_run_id',
        bad_job.payload_json#>>'{source_build,source_build_run_id}',
        bad_job.payload_json#>>'{source_build,run_id}',
        bad_job.payload_json#>>'{cursor,source_build_run_id}',
        bad_job.payload_json#>>'{cursor_json,source_build_run_id}',
        bad_job.payload_json#>>'{result_json,source_build_run_id}',
        ''
      )), '') IS NULL
      AND (
        COALESCE(bad_job.last_error_json, '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
        OR COALESCE(bad_job.payload_json#>'{last_failure_json}', '{}'::jsonb)::text ILIKE '%PAY_WORKBENCH_CANDIDATE_SOURCE_BUILD_RUN_ID_REQUIRED%'
        OR (
          lower(BTRIM(COALESCE(bad_job.payload_json->>'non_blocking_terminal_failure', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND UPPER(BTRIM(COALESCE(bad_job.payload_json->>'non_blocking_terminal_failure_reason', ''))) = 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE'
        )
        OR lower(BTRIM(COALESCE(bad_job.payload_json->>'invalid_source_build_without_run_id_failed_closed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
      AND UPPER(BTRIM(COALESCE(target_session.status, ''))) = 'OPEN'
      AND target_session.discarded_at_utc IS NULL
      AND target_session.source_snapshot_run_id IS NOT NULL
      AND (p_session_id IS NULL OR scope_row.session_id = p_session_id)
      AND (p_candidate_id IS NULL OR scope_row.candidate_id = p_candidate_id)
    ORDER BY scope_row.updated_at_utc ASC, scope_row.id ASC
    LIMIT GREATEST(v_limit - v_processed_count, 0)
  LOOP
    PERFORM 1
    FROM public.banking_pay_workbench_sessions AS locked_session
    WHERE locked_session.id = v_orphan_repair_row.session_id
      AND UPPER(BTRIM(COALESCE(locked_session.status, ''))) = 'OPEN'
      AND locked_session.discarded_at_utc IS NULL
      AND locked_session.source_snapshot_run_id IS NOT NULL
    FOR UPDATE;

    IF NOT FOUND THEN
      v_skipped_count := v_skipped_count + 1;
      v_orphan_pending_skips_json := v_orphan_pending_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'reason', 'ORPHANED_PENDING_REPAIR_SESSION_NO_LONGER_OPEN',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS locked_scope
    JOIN public.banking_pay_workbench_jobs AS locked_bad_job
      ON locked_bad_job.id = locked_scope.pending_job_id
    WHERE locked_scope.id = v_orphan_repair_row.scope_id
      AND locked_scope.session_id = v_orphan_repair_row.session_id
      AND locked_scope.candidate_id = v_orphan_repair_row.candidate_id
      AND UPPER(BTRIM(COALESCE(locked_scope.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(locked_scope.dirty, false) IS TRUE
      AND locked_scope.pending_job_id = v_orphan_repair_row.bad_job_id
      AND UPPER(BTRIM(COALESCE(locked_bad_job.status, ''))) IN ('FAILED', 'DEAD')
      AND locked_bad_job.session_id = locked_scope.session_id
      AND locked_bad_job.candidate_id = locked_scope.candidate_id
    FOR UPDATE OF locked_scope, locked_bad_job;

    IF NOT FOUND THEN
      v_skipped_count := v_skipped_count + 1;
      v_orphan_pending_skips_json := v_orphan_pending_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'reason', 'ORPHANED_PENDING_REPAIR_STATE_ALREADY_CHANGED',
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    v_processed_count := v_processed_count + 1;
    v_orphan_enqueue_result := '{}'::jsonb;
    v_orphan_enqueue_error_json := NULL::jsonb;
    v_orphan_enqueue_job_id_text := NULL::text;
    v_orphan_enqueue_job_id := NULL::uuid;
    v_orphan_enqueue_job_type := NULL::text;
    v_orphan_enqueue_job_status := NULL::text;
    v_orphan_enqueue_source_build_run_id_text := NULL::text;
    v_orphan_enqueue_valid := false;
    v_progress_recompute_json := '{}'::jsonb;
    v_progress_recompute_failed := false;
    v_progress_recompute_error_json := NULL::jsonb;

    WITH targeted_arrays(value_json) AS (
      VALUES
        (v_orphan_repair_row.bad_job_payload_json->'targeted_timesheet_ids'),
        (v_orphan_repair_row.bad_job_payload_json->'targeted_timesheet_ids_requested'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,targeted_timesheet_ids}'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,targeted_timesheet_ids_requested}')
    ), targeted_values(timesheet_id_text) AS (
      SELECT NULLIF(BTRIM(targeted_value.value), '')
      FROM targeted_arrays AS targeted_array
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(targeted_array.value_json) = 'array' THEN targeted_array.value_json ELSE '[]'::jsonb END
      ) AS targeted_value(value)
    )
    SELECT COALESCE(jsonb_agg(targeted_ids.timesheet_id_text ORDER BY targeted_ids.timesheet_id_text), '[]'::jsonb)
    INTO v_orphan_targeted_timesheet_ids_json
    FROM (
      SELECT DISTINCT targeted_value.timesheet_id_text
      FROM targeted_values AS targeted_value
      WHERE targeted_value.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS targeted_ids;

    WITH linked_arrays(value_json) AS (
      VALUES
        (v_orphan_repair_row.bad_job_payload_json->'linked_timesheet_ids'),
        (v_orphan_repair_row.bad_job_payload_json->'linked_timesheet_ids_requested'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,linked_timesheet_ids}'),
        (v_orphan_repair_row.bad_job_payload_json#>'{source_build,linked_timesheet_ids_requested}')
    ), linked_values(timesheet_id_text) AS (
      SELECT NULLIF(BTRIM(linked_value.value), '')
      FROM linked_arrays AS linked_array
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(linked_array.value_json) = 'array' THEN linked_array.value_json ELSE '[]'::jsonb END
      ) AS linked_value(value)
    )
    SELECT COALESCE(jsonb_agg(linked_ids.timesheet_id_text ORDER BY linked_ids.timesheet_id_text), '[]'::jsonb)
    INTO v_orphan_linked_timesheet_ids_json
    FROM (
      SELECT DISTINCT linked_value.timesheet_id_text
      FROM linked_values AS linked_value
      WHERE linked_value.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS linked_ids;

    v_orphan_refresh_scope_kind := UPPER(BTRIM(COALESCE(
      NULLIF(v_orphan_repair_row.bad_job_payload_json->>'refresh_scope_kind', ''),
      NULLIF(v_orphan_repair_row.bad_job_payload_json#>>'{source_build,refresh_scope_kind}', ''),
      CASE
        WHEN jsonb_array_length(COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
          OR jsonb_array_length(COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb)) > 0
        THEN 'TARGETED_TIMESHEETS'
        ELSE 'CANDIDATE_FULL_LIVE'
      END
    )));

    IF v_orphan_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
      v_orphan_refresh_scope_kind := CASE
        WHEN jsonb_array_length(COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
          OR jsonb_array_length(COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb)) > 0
        THEN 'TARGETED_TIMESHEETS'
        ELSE 'CANDIDATE_FULL_LIVE'
      END;
    END IF;

    v_orphan_pay_channel_scope := UPPER(BTRIM(COALESCE(
      NULLIF(v_orphan_repair_row.bad_job_payload_json->>'pay_channel_scope', ''),
      NULLIF(v_orphan_repair_row.bad_job_payload_json#>>'{source_build,pay_channel_scope}', ''),
      'ALL'
    )));

    IF v_orphan_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
      v_orphan_pay_channel_scope := 'ALL';
    END IF;

    v_orphan_source_change_seq := COALESCE(
      CASE WHEN COALESCE(v_orphan_repair_row.bad_job_payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_orphan_repair_row.bad_job_payload_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
      CASE WHEN COALESCE(v_orphan_repair_row.bad_job_payload_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (v_orphan_repair_row.bad_job_payload_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
      v_orphan_repair_row.live_candidate_change_seq,
      0::bigint
    );

    v_orphan_scope_before_json := jsonb_build_object(
      'id', v_orphan_repair_row.scope_id::text,
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'status', v_orphan_repair_row.scope_status,
      'dirty', v_orphan_repair_row.scope_dirty,
      'seeded', v_orphan_repair_row.scope_seeded,
      'pending_job_id', v_orphan_repair_row.bad_job_id::text,
      'error_json', v_orphan_repair_row.scope_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    );

    v_orphan_bad_job_before_json := jsonb_build_object(
      'id', v_orphan_repair_row.bad_job_id::text,
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'job_type', v_orphan_repair_row.bad_job_type,
      'status', v_orphan_repair_row.bad_job_status,
      'dedupe_key', v_orphan_repair_row.bad_job_dedupe_key,
      'source_build_run_id', NULL::text,
      'last_error_json', v_orphan_repair_row.bad_job_last_error_json,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    );

    BEGIN
      v_orphan_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_orphan_repair_row.source_snapshot_run_id,
        p_candidate_id => v_orphan_repair_row.candidate_id,
        p_reason => 'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIR',
        p_actor_user_id => v_orphan_repair_row.session_actor_user_id,
        p_payload_json => jsonb_strip_nulls(
          jsonb_build_object(
            'session_id', v_orphan_repair_row.session_id::text,
            'source_session_id', v_orphan_repair_row.session_id::text,
            'source_snapshot_run_id', v_orphan_repair_row.source_snapshot_run_id::text,
            'snapshot_run_id', v_orphan_repair_row.source_snapshot_run_id::text,
            'session_version', v_orphan_repair_row.session_version,
            'session_signature', v_orphan_repair_row.session_signature,
            'force_legacy', true,
            'fallback_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'projection_class', COALESCE(NULLIF(BTRIM(v_orphan_repair_row.bad_job_payload_json->>'projection_class'), ''), 'POST_DRAFT_PATCH_COMPLEX')
          )
          || jsonb_build_object(
            'source_change_seq', COALESCE(v_orphan_source_change_seq, 0),
            'refresh_scope_kind', v_orphan_refresh_scope_kind,
            'pay_channel_scope', v_orphan_pay_channel_scope,
            'targeted_timesheet_ids', COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb),
            'linked_timesheet_ids', COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb),
            'source_build_required', true,
            'line_work_required', true,
            'delta_refresh_required', false,
            'enqueue_origin', 'PAY_WORKBENCH_REPAIR_INVALID_SOURCE_BUILD_POISON',
            'source_build_poison_repair', true,
            'invalid_source_build_bad_job_id', v_orphan_repair_row.bad_job_id::text,
            'repair_request_reason', v_reason,
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        )
      );
    EXCEPTION WHEN OTHERS THEN
      v_orphan_enqueue_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
    END;

    v_orphan_enqueue_job_id_text := NULLIF(BTRIM(COALESCE(v_orphan_enqueue_result->>'job_id', '')), '');

    IF v_orphan_enqueue_error_json IS NULL
       AND v_orphan_enqueue_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_orphan_enqueue_job_id := v_orphan_enqueue_job_id_text::uuid;

      SELECT
        successor_job.job_type,
        successor_job.status,
        NULLIF(BTRIM(COALESCE(
          successor_job.payload_json->>'source_build_run_id',
          successor_job.payload_json#>>'{source_build,source_build_run_id}',
          successor_job.payload_json#>>'{source_build,run_id}',
          ''
        )), '')
      INTO
        v_orphan_enqueue_job_type,
        v_orphan_enqueue_job_status,
        v_orphan_enqueue_source_build_run_id_text
      FROM public.banking_pay_workbench_jobs AS successor_job
      WHERE successor_job.id = v_orphan_enqueue_job_id
        AND successor_job.session_id = v_orphan_repair_row.session_id
        AND successor_job.candidate_id = v_orphan_repair_row.candidate_id
      FOR UPDATE;

      v_orphan_enqueue_valid := FOUND
        AND UPPER(BTRIM(COALESCE(v_orphan_enqueue_job_type, ''))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND UPPER(BTRIM(COALESCE(v_orphan_enqueue_job_status, ''))) IN ('QUEUED', 'RUNNING')
        AND v_orphan_enqueue_source_build_run_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
    END IF;

    IF v_orphan_enqueue_valid IS NOT TRUE THEN
      v_orphan_enqueue_error_json := COALESCE(
        v_orphan_enqueue_error_json,
        jsonb_build_object(
          'code', 'SOURCE_BUILD_POISON_REPAIR_CANONICAL_SUCCESSOR_REQUIRED',
          'session_id', v_orphan_repair_row.session_id::text,
          'candidate_id', v_orphan_repair_row.candidate_id::text,
          'bad_job_id', v_orphan_repair_row.bad_job_id::text,
          'enqueue_result', COALESCE(v_orphan_enqueue_result, '{}'::jsonb),
          'successor_job_id', v_orphan_enqueue_job_id_text,
          'successor_job_type', v_orphan_enqueue_job_type,
          'successor_job_status', v_orphan_enqueue_job_status,
          'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        )
      );

      UPDATE public.banking_pay_workbench_session_scope AS failed_scope
      SET status = 'SOURCE_BUILD_ERROR',
          dirty = true,
          pending_job_id = NULL::uuid,
          error_json = jsonb_build_object(
            'code', 'SOURCE_BUILD_POISON_REPAIR_CANONICAL_SUCCESSOR_REQUIRED',
            'job_id', v_orphan_repair_row.bad_job_id::text,
            'repair_error_json', v_orphan_enqueue_error_json,
            'reason', v_reason,
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          ),
          updated_at_utc = v_now
      WHERE failed_scope.id = v_orphan_repair_row.scope_id
        AND failed_scope.session_id = v_orphan_repair_row.session_id
        AND failed_scope.candidate_id = v_orphan_repair_row.candidate_id
        AND (
          failed_scope.pending_job_id = v_orphan_repair_row.bad_job_id
          OR (v_orphan_enqueue_job_id IS NOT NULL AND failed_scope.pending_job_id = v_orphan_enqueue_job_id)
        );

      UPDATE public.banking_pay_workbench_jobs AS bad_job_update
      SET payload_json = jsonb_strip_nulls(
            COALESCE(bad_job_update.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'source_build_poison_repair_attempted', true,
              'source_build_poison_repair_attempted_at_utc', v_now::text,
              'source_build_poison_repair_successor_created', false,
              'source_build_poison_repair_error_json', v_orphan_enqueue_error_json,
              'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
            )
          ),
          updated_at_utc = v_now
      WHERE bad_job_update.id = v_orphan_repair_row.bad_job_id;

      BEGIN
        v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
          p_session_id => v_orphan_repair_row.session_id,
          p_apply => true,
          p_reason => 'SOURCE_BUILD_POISON_REPAIR_SUCCESSOR_FAILED_CLOSED',
          p_write_progress_json => true
        );
      EXCEPTION WHEN OTHERS THEN
        v_progress_recompute_failed := true;
        v_progress_recompute_error_json := jsonb_build_object(
          'code', SQLSTATE,
          'message', SQLERRM,
          'session_id', v_orphan_repair_row.session_id::text,
          'candidate_id', v_orphan_repair_row.candidate_id::text,
          'bad_job_id', v_orphan_repair_row.bad_job_id::text,
          'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
        );
      END;

      SELECT jsonb_build_object(
        'id', failed_scope.id::text,
        'session_id', failed_scope.session_id::text,
        'candidate_id', failed_scope.candidate_id::text,
        'status', failed_scope.status,
        'dirty', failed_scope.dirty,
        'seeded', failed_scope.seeded,
        'pending_job_id', CASE WHEN failed_scope.pending_job_id IS NULL THEN NULL ELSE failed_scope.pending_job_id::text END,
        'error_json', failed_scope.error_json,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      )
      INTO v_orphan_scope_after_json
      FROM public.banking_pay_workbench_session_scope AS failed_scope
      WHERE failed_scope.id = v_orphan_repair_row.scope_id;

      PERFORM public._audit_insert(
        'banking_pay_workbench_session_scope',
        v_orphan_repair_row.candidate_id::text,
        'SOURCE_BUILD_POISON_REPAIR_SUCCESSOR_FAILED_CLOSED',
        v_orphan_scope_before_json,
        v_orphan_scope_after_json,
        'SOURCE_BUILD_POISON_REPAIR_SUCCESSOR_FAILED_CLOSED',
        NULL
      );

      v_skipped_count := v_skipped_count + 1;
      v_orphan_pending_failed_closed_count := v_orphan_pending_failed_closed_count + 1;
      v_orphan_pending_skips_json := v_orphan_pending_skips_json || jsonb_build_array(jsonb_build_object(
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'scope_failed_closed', true,
        'failed_job_reference_cleared', true,
        'repair_error_json', v_orphan_enqueue_error_json,
        'progress_recompute_failed', v_progress_recompute_failed,
        'progress_recompute_error_json', v_progress_recompute_error_json,
        'reason', v_reason,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      ));
      CONTINUE;
    END IF;

    PERFORM 1
    FROM public.banking_pay_workbench_session_scope AS repaired_scope
    WHERE repaired_scope.id = v_orphan_repair_row.scope_id
      AND repaired_scope.session_id = v_orphan_repair_row.session_id
      AND repaired_scope.candidate_id = v_orphan_repair_row.candidate_id
      AND UPPER(BTRIM(COALESCE(repaired_scope.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND COALESCE(repaired_scope.dirty, false) IS TRUE
      AND repaired_scope.pending_job_id = v_orphan_enqueue_job_id
      AND repaired_scope.error_json IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'SOURCE_BUILD_POISON_REPAIR_SCOPE_REBIND_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SOURCE_BUILD_POISON_REPAIR_SCOPE_REBIND_REQUIRED',
                'session_id', v_orphan_repair_row.session_id::text,
                'candidate_id', v_orphan_repair_row.candidate_id::text,
                'bad_job_id', v_orphan_repair_row.bad_job_id::text,
                'successor_job_id', v_orphan_enqueue_job_id::text,
                'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
                'message', 'The canonical candidate refresh helper did not replace the failed pending job reference with the validated successor.'
              )::text;
    END IF;

    UPDATE public.banking_pay_workbench_jobs AS bad_job_update
    SET payload_json = jsonb_strip_nulls(
          COALESCE(bad_job_update.payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'source_build_poison_repair_resolved', true,
            'source_build_poison_repair_resolved_at_utc', v_now::text,
            'source_build_poison_repair_reason', v_reason,
            'source_build_poison_repair_successor_job_id', v_orphan_enqueue_job_id::text,
            'source_build_poison_repair_successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
            'source_build_poison_repair_successor_status', v_orphan_enqueue_job_status,
            'non_blocking_terminal_failure', true,
            'non_blocking_terminal_failure_reason', 'MISSING_SOURCE_BUILD_RUN_ID_IS_NOT_AUTHORITATIVE',
            'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
          )
        ),
        updated_at_utc = v_now
    WHERE bad_job_update.id = v_orphan_repair_row.bad_job_id
    RETURNING jsonb_build_object(
      'id', bad_job_update.id::text,
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'job_type', bad_job_update.job_type,
      'status', bad_job_update.status,
      'retained_terminal', true,
      'successor_job_id', v_orphan_enqueue_job_id::text,
      'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_bad_job_after_json;

    SELECT jsonb_build_object(
      'id', repaired_scope.id::text,
      'session_id', repaired_scope.session_id::text,
      'candidate_id', repaired_scope.candidate_id::text,
      'status', repaired_scope.status,
      'dirty', repaired_scope.dirty,
      'seeded', repaired_scope.seeded,
      'pending_job_id', CASE WHEN repaired_scope.pending_job_id IS NULL THEN NULL ELSE repaired_scope.pending_job_id::text END,
      'error_json', repaired_scope.error_json,
      'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_scope_after_json
    FROM public.banking_pay_workbench_session_scope AS repaired_scope
    WHERE repaired_scope.id = v_orphan_repair_row.scope_id;

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'scope_pending_count', session_row.scope_pending_count,
      'scope_failed_count', session_row.scope_failed_count,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_session_before_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_orphan_repair_row.session_id
    FOR UPDATE;

    BEGIN
      v_progress_recompute_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id => v_orphan_repair_row.session_id,
        p_apply => true,
        p_reason => 'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
        p_write_progress_json => true
      );
    EXCEPTION WHEN OTHERS THEN
      v_progress_recompute_failed := true;
      v_progress_recompute_error_json := jsonb_build_object(
        'code', SQLSTATE,
        'message', SQLERRM,
        'session_id', v_orphan_repair_row.session_id::text,
        'candidate_id', v_orphan_repair_row.candidate_id::text,
        'bad_job_id', v_orphan_repair_row.bad_job_id::text,
        'successor_job_id', v_orphan_enqueue_job_id::text,
        'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
      );
      v_progress_recompute_json := COALESCE(v_progress_recompute_error_json, '{}'::jsonb);
    END;

    SELECT jsonb_build_object(
      'id', session_row.id::text,
      'status', session_row.status,
      'progress_state', session_row.progress_state,
      'scope_pending_count', session_row.scope_pending_count,
      'scope_failed_count', session_row.scope_failed_count,
      'progress_counter_version', session_row.progress_counter_version,
      'progress_json', public.pay_workbench_session_compact_progress_json(COALESCE(session_row.progress_json, '{}'::jsonb), true),
      'recompute_failed', v_progress_recompute_failed,
      'recompute_json', COALESCE(v_progress_recompute_json, '{}'::jsonb),
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    )
    INTO v_orphan_session_after_json
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = v_orphan_repair_row.session_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_orphan_repair_row.bad_job_id::text,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      v_orphan_bad_job_before_json,
      v_orphan_bad_job_after_json,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_scope',
      v_orphan_repair_row.candidate_id::text,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      v_orphan_scope_before_json,
      v_orphan_scope_after_json,
      'ORPHANED_PENDING_SOURCE_BUILD_POISON_REPAIRED',
      NULL
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session',
      v_orphan_repair_row.session_id::text,
      'PROGRESS_RECOMPUTED_AFTER_ORPHANED_SOURCE_BUILD_POISON',
      v_orphan_session_before_json,
      v_orphan_session_after_json,
      'PROGRESS_RECOMPUTED_AFTER_ORPHANED_SOURCE_BUILD_POISON',
      NULL
    );

    v_repaired_count := v_repaired_count + 1;
    v_repaired_scope_count := v_repaired_scope_count + 1;
    v_repaired_session_count := v_repaired_session_count + 1;
    v_orphan_pending_repaired_count := v_orphan_pending_repaired_count + 1;

    IF lower(BTRIM(COALESCE(v_orphan_enqueue_result->>'reused', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_corrected_source_build_job_reused_count := v_corrected_source_build_job_reused_count + 1;
    ELSE
      v_corrected_source_build_job_queued_count := v_corrected_source_build_job_queued_count + 1;
    END IF;

    v_orphan_pending_repairs_json := v_orphan_pending_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'bad_job_id', v_orphan_repair_row.bad_job_id::text,
      'successor_job_id', v_orphan_enqueue_job_id::text,
      'successor_job_status', v_orphan_enqueue_job_status,
      'successor_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'refresh_scope_kind', v_orphan_refresh_scope_kind,
      'targeted_timesheet_ids', COALESCE(v_orphan_targeted_timesheet_ids_json, '[]'::jsonb),
      'linked_timesheet_ids', COALESCE(v_orphan_linked_timesheet_ids_json, '[]'::jsonb),
      'failed_job_reference_replaced', true,
      'scope_dirty_preserved', true,
      'session_progress_recomputed', true,
      'progress_recompute_failed', v_progress_recompute_failed,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));

    v_repairs_json := v_repairs_json || jsonb_build_array(jsonb_build_object(
      'session_id', v_orphan_repair_row.session_id::text,
      'candidate_id', v_orphan_repair_row.candidate_id::text,
      'bad_job_id', v_orphan_repair_row.bad_job_id::text,
      'corrected_source_build_job_id', v_orphan_enqueue_job_id::text,
      'corrected_source_build_run_id', v_orphan_enqueue_source_build_run_id_text,
      'orphaned_pending_repair', true,
      'scope_repaired', true,
      'session_progress_repaired', true,
      'reason', v_reason,
      'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'server_utc', v_now,
    'reason', v_reason,
    'filtered_session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    'filtered_candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
    'limit', v_limit,
    'processed_count', v_processed_count,
    'repaired_count', v_repaired_count,
    'skipped_count', v_skipped_count,
    'source_rows_restored_count', v_total_restored_source_row_count,
    'line_seed_requeued_count', v_requeued_line_seed_count,
    'scope_repaired_count', v_repaired_scope_count,
    'session_progress_repaired_count', v_repaired_session_count,
    'zero_source_row_repaired_count', v_zero_source_row_repaired_count,
    'corrected_source_build_job_queued_count', v_corrected_source_build_job_queued_count,
    'corrected_source_build_job_reused_count', v_corrected_source_build_job_reused_count,
    'corrected_source_build_job_succeeded_reused_count', v_corrected_source_build_job_succeeded_reused_count,
    'line_seed_attempt_count_reset_count', v_line_seed_attempt_count_reset_count,
    'post_recompute_progress_state', v_post_recompute_progress_state,
    'post_recompute_scope_failed_count', v_post_recompute_scope_failed_count,
    'post_recompute_scope_pending_count', v_post_recompute_scope_pending_count,
    'zero_source_row_repairs', COALESCE(v_zero_source_row_repairs_json, '[]'::jsonb),
    'zero_source_row_skips', COALESCE(v_zero_source_row_skips_json, '[]'::jsonb),
    'orphaned_pending_repaired_count', v_orphan_pending_repaired_count,
    'orphaned_pending_failed_closed_count', v_orphan_pending_failed_closed_count,
    'orphaned_pending_repairs', COALESCE(v_orphan_pending_repairs_json, '[]'::jsonb),
    'orphaned_pending_skips', COALESCE(v_orphan_pending_skips_json, '[]'::jsonb),
    'repairs', COALESCE(v_repairs_json, '[]'::jsonb),
    'skips', COALESCE(v_skips_json, '[]'::jsonb),
    'policy_x_authority_scope', 'PRE_DRAFT_WORKBENCH_REPAIR_ONLY'
  );
END;
$function$;

-- pay_workbench_repair_orphaned_pending_source_build(uuid,uuid,integer,timestamp with time zone,text)
CREATE OR REPLACE FUNCTION public.pay_workbench_repair_orphaned_pending_source_build(p_session_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT 'PENDING_SCOPE_OWNER_REPAIR'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := COALESCE(p_now_utc, now());
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 10), 1), 25);
  v_reason text := COALESCE(NULLIF(BTRIM(COALESCE(p_reason, '')), ''), 'PENDING_SCOPE_OWNER_REPAIR');
  v_candidate record;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_post_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_owner public.banking_pay_workbench_jobs%ROWTYPE;
  v_post_owner public.banking_pay_workbench_jobs%ROWTYPE;
  v_success public.banking_pay_workbench_jobs%ROWTYPE;
  v_active public.banking_pay_workbench_jobs%ROWTYPE;
  v_success_run_id uuid := NULL::uuid;
  v_success_source_change_seq bigint := 0;
  v_live_change_seq bigint := 0;
  v_post_live_change_seq bigint := 0;
  v_owner_canonical_type text := NULL::text;
  v_owner_valid boolean := false;
  v_owner_generation_obsolete boolean := false;
  v_owner_reason text := NULL::text;
  v_enqueue_payload jsonb := '{}'::jsonb;
  v_enqueue_result jsonb := '{}'::jsonb;
  v_success_result jsonb := '{}'::jsonb;
  v_progress_recompute_result jsonb := '{}'::jsonb;
  v_successor_job_id uuid := NULL::uuid;
  v_successor_run_id_text text := NULL::text;
  v_successor_valid boolean := false;
  v_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_pay_channel_scope text := 'ALL';
  v_scope_transition_row_count integer := 0;
  v_reconciliation_attempted boolean := false;
  v_reconciliation_applied boolean := false;
  v_reconciliation_error_code text := NULL::text;
  v_reconciliation_postcondition_proven boolean := false;
  v_post_scope_found boolean := false;
  v_exact_current_source_exists boolean := false;
  v_unresolved_current_source_exists boolean := false;
  v_remaining_owner_valid boolean := false;
  v_candidate_action text := NULL::text;
  v_candidate_branch text := NULL::text;
  v_candidate_transition_proven boolean := false;
  v_candidate_unresolved boolean := false;
  v_candidate_skipped boolean := false;
  v_candidate_failure_code text := NULL::text;
  v_candidate_failure_message text := NULL::text;
  v_candidate_unresolved_reason text := NULL::text;
  v_candidate_old_pending_job_id uuid := NULL::uuid;
  v_progress_recomputed boolean := false;
  v_progress_recompute_error_code text := NULL::text;
  v_audit_failed boolean := false;
  v_repaired_count integer := 0;
  v_reconciled_count integer := 0;
  v_rebound_count integer := 0;
  v_enqueued_count integer := 0;
  v_failed_closed_count integer := 0;
  v_skipped_count integer := 0;
  v_unresolved_count integer := 0;
  v_progress_recomputed_count integer := 0;
  v_progress_recompute_failed_count integer := 0;
  v_result_rows jsonb := '[]'::jsonb;
  v_expired_attempt record;
  v_expired_attempt_count integer:=0;
  v_expired_requeued_count integer:=0;
  v_expired_exhausted_count integer:=0;
BEGIN
  -- Recover delivered-but-uncompleted material attempts first.  Each recovery
  -- uses the candidate lock and registry/build/job/attempt lock order.
  FOR v_expired_attempt IN
    SELECT attempt.id attempt_id,attempt.job_id,attempt.build_id,attempt.candidate_id,
           attempt.private_stage,job.attempt_count,job.max_attempts
    FROM private.banking_pay_workbench_stage_attempts attempt
    JOIN public.banking_pay_workbench_jobs job ON job.id=attempt.job_id
    WHERE attempt.attempt_status='STARTED'
      AND clock_timestamp()>=attempt.lease_expires_at_utc+interval '15 seconds'
      AND job.status='RUNNING' AND job.economic_build_id=attempt.build_id
      AND job.private_stage=attempt.private_stage
      AND (p_session_id IS NULL OR job.session_id=p_session_id)
      AND (p_candidate_id IS NULL OR attempt.candidate_id=p_candidate_id)
    ORDER BY attempt.lease_expires_at_utc,attempt.id
    LIMIT v_limit
  LOOP
    IF pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(v_expired_attempt.candidate_id),24062027)) THEN
      PERFORM 1 FROM private.banking_pay_workbench_candidate_scope_registry
      WHERE candidate_id=v_expired_attempt.candidate_id FOR UPDATE;
      PERFORM 1 FROM private.banking_pay_workbench_economic_builds
      WHERE id=v_expired_attempt.build_id FOR UPDATE;
      PERFORM 1 FROM public.banking_pay_workbench_jobs
      WHERE id=v_expired_attempt.job_id FOR UPDATE;
      PERFORM 1 FROM private.banking_pay_workbench_stage_attempts
      WHERE id=v_expired_attempt.attempt_id FOR UPDATE;
      UPDATE private.banking_pay_workbench_stage_attempts SET attempt_status='EXPIRED',
        expired_at_utc=clock_timestamp(),result_code='LEASE_EXPIRED_AFTER_CANCELLATION_GRACE',
        error_class='DELIVERED_ATTEMPT_EXPIRED',updated_at_utc=clock_timestamp()
      WHERE id=v_expired_attempt.attempt_id AND attempt_status='STARTED'
        AND clock_timestamp()>=lease_expires_at_utc+interval '15 seconds';
      IF FOUND THEN
        v_expired_attempt_count:=v_expired_attempt_count+1;
        IF v_expired_attempt.attempt_count<v_expired_attempt.max_attempts THEN
          UPDATE public.banking_pay_workbench_jobs SET status='QUEUED',started_at_utc=NULL,
            run_at_utc=clock_timestamp()+make_interval(secs=>LEAST(300,
              GREATEST(1,power(2,LEAST(v_expired_attempt.attempt_count,8))::integer))),
            last_error_json=jsonb_build_object('code','DELIVERED_ATTEMPT_EXPIRED'),
            updated_at_utc=clock_timestamp()
          WHERE id=v_expired_attempt.job_id AND status='RUNNING';
          v_expired_requeued_count:=v_expired_requeued_count+1;
        ELSE
          UPDATE public.banking_pay_workbench_jobs SET status='FAILED',
            failed_at_utc=clock_timestamp(),last_error_json=jsonb_build_object(
              'code','DELIVERED_ATTEMPT_EXHAUSTED'),updated_at_utc=clock_timestamp()
          WHERE id=v_expired_attempt.job_id AND status='RUNNING';
          UPDATE private.banking_pay_workbench_economic_builds SET status='FAILED',
            failed_at_utc=clock_timestamp(),failure_json=jsonb_build_object(
              'code','DELIVERED_ATTEMPT_EXHAUSTED'),updated_at_utc=clock_timestamp()
          WHERE id=v_expired_attempt.build_id AND status NOT IN ('COMPLETE','OBSOLETE');
          v_expired_exhausted_count:=v_expired_exhausted_count+1;
        END IF;
      END IF;
    END IF;
  END LOOP;

  FOR v_candidate IN
    SELECT scope_row.session_id, scope_row.candidate_id
    FROM public.banking_pay_workbench_session_scope AS scope_row
    JOIN public.banking_pay_workbench_sessions AS session_row
      ON session_row.id = scope_row.session_id
    LEFT JOIN public.banking_pay_workbench_jobs AS owner_job
      ON owner_job.id = scope_row.pending_job_id
    LEFT JOIN public.app_change_counters AS owner_change_counter
      ON owner_change_counter.entity_key = 'pay_candidate:' || scope_row.candidate_id::text
    WHERE UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
      AND session_row.discarded_at_utc IS NULL
      AND UPPER(BTRIM(COALESCE(scope_row.status, ''))) = 'SOURCE_BUILD_PENDING'
      AND (p_session_id IS NULL OR scope_row.session_id = p_session_id)
      AND (p_candidate_id IS NULL OR scope_row.candidate_id = p_candidate_id)
      AND (
        scope_row.pending_job_id IS NULL
        OR owner_job.id IS NULL
        OR UPPER(BTRIM(COALESCE(owner_job.status, ''))) NOT IN ('QUEUED', 'RUNNING')
        OR owner_job.session_id IS DISTINCT FROM scope_row.session_id
        OR owner_job.candidate_id IS DISTINCT FROM scope_row.candidate_id
        OR (
          CASE
            WHEN UPPER(BTRIM(COALESCE(owner_job.job_type, ''))) IN (
              'WORKBENCH_CANDIDATE_SOURCE_BUILD',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
              'CANDIDATE_SOURCE_BUILD',
              'CANDIDATE_SOURCE_BUILD_CHUNK',
              'SOURCE_BUILD',
              'SOURCE_BUILD_PAGE'
            ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            ELSE UPPER(BTRIM(COALESCE(owner_job.job_type, '')))
          END
        ) <> 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
        OR CASE
             WHEN COALESCE(owner_job.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$'
               THEN (owner_job.payload_json->>'session_version')::bigint
             ELSE NULL::bigint
           END IS DISTINCT FROM session_row.version
        OR CASE
             WHEN COALESCE(owner_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
               THEN (owner_job.payload_json->>'source_change_seq')::bigint
             ELSE NULL::bigint
           END IS NULL
        OR (
          CASE
            WHEN COALESCE(owner_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
              THEN (owner_job.payload_json->>'source_change_seq')::bigint
            ELSE NULL::bigint
          END
          < COALESCE(owner_change_counter.seq, 0)
        )
        OR COALESCE(owner_job.payload_json->>'source_build_run_id', '') !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
    ORDER BY scope_row.updated_at_utc ASC NULLS FIRST, scope_row.session_id, scope_row.candidate_id
    LIMIT v_limit
  LOOP
    v_session := NULL::public.banking_pay_workbench_sessions;
    v_scope := NULL::public.banking_pay_workbench_session_scope;
    v_post_scope := NULL::public.banking_pay_workbench_session_scope;
    v_owner := NULL::public.banking_pay_workbench_jobs;
    v_post_owner := NULL::public.banking_pay_workbench_jobs;
    v_success := NULL::public.banking_pay_workbench_jobs;
    v_active := NULL::public.banking_pay_workbench_jobs;
    v_success_run_id := NULL::uuid;
    v_success_source_change_seq := 0;
    v_live_change_seq := 0;
    v_post_live_change_seq := 0;
    v_owner_canonical_type := NULL::text;
    v_owner_valid := false;
    v_owner_generation_obsolete := false;
    v_owner_reason := NULL::text;
    v_enqueue_payload := '{}'::jsonb;
    v_enqueue_result := '{}'::jsonb;
    v_success_result := '{}'::jsonb;
    v_progress_recompute_result := '{}'::jsonb;
    v_successor_job_id := NULL::uuid;
    v_successor_run_id_text := NULL::text;
    v_successor_valid := false;
    v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    v_targeted_timesheet_ids := '[]'::jsonb;
    v_linked_timesheet_ids := '[]'::jsonb;
    v_pay_channel_scope := 'ALL';
    v_scope_transition_row_count := 0;
    v_reconciliation_attempted := false;
    v_reconciliation_applied := false;
    v_reconciliation_error_code := NULL::text;
    v_reconciliation_postcondition_proven := false;
    v_post_scope_found := false;
    v_exact_current_source_exists := false;
    v_unresolved_current_source_exists := false;
    v_remaining_owner_valid := false;
    v_candidate_action := NULL::text;
    v_candidate_branch := NULL::text;
    v_candidate_transition_proven := false;
    v_candidate_unresolved := false;
    v_candidate_skipped := false;
    v_candidate_failure_code := NULL::text;
    v_candidate_failure_message := NULL::text;
    v_candidate_unresolved_reason := NULL::text;
    v_candidate_old_pending_job_id := NULL::uuid;
    v_progress_recomputed := false;
    v_progress_recompute_error_code := NULL::text;
    v_audit_failed := false;

    BEGIN
      IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
        public._pay_workbench_candidate_serial_key(v_candidate.candidate_id),24062027
      )) THEN
        v_candidate_skipped := true;
        v_candidate_action := 'SKIPPED_CANDIDATE_SERIAL_BUSY';
      ELSE
        PERFORM 1
        FROM private.banking_pay_workbench_candidate_scope_registry AS registry
        WHERE registry.candidate_id=v_candidate.candidate_id
        FOR UPDATE;

        SELECT session_row.*
        INTO v_session
        FROM public.banking_pay_workbench_sessions AS session_row
        WHERE session_row.id = v_candidate.session_id
        FOR UPDATE;

        IF NOT FOUND
           OR UPPER(BTRIM(COALESCE(v_session.status, ''))) <> 'OPEN'
           OR v_session.discarded_at_utc IS NOT NULL THEN
          v_candidate_skipped := true;
          v_candidate_action := 'SKIPPED_AFTER_RECHECK';
        ELSE
          SELECT scope_row.*
          INTO v_scope
          FROM public.banking_pay_workbench_session_scope AS scope_row
          WHERE scope_row.session_id = v_candidate.session_id
            AND scope_row.candidate_id = v_candidate.candidate_id
          FOR UPDATE;

        IF NOT FOUND
           OR UPPER(BTRIM(COALESCE(v_scope.status, ''))) <> 'SOURCE_BUILD_PENDING' THEN
          v_candidate_skipped := true;
          v_candidate_action := 'SKIPPED_AFTER_RECHECK';
        ELSE
          v_candidate_old_pending_job_id := v_scope.pending_job_id;

          SELECT COALESCE((
            SELECT change_counter.seq
            FROM public.app_change_counters AS change_counter
            WHERE change_counter.entity_key = 'pay_candidate:' || v_scope.candidate_id::text
          ), 0)
          INTO v_live_change_seq;

          IF v_scope.pending_job_id IS NOT NULL THEN
            SELECT owner_job.*
            INTO v_owner
            FROM public.banking_pay_workbench_jobs AS owner_job
            WHERE owner_job.id = v_scope.pending_job_id
            FOR UPDATE;
          END IF;

          v_owner_generation_obsolete := UPPER(BTRIM(COALESCE(
            v_owner.last_error_json->>'code',''
          )))='ATTEMPT_GENERATION_OBSOLETE';

          v_owner_canonical_type := CASE
            WHEN UPPER(BTRIM(COALESCE(v_owner.job_type, ''))) IN (
              'WORKBENCH_CANDIDATE_SOURCE_BUILD',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
              'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
              'CANDIDATE_SOURCE_BUILD',
              'CANDIDATE_SOURCE_BUILD_CHUNK',
              'SOURCE_BUILD',
              'SOURCE_BUILD_PAGE'
            ) THEN 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            ELSE UPPER(BTRIM(COALESCE(v_owner.job_type, '')))
          END;

          v_owner_valid := v_owner.id IS NOT NULL
            AND UPPER(BTRIM(COALESCE(v_owner.status, ''))) IN ('QUEUED', 'RUNNING')
            AND v_owner.session_id = v_scope.session_id
            AND v_owner.candidate_id = v_scope.candidate_id
            AND v_owner_canonical_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
            AND CASE
                  WHEN COALESCE(v_owner.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$'
                    THEN (v_owner.payload_json->>'session_version')::bigint
                  ELSE NULL::bigint
                END = v_session.version
            AND CASE
                  WHEN COALESCE(v_owner.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
                    THEN (v_owner.payload_json->>'source_change_seq')::bigint
                  ELSE NULL::bigint
                END >= v_live_change_seq
            AND COALESCE(v_owner.payload_json->>'source_build_run_id', '') ~*
                '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

          IF v_owner_valid THEN
            v_candidate_skipped := true;
            v_candidate_action := 'SKIPPED_AFTER_RECHECK';
          ELSE
            v_owner_reason := CASE
              WHEN v_scope.pending_job_id IS NULL THEN 'PENDING_JOB_ID_MISSING'
              WHEN v_owner.id IS NULL THEN 'PENDING_JOB_ROW_MISSING'
              WHEN UPPER(BTRIM(COALESCE(v_owner.status, ''))) NOT IN ('QUEUED', 'RUNNING') THEN 'PENDING_JOB_TERMINAL'
              WHEN v_owner.session_id IS DISTINCT FROM v_scope.session_id
                OR v_owner.candidate_id IS DISTINCT FROM v_scope.candidate_id THEN 'PENDING_JOB_SCOPE_MISMATCH'
              WHEN v_owner_canonical_type <> 'WORKBENCH_CANDIDATE_SOURCE_BUILD' THEN 'PENDING_JOB_TYPE_MISMATCH'
              WHEN COALESCE(v_owner.payload_json->>'source_build_run_id', '') !~*
                   '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                THEN 'PENDING_JOB_RUN_ID_INVALID'
              WHEN COALESCE(v_owner.payload_json->>'session_version', '') !~ '^[0-9]{1,18}$'
                OR (v_owner.payload_json->>'session_version')::bigint IS DISTINCT FROM v_session.version
                THEN 'PENDING_JOB_SESSION_VERSION_STALE'
              ELSE 'PENDING_JOB_SOURCE_CHANGE_SEQ_STALE'
            END;

            SELECT successful_job.*
            INTO v_success
            FROM public.banking_pay_workbench_jobs AS successful_job
            WHERE successful_job.session_id = v_scope.session_id
              AND successful_job.candidate_id = v_scope.candidate_id
              AND UPPER(BTRIM(COALESCE(successful_job.status, ''))) = 'SUCCEEDED'
              AND successful_job.completed_at_utc IS NOT NULL
              AND successful_job.failed_at_utc IS NULL
              AND UPPER(BTRIM(COALESCE(successful_job.job_type, ''))) IN (
                'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                'CANDIDATE_SOURCE_BUILD',
                'CANDIDATE_SOURCE_BUILD_CHUNK',
                'SOURCE_BUILD',
                'SOURCE_BUILD_PAGE'
              )
              AND CASE
                    WHEN COALESCE(successful_job.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$'
                      THEN (successful_job.payload_json->>'session_version')::bigint
                    ELSE NULL::bigint
                  END = v_session.version
              AND CASE
                    WHEN COALESCE(successful_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
                      THEN (successful_job.payload_json->>'source_change_seq')::bigint
                    ELSE NULL::bigint
                  END >= v_live_change_seq
              AND COALESCE(successful_job.payload_json->>'source_build_run_id', '') ~*
                  '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              AND EXISTS (
                SELECT 1
                FROM public.banking_pay_workbench_candidate_source_lines AS successful_source
                WHERE successful_source.session_id = v_scope.session_id
                  AND successful_source.candidate_id = v_scope.candidate_id
                  AND successful_source.source_build_run_id::text = successful_job.payload_json->>'source_build_run_id'
                  AND successful_source.session_version = v_session.version
                  AND successful_source.source_change_seq = CASE
                        WHEN COALESCE(successful_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
                          THEN (successful_job.payload_json->>'source_change_seq')::bigint
                        ELSE NULL::bigint
                      END
                  AND UPPER(BTRIM(COALESCE(successful_source.status, ''))) = 'CURRENT'
              )
              AND NOT EXISTS (
                SELECT 1
                FROM public.banking_pay_workbench_candidate_source_lines AS unresolved_successful_source
                WHERE unresolved_successful_source.session_id = v_scope.session_id
                  AND unresolved_successful_source.candidate_id = v_scope.candidate_id
                  AND unresolved_successful_source.session_version = v_session.version
                  AND UPPER(BTRIM(COALESCE(unresolved_successful_source.status, ''))) IN ('DIRTY', 'ERROR')
              )
            ORDER BY
              CASE
                WHEN COALESCE(successful_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
                  THEN (successful_job.payload_json->>'source_change_seq')::bigint
                ELSE NULL::bigint
              END DESC,
              successful_job.completed_at_utc DESC,
              successful_job.id DESC
            LIMIT 1
            FOR UPDATE OF successful_job;

            IF FOUND THEN
              v_success_run_id := (v_success.payload_json->>'source_build_run_id')::uuid;
              v_success_source_change_seq := (v_success.payload_json->>'source_change_seq')::bigint;

              BEGIN
                v_reconciliation_attempted := true;
                v_success_result := public.pay_workbench_reconcile_successful_source_build(
                  p_session_id => v_scope.session_id,
                  p_candidate_id => v_scope.candidate_id,
                  p_source_build_run_id => v_success_run_id,
                  p_source_change_seq => v_success_source_change_seq,
                  p_session_version => v_session.version,
                  p_success_job_id => v_success.id,
                  p_refresh_scope_kind => COALESCE(NULLIF(BTRIM(v_success.payload_json->>'refresh_scope_kind'), ''), 'CANDIDATE_FULL_LIVE'),
                  p_targeted_timesheet_ids => CASE WHEN jsonb_typeof(v_success.payload_json->'targeted_timesheet_ids') = 'array' THEN v_success.payload_json->'targeted_timesheet_ids' ELSE '[]'::jsonb END,
                  p_linked_timesheet_ids => CASE WHEN jsonb_typeof(v_success.payload_json->'linked_timesheet_ids') = 'array' THEN v_success.payload_json->'linked_timesheet_ids' ELSE '[]'::jsonb END,
                  p_recompute_session_progress => false
                );

                IF jsonb_typeof(v_success_result) IS DISTINCT FROM 'object'
                   OR LOWER(BTRIM(COALESCE(v_success_result->>'ok', ''))) <> 'true'
                   OR LOWER(BTRIM(COALESCE(v_success_result->>'skipped', ''))) <> 'false' THEN
                  RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_RESULT_NOT_CONFIRMED'
                    USING ERRCODE = 'P0001';
                END IF;

                SELECT reconciled_scope.*
                INTO v_post_scope
                FROM public.banking_pay_workbench_session_scope AS reconciled_scope
                WHERE reconciled_scope.id = v_scope.id
                FOR UPDATE;
                v_post_scope_found := FOUND;

                PERFORM 1
                FROM public.banking_pay_workbench_candidate_source_lines AS exact_current_source
                WHERE exact_current_source.session_id = v_scope.session_id
                  AND exact_current_source.candidate_id = v_scope.candidate_id
                  AND exact_current_source.session_version = v_session.version
                  AND exact_current_source.source_build_run_id = v_success_run_id
                  AND exact_current_source.source_change_seq = v_success_source_change_seq
                  AND UPPER(BTRIM(COALESCE(exact_current_source.status, ''))) = 'CURRENT'
                FOR UPDATE;
                v_exact_current_source_exists := FOUND;

                PERFORM 1
                FROM public.banking_pay_workbench_candidate_source_lines AS unresolved_current_source
                WHERE unresolved_current_source.session_id = v_scope.session_id
                  AND unresolved_current_source.candidate_id = v_scope.candidate_id
                  AND unresolved_current_source.session_version = v_session.version
                  AND UPPER(BTRIM(COALESCE(unresolved_current_source.status, ''))) IN ('DIRTY', 'ERROR')
                FOR UPDATE;
                v_unresolved_current_source_exists := FOUND;

                v_remaining_owner_valid := v_post_scope.pending_job_id IS NULL;
                IF v_post_scope.pending_job_id IS NOT NULL THEN
                  SELECT downstream_owner.*
                  INTO v_post_owner
                  FROM public.banking_pay_workbench_jobs AS downstream_owner
                  WHERE downstream_owner.id = v_post_scope.pending_job_id
                  FOR UPDATE;

                  v_remaining_owner_valid := FOUND
                    AND v_post_owner.session_id = v_scope.session_id
                    AND v_post_owner.candidate_id = v_scope.candidate_id
                    AND UPPER(BTRIM(COALESCE(v_post_owner.status, ''))) IN ('QUEUED', 'RUNNING')
                    AND UPPER(BTRIM(COALESCE(v_post_owner.job_type, ''))) IN (
                      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                      'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                      'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                      'CANDIDATE_SOURCE_BUILD',
                      'CANDIDATE_SOURCE_BUILD_CHUNK',
                      'SOURCE_BUILD',
                      'SOURCE_BUILD_PAGE',
                      'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
                      'WORKBENCH_CANDIDATE_LINE_WORK_SEED_PAGE',
                      'CANDIDATE_LINE_WORK_SEED',
                      'CANDIDATE_LINE_WORK_SEED_PAGE',
                      'LINE_WORK_SEED_PAGE',
                      'SNAPSHOT_CANDIDATE_REFRESH',
                      'CANDIDATE_REFRESH',
                      'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
                      'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS_CHUNK',
                      'CANDIDATE_LINE_WORK_PROCESS',
                      'CANDIDATE_LINE_WORK_PROCESS_CHUNK',
                      'LINE_WORK_PROCESS',
                      'LINE_WORK_PROCESS_CHUNK',
                      'WORKBENCH_PREVIEW_ROWS_MATERIALISE',
                      'WORKBENCH_PREVIEW_ROWS_MATERIALIZE',
                      'WORKBENCH_PREVIEW_ROWS_MATERIALISE_CHUNK',
                      'WORKBENCH_PREVIEW_ROWS_MATERIALIZE_CHUNK',
                      'PREVIEW_ROWS_MATERIALISE',
                      'PREVIEW_ROWS_MATERIALIZE',
                      'PREVIEW_ROWS_MATERIALISE_CHUNK',
                      'PREVIEW_ROWS_MATERIALIZE_CHUNK'
                    )
                    AND CASE
                          WHEN COALESCE(v_post_owner.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$'
                            THEN (v_post_owner.payload_json->>'session_version')::bigint
                          ELSE NULL::bigint
                        END = v_session.version;
                END IF;

                v_reconciliation_postcondition_proven := v_post_scope_found
                  AND UPPER(BTRIM(COALESCE(v_post_scope.status, ''))) IN (
                    'SOURCE_READY',
                    'LINE_WORK_PENDING',
                    'MATERIALISED',
                    'MATERIALIZED',
                    'READY',
                    'SOURCE_EMPTY'
                  )
                  AND UPPER(BTRIM(COALESCE(v_post_scope.status, ''))) <> 'SOURCE_BUILD_PENDING'
                  AND (
                    v_scope.pending_job_id IS NULL
                    OR v_post_scope.pending_job_id IS DISTINCT FROM v_scope.pending_job_id
                  )
                  AND COALESCE(v_post_scope.dirty, false) IS NOT TRUE
                  AND v_exact_current_source_exists
                  AND v_unresolved_current_source_exists IS NOT TRUE
                  AND v_remaining_owner_valid;

                IF v_reconciliation_postcondition_proven IS NOT TRUE THEN
                  RAISE EXCEPTION 'PAY_WORKBENCH_RECONCILIATION_POSTCONDITION_NOT_PROVEN'
                    USING ERRCODE = 'P0001';
                END IF;

                v_reconciliation_applied := true;
              EXCEPTION WHEN OTHERS THEN
                v_reconciliation_applied := false;
                v_reconciliation_error_code := SQLSTATE;
                v_reconciliation_postcondition_proven := false;
              END;
            END IF;

            IF v_reconciliation_applied THEN
              v_candidate_action := 'RECONCILED_SUCCESSFUL_BUILD';
              v_candidate_branch := 'RECONCILED';
              v_candidate_transition_proven := true;
              v_successor_job_id := v_success.id;
            ELSE
              SELECT active_job.*
              INTO v_active
              FROM public.banking_pay_workbench_jobs AS active_job
              WHERE active_job.id IS DISTINCT FROM v_scope.pending_job_id
                AND active_job.session_id = v_scope.session_id
                AND active_job.candidate_id = v_scope.candidate_id
                AND UPPER(BTRIM(COALESCE(active_job.status, ''))) IN ('QUEUED', 'RUNNING')
                AND UPPER(BTRIM(COALESCE(active_job.job_type, ''))) IN (
                  'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                  'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                  'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                  'CANDIDATE_SOURCE_BUILD',
                  'CANDIDATE_SOURCE_BUILD_CHUNK',
                  'SOURCE_BUILD',
                  'SOURCE_BUILD_PAGE'
                )
                AND CASE
                      WHEN COALESCE(active_job.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$'
                        THEN (active_job.payload_json->>'session_version')::bigint
                      ELSE NULL::bigint
                    END = v_session.version
                AND CASE
                      WHEN COALESCE(active_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
                        THEN (active_job.payload_json->>'source_change_seq')::bigint
                      ELSE NULL::bigint
                    END >= v_live_change_seq
                AND COALESCE(active_job.payload_json->>'source_build_run_id', '') ~*
                    '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              ORDER BY
                CASE WHEN UPPER(BTRIM(COALESCE(active_job.status, ''))) = 'RUNNING' THEN 0 ELSE 1 END,
                CASE
                  WHEN COALESCE(active_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
                    THEN (active_job.payload_json->>'source_change_seq')::bigint
                  ELSE NULL::bigint
                END DESC,
                active_job.created_at_utc ASC,
                active_job.id ASC
              LIMIT 1
              FOR UPDATE OF active_job;

              IF FOUND THEN
                v_successor_job_id := v_active.id;

                UPDATE public.banking_pay_workbench_session_scope AS rebound_scope
                SET pending_job_id = v_active.id,
                    status = 'SOURCE_BUILD_PENDING',
                    dirty = true,
                    error_json = NULL::jsonb,
                    updated_at_utc = v_now
                WHERE rebound_scope.id = v_scope.id
                  AND rebound_scope.pending_job_id IS NOT DISTINCT FROM v_scope.pending_job_id;

                GET DIAGNOSTICS v_scope_transition_row_count = ROW_COUNT;

                SELECT rebound_post_scope.*
                INTO v_post_scope
                FROM public.banking_pay_workbench_session_scope AS rebound_post_scope
                WHERE rebound_post_scope.id = v_scope.id
                FOR UPDATE;

                SELECT COALESCE((
                  SELECT change_counter.seq
                  FROM public.app_change_counters AS change_counter
                  WHERE change_counter.entity_key = 'pay_candidate:' || v_scope.candidate_id::text
                ), 0)
                INTO v_post_live_change_seq;

                SELECT EXISTS (
                  SELECT 1
                  FROM public.banking_pay_workbench_jobs AS rebound_owner
                  WHERE rebound_owner.id = v_active.id
                    AND rebound_owner.session_id = v_scope.session_id
                    AND rebound_owner.candidate_id = v_scope.candidate_id
                    AND UPPER(BTRIM(COALESCE(rebound_owner.status, ''))) IN ('QUEUED', 'RUNNING')
                    AND UPPER(BTRIM(COALESCE(rebound_owner.job_type, ''))) IN (
                      'WORKBENCH_CANDIDATE_SOURCE_BUILD',
                      'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
                      'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
                      'CANDIDATE_SOURCE_BUILD',
                      'CANDIDATE_SOURCE_BUILD_CHUNK',
                      'SOURCE_BUILD',
                      'SOURCE_BUILD_PAGE'
                    )
                    AND CASE
                          WHEN COALESCE(rebound_owner.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$'
                            THEN (rebound_owner.payload_json->>'session_version')::bigint
                          ELSE NULL::bigint
                        END = v_session.version
                    AND CASE
                          WHEN COALESCE(rebound_owner.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
                            THEN (rebound_owner.payload_json->>'source_change_seq')::bigint
                          ELSE NULL::bigint
                        END >= v_post_live_change_seq
                    AND COALESCE(rebound_owner.payload_json->>'source_build_run_id', '') ~*
                        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                )
                INTO v_successor_valid;

                IF v_scope_transition_row_count = 1
                   AND UPPER(BTRIM(COALESCE(v_post_scope.status, ''))) = 'SOURCE_BUILD_PENDING'
                   AND v_post_scope.pending_job_id = v_active.id
                   AND COALESCE(v_post_scope.dirty, false) IS TRUE
                   AND v_post_scope.error_json IS NULL
                   AND v_successor_valid THEN
                  v_candidate_action := 'REBOUND_ACTIVE_SUCCESSOR';
                  v_candidate_branch := 'REBOUND';
                  v_candidate_transition_proven := true;
                ELSIF v_scope_transition_row_count = 0
                      AND UPPER(BTRIM(COALESCE(v_post_scope.status, ''))) = 'SOURCE_BUILD_PENDING'
                      AND COALESCE(v_post_scope.dirty, false) IS TRUE
                      AND v_post_scope.error_json IS NULL
                      AND v_post_scope.pending_job_id = v_active.id
                      AND v_successor_valid THEN
                  v_candidate_skipped := true;
                  v_candidate_action := 'SKIPPED_AFTER_RECHECK';
                  v_successor_job_id := v_post_scope.pending_job_id;
                ELSE
                  RAISE EXCEPTION 'PAY_WORKBENCH_OWNER_REPAIR_POSTCONDITION_NOT_PROVEN'
                    USING ERRCODE = 'P0001';
                END IF;
              ELSIF v_owner.id IS NOT NULL
                    AND v_owner_generation_obsolete IS NOT TRUE
                    AND COALESCE(v_owner.attempt_count, 0) >= COALESCE(v_owner.max_attempts, 8) THEN
                v_candidate_failure_code := 'WORKBENCH_PENDING_SCOPE_WITHOUT_ACTIVE_JOB';
                v_candidate_failure_message := 'Candidate refresh could not be recovered because all job attempts were used.';

                UPDATE public.banking_pay_workbench_session_scope AS failed_scope
                SET status = 'SOURCE_BUILD_ERROR',
                    pending_job_id = NULL::uuid,
                    dirty = true,
                    error_json = jsonb_build_object(
                      'code', v_candidate_failure_code,
                      'message', v_candidate_failure_message,
                      'job_id', v_owner.id::text,
                      'attempt_count', COALESCE(v_owner.attempt_count, 0),
                      'max_attempts', COALESCE(v_owner.max_attempts, 8),
                      'automatic_recovery_scheduled', false,
                      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                    ),
                    updated_at_utc = v_now
                WHERE failed_scope.id = v_scope.id
                  AND failed_scope.pending_job_id IS NOT DISTINCT FROM v_scope.pending_job_id;

                GET DIAGNOSTICS v_scope_transition_row_count = ROW_COUNT;

                UPDATE public.banking_pay_workbench_session_candidate_state AS failed_state
                SET status = 'FAILED',
                    pending_job_id = NULL::uuid,
                    last_error_json = jsonb_build_object(
                      'code', v_candidate_failure_code,
                      'message', v_candidate_failure_message,
                      'job_id', v_owner.id::text,
                      'attempt_count', COALESCE(v_owner.attempt_count, 0),
                      'max_attempts', COALESCE(v_owner.max_attempts, 8),
                      'automatic_recovery_scheduled', false,
                      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                    ),
                    updated_at_utc = v_now
                WHERE failed_state.session_id = v_scope.session_id
                  AND failed_state.candidate_id = v_scope.candidate_id
                  AND UPPER(BTRIM(COALESCE(failed_state.status, ''))) = 'PENDING'
                  AND (
                    failed_state.pending_job_id IS NULL
                    OR failed_state.pending_job_id = v_owner.id
                    OR EXISTS (
                      SELECT 1
                      FROM public.banking_pay_workbench_jobs AS state_owner
                      WHERE state_owner.id = failed_state.pending_job_id
                        AND state_owner.session_id = v_scope.session_id
                        AND state_owner.candidate_id = v_scope.candidate_id
                        AND state_owner.economic_build_id IS NOT DISTINCT FROM v_owner.economic_build_id
                    )
                  );

                SELECT failed_post_scope.*
                INTO v_post_scope
                FROM public.banking_pay_workbench_session_scope AS failed_post_scope
                WHERE failed_post_scope.id = v_scope.id
                FOR UPDATE;

                IF UPPER(BTRIM(COALESCE(v_post_scope.status, ''))) = 'SOURCE_BUILD_ERROR'
                   AND v_post_scope.pending_job_id IS NULL
                   AND COALESCE(v_post_scope.dirty, false) IS TRUE
                   AND v_post_scope.error_json->>'code' = 'WORKBENCH_PENDING_SCOPE_WITHOUT_ACTIVE_JOB'
                   AND LOWER(BTRIM(COALESCE(v_post_scope.error_json->>'automatic_recovery_scheduled', ''))) = 'false' THEN
                  IF v_scope_transition_row_count = 1 THEN
                    v_candidate_action := 'FAILED_CLOSED_MAX_ATTEMPTS';
                    v_candidate_branch := 'FAILED_CLOSED';
                    v_candidate_transition_proven := true;
                  ELSE
                    v_candidate_skipped := true;
                    v_candidate_action := 'SKIPPED_AFTER_RECHECK';
                  END IF;
                ELSE
                  RAISE EXCEPTION 'PAY_WORKBENCH_OWNER_REPAIR_POSTCONDITION_NOT_PROVEN'
                    USING ERRCODE = 'P0001';
                END IF;
              ELSE
                v_refresh_scope_kind := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(v_owner.payload_json->>'refresh_scope_kind', ''))), ''), 'CANDIDATE_FULL_LIVE');
                IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
                  v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
                END IF;
                v_targeted_timesheet_ids := CASE
                  WHEN jsonb_typeof(v_owner.payload_json->'targeted_timesheet_ids') = 'array'
                    THEN v_owner.payload_json->'targeted_timesheet_ids'
                  ELSE '[]'::jsonb
                END;
                v_linked_timesheet_ids := CASE
                  WHEN jsonb_typeof(v_owner.payload_json->'linked_timesheet_ids') = 'array'
                    THEN v_owner.payload_json->'linked_timesheet_ids'
                  ELSE '[]'::jsonb
                END;
                v_pay_channel_scope := COALESCE(NULLIF(UPPER(BTRIM(COALESCE(v_owner.payload_json->>'pay_channel_scope', ''))), ''), 'ALL');
                IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
                  v_pay_channel_scope := 'ALL';
                END IF;

                BEGIN
                  v_enqueue_payload := jsonb_build_object(
                    'session_id', v_session.id::text,
                    'source_session_id', v_session.id::text,
                    'candidate_id', v_scope.candidate_id::text,
                    'session_version', v_session.version,
                    'source_change_seq', v_live_change_seq,
                    'refresh_scope_kind', v_refresh_scope_kind,
                    'targeted_timesheet_ids', v_targeted_timesheet_ids,
                    'linked_timesheet_ids', v_linked_timesheet_ids,
                    'pay_channel_scope', v_pay_channel_scope,
                    'force_legacy', true,
                    'force_broad_legacy', v_refresh_scope_kind = 'CANDIDATE_FULL_LIVE',
                    'owner_repair', true,
                    'owner_repair_reason', v_owner_reason,
                    'replaces_job_id', CASE WHEN v_owner.id IS NULL THEN NULL ELSE v_owner.id::text END,
                    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                  );

                  IF v_owner_generation_obsolete
                     AND lower(BTRIM(COALESCE(
                       v_owner.payload_json->>'bounded_scope_state_precedes_job','false'
                     ))) IN ('true','t','1','yes','y','on')
                     AND COALESCE(v_owner.payload_json->>'scope_change_tx_token','') ~*
                       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                     AND COALESCE(v_owner.payload_json->>'scope_change_generation','') ~ '^\d+$' THEN
                    v_enqueue_payload := v_enqueue_payload || jsonb_build_object(
                      'bounded_scope_state_precedes_job',true,
                      'scope_change_tx_token',v_owner.payload_json->>'scope_change_tx_token',
                      'scope_change_generation',(v_owner.payload_json->>'scope_change_generation')::bigint
                    );
                  END IF;
                  v_enqueue_result := public.pay_workbench_enqueue_candidate_refresh(
                    p_snapshot_run_id => v_session.source_snapshot_run_id,
                    p_candidate_id => v_scope.candidate_id,
                    p_reason => v_reason,
                    p_actor_user_id => v_session.actor_user_id,
                    p_payload_json => v_enqueue_payload
                  );

                  IF COALESCE(v_enqueue_result->>'job_id', '') ~*
                     '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
                    v_successor_job_id := (v_enqueue_result->>'job_id')::uuid;
                  END IF;

                  SELECT successor_job.payload_json->>'source_build_run_id'
                  INTO v_successor_run_id_text
                  FROM public.banking_pay_workbench_jobs AS successor_job
                  JOIN public.banking_pay_workbench_session_scope AS successor_scope
                    ON successor_scope.session_id = successor_job.session_id
                   AND successor_scope.candidate_id = successor_job.candidate_id
                  WHERE successor_job.id = v_successor_job_id
                    AND successor_job.session_id = v_session.id
                    AND successor_job.candidate_id = v_scope.candidate_id
                    AND UPPER(BTRIM(COALESCE(successor_job.status, ''))) IN ('QUEUED', 'RUNNING')
                    AND UPPER(BTRIM(COALESCE(successor_job.job_type, ''))) = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
                    AND successor_scope.pending_job_id = successor_job.id
                    AND UPPER(BTRIM(COALESCE(successor_scope.status, ''))) = 'SOURCE_BUILD_PENDING'
                    AND COALESCE(successor_scope.dirty, false) IS TRUE
                    AND successor_scope.error_json IS NULL
                    AND CASE
                          WHEN COALESCE(successor_job.payload_json->>'session_version', '') ~ '^[0-9]{1,18}$'
                            THEN (successor_job.payload_json->>'session_version')::bigint
                          ELSE NULL::bigint
                        END = v_session.version
                    AND CASE
                          WHEN COALESCE(successor_job.payload_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$'
                            THEN (successor_job.payload_json->>'source_change_seq')::bigint
                          ELSE NULL::bigint
                        END >= v_live_change_seq
                    AND COALESCE(successor_job.payload_json->>'source_build_run_id', '') ~*
                        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  FOR UPDATE OF successor_job, successor_scope;
                  v_successor_valid := FOUND;

                  SELECT final_successor_scope.*
                  INTO v_post_scope
                  FROM public.banking_pay_workbench_session_scope AS final_successor_scope
                  WHERE final_successor_scope.id = v_scope.id
                  FOR UPDATE;

                  IF v_successor_valid IS NOT TRUE
                     OR UPPER(BTRIM(COALESCE(v_post_scope.status, ''))) <> 'SOURCE_BUILD_PENDING'
                     OR v_post_scope.pending_job_id IS DISTINCT FROM v_successor_job_id
                     OR COALESCE(v_post_scope.dirty, false) IS NOT TRUE
                     OR v_post_scope.error_json IS NOT NULL THEN
                    RAISE EXCEPTION 'PAY_WORKBENCH_OWNER_REPAIR_SUCCESSOR_INVALID'
                      USING ERRCODE = 'P0001';
                  END IF;

                  IF v_owner.id IS NOT NULL THEN
                    UPDATE public.banking_pay_workbench_jobs AS repaired_old_job
                    SET payload_json = COALESCE(repaired_old_job.payload_json, '{}'::jsonb)
                      || jsonb_build_object(
                        'owner_repair_applied', true,
                        'owner_repair_reason', v_owner_reason,
                        'owner_repair_successor_job_id', v_successor_job_id::text,
                        'owner_repair_successor_source_build_run_id', v_successor_run_id_text,
                        'owner_repair_at_utc', v_now::text
                      ),
                        updated_at_utc = v_now
                    WHERE repaired_old_job.id = v_owner.id;
                  END IF;

                  v_candidate_action := 'ENQUEUED_CANONICAL_SUCCESSOR';
                  v_candidate_branch := 'ENQUEUED';
                  v_candidate_transition_proven := true;
                EXCEPTION WHEN OTHERS THEN
                  v_successor_job_id := NULL::uuid;
                  v_successor_run_id_text := NULL::text;
                  v_successor_valid := false;
                  v_candidate_failure_code := 'WORKBENCH_PENDING_SCOPE_WITHOUT_ACTIVE_JOB';
                  v_candidate_failure_message := 'Candidate refresh could not be scheduled automatically. Refresh Banking Pay or retry the candidate.';

                  UPDATE public.banking_pay_workbench_session_scope AS failed_repair_scope
                  SET status = 'SOURCE_BUILD_ERROR',
                      pending_job_id = NULL::uuid,
                      dirty = true,
                      error_json = jsonb_build_object(
                        'code', v_candidate_failure_code,
                        'message', v_candidate_failure_message,
                        'job_id', CASE WHEN v_owner.id IS NULL THEN NULL ELSE v_owner.id::text END,
                        'automatic_recovery_scheduled', false,
                        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                      ),
                      updated_at_utc = v_now
                  WHERE failed_repair_scope.id = v_scope.id
                    AND failed_repair_scope.pending_job_id IS NOT DISTINCT FROM v_scope.pending_job_id;

                  GET DIAGNOSTICS v_scope_transition_row_count = ROW_COUNT;

                  SELECT failed_repair_post_scope.*
                  INTO v_post_scope
                  FROM public.banking_pay_workbench_session_scope AS failed_repair_post_scope
                  WHERE failed_repair_post_scope.id = v_scope.id
                  FOR UPDATE;

                  IF UPPER(BTRIM(COALESCE(v_post_scope.status, ''))) = 'SOURCE_BUILD_ERROR'
                     AND v_post_scope.pending_job_id IS NULL
                     AND COALESCE(v_post_scope.dirty, false) IS TRUE
                     AND v_post_scope.error_json->>'code' = 'WORKBENCH_PENDING_SCOPE_WITHOUT_ACTIVE_JOB'
                     AND LOWER(BTRIM(COALESCE(v_post_scope.error_json->>'automatic_recovery_scheduled', ''))) = 'false' THEN
                    IF v_scope_transition_row_count = 1 THEN
                      v_candidate_action := 'FAILED_CLOSED_REPAIR_ERROR';
                      v_candidate_branch := 'FAILED_CLOSED';
                      v_candidate_transition_proven := true;
                    ELSE
                      v_candidate_skipped := true;
                      v_candidate_action := 'SKIPPED_AFTER_RECHECK';
                    END IF;
                  ELSE
                    RAISE EXCEPTION 'PAY_WORKBENCH_OWNER_REPAIR_POSTCONDITION_NOT_PROVEN'
                      USING ERRCODE = 'P0001';
                  END IF;
                END;
              END IF;
            END IF;

            IF v_candidate_skipped IS NOT TRUE
               AND v_candidate_transition_proven IS NOT TRUE THEN
              RAISE EXCEPTION 'PAY_WORKBENCH_OWNER_REPAIR_POSTCONDITION_NOT_PROVEN'
                USING ERRCODE = 'P0001';
            END IF;

            IF v_candidate_transition_proven THEN
              BEGIN
                v_progress_recompute_result := public.pay_workbench_session_recompute_progress_counters(
                  p_session_id => v_scope.session_id,
                  p_apply => true,
                  p_reason => CASE v_candidate_action
                    WHEN 'RECONCILED_SUCCESSFUL_BUILD' THEN 'OWNER_REPAIR_RECONCILED_SUCCESSFUL_BUILD'
                    WHEN 'REBOUND_ACTIVE_SUCCESSOR' THEN 'OWNER_REPAIR_REBOUND_ACTIVE_SUCCESSOR'
                    WHEN 'ENQUEUED_CANONICAL_SUCCESSOR' THEN 'OWNER_REPAIR_ENQUEUED_CANONICAL_SUCCESSOR'
                    WHEN 'FAILED_CLOSED_MAX_ATTEMPTS' THEN 'OWNER_REPAIR_FAILED_CLOSED_MAX_ATTEMPTS'
                    ELSE 'OWNER_REPAIR_FAILED_CLOSED_REPAIR_ERROR'
                  END,
                  p_write_progress_json => true
                );

                v_progress_recomputed := jsonb_typeof(v_progress_recompute_result) = 'object'
                  AND LOWER(BTRIM(COALESCE(v_progress_recompute_result->>'ok', ''))) = 'true';

                IF v_progress_recomputed IS NOT TRUE THEN
                  RAISE EXCEPTION 'PAY_WORKBENCH_OWNER_REPAIR_PROGRESS_RECOMPUTE_NOT_CONFIRMED'
                    USING ERRCODE = 'P0001';
                END IF;
              EXCEPTION WHEN OTHERS THEN
                v_progress_recomputed := false;
                v_progress_recompute_error_code := SQLSTATE;
              END;

              BEGIN
                PERFORM public._audit_insert(
                  'banking_pay_workbench_session_scope',
                  v_scope.candidate_id::text,
                  'PENDING_SOURCE_BUILD_OWNER_REPAIRED',
                  jsonb_build_object(
                    'session_id', v_scope.session_id::text,
                    'candidate_id', v_scope.candidate_id::text,
                    'old_pending_job_id', CASE WHEN v_scope.pending_job_id IS NULL THEN NULL ELSE v_scope.pending_job_id::text END,
                    'owner_failure_reason', v_owner_reason
                  ),
                  jsonb_build_object(
                    'session_id', v_scope.session_id::text,
                    'candidate_id', v_scope.candidate_id::text,
                    'action', v_candidate_action,
                    'successor_job_id', CASE WHEN v_successor_job_id IS NULL THEN NULL ELSE v_successor_job_id::text END,
                    'automatic_recovery_scheduled', v_candidate_action IN ('REBOUND_ACTIVE_SUCCESSOR', 'ENQUEUED_CANONICAL_SUCCESSOR'),
                    'state_transition_proven', true,
                    'progress_recomputed', v_progress_recomputed,
                    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
                  ),
                  'PAY_WORKBENCH_PENDING_SOURCE_BUILD_OWNER_REPAIR',
                  v_session.actor_user_id
                );
              EXCEPTION WHEN OTHERS THEN
                v_audit_failed := true;
              END;
            END IF;
          END IF;
        END IF;
      END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_candidate_transition_proven := false;
      v_candidate_unresolved := true;
      v_candidate_skipped := false;
      v_candidate_action := 'UNRESOLVED_POSTCONDITION_NOT_PROVEN';
      v_candidate_branch := NULL::text;
      v_candidate_failure_code := 'WORKBENCH_PENDING_SCOPE_WITHOUT_ACTIVE_JOB';
      v_candidate_failure_message := NULL::text;
      v_candidate_unresolved_reason := 'POSTCONDITION_NOT_PROVEN';
      v_successor_job_id := NULL::uuid;
      v_progress_recomputed := false;
      v_progress_recompute_error_code := NULL::text;
      v_audit_failed := false;
    END;

    IF v_candidate_skipped THEN
      v_skipped_count := v_skipped_count + 1;
    ELSIF v_candidate_unresolved THEN
      v_unresolved_count := v_unresolved_count + 1;
      v_result_rows := v_result_rows || jsonb_build_array(
        jsonb_strip_nulls(jsonb_build_object(
          'session_id', v_candidate.session_id::text,
          'candidate_id', v_candidate.candidate_id::text,
          'old_pending_job_id', CASE WHEN v_candidate_old_pending_job_id IS NULL THEN NULL ELSE v_candidate_old_pending_job_id::text END,
          'owner_failure_reason', COALESCE(v_owner_reason, 'PENDING_OWNER_REVALIDATION_FAILED'),
          'action', v_candidate_action,
          'automatic_recovery_scheduled', false,
          'failure_code', v_candidate_failure_code,
          'unresolved_reason', v_candidate_unresolved_reason,
          'retry_safe', true,
          'audit_failed', v_audit_failed
        )) || jsonb_build_object(
          'state_transition_proven', false,
          'repaired', false,
          'progress_recomputed', false,
          'progress_recompute_error_code', NULL::text
        )
      );
    ELSIF v_candidate_transition_proven THEN
      v_repaired_count := v_repaired_count + 1;

      CASE v_candidate_branch
        WHEN 'RECONCILED' THEN
          v_reconciled_count := v_reconciled_count + 1;
        WHEN 'REBOUND' THEN
          v_rebound_count := v_rebound_count + 1;
        WHEN 'ENQUEUED' THEN
          v_enqueued_count := v_enqueued_count + 1;
        WHEN 'FAILED_CLOSED' THEN
          v_failed_closed_count := v_failed_closed_count + 1;
        ELSE
          NULL;
      END CASE;

      IF v_progress_recomputed THEN
        v_progress_recomputed_count := v_progress_recomputed_count + 1;
      ELSE
        v_progress_recompute_failed_count := v_progress_recompute_failed_count + 1;
      END IF;

      v_result_rows := v_result_rows || jsonb_build_array(
        jsonb_strip_nulls(jsonb_build_object(
          'session_id', v_scope.session_id::text,
          'candidate_id', v_scope.candidate_id::text,
          'old_pending_job_id', CASE WHEN v_scope.pending_job_id IS NULL THEN NULL ELSE v_scope.pending_job_id::text END,
          'owner_failure_reason', v_owner_reason,
          'action', v_candidate_action,
          'successor_job_id', CASE WHEN v_successor_job_id IS NULL THEN NULL ELSE v_successor_job_id::text END,
          'automatic_recovery_scheduled', v_candidate_action IN ('REBOUND_ACTIVE_SUCCESSOR', 'ENQUEUED_CANONICAL_SUCCESSOR'),
          'failure_code', v_candidate_failure_code,
          'message', v_candidate_failure_message,
          'audit_failed', v_audit_failed
        )) || jsonb_build_object(
          'state_transition_proven', true,
          'repaired', true,
          'progress_recomputed', v_progress_recomputed,
          'progress_recompute_error_code', v_progress_recompute_error_code
        )
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'repair_code', 'PAY_WORKBENCH_PENDING_SOURCE_BUILD_OWNER_REPAIR',
    'expired_attempt_count',v_expired_attempt_count,
    'expired_attempt_requeued_count',v_expired_requeued_count,
    'expired_attempt_exhausted_count',v_expired_exhausted_count,
    'examined_count', jsonb_array_length(v_result_rows) + v_skipped_count,
    'repaired_count', v_repaired_count,
    'reconciled_count', v_reconciled_count,
    'rebound_count', v_rebound_count,
    'enqueued_count', v_enqueued_count,
    'failed_closed_count', v_failed_closed_count,
    'skipped_count', v_skipped_count,
    'unresolved_count', v_unresolved_count,
    'progress_recomputed_count', v_progress_recomputed_count,
    'progress_recompute_failed_count', v_progress_recompute_failed_count,
    'all_state_transitions_proven', v_unresolved_count = 0,
    'all_progress_recomputed', v_progress_recompute_failed_count = 0,
    'partial', v_unresolved_count > 0 OR v_progress_recompute_failed_count > 0,
    'automatic_recovery_scheduled', (v_rebound_count + v_enqueued_count) > 0,
    'results', v_result_rows,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- pay_workbench_revalidate_zero_retained_recovery_headroom_v1(uuid,uuid)
CREATE OR REPLACE FUNCTION public.pay_workbench_revalidate_zero_retained_recovery_headroom_v1(p_session_id uuid, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
 SET "plpgsql_check.profiler" TO 'off'
 SET "plpgsql_check.tracer" TO 'off'
 SET "plpgsql_check.constants_tracing" TO 'off'
 SET "plpgsql_check.cursors_leaks" TO 'off'
 SET "plpgsql_check.strict_cursors_leaks" TO 'off'
 SET "plpgsql_check.fatal_errors" TO 'off'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_nonterminal_line_count integer := 0;
  v_retained_positive_headroom numeric(12,2) := 0;
  v_recovery_group_count integer := 0;
  v_promoted_count integer := 0;
  v_promoted_selected_count integer := 0;
  v_repaired_authority_scope_count integer := 0;
  v_ready_recovery_capped_count integer := 0;
  v_ready_recovery_blocked_count integer := 0;
  v_demoted_count integer := 0;
  v_superseded_count integer := 0;
  v_line_work_revalidated_count integer := 0;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_row_count integer := 0;
  v_selection_intent_mode text := '';
  v_progress_json jsonb := '{}'::jsonb;
  v_scope_attestation jsonb := '{}'::jsonb;
  v_v3_overlay_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  SELECT session_row.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_FOUND',
              'session_id', p_session_id::text
            )::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_session_row.status, ''))) <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_SESSION_NOT_OPEN',
              'session_id', p_session_id::text,
              'status', v_session_row.status
            )::text;
  END IF;

  SELECT COALESCE(scope_row.certified_preview_publication_attestation_json, '{}'::jsonb)
  INTO v_scope_attestation
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_RECOVERY_HEADROOM_CANDIDATE_NOT_IN_SCOPE',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text
            )::text;
  END IF;

  v_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
        THEN 'EXPLICIT_INCLUDE'
      ELSE 'IMPLICIT_ALL'
    END
  )));
  IF v_selection_intent_mode NOT IN ('IMPLICIT_ALL', 'EXPLICIT_INCLUDE') THEN
    v_selection_intent_mode := CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
        THEN 'EXPLICIT_INCLUDE'
      ELSE 'IMPLICIT_ALL'
    END;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_nonterminal_line_count
  FROM public.banking_pay_workbench_candidate_line_work AS line_work
  WHERE line_work.session_id = p_session_id
    AND line_work.candidate_id = p_candidate_id
    AND UPPER(BTRIM(COALESCE(line_work.status, ''))) NOT IN (
      'MATERIALISED',
      'SKIPPED',
      'ERROR',
      'FAILED',
      'CANCELLED',
      'CANCELED',
      'SUPERSEDED',
      'RETIRED'
    );

  IF COALESCE(v_nonterminal_line_count, 0) > 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'DEFERRED_UNTIL_FINAL_MATERIALISATION',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'nonterminal_line_count', v_nonterminal_line_count,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    );
  END IF;

  -- V3 keeps the certified source/preview identity immutable.  Recovery
  -- readiness is a pre-Draft selection projection: it is recalculated from
  -- positive rows the candidate has actually selected, while the physical
  -- source-backed preview section remains unchanged for exact parity.
  IF v_scope_attestation->>'attestation_version' = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
     AND v_scope_attestation->>'contract_version' = '3'
     AND v_scope_attestation->>'semantic_contract_version' = 'READY_TO_PAY_SEMANTIC_V2' THEN
    v_v3_overlay_result := private.pay_workbench_recovery_selection_overlay_apply_v1(
      p_session_id,
      p_candidate_id,
      jsonb_build_object('reason', 'SELECTION_REVALIDATION')
    );

    RETURN COALESCE(v_v3_overlay_result, '{}'::jsonb)
      || jsonb_build_object(
        'legacy_physical_section_revalidation_skipped', true,
        'certified_source_preview_identity_preserved', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
  END IF;

  SELECT ROUND(COALESCE(SUM(
           CASE
             WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
               THEN GREATEST((preview_row.row_json->>'amount_ex_vat')::numeric, 0)
             ELSE 0::numeric
           END
         ), 0), 2)::numeric(12,2)
  INTO v_retained_positive_headroom
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.session_version = COALESCE(v_session_row.version, 1)
    AND preview_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    AND (
      v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
      OR (
        COALESCE(preview_row.selected, false) IS TRUE
        AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
      )
      OR (
        LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
      )
    )
    AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) NOT IN (
      'MANUAL_DEBT_RECOVERY',
      'OVERPAYMENT_RECOVERY',
      'LOAN_REPAYMENT',
      'PAYMENT_ADVANCE_REPAYMENT'
    );

  IF COALESCE(v_retained_positive_headroom, 0) > 0 THEN
    /*
     * A recovery line may have been materialised before the candidate's final
     * positive correction carrier. In that order it is correctly emitted as
     * NO_PAY_HEADROOM, but the terminal candidate view is then stale once the
     * positive carrier exists. Reconcile the other direction here as well:
     * promote only rows whose sole blocker is NO_PAY_HEADROOM, allocate against
     * retained positive pay in the same pay channel, and leave every financial
     * amount sourced from the already-materialised pre-draft authority.
     */
    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_ready_recovery_allocation;
    CREATE TEMP TABLE _tmp_pay_wb_ready_recovery_allocation ON COMMIT DROP AS
    WITH positive_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          positive_row.row_json->>'pay_channel',
          positive_row.row_json->>'current_pay_method',
          positive_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN GREATEST((positive_row.row_json->>'amount_ex_vat')::numeric, 0)
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS positive_row
      WHERE positive_row.session_id = p_session_id
        AND positive_row.session_version = COALESCE(v_session_row.version, 1)
        AND positive_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(positive_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(positive_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(positive_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
          OR (
            COALESCE(positive_row.selected, false) IS TRUE
            AND UPPER(BTRIM(COALESCE(positive_row.selection_state, ''))) = 'SELECTED'
          )
          OR (
            LOWER(BTRIM(COALESCE(positive_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND UPPER(BTRIM(COALESCE(positive_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
          )
        )
        AND UPPER(BTRIM(COALESCE(positive_row.row_json->>'line_type', positive_row.row_json->>'item_type', ''))) NOT IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
      GROUP BY UPPER(BTRIM(COALESCE(
        positive_row.row_json->>'pay_channel',
        positive_row.row_json->>'current_pay_method',
        positive_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), ready_recovery AS (
      SELECT
        ready_row.id AS ready_preview_row_id,
        ready_row.row_key,
        ready_row.row_ordinal,
        ready_row.timesheet_id,
        ready_row.key_type,
        ready_row.key_value,
        ready_row.selected,
        ready_row.selection_state,
        COALESCE(ready_row.row_json, '{}'::jsonb) AS base_row_json,
        UPPER(BTRIM(COALESCE(
          ready_row.row_json->>'pay_channel',
          ready_row.row_json->>'current_pay_method',
          ready_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(
          CASE
            WHEN COALESCE((
              SELECT SUM(
                CASE
                  WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                    THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                  ELSE 0::numeric
                END
              )
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(ready_row.row_json->'case_components') = 'array'
                    THEN ready_row.row_json->'case_components'
                  ELSE '[]'::jsonb
                END
              ) AS component_row(value)
            ), 0) > 0
              THEN (
                SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
                FROM jsonb_array_elements(ready_row.row_json->'case_components') AS component_row(value)
                WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              )
            WHEN COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((ready_row.row_json->>'amount_ex_vat')::numeric) > 0
              THEN ABS((ready_row.row_json->>'amount_ex_vat')::numeric)
            WHEN COALESCE(ready_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((ready_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}')::numeric)
            WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            ELSE 0::numeric
          END,
          2
        )::numeric(12,2) AS nominal_due_amount_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS ready_row
      WHERE ready_row.session_id = p_session_id
        AND ready_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(ready_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
        AND ROUND((ready_row.row_json->>'amount_ex_vat')::numeric, 2) < 0
    ), ranked_recovery AS (
      SELECT
        ready_recovery.*,
        COALESCE(positive_by_channel.positive_headroom_ex_vat, 0)::numeric(12,2) AS positive_headroom_ex_vat,
        COALESCE(SUM(ready_recovery.nominal_due_amount_ex_vat) OVER (
          PARTITION BY ready_recovery.pay_channel
          ORDER BY ready_recovery.row_ordinal, ready_recovery.ready_preview_row_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::numeric(12,2) AS prior_nominal_due_amount_ex_vat
      FROM ready_recovery
      LEFT JOIN positive_by_channel
        ON positive_by_channel.pay_channel = ready_recovery.pay_channel
      WHERE ready_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
        AND ready_recovery.nominal_due_amount_ex_vat > 0
    ), allocated_recovery AS (
      SELECT
        ranked_recovery.*,
        ROUND(LEAST(
          ranked_recovery.nominal_due_amount_ex_vat,
          GREATEST(
            ranked_recovery.positive_headroom_ex_vat - ranked_recovery.prior_nominal_due_amount_ex_vat,
            0
          )
        ), 2)::numeric(12,2) AS recoverable_amount_ex_vat
      FROM ranked_recovery
    )
    SELECT
      allocated_recovery.*,
      ROUND(SUM(allocated_recovery.recoverable_amount_ex_vat) OVER (
        PARTITION BY allocated_recovery.pay_channel
      ), 2)::numeric(12,2) AS channel_recoverable_amount_ex_vat
    FROM allocated_recovery;

    WITH capped_source AS (
      SELECT
        allocation.ready_preview_row_id,
        allocation.base_row_json
          || jsonb_build_object(
            'amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'preview_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'amount_display', -allocation.recoverable_amount_ex_vat,
            'section_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'section_amount_display', -allocation.recoverable_amount_ex_vat,
            'target_pay_ex_vat', -allocation.recoverable_amount_ex_vat,
            'ready_preview_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'preview_component_amount_ex_vat', -allocation.recoverable_amount_ex_vat,
            'nominal_due_amount_ex_vat', allocation.nominal_due_amount_ex_vat,
            'recoverable_this_pay_run_ex_vat', allocation.recoverable_amount_ex_vat,
            'recovery_group_recoverable_this_pay_run_ex_vat', allocation.channel_recoverable_amount_ex_vat,
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
            'retained_positive_headroom_ex_vat', allocation.positive_headroom_ex_vat,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'case_resolution_summary', CASE
              WHEN jsonb_typeof(COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
                THEN COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)
                  || jsonb_build_object('due_amount_ex_vat', allocation.recoverable_amount_ex_vat)
              ELSE jsonb_build_object('due_amount_ex_vat', allocation.recoverable_amount_ex_vat)
            END
          ) AS capped_row_json
      FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
      WHERE allocation.recoverable_amount_ex_vat > 0
    ), contracted_source AS (
      SELECT
        capped_source.ready_preview_row_id,
        capped_source.capped_row_json,
        public.pay_workbench_preview_line_contract_ok(
          p_line_json => capped_source.capped_row_json,
          p_economic_key_json => COALESCE(capped_source.capped_row_json->'economic_key', '{}'::jsonb),
          p_target_section => 'canonical_preview_lines'
        ) AS capped_contract_json
      FROM capped_source
    )
    UPDATE public.banking_pay_workbench_preview_rows AS ready_row
    SET row_json = contracted_source.capped_row_json
          || jsonb_build_object(
            'preview_contract', contracted_source.capped_contract_json,
            'selection_allowed', true
          ),
        updated_at_utc = v_now
    FROM contracted_source
    WHERE ready_row.id = contracted_source.ready_preview_row_id
      AND LOWER(BTRIM(COALESCE(contracted_source.capped_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(contracted_source.capped_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    GET DIAGNOSTICS v_ready_recovery_capped_count = ROW_COUNT;

    INSERT INTO public.banking_pay_workbench_preview_rows (
      session_id,
      candidate_id,
      section,
      row_key,
      row_ordinal,
      row_json,
      timesheet_id,
      key_type,
      key_value,
      selected,
      selection_state,
      status,
      session_version,
      created_at_utc,
      updated_at_utc
    )
    SELECT
      p_session_id,
      p_candidate_id,
      'blocked_for_pay',
      allocation.row_key,
      allocation.row_ordinal,
      (
        allocation.base_row_json
        - 'source_basis_json'
        - 'frozen_source_basis_json'
        - 'frozen_component_snapshot_json'
        - 'finance_component_id'
        - 'materialised_from_line_work_id'
      )
      || jsonb_build_object(
        'line_key', allocation.row_key,
        'row_key', allocation.row_key,
        'presentation_line_id', allocation.row_key,
        'section', 'blocked_for_pay',
        'target_section', 'blocked_for_pay',
        'readiness_state', 'BLOCKED_FOR_PAY',
        'presentation_section', 'BLOCKED_FOR_PAY',
        'presentation_reason', 'NO_PAY_HEADROOM',
        'amount_ex_vat', 0,
        'preview_amount_ex_vat', 0,
        'amount_display', 0,
        'section_amount_ex_vat', 0,
        'section_amount_display', 0,
        'target_pay_ex_vat', 0,
        'ready_preview_amount_ex_vat', 0,
        'preview_component_amount_ex_vat', 0,
        'recoverable_this_pay_run_ex_vat', 0,
        'nominal_due_amount_ex_vat', allocation.nominal_due_amount_ex_vat,
        'draftable', false,
        'is_ready_for_draft', false,
        'selection_allowed', false,
        'is_excluded_from_allocation', true,
        'selected', false,
        'selection_state', 'NOT_SELECTABLE',
        'blocked_reason_codes', jsonb_build_array('NO_PAY_HEADROOM'),
        'materialisation_recovery_headroom_revalidated', true,
        'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
        'retained_positive_headroom_ex_vat', allocation.positive_headroom_ex_vat,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
        'case_resolution_summary', CASE
          WHEN jsonb_typeof(COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
            THEN COALESCE(allocation.base_row_json->'case_resolution_summary', '{}'::jsonb)
              || jsonb_build_object('due_amount_ex_vat', 0)
          ELSE jsonb_build_object('due_amount_ex_vat', 0)
        END
      )
      || jsonb_build_object(
        'preview_contract', COALESCE(allocation.base_row_json->'preview_contract', '{}'::jsonb)
          || jsonb_build_object(
            'line_key', allocation.row_key,
            'amount_ex_vat', 0,
            'draftable', false,
            'is_ready_for_draft', false,
            'selection_allowed', false,
            'is_excluded_from_allocation', true,
            'target_section', 'blocked_for_pay',
            'presentation_section', 'BLOCKED_FOR_PAY'
          )
      ),
      allocation.timesheet_id,
      allocation.key_type,
      allocation.key_value,
      false,
      'NOT_SELECTABLE',
      'READY',
      COALESCE(v_session_row.version, 1),
      v_now,
      v_now
    FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
    WHERE allocation.recoverable_amount_ex_vat <= 0
    ON CONFLICT (session_id, section, candidate_id, row_key)
    DO UPDATE
    SET row_ordinal = EXCLUDED.row_ordinal,
        row_json = EXCLUDED.row_json,
        timesheet_id = EXCLUDED.timesheet_id,
        key_type = EXCLUDED.key_type,
        key_value = EXCLUDED.key_value,
        selected = false,
        selection_state = 'NOT_SELECTABLE',
        status = 'READY',
        session_version = EXCLUDED.session_version,
        updated_at_utc = v_now;

    GET DIAGNOSTICS v_ready_recovery_blocked_count = ROW_COUNT;

    UPDATE public.banking_pay_workbench_preview_rows AS ready_row
    SET status = 'SUPERSEDED',
        selected = false,
        selection_state = 'SUPERSEDED',
        row_json = COALESCE(ready_row.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'selected', false,
            'selection_state', 'SUPERSEDED',
            'superseded_reason', 'RECOVERY_EXCEEDS_SELECTED_POSITIVE_HEADROOM',
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
          ),
        updated_at_utc = v_now
    WHERE ready_row.id IN (
      SELECT allocation.ready_preview_row_id
      FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
      WHERE allocation.recoverable_amount_ex_vat <= 0
    );

    IF COALESCE(v_ready_recovery_capped_count, 0) > 0
       OR COALESCE(v_ready_recovery_blocked_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = active_row.row_json,
          updated_at_utc = v_now
      FROM (
        SELECT ready_row.row_key, ready_row.row_json
        FROM public.banking_pay_workbench_preview_rows AS ready_row
        WHERE ready_row.session_id = p_session_id
          AND ready_row.session_version = COALESCE(v_session_row.version, 1)
          AND ready_row.candidate_id = p_candidate_id
          AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
          AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        UNION ALL
        SELECT blocked_row.row_key, blocked_row.row_json
        FROM public.banking_pay_workbench_preview_rows AS blocked_row
        WHERE blocked_row.session_id = p_session_id
          AND blocked_row.session_version = COALESCE(v_session_row.version, 1)
          AND blocked_row.candidate_id = p_candidate_id
          AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
          AND UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY'
      ) AS active_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND line_work.line_key = active_row.row_key
        AND EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_ready_recovery_allocation AS allocation
          WHERE allocation.row_key = line_work.line_key
        );
    END IF;

    WITH repair_source AS (
      SELECT
        ready_recovery_row.id,
        ready_recovery_row.row_json
          || jsonb_build_object(
            'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
            'materialisation_recovery_headroom_revalidated', true,
            'materialisation_recovery_headroom_revalidated_at_utc', v_now::text
          ) AS repaired_row_json
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.row_json->>'materialisation_recovery_headroom_revalidated', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'line_type', ready_recovery_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    ), contracted_repair AS (
      SELECT
        repair_source.id,
        repair_source.repaired_row_json,
        public.pay_workbench_preview_line_contract_ok(
          p_line_json => repair_source.repaired_row_json,
          p_economic_key_json => COALESCE(repair_source.repaired_row_json->'economic_key', '{}'::jsonb),
          p_target_section => 'canonical_preview_lines'
        ) AS repaired_contract_json
      FROM repair_source
    )
    UPDATE public.banking_pay_workbench_preview_rows AS ready_recovery_row
    SET row_json = contracted_repair.repaired_row_json
          || jsonb_build_object(
            'preview_contract', contracted_repair.repaired_contract_json,
            'selection_allowed', true
          ),
        updated_at_utc = v_now
    FROM contracted_repair
    WHERE ready_recovery_row.id = contracted_repair.id
      AND LOWER(BTRIM(COALESCE(contracted_repair.repaired_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      AND LOWER(BTRIM(COALESCE(contracted_repair.repaired_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    GET DIAGNOSTICS v_repaired_authority_scope_count = ROW_COUNT;

    IF COALESCE(v_repaired_authority_scope_count, 0) > 0 THEN
      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = ready_recovery_row.row_json,
          updated_at_utc = v_now
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND ready_recovery_row.updated_at_utc = v_now
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
        AND line_work.line_key = ready_recovery_row.row_key;
    END IF;

    DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_positive_headroom_recovery;
    CREATE TEMP TABLE _tmp_pay_wb_positive_headroom_recovery ON COMMIT DROP AS
    WITH gross_positive_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          preview_row.row_json->>'pay_channel',
          preview_row.row_json->>'current_pay_method',
          preview_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN GREATEST((preview_row.row_json->>'amount_ex_vat')::numeric, 0)
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.session_version = COALESCE(v_session_row.version, 1)
        AND preview_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'draftable', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'is_ready_for_draft', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(preview_row.row_json->>'post_draft_overlay_applied', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          v_selection_intent_mode <> 'EXPLICIT_INCLUDE'
          OR (
            COALESCE(preview_row.selected, false) IS TRUE
            AND UPPER(BTRIM(COALESCE(preview_row.selection_state, ''))) = 'SELECTED'
          )
          OR (
            LOWER(BTRIM(COALESCE(preview_row.row_json->>'selection_allowed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'policy_x_authority_scope', ''))) = 'PRE_DRAFT_LIVE_TRUTH'
          )
        )
        AND UPPER(BTRIM(COALESCE(preview_row.row_json->>'line_type', preview_row.row_json->>'item_type', ''))) NOT IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
      GROUP BY UPPER(BTRIM(COALESCE(
        preview_row.row_json->>'pay_channel',
        preview_row.row_json->>'current_pay_method',
        preview_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), ready_recovery_by_channel AS (
      SELECT
        UPPER(BTRIM(COALESCE(
          ready_recovery_row.row_json->>'pay_channel',
          ready_recovery_row.row_json->>'current_pay_method',
          ready_recovery_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(COALESCE(SUM(
          CASE
            WHEN COALESCE(ready_recovery_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS(LEAST((ready_recovery_row.row_json->>'amount_ex_vat')::numeric, 0))
            ELSE 0::numeric
          END
        ), 0), 2)::numeric(12,2) AS allocated_recovery_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS ready_recovery_row
      WHERE ready_recovery_row.session_id = p_session_id
        AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_recovery_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(ready_recovery_row.row_json->>'line_type', ready_recovery_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
      GROUP BY UPPER(BTRIM(COALESCE(
        ready_recovery_row.row_json->>'pay_channel',
        ready_recovery_row.row_json->>'current_pay_method',
        ready_recovery_row.row_json->>'candidate_pay_method',
        ''
      )))
    ), positive_by_channel AS (
      SELECT
        gross_positive.pay_channel,
        ROUND(GREATEST(
          gross_positive.positive_headroom_ex_vat
            - COALESCE(ready_recovery.allocated_recovery_ex_vat, 0),
          0
        ), 2)::numeric(12,2) AS positive_headroom_ex_vat
      FROM gross_positive_by_channel AS gross_positive
      LEFT JOIN ready_recovery_by_channel AS ready_recovery
        ON ready_recovery.pay_channel = gross_positive.pay_channel
    ), blocked_recovery AS (
      SELECT
        blocked_row.id AS blocked_preview_row_id,
        blocked_row.candidate_id,
        blocked_row.row_key,
        blocked_row.row_ordinal,
        blocked_row.timesheet_id,
        blocked_row.key_type,
        blocked_row.key_value,
        blocked_row.row_json AS base_row_json,
        UPPER(BTRIM(COALESCE(
          blocked_row.row_json->>'pay_channel',
          blocked_row.row_json->>'current_pay_method',
          blocked_row.row_json->>'candidate_pay_method',
          ''
        ))) AS pay_channel,
        ROUND(
          CASE
            WHEN COALESCE((
              SELECT SUM(
                CASE
                  WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                    THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                  ELSE 0::numeric
                END
              )
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(blocked_row.row_json->'case_components') = 'array'
                    THEN blocked_row.row_json->'case_components'
                  ELSE '[]'::jsonb
                END
              ) AS component_row(value)
            ), 0) > 0
              THEN (
                SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
                FROM jsonb_array_elements(blocked_row.row_json->'case_components') AS component_row(value)
                WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              )
            WHEN COALESCE(blocked_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             AND ABS((blocked_row.row_json->>'amount_ex_vat')::numeric) > 0
              THEN ABS((blocked_row.row_json->>'amount_ex_vat')::numeric)
            WHEN COALESCE(blocked_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((blocked_row.row_json#>>'{case_resolution_summary,due_amount_ex_vat}')::numeric)
            WHEN COALESCE(blocked_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
              THEN ABS((blocked_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
            ELSE 0::numeric
          END,
          2
        )::numeric(12,2) AS nominal_due_amount_ex_vat
      FROM public.banking_pay_workbench_preview_rows AS blocked_row
      WHERE blocked_row.session_id = p_session_id
        AND blocked_row.session_version = COALESCE(v_session_row.version, 1)
        AND blocked_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
        AND UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY'
        AND UPPER(BTRIM(COALESCE(blocked_row.row_json->>'line_type', blocked_row.row_json->>'item_type', ''))) IN (
          'MANUAL_DEBT_RECOVERY',
          'OVERPAYMENT_RECOVERY',
          'LOAN_REPAYMENT',
          'PAYMENT_ADVANCE_REPAYMENT'
        )
        AND (
          UPPER(BTRIM(COALESCE(blocked_row.row_json->>'presentation_reason', ''))) = 'NO_PAY_HEADROOM'
          OR COALESCE(blocked_row.row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
        )
        AND LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_is_blocked', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_needs_resolution_now', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND (
          LOWER(BTRIM(COALESCE(blocked_row.row_json->>'case_resolution_satisfied_now', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          OR UPPER(BTRIM(COALESCE(blocked_row.row_json->>'resolution_state', ''))) = 'RESOLVED'
          OR LOWER(BTRIM(COALESCE(blocked_row.row_json->>'is_case_resolution_satisfied', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        )
        AND NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(blocked_row.row_json->'blocked_reason_codes') = 'array'
                THEN blocked_row.row_json->'blocked_reason_codes'
              ELSE '[]'::jsonb
            END
          ) AS blocked_code(value)
          WHERE UPPER(BTRIM(blocked_code.value)) <> 'NO_PAY_HEADROOM'
        )
    ), ranked_recovery AS (
      SELECT
        blocked_recovery.*,
        COALESCE(positive_by_channel.positive_headroom_ex_vat, 0)::numeric(12,2) AS positive_headroom_ex_vat,
        COALESCE(SUM(blocked_recovery.nominal_due_amount_ex_vat) OVER (
          PARTITION BY blocked_recovery.pay_channel
          ORDER BY blocked_recovery.row_ordinal, blocked_recovery.blocked_preview_row_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ), 0)::numeric(12,2) AS prior_nominal_due_amount_ex_vat
      FROM blocked_recovery
      LEFT JOIN positive_by_channel
        ON positive_by_channel.pay_channel = blocked_recovery.pay_channel
      WHERE blocked_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
        AND ROUND(COALESCE(blocked_recovery.nominal_due_amount_ex_vat, 0), 2) > 0
    ), allocated_recovery AS (
      SELECT
        ranked_recovery.*,
        ROUND(LEAST(
          ranked_recovery.nominal_due_amount_ex_vat,
          GREATEST(
            ranked_recovery.positive_headroom_ex_vat - ranked_recovery.prior_nominal_due_amount_ex_vat,
            0
          )
        ), 2)::numeric(12,2) AS recoverable_amount_ex_vat
      FROM ranked_recovery
    )
    SELECT
      allocated_recovery.*,
      COALESCE(existing_ready.id, gen_random_uuid()) AS promoted_preview_row_id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(
          allocated_recovery.base_row_json->>'selection_user_override',
          existing_ready.row_json->>'selection_user_override',
          ''
        ))) = 'UNSELECTED'
          THEN false
        ELSE true
      END AS promoted_selected
    FROM allocated_recovery
    LEFT JOIN public.banking_pay_workbench_preview_rows AS existing_ready
      ON existing_ready.session_id = p_session_id
     AND existing_ready.session_version = COALESCE(v_session_row.version, 1)
     AND existing_ready.candidate_id = p_candidate_id
     AND LOWER(BTRIM(COALESCE(existing_ready.section, ''))) = 'canonical_preview_lines'
     AND existing_ready.row_key = allocated_recovery.row_key
    WHERE allocated_recovery.recoverable_amount_ex_vat > 0;

    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE promoted_selected)::integer
    INTO v_promoted_count,
         v_promoted_selected_count
    FROM pg_temp._tmp_pay_wb_positive_headroom_recovery;

    IF COALESCE(v_promoted_count, 0) > 0 THEN
      WITH promoted_payload AS (
        SELECT
          promotion.*,
          jsonb_strip_nulls(
            (
              promotion.base_row_json
              - 'blocked_reason_codes'
              - 'superseded_reason'
              - 'materialisation_recovery_headroom_revalidated'
              - 'materialisation_recovery_headroom_revalidated_at_utc'
            )
            || jsonb_build_object(
              'preview_row_id', promotion.promoted_preview_row_id::text,
              'line_id', promotion.promoted_preview_row_id::text,
              'section', 'canonical_preview_lines',
              'target_section', 'canonical_preview_lines',
              'readiness_state', 'READY',
              'presentation_section', 'READY_TO_PAY',
              'presentation_reason', NULL,
              'amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'preview_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'amount_display', -promotion.recoverable_amount_ex_vat,
              'section_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'section_amount_display', -promotion.recoverable_amount_ex_vat,
              'target_pay_ex_vat', -promotion.recoverable_amount_ex_vat,
              'ready_preview_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'preview_component_amount_ex_vat', -promotion.recoverable_amount_ex_vat,
              'nominal_due_amount_ex_vat', promotion.nominal_due_amount_ex_vat,
              'recoverable_this_pay_run_ex_vat', promotion.recoverable_amount_ex_vat,
              'draftable', true,
              'is_ready_for_draft', true,
              'selection_allowed', true,
              'is_excluded_from_allocation', false,
              'selected', promotion.promoted_selected,
              'selection_state', CASE WHEN promotion.promoted_selected THEN 'SELECTED' ELSE 'UNSELECTED' END,
              'selection_origin', CASE
                WHEN UPPER(BTRIM(COALESCE(promotion.base_row_json->>'selection_user_override', ''))) = 'UNSELECTED'
                  THEN 'USER_EXPLICIT_DESELECT'
                ELSE 'SERVER_DEFAULT_NEWLY_ELIGIBLE'
              END,
              'materialisation_recovery_headroom_revalidated', true,
              'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
              'retained_positive_headroom_ex_vat', promotion.positive_headroom_ex_vat,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            )
            || jsonb_build_object(
              'case_resolution_summary', CASE
                WHEN jsonb_typeof(COALESCE(promotion.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
                  THEN COALESCE(promotion.base_row_json->'case_resolution_summary', '{}'::jsonb)
                    || jsonb_build_object('due_amount_ex_vat', promotion.recoverable_amount_ex_vat)
                ELSE jsonb_build_object('due_amount_ex_vat', promotion.recoverable_amount_ex_vat)
              END
            )
          ) AS promoted_row_json
        FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
      ), contracted_payload AS (
        SELECT
          promoted_payload.*,
          public.pay_workbench_preview_line_contract_ok(
            p_line_json => promoted_payload.promoted_row_json,
            p_economic_key_json => COALESCE(promoted_payload.promoted_row_json->'economic_key', '{}'::jsonb),
            p_target_section => 'canonical_preview_lines'
          ) AS promoted_contract_json
        FROM promoted_payload
      )
      INSERT INTO public.banking_pay_workbench_preview_rows (
        id,
        session_id,
        candidate_id,
        section,
        row_key,
        row_ordinal,
        row_json,
        timesheet_id,
        key_type,
        key_value,
        selected,
        selection_state,
        status,
        session_version,
        created_at_utc,
        updated_at_utc
      )
      SELECT
        contracted_payload.promoted_preview_row_id,
        p_session_id,
        p_candidate_id,
        'canonical_preview_lines',
        contracted_payload.row_key,
        contracted_payload.row_ordinal,
        contracted_payload.promoted_row_json
          || jsonb_build_object(
            'preview_contract', contracted_payload.promoted_contract_json,
            'selection_allowed', true
          ),
        contracted_payload.timesheet_id,
        contracted_payload.key_type,
        contracted_payload.key_value,
        contracted_payload.promoted_selected,
        CASE WHEN contracted_payload.promoted_selected THEN 'SELECTED' ELSE 'UNSELECTED' END,
        'READY',
        COALESCE(v_session_row.version, 1),
        v_now,
        v_now
      FROM contracted_payload
      WHERE LOWER(BTRIM(COALESCE(contracted_payload.promoted_contract_json->>'ok', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND LOWER(BTRIM(COALESCE(contracted_payload.promoted_contract_json->>'selection_allowed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
      ON CONFLICT (session_id, section, candidate_id, row_key)
      DO UPDATE
      SET row_ordinal = EXCLUDED.row_ordinal,
          row_json = EXCLUDED.row_json,
          timesheet_id = EXCLUDED.timesheet_id,
          key_type = EXCLUDED.key_type,
          key_value = EXCLUDED.key_value,
          selected = EXCLUDED.selected,
          selection_state = EXCLUDED.selection_state,
          status = 'READY',
          session_version = EXCLUDED.session_version,
          updated_at_utc = v_now;

      UPDATE public.banking_pay_workbench_preview_rows AS blocked_row
      SET status = 'SUPERSEDED',
          selected = false,
          selection_state = 'SUPERSEDED',
          row_json = COALESCE(blocked_row.row_json, '{}'::jsonb)
            || jsonb_build_object(
              'selected', false,
              'selection_state', 'SUPERSEDED',
              'superseded_reason', 'POSITIVE_PAY_HEADROOM_AVAILABLE_AFTER_FINAL_MATERIALISATION',
              'materialisation_recovery_headroom_revalidated', true,
              'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE blocked_row.id IN (
        SELECT promotion.blocked_preview_row_id
        FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
      );

      UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
      SET result_row_json = ready_row.row_json,
          updated_at_utc = v_now
      FROM public.banking_pay_workbench_preview_rows AS ready_row
      WHERE line_work.session_id = p_session_id
        AND line_work.candidate_id = p_candidate_id
        AND ready_row.session_id = p_session_id
        AND ready_row.session_version = COALESCE(v_session_row.version, 1)
        AND ready_row.candidate_id = p_candidate_id
        AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
        AND ready_row.row_key = line_work.line_key
        AND EXISTS (
          SELECT 1
          FROM pg_temp._tmp_pay_wb_positive_headroom_recovery AS promotion
          WHERE promotion.row_key = line_work.line_key
        );

      v_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id,
        true,
        'POST_MATERIALISATION_RECOVERY_HEADROOM_PROMOTION',
        false
      );

      SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
             COUNT(*)::integer
      INTO v_selected_preview_row_ids,
           v_selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS selected_row
      WHERE selected_row.session_id = p_session_id
        AND selected_row.session_version = COALESCE(v_session_row.version, 1)
        AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
        AND COALESCE(selected_row.selected, false) = true
        AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

      v_selection_intent_mode := UPPER(BTRIM(COALESCE(
        v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
        ''
      )));

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET selected_row_count = COALESCE(v_selected_row_count, 0),
          server_selected_preview_row_ids = CASE
            WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
              OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
              THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
            ELSE session_row.server_selected_preview_row_ids
          END,
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_recovery_headroom_revalidation_at_utc', v_now::text,
              'last_recovery_headroom_revalidation_action', 'PROMOTED_RECOVERY_WITH_RETAINED_POSITIVE_PAY',
              'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
              'last_recovery_headroom_revalidation_promoted_count', COALESCE(v_promoted_count, 0),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE session_row.id = p_session_id;

      RETURN jsonb_build_object(
        'ok', true,
        'action', 'PROMOTED_RECOVERY_WITH_RETAINED_POSITIVE_PAY',
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
        'promoted_recovery_count', COALESCE(v_promoted_count, 0),
        'promoted_selected_count', COALESCE(v_promoted_selected_count, 0),
        'repaired_authority_scope_count', COALESCE(v_repaired_authority_scope_count, 0),
        'capped_ready_recovery_count', COALESCE(v_ready_recovery_capped_count, 0),
        'blocked_excess_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
        'selected_row_count', COALESCE(v_selected_row_count, 0),
        'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
        'demoted_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
        'post_draft_artifacts_touched', false,
        'payment_execution_started', false
      );
    END IF;

    IF COALESCE(v_ready_recovery_capped_count, 0) > 0
       OR COALESCE(v_ready_recovery_blocked_count, 0) > 0 THEN
      v_progress_json := public.pay_workbench_session_recompute_progress_counters(
        p_session_id,
        true,
        'POST_MATERIALISATION_RECOVERY_HEADROOM_CAP',
        false
      );

      SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
             COUNT(*)::integer
      INTO v_selected_preview_row_ids,
           v_selected_row_count
      FROM public.banking_pay_workbench_preview_rows AS selected_row
      WHERE selected_row.session_id = p_session_id
        AND selected_row.session_version = COALESCE(v_session_row.version, 1)
        AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
        AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
        AND COALESCE(selected_row.selected, false) IS TRUE
        AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

      UPDATE public.banking_pay_workbench_sessions AS session_row
      SET selected_row_count = COALESCE(v_selected_row_count, 0),
          server_selected_preview_row_ids = CASE
            WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
              OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
              THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
            ELSE session_row.server_selected_preview_row_ids
          END,
          progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'last_recovery_headroom_revalidation_at_utc', v_now::text,
              'last_recovery_headroom_revalidation_action', 'CAPPED_READY_RECOVERY_TO_POSITIVE_HEADROOM',
              'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
              'last_recovery_headroom_revalidation_capped_count', COALESCE(v_ready_recovery_capped_count, 0),
              'last_recovery_headroom_revalidation_blocked_excess_count', COALESCE(v_ready_recovery_blocked_count, 0),
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
            ),
          updated_at_utc = v_now
      WHERE session_row.id = p_session_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'action', CASE
        WHEN COALESCE(v_repaired_authority_scope_count, 0) > 0
          THEN 'REPAIRED_EXISTING_RECOVERY_AUTHORITY_SCOPE'
        ELSE 'RETAINED_POSITIVE_PAY_PRESENT'
      END,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
      'promoted_recovery_count', 0,
      'repaired_authority_scope_count', COALESCE(v_repaired_authority_scope_count, 0),
      'capped_ready_recovery_count', COALESCE(v_ready_recovery_capped_count, 0),
      'blocked_excess_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
      'selected_row_count', COALESCE(v_selected_row_count, 0),
      'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
      'demoted_recovery_count', COALESCE(v_ready_recovery_blocked_count, 0),
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
      'post_draft_artifacts_touched', false,
      'payment_execution_started', false
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_wb_zero_headroom_recovery;
  CREATE TEMP TABLE _tmp_pay_wb_zero_headroom_recovery ON COMMIT DROP AS
  SELECT ready_row.id AS ready_preview_row_id,
         ready_row.row_key AS ready_row_key,
         ready_row.row_json->>'finance_case_id' AS finance_case_id_text,
         UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) AS line_type,
         ready_row.row_ordinal,
         ready_row.timesheet_id,
         ready_row.key_type,
         ready_row.key_value,
         ready_row.row_key AS blocked_row_key,
         COALESCE(blocked_template.row_json, ready_row.row_json, '{}'::jsonb) AS base_row_json,
         CASE
           WHEN COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
            AND ABS((ready_row.row_json->>'amount_ex_vat')::numeric) > 0
             THEN ROUND(ABS((ready_row.row_json->>'amount_ex_vat')::numeric), 2)
           WHEN COALESCE((
             SELECT SUM(
               CASE
                 WHEN COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
                   THEN ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric)
                 ELSE 0::numeric
               END
             )
             FROM jsonb_array_elements(
               CASE
                 WHEN jsonb_typeof(ready_row.row_json->'case_components') = 'array'
                   THEN ready_row.row_json->'case_components'
                 ELSE '[]'::jsonb
               END
             ) AS component_row(value)
           ), 0) > 0
             THEN ROUND((
               SELECT SUM(ABS((component_row.value->>'preview_due_amount_ex_vat')::numeric))
               FROM jsonb_array_elements(ready_row.row_json->'case_components') AS component_row(value)
               WHERE COALESCE(component_row.value->>'preview_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             ), 2)
           WHEN COALESCE(ready_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
             THEN ROUND(ABS((ready_row.row_json->>'nominal_due_amount_ex_vat')::numeric), 2)
           ELSE 0::numeric
         END::numeric(12,2) AS nominal_due_amount_ex_vat
  FROM public.banking_pay_workbench_preview_rows AS ready_row
  LEFT JOIN LATERAL (
    SELECT blocked_row.row_key,
           blocked_row.row_json
    FROM public.banking_pay_workbench_preview_rows AS blocked_row
    WHERE blocked_row.session_id = ready_row.session_id
      AND blocked_row.session_version = ready_row.session_version
      AND blocked_row.candidate_id = ready_row.candidate_id
      AND LOWER(BTRIM(COALESCE(blocked_row.section, ''))) = 'blocked_for_pay'
      AND blocked_row.row_key = ready_row.row_key
    ORDER BY CASE WHEN UPPER(BTRIM(COALESCE(blocked_row.status, ''))) = 'READY' THEN 0 ELSE 1 END,
             blocked_row.updated_at_utc DESC,
             blocked_row.id
    LIMIT 1
  ) AS blocked_template ON true
  WHERE ready_row.session_id = p_session_id
    AND ready_row.session_version = COALESCE(v_session_row.version, 1)
    AND ready_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(ready_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(ready_row.status, ''))) = 'READY'
    AND ready_row.row_json->>'finance_case_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND UPPER(BTRIM(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'item_type', ''))) IN (
      'MANUAL_DEBT_RECOVERY',
      'OVERPAYMENT_RECOVERY',
      'LOAN_REPAYMENT',
      'PAYMENT_ADVANCE_REPAYMENT'
    )
    AND COALESCE(ready_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+([.][0-9]+)?$'
    AND ROUND((ready_row.row_json->>'amount_ex_vat')::numeric, 2) < 0
  ORDER BY ready_row.row_ordinal,
           ready_row.id;

  SELECT COUNT(*)::integer
  INTO v_recovery_group_count
  FROM pg_temp._tmp_pay_wb_zero_headroom_recovery;

  IF COALESCE(v_recovery_group_count, 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'action', 'NO_READY_RECOVERY_TO_REVALIDATE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
      'demoted_recovery_count', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    );
  END IF;

  INSERT INTO public.banking_pay_workbench_preview_rows (
    session_id,
    candidate_id,
    section,
    row_key,
    row_ordinal,
    row_json,
    timesheet_id,
    key_type,
    key_value,
    selected,
    selection_state,
    status,
    session_version,
    created_at_utc,
    updated_at_utc
  )
  SELECT
    p_session_id,
    p_candidate_id,
    'blocked_for_pay',
    recovery_row.blocked_row_key,
    recovery_row.row_ordinal,
    (
      recovery_row.base_row_json
      - 'source_basis_json'
      - 'frozen_source_basis_json'
      - 'frozen_component_snapshot_json'
      - 'finance_component_id'
      - 'materialised_from_line_work_id'
    )
    || jsonb_build_object(
      'line_key', recovery_row.blocked_row_key,
      'row_key', recovery_row.blocked_row_key,
      'presentation_line_id', recovery_row.blocked_row_key,
      'presentation_parent_line_id', NULL,
      'section', 'blocked_for_pay',
      'target_section', 'blocked_for_pay',
      'readiness_state', 'BLOCKED_FOR_PAY',
      'presentation_section', 'BLOCKED_FOR_PAY',
      'presentation_reason', 'NO_PAY_HEADROOM',
      'amount_ex_vat', 0,
      'preview_amount_ex_vat', 0,
      'amount_display', 0,
      'section_amount_ex_vat', 0,
      'section_amount_display', 0,
      'target_pay_ex_vat', 0,
      'ready_preview_amount_ex_vat', 0,
      'preview_component_amount_ex_vat', 0,
      'source_amount_ex_vat', 0,
      'source_reservation_amount_ex_vat', 0,
      'frozen_source_amount', 0,
      'frozen_target_amount_ex_vat', 0,
      'nominal_due_amount_ex_vat', recovery_row.nominal_due_amount_ex_vat,
      'recoverable_this_pay_run_ex_vat', 0,
      'draftable', false,
      'is_ready_for_draft', false,
      'selection_allowed', false,
      'is_excluded_from_allocation', true,
      'selected', false,
      'selection_state', 'NOT_SELECTABLE',
      'blocked_reason_codes', CASE
        WHEN jsonb_typeof(COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb)) <> 'array'
          THEN jsonb_build_array('NO_PAY_HEADROOM')
        WHEN COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
          THEN COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb)
        ELSE COALESCE(recovery_row.base_row_json->'blocked_reason_codes', '[]'::jsonb) || jsonb_build_array('NO_PAY_HEADROOM')
      END,
      'materialisation_recovery_headroom_revalidated', true,
      'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
      'retained_positive_headroom_ex_vat', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
    )
    || jsonb_build_object(
      'preview_contract', COALESCE(recovery_row.base_row_json->'preview_contract', '{}'::jsonb)
        || jsonb_build_object(
          'line_key', recovery_row.blocked_row_key,
          'amount_ex_vat', 0,
          'draftable', false,
          'is_ready_for_draft', false,
          'selection_allowed', false,
          'is_excluded_from_allocation', true,
          'target_section', 'blocked_for_pay',
          'presentation_section', 'BLOCKED_FOR_PAY'
        ),
      'case_resolution_summary', CASE
        WHEN jsonb_typeof(COALESCE(recovery_row.base_row_json->'case_resolution_summary', '{}'::jsonb)) = 'object'
          THEN COALESCE(recovery_row.base_row_json->'case_resolution_summary', '{}'::jsonb)
            || jsonb_build_object('due_amount_ex_vat', 0)
        ELSE jsonb_build_object('due_amount_ex_vat', 0)
      END
    ),
    recovery_row.timesheet_id,
    recovery_row.key_type,
    recovery_row.key_value,
    false,
    'NOT_SELECTABLE',
    'READY',
    COALESCE(v_session_row.version, 1),
    v_now,
    v_now
  FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
  ON CONFLICT (session_id, section, candidate_id, row_key)
  DO UPDATE
  SET row_ordinal = EXCLUDED.row_ordinal,
      row_json = EXCLUDED.row_json,
      timesheet_id = EXCLUDED.timesheet_id,
      key_type = EXCLUDED.key_type,
      key_value = EXCLUDED.key_value,
      selected = false,
      selection_state = 'NOT_SELECTABLE',
      status = 'READY',
      session_version = EXCLUDED.session_version,
      updated_at_utc = v_now;

  GET DIAGNOSTICS v_demoted_count = ROW_COUNT;

  UPDATE public.banking_pay_workbench_preview_rows AS ready_recovery_row
  SET status = 'SUPERSEDED',
      selected = false,
      selection_state = 'SUPERSEDED',
      row_json = COALESCE(ready_recovery_row.row_json, '{}'::jsonb)
        || jsonb_build_object(
          'selected', false,
          'selection_state', 'SUPERSEDED',
          'materialisation_recovery_headroom_revalidated', true,
          'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
          'retained_positive_headroom_ex_vat', 0,
          'superseded_reason', 'NO_PAY_HEADROOM_AFTER_FINAL_MATERIALISATION',
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE ready_recovery_row.session_id = p_session_id
    AND ready_recovery_row.session_version = COALESCE(v_session_row.version, 1)
    AND ready_recovery_row.candidate_id = p_candidate_id
    AND LOWER(BTRIM(COALESCE(ready_recovery_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(ready_recovery_row.status, ''))) = 'READY'
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
      WHERE recovery_row.ready_preview_row_id = ready_recovery_row.id
    );

  GET DIAGNOSTICS v_superseded_count = ROW_COUNT;

  UPDATE public.banking_pay_workbench_candidate_line_work AS line_work
  SET result_row_json = COALESCE(line_work.result_row_json, '{}'::jsonb)
        || jsonb_build_object(
          'section', 'blocked_for_pay',
          'target_section', 'blocked_for_pay',
          'readiness_state', 'BLOCKED_FOR_PAY',
          'presentation_section', 'BLOCKED_FOR_PAY',
          'presentation_reason', 'NO_PAY_HEADROOM',
          'amount_ex_vat', 0,
          'preview_amount_ex_vat', 0,
          'amount_display', 0,
          'target_pay_ex_vat', 0,
          'recoverable_this_pay_run_ex_vat', 0,
          'draftable', false,
          'is_ready_for_draft', false,
          'selection_allowed', false,
          'is_excluded_from_allocation', true,
          'selected', false,
          'selection_state', 'NOT_SELECTABLE',
          'blocked_reason_codes', CASE
            WHEN jsonb_typeof(COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb)) <> 'array'
              THEN jsonb_build_array('NO_PAY_HEADROOM')
            WHEN COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb) @> jsonb_build_array('NO_PAY_HEADROOM')
              THEN COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb)
            ELSE COALESCE(line_work.result_row_json->'blocked_reason_codes', '[]'::jsonb) || jsonb_build_array('NO_PAY_HEADROOM')
          END,
          'materialisation_recovery_headroom_revalidated', true,
          'materialisation_recovery_headroom_revalidated_at_utc', v_now::text,
          'retained_positive_headroom_ex_vat', 0,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE line_work.session_id = p_session_id
    AND line_work.candidate_id = p_candidate_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp._tmp_pay_wb_zero_headroom_recovery AS recovery_row
      WHERE recovery_row.ready_row_key = line_work.line_key
    );

  GET DIAGNOSTICS v_line_work_revalidated_count = ROW_COUNT;

  v_progress_json := public.pay_workbench_session_recompute_progress_counters(
    p_session_id,
    true,
    'POST_MATERIALISATION_RECOVERY_HEADROOM_REVALIDATION',
    false
  );

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_row.id::text) ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_selected_preview_row_ids,
       v_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = COALESCE(v_session_row.version, 1)
    AND LOWER(BTRIM(COALESCE(selected_row.section, ''))) = 'canonical_preview_lines'
    AND UPPER(BTRIM(COALESCE(selected_row.status, ''))) = 'READY'
    AND COALESCE(selected_row.selected, false) = true
    AND UPPER(BTRIM(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

  v_selection_intent_mode := UPPER(BTRIM(COALESCE(
    v_session_row.progress_json#>>'{selection_intent_v1,canonical_preview_lines,mode}',
    ''
  )));

  UPDATE public.banking_pay_workbench_sessions AS session_row
  SET selected_row_count = COALESCE(v_selected_row_count, 0),
      server_selected_preview_row_ids = CASE
        WHEN v_selection_intent_mode = 'EXPLICIT_INCLUDE'
          OR COALESCE(session_row.server_selected_preview_row_ids_provided, false) IS TRUE
          THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
        ELSE session_row.server_selected_preview_row_ids
      END,
      progress_json = COALESCE(session_row.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'last_recovery_headroom_revalidation_at_utc', v_now::text,
          'last_recovery_headroom_revalidation_action', 'DEMOTED_ZERO_RETAINED_HEADROOM',
          'last_recovery_headroom_revalidation_candidate_id', p_candidate_id::text,
          'last_recovery_headroom_revalidation_demoted_count', COALESCE(v_demoted_count, 0),
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY'
        ),
      updated_at_utc = v_now
  WHERE session_row.id = p_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'action', 'DEMOTED_ZERO_RETAINED_HEADROOM',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'retained_positive_headroom_ex_vat', v_retained_positive_headroom,
    'recovery_group_count', COALESCE(v_recovery_group_count, 0),
    'demoted_recovery_count', COALESCE(v_demoted_count, 0),
    'superseded_ready_recovery_count', COALESCE(v_superseded_count, 0),
    'line_work_revalidated_count', COALESCE(v_line_work_revalidated_count, 0),
    'selected_row_count', COALESCE(v_selected_row_count, 0),
    'progress_recomputed', COALESCE(v_progress_json, '{}'::jsonb),
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_WORKBENCH_ONLY',
    'post_draft_artifacts_touched', false,
    'payment_execution_started', false
  );
END;
$function$;

-- pay_workbench_scope_admission_candidates_v1(uuid,jsonb,bigint)
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_admission_candidates_v1(p_session_id uuid, p_candidate_ids jsonb, p_target_generation bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_input_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_shortlist jsonb := '[]'::jsonb;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_context jsonb := '{}'::jsonb;
  v_filter_candidate_id uuid;
  v_filter_client_id uuid;
  v_current_generation bigint := 0;
BEGIN
  IF p_session_id IS NULL OR jsonb_typeof(COALESCE(p_candidate_ids, 'null'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_INPUT_INVALID'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(p_candidate_ids) AS candidate_value(value)
    WHERE NULLIF(BTRIM(candidate_value.value), '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_CANDIDATE_ID_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT candidate_value.value::uuid ORDER BY candidate_value.value::uuid), ARRAY[]::uuid[])
  INTO v_input_candidate_ids
  FROM jsonb_array_elements_text(p_candidate_ids) AS candidate_value(value);

  IF COALESCE(array_length(v_input_candidate_ids, 1), 0) > 50 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_INPUT_TOO_LARGE'
      USING ERRCODE = '22023';
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND
     OR UPPER(BTRIM(COALESCE(v_session.status, ''))) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL
     OR v_session.replacement_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_SESSION_NOT_CURRENT'
      USING ERRCODE = 'P0001';
  END IF;

  v_current_generation := public.pay_workbench_scope_current_generation_v1();
  IF p_target_generation IS NULL
     OR p_target_generation < v_session.scope_change_generation_applied
     OR p_target_generation > v_current_generation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_GENERATION_INVALID'
      USING ERRCODE = '22023';
  END IF;

  IF COALESCE(array_length(v_input_candidate_ids, 1), 0) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'target_generation', p_target_generation,
      'candidate_ids', '[]'::jsonb,
      'eligible_count', 0,
      'shortlist_empty', true,
      'normal_eligibility_authority_used', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(candidate_id::text) ORDER BY candidate_id), '[]'::jsonb)
  INTO v_shortlist
  FROM unnest(v_input_candidate_ids) AS candidate_id;

  IF BTRIM(COALESCE(v_session.filters_json->>'candidate_id', v_session.filters_json->>'candidateId', ''))
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(
      v_session.filters_json->>'candidate_id',
      v_session.filters_json->>'candidateId'
    )::uuid;

    IF NOT (v_filter_candidate_id = ANY(v_input_candidate_ids)) THEN
      RETURN jsonb_build_object(
        'ok', true,
        'session_id', p_session_id::text,
        'target_generation', p_target_generation,
        'candidate_ids', '[]'::jsonb,
        'eligible_count', 0,
        'shortlist_empty', false,
        'explicit_candidate_filter_intersection_empty', true,
        'normal_eligibility_authority_used', false,
        'explicit_candidate_filter_preserved', true,
        'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
      );
    END IF;
  END IF;

  IF BTRIM(COALESCE(v_session.filters_json->>'client_id', v_session.filters_json->>'clientId', ''))
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(
      v_session.filters_json->>'client_id',
      v_session.filters_json->>'clientId'
    )::uuid;
  END IF;

  PERFORM set_config('cloudtms.banking_pay_scope_admission', 'true', true);
  v_context := public.pay_preview_build_context(
    p_pay_date => v_session.pay_date,
    p_week_ending_cutoff => v_session.week_ending_cutoff,
    p_actor_user_id => v_session.actor_user_id,
    p_candidate_id => v_filter_candidate_id,
    p_client_id => v_filter_client_id,
    p_preview_decisions_json => COALESCE(v_session.filters_json, '{}'::jsonb)
      || jsonb_build_object(
        'preview_context_mode', 'PAGE',
        'scope_limit', COALESCE(array_length(v_input_candidate_ids, 1), 0),
        'scope_admission_candidate_ids', v_shortlist
      )
  );

  SELECT COALESCE(jsonb_agg(to_jsonb(candidate_value.value) ORDER BY candidate_value.value), '[]'::jsonb)
  INTO v_candidate_ids
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_context->'candidate_ids') = 'array' THEN v_context->'candidate_ids'
      ELSE '[]'::jsonb
    END
  ) AS candidate_value(value);

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(v_candidate_ids) AS output_candidate(value)
    WHERE output_candidate.value::uuid <> ALL(v_input_candidate_ids)
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ADMISSION_OUTPUT_OUTSIDE_SHORTLIST'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'target_generation', p_target_generation,
    'candidate_ids', v_candidate_ids,
    'eligible_count', jsonb_array_length(v_candidate_ids),
    'shortlist_empty', false,
    'normal_eligibility_authority_used', v_filter_candidate_id IS NULL,
    'explicit_candidate_filter_preserved', v_filter_candidate_id IS NOT NULL,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- pay_workbench_scope_blocker_state_v1(uuid,bigint,uuid)
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_blocker_state_v1(p_session_id uuid, p_target_generation bigint, p_operation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_filter_candidate_id uuid;
  v_filter_client_id uuid;
  v_upstream_active integer := 0;
  v_upstream_failed integer := 0;
  v_session_active integer := 0;
  v_session_failed integer := 0;
  v_broad_pending integer := 0;
  v_unknown_relevance integer := 0;
  v_active_sample jsonb := '[]'::jsonb;
  v_failure_sample jsonb := '[]'::jsonb;
  v_session_active_sample jsonb := '[]'::jsonb;
  v_session_failure_sample jsonb := '[]'::jsonb;
BEGIN
  IF p_session_id IS NULL OR p_target_generation IS NULL OR p_target_generation < 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_BLOCKER_INPUT_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_BLOCKER_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
      AND operation_row.workbench_session_id = p_session_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_BLOCKER_OPERATION_MISMATCH'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF BTRIM(COALESCE(v_session.filters_json->>'candidate_id', v_session.filters_json->>'candidateId', ''))
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(
      v_session.filters_json->>'candidate_id',
      v_session.filters_json->>'candidateId'
    )::uuid;
  END IF;

  IF BTRIM(COALESCE(v_session.filters_json->>'client_id', v_session.filters_json->>'clientId', ''))
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(
      v_session.filters_json->>'client_id',
      v_session.filters_json->>'clientId'
    )::uuid;
  END IF;

  WITH generated_raw AS MATERIALIZED (
    SELECT
      job_row.*,
      COALESCE(NULLIF(BTRIM(job_row.dedupe_key), ''), 'JOB:' || job_row.id::text) AS work_identity,
      UPPER(BTRIM(COALESCE(job_row.payload_json->>'scope_kind', ''))) AS scope_kind,
      COALESCE(
        NULLIF(BTRIM(job_row.payload_json->>'scope_id'), ''),
        NULLIF(BTRIM(job_row.payload_json->>'client_id'), ''),
        NULLIF(BTRIM(job_row.payload_json->>'contract_id'), '')
      ) AS direct_scope_id,
      evidence.candidate_ids,
      CASE
        WHEN UPPER(BTRIM(COALESCE(job_row.payload_json->>'scope_kind', ''))) = 'CLIENT'
         AND COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'client_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'client_id')::uuid
        ELSE NULL::uuid
      END AS direct_client_id,
      CASE
        WHEN UPPER(BTRIM(COALESCE(job_row.payload_json->>'scope_kind', ''))) = 'CONTRACT'
         AND COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'contract_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN COALESCE(job_row.payload_json->>'scope_id', job_row.payload_json->>'contract_id')::uuid
        ELSE NULL::uuid
      END AS direct_contract_id
    FROM public.banking_pay_workbench_jobs AS job_row
    CROSS JOIN LATERAL (
      SELECT COALESCE(array_agg(DISTINCT candidate_source.candidate_id ORDER BY candidate_source.candidate_id), ARRAY[]::uuid[]) AS candidate_ids
      FROM (
        SELECT job_row.candidate_id
        WHERE job_row.candidate_id IS NOT NULL
        UNION ALL
        SELECT (job_row.payload_json->>'candidate_id')::uuid
        WHERE COALESCE(job_row.payload_json->>'candidate_id', '')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        UNION ALL
        SELECT (job_row.payload_json->>'processed_candidate_id')::uuid
        WHERE COALESCE(job_row.payload_json->>'processed_candidate_id', '')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        UNION ALL
        SELECT candidate_value.value::uuid
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(job_row.payload_json->'candidate_ids') = 'array'
              THEN job_row.payload_json->'candidate_ids'
            ELSE '[]'::jsonb
          END
        ) AS candidate_value(value)
        WHERE candidate_value.value
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS candidate_source
    ) AS evidence
    WHERE job_row.job_type IN (
      'WORKBENCH_CANDIDATE_DIRTY_APPLY',
      'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
      'CONTRACT_CLIENT_DIRTY_FANOUT'
    )
      AND job_row.scope_change_generation IS NOT NULL
      AND job_row.scope_change_generation <= p_target_generation
      AND job_row.status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD', 'SUCCEEDED')
  ), generated_classified AS MATERIALIZED (
    SELECT
      generated_raw.*,
      CASE
        WHEN p_operation_id IS NOT NULL THEN
          CASE
            WHEN generated_raw.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
              CASE
                WHEN COALESCE(array_length(generated_raw.candidate_ids, 1), 0) = 0 THEN 'UNKNOWN'
                WHEN EXISTS (
                  SELECT 1
                  FROM public.banking_pay_operation_candidate_scope AS operation_scope
                  WHERE operation_scope.operation_id = p_operation_id
                    AND operation_scope.candidate_id = ANY(generated_raw.candidate_ids)
                ) THEN 'RELEVANT'
                ELSE 'IRRELEVANT'
              END
            WHEN generated_raw.scope_kind = 'CANDIDATE'
             AND COALESCE(array_length(generated_raw.candidate_ids, 1), 0) > 0 THEN
              CASE
                WHEN EXISTS (
                  SELECT 1
                  FROM public.banking_pay_operation_candidate_scope AS operation_scope
                  WHERE operation_scope.operation_id = p_operation_id
                    AND operation_scope.candidate_id = ANY(generated_raw.candidate_ids)
                ) THEN 'RELEVANT'
                ELSE 'IRRELEVANT'
              END
            ELSE 'UNKNOWN'
          END
        WHEN v_filter_candidate_id IS NOT NULL THEN
          CASE
            WHEN generated_raw.job_type <> 'CONTRACT_CLIENT_DIRTY_FANOUT' THEN
              CASE
                WHEN COALESCE(array_length(generated_raw.candidate_ids, 1), 0) = 0 THEN 'UNKNOWN'
                WHEN v_filter_candidate_id = ANY(generated_raw.candidate_ids) THEN 'RELEVANT'
                ELSE 'IRRELEVANT'
              END
            WHEN generated_raw.scope_kind = 'CANDIDATE'
             AND COALESCE(array_length(generated_raw.candidate_ids, 1), 0) > 0 THEN
              CASE WHEN v_filter_candidate_id = ANY(generated_raw.candidate_ids) THEN 'RELEVANT' ELSE 'IRRELEVANT' END
            ELSE 'UNKNOWN'
          END
        WHEN v_filter_client_id IS NOT NULL THEN
          CASE
            WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
             AND generated_raw.scope_kind = 'CLIENT'
             AND generated_raw.direct_client_id IS NOT NULL
              THEN CASE WHEN generated_raw.direct_client_id = v_filter_client_id THEN 'RELEVANT' ELSE 'IRRELEVANT' END
            WHEN generated_raw.job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
             AND generated_raw.scope_kind = 'CONTRACT'
             AND generated_raw.direct_contract_id IS NOT NULL
              THEN CASE
                WHEN EXISTS (
                  SELECT 1
                  FROM public.contracts AS contract_row
                  WHERE contract_row.id = generated_raw.direct_contract_id
                    AND contract_row.client_id = v_filter_client_id
                ) THEN 'RELEVANT'
                ELSE 'IRRELEVANT'
              END
            ELSE 'UNKNOWN'
          END
        ELSE 'RELEVANT'
      END AS relevance_decision
    FROM generated_raw
  ), generated_ranked AS MATERIALIZED (
    SELECT
      generated_classified.*,
      ROW_NUMBER() OVER (
        PARTITION BY generated_classified.work_identity
        ORDER BY generated_classified.scope_change_generation DESC,
                 generated_classified.created_at_utc DESC,
                 generated_classified.id DESC
      ) AS authority_ordinal
    FROM generated_classified
    WHERE generated_classified.relevance_decision <> 'IRRELEVANT'
  ), generated_effective AS MATERIALIZED (
    SELECT
      generated_ranked.*,
      CASE
        -- A terminal row that the normal failure processor has proved obsolete
        -- is audit history, not current blocking authority.
        WHEN generated_ranked.status IN ('FAILED', 'DEAD')
         AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'non_blocking_terminal_failure', 'false'))) = 'true'
          THEN 'SUCCEEDED'
        -- A direct dirty-apply failure is also recovered once every candidate
        -- asserted by that row has subsequently completed and published a
        -- generation-fenced build for this exact session version.  The
        -- original FAILED/DEAD row is immutable history and can have a
        -- different dedupe key from the replacement source build, so ranking
        -- by work_identity alone cannot establish recovery.  Require the
        -- registry and completed build to agree on generation and source
        -- sequence, and require the registry to have no newer dirty work,
        -- active build or failure authority.  Partial or stale recovery keeps
        -- the original terminal row blocking.
        WHEN generated_ranked.status IN ('FAILED', 'DEAD')
         AND generated_ranked.job_type IN (
           'WORKBENCH_CANDIDATE_DIRTY_APPLY',
           'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
         )
         AND COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) > 0
         AND NOT EXISTS (
           SELECT 1
           FROM unnest(generated_ranked.candidate_ids) AS recovered_candidate(candidate_id)
           WHERE NOT EXISTS (
             SELECT 1
             FROM private.banking_pay_workbench_candidate_scope_registry AS recovered_registry
             JOIN private.banking_pay_workbench_economic_builds AS recovered_build
               ON recovered_build.candidate_id = recovered_registry.candidate_id
              AND recovered_build.session_id = p_session_id
              AND recovered_build.session_version = v_session.version
              AND recovered_build.captured_candidate_generation = recovered_registry.evaluated_generation
              AND recovered_build.source_change_seq = recovered_registry.current_source_change_seq
              AND recovered_build.status = 'COMPLETE'
              AND recovered_build.private_stage = 'COMPLETE'
              AND recovered_build.completed_at_utc IS NOT NULL
              AND recovered_build.completed_at_utc >= generated_ranked.created_at_utc
             WHERE recovered_registry.candidate_id = recovered_candidate.candidate_id
               AND recovered_registry.initialisation_status = 'READY'
               AND recovered_registry.current_build_id IS NULL
               AND recovered_registry.dirty_generation = recovered_registry.evaluated_generation
               AND recovered_registry.evaluated_generation >= generated_ranked.scope_change_generation
               AND COALESCE(recovered_registry.failure_json, '{}'::jsonb) = '{}'::jsonb
           )
         ) THEN 'SUCCEEDED'
        -- Backward compatibility for cancellation jobs written before
        -- supersessions became successful terminal work. Do not trust the flag
        -- alone: require the exact legacy code and the replacement full-candidate
        -- job for this session/batch. The replacement's own active/error state is
        -- evaluated independently with the session pipeline below.
        WHEN generated_ranked.status IN ('FAILED', 'DEAD')
         AND generated_ranked.job_type = 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY'
         AND LOWER(BTRIM(COALESCE(generated_ranked.payload_json->>'superseded_by_cancel_full_candidate_refresh', 'false'))) = 'true'
         AND UPPER(BTRIM(COALESCE(generated_ranked.last_error_json->>'code', '')))
               = 'WORKBENCH_FINANCE_DIRTY_SUPERSEDED_BY_CANCEL_FULL_CANDIDATE_REFRESH'
         AND generated_ranked.payload_json->>'superseding_session_id' = p_session_id::text
         AND COALESCE(generated_ranked.payload_json->>'superseding_pay_batch_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         AND EXISTS (
           SELECT 1
           FROM public.banking_pay_workbench_jobs AS replacement_job
           WHERE replacement_job.session_id = p_session_id
             AND replacement_job.job_type = 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
             AND replacement_job.created_at_utc >= generated_ranked.created_at_utc
             AND COALESCE(
                   replacement_job.payload_json->>'pay_batch_id',
                   replacement_job.payload_json#>>'{source_build,pay_batch_id}',
                   ''
                 ) = generated_ranked.payload_json->>'superseding_pay_batch_id'
             AND UPPER(BTRIM(COALESCE(
                   replacement_job.payload_json->>'refresh_scope_kind',
                   replacement_job.payload_json#>>'{source_build,refresh_scope_kind}',
                   ''
                 ))) = 'CANDIDATE_FULL_LIVE'
             AND LOWER(BTRIM(COALESCE(
                   replacement_job.payload_json->>'full_candidate_recovery_reallocation_required',
                   'false'
                 ))) = 'true'
             AND (
               COALESCE(array_length(generated_ranked.candidate_ids, 1), 0) = 0
               OR replacement_job.candidate_id = ANY(generated_ranked.candidate_ids)
             )
         ) THEN 'SUCCEEDED'
        ELSE generated_ranked.status
      END AS effective_status
    FROM generated_ranked
    WHERE authority_ordinal = 1
  )
  SELECT
    (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('QUEUED', 'RUNNING')),
    (SELECT COUNT(*)::integer FROM generated_effective WHERE effective_status IN ('FAILED', 'DEAD')),
    (SELECT COUNT(*)::integer FROM generated_effective
      WHERE job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT'
        AND effective_status IN ('QUEUED', 'RUNNING', 'FAILED', 'DEAD')),
    (SELECT COUNT(*)::integer FROM generated_effective WHERE relevance_decision = 'UNKNOWN'),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'job_id', limited_job.id::text,
        'job_type', limited_job.job_type,
        'status', limited_job.effective_status,
        'scope_change_generation', limited_job.scope_change_generation,
        'dedupe_key', limited_job.work_identity,
        'relevance', limited_job.relevance_decision
      ) ORDER BY limited_job.scope_change_generation, limited_job.id)
      FROM (
        SELECT * FROM generated_effective
        WHERE effective_status IN ('QUEUED', 'RUNNING')
        ORDER BY scope_change_generation, id
        LIMIT 25
      ) AS limited_job
    ), '[]'::jsonb),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'job_id', limited_job.id::text,
        'job_type', limited_job.job_type,
        'status', limited_job.effective_status,
        'scope_change_generation', limited_job.scope_change_generation,
        'dedupe_key', limited_job.work_identity,
        'relevance', limited_job.relevance_decision
      ) ORDER BY limited_job.scope_change_generation, limited_job.id)
      FROM (
        SELECT * FROM generated_effective
        WHERE effective_status IN ('FAILED', 'DEAD')
        ORDER BY scope_change_generation, id
        LIMIT 25
      ) AS limited_job
    ), '[]'::jsonb)
  INTO
    v_upstream_active,
    v_upstream_failed,
    v_broad_pending,
    v_unknown_relevance,
    v_active_sample,
    v_failure_sample;

  -- Session job rows are immutable execution history. Their raw FAILED/DEAD
  -- status is not durable readiness authority because a later current-state
  -- rebuild may have recovered the candidate under a different dedupe key.
  -- Active work remains a blocker. Terminal failure authority is held by the
  -- session's recomputed scope/line failure counters, which the worker updates
  -- from current candidate state and clears after a successful recovery.
  WITH session_active AS MATERIALIZED (
    SELECT
      session_job.*,
      COALESCE(NULLIF(BTRIM(session_job.dedupe_key), ''), 'JOB:' || session_job.id::text) AS work_identity
    FROM public.banking_pay_workbench_jobs AS session_job
    WHERE session_job.session_id = p_session_id
      AND session_job.job_type IN (
        'WORKBENCH_SESSION_SCOPE_SEED',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'WORKBENCH_CANDIDATE_DELTA_REFRESH',
        'WORKBENCH_SESSION_CLONE_REBASE',
        'WORKBENCH_CANDIDATE_LINE_WORK_SEED',
        'WORKBENCH_CANDIDATE_LINE_WORK_PROCESS',
        'WORKBENCH_PREVIEW_ROWS_MATERIALISE'
      )
      AND session_job.status IN ('QUEUED', 'RUNNING')
  )
  SELECT
    (SELECT COUNT(*)::integer FROM session_active),
    0::integer,
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'job_id', limited_job.id::text,
        'job_type', limited_job.job_type,
        'status', limited_job.status,
        'dedupe_key', limited_job.work_identity
      ) ORDER BY limited_job.created_at_utc, limited_job.id)
      FROM (
        SELECT * FROM session_active
        ORDER BY created_at_utc, id
        LIMIT 25
      ) AS limited_job
    ), '[]'::jsonb),
    '[]'::jsonb
  INTO
    v_session_active,
    v_session_failed,
    v_session_active_sample,
    v_session_failure_sample;

  SELECT COALESCE(jsonb_agg(sample_row.value ORDER BY sample_row.ordinality), '[]'::jsonb)
  INTO v_active_sample
  FROM jsonb_array_elements(COALESCE(v_active_sample, '[]'::jsonb) || COALESCE(v_session_active_sample, '[]'::jsonb))
       WITH ORDINALITY AS sample_row(value, ordinality)
  WHERE sample_row.ordinality <= 25;

  SELECT COALESCE(jsonb_agg(sample_row.value ORDER BY sample_row.ordinality), '[]'::jsonb)
  INTO v_failure_sample
  FROM jsonb_array_elements(COALESCE(v_failure_sample, '[]'::jsonb) || COALESCE(v_session_failure_sample, '[]'::jsonb))
       WITH ORDINALITY AS sample_row(value, ordinality)
  WHERE sample_row.ordinality <= 25;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'target_generation', p_target_generation,
    'upstream_active_count', COALESCE(v_upstream_active, 0),
    'upstream_unresolved_failure_count', COALESCE(v_upstream_failed, 0),
    'session_active_count', COALESCE(v_session_active, 0),
    'session_unresolved_failure_count', COALESCE(v_session_failed, 0),
    'session_scope_failed_count', COALESCE(v_session.scope_failed_count, 0),
    'session_line_failed_count', COALESCE(v_session.line_units_failed, 0),
    'broad_root_pending_count', COALESCE(v_broad_pending, 0),
    'unknown_relevance_count', COALESCE(v_unknown_relevance, 0),
    'active_sample', COALESCE(v_active_sample, '[]'::jsonb),
    'failure_sample', COALESCE(v_failure_sample, '[]'::jsonb),
    'all_clear',
      COALESCE(v_upstream_active, 0) = 0
      AND COALESCE(v_upstream_failed, 0) = 0
      AND COALESCE(v_session_active, 0) = 0
      AND COALESCE(v_session_failed, 0) = 0
      AND COALESCE(v_session.scope_failed_count, 0) = 0
      AND COALESCE(v_session.line_units_failed, 0) = 0
  );
END;
$function$;

-- pay_workbench_scope_change_finalize_trg_v1()
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_change_finalize_trg_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_state text;
  v_candidate_count integer := 0;
  v_job_count integer := 0;
  v_generation bigint;
BEGIN
  SELECT scope_tx.state
  INTO v_state
  FROM public.banking_pay_scope_change_transactions AS scope_tx
  WHERE scope_tx.tx_token = NEW.tx_token
  FOR UPDATE;

  IF NOT FOUND OR v_state <> 'PENDING' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_jobs AS coordinator_job
    WHERE coordinator_job.scope_change_tx_token = NEW.tx_token
      AND UPPER(BTRIM(COALESCE(coordinator_job.job_type, ''))) = 'WORKBENCH_SCOPE_RECONCILE'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_COORDINATOR_SOURCE_TOKEN_FORBIDDEN'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT COUNT(*)::integer
  INTO v_candidate_count
  FROM public.app_change_counters AS candidate_counter
  WHERE candidate_counter.scope_change_tx_token = NEW.tx_token;

  SELECT COUNT(*)::integer
  INTO v_job_count
  FROM public.banking_pay_workbench_jobs AS staged_job
  WHERE staged_job.scope_change_tx_token = NEW.tx_token
    AND UPPER(BTRIM(COALESCE(staged_job.job_type, ''))) <> 'WORKBENCH_SCOPE_RECONCILE';

  IF v_candidate_count = 0 AND v_job_count = 0 THEN
    UPDATE public.banking_pay_scope_change_transactions AS scope_tx
    SET state = 'NOOP',
        finalized_at_utc = clock_timestamp()
    WHERE scope_tx.tx_token = NEW.tx_token;
    RETURN NEW;
  END IF;

  PERFORM set_config('cloudtms.scope_generation_finalising', 'true', true);

  -- Bounded-scope metadata is locked candidate-first, then timesheet, before
  -- queue/counter finalisation.  This is the canonical invalidation lock order.
  PERFORM 1
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  WHERE registry.last_scope_change_tx_token=NEW.tx_token
  ORDER BY registry.candidate_id
  FOR UPDATE;

  PERFORM 1
  FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
  WHERE scope_state.last_scope_change_tx_token=NEW.tx_token
  ORDER BY scope_state.candidate_id,scope_state.timesheet_id
  FOR UPDATE;

  -- These rows were staged earlier by this transaction. The deterministic
  -- lock pass documents and enforces the finaliser's lock order.
  PERFORM 1
  FROM public.app_change_counters AS staged_counter
  WHERE staged_counter.scope_change_tx_token = NEW.tx_token
  ORDER BY staged_counter.entity_key
  FOR UPDATE;

  PERFORM 1
  FROM public.banking_pay_workbench_jobs AS staged_job
  WHERE staged_job.scope_change_tx_token = NEW.tx_token
  ORDER BY staged_job.id
  FOR UPDATE;

  INSERT INTO public.app_change_counters AS generation_counter(
    entity_key, seq, updated_at
  ) VALUES (
    'pay_candidate_scope_generation', 1, clock_timestamp()
  )
  ON CONFLICT (entity_key) DO UPDATE
  SET seq = generation_counter.seq + 1,
      updated_at = clock_timestamp()
  RETURNING seq INTO v_generation;

  UPDATE public.app_change_counters AS candidate_counter
  SET scope_change_generation = GREATEST(
        COALESCE(candidate_counter.scope_change_generation, 0),
        v_generation
      ),
      scope_change_tx_token = NULL::uuid
  WHERE candidate_counter.scope_change_tx_token = NEW.tx_token;

  UPDATE private.banking_pay_workbench_candidate_scope_registry AS registry
  SET dirty_generation=GREATEST(registry.dirty_generation,v_generation),
      last_scope_change_tx_token=NULL,updated_at_utc=clock_timestamp()
  WHERE registry.last_scope_change_tx_token=NEW.tx_token;

  UPDATE private.banking_pay_workbench_timesheet_scope_state AS scope_state
  SET economic_state='DIRTY',dirty_generation=GREATEST(scope_state.dirty_generation,v_generation),
      last_scope_change_tx_token=NULL,closed_at_utc=NULL,updated_at_utc=clock_timestamp()
  WHERE scope_state.last_scope_change_tx_token=NEW.tx_token;

  UPDATE public.banking_pay_workbench_jobs AS staged_job
  SET scope_change_generation = GREATEST(
        COALESCE(staged_job.scope_change_generation, 0),
        v_generation
      ),
      scope_change_tx_token = NULL::uuid,
      payload_json = COALESCE(staged_job.payload_json, '{}'::jsonb)
        || jsonb_build_object('scope_change_generation', v_generation),
      updated_at_utc = clock_timestamp()
  WHERE staged_job.scope_change_tx_token = NEW.tx_token
    AND UPPER(BTRIM(COALESCE(staged_job.job_type, ''))) <> 'WORKBENCH_SCOPE_RECONCILE';

  IF EXISTS(SELECT 1 FROM private.banking_pay_workbench_candidate_scope_registry
      WHERE last_scope_change_tx_token=NEW.tx_token)
     OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_timesheet_scope_state
      WHERE last_scope_change_tx_token=NEW.tx_token)
     OR EXISTS(SELECT 1 FROM public.app_change_counters
      WHERE scope_change_tx_token=NEW.tx_token)
     OR EXISTS(SELECT 1 FROM public.banking_pay_workbench_jobs
      WHERE scope_change_tx_token=NEW.tx_token
        AND UPPER(BTRIM(COALESCE(job_type,'')))<>'WORKBENCH_SCOPE_RECONCILE') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_UNRESOLVED'
      USING ERRCODE='P0001';
  END IF;

  UPDATE public.banking_pay_scope_change_transactions AS scope_tx
  SET state = 'FINALIZED',
      allocated_generation = v_generation,
      finalized_at_utc = clock_timestamp()
  WHERE scope_tx.tx_token = NEW.tx_token;

  RETURN NEW;
END;
$function$;

-- pay_workbench_scope_change_tx_token_v1()
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_change_tx_token_v1()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_token uuid;
  v_state text;
BEGIN
  IF LOWER(BTRIM(COALESCE(current_setting('cloudtms.scope_generation_finalising', true), 'false')))
       IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RETURN NULL::uuid;
  END IF;

  BEGIN
    v_token := NULLIF(BTRIM(COALESCE(
      current_setting('cloudtms.banking_pay_scope_tx_token', true),
      ''
    )), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID'
      USING ERRCODE = 'P0001';
  END;

  IF v_token IS NULL THEN
    v_token := gen_random_uuid();
    PERFORM set_config('cloudtms.banking_pay_scope_tx_token', v_token::text, true);
    INSERT INTO public.banking_pay_scope_change_transactions(
      tx_token, state, created_at_utc
    ) VALUES (
      v_token, 'PENDING', clock_timestamp()
    );
    RETURN v_token;
  END IF;

  SELECT scope_tx.state
  INTO v_state
  FROM public.banking_pay_scope_change_transactions AS scope_tx
  WHERE scope_tx.tx_token = v_token;

  IF v_state IN ('FINALIZED', 'NOOP') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_GENERATION_FINALIZED_TOO_EARLY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SCOPE_GENERATION_FINALIZED_TOO_EARLY',
              'state', v_state
            )::text;
  END IF;

  INSERT INTO public.banking_pay_scope_change_transactions(
    tx_token, state, created_at_utc
  ) VALUES (
    v_token, 'PENDING', clock_timestamp()
  ) ON CONFLICT (tx_token) DO NOTHING;

  RETURN v_token;
END;
$function$;

-- pay_workbench_scope_counter_stage_trg_v1()
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_counter_stage_trg_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_inherited_generation bigint;
BEGIN
  IF NEW.entity_key !~* '^pay_candidate:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.seq IS NOT DISTINCT FROM OLD.seq THEN
    RETURN NEW;
  END IF;

  IF LOWER(BTRIM(COALESCE(current_setting('cloudtms.scope_generation_finalising', true), 'false')))
       IN ('true', 't', '1', 'yes', 'y', 'on') THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_inherited_generation := NULLIF(BTRIM(COALESCE(
      current_setting('cloudtms.banking_pay_inherited_scope_generation', true),
      ''
    )), '')::bigint;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_INHERITED_SCOPE_GENERATION_INVALID'
      USING ERRCODE = 'P0001';
  END;

  IF v_inherited_generation IS NOT NULL THEN
    IF TG_OP = 'UPDATE'
       AND v_inherited_generation <= COALESCE(OLD.scope_change_generation, 0) THEN
      -- A retried/equal or older broad-fanout child is already represented.
      -- Preserve the ordinary candidate source sequence as well as generation.
      NEW.seq := OLD.seq;
      NEW.updated_at := OLD.updated_at;
      NEW.scope_change_generation := OLD.scope_change_generation;
      NEW.scope_change_tx_token := NULL::uuid;
      RETURN NEW;
    END IF;

    NEW.scope_change_generation := GREATEST(
      COALESCE(NEW.scope_change_generation, 0),
      v_inherited_generation
    );
    NEW.scope_change_tx_token := NULL::uuid;
  ELSE
    NEW.scope_change_tx_token := public.pay_workbench_scope_change_tx_token_v1();
  END IF;

  RETURN NEW;
END;
$function$;

-- pay_workbench_scope_current_generation_v1()
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_current_generation_v1()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT COALESCE((
    SELECT change_counter.seq
    FROM public.app_change_counters AS change_counter
    WHERE change_counter.entity_key = 'pay_candidate_scope_generation'
  ), 0)::bigint;
$function$;

-- pay_workbench_scope_job_stage_trg_v1()
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_job_stage_trg_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_job_type text := UPPER(BTRIM(COALESCE(NEW.job_type, '')));
  v_inherited_generation bigint;
  v_is_source_enqueue boolean := false;
BEGIN
  IF v_job_type = 'WORKBENCH_SCOPE_RECONCILE' THEN
    IF NEW.scope_change_tx_token IS NOT NULL THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_COORDINATOR_SOURCE_TOKEN_FORBIDDEN'
        USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
  END IF;

  IF v_job_type NOT IN (
    'WORKBENCH_CANDIDATE_DIRTY_APPLY',
    'WORKBENCH_FINANCE_CASE_DIRTY_APPLY',
    'CONTRACT_CLIENT_DIRTY_FANOUT'
  ) THEN
    RETURN NEW;
  END IF;

  v_is_source_enqueue := TG_OP = 'INSERT'
    OR COALESCE(NEW.payload_json->>'latest_event_at_utc', '')
       IS DISTINCT FROM COALESCE(OLD.payload_json->>'latest_event_at_utc', '');

  IF NOT v_is_source_enqueue THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_inherited_generation := NULLIF(BTRIM(COALESCE(
      current_setting('cloudtms.banking_pay_inherited_scope_generation', true),
      ''
    )), '')::bigint;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_INHERITED_SCOPE_GENERATION_INVALID'
      USING ERRCODE = 'P0001';
  END;

  IF v_inherited_generation IS NOT NULL THEN
    NEW.scope_change_generation := GREATEST(
      COALESCE(NEW.scope_change_generation, 0),
      v_inherited_generation
    );
    NEW.scope_change_tx_token := NULL::uuid;
  ELSE
    NEW.scope_change_tx_token := public.pay_workbench_scope_change_tx_token_v1();
  END IF;

  RETURN NEW;
END;
$function$;

-- pay_workbench_scope_progress_v1(uuid)
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_progress_v1(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_current bigint := 0;
  v_shadow boolean := false;
  v_blocker jsonb := '{}'::jsonb;
  v_session_active integer := 0;
  v_session_failed integer := 0;
  v_upstream_active integer := 0;
  v_upstream_failed integer := 0;
  v_display_ready boolean := false;
  v_draft_safe boolean := false;
  v_reason text;
BEGIN
  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'WORKBENCH_SESSION_NOT_FOUND');
  END IF;

  SELECT COALESCE(settings_row.banking_pay_workbench_scope_reconcile_shadow_mode, false)
  INTO v_shadow
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  v_current := public.pay_workbench_scope_current_generation_v1();
  v_blocker := public.pay_workbench_scope_blocker_state_v1(p_session_id, v_current, NULL::uuid);
  v_session_active := COALESCE((v_blocker->>'session_active_count')::integer, 0);
  v_session_failed := COALESCE((v_blocker->>'session_unresolved_failure_count')::integer, 0)
    + COALESCE((v_blocker->>'session_scope_failed_count')::integer, 0)
    + COALESCE((v_blocker->>'session_line_failed_count')::integer, 0);
  v_upstream_active := COALESCE((v_blocker->>'upstream_active_count')::integer, 0);
  v_upstream_failed := COALESCE((v_blocker->>'upstream_unresolved_failure_count')::integer, 0);

  v_display_ready := UPPER(BTRIM(COALESCE(v_session.status, ''))) = 'OPEN'
    AND v_session.discarded_at_utc IS NULL
    AND v_session.replacement_session_id IS NULL
    AND COALESCE(v_session.scope_seed_complete, false)
    AND (
      COALESCE(v_session.preview_row_count, 0) > 0
      OR (
        v_session_active = 0
        AND COALESCE(v_session.scope_pending_count, 0) = 0
        AND COALESCE(v_session.scope_failed_count, 0) = 0
        AND COALESCE(v_session.line_units_pending, 0) = 0
        AND COALESCE(v_session.line_units_failed, 0) = 0
      )
    );

  v_draft_safe := v_display_ready
    AND NOT v_shadow
    AND COALESCE(v_session.scope_change_generation_applied, 0) = v_current
    AND v_session_active = 0
    AND v_session_failed = 0
    AND v_upstream_active = 0
    AND v_upstream_failed = 0;

  v_reason := CASE
    WHEN NOT v_display_ready THEN 'INITIAL_SCOPE_NOT_READY'
    WHEN v_shadow THEN 'SCOPE_RECONCILIATION_SHADOW_MODE'
    WHEN v_upstream_failed > 0 THEN 'UPSTREAM_SCOPE_FAILURE_UNRESOLVED'
    WHEN v_session_failed > 0 THEN 'CANDIDATE_REFRESH_FAILED'
    WHEN COALESCE(v_session.scope_change_generation_applied, 0) < v_current THEN 'SCOPE_RECONCILIATION_REQUIRED'
    WHEN v_upstream_active > 0 THEN 'UPSTREAM_SCOPE_EXPANSION_IN_PROGRESS'
    WHEN v_session_active > 0 THEN 'CANDIDATE_REFRESH_IN_PROGRESS'
    ELSE NULL::text
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'display_ready', v_display_ready,
    'draft_safe', v_draft_safe,
    'draft_block_reason_code', v_reason,
    'scope_change_generation_current', v_current,
    'scope_change_generation_target', COALESCE(v_session.scope_change_generation_target, 0),
    'scope_change_generation_applied', COALESCE(v_session.scope_change_generation_applied, 0),
    'scope_change_generation_shadow_checked', COALESCE(v_session.scope_change_generation_shadow_checked, 0),
    'scope_change_generation_lag', GREATEST(v_current - COALESCE(v_session.scope_change_generation_applied, 0), 0),
    'scope_reconcile_status', COALESCE(v_session.progress_json->>'scope_reconcile_status', 'IDLE'),
    'scope_reconcile_mode', CASE WHEN v_shadow THEN 'SHADOW' ELSE 'AUTHORITATIVE' END,
    'scope_reconcile_error', CASE
      WHEN v_upstream_failed > 0 THEN 'A background Banking Pay scope update failed and has not yet been recovered.'
      WHEN v_session_failed > 0 THEN 'A candidate payment refresh failed.'
      ELSE NULL::text
    END,
    'scope_blocker_active_sample', COALESCE(v_blocker->'active_sample', '[]'::jsonb),
    'scope_blocker_failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb)
  );
END;
$function$;

-- pay_workbench_scope_reconcile_drain_one_v1(integer,text)
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_reconcile_drain_one_v1(p_candidate_limit integer DEFAULT 25, p_worker_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_limit integer := LEAST(GREATEST(COALESCE(p_candidate_limit, 25), 1), 50);
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_enabled boolean := true;
  v_config_shadow boolean := false;
  v_mode text := 'AUTHORITATIVE';
  v_target bigint := 0;
  v_current_generation bigint := 0;
  v_base_generation bigint := 0;
  v_cursor_generation bigint := 0;
  v_cursor_entity_key text := '';
  v_page_count integer := 0;
  v_has_more boolean := false;
  v_last_generation bigint := 0;
  v_last_entity_key text := '';
  v_shortlist jsonb := '[]'::jsonb;
  v_admission jsonb := '{}'::jsonb;
  v_eligible jsonb := '[]'::jsonb;
  v_inserted jsonb := '[]'::jsonb;
  v_inserted_count integer := 0;
  v_enqueue jsonb := '{}'::jsonb;
  v_blocker jsonb := '{}'::jsonb;
  v_upstream_active integer := 0;
  v_upstream_failed integer := 0;
  v_more_sessions boolean := false;
  v_already_in_scope integer := 0;
  v_would_admit integer := 0;
  v_would_reject integer := 0;
  v_shadow_summary jsonb := '{}'::jsonb;
  v_shadow_previous jsonb := '{}'::jsonb;
  v_shadow_sample jsonb := '[]'::jsonb;
  v_error_message text;
  v_error_detail text;
  v_error_state text;
BEGIN
  SELECT queued_job.*
  INTO v_job
  FROM public.banking_pay_workbench_jobs AS queued_job
  WHERE UPPER(BTRIM(COALESCE(queued_job.job_type, ''))) = 'WORKBENCH_SCOPE_RECONCILE'
    AND queued_job.status = 'QUEUED'
    AND queued_job.run_at_utc <= v_now
  ORDER BY queued_job.priority, queued_job.run_at_utc, queued_job.created_at_utc, queued_job.id
  FOR UPDATE SKIP LOCKED
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'processed', false, 'reason', 'NO_DUE_COORDINATOR');
  END IF;

  UPDATE public.banking_pay_workbench_jobs AS claimed_job
  SET status = 'RUNNING',
      started_at_utc = v_now,
      updated_at_utc = v_now,
      payload_json = COALESCE(claimed_job.payload_json, '{}'::jsonb)
        || jsonb_build_object('worker_id', COALESCE(NULLIF(BTRIM(p_worker_id), ''), 'SCOPE_RECONCILE'))
  WHERE claimed_job.id = v_job.id
  RETURNING claimed_job.* INTO v_job;

  BEGIN
    SELECT
      COALESCE(settings_row.banking_pay_workbench_scope_reconcile_enabled, true),
      COALESCE(settings_row.banking_pay_workbench_scope_reconcile_shadow_mode, false)
    INTO v_enabled, v_config_shadow
    FROM public.settings_defaults AS settings_row
    ORDER BY settings_row.id
    LIMIT 1;

    IF NOT COALESCE(v_enabled, true) THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('completion_reason', 'SCOPE_RECONCILIATION_DISABLED'),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object('ok', true, 'processed', true, 'status', 'SUCCEEDED', 'reason', 'SCOPE_RECONCILIATION_DISABLED');
    END IF;

    v_mode := UPPER(BTRIM(COALESCE(
      v_job.payload_json->>'reconcile_mode',
      CASE WHEN v_config_shadow THEN 'SHADOW' ELSE 'AUTHORITATIVE' END
    )));
    IF v_mode NOT IN ('SHADOW', 'AUTHORITATIVE') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_RECONCILE_MODE_INVALID'
        USING ERRCODE = '22023';
    END IF;

    IF v_config_shadow AND v_mode = 'AUTHORITATIVE' THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          payload_json = (COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            - 'active_session_id' - 'cursor_generation' - 'cursor_entity_key')
            || jsonb_build_object('reconcile_mode', 'SHADOW', 'shadow_mode', true),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object('ok', true, 'processed', true, 'status', 'QUEUED', 'reason', 'CONVERTED_TO_SHADOW');
    END IF;

    v_current_generation := public.pay_workbench_scope_current_generation_v1();
    v_target := CASE
      WHEN COALESCE(v_job.payload_json->>'target_generation', '') ~ '^\d+$'
        THEN (v_job.payload_json->>'target_generation')::bigint
      ELSE 0
    END;
    v_target := GREATEST(v_target, v_current_generation);

    UPDATE public.banking_pay_workbench_jobs AS coordinator_job
    SET scope_change_generation = v_target,
        payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
          || jsonb_build_object('target_generation', v_target, 'reconcile_mode', v_mode),
        updated_at_utc = v_now
    WHERE coordinator_job.id = v_job.id;

    IF COALESCE(v_job.payload_json->>'active_session_id', '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT session_row.*
      INTO v_session
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE session_row.id = (v_job.payload_json->>'active_session_id')::uuid
        AND UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL
        AND session_row.replacement_session_id IS NULL
        AND COALESCE(session_row.scope_seed_complete, false)
        AND (
          (v_mode = 'SHADOW' AND COALESCE(session_row.scope_change_generation_shadow_checked, 0) < v_target)
          OR
          (v_mode = 'AUTHORITATIVE' AND COALESCE(session_row.scope_change_generation_applied, 0) < v_target)
        )
      FOR UPDATE;
    END IF;

    IF v_session.id IS NULL THEN
      SELECT session_row.*
      INTO v_session
      FROM public.banking_pay_workbench_sessions AS session_row
      WHERE UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
        AND session_row.discarded_at_utc IS NULL
        AND session_row.replacement_session_id IS NULL
        AND COALESCE(session_row.scope_seed_complete, false)
        AND (
          (v_mode = 'SHADOW' AND COALESCE(session_row.scope_change_generation_shadow_checked, 0) < v_target)
          OR
          (v_mode = 'AUTHORITATIVE' AND COALESCE(session_row.scope_change_generation_applied, 0) < v_target)
        )
      ORDER BY session_row.session_signature, session_row.id
      FOR UPDATE SKIP LOCKED
      LIMIT 1;
    END IF;
    IF v_session.id IS NULL THEN
      SELECT generation_counter.seq
      INTO v_current_generation
      FROM public.app_change_counters AS generation_counter
      WHERE generation_counter.entity_key = 'pay_candidate_scope_generation'
      FOR UPDATE;

      SELECT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_sessions AS lagging_session
        WHERE UPPER(BTRIM(COALESCE(lagging_session.status, ''))) = 'OPEN'
          AND lagging_session.discarded_at_utc IS NULL
          AND lagging_session.replacement_session_id IS NULL
          AND COALESCE(lagging_session.scope_seed_complete, false)
          AND (
            (v_mode = 'SHADOW' AND COALESCE(lagging_session.scope_change_generation_shadow_checked, 0) < v_current_generation)
            OR
            (v_mode = 'AUTHORITATIVE' AND COALESCE(lagging_session.scope_change_generation_applied, 0) < v_current_generation)
          )
      ) INTO v_more_sessions;

      IF v_current_generation > v_target OR v_more_sessions THEN
        UPDATE public.banking_pay_workbench_jobs AS coordinator_job
        SET status = 'QUEUED',
            run_at_utc = v_now,
            started_at_utc = NULL::timestamptz,
            failed_at_utc = NULL::timestamptz,
            last_error_json = NULL::jsonb,
            payload_json = (COALESCE(coordinator_job.payload_json, '{}'::jsonb)
              - 'active_session_id' - 'cursor_generation' - 'cursor_entity_key')
              || jsonb_build_object('target_generation', v_current_generation, 'reconcile_mode', v_mode),
            scope_change_generation = v_current_generation,
            updated_at_utc = v_now
        WHERE coordinator_job.id = v_job.id;
        RETURN jsonb_build_object('ok', true, 'processed', true, 'status', 'QUEUED', 'reason', 'NEW_GENERATION_OR_SESSION_LAG');
      END IF;

      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('completed_generation', v_target, 'completed_mode', v_mode),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', true, 'processed', true, 'status', 'SUCCEEDED',
        'target_generation', v_target, 'reconcile_mode', v_mode
      );
    END IF;

    v_base_generation := CASE
      WHEN v_mode = 'SHADOW' THEN COALESCE(v_session.scope_change_generation_shadow_checked, 0)
      ELSE COALESCE(v_session.scope_change_generation_applied, 0)
    END;
    v_cursor_generation := CASE
      WHEN COALESCE(v_job.payload_json->>'cursor_generation', '') ~ '^\d+$'
        THEN (v_job.payload_json->>'cursor_generation')::bigint
      ELSE v_base_generation
    END;
    v_cursor_entity_key := COALESCE(v_job.payload_json->>'cursor_entity_key', '');

    UPDATE public.banking_pay_workbench_sessions AS session_update
    SET scope_change_generation_target = CASE
          WHEN v_mode = 'AUTHORITATIVE' THEN v_target
          ELSE session_update.scope_change_generation_target
        END,
        progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'scope_reconcile_status', CASE WHEN v_mode = 'SHADOW' THEN 'SHADOW_RUNNING' ELSE 'RUNNING' END,
            'scope_reconcile_mode', v_mode,
            'scope_change_generation_target', v_target,
            'scope_change_generation_applied', COALESCE(session_update.scope_change_generation_applied, 0),
            'scope_change_generation_shadow_checked', COALESCE(session_update.scope_change_generation_shadow_checked, 0)
          ),
        updated_at_utc = v_now
    WHERE session_update.id = v_session.id;

    v_blocker := public.pay_workbench_scope_blocker_state_v1(v_session.id, v_target, NULL::uuid);
    v_upstream_active := COALESCE((v_blocker->>'upstream_active_count')::integer, 0);
    v_upstream_failed := COALESCE((v_blocker->>'upstream_unresolved_failure_count')::integer, 0);

    IF v_upstream_failed > 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now + interval '30 seconds',
          started_at_utc = NULL::timestamptz,
          last_error_json = jsonb_build_object(
            'code', 'PAY_WORKBENCH_SCOPE_RECONCILIATION_UPSTREAM_FAILED',
            'failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb),
            'target_generation', v_target
          ),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', false, 'processed', true, 'status', 'QUEUED',
        'reason', 'UPSTREAM_SCOPE_FAILURE_UNRESOLVED',
        'target_generation', v_target,
        'failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb)
      );
    END IF;

    -- A previously observed blocker may have recovered under the promoted
    -- generation target. Clear stale coordinator error evidence before waiting
    -- for active work or processing the next bounded page.
    UPDATE public.banking_pay_workbench_jobs AS recovered_coordinator
    SET failed_at_utc = NULL::timestamptz,
        last_error_json = NULL::jsonb,
        updated_at_utc = v_now
    WHERE recovered_coordinator.id = v_job.id;

    IF v_upstream_active > 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now + interval '1 second',
          started_at_utc = NULL::timestamptz,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'target_generation', v_target,
              'active_session_id', v_session.id::text,
              'upstream_wait_count', v_upstream_active
            ),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', true, 'processed', true, 'status', 'QUEUED',
        'reason', 'WAITING_FOR_UPSTREAM', 'upstream_count', v_upstream_active
      );
    END IF;

    DROP TABLE IF EXISTS pg_temp._bpay_scope_reconcile_page;
    CREATE TEMP TABLE _bpay_scope_reconcile_page ON COMMIT DROP AS
    SELECT candidate_change.entity_key,
           candidate_change.scope_change_generation,
           SUBSTRING(candidate_change.entity_key FROM 15)::uuid AS candidate_id,
           ROW_NUMBER() OVER (
             ORDER BY candidate_change.scope_change_generation, candidate_change.entity_key
           ) AS page_ordinal
    FROM public.app_change_counters AS candidate_change
    WHERE candidate_change.entity_key LIKE 'pay_candidate:%'
      AND candidate_change.entity_key
            ~* '^pay_candidate:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND candidate_change.scope_change_generation > v_base_generation
      AND candidate_change.scope_change_generation <= v_target
      AND (
        candidate_change.scope_change_generation > v_cursor_generation
        OR (
          candidate_change.scope_change_generation = v_cursor_generation
          AND candidate_change.entity_key > v_cursor_entity_key
        )
      )
    ORDER BY candidate_change.scope_change_generation, candidate_change.entity_key
    LIMIT (v_limit + 1);

    SELECT COUNT(*)::integer,
           EXISTS (SELECT 1 FROM pg_temp._bpay_scope_reconcile_page WHERE page_ordinal > v_limit)
    INTO v_page_count, v_has_more
    FROM pg_temp._bpay_scope_reconcile_page
    WHERE page_ordinal <= v_limit;

    SELECT COUNT(*)::integer
    INTO v_already_in_scope
    FROM pg_temp._bpay_scope_reconcile_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS existing_scope
        WHERE existing_scope.session_id = v_session.id
          AND existing_scope.candidate_id = page_row.candidate_id
      );

    SELECT COALESCE(
             jsonb_agg(to_jsonb(page_row.candidate_id::text) ORDER BY page_row.page_ordinal),
             '[]'::jsonb
           )
    INTO v_shortlist
    FROM pg_temp._bpay_scope_reconcile_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_session_scope AS existing_scope
        WHERE existing_scope.session_id = v_session.id
          AND existing_scope.candidate_id = page_row.candidate_id
      );

    IF jsonb_array_length(v_shortlist) > 0 THEN
      v_admission := public.pay_workbench_scope_admission_candidates_v1(
        v_session.id,
        v_shortlist,
        v_target
      );
      v_eligible := CASE
        WHEN jsonb_typeof(v_admission->'candidate_ids') = 'array' THEN v_admission->'candidate_ids'
        ELSE '[]'::jsonb
      END;
    ELSE
      v_eligible := '[]'::jsonb;
    END IF;

    v_would_admit := jsonb_array_length(v_eligible);
    v_would_reject := GREATEST(jsonb_array_length(v_shortlist) - v_would_admit, 0);
    IF v_mode = 'AUTHORITATIVE' AND v_would_admit > 0 THEN
      WITH input_candidates AS (
        SELECT DISTINCT candidate_value.value::uuid AS candidate_id
        FROM jsonb_array_elements_text(v_eligible) AS candidate_value(value)
      ), base_ordinal AS (
        SELECT COALESCE(MAX(scope_row.scope_ordinal), 0)::bigint AS value
        FROM public.banking_pay_workbench_session_scope AS scope_row
        WHERE scope_row.session_id = v_session.id
      ), inserted_scope AS (
        INSERT INTO public.banking_pay_workbench_session_scope(
          session_id, candidate_id, scope_ordinal, status, pending_job_id,
          seeded, dirty, error_json, created_at_utc, updated_at_utc
        )
        SELECT v_session.id,
               input_candidates.candidate_id,
               base_ordinal.value + ROW_NUMBER() OVER (ORDER BY input_candidates.candidate_id),
               'PENDING', NULL::uuid, true, false, NULL::jsonb, v_now, v_now
        FROM input_candidates
        CROSS JOIN base_ordinal
        ON CONFLICT (session_id, candidate_id) DO NOTHING
        RETURNING candidate_id
      )
      SELECT COUNT(*)::integer,
             COALESCE(
               jsonb_agg(to_jsonb(inserted_scope.candidate_id::text) ORDER BY inserted_scope.candidate_id),
               '[]'::jsonb
             )
      INTO v_inserted_count, v_inserted
      FROM inserted_scope;

      IF v_inserted_count > 0 THEN
        v_enqueue := public.pay_workbench_enqueue_candidate_refresh_many(
          p_session_id => v_session.id,
          p_candidate_ids => v_inserted,
          p_reason => 'CONTINUOUS_SCOPE_RECONCILE_ADMISSION',
          p_actor_user_id => v_session.actor_user_id
        );
      END IF;
    END IF;

    SELECT page_row.scope_change_generation, page_row.entity_key
    INTO v_last_generation, v_last_entity_key
    FROM pg_temp._bpay_scope_reconcile_page AS page_row
    WHERE page_row.page_ordinal <= v_limit
    ORDER BY page_row.page_ordinal DESC
    LIMIT 1;

    v_shadow_previous := CASE
      WHEN jsonb_typeof(v_job.payload_json->'shadow_accumulator') = 'object'
        THEN v_job.payload_json->'shadow_accumulator'
      ELSE '{}'::jsonb
    END;

    SELECT COALESCE(jsonb_agg(sample_row.value ORDER BY sample_row.ordinality), '[]'::jsonb)
    INTO v_shadow_sample
    FROM jsonb_array_elements(
      COALESCE(v_shadow_previous->'candidate_sample', '[]'::jsonb)
      || COALESCE((
        SELECT jsonb_agg(to_jsonb(sample_candidate.value) ORDER BY sample_candidate.ordinality)
        FROM jsonb_array_elements_text(v_shortlist)
             WITH ORDINALITY AS sample_candidate(value, ordinality)
        WHERE sample_candidate.ordinality <= 25
      ), '[]'::jsonb)
    ) WITH ORDINALITY AS sample_row(value, ordinality)
    WHERE sample_row.ordinality <= 25;

    v_shadow_summary := jsonb_build_object(
      'target_generation', v_target,
      'candidates_considered', COALESCE((v_shadow_previous->>'candidates_considered')::integer, 0) + v_page_count,
      'already_in_scope', COALESCE((v_shadow_previous->>'already_in_scope')::integer, 0) + v_already_in_scope,
      'would_admit', COALESCE((v_shadow_previous->>'would_admit')::integer, 0) + v_would_admit,
      'would_reject', COALESCE((v_shadow_previous->>'would_reject')::integer, 0) + v_would_reject,
      'would_enqueue_refresh', COALESCE((v_shadow_previous->>'would_enqueue_refresh')::integer, 0) + v_would_admit,
      'candidate_sample', v_shadow_sample,
      'decision_hash', encode(
        extensions.digest(
          convert_to(v_shortlist::text || '|' || v_eligible::text || '|' || v_target::text, 'UTF8'),
          'sha256'
        ),
        'hex'
      )
    );

    IF v_has_more THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object(
              'target_generation', v_target,
              'active_session_id', v_session.id::text,
              'cursor_generation', v_last_generation,
              'cursor_entity_key', v_last_entity_key,
              'candidate_limit', v_limit,
              'reconcile_mode', v_mode,
              'shadow_accumulator', CASE
                WHEN v_mode = 'SHADOW' THEN v_shadow_summary
                ELSE NULL::jsonb
              END,
              'last_shadow_page', CASE
                WHEN v_mode = 'SHADOW' THEN v_shadow_summary
                ELSE NULL::jsonb
              END
            ),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;

      RETURN jsonb_build_object(
        'ok', true,
        'processed', true,
        'status', 'QUEUED',
        'reconcile_mode', v_mode,
        'session_id', v_session.id::text,
        'target_generation', v_target,
        'page_count', v_page_count,
        'admitted_count', CASE WHEN v_mode = 'AUTHORITATIVE' THEN v_inserted_count ELSE 0 END,
        'shadow_summary', CASE WHEN v_mode = 'SHADOW' THEN v_shadow_summary ELSE NULL::jsonb END,
        'has_more', true
      );
    END IF;

    v_blocker := public.pay_workbench_scope_blocker_state_v1(v_session.id, v_target, NULL::uuid);
    v_upstream_active := COALESCE((v_blocker->>'upstream_active_count')::integer, 0);
    v_upstream_failed := COALESCE((v_blocker->>'upstream_unresolved_failure_count')::integer, 0);

    IF v_upstream_failed > 0 OR v_upstream_active > 0 THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now + CASE
            WHEN v_upstream_failed > 0 THEN interval '30 seconds'
            ELSE interval '1 second'
          END,
          started_at_utc = NULL::timestamptz,
          last_error_json = CASE
            WHEN v_upstream_failed > 0 THEN jsonb_build_object(
              'code', 'PAY_WORKBENCH_SCOPE_RECONCILIATION_UPSTREAM_FAILED',
              'failure_sample', COALESCE(v_blocker->'failure_sample', '[]'::jsonb),
              'target_generation', v_target
            )
            ELSE coordinator_job.last_error_json
          END,
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
      RETURN jsonb_build_object(
        'ok', v_upstream_failed = 0,
        'processed', true,
        'status', 'QUEUED',
        'reason', CASE
          WHEN v_upstream_failed > 0 THEN 'UPSTREAM_SCOPE_FAILURE_UNRESOLVED'
          ELSE 'UPSTREAM_APPEARED_BEFORE_ADVANCE'
        END
      );
    END IF;

    IF v_mode = 'SHADOW' THEN
      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET scope_change_generation_shadow_checked = v_target,
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'scope_reconcile_status', 'SHADOW_SUCCEEDED',
              'scope_reconcile_mode', 'SHADOW',
              'scope_change_generation_shadow_checked', v_target,
              'scope_shadow_summary', v_shadow_summary,
              'scope_shadow_checked_at_utc', v_now::text
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = v_session.id;
    ELSE
      UPDATE public.banking_pay_workbench_sessions AS session_update
      SET scope_change_generation_applied = v_target,
          scope_change_generation_target = v_target,
          progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
            || jsonb_build_object(
              'scope_reconcile_status', 'SUCCEEDED',
              'scope_reconcile_mode', 'AUTHORITATIVE',
              'scope_change_generation_target', v_target,
              'scope_change_generation_applied', v_target,
              'scope_reconciled_at_utc', v_now::text
            ),
          progress_counter_version = COALESCE(session_update.progress_counter_version, 0) + 1,
          progress_updated_at_utc = v_now,
          updated_at_utc = v_now
      WHERE session_update.id = v_session.id;
    END IF;

    SELECT generation_counter.seq
    INTO v_current_generation
    FROM public.app_change_counters AS generation_counter
    WHERE generation_counter.entity_key = 'pay_candidate_scope_generation'
    FOR UPDATE;

    SELECT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_sessions AS lagging_session
      WHERE UPPER(BTRIM(COALESCE(lagging_session.status, ''))) = 'OPEN'
        AND lagging_session.discarded_at_utc IS NULL
        AND lagging_session.replacement_session_id IS NULL
        AND COALESCE(lagging_session.scope_seed_complete, false)
        AND (
          (v_mode = 'SHADOW' AND COALESCE(lagging_session.scope_change_generation_shadow_checked, 0) < v_current_generation)
          OR
          (v_mode = 'AUTHORITATIVE' AND COALESCE(lagging_session.scope_change_generation_applied, 0) < v_current_generation)
        )
    ) INTO v_more_sessions;

    IF v_current_generation > v_target OR v_more_sessions THEN
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'QUEUED',
          run_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = (COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            - 'active_session_id' - 'cursor_generation' - 'cursor_entity_key')
            || jsonb_build_object('target_generation', v_current_generation, 'reconcile_mode', v_mode),
          scope_change_generation = v_current_generation,
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
    ELSE
      UPDATE public.banking_pay_workbench_jobs AS coordinator_job
      SET status = 'SUCCEEDED',
          completed_at_utc = v_now,
          started_at_utc = NULL::timestamptz,
          failed_at_utc = NULL::timestamptz,
          last_error_json = NULL::jsonb,
          payload_json = COALESCE(coordinator_job.payload_json, '{}'::jsonb)
            || jsonb_build_object('completed_generation', v_target, 'completed_mode', v_mode),
          updated_at_utc = v_now
      WHERE coordinator_job.id = v_job.id;
    END IF;
    RETURN jsonb_build_object(
      'ok', true,
      'processed', true,
      'status', CASE
        WHEN v_current_generation > v_target OR v_more_sessions THEN 'QUEUED'
        ELSE 'SUCCEEDED'
      END,
      'reconcile_mode', v_mode,
      'session_id', v_session.id::text,
      'target_generation', v_target,
      'current_generation', v_current_generation,
      'page_count', v_page_count,
      'admitted_count', CASE WHEN v_mode = 'AUTHORITATIVE' THEN v_inserted_count ELSE 0 END,
      'shadow_summary', CASE WHEN v_mode = 'SHADOW' THEN v_shadow_summary ELSE NULL::jsonb END,
      'has_more', false,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_error_message = MESSAGE_TEXT,
      v_error_detail = PG_EXCEPTION_DETAIL,
      v_error_state = RETURNED_SQLSTATE;

    UPDATE public.banking_pay_workbench_jobs AS failed_coordinator
    SET attempt_count = COALESCE(failed_coordinator.attempt_count, 0) + 1,
        status = CASE
          WHEN COALESCE(failed_coordinator.attempt_count, 0) + 1 >= COALESCE(failed_coordinator.max_attempts, 8)
            THEN 'FAILED'
          ELSE 'QUEUED'
        END,
        run_at_utc = v_now + make_interval(
          secs => LEAST(900, 30 * GREATEST(COALESCE(failed_coordinator.attempt_count, 0) + 1, 1))
        ),
        started_at_utc = NULL::timestamptz,
        failed_at_utc = CASE
          WHEN COALESCE(failed_coordinator.attempt_count, 0) + 1 >= COALESCE(failed_coordinator.max_attempts, 8)
            THEN v_now
          ELSE NULL::timestamptz
        END,
        last_error_json = jsonb_strip_nulls(jsonb_build_object(
          'code', COALESCE(NULLIF(v_error_state, ''), 'PAY_WORKBENCH_SCOPE_RECONCILE_FAILED'),
          'message', v_error_message,
          'detail', v_error_detail,
          'failed_at_utc', v_now::text
        )),
        updated_at_utc = v_now
    WHERE failed_coordinator.id = v_job.id;

    RETURN jsonb_build_object(
      'ok', false,
      'processed', true,
      'job_id', v_job.id::text,
      'code', COALESCE(NULLIF(v_error_state, ''), 'PAY_WORKBENCH_SCOPE_RECONCILE_FAILED'),
      'message', v_error_message
    );
  END;
END;
$function$;

-- pay_workbench_scope_reconcile_ensure_v1()
CREATE OR REPLACE FUNCTION public.pay_workbench_scope_reconcile_ensure_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_enabled boolean := true;
  v_shadow boolean := false;
  v_generation bigint := 0;
  v_lag_exists boolean := false;
  v_job_id uuid;
  v_created boolean := false;
  v_repair_count integer := 0;
  v_cleanup_count integer := 0;
  v_mode text := 'AUTHORITATIVE';
BEGIN
  SELECT
    COALESCE(settings_row.banking_pay_workbench_scope_reconcile_enabled, true),
    COALESCE(settings_row.banking_pay_workbench_scope_reconcile_shadow_mode, false)
  INTO v_enabled, v_shadow
  FROM public.settings_defaults AS settings_row
  ORDER BY settings_row.id
  LIMIT 1;

  IF NOT COALESCE(v_enabled, true) THEN
    RETURN jsonb_build_object('ok', true, 'enabled', false, 'created', false);
  END IF;

  IF NOT pg_try_advisory_xact_lock(94231, 1) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'enabled', true,
      'advisory_lock_acquired', false,
      'created', false
    );
  END IF;

  WITH repair_page AS (
    SELECT candidate_counter.entity_key
    FROM public.app_change_counters AS candidate_counter
    WHERE candidate_counter.entity_key LIKE 'pay_candidate:%'
      AND candidate_counter.entity_key
            ~* '^pay_candidate:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND candidate_counter.scope_change_generation IS NULL
    ORDER BY candidate_counter.updated_at, candidate_counter.entity_key
    LIMIT 100
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.app_change_counters AS candidate_counter
  SET seq = candidate_counter.seq + 1,
      updated_at = clock_timestamp()
  FROM repair_page
  WHERE candidate_counter.entity_key = repair_page.entity_key;
  GET DIAGNOSTICS v_repair_count = ROW_COUNT;

  WITH cleanup_page AS (
    SELECT scope_tx.tx_token
    FROM public.banking_pay_scope_change_transactions AS scope_tx
    WHERE scope_tx.state IN ('FINALIZED', 'NOOP')
      AND scope_tx.finalized_at_utc < clock_timestamp() - interval '7 days'
    ORDER BY scope_tx.finalized_at_utc, scope_tx.tx_token
    LIMIT 100
    FOR UPDATE SKIP LOCKED
  )
  DELETE FROM public.banking_pay_scope_change_transactions AS scope_tx
  USING cleanup_page
  WHERE scope_tx.tx_token = cleanup_page.tx_token;
  GET DIAGNOSTICS v_cleanup_count = ROW_COUNT;

  v_generation := public.pay_workbench_scope_current_generation_v1();
  v_mode := CASE WHEN v_shadow THEN 'SHADOW' ELSE 'AUTHORITATIVE' END;

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE UPPER(BTRIM(COALESCE(session_row.status, ''))) = 'OPEN'
      AND session_row.discarded_at_utc IS NULL
      AND session_row.replacement_session_id IS NULL
      AND COALESCE(session_row.scope_seed_complete, false)
      AND (
        (v_shadow AND COALESCE(session_row.scope_change_generation_shadow_checked, 0) < v_generation)
        OR
        (NOT v_shadow AND COALESCE(session_row.scope_change_generation_applied, 0) < v_generation)
      )
  ) INTO v_lag_exists;

  IF NOT v_lag_exists THEN
    RETURN jsonb_build_object(
      'ok', true,
      'enabled', true,
      'shadow_mode', v_shadow,
      'reconcile_mode', v_mode,
      'current_generation', v_generation,
      'lag_exists', false,
      'legacy_counter_repair_count', v_repair_count,
      'staging_cleanup_count', v_cleanup_count,
      'created', false
    );
  END IF;

  INSERT INTO public.banking_pay_workbench_jobs AS coordinator_job(
    job_type, status, priority, run_at_utc, attempt_count, max_attempts,
    dedupe_key, payload_json, created_at_utc, updated_at_utc,
    scope_change_generation, scope_change_tx_token
  ) VALUES (
    'WORKBENCH_SCOPE_RECONCILE', 'QUEUED', 40, clock_timestamp(), 0, 8,
    'WORKBENCH_SCOPE_RECONCILE:GLOBAL',
    jsonb_build_object(
      'run_mode', 'CONTINUOUS_SCOPE_RECONCILE',
      'reconcile_mode', v_mode,
      'target_generation', v_generation,
      'candidate_limit', 25,
      'session_limit', 1,
      'shadow_mode', v_shadow,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    ),
    clock_timestamp(), clock_timestamp(), v_generation, NULL::uuid
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO NOTHING
  RETURNING coordinator_job.id INTO v_job_id;

  v_created := v_job_id IS NOT NULL;
  IF NOT v_created THEN
    SELECT active_job.id
    INTO v_job_id
    FROM public.banking_pay_workbench_jobs AS active_job
    WHERE active_job.dedupe_key = 'WORKBENCH_SCOPE_RECONCILE:GLOBAL'
      AND active_job.status IN ('QUEUED', 'RUNNING')
    ORDER BY active_job.created_at_utc
    LIMIT 1;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'enabled', true,
    'shadow_mode', v_shadow,
    'reconcile_mode', v_mode,
    'current_generation', v_generation,
    'lag_exists', true,
    'legacy_counter_repair_count', v_repair_count,
    'staging_cleanup_count', v_cleanup_count,
    'created', v_created,
    'job_id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END
  );
END;
$function$;

-- pay_workbench_seed_candidate_preview_line_source(uuid,uuid,jsonb,jsonb,integer)
CREATE OR REPLACE FUNCTION public.pay_workbench_seed_candidate_preview_line_source(p_session_id uuid, p_candidate_id uuid, p_context_json jsonb DEFAULT '{}'::jsonb, p_cursor_json jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_context_json jsonb := '{}'::jsonb;
  v_input_cursor_json jsonb := NULL::jsonb;
  v_effective_cursor_json jsonb := '{}'::jsonb;
  v_source_build_run_id_text text := NULL::text;
  v_source_build_run_count integer := 0;
  v_source_change_seq bigint := NULL::bigint;
  v_session_version bigint := NULL::bigint;
  v_source_snapshot_run_id_text text := NULL::text;
  v_session_signature text := NULL::text;
  v_seed_result jsonb := '{}'::jsonb;
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('WORKBENCH_CHUNK');

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_SOURCE_SESSION_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_SEED_SOURCE_SESSION_ID_REQUIRED')::text;
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_SOURCE_CANDIDATE_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_SEED_SOURCE_CANDIDATE_ID_REQUIRED')::text;
  END IF;

  IF p_context_json IS NOT NULL AND jsonb_typeof(p_context_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_SOURCE_CONTEXT_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SEED_SOURCE_CONTEXT_MUST_BE_OBJECT',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'context_type', jsonb_typeof(p_context_json)
            )::text;
  END IF;

  IF p_cursor_json IS NOT NULL AND jsonb_typeof(p_cursor_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_SOURCE_CURSOR_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SEED_SOURCE_CURSOR_MUST_BE_OBJECT',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'cursor_type', jsonb_typeof(p_cursor_json)
            )::text;
  END IF;

  IF to_regclass('public.banking_pay_workbench_candidate_source_lines') IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_SOURCE_TABLE_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SEED_SOURCE_TABLE_MISSING',
              'required_table', 'public.banking_pay_workbench_candidate_source_lines',
              'message', 'This compatibility wrapper now pages persisted source rows only.'
            )::text;
  END IF;

  v_context_json := COALESCE(p_context_json, '{}'::jsonb);
  v_input_cursor_json := CASE
    WHEN p_cursor_json IS NOT NULL THEN p_cursor_json
    WHEN jsonb_typeof(v_context_json->'cursor_json') = 'object' THEN v_context_json->'cursor_json'
    WHEN jsonb_typeof(v_context_json->'cursor') = 'object' THEN v_context_json->'cursor'
    WHEN jsonb_typeof(v_context_json->'source_cursor') = 'object' THEN v_context_json->'source_cursor'
    WHEN jsonb_typeof(v_context_json->'source_build_cursor') = 'object' THEN v_context_json->'source_build_cursor'
    WHEN jsonb_typeof(v_context_json#>'{source_build,cursor}') = 'object' THEN v_context_json#>'{source_build,cursor}'
    ELSE '{}'::jsonb
  END;

  v_source_build_run_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_input_cursor_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_input_cursor_json#>>'{source_build,source_build_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_input_cursor_json#>>'{source_build,run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_context_json->>'source_build_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_context_json#>>'{source_build,source_build_run_id}', '')), ''),
    NULLIF(BTRIM(COALESCE(v_context_json#>>'{source_build,run_id}', '')), '')
  );

  IF v_source_build_run_id_text IS NULL THEN
    WITH current_runs AS (
      SELECT
        source_line.source_build_run_id,
        MAX(source_line.updated_at_utc) AS latest_updated_at_utc
      FROM public.banking_pay_workbench_candidate_source_lines AS source_line
      WHERE source_line.session_id = p_session_id
        AND source_line.candidate_id = p_candidate_id
        AND source_line.status = 'CURRENT'
      GROUP BY source_line.source_build_run_id
    )
    SELECT COUNT(*)::integer,
           (array_agg(current_runs.source_build_run_id::text ORDER BY current_runs.latest_updated_at_utc DESC, current_runs.source_build_run_id::text DESC))[1]
    INTO v_source_build_run_count,
         v_source_build_run_id_text
    FROM current_runs;

    IF COALESCE(v_source_build_run_count, 0) = 0 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SEED_SOURCE_ROWS_MISSING'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_SEED_SOURCE_ROWS_MISSING',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'message', 'No current persisted source rows were found for this candidate.'
              )::text;
    ELSIF COALESCE(v_source_build_run_count, 0) > 1 THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_SEED_SOURCE_BUILD_RUN_ID_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_WORKBENCH_SEED_SOURCE_BUILD_RUN_ID_REQUIRED',
                'session_id', p_session_id::text,
                'candidate_id', p_candidate_id::text,
                'current_source_build_run_count', COALESCE(v_source_build_run_count, 0),
                'message', 'Multiple current source-build runs exist; a cursor with source_build_run_id is required.'
              )::text;
    END IF;
  END IF;

  IF v_source_build_run_id_text IS NULL
     OR v_source_build_run_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEED_SOURCE_BUILD_RUN_ID_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_WORKBENCH_SEED_SOURCE_BUILD_RUN_ID_INVALID',
              'session_id', p_session_id::text,
              'candidate_id', p_candidate_id::text,
              'source_build_run_id', v_source_build_run_id_text
            )::text;
  END IF;

  v_source_change_seq := COALESCE(
    CASE WHEN COALESCE(v_input_cursor_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_input_cursor_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
    CASE WHEN COALESCE(v_input_cursor_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (v_input_cursor_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
    CASE WHEN COALESCE(v_context_json->>'source_change_seq', '') ~ '^[0-9]{1,18}$' THEN (v_context_json->>'source_change_seq')::bigint ELSE NULL::bigint END,
    CASE WHEN COALESCE(v_context_json->>'source_change_sequence', '') ~ '^[0-9]{1,18}$' THEN (v_context_json->>'source_change_sequence')::bigint ELSE NULL::bigint END,
    CASE WHEN COALESCE(v_context_json#>>'{source_build,source_change_seq}', '') ~ '^[0-9]{1,18}$' THEN (v_context_json#>>'{source_build,source_change_seq}')::bigint ELSE NULL::bigint END
  );

  v_session_version := COALESCE(
    CASE WHEN COALESCE(v_input_cursor_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (v_input_cursor_json->>'session_version')::bigint ELSE NULL::bigint END,
    CASE WHEN COALESCE(v_context_json->>'session_version', '') ~ '^[0-9]{1,18}$' THEN (v_context_json->>'session_version')::bigint ELSE NULL::bigint END,
    CASE WHEN COALESCE(v_context_json#>>'{source_build,session_version}', '') ~ '^[0-9]{1,18}$' THEN (v_context_json#>>'{source_build,session_version}')::bigint ELSE NULL::bigint END
  );

  v_source_snapshot_run_id_text := COALESCE(
    NULLIF(BTRIM(COALESCE(v_input_cursor_json->>'source_snapshot_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_input_cursor_json->>'snapshot_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_context_json->>'source_snapshot_run_id', '')), ''),
    NULLIF(BTRIM(COALESCE(v_context_json->>'snapshot_run_id', '')), '')
  );

  v_session_signature := COALESCE(
    NULLIF(BTRIM(COALESCE(v_input_cursor_json->>'session_signature', '')), ''),
    NULLIF(BTRIM(COALESCE(v_context_json->>'session_signature', '')), ''),
    NULLIF(BTRIM(COALESCE(v_context_json#>>'{source_build,session_signature}', '')), '')
  );

  v_effective_cursor_json := jsonb_strip_nulls(
    COALESCE(v_input_cursor_json, '{}'::jsonb)
    || jsonb_build_object(
      'source_build_run_id', v_source_build_run_id_text,
      'source_change_seq', v_source_change_seq,
      'source_change_sequence', v_source_change_seq,
      'session_version', v_session_version,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'source_snapshot_run_id', v_source_snapshot_run_id_text,
      'session_signature', v_session_signature
    )
  );

  v_seed_result := public.pay_workbench_candidate_line_work_seed(
    p_session_id => p_session_id,
    p_candidate_id => p_candidate_id,
    p_cursor_json => v_effective_cursor_json,
    p_limit => LEAST(GREATEST(COALESCE(p_limit, 100), 1), 100)
  );

  RETURN COALESCE(v_seed_result, '{}'::jsonb)
    || jsonb_build_object(
      'ok', true,
      'source_function', 'pay_workbench_seed_candidate_preview_line_source',
      'compatibility_wrapper', true,
      'delegated_to', 'pay_workbench_candidate_line_work_seed',
      'line_seed_source', 'PERSISTED_SOURCE_LINES',
      'candidate_line_calculation_performed', false,
      'source_construction_performed', false,
      'source_build_run_id', v_source_build_run_id_text,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
      'completed_at_utc', v_now::text
    );
END;
$function$;

-- pay_workbench_session_apply_case_resolution(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_session_apply_case_resolution(p_session_id uuid, p_actor_user_id uuid, p_resolution_payload_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "plpgsql_check.mode" TO 'disabled'
 SET "plpgsql_check.profiler" TO 'off'
 SET "plpgsql_check.tracer" TO 'off'
 SET "plpgsql_check.constants_tracing" TO 'off'
 SET "plpgsql_check.cursors_leaks" TO 'off'
 SET "plpgsql_check.strict_cursors_leaks" TO 'off'
 SET "plpgsql_check.fatal_errors" TO 'off'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_expected_session_version bigint := NULL::bigint;
  v_expected_progress_counter_version bigint := NULL::bigint;
  v_expected_session_version_text text := '';
  v_expected_progress_counter_version_text text := '';
  v_resolution_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_resolution_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_resolution_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_top_source_basis_json jsonb := '{}'::jsonb;
  v_bucket_resolutions_json jsonb := '[]'::jsonb;
  v_candidate_id uuid := NULL::uuid;
  v_candidate_id_text text := '';
  v_case_key text := '';
  v_resolution_family text := '';
  v_default_resolution_mode text := '';
  v_linked_timesheet_id uuid := NULL::uuid;
  v_linked_timesheet_id_text text := '';
  v_finance_case_id_text text := '';
  v_resolve_all_linked_timesheets boolean := false;
  v_resolved_candidate_id uuid := NULL::uuid;
  v_matching_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_matching_candidate_count integer := 0;
  v_target_match_count integer := 0;
  v_row_backed_case_count integer := 0;
  v_row_backed_component_count integer := 0;
  v_bucket_count integer := 0;
  v_existing_deleted_count integer := 0;
  v_new_session_version bigint := 0;
  v_new_progress_counter_version bigint := 0;
  v_job_json jsonb := '{}'::jsonb;
  v_job_id_text text := NULL::text;
  v_job_id uuid := NULL::uuid;
  v_session_refresh_cursor jsonb := '{}'::jsonb;
  v_session_refresh_page jsonb := '{}'::jsonb;
  v_session_refresh_pages jsonb := '[]'::jsonb;
  v_session_refresh_page_count integer := 0;
  v_case_resolution_ids jsonb := '[]'::jsonb;
  v_resolution_identity_keys jsonb := '[]'::jsonb;
  v_case_resolution_id_text text := null;
  v_resolution_origins_json jsonb := '[]'::jsonb;
  v_resolution_origin_count integer := 0;
  v_single_resolution_origin_session_id uuid := NULL::uuid;
  v_single_resolution_origin_pay_date date := NULL::date;
  v_correction_normalise_result jsonb := '{}'::jsonb;
  v_action text := 'SESSION_CASE_RESOLUTION_APPLIED';
  v_case_targeted_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_case_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_case_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_target_amount_ex_vat numeric := NULL::numeric;
  v_nonbucket_resolution_mode text := '';
  v_nonbucket_resolution_identity_key text := '';
  v_nonbucket_existing_row public.banking_pay_workbench_session_case_resolutions%ROWTYPE;
  v_nonbucket_upserted_row public.banking_pay_workbench_session_case_resolutions%ROWTYPE;
  v_existing_row public.banking_pay_workbench_session_case_resolutions%ROWTYPE;
  v_upserted_row public.banking_pay_workbench_session_case_resolutions%ROWTYPE;
  v_bucket_row record;
  v_bucket_element record;
  v_bucket_source_basis_json jsonb := '{}'::jsonb;
  v_bucket_source_basis_fingerprint text := '';
  v_bucket_source_family_key text := '';
  v_bucket_bucket_code text := '';
  v_bucket_component_key_type text := '';
  v_bucket_component_key_value text := '';
  v_bucket_resolution_mode text := '';
  v_bucket_timesheet_id uuid := NULL::uuid;
  v_bucket_timesheet_id_text text := '';
  v_bucket_source_units numeric := NULL::numeric;
  v_bucket_source_rate numeric := NULL::numeric;
  v_bucket_source_charge_rate numeric := NULL::numeric;
  v_bucket_target_rate numeric := NULL::numeric;
  v_bucket_resolution_identity_key text := '';
  v_normalized_payload_json jsonb := '{}'::jsonb;
  v_taxable_finance_case_id uuid := NULL::uuid;
  v_taxable_case_candidate_id uuid := NULL::uuid;
  v_taxable_resolution_path text := '';
  v_taxable_schedule_input_mode text := NULL::text;
  v_taxable_weeks_total integer := NULL::integer;
  v_taxable_weekly_due numeric := NULL::numeric;
  v_taxable_manual_total_remaining numeric := NULL::numeric;
  v_taxable_effective_pay_date date := NULL::date;
  v_taxable_note text := NULL::text;
  v_taxable_result_json jsonb := '{}'::jsonb;
  v_audit_before_json jsonb := NULL;
  v_audit_after_json jsonb := '{}'::jsonb;
  v_anchor_evidence_key text := NULL::text;
  v_bucket_matched_candidate_id uuid := NULL::uuid;
  v_matching_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_anchor_timesheet_id uuid := NULL::uuid;
  v_anchor_contract_id uuid := NULL::uuid;
  v_anchor_client_id uuid := NULL::uuid;
  v_anchor_component_count integer := 0;
  v_linked_target_timesheet_count integer := 0;
  v_linked_target_component_count integer := 0;
  v_materialized_target_timesheet_count integer := 0;
  v_skipped_mismatch_count integer := 0;
  v_linked_scope_type text := 'SELF_ONLY';
  v_target_resolution_row record;
  v_target_resolution_result_json jsonb := '{}'::jsonb;
  v_target_bucket_payload_json jsonb := '{}'::jsonb;
  v_linked_scope_json jsonb := '{}'::jsonb;
  v_operation text := 'APPLY';
  v_eligible_linked_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_excluded_linked_timesheets jsonb := '[]'::jsonb;
  v_excluded_linked_timesheet_count integer := 0;
  v_total_affected_timesheet_count integer := 1;
  v_anchor_blocking_batches jsonb := '[]'::jsonb;
BEGIN
  v_resolution_payload_json:=public._ctms_enrich_correction_resolution_payload_v1(
    p_session_id,
    v_resolution_payload_json
  );
  v_operation := UPPER(BTRIM(COALESCE(
    v_resolution_payload_json->>'operation',
    v_resolution_payload_json->>'action',
    'APPLY'
  )));
  IF v_operation IN ('DISCOVER', 'DISCOVER_LINKED_SCOPE', 'PREVIEW_SCOPE', 'LIST_ELIGIBLE_LINKED') THEN
    v_operation := 'DISCOVER';
  ELSIF v_operation IN ('', 'APPLY', 'SAVE', 'APPLY_RESOLUTION') THEN
    v_operation := 'APPLY';
  ELSE
    RAISE EXCEPTION 'WORKBENCH_RESOLUTION_OPERATION_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_RESOLUTION_OPERATION_INVALID',
              'operation', v_operation,
              'message', 'The requested resolved-rate action is not valid.'
            )::text;
  END IF;

  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    PERFORM 1
    FROM public.tms_users
    WHERE public.tms_users.id = p_actor_user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
    END IF;
  END IF;

  IF v_operation = 'DISCOVER' THEN
    SELECT public.banking_pay_workbench_sessions.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions
    WHERE public.banking_pay_workbench_sessions.id = p_session_id;
  ELSE
    SELECT public.banking_pay_workbench_sessions.*
    INTO v_session_row
    FROM public.banking_pay_workbench_sessions
    WHERE public.banking_pay_workbench_sessions.id = p_session_id
    FOR UPDATE;
  END IF;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status <> 'OPEN'
     OR v_session_row.discarded_at_utc IS NOT NULL
     OR v_session_row.replacement_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'OBSOLETE_SESSION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'OBSOLETE_SESSION',
              'session_id', p_session_id::text,
              'status', COALESCE(v_session_row.status, ''),
              'replacement_session_id', CASE WHEN v_session_row.replacement_session_id IS NULL THEN NULL ELSE v_session_row.replacement_session_id::text END,
              'message', 'The Banking Pay workbench session is no longer current. Refresh the preview before saving the case resolution.'
            )::text;
  END IF;

  v_expected_session_version_text := NULLIF(BTRIM(COALESCE(
    v_resolution_payload_json->>'expected_session_version',
    v_resolution_payload_json->>'expectedSessionVersion',
    v_resolution_payload_json->>'session_version',
    v_resolution_payload_json->>'sessionVersion',
    ''
  )), '');

  v_expected_progress_counter_version_text := NULLIF(BTRIM(COALESCE(
    v_resolution_payload_json->>'expected_progress_counter_version',
    v_resolution_payload_json->>'expectedProgressCounterVersion',
    v_resolution_payload_json->>'progress_counter_version',
    v_resolution_payload_json->>'progressCounterVersion',
    ''
  )), '');

  IF v_expected_session_version_text IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_VERSION_CONTEXT_REQUIRED',
              'session_id', p_session_id::text,
              'current_session_version', COALESCE(v_session_row.version, 0),
              'message', 'The Banking Pay case resolution request was missing the current session version. Refresh the preview before saving.'
            )::text;
  END IF;

  IF v_expected_session_version_text !~ '^[0-9]{1,18}$' THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_CONTEXT_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_VERSION_CONTEXT_INVALID',
              'session_id', p_session_id::text,
              'provided_session_version', v_expected_session_version_text
            )::text;
  END IF;

  v_expected_session_version := v_expected_session_version_text::bigint;
  IF v_expected_session_version < 1 THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_CONTEXT_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'WORKBENCH_SESSION_VERSION_CONTEXT_INVALID', 'session_id', p_session_id::text)::text;
  END IF;

  IF v_expected_progress_counter_version_text IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_PROGRESS_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_PROGRESS_CONTEXT_REQUIRED',
              'session_id', p_session_id::text,
              'current_progress_counter_version', COALESCE(v_session_row.progress_counter_version, 0),
              'message', 'The Banking Pay case resolution request was missing the current progress version. Refresh the preview before saving.'
            )::text;
  END IF;

  IF v_expected_progress_counter_version_text !~ '^[0-9]{1,18}$' THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_PROGRESS_CONTEXT_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_PROGRESS_CONTEXT_INVALID',
              'session_id', p_session_id::text,
              'provided_progress_counter_version', v_expected_progress_counter_version_text
            )::text;
  END IF;

  v_expected_progress_counter_version := v_expected_progress_counter_version_text::bigint;

  IF COALESCE(v_session_row.version, 0) IS DISTINCT FROM v_expected_session_version THEN
    RAISE EXCEPTION 'STALE_SESSION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'STALE_SESSION',
              'session_id', p_session_id::text,
              'expected_session_version', v_expected_session_version,
              'current_session_version', COALESCE(v_session_row.version, 0),
              'message', 'The Banking Pay workbench session changed in another window. Refresh the preview before saving the case resolution.'
            )::text;
  END IF;

  -- DISCOVER is read-only and revalidates the row-backed component identity
  -- below. Bind it to the progress version read in this same statement so
  -- unrelated background materialisation cannot create a check/use race.
  -- APPLY retains the caller's reviewed progress fence unchanged.
  IF v_operation = 'DISCOVER' THEN
    v_expected_progress_counter_version :=
      COALESCE(v_session_row.progress_counter_version, 0);
  END IF;

  IF COALESCE(v_session_row.progress_counter_version, 0) IS DISTINCT FROM v_expected_progress_counter_version THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_PROGRESS_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_PROGRESS_CHANGED',
              'session_id', p_session_id::text,
              'expected_progress_counter_version', v_expected_progress_counter_version,
              'current_progress_counter_version', COALESCE(v_session_row.progress_counter_version, 0),
              'message', 'The Banking Pay workbench changed in another window. Refresh the preview before saving the case resolution.'
            )::text;
  END IF;

  v_candidate_id_text := BTRIM(COALESCE(
    v_resolution_payload_json->>'candidate_id',
    v_resolution_payload_json #>> '{case,candidate_id}',
    ''
  ));
  IF v_candidate_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_candidate_id := v_candidate_id_text::uuid;
  END IF;

  v_case_key := BTRIM(COALESCE(
    v_resolution_payload_json->>'case_key',
    v_resolution_payload_json #>> '{case,case_key}',
    ''
  ));
  IF v_case_key = '' THEN
    RAISE EXCEPTION 'case_key is required';
  END IF;

  v_resolution_family := UPPER(BTRIM(COALESCE(v_resolution_payload_json->>'resolution_family', v_resolution_payload_json->>'resolution_kind', '')));
  v_default_resolution_mode := UPPER(BTRIM(COALESCE(
    v_resolution_payload_json->>'resolution_mode',
    v_resolution_payload_json->>'mode',
    ''
  )));

  v_linked_timesheet_id_text := BTRIM(COALESCE(
    v_resolution_payload_json->>'linked_timesheet_id',
    v_resolution_payload_json->>'timesheet_id',
    ''
  ));
  IF v_linked_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_linked_timesheet_id := v_linked_timesheet_id_text::uuid;
  END IF;

  v_finance_case_id_text := BTRIM(COALESCE(
    v_resolution_payload_json->>'finance_case_id',
    v_resolution_payload_json #>> '{case,finance_case_id}',
    ''
  ));

  v_resolve_all_linked_timesheets := CASE
    WHEN LOWER(BTRIM(COALESCE(v_resolution_payload_json->>'resolve_all_linked_timesheets', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN true
    ELSE false
  END;

  v_top_source_basis_json := CASE
    WHEN jsonb_typeof(v_resolution_payload_json->'source_basis_json') = 'object' THEN COALESCE(v_resolution_payload_json->'source_basis_json', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_bucket_resolutions_json := CASE
    WHEN jsonb_typeof(v_resolution_payload_json->'bucket_resolutions') = 'array' THEN COALESCE(v_resolution_payload_json->'bucket_resolutions', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  IF v_resolution_family = '' THEN
    IF jsonb_array_length(v_bucket_resolutions_json) > 0 THEN
      v_resolution_family := 'BUCKETED';
    ELSE
      v_resolution_family := 'NON_BUCKET';
    END IF;
  END IF;

  IF v_resolution_family NOT IN ('BUCKETED', 'NON_BUCKET', 'TAXABLE_CHANNEL_RESTRUCTURE') THEN
    RAISE EXCEPTION 'resolution_family must be BUCKETED, NON_BUCKET or TAXABLE_CHANNEL_RESTRUCTURE';
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS _tmp_bpay_session_candidate_scope (
    candidate_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  TRUNCATE TABLE _tmp_bpay_session_candidate_scope;

  INSERT INTO _tmp_bpay_session_candidate_scope (candidate_id)
  SELECT scoped_candidate.candidate_id
  FROM unnest(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])) AS scoped_candidate(candidate_id)
  WHERE scoped_candidate.candidate_id IS NOT NULL
  ON CONFLICT (candidate_id) DO NOTHING;

  INSERT INTO _tmp_bpay_session_candidate_scope (candidate_id)
  SELECT DISTINCT session_scope.candidate_id
  FROM public.banking_pay_workbench_session_scope AS session_scope
  WHERE session_scope.session_id = p_session_id
    AND session_scope.candidate_id IS NOT NULL
  ON CONFLICT (candidate_id) DO NOTHING;

  INSERT INTO _tmp_bpay_session_candidate_scope (candidate_id)
  SELECT DISTINCT preview_row.candidate_id
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.candidate_id IS NOT NULL
  ON CONFLICT (candidate_id) DO NOTHING;

  INSERT INTO _tmp_bpay_session_candidate_scope (candidate_id)
  SELECT DISTINCT line_work.candidate_id
  FROM public.banking_pay_workbench_candidate_line_work AS line_work
  WHERE line_work.session_id = p_session_id
    AND line_work.candidate_id IS NOT NULL
  ON CONFLICT (candidate_id) DO NOTHING;

  IF v_candidate_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM _tmp_bpay_session_candidate_scope AS candidate_scope
       WHERE candidate_scope.candidate_id = v_candidate_id
     ) THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_CANDIDATE_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_CANDIDATE_NOT_FOUND',
              'session_id', p_session_id::text,
              'candidate_id', v_candidate_id::text
            )::text;
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS _tmp_bpay_session_row_backed_case_baseline (
    preview_row_id uuid PRIMARY KEY,
    candidate_id uuid NOT NULL,
    case_key text NOT NULL,
    timesheet_id uuid NULL,
    finance_case_id uuid NULL,
    resolution_family text NULL,
    row_key text NOT NULL,
    row_json jsonb NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE _tmp_bpay_session_row_backed_case_baseline;

  INSERT INTO _tmp_bpay_session_row_backed_case_baseline (
    preview_row_id,
    candidate_id,
    case_key,
    timesheet_id,
    finance_case_id,
    resolution_family,
    row_key,
    row_json
  )
  WITH preview_source AS (
    SELECT
      preview_row.id AS preview_row_id,
      preview_row.candidate_id,
      preview_row.row_key,
      COALESCE(preview_row.row_json, '{}'::jsonb) AS row_json,
      BTRIM(COALESCE(
        preview_row.row_json->>'case_key',
        preview_row.row_json #>> '{case_resolution_summary,case_key}',
        preview_row.row_json #>> '{case,case_key}',
        preview_row.row_json #>> '{raw_case,case_key}',
        ''
      )) AS extracted_case_key,
      BTRIM(COALESCE(
        preview_row.timesheet_id::text,
        preview_row.row_json->>'timesheet_id',
        preview_row.row_json->>'real_business_timesheet_id',
        preview_row.row_json->>'linked_timesheet_id',
        preview_row.row_json #>> '{case,timesheet_id}',
        preview_row.row_json #>> '{raw_case,timesheet_id}',
        ''
      )) AS timesheet_id_text,
      BTRIM(COALESCE(
        preview_row.row_json->>'finance_case_id',
        preview_row.row_json #>> '{case,finance_case_id}',
        preview_row.row_json #>> '{raw_case,finance_case_id}',
        ''
      )) AS finance_case_id_text,
      UPPER(BTRIM(COALESCE(
        preview_row.row_json->>'resolution_family',
        preview_row.row_json #>> '{case_resolution_summary,resolution_family}',
        preview_row.row_json #>> '{case,resolution_family}',
        preview_row.row_json #>> '{raw_case,resolution_family}',
        ''
      ))) AS resolution_family
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'cases_resolutions'
      AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
  ),
  normalized_preview_source AS (
    SELECT
      preview_source.*,
      CASE
        WHEN preview_source.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN preview_source.timesheet_id_text::uuid
        ELSE NULL::uuid
      END AS timesheet_id,
      CASE
        WHEN preview_source.finance_case_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN preview_source.finance_case_id_text::uuid
        ELSE NULL::uuid
      END AS finance_case_id
    FROM preview_source
  )
  SELECT
    normalized_preview_source.preview_row_id,
    normalized_preview_source.candidate_id,
    COALESCE(NULLIF(normalized_preview_source.extracted_case_key, ''), v_case_key),
    normalized_preview_source.timesheet_id,
    normalized_preview_source.finance_case_id,
    NULLIF(normalized_preview_source.resolution_family, ''),
    normalized_preview_source.row_key,
    normalized_preview_source.row_json
  FROM normalized_preview_source
  WHERE normalized_preview_source.candidate_id IS NOT NULL
    AND (
      normalized_preview_source.extracted_case_key = v_case_key
      OR (
        normalized_preview_source.extracted_case_key = ''
        AND v_linked_timesheet_id IS NOT NULL
        AND (
          normalized_preview_source.timesheet_id = v_linked_timesheet_id
          OR normalized_preview_source.row_key = v_linked_timesheet_id::text
          OR normalized_preview_source.row_key LIKE (v_linked_timesheet_id::text || ':%')
        )
      )
      OR (
        normalized_preview_source.extracted_case_key = ''
        AND v_finance_case_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND normalized_preview_source.finance_case_id = v_finance_case_id_text::uuid
      )
    );

  create temp table if not exists _tmp_bpay_session_case_resolution_existing
  as
  select *
  from public.banking_pay_workbench_session_case_resolutions
  with no data;

  truncate table _tmp_bpay_session_case_resolution_existing;

  IF v_resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' THEN
    IF v_finance_case_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'finance_case_id is required for TAXABLE_CHANNEL_RESTRUCTURE resolution';
    END IF;

    v_taxable_finance_case_id := v_finance_case_id_text::uuid;

    SELECT pa.candidate_id
    INTO v_taxable_case_candidate_id
    FROM public.pay_advances AS pa
    WHERE pa.id = v_taxable_finance_case_id
      AND pa.case_type IN (
        'OVERPAYMENT'::public.pay_finance_case_type_enum,
        'UNDERPAYMENT'::public.pay_finance_case_type_enum,
        'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
        'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
      )
      AND pa.status = 'ACTIVE'::public.pay_advance_status_enum
    LIMIT 1;

    IF v_taxable_case_candidate_id IS NULL THEN
      RAISE EXCEPTION 'No active taxable-channel finance case found for finance_case_id %', v_taxable_finance_case_id;
    END IF;

    IF v_candidate_id IS NOT NULL AND v_candidate_id <> v_taxable_case_candidate_id THEN
      RAISE EXCEPTION 'candidate_id % does not match taxable-channel finance case candidate %', v_candidate_id, v_taxable_case_candidate_id;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM _tmp_bpay_session_candidate_scope AS candidate_scope
      WHERE candidate_scope.candidate_id = v_taxable_case_candidate_id
    ) THEN
      RAISE EXCEPTION 'WORKBENCH_SESSION_CANDIDATE_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_SESSION_CANDIDATE_NOT_FOUND',
                'session_id', p_session_id::text,
                'candidate_id', v_taxable_case_candidate_id::text
              )::text;
    END IF;

    v_resolved_candidate_id := v_taxable_case_candidate_id;

    SELECT COUNT(*)::integer
    INTO v_row_backed_case_count
    FROM _tmp_bpay_session_row_backed_case_baseline AS row_backed_case
    WHERE COALESCE(row_backed_case.resolution_family, '') IN ('', 'TAXABLE_CHANNEL_RESTRUCTURE')
      AND (
        row_backed_case.finance_case_id IS NULL
        OR row_backed_case.finance_case_id = v_taxable_finance_case_id
      );

    IF v_row_backed_case_count > 0 THEN
      SELECT COUNT(*)::integer
      INTO v_target_match_count
      FROM _tmp_bpay_session_row_backed_case_baseline AS row_backed_case
      WHERE row_backed_case.candidate_id = v_resolved_candidate_id
        AND COALESCE(row_backed_case.resolution_family, '') IN ('', 'TAXABLE_CHANNEL_RESTRUCTURE')
        AND (
          row_backed_case.finance_case_id IS NULL
          OR row_backed_case.finance_case_id = v_taxable_finance_case_id
        );

      IF v_target_match_count = 0 THEN
        RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND',
                  'session_id', p_session_id::text,
                  'candidate_id', v_resolved_candidate_id::text,
                  'case_key', v_case_key,
                  'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE'
                )::text;
      ELSIF v_target_match_count > 1 THEN
        RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_CASE_BASELINE_AMBIGUOUS'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'WORKBENCH_ROW_BACKED_CASE_BASELINE_AMBIGUOUS',
                  'session_id', p_session_id::text,
                  'candidate_id', v_resolved_candidate_id::text,
                  'case_key', v_case_key,
                  'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE'
                )::text;
      END IF;
    ELSE
      SELECT COUNT(*)::integer
      INTO v_target_match_count
      FROM public.banking_pay_snapshot_case_state AS snapshot_case
      WHERE snapshot_case.snapshot_run_id = v_session_row.source_snapshot_run_id
        AND snapshot_case.candidate_id = v_resolved_candidate_id
        AND snapshot_case.case_key = v_case_key;

      IF v_target_match_count = 0 THEN
        RAISE EXCEPTION 'No matching snapshot baseline case found for TAXABLE_CHANNEL_RESTRUCTURE candidate % in session %', v_resolved_candidate_id, p_session_id;
      ELSIF v_target_match_count > 1 THEN
        RAISE EXCEPTION 'Ambiguous snapshot baseline case found for TAXABLE_CHANNEL_RESTRUCTURE candidate % in session %', v_resolved_candidate_id, p_session_id;
      END IF;
    END IF;

    v_taxable_resolution_path := UPPER(BTRIM(COALESCE(
      v_resolution_payload_json->>'resolution_path',
      v_resolution_payload_json->>'path',
      'SUGGESTED'
    )));
    IF v_taxable_resolution_path = '' THEN
      v_taxable_resolution_path := 'SUGGESTED';
    END IF;

    IF v_taxable_resolution_path NOT IN ('SUGGESTED', 'MANUAL') THEN
      RAISE EXCEPTION 'resolution_path must be SUGGESTED or MANUAL for TAXABLE_CHANNEL_RESTRUCTURE';
    END IF;

    v_taxable_schedule_input_mode := NULLIF(UPPER(BTRIM(COALESCE(
      v_resolution_payload_json->>'schedule_input_mode',
      v_resolution_payload_json->>'schedule_mode',
      ''
    ))), '');
    IF v_taxable_schedule_input_mode IS NOT NULL
       AND v_taxable_schedule_input_mode NOT IN ('BY_WEEKS', 'BY_WEEKLY_DUE') THEN
      RAISE EXCEPTION 'schedule_input_mode must be BY_WEEKS or BY_WEEKLY_DUE for TAXABLE_CHANNEL_RESTRUCTURE';
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'weeks_total', '')), '') IS NOT NULL THEN
      IF BTRIM(COALESCE(v_resolution_payload_json->>'weeks_total', '')) !~ '^\d+$' THEN
        RAISE EXCEPTION 'weeks_total must be a positive integer for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
      v_taxable_weeks_total := (v_resolution_payload_json->>'weeks_total')::integer;
      IF v_taxable_weeks_total < 1 THEN
        RAISE EXCEPTION 'weeks_total must be >= 1 for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'weekly_due', '')), '') IS NOT NULL THEN
      IF BTRIM(COALESCE(v_resolution_payload_json->>'weekly_due', '')) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'weekly_due must be numeric for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
      v_taxable_weekly_due := round((v_resolution_payload_json->>'weekly_due')::numeric, 2);
      IF v_taxable_weekly_due <= 0 THEN
        RAISE EXCEPTION 'weekly_due must be > 0 for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
    END IF;

    IF COALESCE(
      NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'manual_total_remaining', '')), ''),
      NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'target_remaining_balance_ex_vat', '')), '')
    ) IS NOT NULL THEN
      IF COALESCE(
        NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'manual_total_remaining', '')), ''),
        NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'target_remaining_balance_ex_vat', '')), '')
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'manual_total_remaining must be numeric for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
      v_taxable_manual_total_remaining := round(COALESCE(
        NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'manual_total_remaining', '')), '')::numeric,
        NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'target_remaining_balance_ex_vat', '')), '')::numeric
      ), 2);
      IF v_taxable_manual_total_remaining <= 0 THEN
        RAISE EXCEPTION 'manual_total_remaining must be > 0 for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'effective_pay_date', '')), '') IS NOT NULL THEN
      IF BTRIM(COALESCE(v_resolution_payload_json->>'effective_pay_date', '')) !~ '^\d{4}-\d{2}-\d{2}$' THEN
        RAISE EXCEPTION 'effective_pay_date must be YYYY-MM-DD for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
      v_taxable_effective_pay_date := (v_resolution_payload_json->>'effective_pay_date')::date;
    END IF;

    v_taxable_note := NULLIF(BTRIM(COALESCE(
      v_resolution_payload_json->>'note',
      v_resolution_payload_json->>'reason',
      ''
    )), '');

    v_taxable_result_json := public.pay_finance_case_apply_taxable_channel_restructure(
      p_finance_case_id => v_taxable_finance_case_id,
      p_actor_user_id => p_actor_user_id,
      p_resolution_path => v_taxable_resolution_path,
      p_schedule_input_mode => v_taxable_schedule_input_mode,
      p_weeks_total => v_taxable_weeks_total,
      p_weekly_due => v_taxable_weekly_due,
      p_manual_total_remaining => v_taxable_manual_total_remaining,
      p_effective_pay_date => v_taxable_effective_pay_date,
      p_note => v_taxable_note
    );

    v_resolution_identity_keys := jsonb_build_array(
      concat_ws('|', 'TAXABLE_CHANNEL_RESTRUCTURE', v_case_key, v_taxable_finance_case_id::text)
    );
    v_case_resolution_ids := '[]'::jsonb;
    v_case_resolution_id_text := NULL;
    v_action := 'TAXABLE_CHANNEL_RESTRUCTURE_APPLIED';

  ELSIF v_resolution_family = 'BUCKETED' THEN
    IF jsonb_typeof(v_bucket_resolutions_json) <> 'array' OR jsonb_array_length(v_bucket_resolutions_json) = 0 THEN
      RAISE EXCEPTION 'bucket_resolutions must be a non-empty JSON array for BUCKETED resolution';
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS _tmp_bpay_session_bucket_resolution (
      bucket_ordinal integer PRIMARY KEY,
      timesheet_id uuid NULL,
      source_basis_json jsonb NOT NULL,
      source_basis_fingerprint text NOT NULL,
      source_family_key text NOT NULL,
      bucket_code text NULL,
      component_key_type text NOT NULL,
      component_key_value text NOT NULL,
      source_units numeric NOT NULL,
      source_rate numeric NOT NULL,
      source_charge_rate numeric NOT NULL,
      resolution_mode text NOT NULL,
      target_rate numeric NOT NULL,
      resolution_identity_key text NOT NULL,
      matched_candidate_id uuid NULL,
      anchor_evidence_key text NULL,
      decision_context_key text NULL,
      category_identity text NULL
    ) ON COMMIT DROP;

    TRUNCATE TABLE _tmp_bpay_session_bucket_resolution;

    FOR v_bucket_element IN
      SELECT bucket_item.ordinality AS bucket_ordinal, bucket_item.value AS bucket_json
      FROM jsonb_array_elements(v_bucket_resolutions_json) WITH ORDINALITY AS bucket_item(value, ordinality)
      WHERE jsonb_typeof(bucket_item.value) = 'object'
      ORDER BY bucket_item.ordinality
    LOOP
      v_bucket_source_basis_json := CASE
        WHEN jsonb_typeof(v_bucket_element.bucket_json->'source_basis_json') = 'object' THEN COALESCE(v_bucket_element.bucket_json->'source_basis_json', '{}'::jsonb)
        WHEN jsonb_typeof(v_resolution_payload_json->'source_basis_json') = 'object' THEN COALESCE(v_resolution_payload_json->'source_basis_json', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      v_bucket_source_basis_fingerprint := BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'source_basis_fingerprint',
        v_resolution_payload_json->>'source_basis_fingerprint',
        ''
      ));
      IF v_bucket_source_basis_fingerprint = '' AND v_bucket_source_basis_json <> '{}'::jsonb THEN
        v_bucket_source_basis_fingerprint := md5(v_bucket_source_basis_json::text);
      END IF;

      v_bucket_source_family_key := BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'source_family_key',
        v_resolution_payload_json->>'source_family_key',
        ''
      ));
      v_bucket_bucket_code := UPPER(BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'bucket_code',
        v_resolution_payload_json->>'bucket_code',
        ''
      )));
      v_bucket_component_key_type := UPPER(BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'component_key_type',
        v_resolution_payload_json->>'component_key_type',
        ''
      )));
      v_bucket_component_key_value := BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'component_key_value',
        v_resolution_payload_json->>'component_key_value',
        ''
      ));
      v_bucket_resolution_mode := UPPER(BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'resolution_mode',
        v_default_resolution_mode,
        ''
      )));
      v_bucket_timesheet_id_text := BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'timesheet_id',
        v_resolution_payload_json->>'linked_timesheet_id',
        v_resolution_payload_json->>'timesheet_id',
        ''
      ));
      v_bucket_timesheet_id := NULL::uuid;
      IF v_bucket_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_bucket_timesheet_id := v_bucket_timesheet_id_text::uuid;
      END IF;

      IF COALESCE(
        v_bucket_element.bucket_json->>'source_units',
        v_resolution_payload_json->>'source_units',
        ''
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'source_units is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;
      v_bucket_source_units := round(COALESCE(
        NULLIF(v_bucket_element.bucket_json->>'source_units', '')::numeric,
        NULLIF(v_resolution_payload_json->>'source_units', '')::numeric
      ), 6);

      IF COALESCE(
        v_bucket_element.bucket_json->>'source_rate',
        v_resolution_payload_json->>'source_rate',
        ''
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'source_rate is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;
      v_bucket_source_rate := round(COALESCE(
        NULLIF(v_bucket_element.bucket_json->>'source_rate', '')::numeric,
        NULLIF(v_resolution_payload_json->>'source_rate', '')::numeric
      ), 6);

      IF COALESCE(
        v_bucket_element.bucket_json->>'source_charge_rate',
        v_resolution_payload_json->>'source_charge_rate',
        ''
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'source_charge_rate is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;
      v_bucket_source_charge_rate := round(COALESCE(
        NULLIF(v_bucket_element.bucket_json->>'source_charge_rate', '')::numeric,
        NULLIF(v_resolution_payload_json->>'source_charge_rate', '')::numeric
      ), 6);

      IF COALESCE(
        v_bucket_element.bucket_json->>'target_rate',
        v_resolution_payload_json->>'target_rate',
        ''
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'target_rate is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;
      v_bucket_target_rate := round(COALESCE(
        NULLIF(v_bucket_element.bucket_json->>'target_rate', '')::numeric,
        NULLIF(v_resolution_payload_json->>'target_rate', '')::numeric
      ), 2);

      IF v_bucket_target_rate < 0 THEN
        RAISE EXCEPTION 'target_rate must be non-negative for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_resolution_mode NOT IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_REPLACEMENT_RATE') THEN
        RAISE EXCEPTION 'BUCKETED resolution_mode must be SUGGESTED_EQUIVALENT_BASIS or MANUAL_REPLACEMENT_RATE for bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_source_family_key = '' THEN
        RAISE EXCEPTION 'source_family_key is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_component_key_type = '' THEN
        RAISE EXCEPTION 'component_key_type is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_component_key_value = '' THEN
        RAISE EXCEPTION 'component_key_value is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_source_basis_fingerprint = '' THEN
        RAISE EXCEPTION 'source_basis_fingerprint or source_basis_json is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_component_key_type IN ('TS_DAY', 'TS_TOTAL') AND v_bucket_bucket_code = '' THEN
        RAISE EXCEPTION 'bucket_code is required for BUCKETED worked-time resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_component_key_type = 'TS_DAY'
         AND v_bucket_component_key_value !~ '^\d{4}-\d{2}-\d{2}$' THEN
        RAISE EXCEPTION 'Invalid TS_DAY economic key in BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_source_family_key LIKE 'correction-chain:%' THEN
        v_bucket_resolution_identity_key :=
          public._ctms_correction_carrier_identity_v1(
            v_candidate_id,
            NULLIF(
              COALESCE(
                v_bucket_element.bucket_json->>'correction_root_id',
                v_resolution_payload_json->>'correction_root_id'
              ),
              ''
            )::uuid,
            v_bucket_component_key_type,
            v_bucket_component_key_value
          );

        IF NULLIF(
          COALESCE(
            v_bucket_element.bucket_json->>'canonical_correction_key',
            v_resolution_payload_json->>'canonical_correction_key'
          ),
          ''
        ) IS DISTINCT FROM v_bucket_resolution_identity_key THEN
          RAISE EXCEPTION 'CORRECTION_CARRIER_IDENTITY_MISMATCH'
            USING ERRCODE='P0001',
                  DETAIL=jsonb_build_object(
                    'expected_identity',v_bucket_resolution_identity_key,
                    'provided_identity',COALESCE(
                      v_bucket_element.bucket_json->>'canonical_correction_key',
                      v_resolution_payload_json->>'canonical_correction_key'
                    )
                  )::text;
        END IF;
      ELSE
        v_bucket_resolution_identity_key := concat_ws(
          '|',
          'BUCKETED',
          COALESCE(NULLIF(v_case_key, ''), '~'),
          COALESCE(CASE WHEN v_bucket_timesheet_id IS NULL THEN NULL ELSE v_bucket_timesheet_id::text END, '~'),
          COALESCE(NULLIF(v_bucket_source_basis_fingerprint, ''), '~'),
          COALESCE(NULLIF(v_bucket_source_family_key, ''), '~'),
          COALESCE(NULLIF(v_bucket_bucket_code, ''), '~'),
          COALESCE(NULLIF(v_bucket_component_key_type, ''), '~'),
          COALESCE(NULLIF(v_bucket_component_key_value, ''), '~')
        );
      END IF;

      INSERT INTO _tmp_bpay_session_bucket_resolution (
        bucket_ordinal,
        timesheet_id,
        source_basis_json,
        source_basis_fingerprint,
        source_family_key,
        bucket_code,
        component_key_type,
        component_key_value,
        source_units,
        source_rate,
        source_charge_rate,
        resolution_mode,
        target_rate,
        resolution_identity_key,
        matched_candidate_id,
        anchor_evidence_key,
        decision_context_key,
        category_identity
      )
      VALUES (
        v_bucket_element.bucket_ordinal,
        v_bucket_timesheet_id,
        v_bucket_source_basis_json,
        v_bucket_source_basis_fingerprint,
        v_bucket_source_family_key,
        NULLIF(v_bucket_bucket_code, ''),
        v_bucket_component_key_type,
        v_bucket_component_key_value,
        v_bucket_source_units,
        v_bucket_source_rate,
        v_bucket_source_charge_rate,
        v_bucket_resolution_mode,
        v_bucket_target_rate,
        v_bucket_resolution_identity_key,
        NULL::uuid,
        NULL::text,
        NULL::text,
        NULL::text
      );
    END LOOP;

    SELECT COUNT(*)::integer
    INTO v_bucket_count
    FROM _tmp_bpay_session_bucket_resolution AS input_bucket;

    IF v_bucket_count = 0 THEN
      RAISE EXCEPTION 'bucket_resolutions must contain at least one JSON object for BUCKETED resolution';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM _tmp_bpay_session_bucket_resolution AS duplicate_bucket
      GROUP BY duplicate_bucket.resolution_identity_key
      HAVING COUNT(*) > 1
    ) THEN
      RAISE EXCEPTION 'Duplicate bucket resolution identity detected for case_key %', v_case_key;
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS _tmp_bpay_session_bucket_component_raw (
      evidence_key text PRIMARY KEY,
      evidence_source text NOT NULL,
      candidate_id uuid NOT NULL,
      case_key text NOT NULL,
      timesheet_id uuid NOT NULL,
      case_client_id uuid NULL,
      source_basis_json jsonb NOT NULL,
      source_basis_fingerprint text NOT NULL,
      source_family_key text NOT NULL,
      bucket_code text NULL,
      component_key_type text NOT NULL,
      component_key_value text NOT NULL,
      component_fingerprint text NULL,
      classification text NOT NULL,
      source_pay_method text NOT NULL,
      target_pay_method text NOT NULL,
      source_units numeric NOT NULL,
      source_rate numeric NOT NULL,
      source_charge_rate numeric NOT NULL,
      source_pay_ex_vat numeric NULL,
      source_charge_ex_vat numeric NULL,
      source_margin_ex_vat numeric NULL,
      suggested_target_rate numeric NULL,
      suggested_target_charge_rate numeric NULL,
      relevant_erni_pct numeric NULL,
      vat_rate_pct numeric NULL,
      umbrella_vat_chargeable boolean NULL,
      charge_basis text NULL,
      taxability_context text NULL,
      gross_net_context text NULL,
      reuse_mode text NULL,
      suggested_resolution_payload_json jsonb NOT NULL,
      suggested_resolution_result_json jsonb NOT NULL,
      requires_resolution boolean NOT NULL,
      is_actionable_resolution_row boolean NOT NULL,
      component_state_json jsonb NOT NULL
    ) ON COMMIT DROP;

    TRUNCATE TABLE _tmp_bpay_session_bucket_component_raw;

    INSERT INTO _tmp_bpay_session_bucket_component_raw (
      evidence_key,
      evidence_source,
      candidate_id,
      case_key,
      timesheet_id,
      case_client_id,
      source_basis_json,
      source_basis_fingerprint,
      source_family_key,
      bucket_code,
      component_key_type,
      component_key_value,
      component_fingerprint,
      classification,
      source_pay_method,
      target_pay_method,
      source_units,
      source_rate,
      source_charge_rate,
      source_pay_ex_vat,
      source_charge_ex_vat,
      source_margin_ex_vat,
      suggested_target_rate,
      suggested_target_charge_rate,
      relevant_erni_pct,
      vat_rate_pct,
      umbrella_vat_chargeable,
      charge_basis,
      taxability_context,
      gross_net_context,
      reuse_mode,
      suggested_resolution_payload_json,
      suggested_resolution_result_json,
      requires_resolution,
      is_actionable_resolution_row,
      component_state_json
    )
    WITH preview_source AS (
      SELECT
        preview_row.id AS preview_row_id,
        preview_row.candidate_id,
        preview_row.row_key,
        preview_row.timesheet_id AS preview_timesheet_id,
        COALESCE(preview_row.row_json, '{}'::jsonb) AS row_json,
        BTRIM(COALESCE(
          preview_row.row_json->>'case_key',
          preview_row.row_json #>> '{case_resolution_summary,case_key}',
          preview_row.row_json #>> '{case,case_key}',
          preview_row.row_json #>> '{raw_case,case_key}',
          ''
        )) AS extracted_case_key,
        BTRIM(COALESCE(
          preview_row.timesheet_id::text,
          preview_row.row_json->>'timesheet_id',
          preview_row.row_json->>'real_business_timesheet_id',
          preview_row.row_json->>'linked_timesheet_id',
          preview_row.row_json #>> '{case,timesheet_id}',
          preview_row.row_json #>> '{raw_case,timesheet_id}',
          ''
        )) AS row_timesheet_id_text,
        BTRIM(COALESCE(
          preview_row.row_json->>'client_id',
          preview_row.row_json #>> '{case,client_id}',
          preview_row.row_json #>> '{raw_case,client_id}',
          ''
        )) AS case_client_id_text,
        UPPER(BTRIM(COALESCE(
          preview_row.row_json->>'resolution_family',
          preview_row.row_json #>> '{case_resolution_summary,resolution_family}',
          preview_row.row_json #>> '{case,resolution_family}',
          preview_row.row_json #>> '{raw_case,resolution_family}',
          ''
        ))) AS resolution_family
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.session_version = COALESCE(
          (
            SELECT certified_scope.certified_preview_publication_session_version
            FROM public.banking_pay_workbench_session_scope AS certified_scope
            WHERE certified_scope.session_id = p_session_id
              AND certified_scope.candidate_id = preview_row.candidate_id
              AND certified_scope.certified_preview_publication_parity_ok IS TRUE
          ),
          COALESCE(v_session_row.version, 1)
        )
        AND (v_candidate_id IS NULL OR preview_row.candidate_id = v_candidate_id)
        AND LOWER(BTRIM(COALESCE(preview_row.section, ''))) = 'cases_resolutions'
        AND UPPER(BTRIM(COALESCE(preview_row.status, ''))) = 'READY'
        AND EXISTS (
          SELECT 1
          FROM _tmp_bpay_session_candidate_scope AS candidate_scope
          WHERE candidate_scope.candidate_id = preview_row.candidate_id
        )
    ), normalized_preview AS (
      SELECT
        preview_source.preview_row_id,
        preview_source.candidate_id,
        preview_source.row_key,
        preview_source.row_json,
        CASE
          WHEN preview_source.row_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN preview_source.row_timesheet_id_text::uuid
          ELSE NULL::uuid
        END AS row_timesheet_id,
        CASE
          WHEN preview_source.case_client_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN preview_source.case_client_id_text::uuid
          ELSE NULL::uuid
        END AS case_client_id,
        COALESCE(
          NULLIF(preview_source.extracted_case_key, ''),
          CASE
            WHEN preview_source.row_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN 'timesheet:' || preview_source.row_timesheet_id_text
            ELSE NULL::text
          END,
          ''
        ) AS case_key,
        preview_source.resolution_family
      FROM preview_source
    ), case_component_arrays AS (
      SELECT
        normalized_preview.preview_row_id,
        normalized_preview.candidate_id,
        normalized_preview.case_key,
        normalized_preview.row_timesheet_id,
        normalized_preview.case_client_id,
        normalized_preview.row_json,
        CASE
          WHEN jsonb_typeof(normalized_preview.row_json->'case_components') = 'array' THEN normalized_preview.row_json->'case_components'
          WHEN jsonb_typeof(normalized_preview.row_json->'components') = 'array' THEN normalized_preview.row_json->'components'
          WHEN jsonb_typeof(normalized_preview.row_json->'component_states') = 'array' THEN normalized_preview.row_json->'component_states'
          WHEN jsonb_typeof(normalized_preview.row_json->'component_resolution_states') = 'array' THEN normalized_preview.row_json->'component_resolution_states'
          WHEN jsonb_typeof(normalized_preview.row_json->'preview_components') = 'array' THEN normalized_preview.row_json->'preview_components'
          WHEN jsonb_typeof(normalized_preview.row_json #> '{case,case_components}') = 'array' THEN normalized_preview.row_json #> '{case,case_components}'
          WHEN jsonb_typeof(normalized_preview.row_json #> '{case,components}') = 'array' THEN normalized_preview.row_json #> '{case,components}'
          WHEN jsonb_typeof(normalized_preview.row_json #> '{raw_case,case_components}') = 'array' THEN normalized_preview.row_json #> '{raw_case,case_components}'
          WHEN jsonb_typeof(normalized_preview.row_json #> '{raw_case,components}') = 'array' THEN normalized_preview.row_json #> '{raw_case,components}'
          ELSE '[]'::jsonb
        END AS components_json
      FROM normalized_preview
      WHERE normalized_preview.case_key <> ''
        AND COALESCE(normalized_preview.resolution_family, '') IN ('', 'BUCKETED')
    ), expanded_components AS (
      SELECT
        case_component_arrays.preview_row_id,
        component_element.ordinality::integer AS component_ordinal,
        case_component_arrays.candidate_id,
        case_component_arrays.case_key,
        case_component_arrays.row_timesheet_id,
        case_component_arrays.case_client_id,
        component_element.value AS component_json
      FROM case_component_arrays
      CROSS JOIN LATERAL jsonb_array_elements(case_component_arrays.components_json) WITH ORDINALITY AS component_element(value, ordinality)
      WHERE jsonb_typeof(component_element.value) = 'object'
    ), components_with_basis AS (
      SELECT
        expanded_components.*,
        CASE
          WHEN jsonb_typeof(expanded_components.component_json->'source_basis_json') = 'object' THEN COALESCE(expanded_components.component_json->'source_basis_json', '{}'::jsonb)
          WHEN jsonb_typeof(expanded_components.component_json->'frozen_source_basis_json') = 'object' THEN COALESCE(expanded_components.component_json->'frozen_source_basis_json', '{}'::jsonb)
          WHEN jsonb_typeof(expanded_components.component_json #> '{raw,source_basis_json}') = 'object' THEN COALESCE(expanded_components.component_json #> '{raw,source_basis_json}', '{}'::jsonb)
          ELSE '{}'::jsonb
        END AS source_basis_json,
        CASE
          WHEN jsonb_typeof(expanded_components.component_json->'suggested_resolution_payload_json') = 'object' THEN COALESCE(expanded_components.component_json->'suggested_resolution_payload_json', '{}'::jsonb)
          WHEN jsonb_typeof(expanded_components.component_json #> '{raw,suggested_resolution_payload_json}') = 'object' THEN COALESCE(expanded_components.component_json #> '{raw,suggested_resolution_payload_json}', '{}'::jsonb)
          ELSE '{}'::jsonb
        END AS suggested_resolution_payload_json,
        CASE
          WHEN jsonb_typeof(expanded_components.component_json->'suggested_resolution_result_json') = 'object' THEN COALESCE(expanded_components.component_json->'suggested_resolution_result_json', '{}'::jsonb)
          WHEN jsonb_typeof(expanded_components.component_json #> '{raw,suggested_resolution_result_json}') = 'object' THEN COALESCE(expanded_components.component_json #> '{raw,suggested_resolution_result_json}', '{}'::jsonb)
          ELSE '{}'::jsonb
        END AS suggested_resolution_result_json
      FROM expanded_components
    ), normalized_components AS (
      SELECT
        components_with_basis.*,
        BTRIM(COALESCE(
          components_with_basis.row_timesheet_id::text,
          components_with_basis.component_json->>'timesheet_id',
          components_with_basis.source_basis_json->>'timesheet_id',
          components_with_basis.component_json #>> '{raw,timesheet_id}',
          components_with_basis.component_json #>> '{raw,source_basis_json,timesheet_id}',
          ''
        )) AS timesheet_id_text,
        BTRIM(COALESCE(
          components_with_basis.component_json->>'source_basis_fingerprint',
          components_with_basis.component_json #>> '{raw,source_basis_fingerprint}',
          CASE WHEN components_with_basis.source_basis_json <> '{}'::jsonb THEN md5(components_with_basis.source_basis_json::text) ELSE NULL::text END,
          ''
        )) AS source_basis_fingerprint,
        BTRIM(COALESCE(
          components_with_basis.component_json->>'source_family_key',
          components_with_basis.component_json #>> '{raw,source_family_key}',
          components_with_basis.component_json->>'frozen_source_family_key',
          ''
        )) AS source_family_key,
        UPPER(BTRIM(COALESCE(
          components_with_basis.component_json->>'bucket_code',
          components_with_basis.source_basis_json->>'bucket_code',
          components_with_basis.component_json #>> '{raw,bucket_code}',
          components_with_basis.component_json #>> '{raw,source_basis_json,bucket_code}',
          ''
        ))) AS bucket_code,
        UPPER(BTRIM(COALESCE(
          components_with_basis.component_json->>'component_key_type',
          components_with_basis.component_json->>'frozen_component_key_type',
          components_with_basis.component_json #>> '{raw,component_key_type}',
          ''
        ))) AS component_key_type,
        BTRIM(COALESCE(
          components_with_basis.component_json->>'component_key_value',
          components_with_basis.component_json->>'frozen_component_key_value',
          components_with_basis.component_json #>> '{raw,component_key_value}',
          ''
        )) AS component_key_value,
        NULLIF(BTRIM(COALESCE(
          components_with_basis.component_json->>'component_fingerprint',
          components_with_basis.component_json #>> '{raw,component_fingerprint}',
          ''
        )), '') AS component_fingerprint,
        UPPER(BTRIM(COALESCE(
          components_with_basis.component_json->>'classification',
          components_with_basis.component_json->>'frozen_component_classification',
          components_with_basis.component_json #>> '{raw,classification}',
          ''
        ))) AS classification,
        UPPER(BTRIM(COALESCE(
          components_with_basis.component_json->>'source_pay_method',
          components_with_basis.source_basis_json->>'source_pay_method',
          components_with_basis.component_json #>> '{raw,source_pay_method}',
          ''
        ))) AS source_pay_method,
        UPPER(BTRIM(COALESCE(
          components_with_basis.component_json->>'current_target_pay_method',
          components_with_basis.component_json->>'target_pay_method',
          components_with_basis.suggested_resolution_payload_json->>'target_pay_method',
          components_with_basis.suggested_resolution_result_json->>'target_pay_method',
          components_with_basis.component_json #>> '{raw,current_target_pay_method}',
          components_with_basis.component_json #>> '{raw,target_pay_method}',
          ''
        ))) AS target_pay_method,
        COALESCE(
          components_with_basis.component_json->>'source_units',
          components_with_basis.source_basis_json->>'source_units',
          components_with_basis.component_json #>> '{raw,source_units}',
          ''
        ) AS source_units_text,
        COALESCE(
          components_with_basis.component_json->>'source_rate',
          components_with_basis.source_basis_json->>'source_rate',
          components_with_basis.component_json #>> '{raw,source_rate}',
          ''
        ) AS source_rate_text,
        COALESCE(
          components_with_basis.component_json->>'source_charge_rate',
          components_with_basis.source_basis_json->>'source_charge_rate',
          components_with_basis.component_json #>> '{raw,source_charge_rate}',
          ''
        ) AS source_charge_rate_text,
        COALESCE(
          components_with_basis.component_json->>'source_pay_ex_vat',
          components_with_basis.component_json->>'component_amount_ex_vat',
          components_with_basis.component_json #>> '{raw,source_pay_ex_vat}',
          ''
        ) AS source_pay_ex_vat_text,
        COALESCE(
          components_with_basis.component_json->>'source_charge_ex_vat',
          components_with_basis.component_json #>> '{raw,source_charge_ex_vat}',
          ''
        ) AS source_charge_ex_vat_text,
        COALESCE(
          components_with_basis.component_json->>'source_margin_ex_vat',
          components_with_basis.component_json #>> '{raw,source_margin_ex_vat}',
          ''
        ) AS source_margin_ex_vat_text,
        COALESCE(
          components_with_basis.suggested_resolution_payload_json->>'suggested_target_rate',
          components_with_basis.suggested_resolution_result_json->>'replacement_rate',
          components_with_basis.component_json->>'target_rate',
          components_with_basis.component_json #>> '{raw,target_rate}',
          ''
        ) AS suggested_target_rate_text,
        COALESCE(
          components_with_basis.suggested_resolution_result_json->>'target_charge_rate',
          components_with_basis.suggested_resolution_payload_json->>'target_charge_rate',
          components_with_basis.component_json->>'target_charge_rate',
          ''
        ) AS suggested_target_charge_rate_text,
        COALESCE(
          components_with_basis.suggested_resolution_payload_json->>'relevant_erni_pct',
          components_with_basis.suggested_resolution_result_json->>'relevant_erni_pct',
          ''
        ) AS relevant_erni_pct_text,
        COALESCE(
          components_with_basis.suggested_resolution_payload_json->>'vat_rate_pct',
          components_with_basis.suggested_resolution_result_json->>'vat_rate_pct',
          ''
        ) AS vat_rate_pct_text,
        COALESCE(
          components_with_basis.suggested_resolution_payload_json->>'umbrella_vat_chargeable',
          components_with_basis.suggested_resolution_result_json->>'umbrella_vat_chargeable',
          components_with_basis.component_json->>'umbrella_vat_chargeable',
          ''
        ) AS umbrella_vat_chargeable_text,
        NULLIF(BTRIM(COALESCE(
          components_with_basis.suggested_resolution_payload_json->>'target_charge_basis',
          components_with_basis.suggested_resolution_result_json->>'target_charge_basis',
          components_with_basis.suggested_resolution_payload_json->>'charge_basis',
          components_with_basis.suggested_resolution_result_json->>'charge_basis',
          ''
        )), '') AS charge_basis,
        NULLIF(UPPER(BTRIM(COALESCE(
          components_with_basis.component_json->>'taxability',
          components_with_basis.source_basis_json->>'taxability',
          components_with_basis.component_json #>> '{raw,taxability}',
          ''
        ))), '') AS taxability_context,
        NULLIF(UPPER(BTRIM(COALESCE(
          components_with_basis.component_json->>'gross_net_handling',
          components_with_basis.source_basis_json->>'gross_net_handling',
          components_with_basis.component_json #>> '{raw,gross_net_handling}',
          ''
        ))), '') AS gross_net_context,
        NULLIF(UPPER(BTRIM(COALESCE(
          components_with_basis.suggested_resolution_payload_json->>'reuse_mode',
          components_with_basis.suggested_resolution_result_json->>'reuse_mode',
          ''
        ))), '') AS reuse_mode,
        LOWER(BTRIM(COALESCE(components_with_basis.component_json->>'requires_resolution', ''))) AS requires_resolution_text,
        LOWER(BTRIM(COALESCE(components_with_basis.component_json->>'is_actionable_resolution_row', ''))) AS is_actionable_resolution_row_text
      FROM components_with_basis
    ), typed_components AS (
      SELECT
        normalized_components.*,
        CASE
          WHEN normalized_components.timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN normalized_components.timesheet_id_text::uuid
          ELSE NULL::uuid
        END AS timesheet_id,
        CASE WHEN normalized_components.source_units_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.source_units_text::numeric, 6) ELSE NULL::numeric END AS source_units,
        CASE WHEN normalized_components.source_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.source_rate_text::numeric, 6) ELSE NULL::numeric END AS source_rate,
        CASE WHEN normalized_components.source_charge_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.source_charge_rate_text::numeric, 6) ELSE NULL::numeric END AS source_charge_rate,
        CASE WHEN normalized_components.source_pay_ex_vat_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.source_pay_ex_vat_text::numeric, 2) ELSE NULL::numeric END AS source_pay_ex_vat,
        CASE WHEN normalized_components.source_charge_ex_vat_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.source_charge_ex_vat_text::numeric, 2) ELSE NULL::numeric END AS source_charge_ex_vat,
        CASE WHEN normalized_components.source_margin_ex_vat_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.source_margin_ex_vat_text::numeric, 2) ELSE NULL::numeric END AS source_margin_ex_vat,
        CASE WHEN normalized_components.suggested_target_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.suggested_target_rate_text::numeric, 2) ELSE NULL::numeric END AS suggested_target_rate,
        CASE WHEN normalized_components.suggested_target_charge_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.suggested_target_charge_rate_text::numeric, 6) ELSE NULL::numeric END AS suggested_target_charge_rate,
        CASE WHEN normalized_components.relevant_erni_pct_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.relevant_erni_pct_text::numeric, 6) ELSE NULL::numeric END AS relevant_erni_pct,
        CASE WHEN normalized_components.vat_rate_pct_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_components.vat_rate_pct_text::numeric, 6) ELSE NULL::numeric END AS vat_rate_pct,
        CASE
          WHEN normalized_components.umbrella_vat_chargeable_text = '' THEN NULL::boolean
          WHEN LOWER(normalized_components.umbrella_vat_chargeable_text) IN ('true', 't', '1', 'yes', 'y', 'on') THEN true
          ELSE false
        END AS umbrella_vat_chargeable,
        CASE
          WHEN normalized_components.requires_resolution_text = '' THEN (
            normalized_components.classification = 'TAXABLE_CHANNEL_SENSITIVE'
            AND normalized_components.source_pay_method <> ''
            AND normalized_components.target_pay_method <> ''
            AND normalized_components.source_pay_method IS DISTINCT FROM normalized_components.target_pay_method
          )
          ELSE normalized_components.requires_resolution_text IN ('true', 't', '1', 'yes', 'y', 'on')
        END AS requires_resolution,
        CASE
          WHEN normalized_components.is_actionable_resolution_row_text = '' THEN (
            normalized_components.source_units_text ~ '^-?[0-9]+(\.[0-9]+)?$'
            AND normalized_components.source_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$'
            AND normalized_components.source_charge_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$'
            AND normalized_components.component_key_type <> 'ADJUSTMENT_CODE'
          )
          ELSE normalized_components.is_actionable_resolution_row_text IN ('true', 't', '1', 'yes', 'y', 'on')
        END AS is_actionable_resolution_row
      FROM normalized_components
    )
    SELECT
      'ROW|' || typed_components.preview_row_id::text || '|' || typed_components.component_ordinal::text,
      'ROW_BACKED',
      typed_components.candidate_id,
      COALESCE(NULLIF(typed_components.case_key, ''), 'timesheet:' || typed_components.timesheet_id::text),
      typed_components.timesheet_id,
      typed_components.case_client_id,
      typed_components.source_basis_json,
      typed_components.source_basis_fingerprint,
      typed_components.source_family_key,
      NULLIF(typed_components.bucket_code, ''),
      typed_components.component_key_type,
      typed_components.component_key_value,
      typed_components.component_fingerprint,
      typed_components.classification,
      typed_components.source_pay_method,
      typed_components.target_pay_method,
      typed_components.source_units,
      typed_components.source_rate,
      typed_components.source_charge_rate,
      typed_components.source_pay_ex_vat,
      typed_components.source_charge_ex_vat,
      typed_components.source_margin_ex_vat,
      typed_components.suggested_target_rate,
      typed_components.suggested_target_charge_rate,
      typed_components.relevant_erni_pct,
      typed_components.vat_rate_pct,
      typed_components.umbrella_vat_chargeable,
      typed_components.charge_basis,
      typed_components.taxability_context,
      typed_components.gross_net_context,
      typed_components.reuse_mode,
      typed_components.suggested_resolution_payload_json,
      typed_components.suggested_resolution_result_json,
      typed_components.requires_resolution,
      typed_components.is_actionable_resolution_row,
      typed_components.component_json
    FROM typed_components
    WHERE typed_components.timesheet_id IS NOT NULL
      AND typed_components.source_basis_fingerprint <> ''
      AND typed_components.source_family_key <> ''
      AND typed_components.component_key_type <> ''
      AND typed_components.component_key_value <> ''
      AND typed_components.source_units IS NOT NULL
      AND typed_components.source_rate IS NOT NULL
      AND typed_components.source_charge_rate IS NOT NULL
    ON CONFLICT (evidence_key) DO NOTHING;

    SELECT COUNT(*)::integer
    INTO v_row_backed_component_count
    FROM _tmp_bpay_session_bucket_component_raw AS raw_component
    WHERE raw_component.evidence_source = 'ROW_BACKED'
      AND raw_component.case_key = v_case_key
      AND (v_candidate_id IS NULL OR raw_component.candidate_id = v_candidate_id)
      AND (v_linked_timesheet_id IS NULL OR raw_component.timesheet_id = v_linked_timesheet_id);

    IF v_row_backed_component_count = 0 THEN
      TRUNCATE TABLE _tmp_bpay_session_bucket_component_raw;

      INSERT INTO _tmp_bpay_session_bucket_component_raw (
        evidence_key,
        evidence_source,
        candidate_id,
        case_key,
        timesheet_id,
        case_client_id,
        source_basis_json,
        source_basis_fingerprint,
        source_family_key,
        bucket_code,
        component_key_type,
        component_key_value,
        component_fingerprint,
        classification,
        source_pay_method,
        target_pay_method,
        source_units,
        source_rate,
        source_charge_rate,
        source_pay_ex_vat,
        source_charge_ex_vat,
        source_margin_ex_vat,
        suggested_target_rate,
        suggested_target_charge_rate,
        relevant_erni_pct,
        vat_rate_pct,
        umbrella_vat_chargeable,
        charge_basis,
        taxability_context,
        gross_net_context,
        reuse_mode,
        suggested_resolution_payload_json,
        suggested_resolution_result_json,
        requires_resolution,
        is_actionable_resolution_row,
        component_state_json
      )
      WITH snapshot_source AS (
        SELECT
          snapshot_component.id AS snapshot_component_id,
          snapshot_component.candidate_id,
          snapshot_component.case_key,
          snapshot_component.timesheet_id,
          COALESCE(snapshot_component.component_state_json, '{}'::jsonb) AS component_json,
          CASE
            WHEN jsonb_typeof(snapshot_component.component_state_json->'source_basis_json') = 'object' THEN COALESCE(snapshot_component.component_state_json->'source_basis_json', '{}'::jsonb)
            WHEN jsonb_typeof(snapshot_component.component_state_json->'frozen_source_basis_json') = 'object' THEN COALESCE(snapshot_component.component_state_json->'frozen_source_basis_json', '{}'::jsonb)
            WHEN jsonb_typeof(snapshot_component.component_state_json #> '{raw,source_basis_json}') = 'object' THEN COALESCE(snapshot_component.component_state_json #> '{raw,source_basis_json}', '{}'::jsonb)
            ELSE '{}'::jsonb
          END AS source_basis_json,
          CASE
            WHEN jsonb_typeof(snapshot_component.component_state_json->'suggested_resolution_payload_json') = 'object' THEN COALESCE(snapshot_component.component_state_json->'suggested_resolution_payload_json', '{}'::jsonb)
            WHEN jsonb_typeof(snapshot_component.component_state_json #> '{raw,suggested_resolution_payload_json}') = 'object' THEN COALESCE(snapshot_component.component_state_json #> '{raw,suggested_resolution_payload_json}', '{}'::jsonb)
            ELSE '{}'::jsonb
          END AS suggested_resolution_payload_json,
          CASE
            WHEN jsonb_typeof(snapshot_component.component_state_json->'suggested_resolution_result_json') = 'object' THEN COALESCE(snapshot_component.component_state_json->'suggested_resolution_result_json', '{}'::jsonb)
            WHEN jsonb_typeof(snapshot_component.component_state_json #> '{raw,suggested_resolution_result_json}') = 'object' THEN COALESCE(snapshot_component.component_state_json #> '{raw,suggested_resolution_result_json}', '{}'::jsonb)
            ELSE '{}'::jsonb
          END AS suggested_resolution_result_json,
          snapshot_component.source_basis_fingerprint,
          snapshot_component.source_family_key,
          snapshot_component.bucket_code,
          snapshot_component.component_key_type,
          snapshot_component.component_key_value,
          snapshot_component.component_fingerprint
        FROM public.banking_pay_snapshot_case_component_state AS snapshot_component
        WHERE snapshot_component.snapshot_run_id = v_session_row.source_snapshot_run_id
          AND EXISTS (
            SELECT 1
            FROM _tmp_bpay_session_candidate_scope AS candidate_scope
            WHERE candidate_scope.candidate_id = snapshot_component.candidate_id
          )
      ), normalized_snapshot AS (
        SELECT
          snapshot_source.*,
          BTRIM(COALESCE(
            snapshot_source.source_basis_fingerprint,
            snapshot_source.component_json->>'source_basis_fingerprint',
            snapshot_source.component_json #>> '{raw,source_basis_fingerprint}',
            CASE WHEN snapshot_source.source_basis_json <> '{}'::jsonb THEN md5(snapshot_source.source_basis_json::text) ELSE NULL::text END,
            ''
          )) AS normalized_source_basis_fingerprint,
          BTRIM(COALESCE(
            snapshot_source.source_family_key,
            snapshot_source.component_json->>'source_family_key',
            snapshot_source.component_json #>> '{raw,source_family_key}',
            CASE WHEN snapshot_source.timesheet_id IS NULL THEN NULL ELSE 'timesheet:' || snapshot_source.timesheet_id::text END,
            ''
          )) AS normalized_source_family_key,
          UPPER(BTRIM(COALESCE(
            snapshot_source.bucket_code,
            snapshot_source.component_json->>'bucket_code',
            snapshot_source.source_basis_json->>'bucket_code',
            snapshot_source.component_json #>> '{raw,bucket_code}',
            ''
          ))) AS normalized_bucket_code,
          UPPER(BTRIM(COALESCE(
            snapshot_source.component_key_type,
            snapshot_source.component_json->>'component_key_type',
            snapshot_source.component_json->>'frozen_component_key_type',
            snapshot_source.component_json #>> '{raw,component_key_type}',
            ''
          ))) AS normalized_component_key_type,
          BTRIM(COALESCE(
            snapshot_source.component_key_value,
            snapshot_source.component_json->>'component_key_value',
            snapshot_source.component_json->>'frozen_component_key_value',
            snapshot_source.component_json #>> '{raw,component_key_value}',
            ''
          )) AS normalized_component_key_value,
          NULLIF(BTRIM(COALESCE(
            snapshot_source.component_fingerprint,
            snapshot_source.component_json->>'component_fingerprint',
            snapshot_source.component_json #>> '{raw,component_fingerprint}',
            ''
          )), '') AS normalized_component_fingerprint,
          UPPER(BTRIM(COALESCE(
            snapshot_source.component_json->>'classification',
            snapshot_source.component_json->>'frozen_component_classification',
            snapshot_source.component_json #>> '{raw,classification}',
            ''
          ))) AS classification,
          UPPER(BTRIM(COALESCE(
            snapshot_source.component_json->>'source_pay_method',
            snapshot_source.source_basis_json->>'source_pay_method',
            snapshot_source.component_json #>> '{raw,source_pay_method}',
            ''
          ))) AS source_pay_method,
          UPPER(BTRIM(COALESCE(
            snapshot_source.component_json->>'current_target_pay_method',
            snapshot_source.component_json->>'target_pay_method',
            snapshot_source.suggested_resolution_payload_json->>'target_pay_method',
            snapshot_source.suggested_resolution_result_json->>'target_pay_method',
            snapshot_source.component_json #>> '{raw,current_target_pay_method}',
            snapshot_source.component_json #>> '{raw,target_pay_method}',
            ''
          ))) AS target_pay_method,
          COALESCE(snapshot_source.component_json->>'source_units', snapshot_source.source_basis_json->>'source_units', snapshot_source.component_json #>> '{raw,source_units}', '') AS source_units_text,
          COALESCE(snapshot_source.component_json->>'source_rate', snapshot_source.source_basis_json->>'source_rate', snapshot_source.component_json #>> '{raw,source_rate}', '') AS source_rate_text,
          COALESCE(snapshot_source.component_json->>'source_charge_rate', snapshot_source.source_basis_json->>'source_charge_rate', snapshot_source.component_json #>> '{raw,source_charge_rate}', '') AS source_charge_rate_text,
          COALESCE(snapshot_source.component_json->>'source_pay_ex_vat', snapshot_source.component_json->>'component_amount_ex_vat', snapshot_source.component_json #>> '{raw,source_pay_ex_vat}', '') AS source_pay_ex_vat_text,
          COALESCE(snapshot_source.component_json->>'source_charge_ex_vat', snapshot_source.component_json #>> '{raw,source_charge_ex_vat}', '') AS source_charge_ex_vat_text,
          COALESCE(snapshot_source.component_json->>'source_margin_ex_vat', snapshot_source.component_json #>> '{raw,source_margin_ex_vat}', '') AS source_margin_ex_vat_text,
          COALESCE(snapshot_source.suggested_resolution_payload_json->>'suggested_target_rate', snapshot_source.suggested_resolution_result_json->>'replacement_rate', snapshot_source.component_json->>'target_rate', '') AS suggested_target_rate_text,
          COALESCE(snapshot_source.suggested_resolution_result_json->>'target_charge_rate', snapshot_source.suggested_resolution_payload_json->>'target_charge_rate', snapshot_source.component_json->>'target_charge_rate', '') AS suggested_target_charge_rate_text,
          COALESCE(snapshot_source.suggested_resolution_payload_json->>'relevant_erni_pct', snapshot_source.suggested_resolution_result_json->>'relevant_erni_pct', '') AS relevant_erni_pct_text,
          COALESCE(snapshot_source.suggested_resolution_payload_json->>'vat_rate_pct', snapshot_source.suggested_resolution_result_json->>'vat_rate_pct', '') AS vat_rate_pct_text,
          COALESCE(snapshot_source.suggested_resolution_payload_json->>'umbrella_vat_chargeable', snapshot_source.suggested_resolution_result_json->>'umbrella_vat_chargeable', snapshot_source.component_json->>'umbrella_vat_chargeable', '') AS umbrella_vat_chargeable_text,
          NULLIF(BTRIM(COALESCE(snapshot_source.suggested_resolution_payload_json->>'target_charge_basis', snapshot_source.suggested_resolution_result_json->>'target_charge_basis', snapshot_source.suggested_resolution_payload_json->>'charge_basis', snapshot_source.suggested_resolution_result_json->>'charge_basis', '')), '') AS charge_basis,
          NULLIF(UPPER(BTRIM(COALESCE(snapshot_source.component_json->>'taxability', snapshot_source.source_basis_json->>'taxability', snapshot_source.component_json #>> '{raw,taxability}', ''))), '') AS taxability_context,
          NULLIF(UPPER(BTRIM(COALESCE(snapshot_source.component_json->>'gross_net_handling', snapshot_source.source_basis_json->>'gross_net_handling', snapshot_source.component_json #>> '{raw,gross_net_handling}', ''))), '') AS gross_net_context,
          NULLIF(UPPER(BTRIM(COALESCE(snapshot_source.suggested_resolution_payload_json->>'reuse_mode', snapshot_source.suggested_resolution_result_json->>'reuse_mode', ''))), '') AS reuse_mode,
          LOWER(BTRIM(COALESCE(snapshot_source.component_json->>'requires_resolution', ''))) AS requires_resolution_text,
          LOWER(BTRIM(COALESCE(snapshot_source.component_json->>'is_actionable_resolution_row', ''))) AS is_actionable_resolution_row_text,
          BTRIM(COALESCE(snapshot_source.component_json->>'client_id', snapshot_source.source_basis_json->>'client_id', snapshot_source.component_json #>> '{raw,client_id}', '')) AS case_client_id_text
        FROM snapshot_source
      ), typed_snapshot AS (
        SELECT
          normalized_snapshot.*,
          CASE WHEN normalized_snapshot.case_client_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN normalized_snapshot.case_client_id_text::uuid ELSE NULL::uuid END AS case_client_id,
          CASE WHEN normalized_snapshot.source_units_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.source_units_text::numeric, 6) ELSE NULL::numeric END AS source_units,
          CASE WHEN normalized_snapshot.source_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.source_rate_text::numeric, 6) ELSE NULL::numeric END AS source_rate,
          CASE WHEN normalized_snapshot.source_charge_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.source_charge_rate_text::numeric, 6) ELSE NULL::numeric END AS source_charge_rate,
          CASE WHEN normalized_snapshot.source_pay_ex_vat_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.source_pay_ex_vat_text::numeric, 2) ELSE NULL::numeric END AS source_pay_ex_vat,
          CASE WHEN normalized_snapshot.source_charge_ex_vat_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.source_charge_ex_vat_text::numeric, 2) ELSE NULL::numeric END AS source_charge_ex_vat,
          CASE WHEN normalized_snapshot.source_margin_ex_vat_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.source_margin_ex_vat_text::numeric, 2) ELSE NULL::numeric END AS source_margin_ex_vat,
          CASE WHEN normalized_snapshot.suggested_target_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.suggested_target_rate_text::numeric, 2) ELSE NULL::numeric END AS suggested_target_rate,
          CASE WHEN normalized_snapshot.suggested_target_charge_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.suggested_target_charge_rate_text::numeric, 6) ELSE NULL::numeric END AS suggested_target_charge_rate,
          CASE WHEN normalized_snapshot.relevant_erni_pct_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.relevant_erni_pct_text::numeric, 6) ELSE NULL::numeric END AS relevant_erni_pct,
          CASE WHEN normalized_snapshot.vat_rate_pct_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN round(normalized_snapshot.vat_rate_pct_text::numeric, 6) ELSE NULL::numeric END AS vat_rate_pct,
          CASE WHEN normalized_snapshot.umbrella_vat_chargeable_text = '' THEN NULL::boolean WHEN LOWER(normalized_snapshot.umbrella_vat_chargeable_text) IN ('true', 't', '1', 'yes', 'y', 'on') THEN true ELSE false END AS umbrella_vat_chargeable,
          CASE
            WHEN normalized_snapshot.requires_resolution_text = '' THEN (
              normalized_snapshot.classification = 'TAXABLE_CHANNEL_SENSITIVE'
              AND normalized_snapshot.source_pay_method <> ''
              AND normalized_snapshot.target_pay_method <> ''
              AND normalized_snapshot.source_pay_method IS DISTINCT FROM normalized_snapshot.target_pay_method
            )
            ELSE normalized_snapshot.requires_resolution_text IN ('true', 't', '1', 'yes', 'y', 'on')
          END AS requires_resolution,
          CASE
            WHEN normalized_snapshot.is_actionable_resolution_row_text = '' THEN (
              normalized_snapshot.source_units_text ~ '^-?[0-9]+(\.[0-9]+)?$'
              AND normalized_snapshot.source_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$'
              AND normalized_snapshot.source_charge_rate_text ~ '^-?[0-9]+(\.[0-9]+)?$'
              AND normalized_snapshot.normalized_component_key_type <> 'ADJUSTMENT_CODE'
            )
            ELSE normalized_snapshot.is_actionable_resolution_row_text IN ('true', 't', '1', 'yes', 'y', 'on')
          END AS is_actionable_resolution_row
        FROM normalized_snapshot
      )
      SELECT
        'SNAPSHOT|' || typed_snapshot.snapshot_component_id::text,
        'SNAPSHOT',
        typed_snapshot.candidate_id,
        typed_snapshot.case_key,
        typed_snapshot.timesheet_id,
        typed_snapshot.case_client_id,
        typed_snapshot.source_basis_json,
        typed_snapshot.normalized_source_basis_fingerprint,
        typed_snapshot.normalized_source_family_key,
        NULLIF(typed_snapshot.normalized_bucket_code, ''),
        typed_snapshot.normalized_component_key_type,
        typed_snapshot.normalized_component_key_value,
        typed_snapshot.normalized_component_fingerprint,
        typed_snapshot.classification,
        typed_snapshot.source_pay_method,
        typed_snapshot.target_pay_method,
        typed_snapshot.source_units,
        typed_snapshot.source_rate,
        typed_snapshot.source_charge_rate,
        typed_snapshot.source_pay_ex_vat,
        typed_snapshot.source_charge_ex_vat,
        typed_snapshot.source_margin_ex_vat,
        typed_snapshot.suggested_target_rate,
        typed_snapshot.suggested_target_charge_rate,
        typed_snapshot.relevant_erni_pct,
        typed_snapshot.vat_rate_pct,
        typed_snapshot.umbrella_vat_chargeable,
        typed_snapshot.charge_basis,
        typed_snapshot.taxability_context,
        typed_snapshot.gross_net_context,
        typed_snapshot.reuse_mode,
        typed_snapshot.suggested_resolution_payload_json,
        typed_snapshot.suggested_resolution_result_json,
        typed_snapshot.requires_resolution,
        typed_snapshot.is_actionable_resolution_row,
        typed_snapshot.component_json
      FROM typed_snapshot
      WHERE typed_snapshot.timesheet_id IS NOT NULL
        AND typed_snapshot.case_key <> ''
        AND typed_snapshot.normalized_source_basis_fingerprint <> ''
        AND typed_snapshot.normalized_source_family_key <> ''
        AND typed_snapshot.normalized_component_key_type <> ''
        AND typed_snapshot.normalized_component_key_value <> ''
        AND typed_snapshot.source_units IS NOT NULL
        AND typed_snapshot.source_rate IS NOT NULL
        AND typed_snapshot.source_charge_rate IS NOT NULL
      ON CONFLICT (evidence_key) DO NOTHING;
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS _tmp_bpay_session_bucket_component_evidence (
      evidence_key text PRIMARY KEY,
      evidence_source text NOT NULL,
      candidate_id uuid NOT NULL,
      case_key text NOT NULL,
      timesheet_id uuid NOT NULL,
      contract_id uuid NULL,
      client_id uuid NULL,
      source_basis_json jsonb NOT NULL,
      source_basis_fingerprint text NOT NULL,
      source_family_key text NOT NULL,
      bucket_code text NULL,
      component_key_type text NOT NULL,
      component_key_value text NOT NULL,
      component_fingerprint text NULL,
      classification text NOT NULL,
      source_pay_method text NOT NULL,
      target_pay_method text NOT NULL,
      source_units numeric NOT NULL,
      source_rate numeric NOT NULL,
      source_charge_rate numeric NOT NULL,
      source_pay_ex_vat numeric NOT NULL,
      source_charge_ex_vat numeric NOT NULL,
      source_margin_ex_vat numeric NOT NULL,
      suggested_target_rate numeric NULL,
      suggested_target_charge_rate numeric NOT NULL,
      category_identity text NOT NULL,
      resolution_context_json jsonb NOT NULL,
      decision_context_key text NOT NULL,
      suggested_resolution_payload_json jsonb NOT NULL,
      suggested_resolution_result_json jsonb NOT NULL,
      requires_resolution boolean NOT NULL,
      is_actionable_resolution_row boolean NOT NULL,
      component_state_json jsonb NOT NULL
    ) ON COMMIT DROP;

    TRUNCATE TABLE _tmp_bpay_session_bucket_component_evidence;

    INSERT INTO _tmp_bpay_session_bucket_component_evidence (
      evidence_key,
      evidence_source,
      candidate_id,
      case_key,
      timesheet_id,
      contract_id,
      client_id,
      source_basis_json,
      source_basis_fingerprint,
      source_family_key,
      bucket_code,
      component_key_type,
      component_key_value,
      component_fingerprint,
      classification,
      source_pay_method,
      target_pay_method,
      source_units,
      source_rate,
      source_charge_rate,
      source_pay_ex_vat,
      source_charge_ex_vat,
      source_margin_ex_vat,
      suggested_target_rate,
      suggested_target_charge_rate,
      category_identity,
      resolution_context_json,
      decision_context_key,
      suggested_resolution_payload_json,
      suggested_resolution_result_json,
      requires_resolution,
      is_actionable_resolution_row,
      component_state_json
    )
    WITH enriched_raw AS (
      SELECT
        raw_component.*,
        timesheet_row.contract_id,
        COALESCE(current_financial.client_id, raw_component.case_client_id) AS trusted_client_id,
        COALESCE(raw_component.source_pay_ex_vat, round(raw_component.source_units * raw_component.source_rate, 2)) AS effective_source_pay_ex_vat,
        COALESCE(raw_component.source_charge_ex_vat, round(raw_component.source_units * raw_component.source_charge_rate, 2)) AS effective_source_charge_ex_vat
      FROM _tmp_bpay_session_bucket_component_raw AS raw_component
      LEFT JOIN public.timesheets AS timesheet_row
        ON timesheet_row.timesheet_id = raw_component.timesheet_id
      LEFT JOIN LATERAL (
        SELECT
          financial_row.candidate_id,
          financial_row.client_id
        FROM public.timesheets_financials AS financial_row
        WHERE financial_row.timesheet_id = raw_component.timesheet_id
          AND financial_row.is_current = true
        ORDER BY financial_row.timesheet_version DESC, financial_row.updated_at DESC, financial_row.id DESC
        LIMIT 1
      ) AS current_financial ON true
      WHERE current_financial.candidate_id IS NULL
         OR current_financial.candidate_id = raw_component.candidate_id
    ), categorized_raw AS (
      SELECT
        enriched_raw.*,
        COALESCE(
          enriched_raw.source_margin_ex_vat,
          round(enriched_raw.effective_source_charge_ex_vat - enriched_raw.effective_source_pay_ex_vat, 2)
        ) AS effective_source_margin_ex_vat,
        COALESCE(enriched_raw.suggested_target_charge_rate, enriched_raw.source_charge_rate) AS effective_suggested_target_charge_rate,
        CASE
          WHEN enriched_raw.component_key_type IN ('TS_DAY', 'TS_TOTAL') THEN concat_ws(
            '|',
            'WORKED_TIME',
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.bucket_code, ''))), ''), '~')
          )
          WHEN enriched_raw.component_key_type IN ('ADDITIONAL_CODE', 'ADDITIONAL_UNIT', 'ADDITIONAL_UNITS', 'PAY_CODE') THEN concat_ws(
            '|',
            enriched_raw.component_key_type,
            COALESCE(NULLIF(UPPER(BTRIM(enriched_raw.component_key_value)), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'additional_code', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'additional_unit_code', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'pay_code', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'additional_unit_name', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'additional_unit_description', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'additional_name', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'additional_description', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'additional_code_name', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'additional_code_description', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'pay_code_name', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'pay_code_description', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'name', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'description', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.component_state_json->>'label', ''))), ''), '~')
          )
          ELSE concat_ws(
            '|',
            COALESCE(NULLIF(enriched_raw.component_key_type, ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(enriched_raw.component_key_value)), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.bucket_code, ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'code', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'name', ''))), ''), '~'),
            COALESCE(NULLIF(UPPER(BTRIM(COALESCE(enriched_raw.source_basis_json->>'description', ''))), ''), '~')
          )
        END AS category_identity
      FROM enriched_raw
    ), contextualized_raw AS (
      SELECT
        categorized_raw.*,
        jsonb_strip_nulls(
          jsonb_build_object(
            'resolution_family', 'BUCKETED',
            'classification', NULLIF(categorized_raw.classification, ''),
            'component_semantics', NULLIF(categorized_raw.component_key_type, ''),
            'category_identity', categorized_raw.category_identity,
            'source_pay_method', NULLIF(categorized_raw.source_pay_method, ''),
            'target_pay_method', NULLIF(categorized_raw.target_pay_method, ''),
            'source_rate', round(categorized_raw.source_rate, 6),
            'source_charge_rate', round(categorized_raw.source_charge_rate, 6)
          )
          || jsonb_build_object(
            'suggested_target_charge_rate', categorized_raw.effective_suggested_target_charge_rate,
            'relevant_erni_pct', categorized_raw.relevant_erni_pct,
            'vat_rate_pct', categorized_raw.vat_rate_pct,
            'umbrella_vat_chargeable', categorized_raw.umbrella_vat_chargeable,
            'charge_basis', COALESCE(NULLIF(UPPER(BTRIM(COALESCE(categorized_raw.charge_basis, ''))), ''), 'FIXED_SOURCE_CHARGE'),
            'taxability_context', categorized_raw.taxability_context,
            'gross_net_context', categorized_raw.gross_net_context,
            'reuse_mode', categorized_raw.reuse_mode
          )
        ) AS resolution_context_json
      FROM categorized_raw
    )
    SELECT
      contextualized_raw.evidence_key,
      contextualized_raw.evidence_source,
      contextualized_raw.candidate_id,
      contextualized_raw.case_key,
      contextualized_raw.timesheet_id,
      contextualized_raw.contract_id,
      contextualized_raw.trusted_client_id,
      contextualized_raw.source_basis_json,
      contextualized_raw.source_basis_fingerprint,
      contextualized_raw.source_family_key,
      contextualized_raw.bucket_code,
      contextualized_raw.component_key_type,
      contextualized_raw.component_key_value,
      contextualized_raw.component_fingerprint,
      contextualized_raw.classification,
      contextualized_raw.source_pay_method,
      contextualized_raw.target_pay_method,
      contextualized_raw.source_units,
      contextualized_raw.source_rate,
      contextualized_raw.source_charge_rate,
      contextualized_raw.effective_source_pay_ex_vat,
      contextualized_raw.effective_source_charge_ex_vat,
      contextualized_raw.effective_source_margin_ex_vat,
      contextualized_raw.suggested_target_rate,
      contextualized_raw.effective_suggested_target_charge_rate,
      contextualized_raw.category_identity,
      contextualized_raw.resolution_context_json,
      md5(contextualized_raw.resolution_context_json::text),
      contextualized_raw.suggested_resolution_payload_json,
      contextualized_raw.suggested_resolution_result_json,
      contextualized_raw.requires_resolution,
      contextualized_raw.is_actionable_resolution_row,
      contextualized_raw.component_state_json
    FROM contextualized_raw;

    FOR v_bucket_row IN
      SELECT input_bucket.*
      FROM _tmp_bpay_session_bucket_resolution AS input_bucket
      ORDER BY input_bucket.bucket_ordinal
    LOOP
      SELECT
        COUNT(*)::integer,
        (array_agg(component_evidence.evidence_key ORDER BY component_evidence.evidence_key))[1],
        (array_agg(component_evidence.candidate_id ORDER BY component_evidence.candidate_id))[1]
      INTO
        v_target_match_count,
        v_anchor_evidence_key,
        v_bucket_matched_candidate_id
      FROM _tmp_bpay_session_bucket_component_evidence AS component_evidence
      WHERE component_evidence.case_key = v_case_key
        AND (v_candidate_id IS NULL OR component_evidence.candidate_id = v_candidate_id)
        AND (
          v_bucket_row.timesheet_id IS NULL
          OR component_evidence.timesheet_id = v_bucket_row.timesheet_id
        )
        AND component_evidence.source_basis_fingerprint = v_bucket_row.source_basis_fingerprint
        AND component_evidence.source_family_key = v_bucket_row.source_family_key
        AND COALESCE(component_evidence.bucket_code, '') = COALESCE(v_bucket_row.bucket_code, '')
        AND component_evidence.component_key_type = v_bucket_row.component_key_type
        AND component_evidence.component_key_value = v_bucket_row.component_key_value
        AND round(component_evidence.source_units, 6) = round(v_bucket_row.source_units, 6)
        AND round(component_evidence.source_rate, 6) = round(v_bucket_row.source_rate, 6)
        AND round(component_evidence.source_charge_rate, 6) = round(v_bucket_row.source_charge_rate, 6)
        AND component_evidence.requires_resolution = true
        AND component_evidence.is_actionable_resolution_row = true;

      IF v_target_match_count = 0 THEN
        RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND',
                  'session_id', p_session_id::text,
                  'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
                  'case_key', v_case_key,
                  'bucket_ordinal', v_bucket_row.bucket_ordinal
                )::text;
      ELSIF v_target_match_count > 1 THEN
        RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_AMBIGUOUS'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_AMBIGUOUS',
                  'session_id', p_session_id::text,
                  'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
                  'case_key', v_case_key,
                  'bucket_ordinal', v_bucket_row.bucket_ordinal
                )::text;
      END IF;

      UPDATE _tmp_bpay_session_bucket_resolution AS update_bucket
      SET matched_candidate_id = v_bucket_matched_candidate_id,
          anchor_evidence_key = v_anchor_evidence_key,
          decision_context_key = component_evidence.decision_context_key,
          category_identity = component_evidence.category_identity
      FROM _tmp_bpay_session_bucket_component_evidence AS component_evidence
      WHERE update_bucket.bucket_ordinal = v_bucket_row.bucket_ordinal
        AND component_evidence.evidence_key = v_anchor_evidence_key;
    END LOOP;

    SELECT COALESCE(array_agg(DISTINCT input_bucket.matched_candidate_id ORDER BY input_bucket.matched_candidate_id), ARRAY[]::uuid[])
    INTO v_matching_candidate_ids
    FROM _tmp_bpay_session_bucket_resolution AS input_bucket
    WHERE input_bucket.matched_candidate_id IS NOT NULL;

    v_matching_candidate_count := COALESCE(array_length(v_matching_candidate_ids, 1), 0);
    IF v_matching_candidate_count = 0 THEN
      RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND',
                'session_id', p_session_id::text,
                'case_key', v_case_key
              )::text;
    ELSIF v_matching_candidate_count > 1 THEN
      RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_AMBIGUOUS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_AMBIGUOUS',
                'session_id', p_session_id::text,
                'case_key', v_case_key
              )::text;
    END IF;

    v_resolved_candidate_id := v_matching_candidate_ids[1];

    IF v_candidate_id IS NOT NULL AND v_resolved_candidate_id <> v_candidate_id THEN
      RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND',
                'session_id', p_session_id::text,
                'candidate_id', v_candidate_id::text,
                'case_key', v_case_key
              )::text;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM _tmp_bpay_session_candidate_scope AS candidate_scope
      WHERE candidate_scope.candidate_id = v_resolved_candidate_id
    ) THEN
      RAISE EXCEPTION 'WORKBENCH_SESSION_CANDIDATE_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_SESSION_CANDIDATE_NOT_FOUND',
                'session_id', p_session_id::text,
                'candidate_id', v_resolved_candidate_id::text
              )::text;
    END IF;

    SELECT COALESCE(array_agg(DISTINCT component_evidence.timesheet_id ORDER BY component_evidence.timesheet_id), ARRAY[]::uuid[])
    INTO v_matching_timesheet_ids
    FROM _tmp_bpay_session_bucket_resolution AS input_bucket
    JOIN _tmp_bpay_session_bucket_component_evidence AS component_evidence
      ON component_evidence.evidence_key = input_bucket.anchor_evidence_key;

    IF COALESCE(array_length(v_matching_timesheet_ids, 1), 0) <> 1 THEN
      RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_AMBIGUOUS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_AMBIGUOUS',
                'session_id', p_session_id::text,
                'candidate_id', v_resolved_candidate_id::text,
                'case_key', v_case_key
              )::text;
    END IF;

    v_anchor_timesheet_id := v_matching_timesheet_ids[1];

    IF v_linked_timesheet_id IS NOT NULL AND v_linked_timesheet_id <> v_anchor_timesheet_id THEN
      RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND',
                'session_id', p_session_id::text,
                'candidate_id', v_resolved_candidate_id::text,
                'case_key', v_case_key,
                'timesheet_id', v_linked_timesheet_id::text
              )::text;
    END IF;

    SELECT
      component_evidence.contract_id,
      component_evidence.client_id
    INTO
      v_anchor_contract_id,
      v_anchor_client_id
    FROM _tmp_bpay_session_bucket_component_evidence AS component_evidence
    WHERE component_evidence.candidate_id = v_resolved_candidate_id
      AND component_evidence.timesheet_id = v_anchor_timesheet_id
      AND component_evidence.case_key = v_case_key
    ORDER BY component_evidence.evidence_key
    LIMIT 1;

    IF v_resolve_all_linked_timesheets
       AND v_anchor_contract_id IS NULL
       AND v_anchor_client_id IS NULL THEN
      RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND',
                'session_id', p_session_id::text,
                'candidate_id', v_resolved_candidate_id::text,
                'case_key', v_case_key,
                'reason', 'LINKED_SCOPE_CLIENT_NOT_AVAILABLE'
              )::text;
    END IF;

    IF v_resolve_all_linked_timesheets AND EXISTS (
      SELECT 1
      FROM _tmp_bpay_session_bucket_resolution AS input_bucket
      JOIN _tmp_bpay_session_bucket_component_evidence AS component_evidence
        ON component_evidence.evidence_key = input_bucket.anchor_evidence_key
      WHERE component_evidence.classification = ''
         OR component_evidence.source_pay_method = ''
         OR component_evidence.target_pay_method = ''
         OR component_evidence.category_identity = ''
    ) THEN
      RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND',
                'session_id', p_session_id::text,
                'candidate_id', v_resolved_candidate_id::text,
                'case_key', v_case_key,
                'reason', 'LINKED_DECISION_CONTEXT_INCOMPLETE'
              )::text;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM _tmp_bpay_session_bucket_resolution AS input_bucket
      WHERE input_bucket.anchor_evidence_key IS NULL
         OR input_bucket.decision_context_key IS NULL
         OR input_bucket.category_identity IS NULL
    ) THEN
      RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_NOT_FOUND',
                'session_id', p_session_id::text,
                'candidate_id', v_resolved_candidate_id::text,
                'case_key', v_case_key,
                'reason', 'VALIDATED_COMPONENT_CONTEXT_NOT_ATTACHED'
              )::text;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM _tmp_bpay_session_bucket_resolution AS input_bucket
      GROUP BY input_bucket.decision_context_key
      HAVING COUNT(DISTINCT (input_bucket.resolution_mode || '|' || round(input_bucket.target_rate, 2)::text)) > 1
    ) THEN
      RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_AMBIGUOUS'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_ROW_BACKED_BUCKETED_COMPONENT_AMBIGUOUS',
                'session_id', p_session_id::text,
                'candidate_id', v_resolved_candidate_id::text,
                'case_key', v_case_key,
                'reason', 'CONFLICTING_RATE_DECISIONS'
              )::text;
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS _tmp_bpay_session_bucket_decision (
      decision_context_key text PRIMARY KEY,
      resolution_mode text NOT NULL,
      target_rate numeric NOT NULL,
      source_bucket_ordinal integer NOT NULL
    ) ON COMMIT DROP;

    TRUNCATE TABLE _tmp_bpay_session_bucket_decision;

    INSERT INTO _tmp_bpay_session_bucket_decision (
      decision_context_key,
      resolution_mode,
      target_rate,
      source_bucket_ordinal
    )
    SELECT
      input_bucket.decision_context_key,
      MIN(input_bucket.resolution_mode),
      MIN(input_bucket.target_rate),
      MIN(input_bucket.bucket_ordinal)
    FROM _tmp_bpay_session_bucket_resolution AS input_bucket
    GROUP BY input_bucket.decision_context_key;

    CREATE TEMP TABLE IF NOT EXISTS _tmp_bpay_session_target_bucket_resolution (
      resolution_identity_key text PRIMARY KEY,
      candidate_id uuid NOT NULL,
      case_key text NOT NULL,
      timesheet_id uuid NOT NULL,
      contract_id uuid NULL,
      client_id uuid NULL,
      source_basis_json jsonb NOT NULL,
      source_basis_fingerprint text NOT NULL,
      source_family_key text NOT NULL,
      bucket_code text NULL,
      component_key_type text NOT NULL,
      component_key_value text NOT NULL,
      component_fingerprint text NULL,
      classification text NOT NULL,
      source_pay_method text NOT NULL,
      target_pay_method text NOT NULL,
      source_units numeric NOT NULL,
      source_rate numeric NOT NULL,
      source_charge_rate numeric NOT NULL,
      source_pay_ex_vat numeric NOT NULL,
      source_charge_ex_vat numeric NOT NULL,
      source_margin_ex_vat numeric NOT NULL,
      resolution_mode text NOT NULL,
      target_rate numeric NOT NULL,
      target_pay_ex_vat numeric NOT NULL,
      target_charge_ex_vat numeric NOT NULL,
      target_margin_ex_vat numeric NOT NULL,
      margin_delta_ex_vat numeric NOT NULL,
      decision_context_key text NOT NULL,
      category_identity text NOT NULL,
      suggested_resolution_payload_json jsonb NOT NULL,
      suggested_resolution_result_json jsonb NOT NULL,
      component_state_json jsonb NOT NULL,
      applied_via_linked_scope boolean NOT NULL,
      source_bucket_ordinal integer NOT NULL
    ) ON COMMIT DROP;

    TRUNCATE TABLE _tmp_bpay_session_target_bucket_resolution;

    INSERT INTO _tmp_bpay_session_target_bucket_resolution (
      resolution_identity_key,
      candidate_id,
      case_key,
      timesheet_id,
      contract_id,
      client_id,
      source_basis_json,
      source_basis_fingerprint,
      source_family_key,
      bucket_code,
      component_key_type,
      component_key_value,
      component_fingerprint,
      classification,
      source_pay_method,
      target_pay_method,
      source_units,
      source_rate,
      source_charge_rate,
      source_pay_ex_vat,
      source_charge_ex_vat,
      source_margin_ex_vat,
      resolution_mode,
      target_rate,
      target_pay_ex_vat,
      target_charge_ex_vat,
      target_margin_ex_vat,
      margin_delta_ex_vat,
      decision_context_key,
      category_identity,
      suggested_resolution_payload_json,
      suggested_resolution_result_json,
      component_state_json,
      applied_via_linked_scope,
      source_bucket_ordinal
    )
    SELECT
      input_bucket.resolution_identity_key,
      component_evidence.candidate_id,
      component_evidence.case_key,
      component_evidence.timesheet_id,
      component_evidence.contract_id,
      component_evidence.client_id,
      component_evidence.source_basis_json,
      component_evidence.source_basis_fingerprint,
      component_evidence.source_family_key,
      component_evidence.bucket_code,
      component_evidence.component_key_type,
      component_evidence.component_key_value,
      component_evidence.component_fingerprint,
      component_evidence.classification,
      component_evidence.source_pay_method,
      component_evidence.target_pay_method,
      component_evidence.source_units,
      component_evidence.source_rate,
      component_evidence.source_charge_rate,
      component_evidence.source_pay_ex_vat,
      component_evidence.source_charge_ex_vat,
      component_evidence.source_margin_ex_vat,
      input_bucket.resolution_mode,
      input_bucket.target_rate,
      round(component_evidence.source_units * input_bucket.target_rate, 2),
      component_evidence.source_charge_ex_vat,
      round(component_evidence.source_charge_ex_vat - round(component_evidence.source_units * input_bucket.target_rate, 2), 2),
      round(component_evidence.source_pay_ex_vat - round(component_evidence.source_units * input_bucket.target_rate, 2), 2),
      component_evidence.decision_context_key,
      component_evidence.category_identity,
      component_evidence.suggested_resolution_payload_json,
      component_evidence.suggested_resolution_result_json,
      component_evidence.component_state_json,
      false,
      input_bucket.bucket_ordinal
    FROM _tmp_bpay_session_bucket_resolution AS input_bucket
    JOIN _tmp_bpay_session_bucket_component_evidence AS component_evidence
      ON component_evidence.evidence_key = input_bucket.anchor_evidence_key;

    IF v_resolve_all_linked_timesheets THEN
      INSERT INTO _tmp_bpay_session_target_bucket_resolution (
        resolution_identity_key,
        candidate_id,
        case_key,
        timesheet_id,
        contract_id,
        client_id,
        source_basis_json,
        source_basis_fingerprint,
        source_family_key,
        bucket_code,
        component_key_type,
        component_key_value,
        component_fingerprint,
        classification,
        source_pay_method,
        target_pay_method,
        source_units,
        source_rate,
        source_charge_rate,
        source_pay_ex_vat,
        source_charge_ex_vat,
        source_margin_ex_vat,
        resolution_mode,
        target_rate,
        target_pay_ex_vat,
        target_charge_ex_vat,
        target_margin_ex_vat,
        margin_delta_ex_vat,
        decision_context_key,
        category_identity,
        suggested_resolution_payload_json,
        suggested_resolution_result_json,
        component_state_json,
        applied_via_linked_scope,
        source_bucket_ordinal
      )
      SELECT
        CASE
          WHEN component_evidence.source_family_key LIKE 'correction-chain:%'
          THEN public._ctms_correction_carrier_identity_v1(
            component_evidence.candidate_id,
            NULLIF(
              BTRIM(COALESCE(
                component_evidence.component_state_json->>'correction_root_id',
                ''
              )),
              ''
            )::uuid,
            component_evidence.component_key_type,
            component_evidence.component_key_value
          )
          ELSE concat_ws(
            '|',
            'BUCKETED',
            COALESCE(NULLIF(component_evidence.case_key, ''), '~'),
            component_evidence.timesheet_id::text,
            COALESCE(NULLIF(component_evidence.source_basis_fingerprint, ''), '~'),
            COALESCE(NULLIF(component_evidence.source_family_key, ''), '~'),
            COALESCE(NULLIF(component_evidence.bucket_code, ''), '~'),
            COALESCE(NULLIF(component_evidence.component_key_type, ''), '~'),
            COALESCE(NULLIF(component_evidence.component_key_value, ''), '~')
          )
        END,
        component_evidence.candidate_id,
        component_evidence.case_key,
        component_evidence.timesheet_id,
        component_evidence.contract_id,
        component_evidence.client_id,
        component_evidence.source_basis_json,
        component_evidence.source_basis_fingerprint,
        component_evidence.source_family_key,
        component_evidence.bucket_code,
        component_evidence.component_key_type,
        component_evidence.component_key_value,
        component_evidence.component_fingerprint,
        component_evidence.classification,
        component_evidence.source_pay_method,
        component_evidence.target_pay_method,
        component_evidence.source_units,
        component_evidence.source_rate,
        component_evidence.source_charge_rate,
        component_evidence.source_pay_ex_vat,
        component_evidence.source_charge_ex_vat,
        component_evidence.source_margin_ex_vat,
        bucket_decision.resolution_mode,
        bucket_decision.target_rate,
        round(component_evidence.source_units * bucket_decision.target_rate, 2),
        component_evidence.source_charge_ex_vat,
        round(component_evidence.source_charge_ex_vat - round(component_evidence.source_units * bucket_decision.target_rate, 2), 2),
        round(component_evidence.source_pay_ex_vat - round(component_evidence.source_units * bucket_decision.target_rate, 2), 2),
        component_evidence.decision_context_key,
        component_evidence.category_identity,
        component_evidence.suggested_resolution_payload_json,
        component_evidence.suggested_resolution_result_json,
        component_evidence.component_state_json,
        true,
        bucket_decision.source_bucket_ordinal
      FROM _tmp_bpay_session_bucket_component_evidence AS component_evidence
      JOIN _tmp_bpay_session_bucket_decision AS bucket_decision
        ON bucket_decision.decision_context_key = component_evidence.decision_context_key
      WHERE component_evidence.evidence_source = 'ROW_BACKED'
        AND component_evidence.candidate_id = v_resolved_candidate_id
        AND component_evidence.timesheet_id <> v_anchor_timesheet_id
        AND component_evidence.requires_resolution = true
        AND component_evidence.is_actionable_resolution_row = true
        AND (
          (
            v_anchor_contract_id IS NOT NULL
            AND component_evidence.contract_id = v_anchor_contract_id
          )
          OR (
            v_anchor_contract_id IS NULL
            AND component_evidence.contract_id IS NULL
            AND component_evidence.client_id = v_anchor_client_id
          )
        )
      ON CONFLICT (resolution_identity_key) DO NOTHING;
    END IF;

    IF v_operation = 'APPLY' THEN
      -- Serialize the financial-boundary revalidation with draft creation.
      PERFORM pg_advisory_xact_lock(94201, 1);
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS _tmp_bpay_resolution_batch_boundary (
      timesheet_id uuid NOT NULL,
      pay_batch_id uuid NOT NULL,
      batch_status text NOT NULL,
      PRIMARY KEY (timesheet_id, pay_batch_id)
    ) ON COMMIT DROP;
    TRUNCATE TABLE _tmp_bpay_resolution_batch_boundary;

    INSERT INTO _tmp_bpay_resolution_batch_boundary(timesheet_id, pay_batch_id, batch_status)
    SELECT DISTINCT boundary_rows.timesheet_id, boundary_rows.pay_batch_id, boundary_rows.batch_status
    FROM (
      SELECT
        batch_item.timesheet_id,
        batch_row.id AS pay_batch_id,
        UPPER(BTRIM(COALESCE(batch_row.status, ''))) AS batch_status
      FROM public.pay_batch_items AS batch_item
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = batch_item.pay_batch_candidate_id
      JOIN public.pay_batches AS batch_row
        ON batch_row.id = batch_candidate.pay_batch_id
      WHERE batch_item.timesheet_id IS NOT NULL
        AND COALESCE(batch_item.is_voided, false) = false
        AND EXISTS (
          SELECT 1
          FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution
          WHERE target_resolution.timesheet_id = batch_item.timesheet_id
        )
        AND public._pay_batch_status_is_active_reservation(batch_row.status)

      UNION ALL

      SELECT
        batch_snapshot.timesheet_id,
        batch_row.id AS pay_batch_id,
        UPPER(BTRIM(COALESCE(batch_row.status, ''))) AS batch_status
      FROM public.pay_batch_timesheet_snapshots AS batch_snapshot
      JOIN public.pay_batches AS batch_row
        ON batch_row.id = batch_snapshot.pay_batch_id
      WHERE batch_snapshot.timesheet_id IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution
          WHERE target_resolution.timesheet_id = batch_snapshot.timesheet_id
        )
        AND public._pay_batch_status_is_active_reservation(batch_row.status)
    ) AS boundary_rows
    ON CONFLICT (timesheet_id, pay_batch_id) DO UPDATE
      SET batch_status = EXCLUDED.batch_status;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'pay_batch_id', boundary_row.pay_batch_id::text,
             'batch_status', boundary_row.batch_status
           ) ORDER BY boundary_row.pay_batch_id::text), '[]'::jsonb)
    INTO v_anchor_blocking_batches
    FROM _tmp_bpay_resolution_batch_boundary AS boundary_row
    WHERE boundary_row.timesheet_id = v_anchor_timesheet_id;

    IF jsonb_array_length(COALESCE(v_anchor_blocking_batches, '[]'::jsonb)) > 0 THEN
      RAISE EXCEPTION 'WORKBENCH_RESOLUTION_ANCHOR_FINANCIAL_BOUNDARY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_RESOLUTION_ANCHOR_FINANCIAL_BOUNDARY',
                'session_id', p_session_id::text,
                'candidate_id', v_resolved_candidate_id::text,
                'anchor_timesheet_id', v_anchor_timesheet_id::text,
                'message', 'The payment details changed because this timesheet is now included in a payment batch. Refresh Banking Pay and review the latest details.'
              )::text;
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'timesheet_id', excluded_scope.timesheet_id::text,
             'reason', 'ALREADY_IN_LIVE_BATCH',
             'batch_status', excluded_scope.batch_status
           ) ORDER BY excluded_scope.timesheet_id::text), '[]'::jsonb)
    INTO v_excluded_linked_timesheets
    FROM (
      SELECT
        boundary_row.timesheet_id,
        MIN(boundary_row.batch_status) AS batch_status
      FROM _tmp_bpay_resolution_batch_boundary AS boundary_row
      WHERE boundary_row.timesheet_id <> v_anchor_timesheet_id
      GROUP BY boundary_row.timesheet_id
    ) AS excluded_scope;

    v_excluded_linked_timesheet_count := jsonb_array_length(COALESCE(v_excluded_linked_timesheets, '[]'::jsonb));

    DELETE FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution
    WHERE target_resolution.applied_via_linked_scope = true
      AND EXISTS (
        SELECT 1
        FROM _tmp_bpay_resolution_batch_boundary AS boundary_row
        WHERE boundary_row.timesheet_id = target_resolution.timesheet_id
      );

    SELECT COUNT(*)::integer
    INTO v_anchor_component_count
    FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution
    WHERE target_resolution.applied_via_linked_scope = false;

    SELECT COUNT(*)::integer
    INTO v_linked_target_component_count
    FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution
    WHERE target_resolution.applied_via_linked_scope = true;

    SELECT COUNT(DISTINCT target_resolution.timesheet_id)::integer
    INTO v_linked_target_timesheet_count
    FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution
    WHERE target_resolution.applied_via_linked_scope = true;

    SELECT COUNT(DISTINCT target_resolution.timesheet_id)::integer
    INTO v_materialized_target_timesheet_count
    FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution;

    IF v_resolve_all_linked_timesheets THEN
      SELECT COUNT(*)::integer
      INTO v_skipped_mismatch_count
      FROM _tmp_bpay_session_bucket_component_evidence AS component_evidence
      WHERE component_evidence.evidence_source = 'ROW_BACKED'
        AND component_evidence.candidate_id = v_resolved_candidate_id
        AND component_evidence.timesheet_id <> v_anchor_timesheet_id
        AND component_evidence.requires_resolution = true
        AND component_evidence.is_actionable_resolution_row = true
        AND (
          (
            v_anchor_contract_id IS NOT NULL
            AND component_evidence.contract_id = v_anchor_contract_id
          )
          OR (
            v_anchor_contract_id IS NULL
            AND component_evidence.contract_id IS NULL
            AND component_evidence.client_id = v_anchor_client_id
          )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM _tmp_bpay_session_bucket_decision AS bucket_decision
          WHERE bucket_decision.decision_context_key = component_evidence.decision_context_key
        );
    ELSE
      v_skipped_mismatch_count := 0;
    END IF;

    SELECT COALESCE(array_agg(DISTINCT target_resolution.timesheet_id ORDER BY target_resolution.timesheet_id), ARRAY[]::uuid[])
    INTO v_eligible_linked_timesheet_ids
    FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution
    WHERE target_resolution.applied_via_linked_scope = true
      AND target_resolution.timesheet_id <> v_anchor_timesheet_id;

    v_linked_target_timesheet_count := COALESCE(array_length(v_eligible_linked_timesheet_ids, 1), 0);
    v_total_affected_timesheet_count := 1 + v_linked_target_timesheet_count;

    SELECT COALESCE(array_agg(DISTINCT target_resolution.timesheet_id ORDER BY target_resolution.timesheet_id), ARRAY[]::uuid[])
    INTO v_case_targeted_timesheet_ids
    FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution;
    v_case_linked_timesheet_ids := v_eligible_linked_timesheet_ids;

    v_linked_scope_type := CASE
      WHEN NOT v_resolve_all_linked_timesheets THEN 'SELF_ONLY'
      WHEN v_anchor_contract_id IS NOT NULL THEN 'CONTRACT'
      ELSE 'DAILY_SAME_BASIS'
    END;

    IF v_operation = 'DISCOVER' THEN
      RETURN jsonb_build_object(
        'ok', true,
        'operation', 'DISCOVER',
        'session_id', p_session_id::text,
        'session_version', v_session_row.version,
        'progress_counter_version', COALESCE(v_session_row.progress_counter_version, 0),
        'candidate_id', v_resolved_candidate_id::text,
        'anchor_timesheet_id', v_anchor_timesheet_id::text,
        'anchor_case_key', v_case_key,
        'eligible_linked_timesheet_ids', COALESCE(to_jsonb(v_eligible_linked_timesheet_ids), '[]'::jsonb),
        'eligible_linked_timesheet_count', v_linked_target_timesheet_count,
        'total_affected_timesheet_count', v_total_affected_timesheet_count,
        'excluded_linked_timesheets', COALESCE(v_excluded_linked_timesheets, '[]'::jsonb),
        'excluded_linked_timesheet_count', v_excluded_linked_timesheet_count,
        'targeted_timesheet_ids', COALESCE(to_jsonb(v_case_targeted_timesheet_ids), '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(to_jsonb(v_case_linked_timesheet_ids), '[]'::jsonb),
        'state_changed', false,
        'job_id', NULL::text
      );
    END IF;

    INSERT INTO _tmp_bpay_session_case_resolution_existing
    SELECT existing_resolution.*
    FROM public.banking_pay_workbench_session_case_resolutions AS existing_resolution
    WHERE existing_resolution.session_id = p_session_id
      AND existing_resolution.candidate_id = v_resolved_candidate_id
      AND existing_resolution.resolution_family = 'BUCKETED'
      AND (
        existing_resolution.timesheet_id = v_anchor_timesheet_id
        OR (
          existing_resolution.timesheet_id IS NOT NULL
          AND existing_resolution.timesheet_id = ANY(COALESCE(v_eligible_linked_timesheet_ids, ARRAY[]::uuid[]))
          AND BTRIM(COALESCE(existing_resolution.payload_json->>'source_anchor_timesheet_id', '')) = v_anchor_timesheet_id::text
          AND BTRIM(COALESCE(existing_resolution.payload_json->>'source_anchor_case_key', '')) = v_case_key
          AND LOWER(BTRIM(COALESCE(existing_resolution.payload_json->>'applied_via_linked_scope', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        )
      );

    SELECT COUNT(*)::integer
    INTO v_existing_deleted_count
    FROM _tmp_bpay_session_case_resolution_existing AS existing_resolution;

    IF v_existing_deleted_count > 0 THEN
      DELETE FROM public.banking_pay_workbench_session_case_resolutions AS delete_resolution
      WHERE delete_resolution.id IN (
        SELECT existing_resolution.id
        FROM _tmp_bpay_session_case_resolution_existing AS existing_resolution
      );
    END IF;

    FOR v_target_resolution_row IN
      SELECT target_resolution.*
      FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution
      ORDER BY
        target_resolution.timesheet_id,
        target_resolution.component_key_type,
        target_resolution.component_key_value,
        COALESCE(target_resolution.bucket_code, ''),
        target_resolution.source_basis_fingerprint
    LOOP
      v_existing_row := NULL;
      SELECT existing_resolution.*
      INTO v_existing_row
      FROM _tmp_bpay_session_case_resolution_existing AS existing_resolution
      WHERE existing_resolution.resolution_identity_key = v_target_resolution_row.resolution_identity_key
      LIMIT 1;

      v_target_resolution_result_json := jsonb_strip_nulls(
        jsonb_build_object(
          'target_units', round(v_target_resolution_row.source_units, 6),
          'target_rate', round(v_target_resolution_row.target_rate, 2),
          'target_amount_ex_vat', round(v_target_resolution_row.target_pay_ex_vat, 2),
          'target_pay_ex_vat', round(v_target_resolution_row.target_pay_ex_vat, 2),
          'target_charge_ex_vat', round(v_target_resolution_row.target_charge_ex_vat, 2),
          'target_margin_ex_vat', round(v_target_resolution_row.target_margin_ex_vat, 2),
          'margin_delta_ex_vat', round(v_target_resolution_row.margin_delta_ex_vat, 2),
          'source_pay_ex_vat', round(v_target_resolution_row.source_pay_ex_vat, 2),
          'source_charge_ex_vat', round(v_target_resolution_row.source_charge_ex_vat, 2),
          'source_margin_ex_vat', round(v_target_resolution_row.source_margin_ex_vat, 2)
        )
      );

      v_target_bucket_payload_json := jsonb_strip_nulls(
        jsonb_build_object(
          'timesheet_id', v_target_resolution_row.timesheet_id::text,
          'finance_component_id', NULLIF(BTRIM(COALESCE(v_target_resolution_row.component_state_json->>'finance_component_id', '')), ''),
          'source_basis_json', CASE WHEN v_target_resolution_row.source_basis_json = '{}'::jsonb THEN NULL ELSE v_target_resolution_row.source_basis_json END,
          'source_basis_fingerprint', NULLIF(v_target_resolution_row.source_basis_fingerprint, ''),
          'source_family_key', NULLIF(v_target_resolution_row.source_family_key, ''),
          'bucket_code', v_target_resolution_row.bucket_code,
          'component_key_type', NULLIF(v_target_resolution_row.component_key_type, ''),
          'component_key_value', NULLIF(v_target_resolution_row.component_key_value, ''),
          'component_fingerprint', v_target_resolution_row.component_fingerprint,
          'classification', NULLIF(v_target_resolution_row.classification, '')
        )
        || jsonb_build_object(
          'source_pay_method', NULLIF(v_target_resolution_row.source_pay_method, ''),
          'target_pay_method', NULLIF(v_target_resolution_row.target_pay_method, ''),
          'source_units', round(v_target_resolution_row.source_units, 6),
          'target_units', round(v_target_resolution_row.source_units, 6),
          'source_rate', round(v_target_resolution_row.source_rate, 6),
          'source_charge_rate', round(v_target_resolution_row.source_charge_rate, 6),
          'source_pay_ex_vat', round(v_target_resolution_row.source_pay_ex_vat, 2),
          'source_charge_ex_vat', round(v_target_resolution_row.source_charge_ex_vat, 2),
          'source_margin_ex_vat', round(v_target_resolution_row.source_margin_ex_vat, 2),
          'resolution_mode', v_target_resolution_row.resolution_mode
        )
        || jsonb_build_object(
          'target_rate', round(v_target_resolution_row.target_rate, 2),
          'target_amount_ex_vat', round(v_target_resolution_row.target_pay_ex_vat, 2),
          'target_pay_ex_vat', round(v_target_resolution_row.target_pay_ex_vat, 2),
          'target_charge_ex_vat', round(v_target_resolution_row.target_charge_ex_vat, 2),
          'target_margin_ex_vat', round(v_target_resolution_row.target_margin_ex_vat, 2),
          'margin_delta_ex_vat', round(v_target_resolution_row.margin_delta_ex_vat, 2),
          'decision_context_key', v_target_resolution_row.decision_context_key,
          'category_identity', v_target_resolution_row.category_identity,
          'suggested_resolution_payload_json', CASE WHEN v_target_resolution_row.suggested_resolution_payload_json = '{}'::jsonb THEN NULL ELSE v_target_resolution_row.suggested_resolution_payload_json END,
          'suggested_resolution_result_json', CASE WHEN v_target_resolution_row.suggested_resolution_result_json = '{}'::jsonb THEN NULL ELSE v_target_resolution_row.suggested_resolution_result_json END
        )
        || jsonb_build_object(
          'saved_resolution_payload_json', jsonb_build_object(
            'resolution_family', 'BUCKETED',
            'resolution_mode', v_target_resolution_row.resolution_mode,
            'target_pay_method', NULLIF(v_target_resolution_row.target_pay_method, ''),
            'target_units', round(v_target_resolution_row.source_units, 6),
            'target_rate', round(v_target_resolution_row.target_rate, 2),
            'decision_context_key', v_target_resolution_row.decision_context_key
          ),
          'saved_resolution_result_json', v_target_resolution_result_json,
          'applied_via_linked_scope', v_target_resolution_row.applied_via_linked_scope,
          'source_anchor_case_key', v_case_key,
          'source_anchor_timesheet_id', v_anchor_timesheet_id::text,
          'resolved_rate_cancel_scope', 'ANCHOR_FAMILY_PRE_DRAFT'
        )
      );

      v_linked_scope_json := jsonb_strip_nulls(
        jsonb_build_object(
          'linked_scope_type', v_linked_scope_type,
          'contract_id', CASE WHEN v_anchor_contract_id IS NULL THEN NULL ELSE v_anchor_contract_id::text END,
          'client_id', CASE WHEN v_anchor_client_id IS NULL THEN NULL ELSE v_anchor_client_id::text END,
          'source_anchor_case_key', v_case_key,
          'source_anchor_timesheet_id', v_anchor_timesheet_id::text,
          'target_case_key', v_target_resolution_row.case_key,
          'target_timesheet_id', v_target_resolution_row.timesheet_id::text,
          'requested_resolve_all_linked_timesheets', v_resolve_all_linked_timesheets,
          'applied_via_linked_scope', v_target_resolution_row.applied_via_linked_scope,
          'resolved_rate_cancel_scope', 'ANCHOR_FAMILY_PRE_DRAFT'
        )
      );

      v_normalized_payload_json := jsonb_strip_nulls(
        (
          COALESCE(v_resolution_payload_json, '{}'::jsonb)
          - 'bucket_resolutions'
          - 'resolution_mode'
          - 'mode'
          - 'candidate_id'
          - 'case_key'
          - 'resolution_family'
          - 'timesheet_id'
          - 'linked_timesheet_id'
          - 'target_rate'
          - 'source_units'
          - 'source_rate'
          - 'source_charge_rate'
          - 'resolve_all_linked_timesheets'
          - 'linked_resolution_scope_json'
        )
        || jsonb_build_object(
          'case_key', v_target_resolution_row.case_key,
          'candidate_id', v_resolved_candidate_id::text,
          'finance_case_id', CASE WHEN v_finance_case_id_text = '' THEN NULL ELSE v_finance_case_id_text END,
          'linked_timesheet_id', v_target_resolution_row.timesheet_id::text,
          'timesheet_id', v_target_resolution_row.timesheet_id::text,
          'resolution_family', 'BUCKETED',
          'resolve_all_linked_timesheets', false,
          'requested_resolve_all_linked_timesheets', v_resolve_all_linked_timesheets,
          'applied_via_linked_scope', v_target_resolution_row.applied_via_linked_scope,
          'source_anchor_case_key', v_case_key
        )
        || jsonb_build_object(
          'source_anchor_timesheet_id', v_anchor_timesheet_id::text,
          'linked_resolution_scope_json', v_linked_scope_json,
          'resolved_rate_cancel_scope', 'ANCHOR_FAMILY_PRE_DRAFT',
          'decision_context_key', v_target_resolution_row.decision_context_key,
          'category_identity', v_target_resolution_row.category_identity,
          'bucket_resolutions', jsonb_build_array(v_target_bucket_payload_json)
        )
      );

      v_audit_before_json := CASE
        WHEN v_existing_row.id IS NULL THEN NULL
        ELSE jsonb_build_object(
          'id', v_existing_row.id::text,
          'session_id', v_existing_row.session_id::text,
          'candidate_id', v_existing_row.candidate_id::text,
          'case_key', v_existing_row.case_key,
          'resolution_family', v_existing_row.resolution_family,
          'resolution_identity_key', v_existing_row.resolution_identity_key,
          'timesheet_id', CASE WHEN v_existing_row.timesheet_id IS NULL THEN NULL ELSE v_existing_row.timesheet_id::text END,
          'source_basis_fingerprint', v_existing_row.source_basis_fingerprint,
          'source_family_key', v_existing_row.source_family_key,
          'bucket_code', v_existing_row.bucket_code,
          'component_key_type', v_existing_row.component_key_type,
          'component_key_value', v_existing_row.component_key_value,
          'payload_json', v_existing_row.payload_json
        )
      END;

      INSERT INTO public.banking_pay_workbench_session_case_resolutions (
        session_id,
        candidate_id,
        case_key,
        resolution_family,
        resolution_identity_key,
        timesheet_id,
        source_basis_fingerprint,
        source_family_key,
        bucket_code,
        component_key_type,
        component_key_value,
        payload_json,
        created_at_utc,
        updated_at_utc
      )
      VALUES (
        p_session_id,
        v_resolved_candidate_id,
        v_target_resolution_row.case_key,
        'BUCKETED',
        v_target_resolution_row.resolution_identity_key,
        v_target_resolution_row.timesheet_id,
        NULLIF(v_target_resolution_row.source_basis_fingerprint, ''),
        NULLIF(v_target_resolution_row.source_family_key, ''),
        v_target_resolution_row.bucket_code,
        NULLIF(v_target_resolution_row.component_key_type, ''),
        NULLIF(v_target_resolution_row.component_key_value, ''),
        v_normalized_payload_json,
        v_now,
        v_now
      )
      ON CONFLICT (session_id, resolution_identity_key)
      DO UPDATE
      SET candidate_id = EXCLUDED.candidate_id,
          case_key = EXCLUDED.case_key,
          resolution_family = EXCLUDED.resolution_family,
          timesheet_id = EXCLUDED.timesheet_id,
          source_basis_fingerprint = EXCLUDED.source_basis_fingerprint,
          source_family_key = EXCLUDED.source_family_key,
          bucket_code = EXCLUDED.bucket_code,
          component_key_type = EXCLUDED.component_key_type,
          component_key_value = EXCLUDED.component_key_value,
          payload_json = EXCLUDED.payload_json,
          updated_at_utc = v_now
      RETURNING public.banking_pay_workbench_session_case_resolutions.*
      INTO v_upserted_row;

      v_case_resolution_ids := v_case_resolution_ids || jsonb_build_array(v_upserted_row.id::text);
      v_resolution_identity_keys := v_resolution_identity_keys || jsonb_build_array(v_upserted_row.resolution_identity_key);
      IF v_case_resolution_id_text IS NULL THEN
        v_case_resolution_id_text := v_upserted_row.id::text;
      END IF;

      v_audit_after_json := jsonb_build_object(
        'id', v_upserted_row.id::text,
        'session_id', v_upserted_row.session_id::text,
        'candidate_id', v_upserted_row.candidate_id::text,
        'case_key', v_upserted_row.case_key,
        'resolution_family', v_upserted_row.resolution_family,
        'resolution_identity_key', v_upserted_row.resolution_identity_key,
        'timesheet_id', CASE WHEN v_upserted_row.timesheet_id IS NULL THEN NULL ELSE v_upserted_row.timesheet_id::text END,
        'source_basis_fingerprint', v_upserted_row.source_basis_fingerprint,
        'source_family_key', v_upserted_row.source_family_key,
        'bucket_code', v_upserted_row.bucket_code,
        'component_key_type', v_upserted_row.component_key_type,
        'component_key_value', v_upserted_row.component_key_value,
        'payload_json', v_upserted_row.payload_json
      );

      PERFORM public._audit_insert(
        'banking_pay_workbench_session_case_resolution',
        v_upserted_row.id::text,
        CASE WHEN v_existing_row.id IS NULL THEN 'SESSION_CASE_RESOLUTION_CREATED' ELSE 'SESSION_CASE_RESOLUTION_UPDATED' END,
        v_audit_before_json,
        v_audit_after_json,
        'SESSION_CASE_RESOLUTION_APPLIED',
        p_actor_user_id
      );
    END LOOP;
  ELSE
    v_nonbucket_resolution_mode := UPPER(BTRIM(COALESCE(
      v_resolution_payload_json->>'resolution_mode',
      v_resolution_payload_json->>'mode',
      ''
    )));

    IF v_nonbucket_resolution_mode NOT IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_AMOUNT') THEN
      RAISE EXCEPTION 'NON_BUCKET resolution_mode must be SUGGESTED_EQUIVALENT_BASIS or MANUAL_AMOUNT';
    END IF;

    IF COALESCE(
      v_resolution_payload_json->>'target_amount_ex_vat',
      v_resolution_payload_json->>'target_amount',
      v_resolution_payload_json->>'amount_ex_vat',
      v_resolution_payload_json->>'amount',
      ''
    ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      RAISE EXCEPTION 'target_amount_ex_vat is required for NON_BUCKET resolution';
    END IF;

    v_target_amount_ex_vat := round(COALESCE(
      NULLIF(v_resolution_payload_json->>'target_amount_ex_vat', '')::numeric,
      NULLIF(v_resolution_payload_json->>'target_amount', '')::numeric,
      NULLIF(v_resolution_payload_json->>'amount_ex_vat', '')::numeric,
      NULLIF(v_resolution_payload_json->>'amount', '')::numeric
    ), 2);

    IF v_target_amount_ex_vat < 0 THEN
      RAISE EXCEPTION 'target_amount_ex_vat must be non-negative';
    END IF;

    SELECT COUNT(*)::integer
    INTO v_row_backed_case_count
    FROM _tmp_bpay_session_row_backed_case_baseline AS row_backed_case
    WHERE COALESCE(row_backed_case.resolution_family, '') IN ('', 'NON_BUCKET')
      AND (
        v_linked_timesheet_id IS NULL
        OR row_backed_case.timesheet_id IS NULL
        OR row_backed_case.timesheet_id = v_linked_timesheet_id
      )
      AND (
        v_finance_case_id_text = ''
        OR row_backed_case.finance_case_id IS NULL
        OR row_backed_case.finance_case_id::text = v_finance_case_id_text
      );

    IF v_row_backed_case_count > 0 THEN
      IF v_candidate_id IS NULL THEN
        IF v_row_backed_case_count > 1 THEN
          RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_CASE_BASELINE_AMBIGUOUS'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'WORKBENCH_ROW_BACKED_CASE_BASELINE_AMBIGUOUS',
                    'session_id', p_session_id::text,
                    'case_key', v_case_key,
                    'resolution_family', 'NON_BUCKET'
                  )::text;
        END IF;

        SELECT COALESCE(array_agg(DISTINCT row_backed_case.candidate_id ORDER BY row_backed_case.candidate_id), ARRAY[]::uuid[])
        INTO v_matching_candidate_ids
        FROM _tmp_bpay_session_row_backed_case_baseline AS row_backed_case
        WHERE COALESCE(row_backed_case.resolution_family, '') IN ('', 'NON_BUCKET')
          AND (
            v_linked_timesheet_id IS NULL
            OR row_backed_case.timesheet_id IS NULL
            OR row_backed_case.timesheet_id = v_linked_timesheet_id
          )
          AND (
            v_finance_case_id_text = ''
            OR row_backed_case.finance_case_id IS NULL
            OR row_backed_case.finance_case_id::text = v_finance_case_id_text
          );

        v_matching_candidate_count := COALESCE(array_length(v_matching_candidate_ids, 1), 0);
        IF v_matching_candidate_count = 0 THEN
          RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND',
                    'session_id', p_session_id::text,
                    'case_key', v_case_key,
                    'resolution_family', 'NON_BUCKET'
                  )::text;
        ELSIF v_matching_candidate_count > 1 THEN
          RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_CASE_BASELINE_AMBIGUOUS'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'WORKBENCH_ROW_BACKED_CASE_BASELINE_AMBIGUOUS',
                    'session_id', p_session_id::text,
                    'case_key', v_case_key,
                    'resolution_family', 'NON_BUCKET'
                  )::text;
        END IF;

        v_resolved_candidate_id := v_matching_candidate_ids[1];
      ELSE
        SELECT COUNT(*)::integer
        INTO v_target_match_count
        FROM _tmp_bpay_session_row_backed_case_baseline AS row_backed_case
        WHERE row_backed_case.candidate_id = v_candidate_id
          AND COALESCE(row_backed_case.resolution_family, '') IN ('', 'NON_BUCKET')
          AND (
            v_linked_timesheet_id IS NULL
            OR row_backed_case.timesheet_id IS NULL
            OR row_backed_case.timesheet_id = v_linked_timesheet_id
          )
          AND (
            v_finance_case_id_text = ''
            OR row_backed_case.finance_case_id IS NULL
            OR row_backed_case.finance_case_id::text = v_finance_case_id_text
          );

        IF v_target_match_count = 0 THEN
          RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'WORKBENCH_ROW_BACKED_CASE_BASELINE_NOT_FOUND',
                    'session_id', p_session_id::text,
                    'candidate_id', v_candidate_id::text,
                    'case_key', v_case_key,
                    'resolution_family', 'NON_BUCKET'
                  )::text;
        ELSIF v_target_match_count > 1 THEN
          RAISE EXCEPTION 'WORKBENCH_ROW_BACKED_CASE_BASELINE_AMBIGUOUS'
            USING ERRCODE = 'P0001',
                  DETAIL = jsonb_build_object(
                    'code', 'WORKBENCH_ROW_BACKED_CASE_BASELINE_AMBIGUOUS',
                    'session_id', p_session_id::text,
                    'candidate_id', v_candidate_id::text,
                    'case_key', v_case_key,
                    'resolution_family', 'NON_BUCKET'
                  )::text;
        END IF;

        v_resolved_candidate_id := v_candidate_id;
      END IF;
    ELSIF v_candidate_id IS NULL THEN
      SELECT COALESCE(array_agg(DISTINCT snapshot_case.candidate_id ORDER BY snapshot_case.candidate_id), ARRAY[]::uuid[])
      INTO v_matching_candidate_ids
      FROM public.banking_pay_snapshot_case_state AS snapshot_case
      WHERE snapshot_case.snapshot_run_id = v_session_row.source_snapshot_run_id
        AND EXISTS (
          SELECT 1
          FROM _tmp_bpay_session_candidate_scope AS candidate_scope
          WHERE candidate_scope.candidate_id = snapshot_case.candidate_id
        )
        AND snapshot_case.case_key = v_case_key;

      v_matching_candidate_count := COALESCE(array_length(v_matching_candidate_ids, 1), 0);
      IF v_matching_candidate_count = 0 THEN
        RAISE EXCEPTION 'No snapshot baseline case found for NON_BUCKET resolution in session % for case_key %', p_session_id, v_case_key;
      ELSIF v_matching_candidate_count > 1 THEN
        RAISE EXCEPTION 'Ambiguous NON_BUCKET resolution target for case_key % in session %', v_case_key, p_session_id;
      END IF;

      v_resolved_candidate_id := v_matching_candidate_ids[1];
    ELSE
      SELECT COUNT(*)::integer
      INTO v_target_match_count
      FROM public.banking_pay_snapshot_case_state AS snapshot_case
      WHERE snapshot_case.snapshot_run_id = v_session_row.source_snapshot_run_id
        AND snapshot_case.candidate_id = v_candidate_id
        AND snapshot_case.case_key = v_case_key;

      IF v_target_match_count = 0 THEN
        RAISE EXCEPTION 'No matching NON_BUCKET snapshot baseline case found for candidate % in session %', v_candidate_id, p_session_id;
      ELSIF v_target_match_count > 1 THEN
        RAISE EXCEPTION 'Ambiguous NON_BUCKET snapshot baseline case found for candidate % in session %', v_candidate_id, p_session_id;
      END IF;

      v_resolved_candidate_id := v_candidate_id;
    END IF;

    INSERT INTO _tmp_bpay_session_case_resolution_existing
    SELECT existing_resolution.*
    FROM public.banking_pay_workbench_session_case_resolutions AS existing_resolution
    WHERE existing_resolution.session_id = p_session_id
      AND existing_resolution.candidate_id = v_resolved_candidate_id
      AND existing_resolution.case_key = v_case_key
      AND existing_resolution.resolution_family = 'NON_BUCKET'
      AND (
        v_linked_timesheet_id IS NULL
        OR existing_resolution.timesheet_id = v_linked_timesheet_id
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'linked_timesheet_id', '')), '') = v_linked_timesheet_id::text
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'timesheet_id', '')), '') = v_linked_timesheet_id::text
      )
      AND (
        v_finance_case_id_text = ''
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') IS NULL
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') = v_finance_case_id_text
      );

    v_nonbucket_resolution_identity_key := concat_ws(
      '|',
      'NON_BUCKET',
      COALESCE(NULLIF(v_case_key, ''), '~'),
      COALESCE(CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END, '~'),
      '~',
      '~',
      '~',
      '~',
      '~'
    );

    v_nonbucket_existing_row := NULL;
    SELECT temp_existing.*
    INTO v_nonbucket_existing_row
    FROM _tmp_bpay_session_case_resolution_existing AS temp_existing
    WHERE temp_existing.resolution_identity_key = v_nonbucket_resolution_identity_key
    LIMIT 1;

    v_normalized_payload_json := jsonb_strip_nulls(
      (COALESCE(v_resolution_payload_json, '{}'::jsonb) - 'bucket_resolutions' - 'candidate_id' - 'case_key' - 'resolution_family' - 'timesheet_id' - 'linked_timesheet_id')
      || jsonb_build_object(
        'case_key', v_case_key,
        'candidate_id', v_resolved_candidate_id::text,
        'finance_case_id', CASE WHEN v_finance_case_id_text = '' THEN NULL ELSE v_finance_case_id_text END,
        'linked_timesheet_id', CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END,
        'timesheet_id', CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END,
        'resolution_family', 'NON_BUCKET',
        'resolution_mode', v_nonbucket_resolution_mode,
        'target_amount_ex_vat', round(v_target_amount_ex_vat, 2)
      )
    );

    v_audit_before_json := CASE
      WHEN v_nonbucket_existing_row.id IS NULL THEN NULL
      ELSE jsonb_build_object(
        'id', v_nonbucket_existing_row.id::text,
        'session_id', v_nonbucket_existing_row.session_id::text,
        'candidate_id', v_nonbucket_existing_row.candidate_id::text,
        'case_key', v_nonbucket_existing_row.case_key,
        'resolution_family', v_nonbucket_existing_row.resolution_family,
        'resolution_identity_key', v_nonbucket_existing_row.resolution_identity_key,
        'timesheet_id', CASE WHEN v_nonbucket_existing_row.timesheet_id IS NULL THEN NULL ELSE v_nonbucket_existing_row.timesheet_id::text END,
        'source_basis_fingerprint', v_nonbucket_existing_row.source_basis_fingerprint,
        'source_family_key', v_nonbucket_existing_row.source_family_key,
        'bucket_code', v_nonbucket_existing_row.bucket_code,
        'component_key_type', v_nonbucket_existing_row.component_key_type,
        'component_key_value', v_nonbucket_existing_row.component_key_value,
        'payload_json', v_nonbucket_existing_row.payload_json
      )
    END;

    INSERT INTO public.banking_pay_workbench_session_case_resolutions (
      session_id,
      candidate_id,
      case_key,
      resolution_family,
      resolution_identity_key,
      timesheet_id,
      source_basis_fingerprint,
      source_family_key,
      bucket_code,
      component_key_type,
      component_key_value,
      payload_json,
      created_at_utc,
      updated_at_utc
    )
    VALUES (
      p_session_id,
      v_resolved_candidate_id,
      v_case_key,
      'NON_BUCKET',
      v_nonbucket_resolution_identity_key,
      v_linked_timesheet_id,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      v_normalized_payload_json,
      v_now,
      v_now
    )
    ON CONFLICT (session_id, resolution_identity_key)
    DO UPDATE
    SET candidate_id = EXCLUDED.candidate_id,
        case_key = EXCLUDED.case_key,
        resolution_family = EXCLUDED.resolution_family,
        timesheet_id = EXCLUDED.timesheet_id,
        payload_json = EXCLUDED.payload_json,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_session_case_resolutions.*
    INTO v_nonbucket_upserted_row;

    v_case_resolution_ids := jsonb_build_array(v_nonbucket_upserted_row.id::text);
    v_resolution_identity_keys := jsonb_build_array(v_nonbucket_upserted_row.resolution_identity_key);
    v_case_resolution_id_text := v_nonbucket_upserted_row.id::text;

    v_audit_after_json := jsonb_build_object(
      'id', v_nonbucket_upserted_row.id::text,
      'session_id', v_nonbucket_upserted_row.session_id::text,
      'candidate_id', v_nonbucket_upserted_row.candidate_id::text,
      'case_key', v_nonbucket_upserted_row.case_key,
      'resolution_family', v_nonbucket_upserted_row.resolution_family,
      'resolution_identity_key', v_nonbucket_upserted_row.resolution_identity_key,
      'timesheet_id', CASE WHEN v_nonbucket_upserted_row.timesheet_id IS NULL THEN NULL ELSE v_nonbucket_upserted_row.timesheet_id::text END,
      'payload_json', v_nonbucket_upserted_row.payload_json,
      'resolution_origin_session_id', CASE WHEN v_nonbucket_upserted_row.resolution_origin_session_id IS NULL THEN NULL ELSE v_nonbucket_upserted_row.resolution_origin_session_id::text END,
      'resolution_origin_pay_date', CASE WHEN v_nonbucket_upserted_row.resolution_origin_pay_date IS NULL THEN NULL ELSE v_nonbucket_upserted_row.resolution_origin_pay_date::text END,
      'resolution_origin_source_basis_fingerprint', v_nonbucket_upserted_row.resolution_origin_source_basis_fingerprint
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_case_resolution',
      v_nonbucket_upserted_row.id::text,
      CASE WHEN v_nonbucket_existing_row.id IS NULL THEN 'SESSION_CASE_RESOLUTION_CREATED' ELSE 'SESSION_CASE_RESOLUTION_UPDATED' END,
      v_audit_before_json,
      v_audit_after_json,
      'SESSION_CASE_RESOLUTION_APPLIED',
      p_actor_user_id
    );
  END IF;

  IF v_resolution_family='BUCKETED'
     AND v_anchor_timesheet_id IS NOT NULL
     AND COALESCE(v_resolved_candidate_id,v_candidate_id) IS NOT NULL THEN
    v_correction_normalise_result :=
      public._ctms_normalise_correction_case_resolutions_v1(
        p_session_id,
        COALESCE(v_resolved_candidate_id,v_candidate_id),
        v_anchor_timesheet_id
      );

    -- The normaliser may reuse an existing stable canonical resolution and
    -- remove the temporary per-timesheet aliases created above. From this
    -- point onwards the surviving canonical rows are the authoritative IDs
    -- for audit, origin proof and the API response.
    IF COALESCE(
         NULLIF(v_correction_normalise_result->>'normalised_count','')::integer,
         0
       ) > 0 THEN
      v_case_resolution_ids :=
        COALESCE(
          v_correction_normalise_result->'case_resolution_ids',
          '[]'::jsonb
        );
      v_resolution_identity_keys :=
        COALESCE(
          v_correction_normalise_result->'resolution_identity_keys',
          '[]'::jsonb
        );
      v_case_resolution_id_text :=
        NULLIF(
          BTRIM(COALESCE(
            v_correction_normalise_result->>'case_resolution_id',
            ''
          )),
          ''
        );
    END IF;
  END IF;

  -- A fresh target-session decision is authoritative for its canonical
  -- component.  Any deferred or stale predecessor carry for that exact key
  -- must stop blocking draftability once this transaction has saved and
  -- normalised the replacement decision.
  WITH superseded_carry AS (
    UPDATE
      public.banking_pay_workbench_case_resolution_carry_registrations
        carry_row
    SET status = 'SUPERSEDED',
        state_reason_code = 'TARGET_AUTHORITATIVE_DECISION_EXISTS',
        target_resolution_id = target_resolution.id,
        target_economic_fingerprint =
          NULLIF(
            target_resolution.payload_json
              ->> 'resolution_economic_fingerprint',
            ''
          ),
        last_error_json = NULL,
        updated_at_utc = v_now,
        completed_at_utc = v_now
    FROM public.banking_pay_workbench_session_case_resolutions
      target_resolution
    WHERE carry_row.target_session_id = p_session_id
      AND carry_row.candidate_id =
        COALESCE(v_resolved_candidate_id, v_candidate_id)
      AND carry_row.status IN ('PENDING', 'STALE')
      AND target_resolution.session_id = p_session_id
      AND target_resolution.candidate_id =
        COALESCE(v_resolved_candidate_id, v_candidate_id)
      AND target_resolution.resolution_identity_key =
        carry_row.canonical_resolution_key
      AND target_resolution.resolution_identity_key IN (
        SELECT resolution_key.value
        FROM jsonb_array_elements_text(
          COALESCE(v_resolution_identity_keys, '[]'::jsonb)
        ) resolution_key(value)
      )
    RETURNING
      carry_row.id,
      carry_row.source_session_id,
      carry_row.source_resolution_id,
      carry_row.canonical_resolution_key,
      target_resolution.id AS target_resolution_id
  )
  INSERT INTO public.audit_events (
    actor_user_id,
    object_type,
    object_id_text,
    action,
    before_json,
    after_json,
    reason
  )
  SELECT
    p_actor_user_id,
    'BANKING_PAY_CASE_RESOLUTION_CARRY',
    superseded_carry.id::text,
    'CARRY_SUPERSEDED',
    jsonb_build_object(
      'status',
      'STALE_OR_PENDING'
    ),
    jsonb_build_object(
      'status',
      'SUPERSEDED',
      'source_session_id',
      superseded_carry.source_session_id,
      'source_resolution_id',
      superseded_carry.source_resolution_id,
      'canonical_resolution_key',
      superseded_carry.canonical_resolution_key,
      'target_resolution_id',
      superseded_carry.target_resolution_id,
      'state_reason_code',
      'TARGET_AUTHORITATIVE_DECISION_EXISTS'
    ),
    'TARGET_AUTHORITATIVE_DECISION_EXISTS'
  FROM superseded_carry;

  UPDATE public.banking_pay_workbench_sessions
  SET version = public.banking_pay_workbench_sessions.version + 1,
      progress_counter_version = COALESCE(public.banking_pay_workbench_sessions.progress_counter_version, 0) + 1,
      progress_updated_at_utc = v_now,
      updated_at_utc = v_now
  WHERE public.banking_pay_workbench_sessions.id = p_session_id
  RETURNING public.banking_pay_workbench_sessions.version, public.banking_pay_workbench_sessions.progress_counter_version
  INTO v_new_session_version, v_new_progress_counter_version;

  IF v_resolution_family = 'BUCKETED' THEN
    SELECT COALESCE(array_agg(DISTINCT target_resolution.timesheet_id ORDER BY target_resolution.timesheet_id), ARRAY[]::uuid[])
    INTO v_case_targeted_timesheet_ids
    FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution;

    SELECT COALESCE(array_agg(DISTINCT target_resolution.timesheet_id ORDER BY target_resolution.timesheet_id), ARRAY[]::uuid[])
    INTO v_case_linked_timesheet_ids
    FROM _tmp_bpay_session_target_bucket_resolution AS target_resolution
    WHERE target_resolution.timesheet_id <> v_anchor_timesheet_id;

    IF COALESCE(array_length(v_case_targeted_timesheet_ids, 1), 0) = 0 THEN
      RAISE EXCEPTION 'WORKBENCH_RESOLUTION_REFRESH_SCOPE_EMPTY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORKBENCH_RESOLUTION_REFRESH_SCOPE_EMPTY',
                'session_id', p_session_id::text,
                'candidate_id', COALESCE(v_resolved_candidate_id, v_candidate_id)::text,
                'case_key', v_case_key,
                'resolution_family', v_resolution_family
              )::text;
    END IF;

    v_case_refresh_scope_kind := 'TARGETED_TIMESHEETS';
  ELSE
    SELECT COALESCE(array_agg(DISTINCT case_timesheet_ids.timesheet_id ORDER BY case_timesheet_ids.timesheet_id), ARRAY[]::uuid[])
    INTO v_case_targeted_timesheet_ids
    FROM (
      SELECT v_linked_timesheet_id AS timesheet_id
      UNION ALL
      SELECT v_anchor_timesheet_id AS timesheet_id
      UNION ALL
      SELECT unnest(COALESCE(v_matching_timesheet_ids, ARRAY[]::uuid[])) AS timesheet_id
    ) AS case_timesheet_ids
    WHERE case_timesheet_ids.timesheet_id IS NOT NULL;

    IF COALESCE(array_length(v_case_targeted_timesheet_ids, 1), 0) > 0 THEN
      SELECT COALESCE(array_agg(DISTINCT rotation_scope.family_timesheet_id ORDER BY rotation_scope.family_timesheet_id), ARRAY[]::uuid[])
      INTO v_case_linked_timesheet_ids
      FROM public._pay_timesheet_rotation_scope(v_case_targeted_timesheet_ids) AS rotation_scope
      WHERE rotation_scope.family_timesheet_id IS NOT NULL
        AND NOT (rotation_scope.family_timesheet_id = ANY(v_case_targeted_timesheet_ids));

      v_case_refresh_scope_kind := 'TARGETED_TIMESHEETS';
    ELSE
      v_case_linked_timesheet_ids := ARRAY[]::uuid[];
      v_case_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    END IF;
  END IF;

  -- Applying any case resolution advances the session version. Rebuild the
  -- complete affected candidate so independent ready lines and the candidate-
  -- wide recovery headroom remain on that same version. A targeted rebuild
  -- would correctly refresh the resolved chain but leave unrelated candidate
  -- lines on the previous version, making them disappear from the preview.
  v_case_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';

  v_job_json := public.pay_workbench_enqueue_session_candidate_refresh(
    p_session_id => p_session_id,
    p_candidate_id => COALESCE(v_resolved_candidate_id, v_candidate_id),
    p_reason => v_action,
    p_actor_user_id => p_actor_user_id,
    p_payload_json => jsonb_build_object(
      'case_key', v_case_key,
      'resolution_family', v_resolution_family,
      'finance_case_id', CASE WHEN v_finance_case_id_text = '' THEN NULL ELSE v_finance_case_id_text END,
      'linked_timesheet_id', CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END,
      'resolution_identity_keys', v_resolution_identity_keys,
      'force_legacy', true,
      'projection_class', 'CASE_RESOLUTION',
      'fallback_reason', 'CASE_RESOLUTION_CHANGED',
      'refresh_scope_kind', v_case_refresh_scope_kind,
      -- A case-resolution save advances the whole candidate to a new session
      -- version.  Do not let the affected-row evidence below silently turn
      -- that rebuild back into a targeted refresh: later source pages may
      -- contain other members required to prove a correction-chain residual.
      'targeted_timesheet_ids', CASE
        WHEN v_case_refresh_scope_kind = 'CANDIDATE_FULL_LIVE' THEN '[]'::jsonb
        ELSE COALESCE(to_jsonb(v_case_targeted_timesheet_ids), '[]'::jsonb)
      END,
      'linked_timesheet_ids', CASE
        WHEN v_case_refresh_scope_kind = 'CANDIDATE_FULL_LIVE' THEN '[]'::jsonb
        ELSE COALESCE(to_jsonb(v_case_linked_timesheet_ids), '[]'::jsonb)
      END,
      'source_build_required', true,
      'line_work_required', true,
      'delta_refresh_required', false
    )
  );

  v_job_id_text := COALESCE(
    NULLIF(BTRIM(v_job_json->>'job_id'), ''),
    NULLIF(BTRIM(v_job_json#>>'{enqueue_result,job_id}'), ''),
    NULLIF(BTRIM(v_job_json#>>'{enqueue_result,job_ids,0}'), ''),
    NULLIF(BTRIM(v_job_json#>>'{job_ids,0}'), ''),
    NULLIF(BTRIM(v_job_json#>>'{enqueue_result,session_recompute_job_ids,0}'), ''),
    NULLIF(BTRIM(v_job_json#>>'{session_recompute_job_ids,0}'), '')
  );

  IF v_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_job_id := v_job_id_text::uuid;
  END IF;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_REFRESH_JOB_NOT_PROVEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_REFRESH_JOB_NOT_PROVEN',
              'session_id', p_session_id::text,
              'candidate_id', COALESCE(v_resolved_candidate_id, v_candidate_id)::text,
              'case_key', v_case_key,
              'resolution_family', v_resolution_family,
              'enqueue_ok', COALESCE(v_job_json->>'ok', ''),
              'enqueue_job_type', NULLIF(BTRIM(COALESCE(v_job_json->>'job_type', v_job_json#>>'{enqueue_result,job_type}', '')), ''),
              'enqueue_candidate_count', NULLIF(BTRIM(COALESCE(v_job_json->>'candidate_count', '')), '')
            )::text;
  END IF;

  -- The decision advances the session version, so every scoped candidate must
  -- either be physically current on that version or enter the existing
  -- canonical refresh ladder.  The affected candidate already has an active
  -- owner above; this established session owner observes it and enqueues only
  -- the remaining non-current candidates.
  LOOP
    v_session_refresh_page :=
      public.pay_workbench_session_refresh_current_authority_v1(
        p_session_id,
        p_actor_user_id,
        v_session_refresh_cursor,
        100
      );
    IF jsonb_typeof(v_session_refresh_page) IS DISTINCT FROM 'object'
       OR COALESCE((v_session_refresh_page->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_REFRESH_NOT_PROVEN'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','WORKBENCH_SESSION_VERSION_REFRESH_NOT_PROVEN',
          'session_id',p_session_id,
          'page_number',v_session_refresh_page_count+1
        )::text;
    END IF;
    v_session_refresh_pages:=v_session_refresh_pages
      ||jsonb_build_array(v_session_refresh_page);
    v_session_refresh_page_count:=v_session_refresh_page_count+1;
    EXIT WHEN COALESCE((v_session_refresh_page->>'has_more')::boolean,false)
      IS NOT TRUE;
    IF v_session_refresh_page_count>=1000
       OR jsonb_typeof(v_session_refresh_page->'next_cursor') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'WORKBENCH_SESSION_VERSION_REFRESH_CURSOR_INVALID'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','WORKBENCH_SESSION_VERSION_REFRESH_CURSOR_INVALID',
          'session_id',p_session_id,
          'page_number',v_session_refresh_page_count
        )::text;
    END IF;
    v_session_refresh_cursor:=v_session_refresh_page->'next_cursor';
  END LOOP;


  SELECT COALESCE(
           jsonb_agg(
             jsonb_strip_nulls(
               jsonb_build_object(
                 'resolution_id', origin_row.id::text,
                 'resolution_identity_key', origin_row.resolution_identity_key,
                 'origin_session_id', origin_row.resolution_origin_session_id::text,
                 'origin_pay_date', origin_row.resolution_origin_pay_date::text,
                 'origin_source_basis_fingerprint', origin_row.resolution_origin_source_basis_fingerprint
               )
             )
             ORDER BY origin_row.resolution_identity_key, origin_row.id
           ),
           '[]'::jsonb
         ),
         COUNT(*)::integer,
         CASE WHEN COUNT(*) = 1 THEN (array_agg(origin_row.resolution_origin_session_id ORDER BY origin_row.resolution_origin_session_id))[1] ELSE NULL::uuid END,
         CASE WHEN COUNT(*) = 1 THEN MIN(origin_row.resolution_origin_pay_date) ELSE NULL::date END
  INTO v_resolution_origins_json,
       v_resolution_origin_count,
       v_single_resolution_origin_session_id,
       v_single_resolution_origin_pay_date
  FROM public.banking_pay_workbench_session_case_resolutions AS origin_row
  JOIN (
    SELECT DISTINCT resolution_id_text.value::uuid AS resolution_id
    FROM jsonb_array_elements_text(COALESCE(v_case_resolution_ids, '[]'::jsonb)) AS resolution_id_text(value)
    WHERE resolution_id_text.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS selected_resolution
    ON selected_resolution.resolution_id = origin_row.id;

  IF v_resolution_family IN ('BUCKETED', 'NON_BUCKET')
     AND v_resolution_origin_count <> jsonb_array_length(COALESCE(v_case_resolution_ids, '[]'::jsonb)) THEN
    RAISE EXCEPTION 'WORKBENCH_RESOLUTION_ORIGIN_NOT_PROVEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_RESOLUTION_ORIGIN_NOT_PROVEN',
              'session_id', p_session_id::text,
              'case_key', v_case_key,
              'resolution_family', v_resolution_family,
              'resolution_count', jsonb_array_length(COALESCE(v_case_resolution_ids, '[]'::jsonb)),
              'origin_count', v_resolution_origin_count,
              'message', 'The immutable origin of one or more Banking Pay resolutions could not be verified.'
            )::text;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', COALESCE(v_resolved_candidate_id, v_candidate_id)::text,
    'session_version', v_new_session_version,
    'progress_counter_version', v_new_progress_counter_version,
    'job_id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END,
    'case_resolution_id', v_case_resolution_id_text,
    'case_resolution_ids', v_case_resolution_ids,
    'resolution_identity_keys', v_resolution_identity_keys,
    'case_resolution_count', jsonb_array_length(v_case_resolution_ids),
    'resolution_origins', v_resolution_origins_json,
    'resolution_origin_count', v_resolution_origin_count,
    'resolution_origin_session_id', CASE WHEN v_single_resolution_origin_session_id IS NULL THEN NULL ELSE v_single_resolution_origin_session_id::text END,
    'resolution_origin_pay_date', CASE WHEN v_single_resolution_origin_pay_date IS NULL THEN NULL ELSE v_single_resolution_origin_pay_date::text END,
    'anchor_component_count', CASE WHEN v_resolution_family = 'BUCKETED' THEN v_anchor_component_count ELSE NULL END,
    'anchor_timesheet_id', CASE WHEN v_resolution_family = 'BUCKETED' AND v_anchor_timesheet_id IS NOT NULL THEN v_anchor_timesheet_id::text ELSE NULL END,
    'eligible_linked_timesheet_ids', CASE WHEN v_resolution_family = 'BUCKETED' THEN COALESCE(to_jsonb(v_eligible_linked_timesheet_ids), '[]'::jsonb) ELSE NULL END,
    'eligible_linked_timesheet_count', CASE WHEN v_resolution_family = 'BUCKETED' THEN v_linked_target_timesheet_count ELSE NULL END,
    'total_affected_timesheet_count', CASE WHEN v_resolution_family = 'BUCKETED' THEN v_total_affected_timesheet_count ELSE NULL END,
    'excluded_linked_timesheets', CASE WHEN v_resolution_family = 'BUCKETED' THEN COALESCE(v_excluded_linked_timesheets, '[]'::jsonb) ELSE NULL END,
    'excluded_linked_timesheet_count', CASE WHEN v_resolution_family = 'BUCKETED' THEN v_excluded_linked_timesheet_count ELSE NULL END,
    'linked_target_timesheet_count', CASE WHEN v_resolution_family = 'BUCKETED' THEN v_linked_target_timesheet_count ELSE NULL END,
    'linked_target_component_count', CASE WHEN v_resolution_family = 'BUCKETED' THEN v_linked_target_component_count ELSE NULL END,
    'materialized_target_timesheet_count', CASE WHEN v_resolution_family = 'BUCKETED' THEN v_materialized_target_timesheet_count ELSE NULL END,
    'skipped_mismatch_count', CASE WHEN v_resolution_family = 'BUCKETED' THEN v_skipped_mismatch_count ELSE NULL END,
    'state_changed', true,
    'action', v_action,
    'refresh_scope_kind', v_case_refresh_scope_kind,
    'targeted_timesheet_ids', COALESCE(to_jsonb(v_case_targeted_timesheet_ids), '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(to_jsonb(v_case_linked_timesheet_ids), '[]'::jsonb),
    'targeted_refresh_enqueued', (v_job_id IS NOT NULL),
    'session_version_refresh_pages',v_session_refresh_pages,
    'session_version_refresh_page_count',v_session_refresh_page_count,
    'legacy_refresh_enqueued', CASE
      WHEN COALESCE(v_job_json->>'legacy_queued_count', '') ~ '^[0-9]+$' THEN (v_job_json->>'legacy_queued_count')::integer > 0
      ELSE upper(btrim(coalesce(v_job_json->>'job_type', v_job_json#>>'{enqueue_result,job_type}', ''))) <> 'WORKBENCH_CANDIDATE_DELTA_REFRESH'
    END,
    'enqueue_result', jsonb_strip_nulls(
      jsonb_build_object(
        'job_id', v_job_id::text,
        'job_type', NULLIF(BTRIM(COALESCE(v_job_json->>'job_type', v_job_json#>>'{enqueue_result,job_type}', '')), ''),
        'delta_queued_count', CASE WHEN COALESCE(v_job_json->>'delta_queued_count', '') ~ '^[0-9]+$' THEN (v_job_json->>'delta_queued_count')::integer ELSE NULL END,
        'legacy_queued_count', CASE WHEN COALESCE(v_job_json->>'legacy_queued_count', '') ~ '^[0-9]+$' THEN (v_job_json->>'legacy_queued_count')::integer ELSE NULL END,
        'candidate_count', CASE WHEN COALESCE(v_job_json->>'candidate_count', '') ~ '^[0-9]+$' THEN (v_job_json->>'candidate_count')::integer ELSE NULL END,
        'paged', CASE WHEN lower(btrim(coalesce(v_job_json->>'paged', ''))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN true WHEN NULLIF(BTRIM(COALESCE(v_job_json->>'paged', '')), '') IS NOT NULL THEN false ELSE NULL END
      )
    ),
    'durable_result', CASE WHEN v_resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' THEN v_taxable_result_json ELSE NULL END
  );
END;
$function$;

-- pay_workbench_session_apply_decision_operations(uuid,uuid,jsonb,bigint)
CREATE OR REPLACE FUNCTION public.pay_workbench_session_apply_decision_operations(p_session_id uuid, p_actor_user_id uuid, p_operation_plan_json jsonb, p_expected_session_version bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_plan_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_operation_plan_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(p_operation_plan_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_clear_operations_json jsonb := '[]'::jsonb;
  v_apply_operations_json jsonb := '[]'::jsonb;
  v_decision_operations_json jsonb := '[]'::jsonb;
  v_selected_preview_row_ids_json jsonb := '[]'::jsonb;
  v_selected_rows_provided boolean := false;
  v_expected_session_version bigint := p_expected_session_version;
  v_expected_progress_counter_version bigint := NULL::bigint;
  v_plan_expected_session_version_text text := NULL::text;
  v_plan_expected_progress_counter_version_text text := NULL::text;
  v_unchanged_case_resolution_count integer := 0;
  v_unchanged_case_resolution_count_text text := NULL::text;
  v_initial_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_final_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_current_session_version bigint := 0;
  v_current_progress_counter_version bigint := 0;
  v_operation_row record;
  v_operation_result jsonb := '{}'::jsonb;
  v_cleared_results_json jsonb := '[]'::jsonb;
  v_applied_results_json jsonb := '[]'::jsonb;
  v_decision_results_json jsonb := '[]'::jsonb;
  v_selected_rows_result_json jsonb := NULL::jsonb;
  v_touched_candidate_ids text[] := ARRAY[]::text[];
  v_job_ids text[] := ARRAY[]::text[];
  v_candidate_id_text text := NULL::text;
  v_job_id_text text := NULL::text;
  v_state_changed boolean := false;
  v_clear_operation_count integer := 0;
  v_apply_operation_count integer := 0;
  v_decision_operation_count integer := 0;
  v_decision_ordinality bigint := 0;
  v_decision_json jsonb := '{}'::jsonb;
  v_decision_type text := NULL::text;
  v_decision_candidate_id uuid := NULL::uuid;
  v_decision_candidate_id_text text := NULL::text;
  v_decision_timesheet_id_text text := NULL::text;
  v_decision_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_decision_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_decision_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_decision_projection_class text := 'UNKNOWN_TRIGGER';
  v_decision_projection_mode text := 'LEGACY';
  v_decision_force_legacy boolean := true;
  v_decision_fallback_reason text := 'UNKNOWN_DECISION_OPERATION';
  v_decision_affects_economic_key boolean := false;
  v_decision_affects_amount boolean := false;
  v_decision_affects_section boolean := false;
  v_decision_economic_rows_unchanged boolean := false;
  v_decision_override_mode text := NULL::text;
  v_decision_adjustment_type text := NULL::text;
  v_decision_enqueue_result jsonb := '{}'::jsonb;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_SESSION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_SESSION_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_ACTOR_REQUIRED', 'session_id', p_session_id::text)::text;
  END IF;

  IF p_operation_plan_json IS NULL OR jsonb_typeof(p_operation_plan_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_PLAN_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_PLAN_MUST_BE_OBJECT', 'session_id', p_session_id::text)::text;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_ACTOR_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_ACTOR_NOT_FOUND', 'session_id', p_session_id::text, 'actor_user_id', p_actor_user_id::text)::text;
  END IF;

  v_clear_operations_json := CASE
    WHEN NOT (v_operation_plan_json ? 'clear_case_resolutions') THEN '[]'::jsonb
    WHEN jsonb_typeof(v_operation_plan_json->'clear_case_resolutions') = 'array' THEN COALESCE(v_operation_plan_json->'clear_case_resolutions', '[]'::jsonb)
    ELSE NULL::jsonb
  END;

  IF v_clear_operations_json IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_CLEAR_LIST_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_CLEAR_LIST_INVALID', 'session_id', p_session_id::text, 'field', 'clear_case_resolutions')::text;
  END IF;

  v_apply_operations_json := CASE
    WHEN NOT (v_operation_plan_json ? 'apply_case_resolutions') THEN '[]'::jsonb
    WHEN jsonb_typeof(v_operation_plan_json->'apply_case_resolutions') = 'array' THEN COALESCE(v_operation_plan_json->'apply_case_resolutions', '[]'::jsonb)
    ELSE NULL::jsonb
  END;

  IF v_apply_operations_json IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_APPLY_LIST_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_APPLY_LIST_INVALID', 'session_id', p_session_id::text, 'field', 'apply_case_resolutions')::text;
  END IF;

  v_decision_operations_json := '[]'::jsonb
    || CASE WHEN jsonb_typeof(v_operation_plan_json->'decision_operations') = 'array' THEN COALESCE(v_operation_plan_json->'decision_operations', '[]'::jsonb) ELSE '[]'::jsonb END
    || CASE WHEN jsonb_typeof(v_operation_plan_json->'operations') = 'array' THEN COALESCE(v_operation_plan_json->'operations', '[]'::jsonb) ELSE '[]'::jsonb END
    || CASE WHEN jsonb_typeof(v_operation_plan_json->'snooze_operations') = 'array' THEN COALESCE(v_operation_plan_json->'snooze_operations', '[]'::jsonb) ELSE '[]'::jsonb END
    || CASE WHEN jsonb_typeof(v_operation_plan_json->'exclusion_operations') = 'array' THEN COALESCE(v_operation_plan_json->'exclusion_operations', '[]'::jsonb) ELSE '[]'::jsonb END
    || CASE WHEN jsonb_typeof(v_operation_plan_json->'override_operations') = 'array' THEN COALESCE(v_operation_plan_json->'override_operations', '[]'::jsonb) ELSE '[]'::jsonb END
    || CASE WHEN jsonb_typeof(v_operation_plan_json->'adjustment_operations') = 'array' THEN COALESCE(v_operation_plan_json->'adjustment_operations', '[]'::jsonb) ELSE '[]'::jsonb END;

  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_clear_operations_json) AS clear_operation(operation_json) WHERE jsonb_typeof(clear_operation.operation_json) <> 'object') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_CLEAR_ENTRY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_CLEAR_ENTRY_INVALID', 'session_id', p_session_id::text, 'field', 'clear_case_resolutions')::text;
  END IF;

  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_apply_operations_json) AS apply_operation(operation_json) WHERE jsonb_typeof(apply_operation.operation_json) <> 'object') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_APPLY_ENTRY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_APPLY_ENTRY_INVALID', 'session_id', p_session_id::text, 'field', 'apply_case_resolutions')::text;
  END IF;

  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_decision_operations_json) AS decision_operation(operation_json) WHERE jsonb_typeof(decision_operation.operation_json) <> 'object') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_DECISION_ENTRY_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_DECISION_ENTRY_INVALID', 'session_id', p_session_id::text, 'field', 'decision_operations')::text;
  END IF;

  IF v_operation_plan_json ? 'selected_rows_provided' THEN
    IF jsonb_typeof(v_operation_plan_json->'selected_rows_provided') <> 'boolean' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_SELECTED_ROWS_FLAG_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_SELECTED_ROWS_FLAG_INVALID', 'session_id', p_session_id::text, 'field', 'selected_rows_provided')::text;
    END IF;
    v_selected_rows_provided := (v_operation_plan_json->>'selected_rows_provided')::boolean;
  END IF;

  IF v_operation_plan_json ? 'selected_preview_row_ids' THEN
    IF jsonb_typeof(v_operation_plan_json->'selected_preview_row_ids') <> 'array' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_SELECTED_ROWS_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_SELECTED_ROWS_INVALID', 'session_id', p_session_id::text, 'field', 'selected_preview_row_ids')::text;
    END IF;
    v_selected_preview_row_ids_json := COALESCE(v_operation_plan_json->'selected_preview_row_ids', '[]'::jsonb);
  ELSIF v_selected_rows_provided THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_SELECTED_ROWS_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_SELECTED_ROWS_REQUIRED', 'session_id', p_session_id::text, 'field', 'selected_preview_row_ids')::text;
  END IF;

  v_plan_expected_session_version_text := NULLIF(BTRIM(COALESCE(v_operation_plan_json->>'expected_session_version', '')), '');
  IF v_plan_expected_session_version_text IS NOT NULL THEN
    IF v_plan_expected_session_version_text !~ '^[0-9]{1,18}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_EXPECTED_VERSION_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_EXPECTED_VERSION_INVALID', 'session_id', p_session_id::text, 'expected_session_version', v_plan_expected_session_version_text)::text;
    END IF;
    IF v_expected_session_version IS NOT NULL AND v_expected_session_version IS DISTINCT FROM v_plan_expected_session_version_text::bigint THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_EXPECTED_VERSION_CONFLICT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_EXPECTED_VERSION_CONFLICT', 'session_id', p_session_id::text, 'parameter_expected_session_version', v_expected_session_version, 'plan_expected_session_version', v_plan_expected_session_version_text::bigint)::text;
    END IF;
    v_expected_session_version := v_plan_expected_session_version_text::bigint;
  END IF;

  IF v_expected_session_version IS NULL OR v_expected_session_version < 1 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_EXPECTED_VERSION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_EXPECTED_VERSION_REQUIRED', 'session_id', p_session_id::text)::text;
  END IF;

  v_plan_expected_progress_counter_version_text := NULLIF(BTRIM(COALESCE(
    v_operation_plan_json->>'expected_progress_counter_version',
    v_operation_plan_json->>'expectedProgressCounterVersion',
    v_operation_plan_json->>'progress_counter_version',
    v_operation_plan_json->>'progressCounterVersion',
    ''
  )), '');

  IF v_plan_expected_progress_counter_version_text IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_PROGRESS_CONTEXT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_PROGRESS_CONTEXT_REQUIRED',
              'session_id', p_session_id::text,
              'message', 'The Banking Pay decision update was missing the current progress version. Refresh the preview before changing the workbench.'
            )::text;
  END IF;

  IF v_plan_expected_progress_counter_version_text !~ '^[0-9]{1,18}$' THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_PROGRESS_CONTEXT_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_PROGRESS_CONTEXT_INVALID',
              'session_id', p_session_id::text,
              'provided_progress_counter_version', v_plan_expected_progress_counter_version_text
            )::text;
  END IF;

  v_expected_progress_counter_version := v_plan_expected_progress_counter_version_text::bigint;

  v_unchanged_case_resolution_count_text := NULLIF(BTRIM(COALESCE(v_operation_plan_json->>'unchanged_case_resolution_count', '')), '');
  IF v_unchanged_case_resolution_count_text IS NOT NULL THEN
    IF v_unchanged_case_resolution_count_text !~ '^[0-9]{1,9}$' THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_UNCHANGED_COUNT_INVALID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_UNCHANGED_COUNT_INVALID', 'session_id', p_session_id::text, 'unchanged_case_resolution_count', v_unchanged_case_resolution_count_text)::text;
    END IF;
    v_unchanged_case_resolution_count := v_unchanged_case_resolution_count_text::integer;
  END IF;

  SELECT session_row.*
  INTO v_initial_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_SESSION_NOT_FOUND', 'session_id', p_session_id::text)::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_initial_session_row.status, ''))) <> 'OPEN' OR v_initial_session_row.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_SESSION_NOT_OPEN', 'session_id', p_session_id::text, 'status', v_initial_session_row.status, 'discarded_at_utc', v_initial_session_row.discarded_at_utc)::text;
  END IF;

  IF v_initial_session_row.version IS DISTINCT FROM v_expected_session_version THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_VERSION_CONFLICT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_VERSION_CONFLICT', 'session_id', p_session_id::text, 'expected_session_version', v_expected_session_version, 'actual_session_version', v_initial_session_row.version)::text;
  END IF;

  IF COALESCE(v_initial_session_row.progress_counter_version, 0) IS DISTINCT FROM v_expected_progress_counter_version THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_PROGRESS_CHANGED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_SESSION_PROGRESS_CHANGED',
              'session_id', p_session_id::text,
              'expected_progress_counter_version', v_expected_progress_counter_version,
              'current_progress_counter_version', COALESCE(v_initial_session_row.progress_counter_version, 0),
              'message', 'The Banking Pay workbench changed in another window. Refresh the preview before applying these decisions.'
            )::text;
  END IF;

  v_current_session_version := COALESCE(v_initial_session_row.version, 0);
  v_current_progress_counter_version := COALESCE(v_initial_session_row.progress_counter_version, 0);

  v_clear_operation_count := jsonb_array_length(v_clear_operations_json);
  v_apply_operation_count := jsonb_array_length(v_apply_operations_json);
  v_decision_operation_count := jsonb_array_length(v_decision_operations_json);

  FOR v_operation_row IN
    SELECT clear_operation.operation_json, clear_operation.operation_ordinality
    FROM jsonb_array_elements(v_clear_operations_json) WITH ORDINALITY AS clear_operation(operation_json, operation_ordinality)
    ORDER BY clear_operation.operation_ordinality
  LOOP
    v_operation_result := public.pay_workbench_session_clear_case_resolution(
      p_session_id => p_session_id,
      p_actor_user_id => p_actor_user_id,
      p_resolution_payload_json => (
        CASE WHEN jsonb_typeof(COALESCE(v_operation_row.operation_json, '{}'::jsonb)) = 'object' THEN COALESCE(v_operation_row.operation_json, '{}'::jsonb) ELSE '{}'::jsonb END
        || jsonb_build_object(
          'expected_session_version', v_current_session_version,
          'expected_progress_counter_version', v_current_progress_counter_version
        )
      )
    );
    IF jsonb_typeof(COALESCE(v_operation_result, '{}'::jsonb)) <> 'object' OR LOWER(BTRIM(COALESCE(v_operation_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_CLEAR_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_CLEAR_FAILED', 'session_id', p_session_id::text, 'operation_ordinality', v_operation_row.operation_ordinality, 'operation_result', COALESCE(v_operation_result, '{}'::jsonb))::text;
    END IF;
    v_cleared_results_json := v_cleared_results_json || jsonb_build_array(v_operation_result);
    v_state_changed := v_state_changed OR LOWER(BTRIM(COALESCE(v_operation_result->>'state_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_candidate_id_text := NULLIF(BTRIM(COALESCE(v_operation_result->>'candidate_id', '')), '');
    IF v_candidate_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND NOT (v_candidate_id_text = ANY(v_touched_candidate_ids)) THEN
      v_touched_candidate_ids := array_append(v_touched_candidate_ids, v_candidate_id_text);
    END IF;
    v_job_id_text := NULLIF(BTRIM(COALESCE(v_operation_result->>'job_id', '')), '');
    IF v_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND NOT (v_job_id_text = ANY(v_job_ids)) THEN
      v_job_ids := array_append(v_job_ids, v_job_id_text);
    END IF;

    SELECT COALESCE(session_row.version, 0), COALESCE(session_row.progress_counter_version, 0)
    INTO v_current_session_version, v_current_progress_counter_version
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = p_session_id;
  END LOOP;

  FOR v_operation_row IN
    SELECT apply_operation.operation_json, apply_operation.operation_ordinality
    FROM jsonb_array_elements(v_apply_operations_json) WITH ORDINALITY AS apply_operation(operation_json, operation_ordinality)
    ORDER BY apply_operation.operation_ordinality
  LOOP
    v_operation_result := public.pay_workbench_session_apply_case_resolution(
      p_session_id => p_session_id,
      p_actor_user_id => p_actor_user_id,
      p_resolution_payload_json => (
        CASE WHEN jsonb_typeof(COALESCE(v_operation_row.operation_json, '{}'::jsonb)) = 'object' THEN COALESCE(v_operation_row.operation_json, '{}'::jsonb) ELSE '{}'::jsonb END
        || jsonb_build_object(
          'expected_session_version', v_current_session_version,
          'expected_progress_counter_version', v_current_progress_counter_version
        )
      )
    );
    IF jsonb_typeof(COALESCE(v_operation_result, '{}'::jsonb)) <> 'object' OR LOWER(BTRIM(COALESCE(v_operation_result->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_APPLY_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_APPLY_FAILED', 'session_id', p_session_id::text, 'operation_ordinality', v_operation_row.operation_ordinality, 'operation_result', COALESCE(v_operation_result, '{}'::jsonb))::text;
    END IF;
    v_applied_results_json := v_applied_results_json || jsonb_build_array(v_operation_result);
    v_state_changed := v_state_changed OR LOWER(BTRIM(COALESCE(v_operation_result->>'state_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_candidate_id_text := NULLIF(BTRIM(COALESCE(v_operation_result->>'candidate_id', '')), '');
    IF v_candidate_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND NOT (v_candidate_id_text = ANY(v_touched_candidate_ids)) THEN
      v_touched_candidate_ids := array_append(v_touched_candidate_ids, v_candidate_id_text);
    END IF;
    v_job_id_text := NULLIF(BTRIM(COALESCE(v_operation_result->>'job_id', '')), '');
    IF v_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND NOT (v_job_id_text = ANY(v_job_ids)) THEN
      v_job_ids := array_append(v_job_ids, v_job_id_text);
    END IF;

    SELECT COALESCE(session_row.version, 0), COALESCE(session_row.progress_counter_version, 0)
    INTO v_current_session_version, v_current_progress_counter_version
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = p_session_id;
  END LOOP;

  FOR v_operation_row IN
    SELECT decision_operation.operation_json, decision_operation.operation_ordinality
    FROM jsonb_array_elements(v_decision_operations_json) WITH ORDINALITY AS decision_operation(operation_json, operation_ordinality)
    ORDER BY decision_operation.operation_ordinality
  LOOP
    v_decision_json := v_operation_row.operation_json;
    v_decision_ordinality := v_operation_row.operation_ordinality;
    v_decision_type := UPPER(BTRIM(COALESCE(
      v_decision_json->>'operation_type',
      v_decision_json->>'operation',
      v_decision_json->>'decision_type',
      v_decision_json->>'type',
      v_decision_json->>'kind',
      'UNKNOWN_OPERATION'
    )));
    v_decision_override_mode := UPPER(BTRIM(COALESCE(v_decision_json->>'override_mode', v_decision_json->>'payment_override_mode', v_decision_json#>>'{override,mode}', '')));
    v_decision_adjustment_type := UPPER(BTRIM(COALESCE(v_decision_json->>'adjustment_type', v_decision_json->>'manual_adjustment_type', v_decision_json#>>'{adjustment,type}', '')));
    v_decision_affects_amount := LOWER(BTRIM(COALESCE(v_decision_json->>'affects_amount', v_decision_json->>'amount_changed', v_decision_json->>'economic_amount_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_decision_affects_economic_key := LOWER(BTRIM(COALESCE(v_decision_json->>'affects_economic_key', v_decision_json->>'economic_key_changed', v_decision_json->>'key_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_decision_affects_section := LOWER(BTRIM(COALESCE(v_decision_json->>'affects_section', v_decision_json->>'section_changed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
    v_decision_economic_rows_unchanged := LOWER(BTRIM(COALESCE(v_decision_json->>'economic_rows_unchanged', v_decision_json->>'economics_unchanged', v_decision_json->>'amount_and_key_unchanged', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

    SELECT COALESCE(jsonb_agg(target_ids.timesheet_id_text ORDER BY target_ids.timesheet_id_text), '[]'::jsonb)
    INTO v_decision_targeted_timesheet_ids_json
    FROM (
      SELECT DISTINCT NULLIF(BTRIM(timesheet_values.value), '') AS timesheet_id_text
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_decision_json->'targeted_timesheet_ids') = 'array' THEN v_decision_json->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_decision_json->'timesheet_ids') = 'array' THEN v_decision_json->'timesheet_ids'
          WHEN jsonb_typeof(v_decision_json->'affected_timesheet_ids') = 'array' THEN v_decision_json->'affected_timesheet_ids'
          ELSE '[]'::jsonb
        END
      ) AS timesheet_values(value)
      WHERE NULLIF(BTRIM(timesheet_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION
      SELECT NULLIF(BTRIM(COALESCE(v_decision_json->>'timesheet_id', v_decision_json->>'targeted_timesheet_id', v_decision_json->>'affected_timesheet_id', '')), '') AS timesheet_id_text
      WHERE NULLIF(BTRIM(COALESCE(v_decision_json->>'timesheet_id', v_decision_json->>'targeted_timesheet_id', v_decision_json->>'affected_timesheet_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS target_ids;

    SELECT COALESCE(jsonb_agg(linked_ids.timesheet_id_text ORDER BY linked_ids.timesheet_id_text), '[]'::jsonb)
    INTO v_decision_linked_timesheet_ids_json
    FROM (
      SELECT DISTINCT NULLIF(BTRIM(linked_values.value), '') AS timesheet_id_text
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_decision_json->'linked_timesheet_ids') = 'array' THEN v_decision_json->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_decision_json->'family_timesheet_ids') = 'array' THEN v_decision_json->'family_timesheet_ids'
          ELSE '[]'::jsonb
        END
      ) AS linked_values(value)
      WHERE NULLIF(BTRIM(linked_values.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS linked_ids;

    IF jsonb_array_length(COALESCE(v_decision_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 THEN
      SELECT COALESCE(jsonb_agg(rotation_rows.family_timesheet_id::text ORDER BY rotation_rows.family_timesheet_id::text), '[]'::jsonb)
      INTO v_decision_linked_timesheet_ids_json
      FROM (
        SELECT DISTINCT rotation_scope.family_timesheet_id
        FROM public._pay_timesheet_rotation_scope(
          ARRAY(
            SELECT targeted_value.value::uuid
            FROM jsonb_array_elements_text(v_decision_targeted_timesheet_ids_json) AS targeted_value(value)
            WHERE targeted_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          )
        ) AS rotation_scope
        WHERE rotation_scope.family_timesheet_id IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(v_decision_targeted_timesheet_ids_json) AS targeted_value(value)
            WHERE targeted_value.value::uuid = rotation_scope.family_timesheet_id
          )
        UNION
        SELECT linked_value.value::uuid
        FROM jsonb_array_elements_text(v_decision_linked_timesheet_ids_json) AS linked_value(value)
        WHERE linked_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ) AS rotation_rows;
    END IF;

    v_decision_candidate_id := NULL::uuid;
    v_decision_candidate_id_text := NULLIF(BTRIM(COALESCE(v_decision_json->>'candidate_id', v_decision_json#>>'{candidate,id}', '')), '');
    IF v_decision_candidate_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_decision_candidate_id := v_decision_candidate_id_text::uuid;
    ELSIF jsonb_array_length(COALESCE(v_decision_targeted_timesheet_ids_json, '[]'::jsonb)) > 0 THEN
      SELECT preview_row.candidate_id
      INTO v_decision_candidate_id
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id = p_session_id
        AND preview_row.session_version = v_initial_session_row.version
        AND preview_row.timesheet_id IN (
          SELECT targeted_value.value::uuid
          FROM jsonb_array_elements_text(v_decision_targeted_timesheet_ids_json) AS targeted_value(value)
          WHERE targeted_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        )
      ORDER BY preview_row.updated_at_utc DESC, preview_row.id DESC
      LIMIT 1;
    END IF;

    IF v_decision_candidate_id IS NULL THEN
      v_decision_results_json := v_decision_results_json || jsonb_build_array(jsonb_build_object(
        'ok', false,
        'operation_ordinality', v_decision_ordinality,
        'operation_type', v_decision_type,
        'skipped', true,
        'reason', 'CANDIDATE_SCOPE_MISSING'
      ));
      CONTINUE;
    END IF;

    v_decision_refresh_scope_kind := CASE
      WHEN jsonb_array_length(COALESCE(v_decision_targeted_timesheet_ids_json, '[]'::jsonb)) > 0
        OR jsonb_array_length(COALESCE(v_decision_linked_timesheet_ids_json, '[]'::jsonb)) > 0 THEN 'TARGETED_TIMESHEETS'
      ELSE 'CANDIDATE_FULL_LIVE'
    END;

    v_decision_force_legacy := true;
    v_decision_projection_mode := 'LEGACY';
    v_decision_projection_class := 'UNKNOWN_TRIGGER';
    v_decision_fallback_reason := 'UNKNOWN_DECISION_OPERATION';

    IF v_decision_type IN ('SNOOZE', 'SNOOZE_SET', 'SNOOZE_CLEAR', 'UNSNOOZE', 'READINESS_ONLY', 'READINESS_STATUS', 'PAYEE_READINESS', 'NAME_CHECK', 'BANK_NAME_CHECK', 'BLOCKER_ONLY', 'ROW_BLOCKER')
       AND v_decision_economic_rows_unchanged IS TRUE
       AND v_decision_affects_amount IS NOT TRUE
       AND v_decision_affects_economic_key IS NOT TRUE
       AND v_decision_affects_section IS NOT TRUE THEN
      v_decision_force_legacy := false;
      v_decision_projection_mode := 'READINESS_PATCH';
      v_decision_projection_class := 'READINESS_ONLY';
      v_decision_fallback_reason := NULL::text;
    ELSIF v_decision_type IN ('SNOOZE', 'SNOOZE_SET', 'SNOOZE_CLEAR', 'UNSNOOZE', 'READINESS_ONLY', 'READINESS_STATUS', 'PAYEE_READINESS', 'NAME_CHECK', 'BANK_NAME_CHECK', 'BLOCKER_ONLY', 'ROW_BLOCKER') THEN
      v_decision_projection_class := 'READINESS_ONLY';
      v_decision_fallback_reason := 'READINESS_OPERATION_ECONOMIC_REFRESH_REQUIRED';
    ELSIF v_decision_type IN ('RESERVATION', 'RESERVATION_ONLY', 'PAYMENT_RESERVATION', 'DRAFT_RESERVATION') AND v_decision_economic_rows_unchanged THEN
      v_decision_force_legacy := false;
      v_decision_projection_mode := 'RESERVATION_PATCH';
      v_decision_projection_class := 'RESERVATION_ONLY';
      v_decision_fallback_reason := NULL::text;
    ELSIF v_decision_type IN ('TIMESHEET_EXCLUSION', 'TIMESHEET_EXCLUDE', 'TIMESHEET_INCLUDE', 'TOGGLE_TIMESHEET_EXCLUSION', 'EXCLUDE_TIMESHEET', 'INCLUDE_TIMESHEET')
       AND v_decision_affects_amount IS NOT TRUE
       AND v_decision_affects_economic_key IS NOT TRUE
       AND v_decision_affects_section IS NOT TRUE
       AND COALESCE(v_decision_economic_rows_unchanged, false) THEN
      v_decision_force_legacy := false;
      v_decision_projection_mode := 'READINESS_PATCH';
      v_decision_projection_class := 'READINESS_ONLY';
      v_decision_fallback_reason := NULL::text;
    ELSIF v_decision_type IN ('TIMESHEET_EXCLUSION', 'TIMESHEET_EXCLUDE', 'TIMESHEET_INCLUDE', 'TOGGLE_TIMESHEET_EXCLUSION', 'EXCLUDE_TIMESHEET', 'INCLUDE_TIMESHEET') THEN
      v_decision_projection_class := 'TARGET_SCOPE_MISSING';
      v_decision_fallback_reason := 'TIMESHEET_EXCLUSION_ECONOMIC_REFRESH_REQUIRED';
    ELSIF v_decision_type IN ('PAYMENT_OVERRIDE', 'TIMESHEET_PAYMENT_OVERRIDE')
       AND v_decision_override_mode IN ('TIMESHEET_ADVANCE', 'ADVANCE_THIS_PAYMENT') THEN
      v_decision_projection_class := 'TIMESHEET_ADVANCE';
      v_decision_fallback_reason := 'TIMESHEET_ADVANCE_OVERRIDE_REQUIRES_LEGACY';
    ELSIF v_decision_type IN ('REPAYMENT', 'LOAN_REPAYMENT', 'ADVANCE_REPAYMENT') THEN
      v_decision_projection_class := 'REPAYMENT';
      v_decision_fallback_reason := 'REPAYMENT_REQUIRES_LEGACY';
    ELSIF v_decision_type IN ('LOAN', 'PAY_ADVANCE', 'ADVANCE', 'TIMESHEET_ADVANCE') THEN
      v_decision_projection_class := CASE WHEN v_decision_type = 'TIMESHEET_ADVANCE' THEN 'TIMESHEET_ADVANCE' ELSE 'PAY_ADVANCE' END;
      v_decision_fallback_reason := 'ADVANCE_OR_LOAN_REQUIRES_LEGACY';
    ELSIF v_decision_type IN ('MANUAL_CREDIT_ADJUSTMENT', 'MANUAL_DEBIT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_ADJUSTMENT', 'ADJUSTMENT')
       OR v_decision_adjustment_type IN ('MANUAL_CREDIT_ADJUSTMENT', 'MANUAL_DEBIT', 'MANUAL_DEBT_ADJUSTMENT', 'MANUAL_CREDIT', 'MANUAL_DEBIT') THEN
      v_decision_projection_class := CASE
        WHEN v_decision_adjustment_type IN ('MANUAL_CREDIT_ADJUSTMENT', 'MANUAL_DEBIT', 'MANUAL_DEBT_ADJUSTMENT') THEN v_decision_adjustment_type
        WHEN v_decision_type IN ('MANUAL_CREDIT_ADJUSTMENT', 'MANUAL_DEBIT', 'MANUAL_DEBT_ADJUSTMENT') THEN v_decision_type
        ELSE 'MANUAL_DEBT_ADJUSTMENT'
      END;
      v_decision_fallback_reason := 'MANUAL_ADJUSTMENT_REQUIRES_LEGACY';
    ELSE
      v_decision_projection_class := COALESCE(NULLIF(v_decision_type, ''), 'UNKNOWN_TRIGGER');
      v_decision_fallback_reason := 'UNKNOWN_DECISION_OPERATION';
    END IF;

    v_decision_enqueue_result := public.pay_workbench_enqueue_session_candidate_refresh(
      p_session_id => p_session_id,
      p_candidate_id => v_decision_candidate_id,
      p_reason => COALESCE(v_decision_fallback_reason, v_decision_type),
      p_actor_user_id => p_actor_user_id,
      p_payload_json => jsonb_strip_nulls(
        jsonb_build_object(
          'trigger_table', 'workbench_decision_operations',
          'trigger_operation', v_decision_type,
          'dirty_reason', v_decision_type,
          'operation_type', v_decision_type,
          'candidate_id', v_decision_candidate_id::text,
          'session_id', p_session_id::text,
          'source_session_id', p_session_id::text,
          'source_snapshot_run_id', CASE WHEN v_initial_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_initial_session_row.source_snapshot_run_id::text END,
          'session_version', COALESCE(v_initial_session_row.version, 0),
          'session_signature', v_initial_session_row.session_signature,
          'refresh_scope_kind', v_decision_refresh_scope_kind,
          'targeted_timesheet_ids', COALESCE(v_decision_targeted_timesheet_ids_json, '[]'::jsonb),
          'linked_timesheet_ids', COALESCE(v_decision_linked_timesheet_ids_json, '[]'::jsonb),
          'force_legacy', v_decision_force_legacy,
          'projection_mode', v_decision_projection_mode,
          'projection_class', v_decision_projection_class,
          'fallback_reason', v_decision_fallback_reason
        )
        || CASE
          WHEN v_decision_force_legacy THEN jsonb_build_object(
            'source_build_required', true,
            'line_work_required', true,
            'delta_refresh_required', false,
            'complex_refresh_required', true,
            'resolved_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD',
            'fast_path_allowed', false
          )
          ELSE jsonb_build_object(
            'source_build_required', false,
            'line_work_required', false,
            'delta_refresh_required', true,
            'fallback_required', false
          )
        END
      )
    );

    v_decision_results_json := v_decision_results_json || jsonb_build_array(
      jsonb_build_object(
        'ok', true,
        'operation_ordinality', v_decision_ordinality,
        'operation_type', v_decision_type,
        'candidate_id', v_decision_candidate_id::text,
        'projection_mode', v_decision_projection_mode,
        'projection_class', v_decision_projection_class,
        'force_legacy', v_decision_force_legacy,
        'fallback_reason', v_decision_fallback_reason,
        'targeted_timesheet_ids', COALESCE(v_decision_targeted_timesheet_ids_json, '[]'::jsonb),
        'linked_timesheet_ids', COALESCE(v_decision_linked_timesheet_ids_json, '[]'::jsonb),
        'refresh_scope_kind', v_decision_refresh_scope_kind,
        'enqueue_result', COALESCE(v_decision_enqueue_result, '{}'::jsonb)
      )
    );
    v_state_changed := true;

    v_candidate_id_text := v_decision_candidate_id::text;
    IF NOT (v_candidate_id_text = ANY(v_touched_candidate_ids)) THEN
      v_touched_candidate_ids := array_append(v_touched_candidate_ids, v_candidate_id_text);
    END IF;
    v_job_id_text := NULLIF(BTRIM(COALESCE(v_decision_enqueue_result->>'job_id', '')), '');
    IF v_job_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND NOT (v_job_id_text = ANY(v_job_ids)) THEN
      v_job_ids := array_append(v_job_ids, v_job_id_text);
    END IF;
  END LOOP;

  IF v_selected_rows_provided THEN
    SELECT COALESCE(session_row.version, 0), COALESCE(session_row.progress_counter_version, 0)
    INTO v_current_session_version, v_current_progress_counter_version
    FROM public.banking_pay_workbench_sessions AS session_row
    WHERE session_row.id = p_session_id;

    v_selected_rows_result_json := public.pay_workbench_session_set_selected_rows(
      p_session_id => p_session_id,
      p_selected_preview_row_ids => jsonb_build_object(
        'selected_preview_row_ids', COALESCE(v_selected_preview_row_ids_json, '[]'::jsonb),
        'expected_session_version', v_current_session_version,
        'expected_progress_counter_version', v_current_progress_counter_version
      ),
      p_actor_user_id => p_actor_user_id
    );
    IF jsonb_typeof(COALESCE(v_selected_rows_result_json, '{}'::jsonb)) <> 'object' OR LOWER(BTRIM(COALESCE(v_selected_rows_result_json->>'ok', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_SELECTION_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_SELECTION_FAILED', 'session_id', p_session_id::text, 'operation_result', COALESCE(v_selected_rows_result_json, '{}'::jsonb))::text;
    END IF;
    v_state_changed := true;
  END IF;

  SELECT session_row.*
  INTO v_final_session_row
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DECISION_OPERATIONS_SESSION_LOST'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_DECISION_OPERATIONS_SESSION_LOST', 'session_id', p_session_id::text)::text;
  END IF;

  RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'snapshot_run_id', CASE WHEN v_final_session_row.source_snapshot_run_id IS NULL THEN NULL::text ELSE v_final_session_row.source_snapshot_run_id::text END,
      'source_snapshot_run_id', CASE WHEN v_final_session_row.source_snapshot_run_id IS NULL THEN NULL::text ELSE v_final_session_row.source_snapshot_run_id::text END,
      'expected_session_version', v_expected_session_version,
      'expected_progress_counter_version', v_expected_progress_counter_version,
      'initial_session_version', v_initial_session_row.version,
      'session_version', v_final_session_row.version,
      'progress_state', v_final_session_row.progress_state,
      'progress_counter_version', COALESCE(v_final_session_row.progress_counter_version, 0),
      'state_changed', v_state_changed,
      'applied_case_resolution_results', v_applied_results_json,
      'cleared_case_resolution_results', v_cleared_results_json,
      'decision_operation_results', v_decision_results_json,
      'unchanged_case_resolution_count', v_unchanged_case_resolution_count
    )
    || jsonb_build_object(
      'selected_rows_result', v_selected_rows_result_json,
      'selected_rows_provided', v_selected_rows_provided,
      'selected_preview_row_ids', CASE WHEN v_selected_rows_provided THEN v_selected_preview_row_ids_json ELSE NULL::jsonb END,
      'clear_operation_count', v_clear_operation_count,
      'apply_operation_count', v_apply_operation_count,
      'decision_operation_count', v_decision_operation_count,
      'touched_candidate_ids', to_jsonb(v_touched_candidate_ids),
      'job_ids', to_jsonb(v_job_ids),
      'operation_order', jsonb_build_array('CLEAR_CASE_RESOLUTIONS', 'APPLY_CASE_RESOLUTIONS', 'DECISION_OPERATIONS', 'SET_SELECTED_ROWS'),
      'network_rpc_fanout_performed', false
    );
END;
$function$;

-- pay_workbench_session_canonical_signature_v1(uuid,date,date,jsonb,text)
CREATE OR REPLACE FUNCTION public.pay_workbench_session_canonical_signature_v1(p_actor_user_id uuid, p_pay_date date, p_week_ending_cutoff date, p_filters_json jsonb, p_fallback_session_signature text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_filters jsonb := public.pay_workbench_filters_sanitise_v1(COALESCE(p_filters_json, '{}'::jsonb), p_pay_date, p_week_ending_cutoff);
  v_nested_filters jsonb := CASE WHEN jsonb_typeof(v_filters->'filters') = 'object' THEN COALESCE(v_filters->'filters', '{}'::jsonb) ELSE '{}'::jsonb END;
  v_nested_filter jsonb := CASE WHEN jsonb_typeof(v_filters->'filter') = 'object' THEN COALESCE(v_filters->'filter', '{}'::jsonb) ELSE '{}'::jsonb END;
  v_fallback_json jsonb := '{}'::jsonb;
  v_candidate_filter_id text := NULLIF(BTRIM(COALESCE(
    v_filters->>'candidate_filter_id',
    v_filters->>'candidateFilterId',
    v_filters->>'filter_candidate_id',
    v_nested_filters->>'candidate_filter_id',
    v_nested_filters->>'candidateFilterId',
    v_nested_filters->>'filter_candidate_id',
    v_nested_filter->>'candidate_filter_id',
    v_nested_filter->>'candidateFilterId',
    v_nested_filter->>'filter_candidate_id',
    v_fallback_json->>'candidate_filter_id',
    v_fallback_json->>'candidateFilterId',
    v_fallback_json->>'filter_candidate_id',
    ''
  )), '');
  v_client_filter_id text := NULLIF(BTRIM(COALESCE(
    v_filters->>'client_filter_id',
    v_filters->>'clientFilterId',
    v_filters->>'filter_client_id',
    v_filters->>'client_id',
    v_filters->>'clientId',
    v_nested_filters->>'client_filter_id',
    v_nested_filters->>'clientFilterId',
    v_nested_filters->>'filter_client_id',
    v_nested_filters->>'client_id',
    v_nested_filters->>'clientId',
    v_nested_filter->>'client_filter_id',
    v_nested_filter->>'clientFilterId',
    v_nested_filter->>'filter_client_id',
    v_nested_filter->>'client_id',
    v_nested_filter->>'clientId',
    v_fallback_json->>'client_filter_id',
    v_fallback_json->>'clientFilterId',
    v_fallback_json->>'filter_client_id',
    v_fallback_json->>'client_id',
    v_fallback_json->>'clientId',
    ''
  )), '');
  v_candidate_ids jsonb := '[]'::jsonb;
  v_effective_week_ending_cutoff date := COALESCE(p_week_ending_cutoff, DATE '9999-12-31');
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_SIGNATURE_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CANONICAL_SIGNATURE_ACTOR_REQUIRED')::text;
  END IF;

  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_CANONICAL_SIGNATURE_PAY_DATE_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_WORKBENCH_CANONICAL_SIGNATURE_PAY_DATE_REQUIRED')::text;
  END IF;

  WITH raw_candidate_ids(candidate_id_text) AS (
    SELECT NULLIF(BTRIM(v_filters->>'candidate_id'), '')
    UNION ALL SELECT NULLIF(BTRIM(v_filters->>'candidateId'), '')
    UNION ALL SELECT NULLIF(BTRIM(v_nested_filters->>'candidate_id'), '')
    UNION ALL SELECT NULLIF(BTRIM(v_nested_filters->>'candidateId'), '')
    UNION ALL SELECT NULLIF(BTRIM(v_nested_filter->>'candidate_id'), '')
    UNION ALL SELECT NULLIF(BTRIM(v_nested_filter->>'candidateId'), '')
    UNION ALL SELECT NULLIF(BTRIM(value), '')
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_filters->'candidate_ids') = 'array' THEN v_filters->'candidate_ids' ELSE '[]'::jsonb END) AS arr(value)
    UNION ALL SELECT NULLIF(BTRIM(value), '')
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_filters->'candidateIds') = 'array' THEN v_filters->'candidateIds' ELSE '[]'::jsonb END) AS arr(value)
    UNION ALL SELECT NULLIF(BTRIM(value), '')
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_nested_filters->'candidate_ids') = 'array' THEN v_nested_filters->'candidate_ids' ELSE '[]'::jsonb END) AS arr(value)
    UNION ALL SELECT NULLIF(BTRIM(value), '')
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_nested_filters->'candidateIds') = 'array' THEN v_nested_filters->'candidateIds' ELSE '[]'::jsonb END) AS arr(value)
    UNION ALL SELECT NULLIF(BTRIM(value), '')
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_nested_filter->'candidate_ids') = 'array' THEN v_nested_filter->'candidate_ids' ELSE '[]'::jsonb END) AS arr(value)
    UNION ALL SELECT NULLIF(BTRIM(value), '')
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_nested_filter->'candidateIds') = 'array' THEN v_nested_filter->'candidateIds' ELSE '[]'::jsonb END) AS arr(value)
    UNION ALL SELECT NULLIF(BTRIM(value), '')
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_fallback_json->'candidate_ids') = 'array' THEN v_fallback_json->'candidate_ids' ELSE '[]'::jsonb END) AS arr(value)
  ), valid_candidate_ids AS (
    SELECT DISTINCT LOWER(candidate_id_text) AS candidate_id_text
    FROM raw_candidate_ids
    WHERE candidate_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  )
  SELECT COALESCE(jsonb_agg(candidate_id_text ORDER BY candidate_id_text), '[]'::jsonb)
  INTO v_candidate_ids
  FROM valid_candidate_ids;

  RETURN jsonb_build_object(
    'candidate_filter_id', COALESCE(v_candidate_filter_id, ''),
    'candidate_ids', COALESCE(v_candidate_ids, '[]'::jsonb),
    'client_filter_id', COALESCE(v_client_filter_id, ''),
    'kind', 'BANKING_PAY_WORKBENCH',
    'pay_date', p_pay_date::text,
    'signature_version', 4,
    'week_ending_cutoff', v_effective_week_ending_cutoff::text
  )::text;
EXCEPTION
  WHEN invalid_text_representation THEN
    RETURN jsonb_build_object(
        'candidate_filter_id', COALESCE(v_candidate_filter_id, ''),
      'candidate_ids', COALESCE(v_candidate_ids, '[]'::jsonb),
      'client_filter_id', COALESCE(v_client_filter_id, ''),
      'kind', 'BANKING_PAY_WORKBENCH',
      'pay_date', p_pay_date::text,
      'signature_version', 4,
      'week_ending_cutoff', COALESCE(p_week_ending_cutoff, DATE '9999-12-31')::text
    )::text;
END;
$function$;

-- pay_workbench_session_carry_forward_case_resolutions_v1(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_session_carry_forward_case_resolutions_v1(p_source_session_id uuid, p_target_session_id uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_options jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_options_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(p_options_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_source record;
  v_target record;
  v_resolution record;
  v_actor_user_id uuid;
  v_carry_reason text := left(
    upper(
      coalesce(
        nullif(
          btrim(
            coalesce(
              v_options ->> 'carry_forward_reason',
              v_options ->> 'carryForwardReason',
              ''
            )
          ),
          ''
        ),
        'SESSION_REPLACEMENT'
      )
    ),
    128
  );
  v_allow_same_pay_date boolean :=
    lower(
      btrim(
        coalesce(
          v_options ->> 'allow_same_pay_date_duplicate',
          v_options ->> 'allowSamePayDateDuplicate',
          'false'
        )
      )
    ) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_source_priority integer := CASE
    WHEN coalesce(
      v_options ->> 'source_priority',
      v_options ->> 'sourcePriority',
      ''
    ) ~ '^-?[0-9]{1,7}$'
      THEN least(
        greatest(
          coalesce(
            v_options ->> 'source_priority',
            v_options ->> 'sourcePriority'
          )::integer,
          -1000000
        ),
        1000000
      )
    ELSE 0
  END;
  v_residuals jsonb;
  v_residual jsonb;
  v_component jsonb;
  v_canonical_key text;
  v_economic_fingerprint text;
  v_authority_fingerprint text;
  v_scope_kind text;
  v_registered_count integer := 0;
  v_incompatible_count integer := 0;
  v_existing_count integer := 0;
  v_registration_id uuid;
BEGIN
  IF p_source_session_id IS NULL
     OR p_target_session_id IS NULL
     OR p_source_session_id = p_target_session_id THEN
    RAISE EXCEPTION 'WORKBENCH_CASE_RESOLUTION_CARRY_SESSION_INVALID'
      USING ERRCODE = '22023',
            DETAIL = jsonb_build_object(
              'code', 'WORKBENCH_CASE_RESOLUTION_CARRY_SESSION_INVALID',
              'source_session_id', p_source_session_id,
              'target_session_id', p_target_session_id
            )::text;
  END IF;

  PERFORM 1
  FROM public.banking_pay_workbench_sessions session_lock
  WHERE session_lock.id IN (p_source_session_id, p_target_session_id)
  ORDER BY session_lock.id
  FOR UPDATE;

  SELECT *
  INTO v_source
  FROM public.banking_pay_workbench_sessions
  WHERE id = p_source_session_id;

  SELECT *
  INTO v_target
  FROM public.banking_pay_workbench_sessions
  WHERE id = p_target_session_id;

  IF v_source.id IS NULL OR v_target.id IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_CASE_RESOLUTION_CARRY_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0002';
  END IF;

  IF v_target.status <> 'OPEN'
     OR v_target.discarded_at_utc IS NOT NULL
     OR v_target.replacement_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'WORKBENCH_CASE_RESOLUTION_CARRY_TARGET_OBSOLETE'
      USING ERRCODE = '55000';
  END IF;

  IF v_source.week_ending_cutoff IS DISTINCT FROM v_target.week_ending_cutoff
     OR v_source.pay_date > v_target.pay_date
     OR (
       v_source.pay_date = v_target.pay_date
       AND v_allow_same_pay_date IS NOT TRUE
     ) THEN
    RAISE EXCEPTION 'WORKBENCH_CASE_RESOLUTION_CARRY_SCOPE_MISMATCH'
      USING ERRCODE = '55000';
  END IF;

  IF NOT (
    (
      v_source.status = 'OPEN'
      AND v_source.discarded_at_utc IS NULL
      AND v_source.replacement_session_id IS NULL
    )
    OR (
      v_source.status = 'DISCARDED'
      AND v_source.discarded_at_utc IS NOT NULL
      AND v_source.replacement_session_id = p_target_session_id
    )
  ) THEN
    RAISE EXCEPTION 'WORKBENCH_CASE_RESOLUTION_CARRY_SOURCE_LIFECYCLE_INVALID'
      USING ERRCODE = '55000';
  END IF;

  v_actor_user_id := COALESCE(
    CASE
      WHEN coalesce(
        v_options ->> 'actor_user_id',
        v_options ->> 'actorUserId',
        ''
      ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN coalesce(
          v_options ->> 'actor_user_id',
          v_options ->> 'actorUserId'
        )::uuid
    END,
    v_target.actor_user_id
  );

  IF v_actor_user_id IS DISTINCT FROM v_target.actor_user_id THEN
    RAISE EXCEPTION 'WORKBENCH_CASE_RESOLUTION_CARRY_ACTOR_MISMATCH'
      USING ERRCODE = '42501';
  END IF;

  FOR v_resolution IN
    SELECT resolution_row.*
    FROM public.banking_pay_workbench_session_case_resolutions resolution_row
    WHERE resolution_row.session_id = p_source_session_id
    ORDER BY resolution_row.candidate_id,
             resolution_row.updated_at_utc,
             resolution_row.id
  LOOP
    v_canonical_key := NULL;
    v_economic_fingerprint := NULL;
    v_authority_fingerprint := NULL;
    v_scope_kind := 'NON_CORRECTION';
    v_residual := NULL;
    v_component := NULL;
    v_registration_id := NULL;

    IF coalesce(v_resolution.source_family_key, '')
         LIKE 'correction-chain:%'
       OR coalesce(
         v_resolution.payload_json ->> 'correction_identity_version',
         ''
       ) = 'CORRECTION_CHAIN_V1'
       OR nullif(
         v_resolution.payload_json ->> 'correction_chain_fingerprint',
         ''
       ) IS NOT NULL THEN
      v_scope_kind := 'CORRECTION_COMPONENT';
      v_residuals :=
        public._ctms_candidate_correction_residuals_v1(
          p_source_session_id,
          v_resolution.candidate_id,
          NULL::uuid,
          'PAY_WORKBENCH_CARRY_REGISTER'
        );

      SELECT residual.value
      INTO v_residual
      FROM jsonb_array_elements(
        coalesce(v_residuals, '[]'::jsonb)
      ) residual(value)
      WHERE residual.value ->> 'source_family_key'
        = v_resolution.source_family_key
      LIMIT 1;

      SELECT component.value
      INTO v_component
      FROM jsonb_array_elements(
        coalesce(v_residual -> 'components', '[]'::jsonb)
      ) component(value)
      WHERE upper(component.value ->> 'component_key_type')
          = upper(v_resolution.component_key_type)
        AND component.value ->> 'component_key_value'
          = v_resolution.component_key_value
      LIMIT 1;

      v_canonical_key :=
        public._ctms_correction_carrier_identity_v1(
          v_resolution.candidate_id,
          nullif(v_residual ->> 'root_timesheet_id', '')::uuid,
          v_component ->> 'component_key_type',
          v_component ->> 'component_key_value'
        );
      v_economic_fingerprint :=
        nullif(v_component ->> 'resolution_economic_fingerprint', '');
      v_authority_fingerprint :=
        public._ctms_correction_resolution_authority_fingerprint_v1(
          v_residual,
          v_component
        );
    ELSE
      v_canonical_key :=
        nullif(btrim(v_resolution.resolution_identity_key), '');
      IF v_canonical_key IS NOT NULL THEN
        v_economic_fingerprint := encode(
          extensions.digest(
            convert_to(
              jsonb_build_object(
                'resolution_identity_key', v_canonical_key,
                'source_basis_fingerprint',
                  v_resolution.source_basis_fingerprint,
                'source_family_key', v_resolution.source_family_key,
                'component_key_type', v_resolution.component_key_type,
                'component_key_value', v_resolution.component_key_value,
                'payload_json', v_resolution.payload_json
              )::text,
              'UTF8'
            ),
            'sha256'
          ),
          'hex'
        );
        v_authority_fingerprint := v_economic_fingerprint;
      END IF;
    END IF;

    IF v_canonical_key IS NULL
       OR v_economic_fingerprint IS NULL
       OR v_authority_fingerprint IS NULL THEN
      v_canonical_key := 'INCOMPATIBLE|' || v_resolution.id::text;
      v_economic_fingerprint := encode(
        extensions.digest(
          convert_to(
            jsonb_build_object(
              'source_resolution', to_jsonb(v_resolution),
              'correction_residual', v_residual,
              'correction_component', v_component,
              'incompatibility_code',
                'STABLE_IDENTITY_OR_ECONOMIC_FINGERPRINT_UNAVAILABLE'
            )::text,
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      );
    END IF;

    INSERT INTO
      public.banking_pay_workbench_case_resolution_carry_registrations (
        target_session_id,
        source_session_id,
        candidate_id,
        source_resolution_id,
        source_resolution_identity_key,
        canonical_resolution_key,
        resolution_scope_kind,
        source_economic_fingerprint,
        source_resolution_snapshot_json,
        source_priority,
        carry_reason,
        status,
        state_reason_code,
        created_at_utc,
        updated_at_utc,
        completed_at_utc
      )
    VALUES (
      p_target_session_id,
      p_source_session_id,
      v_resolution.candidate_id,
      v_resolution.id,
      v_resolution.resolution_identity_key,
      v_canonical_key,
      v_scope_kind,
      v_economic_fingerprint,
      jsonb_strip_nulls(
        jsonb_build_object(
          'resolution', to_jsonb(v_resolution),
          'correction_residual', v_residual,
          'correction_component', v_component,
          'source_resolution_authority_fingerprint',
            v_authority_fingerprint,
          'registered_at_utc', v_now,
          'policy_x_authority_scope',
            'PRE_DRAFT_CASE_RESOLUTION_STATE_ONLY'
        )
      ),
      v_source_priority,
      v_carry_reason,
      CASE
        WHEN v_canonical_key LIKE 'INCOMPATIBLE|%'
          THEN 'INCOMPATIBLE'
        ELSE 'PENDING'
      END,
      CASE
        WHEN v_canonical_key LIKE 'INCOMPATIBLE|%'
          THEN 'STABLE_IDENTITY_UNAVAILABLE'
      END,
      v_now,
      v_now,
      CASE
        WHEN v_canonical_key LIKE 'INCOMPATIBLE|%'
          THEN v_now
      END
    )
    ON CONFLICT (target_session_id, source_resolution_id)
    DO NOTHING
    RETURNING id
    INTO v_registration_id;

    IF v_registration_id IS NULL THEN
      v_existing_count := v_existing_count + 1;
    ELSIF v_canonical_key LIKE 'INCOMPATIBLE|%' THEN
      v_incompatible_count := v_incompatible_count + 1;
    ELSE
      v_registered_count := v_registered_count + 1;
    END IF;

    IF v_registration_id IS NOT NULL THEN
      INSERT INTO public.audit_events (
        actor_user_id,
        object_type,
        object_id_text,
        action,
        before_json,
        after_json,
        reason
      )
      VALUES (
        v_actor_user_id,
        'BANKING_PAY_CASE_RESOLUTION_CARRY',
        v_registration_id::text,
        CASE
          WHEN v_canonical_key LIKE 'INCOMPATIBLE|%'
            THEN 'CARRY_REGISTRATION_INCOMPATIBLE'
          ELSE 'CARRY_REGISTERED'
        END,
        NULL,
        jsonb_build_object(
          'registration_id', v_registration_id,
          'source_session_id', p_source_session_id,
          'target_session_id', p_target_session_id,
          'source_resolution_id', v_resolution.id,
          'candidate_id', v_resolution.candidate_id,
          'canonical_resolution_key', v_canonical_key,
          'source_economic_fingerprint', v_economic_fingerprint,
          'status', CASE
            WHEN v_canonical_key LIKE 'INCOMPATIBLE|%'
              THEN 'INCOMPATIBLE'
            ELSE 'PENDING'
          END
        ),
        v_carry_reason
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'source_session_id', p_source_session_id,
    'target_session_id', p_target_session_id,
    'total_resolution_count',
      v_registered_count + v_incompatible_count + v_existing_count,
    'valid_resolution_count', 0,
    'stale_resolution_count', 0,
    'saved_resolution_count', 0,
    'preview_row_count', 0,
    'pending_registration_count', v_registered_count,
    'incompatible_registration_count', v_incompatible_count,
    'existing_registration_count', v_existing_count,
    'state_changed', v_registered_count > 0 OR v_incompatible_count > 0,
    'carry_state', CASE
      WHEN v_registered_count > 0 THEN 'DEFERRED'
      ELSE 'NOT_REQUIRED'
    END,
    'policy_x_authority_scope',
      'PRE_DRAFT_CASE_RESOLUTION_STATE_ONLY'
  );
END;
$function$;

-- pay_workbench_session_carry_forward_preview_selections_v1(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.pay_workbench_session_carry_forward_preview_selections_v1(p_source_session_id uuid, p_target_session_id uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_options jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_options_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(p_options_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_source record;
  v_target record;
  v_actor_user_id uuid;
  v_allow_same_pay_date boolean :=
    lower(btrim(COALESCE(
      v_options ->> 'allow_same_pay_date_duplicate',
      v_options ->> 'allowSamePayDateDuplicate',
      'false'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_source_priority integer := CASE
    WHEN COALESCE(
      v_options ->> 'source_priority',
      v_options ->> 'sourcePriority',
      ''
    ) ~ '^-?[0-9]{1,7}$'
      THEN COALESCE(
        v_options ->> 'source_priority',
        v_options ->> 'sourcePriority'
      )::integer
    ELSE 0
  END;
  v_carry_reason text := left(upper(COALESCE(
    NULLIF(btrim(COALESCE(
      v_options ->> 'carry_forward_reason',
      v_options ->> 'carryForwardReason',
      ''
    )), ''),
    'SESSION_REPLACEMENT'
  )), 128);
  v_registered integer := 0;
  v_existing integer := 0;
  v_ambiguous integer := 0;
BEGIN
  IF p_source_session_id IS NULL
     OR p_target_session_id IS NULL
     OR p_source_session_id = p_target_session_id THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CARRY_SESSION_INVALID'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.banking_pay_workbench_sessions session_lock
  WHERE session_lock.id IN (p_source_session_id, p_target_session_id)
  ORDER BY session_lock.id
  FOR UPDATE;

  SELECT * INTO v_source
  FROM public.banking_pay_workbench_sessions
  WHERE id = p_source_session_id;

  SELECT * INTO v_target
  FROM public.banking_pay_workbench_sessions
  WHERE id = p_target_session_id;

  IF v_source.id IS NULL OR v_target.id IS NULL THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CARRY_SESSION_NOT_FOUND'
      USING ERRCODE = 'P0002';
  END IF;

  IF v_target.status <> 'OPEN'
     OR v_target.discarded_at_utc IS NOT NULL
     OR v_target.replacement_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CARRY_TARGET_OBSOLETE'
      USING ERRCODE = '55000';
  END IF;

  IF v_source.week_ending_cutoff IS DISTINCT FROM v_target.week_ending_cutoff
     OR v_source.pay_date > v_target.pay_date
     OR (v_source.pay_date = v_target.pay_date AND v_allow_same_pay_date IS NOT TRUE) THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CARRY_SCOPE_MISMATCH'
      USING ERRCODE = '55000';
  END IF;

  IF NOT (
    (v_source.status = 'OPEN' AND v_source.discarded_at_utc IS NULL)
    OR
    (v_source.status = 'DISCARDED'
      AND v_source.discarded_at_utc IS NOT NULL
      AND v_source.replacement_session_id = p_target_session_id)
  ) THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CARRY_SOURCE_LIFECYCLE_INVALID'
      USING ERRCODE = '55000';
  END IF;

  v_actor_user_id := CASE
    WHEN COALESCE(
      v_options ->> 'actor_user_id',
      v_options ->> 'actorUserId',
      ''
    ) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN COALESCE(
        v_options ->> 'actor_user_id',
        v_options ->> 'actorUserId'
      )::uuid
    ELSE v_target.actor_user_id
  END;

  IF NOT EXISTS (
    SELECT 1
    FROM public.tms_users actor_row
    WHERE actor_row.id = v_actor_user_id
      AND actor_row.is_active = true
  ) THEN
    RAISE EXCEPTION 'WORKBENCH_SELECTION_CARRY_ACTOR_INVALID'
      USING ERRCODE = '42501';
  END IF;

  WITH source_rows AS (
    SELECT
      source_preview.id AS source_preview_row_id,
      source_preview.candidate_id,
      source_preview.selected,
      upper(btrim(source_preview.selection_state)) AS selection_state,
      upper(btrim(COALESCE(source_preview.row_json->>'selection_user_override', ''))) AS selection_user_override,
      source_preview.row_key,
      source_preview.section,
      source_preview.timesheet_id,
      source_preview.key_type,
      source_preview.key_value,
      source_preview.row_json,
      public._pay_workbench_preview_selection_key_v1(
        source_preview.candidate_id,
        source_preview.section,
        source_preview.timesheet_id,
        source_preview.key_type,
        source_preview.key_value,
        source_preview.row_key,
        source_preview.row_json
      ) AS stable_selection_key
    FROM public.banking_pay_workbench_preview_rows source_preview
    WHERE source_preview.session_id = p_source_session_id
      AND source_preview.session_version = v_source.version
      AND source_preview.status = 'READY'
      AND upper(btrim(COALESCE(source_preview.selection_state, '')))
        IN ('SELECTED', 'UNSELECTED')
      AND upper(btrim(COALESCE(source_preview.row_json->>'selection_user_override', '')))
        = upper(btrim(COALESCE(source_preview.selection_state, '')))
  ),
  grouped_keys AS (
    SELECT
      stable_selection_key,
      candidate_id,
      count(*) AS row_count,
      count(DISTINCT selection_state) AS state_count
    FROM source_rows
    WHERE stable_selection_key IS NOT NULL
    GROUP BY stable_selection_key, candidate_id
  ),
  inserted AS (
    INSERT INTO public.banking_pay_workbench_selection_carry_registrations (
      target_session_id,
      source_session_id,
      candidate_id,
      source_preview_row_id,
      stable_selection_key,
      selected,
      selection_state,
      source_priority,
      carry_reason,
      status,
      state_reason_code,
      source_row_snapshot_json,
      created_at_utc,
      updated_at_utc,
      completed_at_utc
    )
    SELECT
      p_target_session_id,
      p_source_session_id,
      source_row.candidate_id,
      source_row.source_preview_row_id,
      source_row.stable_selection_key,
      source_row.selection_state = 'SELECTED',
      source_row.selection_state,
      v_source_priority,
      v_carry_reason,
      CASE WHEN grouped_key.state_count > 1 THEN 'AMBIGUOUS' ELSE 'PENDING' END,
      CASE WHEN grouped_key.state_count > 1 THEN 'SOURCE_SELECTION_STATES_CONFLICT' END,
      jsonb_strip_nulls(jsonb_build_object(
        'source_preview_row_id', source_row.source_preview_row_id,
        'source_session_id', p_source_session_id,
        'candidate_id', source_row.candidate_id,
        'stable_selection_key', source_row.stable_selection_key,
        'selected', source_row.selected,
        'selection_state', source_row.selection_state,
        'selection_user_override', source_row.selection_user_override,
        'row_key', source_row.row_key,
        'section', source_row.section,
        'timesheet_id', source_row.timesheet_id,
        'key_type', source_row.key_type,
        'key_value', source_row.key_value,
        'policy_x_authority_scope', 'PRE_DRAFT_SELECTION_INTENT_ONLY'
      )),
      clock_timestamp(),
      clock_timestamp(),
      CASE WHEN grouped_key.state_count > 1 THEN clock_timestamp() END
    FROM source_rows source_row
    JOIN grouped_keys grouped_key
      ON grouped_key.stable_selection_key = source_row.stable_selection_key
     AND grouped_key.candidate_id = source_row.candidate_id
    ON CONFLICT (target_session_id, source_preview_row_id)
    DO NOTHING
    RETURNING status
  )
  SELECT
    count(*) FILTER (WHERE status = 'PENDING')::integer,
    count(*) FILTER (WHERE status = 'AMBIGUOUS')::integer
  INTO v_registered, v_ambiguous
  FROM inserted;

  SELECT count(*)::integer
  INTO v_existing
  FROM public.banking_pay_workbench_selection_carry_registrations
  WHERE target_session_id = p_target_session_id
    AND source_session_id = p_source_session_id;

  RETURN jsonb_build_object(
    'ok', true,
    'source_session_id', p_source_session_id,
    'target_session_id', p_target_session_id,
    'registered_count', COALESCE(v_registered, 0),
    'ambiguous_count', COALESCE(v_ambiguous, 0),
    'total_registered_or_existing_count', COALESCE(v_existing, 0),
    'policy_x_authority_scope', 'PRE_DRAFT_SELECTION_INTENT_ONLY'
  );
END;
$function$;

